window.__RF_DATA=window.__RF_DATA||{};window.__RF_DATA["khalwaYear"]="{\"v\":2,\"weeks\":[[\"نبدأ السنة بالشكر ونصل إلى المذود\",\"شكرٌ وصلاةٌ وإصغاءٌ وتوبةٌ ومحبةٌ، تقودنا كلها إلى ميلاد المسيح.\"],[\"فضائل التلميذ في أول الطريق\",\"الصبر والاتضاع والرجاء والفرح: ملامح حياةٍ قريبة من الله.\"],[\"من الخلوة إلى الأردن\",\"غفرانٌ وطاعةٌ واستعدادٌ، ثم نقف مع المسيح في معموديته.\"],[\"إيمانٌ يعمل\",\"لسانٌ محفوظ، وصلاةٌ بلا ملل، ورحمةٌ وخدمةٌ وثباتٌ في التجارب.\"],[\"طمأنينة تحت عناية الله\",\"راحةٌ في الرب، ووداعةٌ، وبيتٌ مبنيٌّ عليه، وشجاعةٌ تنمو.\"],[\"قلبٌ نقيٌّ يخدم ويسبّح\",\"رجاءٌ في الضعف، وإصغاءٌ للآخرين، وذبيحةُ تسبيحٍ وجهادٌ روحي.\"],[\"عطش القلب ولقاء الهيكل\",\"عطشٌ إلى الله، وحريةٌ ومحبةٌ عملية، ولقاءٌ مع السيد في الهيكل.\"],[\"جماعةٌ مصالَحة تخاف الرب\",\"جسدٌ واحد، وميراثٌ سماوي، ومصالحةٌ وسهرٌ وعطاءٌ بفرح.\"],[\"نهضةٌ وتوبة\",\"نقوم بعد السقوط، ونقتني القناعة، ونفتدي الوقت، ونقترب بقلبٍ منسحق.\"],[\"كلمةٌ تغذّي وصليبٌ ينتصر\",\"الكلمة غذاءٌ، والشهادة والإيمان والمحبة تتوّجها قوةُ الصليب.\"],[\"الراعي الذي يعطي الحياة\",\"رجاءٌ في الألم، ولصُّ اليمين، وصوتُ الراعي، وخبزُ الحياة، والقيامة.\"],[\"نورٌ وبيتٌ ودعوة\",\"نورُ المسيح في الخفاء وفي البيت، وصلاةٌ ربانيةٌ ودعوةٌ مختارة.\"],[\"سلامٌ يبدأ بالتوبة\",\"سلامٌ داخلي، ونقاءٌ، وسرُّ الاعتراف، ووحدةُ الكنيسة، وصدقٌ في الكلمة.\"],[\"من الخوف إلى الثقة\",\"نُلحّ في الصلاة، ونلقي همَّنا، ونتحرر من الخوف، ونطيع كما أطاعت العذراء.\"],[\"فرح القيامة ومعزّي الطريق\",\"رحمةٌ جديدة، وحياةٌ أبدية، ومسيحٌ رفيقُ الطريق، وروحٌ يعزّي ويهب.\"],[\"تربيةُ القلب بالكلمة\",\"محبةٌ تُربّي، وقبولُ الآخر، وخضوعٌ لله، وكتابٌ مقدسٌ يفحص الخفايا.\"],[\"مرسَلون بثمر الحياة\",\"شهادةٌ أمينة، وجوابُ «هأنذا»، وعدلٌ ورحمة، وإنسانٌ جديدٌ يعبد في الجماعة.\"],[\"العمل والخدمة بروح الفقر\",\"أمانةُ الله، وكرامةُ العمل، وفرحُ الخدمة، والكنزُ الحقيقي، وفقرُ الروح.\"],[\"التطويبات في الحياة اليومية\",\"تعزيةٌ وسلامٌ وملحٌ وكمالُ محبة، وصدقُ كلمةٍ بلا قلق.\"],[\"الطريق الضيق وعبادة الروح\",\"لا نَدين، ندخل الباب الضيق، ونعبد بالروح والحق، ونحب الله والإخوة.\"],[\"كرازةٌ تبدأ بالشكر والشفاعة\",\"حكمةٌ وشكرٌ وقوةُ الاسم، وكرازةٌ وبحثٌ عن الضال وشفاعة.\"],[\"الحصاد وحلول الروح\",\"خميرةٌ وحصادٌ وأيدٍ مرفوعة، ثم حلولُ الروح القدس واستنارتُه.\"],[\"المحبة الأولى وغنى المسيح\",\"زيارةُ المتألمين، ومحبةٌ أولى، وكلمةٌ تثمر، ومعرفةُ الله وأمانُه.\"],[\"فرحٌ لا تهزّه الظروف\",\"ثمرٌ مطلوب، وفرحُ الرب قوتنا، وهدوءُ القلب، وتسبيحٌ وسط الخسارة.\"],[\"ثباتٌ ورحمة\",\"خيرُ الله وثباتُنا فيه، وتواضعٌ ونعمة، ومحبةٌ بلا رياء وغفران.\"],[\"كلمةٌ ورجاءٌ ونداء\",\"أمانةٌ في القليل، وكلمةٌ في وقتها، ومرساةُ الرجاء، ونداء «اتبعني».\"],[\"اتبعني… وأرسلكم\",\"اتباعٌ أمين، وحملُ الصليب، وخدمةٌ كمثال، وحصادٌ كثير وإرسالية.\"],[\"شهودٌ وجماعةٌ مصلية\",\"شجاعةُ الشهادة، واعترافُ الإيمان، وبطرس وبولس، وكنيسةٌ تصلي.\"],[\"السلوك في النور\",\"محبةٌ كاملة، ووحدةٌ وحرية، وصوتٌ منخفضٌ خفيف، ونعمةٌ فوق نعمة.\"],[\"ثقةُ المؤمن\",\"نورُ العالم، وإيمانٌ عظيم، ورجاءٌ وثقة، وملجأٌ وشبعُ النفس.\"],[\"العودة إلى الرب\",\"ظلٌّ ونور، وشكرُ الغروب، وقلبٌ جديد، وصومٌ وصلاةٌ في الخفاء.\"],[\"العذراء وسرّ التجسد\",\"عطاءٌ مبارك، واتضاعُ العذراء، ونبواتُ التجسد ورموزه.\"],[\"رموزُ العذراء وجبلُ التجلي\",\"الباب المغلق وعصا هارون ونشيدُ العروس، ثم جبلُ الرب والتجلي.\"],[\"رجاءُ ما بعد الجبل\",\"نزولٌ من الجبل، ونياحةُ العذراء، ومنازلُ الآب، وسحابةُ الشهود.\"],[\"سكونٌ وشكر\",\"انتظارُ النفس، وكفطيمٍ نحو أمه، وعهدُ سلامٍ، وشكرُ ختام السنة.\"],[\"كلمةٌ تروي القلب\",\"أبوابُ الحمد، وجودُ الرب، وكلمةٌ تثبت، ومياهٌ للعطشان.\"],[\"رأس السنة والشهداء\",\"استعدادٌ للعام الجديد، وعيدُ النيروز، وصبرٌ واتكالٌ وسهر.\"],[\"ثمرُ الروح ومحبةُ المصلوب\",\"غلبةُ المسيح، ووداعةٌ وتأنٍّ، ومحبةُ المصلوب وحملُ الله.\"],[\"الصليبُ في الكتب\",\"جراحُه شفاؤنا، ونبواتُ الصليب، والحيةُ النحاسية، وعيدُ الصليب.\"],[\"الكنيسةُ جسدٌ واحد\",\"أعضاءٌ بعضُنا لبعض، بيتُ الله، وقطيعٌ واحدٌ ووحدةُ الروح.\"],[\"أسرارُ الكنيسة وطريقُ الاتضاع\",\"خبزُ الحياة، والمعمودية والمسحة، ومخافةُ الرب وانتظارُ رحمته.\"],[\"رحمةٌ وحكمةٌ وبيت\",\"رحمةٌ بالفقير، وصديقٌ أمين، وغفرانٌ وحكمةٌ، وأسرةٌ في قصد الله.\"],[\"البيتُ المبارك\",\"اثنان خيرٌ من واحد، ومحبةٌ واحترام، وبنونٌ ميراثٌ من الرب.\"],[\"من البيت إلى الرجوع\",\"وفاءٌ وأمانةُ الأجيال، ثم صرخةٌ من الهاوية ورجوعٌ إلى الرب.\"],[\"تذكرةُ الأنبياء الأخيرة\",\"اذكر الرحمة، واجعلوا قلبكم على طرقكم، وشمسُ البرّ تشرق.\"],[\"الحكمةُ واختيارُ الحياة\",\"تأديبٌ وزمانٌ لكل شيء، وختامُ الأمر، واختَر الحياة.\"],[\"الملائكةُ وبدءُ الصوم\",\"تواضعٌ وصلاة، وعيدُ ميخائيل، وفرحُ الملائكة، وبدءُ صوم الميلاد.\"],[\"مِلءُ الزمان\",\"موعدٌ منذ القديم، ورحمةٌ وحقٌّ التقيا، وزكريا والسابق.\"],[\"البشارةُ والاستعداد\",\"صمتٌ وإيمان، وبشارةٌ للعذراء، وزيارةٌ وفرح، ويوسفُ البارُّ وعمانوئيل.\"],[\"الطريقُ إلى المذود\",\"نورٌ حقيقي، وطريقٌ إلى بيت لحم، ورعاةٌ ومجوس، وحفظُ الله.\"],[\"سهرُ كيهك وانتظارُ المشرق\",\"لماذا تجسّد؟ ظهورُ النعمة، وسهرٌ وصلاة، والمشرقُ من العلاء.\"],[\"شكرٌ وختامٌ وبداية\",\"رجاءٌ مبارك، «إلى هنا أعاننا الرب»، وعطيةٌ لا يُعبَّر عنها، وكلُّ شيءٍ جديد.\"]],\"days\":{\"1-1\":{\"th\":\"سنةٌ جديدة بين يدي الله\",\"m\":[{\"t\":\"بركةٌ ووجهٌ مضيء\",\"ref\":\"المزمور السادس والستون — باكر\",\"v\":\"ليتراءف الله علينا ويباركنا، وليظهر وجهه علينا ويرحمنا. لتعرف في الأرض طريقك، وفي جميع الأمم خلاصك.\",\"r\":\"نبدأ السنة بطلب البركة قبل أي خطة: أن يُظهر الله وجهه علينا. من يبدأ يومه ووجهه نحو الله لا يخاف مما لم يعرفه بعد، ومن تعلّم أن يرى طريق الله يهتدي في كل طريق. اجعل أولى خطواتك في هذه السنة صلاةً قصيرة تطلب فيها وجه الله لا نتائجه.\",\"p\":\"يا رب، تراءف علينا وباركنا، وأظهر وجهك علينا في هذه السنة. عرّفني طريقك في كل يوم، وليكن خلاصك حاضرًا في بيتي وعملي وقلبي. آمين.\",\"x\":\"بركة الله في الكتاب هي حضوره: إشراق وجهه يعني نظره الأبوي إلينا. لذلك تفتتح الكنيسة صلواتها بطلب الرحمة قبل أي طلب آخر. تدريب: اكتب في أول السنة ثلاثة أشياء تريد أن يباركها الله، وسلّمها له.\"},{\"t\":\"سنةٌ تُكلَّل بالصلاح\",\"ref\":\"المزامير ٦٥: ١١\",\"bk\":\"المزامير\",\"v\":\"كللت السنة بجودك، وآثارك تقطر دسما.\",\"r\":\"في أول يوم من السنة تميل النفس إلى الحساب: ماذا أنجزت، وماذا أريد، وماذا أخاف؟ لكن المزمور يبدأ من اتجاه آخر؛ فالسنة نفسها تاجٌ يضعه الله على رأسك. قبل أن تضع خططك، ارفع عينيك واشكر على ما سبق، فالقلب الشاكر يدخل المستقبل بطمأنينة لا بقلق.\",\"p\":\"يا رب، أنت إله الأزمنة وصاحب السنين. أشكرك على كل ما أعطيتني فيما مضى، المعلَن منه والخفي. كلّل هذه السنة الجديدة بصلاحك، واجعلني أرى يدك في كل يوم من أيامها. آمين.\",\"x\":\"الشكر ليس مجاملة لله، بل هو نظرة صحيحة إلى الحياة: أن ما عندي ليس من صنع يدي وحدي. حين أتذكر أن الصحة والأحباء والعمل والنجاة من أخطار لا أعلمها كلها كانت عطايا، يصير الغد أخفّ، لأن الذي كلّل الأمس يستطيع أن يكلّل الغد.\\nاليوم، خذ ورقة واكتب ثلاث نِعَم من السنة الماضية لم تشكر عليها بما يكفي، ثم قدّمها لله بصوت مسموع قبل أن تبدأ يومك.\"},{\"t\":\"كأنني لم أبدأ بعد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يختم الأب بمفو عمره الطويل بكلمات من لم يبدأ بعد، وليست هذه قلة تقدير لما مضى بل تواضع من يعرف أن الطريق إلى الله لا ينتهي. افتتح سنتك بروح البداية: لا تفتخر بما أنجزت ولا تيأس مما فات، بل ابدأ اليوم كأنه أول يوم تعرف فيه الله.\",\"p\":\"أيها الرب يسوع، علّمني أن أبدأ كل يوم بقلب المبتدئ، متواضعًا أمامك، شاكرًا على الماضي، ومشتاقًا أن أتعلم منك من جديد. آمين.\",\"x\":\"من يبدأ كل يوم كأنه لم يبدأ بعد، لا يتكل على ما أنجز ولا ييأس مما فاته. هذا هو التواضع الذي يحفظ النمو. تدريب: اختر عادة صالحة قديمة وابدأها اليوم من جديد كأنها المرة الأولى.\",\"fq\":461}]},\"1-2\":{\"th\":\"الشكر أولًا\",\"m\":[{\"t\":\"أبارك الرب في كل حين\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"أبارك الرب في كل وقت؛ وفي كل حين تسبحته في فمي، بالرب تفتخر نفسي، يسمع الودعاء فيفرحون. عظموا الرب معي، لنرفع اسمه جميعا.\",\"r\":\"المرنم لا يخصّص للشكر مناسبة، فهو في كل وقت وكل حين. الشكر عادةٌ تُبنى كما تُبنى الصلاة، تبدأ بإرادة وتنتهي بطبع. وكلما سبّحتَ في لحظة بسيطة من يومك، صار قلبك أقدر على أن يلمس يد الله في الأمور العادية.\",\"p\":\"يا رب، أبارك اسمك في كل وقت، وليكن تسبيحك دائمًا في فمي. علّمني أن أعظّمك مع إخوتي، وأن أجد في كل يوم سببًا جديدًا للشكر. آمين.\",\"x\":\"يربط المرنم الشكر بكل حين، لأن الله لا يتوقف عن العطاء. وفي الأجبية يتكرر الشكر في ختام كل ساعة. تدريب: قبل النوم اذكر خمس عطايا من يومك، حتى الصغيرة منها، وقل لله شكرًا على كل واحدة.\"},{\"t\":\"رسالة شكر من القلب\",\"ref\":\"لوقا ١٧: ١٥–١٦\",\"bk\":\"لوقا\",\"v\":\"فواحد منهم لما رأى أنه شفي، رجع يمجد الله بصوت عظيم، وخر على وجهه عند رجليه شاكرا له، وكان سامريا.\",\"r\":\"عشرة برصٍ شُفوا، وواحد فقط عاد. الفرق لم يكن في الشفاء، بل في العودة. التسعة أخذوا الهدية، والواحد وجد الواهب. اليوم لا تكتفِ بأن تستمتع بعطايا الله، بل ارجع وقل له: يا رب، أنت أغلى من العطية.\",\"p\":\"يا رب يسوع، كثيرًا ما أخذت عطاياك ومضيت. اليوم أرجع إليك وأخرّ عند قدميك شاكرًا. اشفِ قلبي من الجحود، وعلّمني أن أرى فيك الواهب قبل الهبة. آمين.\",\"x\":\"العودة إلى المسيح كانت «بصوت عظيم» و«خرّ على وجهه»؛ أي أن الشكر الحقيقي يشمل الصوت والجسد معًا، لا مجرد فكرة طيبة في الذهن. والعجيب أن العائد كان سامريًا، أي إنسانًا اعتاد أن يُحسب بعيدًا، فصار قريبًا بالشكر.\\nخطوة عملية: فكّر في شخص قدّم لك معروفًا ولم تشكره بعد، وأرسل له اليوم رسالة صادقة. ثم قدّم الشكر لله من أجل هذا الشخص.\"},{\"t\":\"يذوق ويشكر\",\"ref\":\"\",\"v\":\"\",\"r\":\"القديس أرسانيوس يذوق قليلًا من كل نوع من الثمار ويشكر الله، فالشكر عنده يمرّ من الفم إلى القلب. لا ينتظر كثرة العطايا ليشكر، بل يشكر على قليلها. تعلّم منه أن تقف اليوم عند نعمةٍ بسيطة وتقول: شكرًا يا رب.\",\"p\":\"يا إله كل عطية صالحة، علّمني أن أقبل القليل بشكر كبير، وأن أتذوق خيراتك بقلب ممتن لا يعتاد على نعمك. لك المجد دائمًا. آمين.\",\"x\":\"يذوق الأب قليلًا من كل ما يوضع أمامه ويشكر الله، فالشكر عنده أوسع من الشبع. ومن يشكر على القليل يعرف أن كل شيء عطية. تدريب: اليوم أمام كل طعام أو نعمة قل بصوت منخفض: شكرًا يا رب.\",\"fq\":36}]},\"1-3\":{\"th\":\"أن نبدأ بالصلاة\",\"m\":[{\"t\":\"عطشت إليك نفسي\",\"ref\":\"المزمور ٦٣ — باكر\",\"v\":\"يا الله إلهي إليك أبكر، عطشت إليك نفسي. يشتاق إليك جسدي، في أرض مقفرة وموضع غير مسلوك ومكان بلا ماء.\",\"r\":\"يبكّر المرنم إلى الله لأن عطشه أكبر من انشغاله. ليست البداية بالصلاة واجبًا ثقيلًا بل جوابًا لعطش داخلي، فكل نفس تعرف أنها لا تشبع بغير الله. ابدأ يومك اليوم بدقائق تسمّي فيها عطشك أمام الله دون ألفاظ كثيرة.\",\"p\":\"يا الله إلهي، إليك أبكّر، وإليك عطشت نفسي. اروِ قلبي بحضورك في أرض الانشغال القاحلة، واجعل صلاتي أول خطواتي كل صباح. آمين.\",\"x\":\"الباكر هو وقت أن يبكر الإنسان إلى الله قبل مشاغله، وهكذا نصلي المزمور الثاني والستين مع شروق النهار. العطش إلى الله ليس شعورًا يأتي بل رغبة نغذيها. تدريب: ابدأ يومك بدقيقتين من الصلاة قبل أن تفتح هاتفك.\"},{\"t\":\"اطلبوا تجدوا\",\"ref\":\"متى ٧: ٧–٨\",\"bk\":\"متى\",\"v\":\"«اسألوا تعطوا. اطلبوا تجدوا. اقرعوا يفتح لكم. لأن كل من يسأل يأخذ، ومن يطلب يجد، ومن يقرع يفتح له.\",\"r\":\"قد نصلّي ونشعر أن السماء صامتة. لكن المسيح يشجعنا ثلاث مرات في عدد واحد: اسأل، اطلب، اقرع. الإلحاح لا يغيّر قلب الله، لكنه يغيّر قلبي أنا ويُظهر ما أطلبه حقًا. الله لا يتأخر ليعاقب، بل ليعلّم الثقة.\",\"p\":\"يا أبانا الذي في السموات، أسألك فأعطني، أطلبك فاجعلني أجدك، أقرع بابك فافتح لي. علّمني أن أثق بحكمتك حين لا أفهم تأخيرك، وأن أطلبك أنت أكثر من عطاياك. آمين.\",\"x\":\"وفي إنجيل لوقا يضيف المسيح أن الآب يعطي «الروح القدس» للذين يسألونه؛ أي أن أعظم ما يعطيه الله ليس الأشياء بل ذاته. وربما لهذا يتأخر أحيانًا في إجابة ما نطلب لأنه يريد أن يعطينا ما هو أفضل مما نطلب.\\nاكتب طلبًا واحدًا تحمله منذ مدة، وصلِّ به كل يوم هذا الأسبوع، وسجّل كيف يتغير قلبك أنت وأنت تحمله.\"},{\"t\":\"ابدأ في هذه الساعة\",\"ref\":\"\",\"v\":\"\",\"r\":\"سُئل الأب سلوان: هل يمكن أن يبتدئ المرء من جديد؟ فأجاب أن النشيط يبتدئ كل ساعة. لا ينتظر الإنسان رأس السنة أو بداية الأسبوع ليعود إلى الصلاة، فالله يقبله في هذه اللحظة. وإن فاتك صباحك، فابدأ بصلاة قصيرة الآن.\",\"p\":\"يا رب، اجعلني نشيطًا في البدء كل ساعة، ولا تدعني أؤجل لقاءك. أعطني نعمة العودة إليك مرارًا بقلب جديد. آمين.\",\"x\":\"السؤال الذي سأله الأخ هو سؤال كل واحد منا بعد سقطة. والجواب أن الساعة الحاضرة هي نقطة الانطلاق، لا الماضي ولا الغد. تدريب: ما الخطوة الأولى التي أجلتها كثيرًا؟ افعلها خلال هذه الساعة.\",\"fq\":515}]},\"1-4\":{\"th\":\"الإصغاء لكلمة الله\",\"m\":[{\"t\":\"ناموس الرب يردّ النفوس\",\"ref\":\"المزمور الثامن عشر — باكر\",\"v\":\"ناموس الرب بلا عيب يرد النفوس. شهادة الرب صادقة. تعلم الأطفال.\",\"r\":\"كلمة الله لا تعلّمنا فقط، بل تردّ النفس إذا ضلّت وتفرح القلب إذا حزن. قد نسمعها كثيرًا دون أن نُصغي إليها، فالإصغاء أن نترك لها أن تعمل فينا. اقرأ اليوم فقرة قصيرة ببطء، ثم اسأل: ماذا تريد هذه الكلمة أن تفعل فيّ؟\",\"p\":\"يا رب، ناموسك بلا عيب يردّ النفوس، فردّ نفسي إليك. افتح أذني لأصغي وقلبي لأقبل، وعلّمني بكلمتك كما يتعلم الطفل من أبيه. آمين.\",\"x\":\"الكتاب يسمّى ناموس الرب، لأنه ليس معلومات بل قوة تردّ النفس إلى مكانها. وتضعه الكنيسة في الباكر لتبدأ النفس يومها بنوره. تدريب: اقرأ اليوم أصحاحًا قصيرًا ببطء، وتوقف عند آية واحدة تكررها في سرك طوال النهار.\"},{\"t\":\"الأرض الجيدة\",\"ref\":\"لوقا ٨: ١٥\",\"bk\":\"لوقا\",\"v\":\"والذي في الأرض الجيدة، هو الذين يسمعون الكلمة فيحفظونها في قلب جيد صالح، ويثمرون بالصبر.\",\"r\":\"لا نستطيع أن نتحكم في مقدار ما يزرعه الله في قلوبنا، لكننا نتحكم في نوع الأرض. هل قلبي طريق مداس، أم صخرة بلا عمق، أم أرض فيها شوك؟ والأرض الجيدة ليست بلا مشاكل، بل هي التي تسمع وتحفظ وتصبر حتى يأتي الثمر.\",\"p\":\"يا رب، أنت الزارع وأنا الأرض. اقلع شوك الاهتمامات من قلبي، وليّن قسوتي، واجعلني أسمع كلمتك وأحفظها وأثمر بالصبر. آمين.\",\"x\":\"المسيح يذكر ثلاثة أفعال: يسمعون الكلمة، ويحفظونها «في قلب جيد صالح»، ويثمرون «بالصبر». كلها تحتاج وقتًا. وقد نعيش في ثقافة تريد النتائج السريعة، لكن النمو الروحي يشبه الزرع: يعمل في الخفاء قبل أن يظهر.\\nاسأل نفسك: أي نوع من الأرض أنا الآن؟ وما الشوك الذي يخنق الكلمة في حياتي اليومية؟ اختر شوكة واحدة لتقتلعها هذا الأسبوع.\"},{\"t\":\"ضمانة للهرب من الخطيئة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يرى القديس إبيفانيوس في قراءة الكتب المقدسة ضمانة كبيرة للهرب من الخطيئة، لأن الكلمة تملأ الذهن بما هو أنقى من أفكاره. ما نحتفظ به في داخلنا يظهر في اختياراتنا. اجعل لك وقتًا ثابتًا في اليوم للكلمة، ولو صفحة واحدة.\",\"p\":\"يا رب، احفظني بكلمتك من كل سقوط. ثبّت فيّ الشوق إلى قراءتها وتأملها، وليكن الكتاب نورًا لخطواتي وحصنًا لقلبي. آمين.\",\"x\":\"ضمانة الهرب من الخطية في نظر الأب هي ألفة الكتاب، لأن النفس التي تعرف كلمة الله تميز الفخ مبكرًا. تدريب: خصص اليوم وقتًا ثابتًا للقراءة، وأغلق كل ما يشتتك أثناءه.\",\"fq\":100}]},\"1-5\":{\"th\":\"التوبة بابٌ مفتوح\",\"m\":[{\"t\":\"اذكرني كرحمتك\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"خطايا شبابي وجهالاتي لا تذكر. كرحمتك اذكرني أنت من أجل صلاحك يا رب.\",\"r\":\"يطلب المرنم أن يُنسى ما كان من الخطأ، وأن يُذكر بحسب الرحمة. هذا الباب لا يُغلق، لا لأنني أستحق بل لأن رحمة الله أقدم من خطيتي. لا تنتظر أن تصير أفضل لتعود، بل عُد فتصير أفضل في حضنه.\",\"p\":\"اذكرني يا رب كرحمتك لا كخطاياي. لا تذكر جهالات شبابي وسقطاتي، وردّني إليك بقلب منكسر يرجو صلاحك. آمين.\",\"x\":\"يطلب المرنم أن يُذكر بحسب الرحمة لا بحسب الاستحقاق، وهذه أسس التوبة في المزمور الخمسين الذي نصليه كل يوم. تدريب: اعترف لله بخطية واحدة بالاسم الآن، دون أعذار، وثق أن رحمته أكبر منها.\"},{\"t\":\"الابن الضال والآب المنتظر\",\"ref\":\"لوقا ١٥: ٢٠\",\"bk\":\"لوقا\",\"v\":\"فقام وجاء إلى أبيه. وإذ كان لم يزل بعيدا رآه أبوه، فتحنن وركض ووقع على عنقه وقبله.\",\"r\":\"توقف عند هذا المشهد: «وإذ كان لم يزل بعيدًا رآه أبوه فتحنن وركض». الأب لم يكن ينتظر في البيت، بل كان يراقب الطريق. وقبل أن يسمع كلمات الاعتذار كان قد احتضنه. هذه هي صورة الله لمن يفكر في العودة إليه.\",\"p\":\"يا أبي السماوي، أخطأت إليك وإلى السماء. ها أنا راجع إليك، فاستقبلني كما استقبلت الابن الراجع. ألبسني ثوب البنوة، وأقمني من جديد في بيتك. آمين.\",\"x\":\"كثيرون يؤجلون التوبة لأنهم يظنون أنهم يجب أن يصلحوا أنفسهم أولًا. لكن الابن لم يتمم اعتذاره المُعدّ؛ احتضنه الآب أولًا ثم ألبسه الحلة الأولى. فالتوبة ليست استحقاقًا نكسبه، بل قبول لمحبة تسبقنا.\\nما الشيء الذي تؤجل الاعتراف به؟ اليوم قم وانطلق نحو بيت الآب، وحدّد موعدًا مع أب اعترافك إن لم يكن لك موعد قريب.\"},{\"t\":\"أن أضع خطيتي أمام الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يسمّي القديس أنطونيوس العمل العظيم أن يحمل الإنسان خطيته ويضعها أمام الله. لا إنكار ولا تبرير ولا هروب، بل وقوف صادق. من يقف هكذا لا يبقى طويلًا تحت ثقل الذنب، فسمِّ خطيتك اليوم أمام الله باسمها.\",\"p\":\"يا رب، أضع أمامك خطيتي بلا تبرير ولا خوف. اقبل اعترافي، وارفع عني ثقلها، وعلّمني أن أنتظر رحمتك طوال أيام حياتي. آمين.\",\"x\":\"وضع الخطية أمام الله معناه أن لا نخبئها ولا نبررها ولا ننكرها، بل نسميها. من يسميها يخرج من سلطانها. تدريب: اكتب خطية واحدة على ورقة صغيرة، وصلِّ عليها، ثم مزّق الورقة.\",\"fq\":2}]},\"1-6\":{\"th\":\"المحبة أعظم\",\"m\":[{\"t\":\"ما أحسن وما أحلى\",\"ref\":\"المزمور ١٣٢ — النوم\",\"v\":\"هوذا ما أحسن وما أحلى أن يسكن الإخوة معا. كالطيب الكائن على الرأس الذي ينزل على اللحية، لحية هارون النازلة على جيب قميصه.\",\"r\":\"المحبة التي تبقى هي التي تُرى في بيتٍ واحد ومائدةٍ واحدة. يشبّه المرنم وحدة الإخوة بالطيب الذي ينزل على الرأس، فيشمّ الجميع رائحته. حيث يُسكب الحب لا يبقى لأحد وحده. فمن أقرب الناس إليك ويحتاج اليوم إلى كلمة طيبة؟\",\"p\":\"يا رب، ما أحسن أن نسكن معًا بمحبة. انزع من بيتي وكنيستي كل جفاء، واسكب فينا طيب وحدتك وبركتك. آمين.\",\"x\":\"الإخوة المجتمعون في بيت واحد على مائدة واحدة هم صورة الكنيسة، والمحبة تختبر بالقرب لا بالبعد. تدريب: اختر شخصًا من بيتك أو كنيستك أصعب على قلبك، وقدم له اليوم خدمة صغيرة دون أن يطلبها.\"},{\"t\":\"أحبّ بالفعل\",\"ref\":\"يوحنا الأولى ٣: ١٨\",\"bk\":\"يوحنا الأولى\",\"v\":\"يا أولادي، لا نحب بالكلام ولا باللسان، بل بالعمل والحق!\",\"r\":\"من السهل أن أقول «أحبك» لكل أحد، ولكن المحبة تُختبر حين أحتاج إلى أن أترك راحتي لأجل غيري. يطلب منا الرسول أن تكون محبتنا «بالعمل والحق». فلنفتش اليوم عن حاجة بين أيدينا نستطيع أن نسدّها دون أن نُعلن عنها.\",\"p\":\"يا رب، لا تجعل محبتي كلامًا فقط. علّمني أن أرى حاجة من حولي وأتحرك، وأن أبذل بفرح دون أن أنتظر شكرًا. اجعلني أداة لمحبتك. آمين.\",\"x\":\"المحبة بالعمل لا تعني بالضرورة أعمالًا كبيرة. قد تكون وقتًا نمنحه للاستماع، أو مساعدة صغيرة في عمل، أو رسالة تشجيع في لحظة ضعف. وكثيرًا ما تكون أصدق المحبة هي التي لا يعلم بها أحد غير الله.\\nاليوم اصنع عملين صغيرين من المحبة المخفية، ولا تذكرهما لأحد.\"},{\"t\":\"ربح الأخ ربحٌ لله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّمنا القديس أنطونيوس أن الحياة والموت متعلقان بالقريب: إن ربحنا أخانا ربحنا الله، وإن أعثرناه أخطأنا إلى المسيح. هذا يعطي لكل علاقة ثقلها الروحي. قبل أن تكلّم أحدًا اليوم، تذكّر أنك تتعامل مع من يحبه المسيح.\",\"p\":\"أيها المسيح إلهي، علّمني أن أرى فيك كل أخ. احفظني من أن أعثر أحدًا، وأعطني أن أكسب القلوب بمحبتك. آمين.\",\"x\":\"الربح هنا هو أن نربح الإنسان لا الحجة. من خسر أخاه خسر حياته، ومن ربحه ربح الله معه. تدريب: عند أول خلاف اليوم، اسأل: ماذا يربح أخي لو سكتُّ وصلّيتُ؟\",\"fq\":7}]},\"1-7\":{\"th\":\"عيد الميلاد المجيد\",\"m\":[{\"t\":\"الكلمة صار جسدًا\",\"ref\":\"إنجيل باكر\",\"v\":\"والكلمة صار جسدا وحل بيننا ورأينا مجده مثل مجد ابن وحيد لأبيه مملوءا نعمة وحقا.\",\"r\":\"في الميلاد لا نحتفل بفكرة بل بشخص: الكلمة نفسه صار جسدًا وسكن بيننا. الله لم يرسل رسالة بل جاء بنفسه. هذا هو معنى عيدنا، أن الله ليس بعيدًا عن بيتك وتعبك وفرحك. اقترب اليوم من المذود بقلب يفتح له مكانًا.\",\"p\":\"أيها الكلمة المتجسد، شكرًا لأنك سكنت بيننا ورأينا مجدك. افتح قلبي لك كما فتحت العذراء حضنها، واملأني نعمةً وحقًا. آمين.\",\"x\":\"ميلاد المسيح يحقق وعد الله القديم: الكلمة صار جسدًا، فسكن بيننا. والكنيسة تسمي التجسد سر التقوى العظيم. تدريب: اقرأ مطلع إنجيل يوحنا واجعله صلاتك اليوم، وقل: يا رب أشكرك لأنك جئت إلينا.\"},{\"t\":\"وُلد لكم اليوم مخلّص\",\"ref\":\"لوقا ٢: ١٠–١١\",\"bk\":\"لوقا\",\"v\":\"فقال لهم الملاك: «لا تخافوا! فها أنا أبشركم بفرح عظيم يكون لجميع الشعب: أنه ولد لكم اليوم في مدينة داود مخلص هو المسيح الرب.\",\"r\":\"الملاك لم يقل للرعاة: ستحتاجون إلى مجهود كبير. قال: «أبشركم بفرح عظيم». الميلاد ليس إنجازًا بشريًا بل هبة. والله جاء إلى أبسط الناس: رعاة يسهرون على قطيعهم. وهو يأتي اليوم إلى قلبي أيضًا، لا لأني أستحق بل لأن محبته سبقت استحقاقي.\",\"p\":\"يا رب يسوع، أشكرك لأنك ولدت لأجلي. افتح قلبي مذودًا لك، وامنحني فرح الرعاة وإيمانهم. ثبّتني في البشارة التي تجعل الحياة جديدة. آمين.\",\"x\":\"الميلاد هو إعلان أن الله لم يبقَ بعيدًا. دخل التاريخ في مغارة فقيرة بلا ضجيج ملكي. وهذا يعلّمنا أن الله يأتي حيث يُفتح له مكان، لا حيث يُعرض عليه المجد. والرعاة سمعوا البشارة لأنهم كانوا مستيقظين، فالاستعداد للقاء الله يبدأ بالسهر الروحي.\\nاجعل عيد الميلاد هذا العام لحظة تفتح فيها مذودًا لقلبك: أعطِ المسيح مكانًا في برنامج يومك، وصلِّ شكرًا على تجسده.\"},{\"t\":\"أعظم نعمة: تجسّد ابن الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"حين طلب الإخوة من الأب إيسيذورس أن يرتاح لأنه شاخ، أجاب أنه حتى لو أُحرق ونُثر رماده في الهواء فلا نعمة أكبر من أن ابن الله جاء إلى هنا من أجلنا. التجسد هو الذي يهوّن كل تعب. تأمّل اليوم: ماذا يعني أن الله أحبني حتى نزل إلى عالمي؟\",\"p\":\"يا رب يسوع، ابن الله الذي جاء من أجلنا، لك الشكر على تجسدك وفدائك. اجعل هذه النعمة أعظم ما في قلبي، وهوّن عليّ كل تعب بسببك. آمين.\",\"x\":\"تكفي نعمة التجسد وحدها لتملأ العمر عبادة، وهذا ما كان يردده الأب في شيخوخته. تدريب: في هذا العيد، خصص وقتًا لتشكر الله على التجسد قبل أي هدية أو وليمة.\",\"fq\":170}]},\"1-8\":{\"th\":\"الصبر والانتظار\",\"m\":[{\"t\":\"انتظر الرب فتقوى\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"وأنا أؤمن أني أعاين خيرات الرب في أرض الأحياء. انتظر الرب، تقو وليتشدد قلبك وانتظر الرب.\",\"r\":\"يعلّمنا المرنم أن الانتظار ليس ضعفًا بل مدرسة قوة: «انتظر الرب، تقوَّ وليتشدد قلبك». ننتظر وقلوبنا تُبنى بالإيمان بأن الله يرى ما لا نرى. في أمرٍ معلّق في حياتك اليوم، قل لله: أنا أنتظرك، وأثق أنك أعددتَ لي خيرًا.\",\"p\":\"يا رب، أؤمن أني سأعاين خيراتك في أرض الأحياء. قوِّ قلبي في الانتظار، وأعطني صبرًا لا يتعجّل ولا ييأس مما تؤخّره. آمين.\",\"x\":\"الانتظار في لغة الكتاب فعل إيمان، لا فراغ. ومن ينتظر الرب تتجدد قوته. تدريب: ما الأمر الذي تنتظر فيه الله منذ مدة طويلة؟ اكتبه وقل له: أنا أنتظرك وأثق في وقتك.\"},{\"t\":\"الصبر يصنع الخبرة\",\"ref\":\"رومية ٥: ٣–٥\",\"bk\":\"رومية\",\"v\":\"وليس ذلك فقط، بل نفتخر أيضا في الضيقات، عالمين أن الضيق ينشئ صبرا، والصبر تزكية، والتزكية رجاء، والرجاء لا يخزي، لأن محبة الله قد انسكبت في قلوبنا بالروح القدس المعطى لنا.\",\"r\":\"يبدو غريبًا أن نفتخر بالضيقات. لكن الرسول يشرح السلسلة: الضيق ينتج صبرًا، والصبر خبرة، والخبرة رجاء. فالألم لا يُحتمل وحده، بل يحمله الروح القدس الذي سُكبت فيه محبة الله. وهكذا تتحول المحنة من عائق إلى مدرسة.\",\"p\":\"يا رب، أشكرك لأنك لا تترك المتألم وحده. حوّل ضيقاتي إلى صبر وخبرة ورجاء. املأ قلبي بمحبتك لأقف ثابتًا في المحنة. آمين.\",\"x\":\"نلاحظ أن الرجاء هنا ليس تفاؤلًا ساذجًا، بل هو ثمرة خبرة حقيقية مع الله في الضيق. من عبر وادي الظلمة ورأى يد الله فيه يعرف أن الله أمين. وفي رسالة يعقوب نجد أن التجارب تجعلنا «كاملين وتامين غير ناقصين في شيء».\\nتأمل ضيقًا مررت به في الماضي، وتذكّر كيف عبرت منه. اشكر الله على ما تعلمته، وخذ من ذلك ثقة لمواجهة الحاضر.\"},{\"t\":\"أعطني الصبر في الحروب\",\"ref\":\"\",\"v\":\"\",\"r\":\"لم يطلب الأب يوحنا الكولوفي أن تُرفع الحرب عنه، بل صلّى: «يا رب أعطني الصبر في الحروب». كثيرًا ما نطلب رفع الضيق، وقليلًا ما نطلب القوة على الصبر فيه. هذه كلمات قليلة نردّدها اليوم عند أول ضيق.\",\"p\":\"يا رب، أعطني الصبر في حروبي، ولا تدعني أتعجّل مخرجًا خارج مشيئتك. كن معي حتى ينتهي الامتحان. آمين.\",\"x\":\"لم يطلب الأب رفع الحرب بل قوة للصبر عليها، لأن الحرب تدربنا على الاتكال على الله. تدريب: عند أول ضيق اليوم، قل: أعطني الصبر يا رب، ولا تطلب فقط زواله.\",\"fq\":155}]},\"1-9\":{\"th\":\"الاتضاع طريق الرفعة\",\"m\":[{\"t\":\"قلبٌ لم يرتفع\",\"ref\":\"المزمور ١٣٠ — النوم\",\"v\":\"يا رب لم يرتفع قلبي، ولم تستعل عيناي؛ ولم أسلك في العظائم ولا في العجائب التي هي أعلى مني.\",\"r\":\"لا يدّعي المرنم العظمة ولا يطلب ما فوق طاقته، فقلبه مطمئن كطفل فُطم على صدر أمه. الاتضاع ليس إنكار القدرة، بل قبول حجمي أمام الله. إن تعبتَ من المقارنة والسباق، فاجلس اليوم لحظة وقل: لا أطلب يا رب أكثر مما تعطيني.\",\"p\":\"يا رب، لم يرتفع قلبي ولم تستعلِ عيناي. علّمني أن أطمئن في حضنك كطفل، ولا أسعى إلى عظائم تفوق ما أعطيتني. آمين.\",\"x\":\"يصف المرنم قلبه بالطفل المفطوم عند أمه، آمنًا لا يطلب أكثر مما يلزم. هذا هو الاتضاع الذي يرفعه الله. تدريب: تخل اليوم عن حاجة واحدة للظهور أو الكلام الكثير عن نفسك.\"},{\"t\":\"الله يقاوم المستكبرين\",\"ref\":\"بطرس الأولى ٥: ٥–٦\",\"bk\":\"بطرس الأولى\",\"v\":\"كذلك أيها الأحداث، اخضعوا للشيوخ، وكونوا جميعا خاضعين بعضكم لبعض، وتسربلوا بالتواضع، لأن: «الله يقاوم المستكبرين، وأما المتواضعون فيعطيهم نعمة». فتواضعوا تحت يد الله القوية لكي يرفعكم في حينه،\",\"r\":\"قد نظن أن الكبرياء يدفعنا إلى القمة، لكن الكتاب يقول إن الله يقاوم المستكبرين. وهذه مقاومة محبة، لأنه لا يريد أن نسقط في الوهم. بينما المتواضعون يأخذون نعمة، أي قوة ومعونة. فلنتواضع تحت يد الله القوية.\",\"p\":\"يا رب، احفظني من الكبرياء الخفي. أعطني نعمة الاتضاع لأقبل مكاني ومحدوديتي، وارفعني أنت في الوقت الذي تراه. آمين.\",\"x\":\"التواضع لا يمنعنا من السعي والطموح، لكنه يغير الدافع: أن نسعى للخدمة لا للتفوق على الآخرين. والرسول يعد برفعة «في حينه»؛ أي أن الله هو الذي يرفع وليس نحن. وهذا يريحنا من سباق إثبات الذات.\\nاسأل نفسك: متى آخر مرة اعترفت بخطأ علنًا؟ فكّر في موقف تحتاج فيه إلى الاعتذار، واتخذ الخطوة.\"},{\"t\":\"فخاخ العدو والتواضع\",\"ref\":\"\",\"v\":\"\",\"r\":\"رأى القديس أنطونيوس فخاخ العدو منتشرة على الأرض فتنهّد: من ينجو منها؟ فجاءه الجواب: التواضع. جوابٌ بسيط لكنه يحتاج حياةً كاملة. جرّب اليوم أن تتنازل في موقف صغير قبل أن تثبت أنك على صواب.\",\"p\":\"يا رب، احفظني من فخاخ العدو بالتواضع. انزع الكبرياء من قلبي، وعلّمني أن أنحني كما انحنيتَ أنت لتغسل أقدام تلاميذك. آمين.\",\"x\":\"رأى الأب فخاخ العدو منتشرة على الأرض، وسأل من يفلت منها، فجاء الجواب: التواضع. من يتحرك بخفة لا يعلق بها. تدريب: انتبه اليوم لموقف تميل فيه إلى التفاخر، واستبدله بشكر.\",\"fq\":5}]},\"1-10\":{\"th\":\"أنا مع الله\",\"m\":[{\"t\":\"معه أنا في الشدة\",\"ref\":\"المزمور ٩٠ (٩١) — السادسة\",\"v\":\"لأنه على أتكل فأنجيه: أرفعه (أستره) لأنه عرف اسمي. يدعوني فأستجيب له. معه أنا في الشدة، أنقذه وأمجده.\",\"r\":\"الله لا يعد بغياب الشدة، بل بحضوره فيها: «معه أنا في الشدة». هذا الوعد يغيّر نظرتنا إلى الصعوبة، فهي ليست دليل غياب بل مكان لقاء. تذكّر اليوم موقفًا ثقيلًا في حياتك وقل: أنت معي هنا.\",\"p\":\"يا رب، أنت تُجيب من يدعوك وتكون معه في الشدة. أنقذني ومجّدني بنعمتك، وعلّمني أن أراك قريبًا في ضيقاتي. آمين.\",\"x\":\"الله لا يعد بغياب الضيقة بل بوجوده معنا فيها، وهذا ما يثبّت المرنم. تدريب: اذكر شدة تمر بها وقل لله: أنت معي فيها، ثم اطلب منه أن ترى حضوره في تفاصيلها.\"},{\"t\":\"لا أتركك ولا أهملك\",\"ref\":\"العبرانيين ١٣: ٥–٦\",\"bk\":\"العبرانيين\",\"v\":\"لتكن سيرتكم خالية من محبة المال. كونوا مكتفين بما عندكم، لأنه قال: «لا أهملك ولا أتركك» حتى إننا نقول واثقين: «الرب معين لي فلا أخاف. ماذا يصنع بي إنسان؟»\",\"r\":\"في زمن يعتمد فيه الإنسان على المال والمكانة والعلاقات، يعدنا الله بما هو أعظم: حضوره الدائم. هذا الوعد لا يلغي الصعوبات، لكنه يغيّر طريقة مواجهتها. فنقول بثقة: «الرب معين لي فلا أخاف».\",\"p\":\"يا رب، أشكرك لأنك وعدت ألا تتركني. حين أخاف ذكّرني بحضورك، وحين أطمع علّمني القناعة. أنت معيني فلا أخاف. آمين.\",\"x\":\"الوعد هنا يتكرر بصيغة النفي المزدوج في الأصل: لن أتركك أبدًا. وهذا يعطي الثقة التي تحررنا من محبة المال والتعلق بما نملك. فمن يعرف أن الله معه، يقنع بما عنده ويجرؤ على الخدمة والعطاء.\\nاسأل نفسك: ما الأمر الذي أحسب أمانه عليه أكثر من الله؟ اختر اليوم أن تضعه جانبًا وتتكل على الله وحده.\"},{\"t\":\"الله في القلاية وخارجها\",\"ref\":\"\",\"v\":\"\",\"r\":\"يتساءل الأب دانيال: من ينزع الله منا؟ ثم يعلن أن الله في القلاية وخارجها. حضوره لا يتوقف على مكان نحبه أو ظرف نختاره. فلنعش اليوم بإحساس أن الله يرافقنا في العمل والطريق والبيت.\",\"p\":\"يا رب، أنت في كل مكان، فلا تدعني أنسى حضورك. أعطني سلامًا يثبّتني في كل ظرف وتغيير. آمين.\",\"x\":\"قلب الأب مطمئن لأن الله حاضر في القلاية كما في خارجها، فلا يحتاج مكانًا معينًا ليلتقيه. تدريب: توقف مرتين اليوم في عملك وقل: أنت هنا يا رب.\",\"fq\":95}]},\"1-11\":{\"th\":\"الرجاء الذي لا يخزي\",\"m\":[{\"t\":\"خلاص وجهي هو إلهي\",\"ref\":\"المزمور ٤٢ (٤٣) — الثالثة\",\"v\":\"لماذا أنت حزينة يا نفسي، ولماذا تزعجينني؟ توكلي على الله فإني أعترف له. خلاص وجهي هو إلهي.\",\"r\":\"يحاور المرنم نفسه الحزينة بدل أن يتركها للحزن: لماذا أنت حزينة؟ توكلي على الله. الرجاء قرارٌ يُتخذ حين تثقل النفس، وليس شعورًا ينتظر الظروف. حاور قلبك اليوم بالطريقة نفسها، وذكّره بأن خلاصك من الله لا من الأحوال.\",\"p\":\"يا رب، أنت خلاص وجهي وإلهي. حين تحزن نفسي ذكّرني أن أتوكل عليك، واجعل الرجاء فيك مرساةً لقلبي. آمين.\",\"x\":\"المرنم يحاور نفسه بدلًا من أن ينجرف مع حزنها: لماذا أنت حزينة؟ ثم يوجه رجاءه إلى الله. تدريب: اكتب حزنًا يطاردك، ثم اكتب تحته آية رجاء، وردد الآية كلما عاد.\"},{\"t\":\"رجاء يحيا في الانتظار\",\"ref\":\"رومية ٨: ٢٤–٢٥\",\"bk\":\"رومية\",\"v\":\"لأننا بالرجاء خلصنا. ولكن الرجاء المنظور ليس رجاء، لأن ما ينظره أحد كيف يرجوه أيضا؟ ولكن إن كنا نرجو ما لسنا ننظره فإننا نتوقعه بالصبر.\",\"r\":\"أصعب أنواع الانتظار هو انتظار ما لا نراه. بولس يقول إن الرجاء المنظور ليس رجاءً، فالذي أراه بعيني لا أحتاج أن أرجوه. إذن الرجاء مدرسة الإيمان: يعلّمني أن أمشي بثقة قبل أن أرى، وأن أصبر وأنا أعلم أن الله لا يتأخر ولا ينسى.\",\"p\":\"يا رب، علّمني أن أرجو ما لا أراه وأن أنتظر دون تذمر. اجعل ضيقي مدرسة تصنع فيّ صبرًا ورجاءً. املأ قلبي بمحبتك المسكوبة بروحك القدوس. آمين.\",\"x\":\"الرجاء يتولد في أرض غير متوقعة: الضيق. فالضيق ينشئ صبرًا، والصبر تزكية، والتزكية رجاءً. هذه سلسلة تعني أن الله لا يُقيمني على رجاء بدون اختبار، لأن الرجاء الذي لم يُجرَّب هشٌّ. ومن ذاق مرة أن الله أمين في ضيقه، صار يرجو أكثر في الضيق القادم.\\nتذكّر موقفًا صعبًا مرّ بك وخرجت منه بحماية لم تتوقعها. اشكر الله عليه بصوت مسموع، ثم قل: «الذي أعان في الماضي يعين اليوم».\"},{\"t\":\"لماذا الشك إذن؟\",\"ref\":\"\",\"v\":\"\",\"r\":\"تعب الإخوة فسأل أحدهم الأب يوحنا الفارسي، فأجابهم بإيمان من يثق في وعد ربه: سأرث أورشليم العلوية لأن من وعدنا أمين. لا ينفي التعبَ، لكنه يضع الوعد فوقه. حين تثقل عليك مشقة اليوم، فكّر في من وعدك.\",\"p\":\"يا رب، أنت أمين في كل وعودك. ثبّتني في رجاء أورشليم العلوية، وامنحني ألا أشك فيك عند التعب. آمين.\",\"x\":\"سؤال الأب: لماذا الشك؟ يذكّر أن الله الذي حملنا حتى اليوم لن يتركنا الآن. تدريب: اذكر موقفًا نجاك الله فيه سابقًا، وأخبر به شخصًا ليتقوى به.\",\"fq\":204}]},\"1-12\":{\"th\":\"الفرح بالرب\",\"m\":[{\"t\":\"فرحٌ للمستقيمي القلوب\",\"ref\":\"المزمور ٩٦ (٩٧) — التاسعة\",\"v\":\"نور أشرق للصديقين وفرح للمستقيمي القلوب. افرحوا أيها الصديقون بالرب. واعترفوا لذكر قدسه.\",\"r\":\"الفرح الذي يتحدث عنه المرنم نور يُشرق للصديقين، فليس هو تهريجًا ولا هروبًا. إنه ثمرة قلب مستقيم أمام الله. افرح اليوم بشيء صغير تعرف أنه من الله، واشكره باسمه، وسترى أن الفرح يكبر حين نعترف بمصدره.\",\"p\":\"يا رب، أشرق بنورك على قلبي واملأه فرحًا مستقيمًا. علّمني أن أفرح بك وأعترف لذكر قدسك في كل يوم. آمين.\",\"x\":\"فرح المرنم نور يشرق على المستقيمي القلوب، وليس مرتبطًا بظروف سهلة. تدريب: ابحث عن موقف اليوم يمكن أن تبتسم فيه بصدق وتشكر، واجعله علامة فرحك بالرب.\"},{\"t\":\"فرح لا ينتزعه أحد\",\"ref\":\"فيلبي ٤: ٤\",\"bk\":\"فيلبي\",\"v\":\"افرحوا في الرب كل حين، وأقول أيضا: افرحوا.\",\"r\":\"بولس كتب هذه الآية وهو في السجن. هذا وحده كافٍ ليعلّمنا أن الفرح الذي يتكلم عنه ليس راحة ظرفية. إنه فرحٌ في الرب، أي أن مصدره خارج الظروف. إن كان فرحي مرهونًا بيوم هادئ، فهو ضيف. أما إن كان مرتبطًا بشخص المسيح، فهو ساكن لا يغادر.\",\"p\":\"يا رب، علّمني أن أفرح بك لا بما يعطيه الزمان. حوّل شكواي إلى تسبيح وثقل يومي إلى شكر. ثبّت فيّ فرحك الذي لا ينتزعه أحد. آمين.\",\"x\":\"قد نظن أن الفرح مشاعر تأتي وتذهب، لكن الكتاب يعامله كوصية وكثمرة. الوصية معناها أني أختاره وأتدرّب عليه: أن أنظر إلى ما عند الله لا إلى ما ينقصني. والثمرة معناها أنه ينمو من علاقتي بالروح القدس مع الوقت. فالفرح ليس إنكارًا للحزن، بل هو شمس تبقى فوق الغيوم.\\nاليوم، قبل أن تنام، اذكر ثلاثة أسباب للفرح في المسيح لا علاقة لها بما جرى في يومك. ردّدها كتسبحة قصيرة.\"},{\"t\":\"افرحوا دائمًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب بنيامين أبناءه في ساعته الأخيرة بثلاث: افرحوا دائمًا، صلوا بلا انقطاع، واشكروا على كل شيء. وصية رجل قرر أن يترك لهم ما هو أثمن من المال. أيٌّ من الثلاث أحوج إليه قلبك اليوم؟\",\"p\":\"يا رب، علّمني الفرح الدائم والصلاة بلا انقطاع والشكر على كل شيء. احفظ هذه الوصية حيةً في داخلي. آمين.\",\"x\":\"وصية الأب الأخيرة تجمع فرحًا وصلاة وشكرًا، وهي التي تحفظ القلب في كل ظرف. تدريب: أضف إلى صلاتك اليوم جملة فرح: افرحني بخلاصك يا رب.\",\"fq\":84}]},\"1-13\":{\"th\":\"الأمانة في القليل\",\"m\":[{\"t\":\"الوكيل الأمين الحكيم\",\"ref\":\"إنجيل الخدمة الثالثة — نصف الليل — الخدمة الثالثة\",\"v\":\"من هو الوكيل الأمين الحكيم الذي يقيمه سيده على عبيده ليعطيهم طعامهم في حينه؟ طوبى لذلك العبد الذي إذا جاء سيده يجده يفعل هكذا. حقا أقول لكم إنه يقيمه على جميع أمواله.\",\"r\":\"سؤال الرب عن الوكيل الأمين لا يبحث عن المشاهير، بل عمّن يعطي الآخرين طعامهم في حينه. الأمانة هي الاستمرار في الواجب الصغير دون مراقب. ما المهمة الصغيرة المنسية في يومك، وهل تؤديها كأن السيد حاضر؟\",\"p\":\"يا رب، اجعلني وكيلًا أمينًا حكيمًا على ما استأمنتني عليه. علّمني أن أؤدي الصغير بفرح، فتقيمني على الكثير بنعمتك. آمين.\",\"x\":\"الوكيل الأمين هو من يوزع في ميعاده، وليس من يملك كثيرًا. الأمانة تظهر في التفاصيل اليومية. تدريب: اختر مسؤولية صغيرة تهملها وأتمها اليوم بإتقان لله.\"},{\"t\":\"من كان أمينًا في القليل\",\"ref\":\"لوقا ١٦: ١٠\",\"bk\":\"لوقا\",\"v\":\"الأمين في القليل أمين أيضا في الكثير، والظالم في القليل ظالم أيضا في الكثير.\",\"r\":\"نحب أن نتصور أننا سنكون أمناء متى جاءت المهمة الكبرى. لكن الرب يقول إن الحياة تُقاس بالتفاصيل: مواعيدي الصغيرة، وكلمتي التي لم يسمعها أحد، وعملي حين لا يراقبني أحد. الأمانة عادة تتكون يومًا بعد يوم في الأمور التي نحسبها لا شيء.\",\"p\":\"يا رب، علّمني أن أكون أمينًا في الصغير كما في الكبير. نقِّ قلبي من الإهمال والتسويف، واجعل عملي كله لمجدك. اذكرني كعبدك الأمين. آمين.\",\"x\":\"الأمانة ليست كمية بل نوعية. من لا يصدق في أمر بسيط لن يصدق في كبير، لأن المشكلة ليست في حجم الأمر بل في حال القلب. والله لا يختبرنا بالعظائم أولًا، بل بما بين أيدينا الآن. لذلك فإن غسل الأطباق بأمانة والرد على الرسالة بصدق وإنهاء العمل بإتقان هي ممارسات روحية.\\nاسأل نفسك: ما الأمر الصغير الذي أهملته عن عمد أو تهرّبت منه؟ اختر واحدًا وأتمّه اليوم كأنك تقدمه للمسيح.\"},{\"t\":\"عمل خفيف ودائم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يفضّل الأب ماتوى عملًا خفيفًا دائمًا على عمل متعب لا يدوم. الأمانة ليست حماسة البدء بل ثبات الاستمرار. اختر اليوم عادة روحية صغيرة يمكنك أن تمارسها كل يوم دون أن تنقطع.\",\"p\":\"يا رب، أعطني أمانةً هادئة لا تتعب، وثباتًا في العمل الصغير. وكلّل جهدي المتواضع بنعمتك. آمين.\",\"x\":\"عمل خفيف ودائم يبني حياة روحية ثابتة أكثر من حماس قصير يتلاشى. تدريب: التزم بقاعدة صغيرة، مثل مزمور واحد كل يوم، وثبّت عليها شهرًا.\",\"fq\":268}]},\"1-14\":{\"th\":\"الصداقة مع الله\",\"m\":[{\"t\":\"الرب أمامي في كل حين\",\"ref\":\"المزمور الخامس عشر — باكر\",\"v\":\"تقدمت فرأيت الرب أمامي في كل حين، لأنه عن يميني لكي لا أتزعزع. من أجل هذا فرح قلبي وتهلل لساني. وأيضا جسدي يسكن على الرجاء.\",\"r\":\"الصداقة مع الله تبدأ حين أراه أمامي في كل حين لا في المناسبات فقط. وجوده عن يميني يعطيني ثباتًا، وفرح القلب نتيجة طبيعية لهذه الصحبة. اجعل لنفسك اليوم عادة قصيرة: كلما بدأت عملًا جديدًا، قل في سرّك: أنت هنا يا رب.\",\"p\":\"يا رب، أنت أمامي في كل حين وعن يميني فلا أتزعزع. ليفرح قلبي بصحبتك، وليسكن جسدي على الرجاء. آمين.\",\"x\":\"أن أجعل الرب أمامي في كل حين يعني أن أعيش بوعي حضوره، فلا أتزعزع. تدريب: ضع علامة صغيرة تذكرك بحضور الله: ورقة على مكتبك أو كلمة على شاشة هاتفك.\"},{\"t\":\"موسى وإبراهيم: أصدقاء الله\",\"ref\":\"الخروج ٣٣: ١١\",\"bk\":\"الخروج\",\"v\":\"ويكلم الرب موسى وجها لوجه، كما يكلم الرجل صاحبه. وإذا رجع موسى إلى المحلة كان خادمه يشوع بن نون الغلام، لا يبرح من داخل الخيمة.\",\"r\":\"موسى كان يكلّم الله «كما يكلم الرجل صاحبه». هذا يعني أنه قال كل ما في قلبه: شكواه وخوفه وأسئلته وحتى اعتراضه. والله لم يغضب، بل قرّبه أكثر. الصداقة مع الله لا تعني أن أخفي ضعفي، بل أن أحمله إليه بصدق.\",\"p\":\"يا رب، علّمني أن أكلمك كصديق وأسمعك كابن. اجعل صلاتي صادقة لا زخرفة فيها. كشف لي قلبك كما كشفته لأحبائك، وأعطني أن أحيا حسب مشيئتك. آمين.\",\"x\":\"في قصة إبراهيم يقول الله: «هل أخفي عن إبراهيم ما أنا فاعله؟». والله يُعلن خطته لمن يحبه. هكذا الصداقة: مشاركة، لا أوامر فقط. والذي يعيش في صلاة حقيقية يبدأ يفهم قلب الله ويتألم لما يتألم له ويفرح بما يفرح به.\\nاسأل الله اليوم سؤالًا حقيقيًا يشغلك، ثم اجلس بعد السؤال دقيقتين في صمت لتسمع، ولو لم يأتك صوت فالإصغاء نفسه صلاة.\"},{\"t\":\"إذا طلبنا الله يظهر لنا\",\"ref\":\"\",\"v\":\"\",\"r\":\"الكلمات قليلة عند القديس أرسانيوس لكنها وعد: إذا طلبنا الله يظهر لنا، وإذا تمسكنا به يقيم فينا. الصداقة مع الله تتطلب طلبًا ثم تمسكًا. اطلب وجهه اليوم، ولا تتركه عند أول ازدحام للانشغال.\",\"p\":\"يا رب، أطلبك فاظهر لي، وأتمسك بك فأقم فيّ. لا تدعني أبتعد عنك مهما شغلتني الأيام. آمين.\",\"x\":\"من يطلب الله بقلب صادق يجده، فالأمر ليس لغزًا، بل وعد. تدريب: خصص اليوم عشر دقائق للبحث عن الله في الكتاب والصلاة بلا طلب محدد، فقط لتلتقيه.\",\"fq\":30}]},\"1-15\":{\"th\":\"الصوم والخلوة\",\"m\":[{\"t\":\"تذكرتُ الأيام الأولى\",\"ref\":\"المزمور المئة والثاني والأربعون — باكر\",\"v\":\"تذكرت الأيام الأولى ولهجت في كل أعمالك، وفي صنائع يديك كنت أتأمل. بسطت إليك يدي. صارت نفسي لك مثل أرض بلا ماء.\",\"r\":\"في خلوة المرنم يتذكر أعمال الله ويتأمل صنائع يديه، ثم يبسط يديه إليه كأرض عطشى. الخلوة ليست انسحابًا بل استعادة لذاكرة النعمة. خصّص اليوم دقائق بلا هاتف، واذكر ثلاثة مواقف عمل الله فيها معك.\",\"p\":\"يا رب، أتذكر أعمالك وأتأمل صنائع يديك. أبسط يدي إليك، فتصير نفسي أرضًا عطشى ترتوي من حضورك. آمين.\",\"x\":\"في الخلوة يتذكر المرنم أعمال الله القديمة، فيتحول الذكر إلى صلاة. والصوم خلوة الجسد كما الصلاة خلوة القلب. تدريب: اجلس خمس دقائق في صمت، وتذكر ثلاث مرات تدخل الله فيها في حياتك.\"},{\"t\":\"صلِّ إلى أبيك في الخفاء\",\"ref\":\"متى ٦: ٦\",\"bk\":\"متى\",\"v\":\"وأما أنت فمتى صليت فادخل إلى مخدعك وأغلق بابك، وصل إلى أبيك الذي في الخفاء. فأبوك الذي يرى في الخفاء يجازيك علانية.\",\"r\":\"في عالم يُعرض فيه كل شيء، يدعوك المسيح إلى باب مغلق. ليست الدعوة هروبًا بل لقاء بلا جمهور، لا أحتاج فيه أن أبدو صالحًا بل أكون على حقيقتي. ومن يتعلم الخلوة يصير ثابتًا حين يخرج، لأن جذوره في الخفاء.\",\"p\":\"أبانا الذي في السموات، أريد أن ألقاك في الخفاء بلا قناع. اجذبني إلى خلوتي، وأغلق عني ضجيج العالم. علّمني أن أصلي لأجلك لا لأجل أحد. آمين.\",\"x\":\"الصلاة العلنية لها مكانها، لكن الصلاة الحقيقية تبدأ في الخفاء. فالإنسان قد يكتسب شكل التقوى ولا يكتسب جوهرها. والباب المغلق رمز لإغلاق الأبواب أمام الأفكار والمشتتات والصورة التي أريد أن يراها الناس عني. حينئذ فقط يلتقي القلب بالآب بلا قناع.\\nاختر مكانًا هادئًا ووقتًا محددًا لهذه الخلوة، واكتب موعدها في هاتفك كموعد مهم لا يُلغى.\"},{\"t\":\"اجلس في قلايتك\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل أخٌ الأب موسى كلمة منفعة، فلم يعطه محاضرة بل قال: اجلس في قلايتك وهي تعلّمك كل شيء. الخلوة مدرسة لمن يسكن فيها بصدق. اختر لنفسك مكانًا هادئًا في بيتك، واجلس فيه خمس دقائق صامتًا.\",\"p\":\"يا رب، علّمني أن أحب الخلوة معك. وفي صمتها علّمني ما لا يُقال، ودعني أسمع فيها همس نعمتك. آمين.\",\"x\":\"جلسة القلاية تعلّمنا أن الراحة تُوجد في الثبات في المكان لا في الحركة. تدريب: اختر ركنًا هادئًا في بيتك واجلس فيه اليوم دقائق بلا هاتف ولا ضجيج.\",\"fq\":255}]},\"1-16\":{\"th\":\"الغفران يحرر\",\"m\":[{\"t\":\"غفرتَ وسترتَ\",\"ref\":\"المزمور ٨٤ (٨٥) — السادسة\",\"v\":\"رضيت يا رب عن أرضك، رددت سبى يعقوب. غفرت آثام شعبك. سترت جميع خطاياهم.\",\"r\":\"يرى المرنم الغفران مثل نهرٍ يرد الأسير إلى بيته: غفرت آثام، وسترت الخطايا، ورجعت عن غضبك. من نال هذا الغفران صار أقدر على أن يغفر. فكّر في إنسان لم تغفر له بعد، واطلب اليوم من الله أن يعطيك أن تبدأ.\",\"p\":\"يا رب، شكرًا لأنك غفرت آثام شعبك وسترت خطاياهم. علّمني أن أغفر كما غفرت لي، وحرّر قلبي من كل مرارة. آمين.\",\"x\":\"الغفران كنهر يعيد الأسير إلى بيته، فمن غُفر له يُطلق ليعيش. تدريب: اطلب اليوم من الله أن يغفر لك، ثم اغفر لشخص واحد بكلمة أو صلاة.\"},{\"t\":\"سبعون مرة سبع مرات\",\"ref\":\"متى ١٨: ٢١–٢٢\",\"bk\":\"متى\",\"v\":\"حينئذ تقدم إليه بطرس وقال: «يارب، كم مرة يخطئ إلي أخي وأنا أغفر له؟ هل إلى سبع مرات؟» قال له يسوع: «لا أقول لك إلى سبع مرات، بل إلى سبعين مرة سبع مرات.\",\"r\":\"بطرس ظن أن سبع مرات سخاء كبير. لكن الرب أجاب بما يتجاوز الحساب. الغفران الحقيقي لا يعدّ. وهو لا يعني تجاهل الأذى بل رفض العيش به. إن كنت تغفر ثم تتذكر الألم وتضيق، فلا تيأس: الغفران عملية تحتاج تكرارًا لا مرة واحدة.\",\"p\":\"يا رب، علّمني أن أغفر دون عدّ، كما تغفر أنت لي كل يوم. اشفِ ذاكرتي من المرارة. وأعطني أن أكون سفير مصالحتك. آمين.\",\"x\":\"الغفران ليس لحظة بل مسيرة. قد أغفر اليوم ثم تعود الذكرى فأغفر من جديد، وهذا لا يعني أن الأول فشل بل أن الجرح عميق. والله يصبر علينا في هذه العملية كما يصبر علينا في سقوطنا. المهم ألا أتوقف عن الرغبة في الشفاء.\\nكلما عاد إليك ألم ذكرى مؤلمة هذا الأسبوع، قل: «يا رب أنا أغفر ثانية». سجّل كم مرة احتجت إلى قولها.\"},{\"t\":\"لم أنم وفي قلبي شيء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشهد القديس أغاثون أنه لم ينم يومًا وفي قلبه شيء على أحد، ولم يترك أحدًا ينام وفي قلبه عليه شيء. يعمل هكذا على قدر طاقته. هذا هو الغفران العملي: مصالحة قبل الغروب. إن كان بينك وبين أحد خلاف، فابدأ اليوم بخطوة صغيرة.\",\"p\":\"يا رب، اجعلني صانع سلام لا أنام وفي قلبي ضغينة. وأعطني شجاعة أن أبدأ بالاعتذار والمصالحة. آمين.\",\"x\":\"يشهد الأب أنه لم ينم وفي قلبه شيء على أحد، لأن الغفران قبل النوم يحمي الراحة. تدريب: قبل النوم اليوم، اذكر اسم من آذاك وصلِّ من أجله بخير.\",\"fq\":48}]},\"1-17\":{\"th\":\"الطاعة طريق البركة\",\"m\":[{\"t\":\"علّمني أن أصنع مشيئتك\",\"ref\":\"المزمور المئة والثاني والأربعون — باكر\",\"v\":\"علمني أن أصنع مشيئتك. لأنك أنت هو إلهي. روحك القدوس فليهدني إلى الاستقامة.\",\"r\":\"الطاعة في كلمات المرنم ليست آلية بل طلب: علّمني. نحن لا نعرف المشيئة تلقائيًا، والروح القدس هو الذي يهدينا إلى الاستقامة. اسأل الله اليوم عن مشيئته في أمرٍ يشغلك، واترك الجواب يأتي بهدوء، ولو تأخر.\",\"p\":\"يا رب، علّمني أن أصنع مشيئتك فأنت إلهي. وليهدني روحك القدوس إلى الاستقامة من أجل اسمك. آمين.\",\"x\":\"يقول المرنم: علمني، فالطاعة تبدأ بالتعلم وليس بالإذعان الأعمى. فمشيئة الله ليست قيدًا بل طريق. تدريب: اسأل الله: ما مشيئتك اليوم؟ ثم نفذ أول ما يتضح لك.\"},{\"t\":\"نوح ومسيرة الطاعة\",\"ref\":\"التكوين ٦: ٢٢\",\"bk\":\"التكوين\",\"v\":\"ففعل نوح حسب كل ما أمره به الله. هكذا فعل.\",\"r\":\"بنى نوح الفلك سنين طويلة والسماء صافية. ربما سخر منه الناس. لكنه فعل «حسب كل ما أمره الله». لم يطلب دليلًا ولم يؤجل. طاعته كانت تصديقًا بالفعل. وربما يطلب منا الله اليوم أمرًا يبدو غير منطقي، لكنه خلاص لنا ولمن حولنا.\",\"p\":\"يا رب، امنحني إيمان نوح الذي يطيع قبل أن يرى. ثبّتني على الطريق الطويل. اجعل طاعتي سببًا لخلاص بيتي وكل من حولي. آمين.\",\"x\":\"الإيمان في العبرانيين ليس شعورًا بل حركة: «بالإيمان نوح... بنى فلكًا». ولم تكن طاعته لحظة حماس بل مثابرة على مدى سنوات. والطاعة المثابرة تُدين العالم دون كلام، إذ تُظهر قيمة مختلفة. وقد نجا أهل بيته معه، فطاعة الأب لها أثر على من حوله.\\nاكتب أمرًا واحدًا تشعر أن الله يطلب منك المثابرة عليه، وقرّر ألا تتوقف عنه حتى لو لم ترَ ثمرًا الآن.\"},{\"t\":\"الطاعة تخضع الوحوش\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أنطونيوس إن الطاعة مع الإمساك تخضع الوحوش. أي أن الذي يتعلم أن يطيع ويضبط نفسه يصير أقوى من كل ما يخيفه. جرّب اليوم أن تطيع بسرعة في أمر لا تحبه، وراقب كيف يتقوّى قلبك.\",\"p\":\"يا رب، علّمني الطاعة والإمساك، واخضع بهما وحوش أهوائي. أعطني قلبًا ينقاد لوصاياك بفرح. آمين.\",\"x\":\"الطاعة مع الإمساك تخضع حتى الوحوش، أي أن الداخل المنضبط يهدئ الخارج. تدريب: اختر اليوم أمرًا تمسك فيه نفسك طاعة لله، وليكن صغيرًا لكنه يومي.\",\"fq\":20}]},\"1-18\":{\"th\":\"الاستعداد لعيد الغطاس\",\"m\":[{\"t\":\"يقظةٌ تسبق النور\",\"ref\":\"قوموا يا بني النور — نصف الليل — الخدمة الأولى\",\"v\":\"قوموا يا بني النور لنسبح رب القوات، لكي ينعم علينا بخلاص نفوسنا، عندما نقف أمامك جسديا انزع من عقولنا نوم الغفلة. أعطنا يا رب يقظة لكي نفهم كيف نقف أمامك وقت الصلاة.\",\"r\":\"قبل عيد الغطاس تدعونا الكنيسة أن نقوم كبني النور وننزع من عقولنا نوم الغفلة. الاستعداد للعيد أن نصحو لما هو أثمن: حضور الله. اطلب اليوم يقظة ذهنية واحدة، كأن تنتبه لكلماتك وأفكارك في الصلاة.\",\"p\":\"يا رب، أنعم عليّ بيقظةٍ أقف بها أمامك وقت الصلاة. انزع من عقلي نوم الغفلة، واجعلني أحد بني النور. آمين.\",\"x\":\"اليقظة قبل الغطاس تشبه التهيؤ للنور: ننزع ثياب الظلمة ونلبس أسلحة النور. تدريب: اختر عادة تحجب عنك النور وتخلص منها اليوم، حتى لو كانت صغيرة.\"},{\"t\":\"توبة تسبق المعمودية\",\"ref\":\"متى ٣: ٨\",\"bk\":\"متى\",\"v\":\"فاصنعوا أثمارا تليق بالتوبة.\",\"r\":\"يوحنا لم يعتمد كل من جاء، بل صرخ في الفريسيين: «اصنعوا ثمرًا يليق بالتوبة». فالتوبة ليست شعورًا بالندم فقط بل تغيير يُرى. وقبل العيد، هذا السؤال موجه لي: ما هو الثمر الذي يشهد على أنني رجعت إلى الله؟ هل في علاقاتي وكلامي وقراراتي علامة جديدة؟\",\"p\":\"يا رب، لا أريد توبة بالكلام بل بالحياة. أعطني ثمرًا يليق بالتوبة. اشفِ ضعفي وقوِّ إرادتي، واقبلني إليك كل يوم من جديد. آمين.\",\"x\":\"الثمر دليل الشجرة. وإذا لم أرَ تغييرًا في سلوكي بعد سنوات من الاعتراف، فربما كنت أعترف بالكلام فقط. هذا لا يعني الكمال بل الاتجاه: أن أسير في طريق التوبة. فحتى الخطوات الصغيرة تُحسب. والنعمة تعمل معي وتعطيني القوة لثمر لم أكن قادرًا عليه.\\nاختر عادة واحدة سيئة وقرّر معالجتها بخطوة عملية محددة هذا الأسبوع، وناقشها مع أب اعترافك.\"},{\"t\":\"الصحو أصل التقدم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أغاثون إنه بدون صحو كثير لا يستطيع الإنسان أن يتقدم ولا في فضيلة واحدة. الصحو هو أن أنتبه لما يحدث في داخلي. استعدادك للغطاس هذا الأسبوع يبدأ بأن تلاحظ أفكارك اليوم قبل أن تتصرف.\",\"p\":\"يا رب، امنحني صحوًا ويقظة. علّمني أن أراقب قلبي وأفكاري، وأتقدم في الفضيلة بنعمتك. آمين.\",\"x\":\"الصحو الكثير هو الانتباه للفكر والنظر والكلام، وهو أصل التقدم. تدريب: راقب اليوم أفكارك ثلاث مرات في النهار، واسأل: هل هذا الفكر من الله؟\",\"fq\":59}]},\"1-19\":{\"th\":\"عيد الغطاس: معمودية ربنا\",\"m\":[{\"t\":\"تقدموا واستنيروا\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"تقدموا إليه واستنيروا، ووجوهكم لا تخزى.\",\"r\":\"في الغطاس يستنير الإنسان بالمسيح، وكل من يتقدم إليه لا يخزى. ليس المعمودية حدثًا مضى بل نور ما زال يضيء. تذكّر اليوم أنك ابن لله بالمعمودية، وأن هذه الهوية لا تتغير بتغير ظروفك.\",\"p\":\"يا رب، أتقدم إليك لأستنير، فلا تُخزِ وجهي. اجعلني أحيا بنور معموديتي، وأثبت في بنوّتي لك كل أيام حياتي. آمين.\",\"x\":\"في الغطاس يتجلى الثالوث: الآب يشهد والروح ينزل والابن يعتمد. ونحن بالمعمودية ندخل هذه الشركة. تدريب: تذكر يوم عمادك واشكر الله على الاسم الذي حملته، وصلِّ بإشارة الصليب بوعي.\"},{\"t\":\"ماء يقدّس الحياة\",\"ref\":\"رومية ٦: ٤\",\"bk\":\"رومية\",\"v\":\"فدفنا معه بالمعمودية للموت، حتى كما أقيم المسيح من الأموات، بمجد الآب، هكذا نسلك نحن أيضا في جدة الحياة؟\",\"r\":\"بولس يقول إننا دُفنا مع المسيح بالمعمودية لنسلك في جدّة الحياة. هذا ليس تشبيهًا فقط بل حقيقة سرائرية: شيء مات فيّ وشيء قام. ولكني أحتاج أن أعيش حسب هذه الحقيقة كل يوم، فأرفض ما دُفن وأتمسك بما قام.\",\"p\":\"يا رب، أشكرك على نعمة المعمودية. ميّت معك أنا عن الخطية، وقائم معك للحياة. ساعدني أن أسلك في جدّة الحياة كل يوم، وأن أعيش ما صرت إليه بنعمتك. آمين.\",\"x\":\"في الكنيسة القبطية نغطّس المعتمد ثلاث مرات إشارة إلى الثالوث وإلى أيام الدفن الثلاثة. والغطس يعني أن حياة قديمة انتهت، والصعود يعني أن حياة جديدة بدأت. غير أن هذه الحياة تنمو بالنعمة والجهاد. المعمودية بداية الطريق وليست نهايته.\\nاسأل نفسك: ما هو الشيء الذي ينبغي أن يموت فيّ، والذي ما زلت أحمله؟ سلّمه اليوم للمسيح ليدفنه معه.\"},{\"t\":\"ثلاثة أمور يطلبها الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس غريغوريوس اللاهوتي إن الله يطلب ممن اقتبل المعمودية ثلاثة أمور: الإيمان القويم من كل النفس، والحقيقة من الفم، والتعقل من الجسد. اختر اليوم أمرًا واحدًا من الثلاثة لتتدرب عليه، وسيصير عيدك أثمر.\",\"p\":\"يا رب، أثبّتني في إيماني المستقيم، وافتح فمي للصدق، وعلّمني تعقّل الجسد. أنت الذي اقتبلتني بالمعمودية، أكمل عمل نعمتك. آمين.\",\"x\":\"ثلاثة أمور يطلبها الله ممن اعتمد، وعلى المعمد أن يسأل نفسه عن ثمر عماده. تدريب: اكتب الآن سلوكًا يليق بمن اعتمد، واحرص عليه هذا الأسبوع.\",\"fq\":87}]},\"1-20\":{\"th\":\"حياة جديدة بالروح\",\"m\":[{\"t\":\"روحك لا تنزعه منا\",\"ref\":\"قطعة الثالثة (١)\",\"v\":\"روحك القدوس يا رب الذي أرسلته على تلاميذك القديسين ورسلك المكرمين، هذا لا تنزعه منا أيها الصالح، لكن جدده في أحشائنا. قلبا نقيا اخلق في يا الله، وروحا مستقيما جدد في أحشائي.\",\"r\":\"تصلي الكنيسة في الساعة الثالثة أن لا ينزع الله روحه القدوس بل يجدده في الأحشاء. الحياة الجديدة تتجدد كل يوم بتسليم القلب. اطلب اليوم قلبًا نقيًا في لحظة صلاة، واترك لله أن يخلقه كما يشاء.\",\"p\":\"يا رب، لا تنزع منا روحك القدوس بل جدده في أحشائنا. اخلق فيّ قلبًا نقيًا وروحًا مستقيمًا. آمين.\",\"x\":\"تصلي الكنيسة في الساعة الثالثة بحلول الروح القدس، لأنها ساعة العنصرة. ولا نطلب الروح لأنفسنا فقط بل ليبقى فينا. تدريب: في الساعة الثالثة اليوم، توقف دقيقة وقل: لا تنزع روحك القدوس مني.\"},{\"t\":\"السير بالروح\",\"ref\":\"غلاطية ٥: ٢٥\",\"bk\":\"غلاطية\",\"v\":\"إن كنا نعيش بالروح، فلنسلك أيضا بحسب الروح.\",\"r\":\"الحياة بالروح ليست حالة ثابتة بل سير: خطوة بعد خطوة. وفي كل يوم أقف عند مفترقات صغيرة: أن أرد أو أصمت، أن أغفر أو أحتفظ، أن أصلي أو أؤجل. والسير بالروح هو أن أسأل في كل مفترق: ماذا تريدني أن أفعل يا رب؟\",\"p\":\"أيها الروح القدس، أريد أن أسير بك لا أن أكتفي بأنني أملكك. قدني في كل خطوة. أعطني أن أسمع صوتك الهادئ وأطيعه. آمين.\",\"x\":\"الرسول يربط بين الحياة بالروح والسير بالروح. فمن عاش بالروح ولم يسر به، يشبه من امتلك سيارة ويتركها واقفة. والسير يعني الاتجاه والاستمرار. وقيادة الروح لا تتعارض مع عقلي بل تنيره، وهو يتكلم بهدوء وبما يوافق الكتاب.\\nاجعل لنفسك اليوم عادة: قبل اتخاذ أي قرار، حتى لو صغيرًا، توقف ثلاث ثوانٍ وقل داخلك: «قدني يا روح الله».\"},{\"t\":\"الروح كالمطر\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب يوحنا الكولوفي نزول الروح القدس بالمطر: عندما ينزل في القلوب تتجدد وتخرج براعم بمخافة الله. التجديد عمل الله، وعلينا أن نكون أرضًا مفتوحة. افتح قلبك اليوم لصلاة قصيرة تطلب فيها حلول الروح.\",\"p\":\"أيها الروح القدس، انزل في قلبي كالمطر، وأنبت فيّ براعم مخافة الله. جدّد حياتي، وأعد لي نضارة البدء. آمين.\",\"x\":\"كما يغير المطر الأرض اليابسة، يغيّر الروح القلب الجاف. تدريب: اسأل نفسك أي جزء من قلبك جاف، وصلِّ أن يسقيه الروح القدس.\",\"fq\":153}]},\"1-21\":{\"th\":\"مريم: حفظت كل هذه الأمور\",\"m\":[{\"t\":\"أم النور المكرّمة\",\"ref\":\"قطعة باكر (٣)\",\"v\":\"أنت هي أم النور المكرمة، يا والدة الإله... لأن الآب اختارك، والروح القدس ظللك. والابن تنازل وتجسد منك.\",\"r\":\"تذكر الكنيسة العذراء بالتمجيد لأن الآب اختارها والروح القدس ظللها والابن تجسد منها. قبلت دعوة الله بصمت وتأمل. تأمّل اليوم كيف يمكن أن تقبل أنت دعوة الله في أمرٍ صغير، بقلب مصغٍ كقلبها.\",\"p\":\"أيتها العذراء والدة الإله، اسألي المسيح من أجلنا. علّمينا أن نحفظ كلمة الله في القلب، ونقبل مشيئته بإيمان وصمت. آمين.\",\"x\":\"تكرم الكنيسة العذراء لأن الله اختارها لتحمل المسيح، وهي أول من حفظ كلمته في قلبها. تدريب: حاول اليوم أن تحفظ كلمة سمعتها في قلبك وتتأمل فيها بدلًا من أن تنقلها.\"},{\"t\":\"مريم في عرس قانا\",\"ref\":\"يوحنا ٢: ٥\",\"bk\":\"يوحنا\",\"v\":\"قالت أمه للخدام: «مهما قال لكم فافعلوه».\",\"r\":\"في قانا رأت مريم حاجة العروسين قبل أن يطلب أحد. رفعتها إلى ابنها بلا ضغط ولا تفاصيل، ثم قالت للخدام كلمة واحدة: افعلوا ما يقوله. هكذا تعلّمنا أن نصلي: نعرض الحاجة ثم نسلّم الطريقة. والطاعة بعد ذلك تفتح باب المعجزة.\",\"p\":\"يا رب يسوع، بشفاعة أمك العذراء أعرض عليك حاجتي. علّمني أن أطيعك دون أن أفهم، وأن أنتظر عملك بثقة. حوّل ماء حياتي إلى خمر فرحك. آمين.\",\"x\":\"حين بدا أن جوابه لا يوافق طلبها، لم تجادل، بل التفتت إلى الخدام وقالت لهم ما يقوّي إيمانهم. والمعجزة لم تحدث بالكلام بل بالخدام الذين ملأوا الجرار ماءً دون أن يفهموا. فالطاعة في الأمور الصغيرة التي لا معنى لها عندنا، هي ما يهيّئ لعمل الله العظيم.\\nما هو أمر صغير طلبه الله منك ولم تفهم سببه؟ قم به اليوم بإيمان، وعرض عليه حاجتك دون فرض الحل.\"},{\"t\":\"أن يكون إصغاؤك أكثر من كلامك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب نيسثروس أن الإصغاء أولى من الكلام في المناقشة، وأن من لا يشعر بالراحة في كلامه فالصمت أفضل. العذراء كانت تحفظ الأمور في قلبها. في حوارٍ ما اليوم، انتظر لحظة قبل أن تجيب.\",\"p\":\"يا رب، علّمني الإصغاء قبل الكلام. وبشفاعة العذراء اجعلني أحفظ كلمتك في قلبي وأتكلم بما ينفع. آمين.\",\"x\":\"الإصغاء أول التعلم، ومن يسمع أكثر مما يتكلم يتعلم الحكمة. تدريب: في أول حوار اليوم، استمع حتى النهاية قبل أن ترد.\",\"fq\":299}]},\"1-22\":{\"th\":\"حفظ اللسان\",\"m\":[{\"t\":\"صُن لسانك عن الشر\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"صن لسانك عن الشر، وشفتيك عن النطق بالغش. حد عن الشر واصنع الخير. اطلب السلامة وأتبعها.\",\"r\":\"يربط المرنم الحياة الصالحة بحفظ اللسان: صن لسانك، حد عن الشر، اطلب السلامة. الكلمة تصنع حياة أو تهدمها. تدرّب اليوم على أن تتأنى قبل كل جملة جارحة، وتستبدلها بصمت أو بكلمة طيبة.\",\"p\":\"يا رب، صن لساني عن الشر وشفتيّ عن الغش. علّمني أن أحيد عن الشر وأصنع الخير، وأطلب السلامة وأتبعها. آمين.\",\"x\":\"حفظ اللسان من الشر بداية الحياة الصالحة في نظر المرنم، لأن الكلمات تحدد الاتجاه. تدريب: امتنع اليوم عن كلمة سلبية واحدة تقولها عادة، واستبدلها بكلمة تشجيع.\"},{\"t\":\"كلام يُصلح\",\"ref\":\"أفسس ٤: ٢٩\",\"bk\":\"أفسس\",\"v\":\"لا تخرج كلمة ردية من أفواهكم، بل كل ما كان صالحا للبنيان، حسب الحاجة، كي يعطي نعمة للسامعين.\",\"r\":\"الكلمة الطيبة صدقة كما يقول الآباء. وقد لا ندرك كم يحتاج الناس إلى كلمة تشجيع. زميل متعب، أو أم في البيت، أو صديق وحيد. بكلمة واحدة صادقة قد أعطي أحدهم قوة ليوم كامل. فهل أقول اليوم كلمة تبني؟\",\"p\":\"يا رب، علّمني أن أستخدم كلامي لأبني لا لأهدم. أعطني عينًا ترى حاجة الآخرين وفمًا يقول الكلمة الصالحة في وقتها. اجعل شفتيّ ينبوع نعمة. آمين.\",\"x\":\"بولس لا يكتفي بالنهي عن الكلام الفاسد، بل يضع معيارًا إيجابيًا: هل تفيد البنيان حسب الحاجة؟ يعني أن أنظر إلى حال السامع قبل أن أتكلم: ماذا يحتاج الآن؟ تشجيع أم تصحيح أم تعزية؟ وهذه حكمة تُكتسب بالمحبة والانتباه.\\nأرسل اليوم رسالة شكر أو تشجيع صادقة إلى ثلاثة أشخاص، وسمّ فيها ما تقدّره فيهم بالتحديد.\"},{\"t\":\"استرني من لساني\",\"ref\":\"\",\"v\":\"\",\"r\":\"صلاة الأب سيسوى بسيطة وصادقة: «استرني من لساني لأني بسببه أسقط كل يوم». لا يدّعي القوة بل يطلب الستر. اجعل هذه الصلاة بداية يومك، وأعطها لنفسك كلما همّت بالكلام الجارح.\",\"p\":\"يا ربي يسوع المسيح، استرني من لساني، لأني بسببه أسقط وأخطئ. ضع حافظًا لفمي وبابًا حصينًا لشفتيّ. آمين.\",\"x\":\"صلاة الأب بسيطة: استرني من لساني. إنها اعتراف بأن أكثر سقطاتنا تبدأ من الفم. تدريب: ردد هذه الصلاة قبل كل اجتماع أو مكالمة اليوم.\",\"fq\":486}]},\"1-23\":{\"th\":\"الصلاة بلا ملل\",\"m\":[{\"t\":\"إذ دعوت استجبتَ لي\",\"ref\":\"المزمور الرابع — باكر\",\"v\":\"إذ دعوت استجبت لي يا إله بري. في الشدة فرجت عني. تراءف على يا رب واسمع صلاتي.\",\"r\":\"يقول المرنم إن الله استجاب حين دعاه، وفرّج عنه في الشدة. الذي يذكر استجابات الأمس يواصل الصلاة اليوم. اكتب في ذهنك ثلاث مرات استجاب الله لك فيها، وارفع بعدها طلبك الحالي بثقة.\",\"p\":\"يا إله برّي، إذ دعوتُك استجبتَ لي، وفي الشدة فرّجت عني. تراءف عليّ واسمع صلاتي، وعلّمني ألا أمل من الدعاء. آمين.\",\"x\":\"الله يستجيب حين يُدعى، والصلاة ليست محاولة لإقناعه بل لقاء معه. تدريب: لا تؤجل الصلاة لحين الفراغ، بل صلِّ قصيرة في منتصف العمل.\"},{\"t\":\"القاضي الظالم والأرملة\",\"ref\":\"لوقا ١٨: ١\",\"bk\":\"لوقا\",\"v\":\"وقال لهم أيضا مثلا في أنه ينبغي أن يصلى كل حين ولا يمل،\",\"r\":\"الأرملة لم تملك مالًا ولا نفوذًا، بل إصرارًا. وكلما أغلق القاضي بابه كانت تعود. المسيح يريد أن نصلي بالإصرار نفسه، لا لأن الله قاسٍ أو يحتاج إلى إقناع، بل لأن الإصرار يربي إيماننا ويعلّمنا أن نطلب ما يستحق أن نطلبه حقًا.\",\"p\":\"يا رب، علّمني ألا أملّ من الصلاة. قوِّ إيماني حين يتأخر الجواب. أشكرك لأنك تسمع وتنصف، وأنك أعدل وأرحم من كل قاضٍ. آمين.\",\"x\":\"المثل يعتمد على التضاد: إن كان قاضٍ بلا رحمة يستجيب للإلحاح، فكم بالأحرى أبونا الصالح. فالمشكلة ليست في الله بل في إيماننا الذي يضعف. والمسيح ينتهي بسؤال: «ولكن متى جاء ابن الإنسان، ألعله يجد الإيمان على الأرض؟». فالصلاة الدائمة علامة إيمان حي.\\nاكتب طلبًا واحدًا أرجأته لأنك يئست من استجابته، وقرّر أن تحمله في صلاتك كل يوم هذا الأسبوع.\"},{\"t\":\"أصلّي وأنا أعمل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يردّ الأب لوكيوس على من يظنون أن الصلاة تعطّل العمل بأنه يصلّي بدون انقطاع وهو يحوك الخوص، مردّدًا: «ارحمني يا الله كعظيم رحمتك». يمكنك أن تحول عملك كله إلى صلاة بكلمة قصيرة تكررها.\",\"p\":\"يا الله، ارحمني كعظيم رحمتك وكمثل كثرة رأفتك. اجعل عملي كله صلاةً ترتفع إليك بلا انقطاع. آمين.\",\"x\":\"يمكن أن تتحول الأعمال اليدوية إلى صلاة مستمرة إذا اجتمعت مع ذكر الله. تدريب: اختر عملًا روتينيًا اليوم، ورافقه بصلاة يسوع بهدوء.\",\"fq\":226}]},\"1-24\":{\"th\":\"إيمان مثل حبة الخردل\",\"m\":[{\"t\":\"آمنتُ لذلك تكلمت\",\"ref\":\"المزمور ١١٥ — التاسعة\",\"v\":\"آمنت لذلك تكلمت. وأنا اتضعت جدا.\",\"r\":\"ينطق المرنم بإيمان لا يخلو من اعتراف بالضعف: آمنت، وأنا اتضعت جدًا. الإيمان لا يعني غياب الشك، بل أن نتكلم مع الله وسط الشك. قل اليوم لله بصراحة ما يخيفك، وأضف إليه: لكني أؤمن بك.\",\"p\":\"يا رب، آمنت لذلك تكلمت. أنا اتضعت جدًا أمامك، فاقبل إيماني القليل وزده، وأعن عدم إيماني. آمين.\",\"x\":\"يقول المرنم: آمنت لذلك تكلمت، فالإيمان يظهر في الكلام والشهادة. وهو في الوقت نفسه يعترف بتواضع أنه ضعيف. تدريب: شارك اليوم شخصًا بكلمة إيمان صغيرة عن خبرة عشتها.\"},{\"t\":\"أؤمن يا رب فأعن عدم إيماني\",\"ref\":\"مرقس ٩: ٢٤\",\"bk\":\"مرقس\",\"v\":\"فللوقت صرخ أبو الولد بدموع وقال: «أومن يا سيد، فأعن عدم إيماني».\",\"r\":\"هذا الأب لم يقل: أؤمن بالكامل. بل قال: «أؤمن فأعن عدم إيماني». كانت صلاته صادقة بشكل مؤثر. اعترف بالإيمان والشك معًا. والمسيح لم يوبخه بل شفى ابنه. فلا تخجل أن تصلي بقلب فيه أسئلة وشكوك. الله يقبل الإيمان الناقص ويكمله.\",\"p\":\"يا رب، أؤمن، فأعن عدم إيماني. أنا أحمل إليك شكوكي وأسئلتي بدل أن أهرب منك. قوِّ ثقتي بك، وأعطني أن أراك في كل موقف. آمين.\",\"x\":\"قد نظن أن الشك عدو الإيمان، لكنه في كثير من الأحيان جزء من رحلته. المهم ما أفعله بالشك: هل أذهب به إلى الله أم أبتعد؟ هذا الأب أخذ شكوكه إلى المسيح. والمسيح يعطي إيمانًا لمن يطلبه، فالإيمان نفسه عطية. ولهذا يمكنني أن أصلي من أجل زيادته.\\nاكتب الشك أو السؤال الذي يزعجك، وحوّله إلى صلاة بصيغة هذه الآية، وكرّرها حتى تهدأ.\"},{\"t\":\"الإيمان ثمر التواضع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعرّف الأب بيمن الإيمان بأن يسلك الإنسان بتواضع ويفعل الصدقة، لأن الإيمان والإحسان يمحوان الخطايا. هكذا يبدو الإيمان عملًا بسيطًا. اختر اليوم عملًا صغيرًا من الإحسان تقوم به بتواضع.\",\"p\":\"يا رب، أعطني إيمانًا يعمل بالمحبة، وتواضعًا يخدم بلا ضجيج. وليكن إحساني اليوم شهادةً لك. آمين.\",\"x\":\"يربط الأب الإيمان بالتواضع والعطاء، فالإيمان ليس فكرة بل سلوك. تدريب: أعط اليوم صدقة سرية، وصلِّ أن تزيد إيمانك.\",\"fq\":365}]},\"1-25\":{\"th\":\"الرحمة تنتصر\",\"m\":[{\"t\":\"رؤوفٌ ورحيم\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"وأنت أيها الرب الإله أنت رؤوف ورحيم. أنت طويل الروح؛ وكثير الرحمة وصادق.\",\"r\":\"يصف المرنم الله بأنه رؤوف رحيم طويل الروح كثير الرحمة. الرحمة التي نأخذها منه هي التي نتعلم أن نعطيها. فكّر في إنسان تأخرتَ في رحمته، وأعطه اليوم فرصة أخرى كما أعطاك الله فرصًا كثيرة.\",\"p\":\"يا رب، أنت رؤوف ورحيم طويل الروح كثير الرحمة. اجعلني رحيمًا بالآخرين كما رحمتني، وطويل الأناة على من أساء إليّ. آمين.\",\"x\":\"صفات الله الثلاث هنا: رؤوف رحيم طويل الروح، وبها يتعامل معنا. وعلينا أن نتشبه به في بيوتنا. تدريب: عند أول إساءة اليوم، قل لنفسك: الله طويل الروح معي، فلأكن كذلك مع غيري.\"},{\"t\":\"السامري الصالح\",\"ref\":\"لوقا ١٠: ٣٣\",\"bk\":\"لوقا\",\"v\":\"ولكن سامريا مسافرا جاء إليه، ولما رآه تحنن،\",\"r\":\"الكاهن واللاوي رأيا الجريح وعبرا. أما السامري فـ«رآه فتحنن». الفرق بين الثلاثة لم يكن المعرفة الدينية بل القلب. الرحمة تبدأ بأن أسمح لعيني أن ترى وتتأثر. وأحيانًا أمر على حاجة قريبة مني لأني مشغول، فيسألني المسيح: ومن هو قريبك؟\",\"p\":\"يا رب يسوع، يا سامري نفوسنا، أشكرك لأنك تحننت عليّ. اجعل عيني ترى المحتاجين وقلبي يتحرك نحوهم. لا تدعني أمرّ بجانب أحد دون أن أرحمه. آمين.\",\"x\":\"السامري لم يكتف بالشعور، بل أعطى وقتًا ومالًا وجهدًا، وضمّد وحمل وأنزل في فندق ووعد بالعودة. الرحمة الحقيقية عملية ومكلفة ومستمرة. والمسيح هو السامري الأعظم الذي ضمّد جراحنا بالسرّ وحملنا إلى الكنيسة. ومن ذاق رحمته يستطيع أن يقدّمها.\\nاسأل نفسك: من هو «الجريح» الذي مررت به مؤخرًا ولم تتوقف؟ ارجع إليه اليوم بمكالمة أو زيارة أو مساعدة.\"},{\"t\":\"كن رحيمًا نحو الجميع\",\"ref\":\"\",\"v\":\"\",\"r\":\"وصية الأب بمفو للأب ثيوذورس واضحة: «اذهب وكن رحيمًا نحو الجميع، لأن الرحمة قد وجدت حظوة في عيني الرب». ما أبسط الوصية وما أعمق أثرها! اجعل رحمتك اليوم تتجاوز من تحبهم إلى من يصعب عليك حبهم.\",\"p\":\"يا رب، اجعلني رحيمًا نحو الجميع، وأعطني أن أجد حظوة في عينيك برحمتي. وارحمني أنا أيضًا كعظيم رحمتك. آمين.\",\"x\":\"وصية قصيرة لكنها تشمل كل شيء: كن رحيمًا نحو الجميع. تدريب: اختر شخصًا تعامله بجفاف، وغيّر تعاملك معه اليوم.\",\"fq\":465}]},\"1-26\":{\"th\":\"الخدمة بمحبة\",\"m\":[{\"t\":\"اعبدوا الرب بالفرح\",\"ref\":\"المزمور ٩٩ (١٠٠) — التاسعة\",\"v\":\"اعبدوا الرب بالفرح، ادخلوا أمامه بالتهليل. اعلموا أن الرب هو إلهنا، هو صنعنا وليس نحن، ونحن شعبه وغنم رعيته.\",\"r\":\"الخدمة في كلمات المرنم عبادة بفرح ودخول بتهليل، فنحن شعبه وغنم رعيته. الخادم الذي ينسى أنه من الغنم يتعب، والذي يتذكر يخدم بسرور. خدمتك اليوم، مهما صغرت، يمكن أن تكون عبادة إن قمت بها بقلب فرح.\",\"p\":\"يا رب، أعبدك بالفرح وأدخل أمامك بالتهليل. أعلم أنك إلهي وأنني من غنم رعيتك، فاجعل خدمتي ثمرة فرحي بك. آمين.\",\"x\":\"العبادة بالفرح تعني أن الخدمة ليست عبئًا بل امتياز. نحن شعب الرب وغنم رعيته. تدريب: قدّم اليوم خدمة صغيرة بابتسامة صادقة وبلا تذمر.\"},{\"t\":\"كل واحد بحسب الموهبة\",\"ref\":\"بطرس الأولى ٤: ١٠\",\"bk\":\"بطرس الأولى\",\"v\":\"ليكن كل واحد بحسب ما أخذ موهبة، يخدم بها بعضكم بعضا، كوكلاء صالحين على نعمة الله المتنوعة.\",\"r\":\"ليس هناك مؤمن بلا موهبة. قد لا أراها لأنها بسيطة: قدرة على الاستماع، أو ترتيب، أو ابتسامة، أو صبر على الصغار. وبطرس يقول إنها نعمة الله المتنوعة، وأنا وكيل عليها. فالسؤال ليس هل لدي موهبة، بل هل أستخدمها لأخدم به غيري؟\",\"p\":\"يا رب، أشكرك على المواهب التي أعطيتني. اغفر لي إخفاءها وتقليلي منها. علّمني أن أخدم بها بأمانة وتواضع، لمجد اسمك ولبنيان كنيستك. آمين.\",\"x\":\"المقارنة تقتل الموهبة. حين أنظر إلى مواهب غيري أنسى ما أعطاني الله. والكنيسة جسد كل عضو فيه ضروري. وربما تكون خدمتي صغيرة في عين الناس، لكنها كبيرة في عين الله، لأن عمله يتم بتكامل الجميع. وأن أخدم بما عندي أفضل من أن أنتظر موهبة أخرى.\\nاكتب ثلاث أشياء تجيد فعلها، وسل أب اعترافك أو صديقًا أين يمكن أن تستخدمها في خدمة الكنيسة هذا الشهر.\"},{\"t\":\"ننحني لله في أخينا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّمنا الأب أبو للوس أن ننحني للإخوة الذين يأتون إلينا لأننا لا ننحني لهم إنما لله، فإذا رأيت أخاك رأيت الرب إلهك. هذه نظرة خدمة جديدة. استقبل اليوم من يطرق بابك أو يطلب منك شيئًا كأنه ضيف المسيح.\",\"p\":\"يا رب، علّمني أن أرى وجهك في وجه أخي، وأخدمه بتواضع كمن يخدمك. آمين.\",\"x\":\"ننحني لله في أخينا لأن المسيح يظهر في كل إنسان، فالانحناء للأخ تعبير عن إكرام الله. تدريب: عامل اليوم كل من تقابله كأنه المسيح، ولو لدقائق.\",\"fq\":77}]},\"1-27\":{\"th\":\"الحكمة من فوق\",\"m\":[{\"t\":\"رأس الحكمة\",\"ref\":\"المزمور ١١٠ (١١١) — التاسعة\",\"v\":\"رأس الحكمة مخافة الرب. والفهم صالح لكل من يعمل به؛ وتسبحته دائمة إلى الأبد هلليلويا.\",\"r\":\"يضع المرنم نقطة البداية: مخافة الرب، ثم الفهم الصالح لمن يعمل به. الحكمة ليست معلومات بل عمل. اسأل نفسك اليوم عن أمرٍ تعرف الصواب فيه ولا تعمل به، وابدأ في تنفيذه بخطوة واحدة.\",\"p\":\"يا رب، ضع في قلبي مخافتك رأسًا للحكمة. وأعطني فهمًا صالحًا أعمل به، فتكون تسبحتك دائمة في فمي. آمين.\",\"x\":\"رأس الحكمة مخافة الرب، لأنها تضع الله في مكانه فيعرف الإنسان مكانه. تدريب: اطلب اليوم الحكمة في قرار صغير قبل أن تتخذه، بصلاة قصيرة.\"},{\"t\":\"سليمان يطلب قلبًا فهيمًا\",\"ref\":\"الملوك الأول ٣: ٩\",\"bk\":\"الملوك الأول\",\"v\":\"فأعط عبدك قلبا فهيما لأحكم على شعبك وأميز بين الخير والشر، لأنه من يقدر أن يحكم على شعبك العظيم هذا؟»\",\"r\":\"لو أتاك الله وقال: اطلب ماذا أعطيك؟ فما الذي ستقوله؟ سليمان كان شابًا وملكًا وأمامه كل الخيارات. لكنه طلب قلبًا فاهمًا. وهذا يكشف تواضعه: اعترف أنه صغير وأن المسؤولية أكبر منه. والله أعطاه ما طلب وزاده ما لم يطلب.\",\"p\":\"يا رب، أنا فتى صغير لا أعرف كيف أخرج وأدخل. أعطني قلبًا فهيمًا يميز بين الخير والشر. وليكن كل ما أطلبه لمجدك وخير شعبك. آمين.\",\"x\":\"الصلاة التي تبدأ بما أحتاجه حقًا (الحكمة) تفتح الباب لكل الباقي. أما الصلاة التي تطلب الأشياء الثانوية أولًا فقد تفقد الأهم. والله يُسر حين تكون رغبتنا مرتبطة بخدمة الآخرين: سليمان طلب الحكمة ليقضي بين الشعب لا لنفسه. فالدافع يؤثر على الاستجابة.\\nراجع قائمة طلباتك في الصلاة: كم منها لخدمة الله والناس؟ أضف طلبًا واحدًا لأجل حكمة حقيقية في مسؤوليتك.\"},{\"t\":\"فضيلة التمييز\",\"ref\":\"\",\"v\":\"\",\"r\":\"يلفت القديس أنطونيوس النظر إلى أناس أفنوا أجسادهم بالنسك وبقوا بعيدين عن الله لأنهم لم يقتنوا فضيلة التمييز. الحماس بغير حكمة قد يضر. قبل أن تقرر في أمر مهم اليوم، اسأل مرشدك أو صلِّ طالبًا التمييز.\",\"p\":\"يا رب، هب لي روح التمييز. احفظني من الحماس الأعمى، واجعل أعمالي كلها بحكمة تقودني إليك. آمين.\",\"x\":\"التمييز يحفظ النسك من الانحراف، فبه نعرف ما يوافق الله وما لا يوافق. تدريب: قبل أن تلتزم بأمر جديد في عبادتك، استشر أب اعتراف أو شخصًا حكيمًا.\",\"fq\":6}]},\"1-28\":{\"th\":\"الثبات في التجارب\",\"m\":[{\"t\":\"اضطجعتُ ونمتُ فاستيقظت\",\"ref\":\"المزمور الثالث — باكر\",\"v\":\"أنا اضطجعت ونمت، ثم استيقظت لأن الرب ناصري. فلا أخاف من ربوات الجموع المحيطين بي القائمين علي.\",\"r\":\"ينام المرنم وسط جموع محيطة به ثم يستيقظ آمنًا لأن الرب ناصره. الثبات في التجارب لا يعني غياب الأعداء بل حضور الناصر. في موقفٍ يحاصرك اليوم، قل: الرب ناصري، وانتبه كيف يتغير ثقل الجموع في قلبك.\",\"p\":\"يا رب، أنت ناصري فلا أخاف من ربوات الجموع المحيطين بي. ثبّتني في التجارب، وأيقظني دائمًا في حفظك. آمين.\",\"x\":\"ينام المرنم وسط جموع حوله ثم يستيقظ لأن الرب سنده. الأمان في الله لا في غياب المشاكل. تدريب: قبل النوم اليوم سلّم لله ما يقلقك، وقل: أنت تحفظني.\"},{\"t\":\"لا تجربة إلا بشرية\",\"ref\":\"كورنثوس الأولى ١٠: ١٣\",\"bk\":\"كورنثوس الأولى\",\"v\":\"لم تصبكم تجربة إلا بشرية. ولكن الله أمين، الذي لا يدعكم تجربون فوق ما تستطيعون، بل سيجعل مع التجربة أيضا المنفذ، لتستطيعوا أن تحتملوا.\",\"r\":\"حين أتألم أشعر أن أحدًا لا يفهمني وأن الحمل فوق طاقتي. لكن الكتاب يقول إن كل من مرّوا بمثل ما أمر به، والله أمين: لا يسمح بتجربة تفوق احتمالي، ويفتح مخرجًا. هذه ليست كلمات سهلة، لكنها وعد من الله الذي لا يكذب.\",\"p\":\"يا رب، أنت أمين ولا تسمح بتجربة فوق طاقتي. افتح لي المنفذ، وقوِّ قلبي. اجعلني أسهر وأقاوم بإيمان، وأعبر كل شدة بنعمتك. آمين.\",\"x\":\"التجربة تأتي من ثلاثة مصادر: من الخارج، ومن ضعفي، ومن إبليس. والله لا يجربنا بالشر لكنه قد يسمح بالامتحان. وبطرس يوصينا بالسهر والمقاومة، لا بالاستسلام. ومع هذا يعدنا بأن الله بعد ألم قليل سيكمّلنا ويثبّتنا ويقوّينا. فالنهاية دائمًا شفاء ونمو.\\nاذكر تجربة تشعر أنها فوق طاقتك، وصلّ بالآية: «الله أمين». اطلب من الله أن يريك المنفذ، وقد يأتيك بصورة غير متوقعة.\"},{\"t\":\"يوسف وأيوب\",\"ref\":\"\",\"v\":\"\",\"r\":\"حين تعب أخ قلبه، ذكّره الأب بيمن بيوسف الشاب الذي قاوم التجربة حتى النهاية وبأيوب الذي تمسك بالصبر ولم يتزعزع رجاؤه. الثبات يُتعلّم من الذين سبقونا. اذكر اليوم قصة قديس ثبت في تجربة تشبه تجربتك.\",\"p\":\"يا رب، كما ثبّت يوسف وأيوب ثبّتني في تجاربي، وامنحني رجاءً لا يتزعزع بك. آمين.\",\"x\":\"يوسف وأيوب مثالان لمن تحمل المحن والتجارب بصبر وثقة. تدريب: اقرأ جزءًا من قصة يوسف أو أيوب اليوم، وسجّل ما تعلمته.\",\"fq\":387}]},\"1-29\":{\"th\":\"الراحة في الرب\",\"m\":[{\"t\":\"ارجعي يا نفسي إلى راحتك\",\"ref\":\"المزمور ١١٤ — التاسعة\",\"v\":\"ارجعي يا نفسي إلى موضع راحتك، لأن الرب قد أحسن إلي، وأنقذ نفسي من الموت وعيني من الدموع ورجلي من الزلل، أرضي الرب أمامه في كورة الأحياء.\",\"r\":\"يدعو المرنم نفسه أن ترجع إلى موضع راحتها، لأن الرب أحسن إليه وأنقذه. راحة النفس ليست في زيادة الإنجاز بل في الرجوع إلى المحسن. خصّص اليوم عشر دقائق راحة بلا شاشات لتشكر الله على إنقاذه لك.\",\"p\":\"ارجعي يا نفسي إلى موضع راحتك لأن الرب قد أحسن إليّ. أنقذ نفسي وعيني ورجلي، وأعطني أن أسير أمامك في كورة الأحياء. آمين.\",\"x\":\"يدعو المرنم نفسه أن ترجع إلى راحتها، فهناك راحة لا تتحقق في الأنشطة بل في الله. تدريب: اختر لحظة اليوم تتوقف فيها عن الجري، وتجلس مع الله بصمت.\"},{\"t\":\"سلامًا أترك لكم\",\"ref\":\"يوحنا ١٤: ٢٧\",\"bk\":\"يوحنا\",\"v\":\"«سلاما أترك لكم. سلامي أعطيكم. ليس كما يعطي العالم أعطيكم أنا. لا تضطرب قلوبكم ولا ترهب.\",\"r\":\"العالم يعطي سلامًا مشروطًا: إذا سارت الأمور بخير. أما المسيح فيعطي سلامه وسط الضيق. هو سلام إنسان يعرف أن الله يمسك به. ولهذا يقول: لا تضطرب قلوبكم ولا ترهب. هذه وصية ووعد معًا، تُمارَس بالإيمان.\",\"p\":\"يا رب، أشكرك على سلامك الذي لا يشبه سلام العالم. احرس قلبي من الاضطراب. أعطني أن أحمل سلامك إلى بيتي وعملي وكل من ألقاه. آمين.\",\"x\":\"السلام هنا ليس شعورًا سطحيًا بل حالة عميقة تنبع من علاقة. وهو يحتاج حراسة: أن لا أسمح للأفكار المقلقة أن تحتل القلب. وفي كل قداس نسمع: «السلام لجميعكم»، فنتذكر أن السلام عطية مستمرة. ومن يسلم همّه لله يتذوق السلام حتى في أسوأ لحظاته.\\nاستقبل سلام المسيح اليوم بتنفّس هادئ: اجلس، وردد ببطء ثلاث مرات: «سلامك يا رب»، ثم أكمل يومك.\"},{\"t\":\"اطرح ضعفك أمام الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"جواب القديس أغاثون لأخ ضعيف: «اذهب واطرح ضعفك أمام الله تجد راحة». لا يطلب منه أن يصير قويًا أولًا. الراحة تأتي حين نعترف بالضعف بلا خجل. ضع اليوم أمام الله أكثر شيء يتعبك.\",\"p\":\"يا رب، أطرح أمامك ضعفي، وأطلب منك الراحة. خذ ما يتعبني وأعطني سلامك. آمين.\",\"x\":\"ضعفنا لا يمنعنا من الله بل هو الذي يقربنا إليه، فنطرحه أمامه. تدريب: اذكر لله اليوم ضعفًا معينًا، وقل: هذا ما أعجز عنه، فأعنّي.\",\"fq\":55}]},\"1-30\":{\"th\":\"عناية الله بنا\",\"m\":[{\"t\":\"الرب يحفظك\",\"ref\":\"المزمور ١٢٠ (١٢١) — الغروب\",\"v\":\"الرب يحفظك. الرب يظلل على يدك اليمنى، فلا تحرقك الشمس بالنهار ولا القمر بالليل. الرب يحفظك من كل سوء.\",\"r\":\"كرّر المرنم عبارة «الرب يحفظك» كما يردد الأب كلمة طمأنينة لابنه. عناية الله تظلّل اليد اليمنى بالنهار والليل. ما الذي يقلقك على الغد؟ اجلس اليوم وقل مرة بعد مرة: الرب يحفظني من كل سوء.\",\"p\":\"يا رب، أنت حافظي وظلي على يدي اليمنى. احفظني من كل سوء، واحفظ دخولي وخروجي من الآن وإلى الأبد. آمين.\",\"x\":\"عبارة: الرب يحفظك، تتكرر لتؤكد أن الحفظ شامل: دخولًا وخروجًا وكل حين. تدريب: اكتب لشخص تحبه رسالة قصيرة تقول فيها: الرب يحفظك.\"},{\"t\":\"أعرف الخطط\",\"ref\":\"إرميا ٢٩: ١١\",\"bk\":\"إرميا\",\"v\":\"لأني عرفت الأفكار التي أنا مفتكر بها عنكم، يقول الرب، أفكار سلام لا شر، لأعطيكم آخرة ورجاء.\",\"r\":\"هذه الآية قيلت للمسبيّين في بابل، أي لشعب يعاني ويعيش بعيدًا عن بيته. لم يقل لهم الله إن الأمر سينتهي غدًا، بل إنه يعرف خططه لهم. أحيانًا أعيش في «بابل» خاصة بي، فأحتاج أن أتذكر أن لله خطة هناك أيضًا.\",\"p\":\"يا رب، أنت تعرف الأفكار التي تفكرها نحوي، أفكار سلام لا شر. ثبّتني في رجائك حتى حين أكون في الغربة. علّمني أن أزرع وأبني حيث وضعتني. آمين.\",\"x\":\"الوعد هنا ليس بسرعة الحل بل باليقين بالنهاية. والله طلب من المسبيين أن يبنوا بيوتًا ويزرعوا ويصلوا لأجل المدينة التي سُبوا إليها. أي أن يعيشوا حياتهم بكاملها حتى في الغربة. فالإيمان لا ينتظر الخلاص ليبدأ الحياة، بل يزرع حيث وُضع.\\nاسأل نفسك: ما هي «بابل» التي أنا فيها؟ وأين يمكنني أن أزرع وأبني وأصلي فيها اليوم بدل أن أنتظر الخروج منها؟\"},{\"t\":\"إن لم يهتم الله بي\",\"ref\":\"\",\"v\":\"\",\"r\":\"سؤال الأب دانيال صادم: «إذا كان الله لا يهتم بي، لماذا أحيا؟». وهو في الحقيقة اعتراف بأن حياتنا كلها قائمة على اهتمام الله. تأمّل في الأمور التي تتوالى كل يوم دون أن تلاحظها، فهي دليل رعايته.\",\"p\":\"يا رب، شكرًا لأن عنايتك تحمل حياتي كل يوم حتى حين لا أراها. ثبّتني في الثقة بأنك تهتم بي. آمين.\",\"x\":\"سؤال الأب شبه صدمة، لكنه يكشف أن الحياة بلا عناية الله لا معنى لها. تدريب: اسأل نفسك أين رأيت عناية الله هذا الأسبوع، واكتبها.\",\"fq\":93}]},\"1-31\":{\"th\":\"ختام الشهر: شكر وتسليم\",\"m\":[{\"t\":\"نشكرك على هذا اليوم\",\"ref\":\"تحليل الغروب\",\"v\":\"نشكرك يا ملكنا المتحنن لأنك منحتنا أن نعبر هذا اليوم بسلام وأتيت بنا إلى المساء شاكرين: وجعلتنا مستحقين أن ننظر النور إلى المساء.\",\"r\":\"في ختام الشهر نقف مع الكنيسة وقت الغروب لنشكر أن عبرنا اليوم بسلام ووصلنا إلى المساء. الشكر عند نهاية اليوم يغلق صفحته بسلام. اكتب الليلة بضع كلمات عن شهر يناير تشكر الله فيها، ثم سلّم ما بقي له.\",\"p\":\"نشكرك يا ملكنا المتحنن لأنك منحتنا أن نعبر هذا اليوم بسلام. تقبّل شكرنا وسلامنا، واجعل الشهر القادم أقرب إليك. آمين.\",\"x\":\"صلاة الغروب شكر على اليوم الذي عبر، فنختم النهار بالامتنان لا بالحساب فقط. تدريب: الليلة ارجع إلى يومك وسجل ثلاث لحظات شكر قبل أي تقييم لنفسك.\"},{\"t\":\"لتكن مشيئتك\",\"ref\":\"متى ٢٦: ٣٩\",\"bk\":\"متى\",\"v\":\"ثم تقدم قليلا وخر على وجهه، وكان يصلي قائلا: «يا أبتاه، إن أمكن فلتعبر عني هذه الكأس، ولكن ليس كما أريد أنا بل كما تريد أنت».\",\"r\":\"في ليلة آلامه، لم يخفِ المسيح خوفه. قال: «إن أمكن فلتعبر عني هذه الكأس». ثم أكمل: «ولكن ليس كما أريد أنا بل كما تريد أنت». الصلاة الحقيقية لا تلغي رغباتي بل تعرضها بصدق ثم تسلّمها. هذا التسليم لا يعني ضعفًا بل أعلى درجات الثقة.\",\"p\":\"يا أبتاه، إن شئت فاجعل ما أتألم منه يعبر. ولكن ليكن لا كما أريد أنا بل كما تريد أنت. قوّني بروحك لأقبل مشيئتك بسلام وأمضي فيها بثقة. آمين.\",\"x\":\"في جثسيماني تعلّمنا أن الصلاة صراع، وأن الله لا يخيفه صراحتنا. والمسيح عرق دمًا وهو يصلي، ومع ذلك وصل إلى «لتكن مشيئتك». وقد أرسل الله ملاكًا يقوّيه، فهو لا يترك من يسلّم إرادته. وهذا التسليم ينتج قوة لمواجهة الصليب نفسه.\\nاكتب أمرًا تريده بشدة ولا تعرف إن كان من مشيئة الله، وصلِّ به بأمانة، واختم بالعبارة: «لتكن مشيئتك» بكل ما تستطيع من صدق.\"},{\"t\":\"أن يرمي الإنسان نفسه أمام الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعرّف الأب بيمن أدوات النفس بأن يرمي الإنسان نفسه أمام الله ولا يعتبر نفسه شيئًا وأن يهمل مشيئته. هذا هو التسليم الذي يليق بختام شهر: أن نضع كل ما أنجزنا أو فشلنا فيه عند قدمي الله ونمضي بسلام.\",\"p\":\"يا رب، أرمي نفسي أمامك بلا تردد. خذ ما مضى وما سيأتي، وليكن لي مشيئتك وسلامك. آمين.\",\"x\":\"أن يرمي الإنسان نفسه أمام الله في نهاية الشهر معناه أن يسلّم ما فعله وما فاته. تدريب: اختم الشهر بصلاة تسليم: ما أنجزته وما قصّرت فيه، كله بين يديك.\",\"fq\":334}]},\"2-1\":{\"th\":\"الوداعة قوة\",\"m\":[{\"t\":\"يهدي الودعاء في الحكم\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"الرب صالح ومستقيم، لذلك يرشد الذين يخطئون في الطريق. يهدى الودعاء في الحكم؛ يعلم الودعاء طرقه.\",\"r\":\"الوداعة في كلمات المرنم ليست ضعفًا، فالله نفسه يهدي الودعاء ويعلّمهم طرقه. من يملك نفسه أقوى ممن يملك الكلمة الأخيرة. جرّب اليوم أن تجيب بهدوء على كلمة تستفزك، وراقب كيف يهدئ الله ما بداخلك.\",\"p\":\"يا رب، أنت صالح ومستقيم، فأرشدني وأنا أخطئ الطريق. اهدني بوداعتك، وعلّمني طرقك التي تنتهي كلها برحمة وحق. آمين.\",\"x\":\"يؤكد المرنم أن الله يهدي الودعاء في الحكم، أي أن الوداعة تفتح باب الإرشاد. المتكبر يظن أنه يعرف، والوديع يسأل. تدريب: قبل قرارك اليوم اسأل الله بهدوء: ماذا تريد أن أفعل؟\"},{\"t\":\"روح وديعة هادئة\",\"ref\":\"بطرس الأولى ٣: ٤\",\"bk\":\"بطرس الأولى\",\"v\":\"بل إنسان القلب الخفي في العديمة الفساد، زينة الروح الوديع الهادئ، الذي هو قدام الله كثير الثمن.\",\"r\":\"نهتم كثيرًا بما يراه الناس: المظهر والصورة والانطباع. لكن الله ينظر إلى القلب. وجمال الروح الوديعة الهادئة لا يذبل بالزمن ولا يحتاج إلى تحديث. فما الذي أستثمر فيه أكثر: زينتي الخارجية أم قلبي المخفي؟\",\"p\":\"يا رب، علّمني أن أهتم بجمال قلبي أكثر من ظاهري. أعطني روحًا وديعة هادئة ثمينة أمامك. جمّل نفسي بنعمتك. آمين.\",\"x\":\"بطرس لا يمنع العناية بالمظهر، لكنه يضع الأولويات: الإنسان الخفي أهم. والروح الوديعة الهادئة تظهر في الكلام والتعامل والصبر، وتجذب الناس بدون كلام. وهي ثمينة عند الله لأنها تشبه المسيح.\\nاسأل نفسك: ما هو أكثر شيء أنفقت فيه وقتي هذا الأسبوع؟ وكم منه كان لبناء القلب؟ اختر عادة روحية تضيفها.\"},{\"t\":\"الصلاة برعم الوداعة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يربط الأب نيلوس بين الصلاة والوداعة: الصلاة برعم الوداعة وعدم الغضب. من يصلي بصدق يلين قلبه تدريجيًا. اجعل صلاتك اليوم قبل لقاء يوترك، وانظر كيف تخفّ حدّتك.\",\"p\":\"يا رب، اجعل صلاتي تُثمر في قلبي وداعةً وسلامًا. انزع غضبي، وأعطني لسانًا هادئًا في مواجهة كل ضغط. آمين.\",\"x\":\"عندما تكون الصلاة برعمًا، تكون الوداعة هي التربة التي ينمو فيها. تدريب: عند أول استفزاز اليوم، لا تجب فورًا، بل اصمت ثلاث ثوان وصلِّ قبل أن ترد.\",\"fq\":289}]},\"2-2\":{\"th\":\"بيت مبني على الرب\",\"m\":[{\"t\":\"إن لم يبنِ الرب البيت\",\"ref\":\"المزمور ١٢٦ (١٢٧) — الغروب\",\"v\":\"إن لم يبن الرب البيت فباطلا تعب البناءون، وإن لم يحرس الرب المدينة فباطلا سهر الحراس. باطل هو لكم التبكير. انهضوا من بعد جلوسكم يا آكلي الخبز بالهموم، فإنه يمنح أحباءه نوما.\",\"r\":\"كل بيت يُبنى على التعب وحده، مهما كثر السهر والتبكير، يظل ناقصًا من غير الرب. المرنم يذكّرنا أن نوم الطمأنينة هبة يمنحها الله لأحبائه. قبل أن تبدأ مشاغل بيتك اليوم، ضعها كلها في يد الرب صراحةً بصلاة قصيرة.\",\"p\":\"يا رب، ابنِ بيتي ولا تتركني أتعب باطلًا. احرس أسرتي، وامنحنا نومًا هادئًا وقلبًا مطمئنًا في رعايتك. آمين.\",\"x\":\"البيت المبني بالسهر والتبكير وحدهما يظل ناقصًا إن لم يبنه الرب. العمل مطلوب لكن الاتكال هو الأساس. تدريب: اذكر مشروعًا أو بيتًا تقوم به، وارفعه للرب قبل أن تبدأ العمل فيه.\"},{\"t\":\"أنا وبيتي نعبد الرب\",\"ref\":\"يشوع ٢٤: ١٥\",\"bk\":\"يشوع\",\"v\":\"وإن ساء في أعينكم أن تعبدوا الرب، فاختاروا لأنفسكم اليوم من تعبدون: إن كان الآلهة الذين عبدهم آباؤكم الذين في عبر النهر، وإن كان آلهة الأموريين الذين أنتم ساكنون في أرضهم. وأما أنا وبيتي فنعبد الرب».\",\"r\":\"قال يشوع للشعب: «اختاروا لأنفسكم اليوم من تعبدون». ثم أعلن موقفه بلا تردد. لا يمكن أن نعبد الله بنصف قلب ونطلب أن يكون بيتنا كله له. القرار يبدأ منّي، وأولادي وأسرتي يرون كيف أعيشه قبل أن يسمعوا ما أقوله.\",\"p\":\"يا رب، أنا أختارك إلهًا لي ولبيتي. انزع من حياتي كل ما ينافسك. اجعل بيتي مكانًا يُعبد فيه اسمك ويُشهد لك. آمين.\",\"x\":\"الاختيار هنا ليس بين الله والإلحاد فقط، بل بين الله والآلهة الصغيرة: المال والنجاح والراحة والصورة. وكل بيت له آلهته الخفية. ويشوع يدعو إلى مراجعة صريحة: من الذي أخدمه حقًا؟ وإعلان القرار أمام الأسرة يعطيه قوة، ويصنع تقليدًا يتوارثه الأبناء.\\nاكتب جملة من سطر واحد تعبّر عن اختيارك لله، وشاركها مع شخص تثق به.\"},{\"t\":\"الأساس هو القريب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّمنا الأب يوحنا الكولوفي أن البيت لا يُبنى من أعلى إلى أسفل، بل من الأساس، والأساس هو القريب الذي ينبغي أن نربحه. فبيتك الروحي لا يقوم على أعمال عظيمة فقط، بل على علاقة طيبة بمن حولك. ابدأ اليوم من أقرب شخص إليك.\",\"p\":\"يا رب، ثبّت بيتي على أساس المحبة. علّمني أن أربح قريبي أولًا، فيقوم ما أبنيه على وصاياك. آمين.\",\"x\":\"لا ينجح البناء إن بدأنا من أعلى، فالأساس هو القريب الذي نعامله كل يوم. تدريب: ابدأ اليوم بخدمة صغيرة لمن بجوارك، ثم فكر في الخدمات الكبيرة.\",\"fq\":165}]},\"2-3\":{\"th\":\"التلمذة والنمو\",\"m\":[{\"t\":\"وباسم إلهنا ننمو\",\"ref\":\"المزمور ١٩ (٢٠) — الثالثة\",\"v\":\"وباسم إلهنا ننمو. يكمل الرب كل سؤالك. الآن علمت أن الرب قد خلص مسيحه؛ واستجاب له من سماء قدسه بجبروت خلاص يمينه.\",\"r\":\"النمو في الحياة الروحية ليس عملية سريعة، لكنه يحدث «باسم إلهنا»، أي بقوته وحضوره. المرنم يعلن أن الرب يكمل كل سؤال. اسأل نفسك: في أي جانب من حياتي أريد أن أنمو هذا الشهر؟ وارفعه إلى الله بصلاة محددة.\",\"p\":\"يا رب، باسمك ننمو، فأكمل كل سؤال قلبي. استجب لي من سماء قدسك، وانمِ فيّ ما غرسته بنعمتك. آمين.\",\"x\":\"النمو الروحي بطيء لكنه ثابت إذا تم باسم إلهنا. لا نقارن أنفسنا بغيرنا بل بالأمس. تدريب: اكتب شيئًا واحدًا نموت فيه عن العام الماضي في صلاتك أو سلوكك، واشكر الله عليه.\"},{\"t\":\"قدّام قدمي المعلم\",\"ref\":\"لوقا ١٠: ٣٩\",\"bk\":\"لوقا\",\"v\":\"وكانت لهذه أخت تدعى مريم، التي جلست عند قدمي يسوع وكانت تسمع كلامه.\",\"r\":\"كانت مرثا مشغولة بالخدمة، ومريم جالسة عند قدمي يسوع. ومرثا اشتكت، فأجابها المسيح بلطف: «أنتِ تهتمين بأمور كثيرة، ولكن الحاجة إلى واحد». لا يلوم الخدمة، لكنه يضع الأولويات: أن أجلس أولًا، ثم أخدم من الامتلاء.\",\"p\":\"يا رب، علّمني أن أجلس عند قدميك قبل أن أخدم. اغفر لي انشغالي بالكثير. أعطني النصيب الصالح الذي لا ينزع مني. آمين.\",\"x\":\"الانشغال بالخدمة قد يصير هروبًا من الجلوس مع الله. ومن يخدم بدون صلاة يجف ويتذمر كمرثا. والحاجة الواحدة هي الحضور في محضره. ومنها تنبع كل خدمة صحيحة. ولهذا قال إن مريم اختارت النصيب الصالح الذي لا يُنزع.\\nقبل أن تبدأ مهام يومك، اجلس عشر دقائق عند قدمي المسيح بالإنجيل، ثم ابدأ عملك من هذا المكان.\"},{\"t\":\"من الصباح حتى المساء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ألونيوس إن الإنسان إذا أراد يستطيع أن يصل إلى القامة الإلهية من الصباح حتى المساء. هذه الجملة تحمل تحديًا ورجاءً: ليس النمو حكرًا على الزمن الطويل، فاليوم الواحد قد يغيّرنا حين نقرر. ما قرارك الواحد اليوم؟\",\"p\":\"يا رب، أعطني إرادةً جادة وقوة في يومي هذا. ليكن لي نمو حقيقي من الصباح حتى المساء بنعمتك. آمين.\",\"x\":\"الأب يعلّمنا أن الوصول للقامة المرجوة ممكن بالمثابرة من الصباح حتى المساء. تدريب: حدد لنفسك اليوم عملًا روحيًا واحدًا بلا انقطاع، وثبّت عليه حتى المساء.\",\"fq\":74}]},\"2-4\":{\"th\":\"الشجاعة بالرب\",\"m\":[{\"t\":\"إن يحاربني جيش\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"إن يحاربني جيش فلن يخاف قلبي. وإن قام على قتال ففي هذا أنا أطمئن.\",\"r\":\"الشجاعة عند المرنم ليست أن تغيب الحرب، بل ألا يخاف القلب وسطها لأن الرب نوره وحصنه. اكتب الآن أكثر ما يقلقك، وقل أمام الله: إن حاربني هذا فلن يخاف قلبي، لأنك معي. ثم ابدأ يومك.\",\"p\":\"يا رب، أنت نوري وخلاصي وحصن حياتي، فممن أخاف؟ إن حاربني جيش فلن يخاف قلبي، ففي هذا أنا مطمئن بك. آمين.\",\"x\":\"الشجاعة هنا ليست غياب الحرب بل ثبات القلب وسطها، لأن الرب نوري وخلاصي. تدريب: اذكر خوفًا يشغلك، وأنشد المزمور السادس والعشرين مرة، وقل: الرب نوري فمن أخاف؟\"},{\"t\":\"داود وجليات\",\"ref\":\"صموئيل الأول ١٧: ٤٥\",\"bk\":\"صموئيل الأول\",\"v\":\"فقال داود للفلسطيني: «أنت تأتي إلي بسيف وبرمح وبترس، وأنا آتي إليك باسم رب الجنود إله صفوف إسرائيل الذين عيرتهم.\",\"r\":\"أمام جليات، لم يكن لداود سيف ولا درع. كان معه اسم الرب وخبرة سابقة مع الله في مواجهة الأسد والدب. وهذا درس: الإيمان يتغذى بالذكريات. من تذكّر كيف أنقذه الله سابقًا واجه التحدي الحالي بثقة.\",\"p\":\"يا رب القوات، أنا أواجه جبابرة لا أقوى عليهم. أذكّرني بما فعلته معي في الماضي. اجعل المعركة لك، وأنا أسير باسمك. آمين.\",\"x\":\"جليات يرمز إلى كل تحدٍّ يبدو أكبر مني: ضغط عمل أو مرض أو عادة. وداود لم يتجاهل ضخامة العدو، لكنه رأى أن المعركة للرب. وأيضًا رفض درع شاول، أي أن لا أحاول مواجهة التحدي بطريقة غيري، بل بما أتقنه مع الله.\\nاذكر موقفًا سابقًا أنقذك فيه الله، وسجله في سطرين، وارجع إليه حين يضعف إيمانك.\"},{\"t\":\"أحبه فلا أخافه\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أنطونيوس: «أنا لا أخاف الله أبدًا إنما أحبه، لأن المحبة تطرد الخوف خارجًا». حين نحب الله، يتحول الخوف من العقاب إلى شوق للقاء. اسأل نفسك هل تقف أمام الله اليوم بخوف المذنب أم بمحبة الابن؟\",\"p\":\"يا رب، علّمني أن أحبك فيطرد حبك الخوف من قلبي. وكن شجاعتي في كل يوم أواجه فيه ما يخيفني. آمين.\",\"x\":\"من أحب الله لا يخافه خوف العبد بل يحترمه محبةً، والمحبة تطرد الخوف. تدريب: بدّل صلاة الطلب اليوم بصلاة محبة: قل لله كم تحبه بدلًا من أن تطلب منه.\",\"fq\":17}]},\"2-5\":{\"th\":\"الرجاء في الضعف\",\"m\":[{\"t\":\"ارحمني فإني ضعيف\",\"ref\":\"المزمور السادس — باكر\",\"v\":\"ارحمني يا رب فإني ضعيف. اشفني يا رب فإن عظامي قد اضطربت ونفسي قد انزعجت جدا.\",\"r\":\"يعترف المرنم بضعفه بلا مواربة: ارحمني فإني ضعيف، اشفني فعظامي اضطربت. هذه ليست نهاية الرجاء بل بدايته، فالضعف المعترف به هو الباب الذي تدخل منه القوة الإلهية. لا تخفِ ضعفك اليوم عن الله، فهو يعرفه ويحب أن تقوله له.\",\"p\":\"ارحمني يا رب فإني ضعيف، واشفني فإن عظامي قد اضطربت ونفسي انزعجت جدًا. أعنّي بقوتك التي تكمل في الضعف. آمين.\",\"x\":\"يبدأ المرنم بالاعتراف بضعفه، وهذا هو باب الشفاء. من يخفي ضعفه لا يستفيد من الطبيب. تدريب: قل لله اليوم بصدق: أنا ضعيف في هذا الأمر، فاشفني.\"},{\"t\":\"القصبة المرضوضة\",\"ref\":\"إشعياء ٤٢: ٣\",\"bk\":\"إشعياء\",\"v\":\"قصبة مرضوضة لا يقصف، وفتيلة خامدة لا يطفئ. إلى الأمان يخرج الحق.\",\"r\":\"القصبة المرضوضة كادت تنكسر، والفتيلة المدخنة كادت تنطفئ. وأحيانًا أكون كذلك: مجروحًا ومتعبًا وطاقتي الروحية خافتة. والخبر السار أن المسيح لا يكسر ولا يطفئ، بل يصبر ويعالج. فلا أخجل من حالتي أمامه.\",\"p\":\"يا رب يسوع، أشكرك لأنك لا تكسر القصبة المرضوضة. أعطني أن أثق برفقك حين أضعف. واجعلني رفيقًا بالضعفاء من حولي. آمين.\",\"x\":\"في عالم يتخلص من الضعيف ويستبدله، يتعامل المسيح برفق. والآباء يرون هنا وعدًا للتائبين الذين يشعرون بأن إيمانهم قد انطفأ: النار لم تنتهِ بعد، وهو ينفخ فيها لتتقد. ومتى أدرك هذا، أستطيع أن أتعامل مع ضعف غيري بنفس الرفق.\\nاسأل نفسك: من هي القصبة المرضوضة حولي؟ قدّم لها اليوم كلمة رفق أو اتصالًا مشجعًا.\"},{\"t\":\"ابدأ من جديد\",\"ref\":\"\",\"v\":\"\",\"r\":\"صلّى القديس أرسانيوس حين اقتربت الشياطين من صومعته: «لا تتركني لوحدي لأني لم أعمل الصلاح أمامك، لكن بصلاحك أعطني أن أبدأ من جديد». الرجاء في الضعف أن أبدأ من جديد بنعمته كل مرة. فابدأ من حيث أنت.\",\"p\":\"يا إلهي، لا تتركني وحدي، فأنا لم أعمل الصلاح أمامك. بصلاحك ومحبتك أعطني أن أبدأ من جديد. آمين.\",\"x\":\"حين اقتربت الشياطين صلّى الأب أن يبدأ من جديد، فالبداية الجديدة دائمًا ممكنة. تدريب: أخطأت أمس؟ ابدأ اليوم نظيفًا، واقصر صلاتك على كلمة: أعنّي.\",\"fq\":25}]},\"2-6\":{\"th\":\"القلب النقي\",\"m\":[{\"t\":\"نقِّ قلبي وكليتي\",\"ref\":\"المزمور ٢٥ (٢٦) — الثالثة\",\"v\":\"اختبرني يا رب وجربنى، نق قلبي وكليتي. لأن رحمتك أمام عيني، وقد ارتضيت بحقك.\",\"r\":\"يطلب المرنم أن يختبره الله وينقي قلبه، لأنه واثق أن رحمة الله أمام عينيه. النقاء ليس نتيجة جهدنا وحده، بل نعمة نطلبها ثم نتعاون معها. اطلب اليوم من الله أن يكشف لك فكرة واحدة تلوّث قلبك، وسلّمها له.\",\"p\":\"اختبرني يا رب وجرّبني، ونقِّ قلبي وكليتي. لتكن رحمتك أمام عيني، وليكن حقك طريقي في كل خطوة. آمين.\",\"x\":\"يطلب المرنم أن يفحصه الله ويختبره، فالقلب النقي لا يخاف النظر الإلهي. وتنتهي مزامير الغروب بهذه الروح. تدريب: اسأل الله الليلة: هل في قلبي ما تريد أن ينقى؟ وأصغِ.\"},{\"t\":\"احفظ قلبك\",\"ref\":\"الأمثال ٤: ٢٣\",\"bk\":\"الأمثال\",\"v\":\"فوق كل تحفظ احفظ قلبك، لأن منه مخارج الحياة.\",\"r\":\"كل ما أفعله يبدأ من فكرة، وكل فكرة تبدأ من قلب. ولهذا يقول الحكيم: احفظ قلبك أكثر من كل تحفظ. فمن يحرس الحدود الخارجية ويترك المنبع مفتوحًا، سيتلوث ماؤه. والحراسة تبدأ بالانتباه لما أسمح بدخوله من أفكار وصور وأحاديث.\",\"p\":\"يا رب، احرس قلبي لأن منه مخارج الحياة. ساعدني أن أنتبه لأفكاري وأن أطردها بصلاتك. ملّأ ذهني بما هو حق وطاهر وجميل. آمين.\",\"x\":\"آباء البرية سمّوا هذا «حراسة الأفكار»: أن نلاحظ الفكرة حين تأتي ولا نتركها تستوطن. فالفكرة الأولى ليست خطية، لكن التمادي فيها يتحول إلى رغبة ثم فعل. والحل الصلاة القصيرة والانشغال بالنافع، وأن نعترف بما يزعجنا.\\nاختر مصدرًا واحدًا يملأ ذهنك بما لا ينفع (مشاهدة أو تصفح)، وقلل منه هذا الأسبوع، ثم استبدله بشيء يبني.\"},{\"t\":\"الصحو يمنع الدنس\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب بيمن أنه إذا تجاوزنا ما هو عملي وثابرنا على الصحو بنشاط لن يكون في داخلنا دنس. القلب النقي لا يُصنع بالتمنّي، بل بالانتباه المستمر. اختر ساعة اليوم لتراقب فيها أفكارك دون أن تحكم عليها، ثم صلِّ.\",\"p\":\"يا رب، اجعلني صاحيًا في ذهني وقلبي، ونقّني من كل دنس بنعمتك. علّمني أن أثابر على اليقظة بنشاط. آمين.\",\"x\":\"الصحو والانتباه يمنعان دخول الدنس، لأن الفكر يُصد قبل أن يتحول إلى فعل. تدريب: أوقف فكرًا واحدًا اليوم عند بدايته، قبل أن تتابعه.\",\"fq\":437}]},\"2-7\":{\"th\":\"شريك الله في العمل\",\"m\":[{\"t\":\"هوذا الله عوني\",\"ref\":\"المزمور ٥٣ (٥٤) — السادسة\",\"v\":\"هوذا الله عوني، والرب ناصر نفسي، يرد الشرور على أعدائي، بحقك استأصلهم. فأذبح لك طائعا، وأعترف لاسمك يا رب فإنه صالح.\",\"r\":\"الشراكة مع الله تبدأ من إقرار بسيط: هوذا الله عوني. لا أعمل وحدي، ولا أخدم لحساب نفسي. وحين أذبح له طائعًا، أقدّم عملي تقدمة. قبل أن تبدأ عمل اليوم، قل: هذا العمل لك يا رب، وبمعونتك أنجزه.\",\"p\":\"هوذا الله عوني والرب ناصر نفسي. أقدّم لك عملي طائعًا، وأعترف لاسمك لأنه صالح، فقد نجيتني من الشدائد. آمين.\",\"x\":\"«هوذا الله عوني» اعتراف أن الله شريك في كل ما أعمله. فلا أحمل ثقلًا وحدي. تدريب: قبل أن تبدأ مهمة اليوم الأصعب، ارفع يدك وقل: هوذا الله عوني.\"},{\"t\":\"الكرمة والأغصان\",\"ref\":\"يوحنا ١٥: ٥\",\"bk\":\"يوحنا\",\"v\":\"أنا الكرمة وأنتم الأغصان. الذي يثبت في وأنا فيه هذا يأتي بثمر كثير، لأنكم بدوني لا تقدرون أن تفعلوا شيئا.\",\"r\":\"الغصن لا يجهد ليثمر، بل يثبت في الكرمة فتمر فيه الحياة. وهذا درس عميق: أن ثمر حياتي ليس نتيجة إجهاد بل نتيجة اتصال. وإن كنت أشعر بجفاف روحي، ربما أحتاج أن أراجع اتصالي بالكرمة: كيف صلاتي وأسراري وكلمة الله؟\",\"p\":\"يا رب يسوع، أنت الكرمة وأنا الغصن. ثبتني فيك فأثمر ثمرًا يبقى. قلّم ما يعطّلني، وأعطني حياتك تجري فيّ. آمين.\",\"x\":\"المسيح يتحدث عن تنقية الأغصان لتأتي بثمر أكثر. فالله يقلّم بعض الأشياء من حياتنا، لا ليؤلمنا بل ليزيد ثمرنا. والثبات ليس حالة سلبية بل علاقة حية مستمرة. ومن ثبت فيه أتى بثمر كثير: محبة وفرح وسلام وطول أناة.\\nخصص اليوم وقتًا للثبات في المسيح: اقرأ إصحاحًا من الإنجيل وتأمل في الآية: «بدوني لا تقدرون أن تفعلوا شيئًا».\"},{\"t\":\"أشتغل مع المسيح\",\"ref\":\"\",\"v\":\"\",\"r\":\"كان الأب أبو للوس يقول بفرح كلما قصده الناس في طلب خدمة: «اليوم سأشتغل مع المسيح من أجل نفسي، لأن هذا هو أجرها». الخدمة تتحول إلى شراكة حين أراه شريكي. حين يطلب منك أحد خدمة اليوم، تذكّر هذه العبارة.\",\"p\":\"أيها المسيح، اجعلني أشتغل معك في كل خدمة. علّمني أن أرى طلبات الناس فرصًا للقاء بك وللنمو في المحبة. آمين.\",\"x\":\"الأب كان يقول بفرح إنه يشتغل مع المسيح، فالخدمة معه خفيفة. تدريب: اطلب اليوم من المسيح أن يشاركك في ما تعمله، وانظر كيف يتغير مزاجك فيه.\",\"fq\":75}]},\"2-8\":{\"th\":\"الإصغاء إلى الآخرين\",\"m\":[{\"t\":\"هلمّ أيها البنون استمعوا\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"هلم أيها البنون استمعوا لي. فأعلمكم مخافة الرب.\",\"r\":\"الدعوة إلى الاستماع تسبق التعليم: «هلم استمعوا لي فأعلمكم». كثيرًا ما نكون متحدثين في محضر من يحتاج أن يُصغى إليه. اطلب اليوم أن تستمع كاملًا لشخص واحد دون أن تقاطعه أو تجهّز ردك.\",\"p\":\"يا رب، علّمني أن أُصغي كما تُصغي إليّ. أعطني أذنًا مفتوحة، وقلبًا هادئًا، وحكمة أن أسمع قبل أن أجيب. آمين.\",\"x\":\"الاستماع يسبق التعليم، فالمتعلم الحقيقي يصمت أولًا. تدريب: في أول حديث اليوم، اطلب من محدثك أن يكمل ما يقوله، وانتظر حتى ينتهي بلا مقاطعة.\"},{\"t\":\"سريعًا في الاستماع\",\"ref\":\"يعقوب ١: ١٩\",\"bk\":\"يعقوب\",\"v\":\"إذا يا إخوتي الأحباء، ليكن كل إنسان مسرعا في الاستماع، مبطئا في التكلم، مبطئا في الغضب،\",\"r\":\"نحب أن نتكلم لنُسمَع، لكن يعقوب يقلب الترتيب: سريعًا في الاستماع، بطيئًا في التكلم، بطيئًا في الغضب. الاستماع الحقيقي أن أسمع لأفهم لا لأرد. وحين أعطي إنسانًا انتباهي الكامل، أقول له بدون كلمات: أنت مهم عندي.\",\"p\":\"يا رب، اجعلني سريعًا في الاستماع بطيئًا في الكلام. أعطني صبرًا أسمع به إخوتي. وعلّمني أن أسمع صوتك أيضًا. آمين.\",\"x\":\"كثير من المشكلات تُحل حين يشعر الناس أنهم مسموعون. الاستماع يخفف التوتر ويكشف الحقيقة ويعطي حكمة في الرد. وهو أيضًا تدريب لسماع صوت الله: من لا يعرف أن يسمع الناس يصعب عليه أن يسمع الله.\\nفي حديثك التالي اليوم، جرّب ألا تقاطع، وأعد ما فهمته بجملة قبل أن تجيب، وانتبه كيف يتغير الحديث.\"},{\"t\":\"لا تجب قبل أن تسمع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب بيمن أن من يجيب بكلمة قبل أن يسمع يعمل بجهل، وأن علينا أن نجيب إذا سُئلنا وإلا نصمت. الإصغاء احترام لصورة الله في الآخر. راقب اليوم رغبتك في المقاطعة وامتنع عنها مرة واحدة على الأقل.\",\"p\":\"يا رب، أبعد عني الجهل الذي يتسرع. علّمني الصمت المحب والكلمة في وقتها، لأحترم كل إنسان تجعله في طريقي. آمين.\",\"x\":\"الجواب قبل السماع جهل، فالحكمة تبدأ بالإنصات. تدريب: اختر اليوم شخصًا يتكلم كثيرًا، واستمع إليه بصبر كأنه رسالة من الله.\",\"fq\":344}]},\"2-9\":{\"th\":\"قدوس هو الرب\",\"m\":[{\"t\":\"الجلال والبهاء قدامه\",\"ref\":\"المزمور ٩٥ (٩٦) — التاسعة\",\"v\":\"الجلال والبهاء قدامه؛ الطهر والجمال العظيم في قدسه. قدموا للرب يا جميع قبائل الأمم؛ قدموا للرب مجدا وكرامة؛ قدموا للرب مجدا لاسمه.\",\"r\":\"القداسة في الكتاب ليست كمالًا بشريًا بل حضور الله الذي يملأ المكان جلالًا وطهرًا. وحين ندخل إلى هذا الحضور نتغير. قبل أن تبدأ صلاتك اليوم، قف لحظة صامتًا كمن يدخل مكانًا مقدسًا، ثم ابدأ.\",\"p\":\"يا رب، الجلال والبهاء قدامك والطهر في قدسك. أقدّم لك مجدًا وكرامة، واجعل قلبي موضعًا لحضورك. آمين.\",\"x\":\"القداسة حضور الله الذي يملأ المكان، وكل من يقف أمامه يخشع. تدريب: ادخل غرفتك اليوم وقف دقيقة بصمت كأنك في مقدس الله، ثم صلِّ.\"},{\"t\":\"قدوس قدوس قدوس\",\"ref\":\"إشعياء ٦: ٣\",\"bk\":\"إشعياء\",\"v\":\"وهذا نادى ذاك وقال: «قدوس، قدوس، قدوس رب الجنود. مجده ملء كل الأرض».\",\"r\":\"رأى إشعياء الرب جالسًا على كرسي عالٍ، فلم يتفاخر بل صرخ: «ويل لي، إني هلكت». اللقاء مع القداسة يكشف الحقيقة. لكن الله لم يتركه في اليأس: أرسل سيرافًا بجمرة تطهّر شفتيه. ثم سمع النداء: من أرسل؟ فقال: هأنذا.\",\"p\":\"قدوس قدوس قدوس رب الجنود، السماوات والأرض مملوءتان من مجدك. طهّر شفتيّ وقلبي، وأرسلني حيثما تشاء. هأنذا فأرسلني. آمين.\",\"x\":\"هكذا يحدث في القداس: نسمع «قدوس قدوس قدوس»، ونعترف بضعفنا، ونتناول الجمرة، فنذهب مرسلين. هذه حركة كل عبادة صحيحة. والتطهير لا يأتي من قدرة النبي بل من مبادرة الله. وبعد التطهير يصبح الإنسان مستعدًا لتلبية الدعوة.\\nاليوم قل لله بصدق: «هأنذا فأرسلني». اطلب أن يريك أين يرسلك: في بيتك أو عملك أو كنيستك.\"},{\"t\":\"خوف الله كالمصباح\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب يعقوب خوف الله بمصباح يضيء غرفة النوم المظلمة، فينير القلب ويعلّمه كل الفضائل. القداسة تبدأ إذًا من إضاءة داخلية. أي ركن مظلم في داخلك تحتاج أن يضيئه هذا المصباح اليوم؟\",\"p\":\"يا رب، أدخل خوفك الطاهر قلبي، كالمصباح الذي ينير. علّمني بنوره الفضائل والوصايا التي تقدّسني. آمين.\",\"x\":\"مخافة الله مصباح في الغرفة المظلمة، تُري الإنسان ما لم يره. تدريب: قبل أن تفعل أمرًا مشكوكًا فيه اليوم، اسأل: هل يرضي هذا الله؟\",\"fq\":189}]},\"2-10\":{\"th\":\"ذبيحة التسبيح\",\"m\":[{\"t\":\"ذبيحة التسبيح\",\"ref\":\"المزمور ١١٥ — التاسعة\",\"v\":\"فلك أذبح ذبيحة التسبيح، وباسم الرب أدعو.\",\"r\":\"يعد المرنم بذبيحة لا ثمن مادي لها: ذبيحة التسبيح. وما أبسطها وما أعمقها! تسبيح في وقت الضيق أثمن من تسبيح في وقت الراحة. اختر اليوم لحظة صعبة وسبّح فيها بكلمة واحدة، مثل: المجد لك يا رب.\",\"p\":\"لك أذبح ذبيحة التسبيح وباسم الرب أدعو. اقبل شفتيّ تقدمة، وارفع بها قلبي إليك في كل ظرف. آمين.\",\"x\":\"ذبيحة التسبيح لا تكلف مالًا بل شفتين وقلبًا. وتبدأ الأجبية دائمًا بتسبحة. تدريب: سبّح الله اليوم بمزمور تعرفه أو ترنيمة تحبها، حتى وأنت تعمل.\"},{\"t\":\"بولس وسيلا في السجن\",\"ref\":\"أعمال الرسل ١٦: ٢٥\",\"bk\":\"أعمال الرسل\",\"v\":\"ونحو نصف الليل كان بولس وسيلا يصليان ويسبحان الله، والمسجونون يسمعونهما.\",\"r\":\"جُلدا وقيّدت أرجلهما في المقطرة، ومع ذلك سبّحا الله في منتصف الليل. والمساجين كانوا يسمعونهما. لم يكن التسبيح حيلة لتغيير الظروف، بل تعبيرًا عن إيمانهما. وحين حدث الزلزال لم يهربا، فكانت شهادتهما أقوى، وخلص السجان وبيته.\",\"p\":\"يا رب، علّمني أن أسبحك في منتصف ليلي. اجعل ضيقي شهادة لمن يراقبني. افتح أبواب القلوب كما فتحت أبواب السجن. آمين.\",\"x\":\"من المدهش أنهما بقيا بعد فتح الأبواب. لو هربا لخسرا السجان. ويذكّرنا هذا بأن غاية الألم قد تكون خدمة لآخر لا نعرفه. وسؤال السجان: «ماذا ينبغي أن أفعل لكي أخلص؟» يكشف أن التسبيح كان عظة صامتة بلغ صداها قلبه.\\nاسأل نفسك: من يراقبني وأنا أتألم؟ اجعل رد فعلك في الضيق شهادة، ولو بكلمة شكر وحيدة.\"},{\"t\":\"ترتيل بلا تشتت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إفاغريوس إن عظيم أن يصلّي المرء بدون شرود، لكن الأعظم أن يرتل بدون تشتت. التسبيح يحتاج انتباهًا أكثر لأنه يمرّ بالفم والقلب معًا. رتل اليوم مزمورًا أو ترنيمة واحدة بتمهل وانتباه.\",\"p\":\"يا رب، علّمني أن أرتل بقلب مجتمع غير مشتت. اجعل تسبيحي ذبيحة مقبولة أمامك وقوةً لي في كل يوم. آمين.\",\"x\":\"الصلاة بلا شرود هدف، لكن الأهم أن نصلي رغم الشرود. تدريب: إن شردت أثناء الصلاة اليوم، عد بهدوء ولا تلم نفسك، وكرر ذلك بلا يأس.\",\"fq\":110}]},\"2-11\":{\"th\":\"الجهاد الروحي\",\"m\":[{\"t\":\"قمنا وانتصبنا\",\"ref\":\"المزمور ١٩ (٢٠) — الثالثة\",\"v\":\"ونحن باسم الرب إلهنا ننمو. هم عثروا وسقطوا، ونحن قمنا وانتصبنا. يا رب خلص ملكك واستجب لنا يوم ندعوك.\",\"r\":\"يرى المرنم الفرق بين من يتكلون على مركبات وخيل ومن يتكلون على الله: أولئك عثروا وسقطوا ونحن قمنا وانتصبنا. الجهاد الروحي ليس بقدراتنا بل بالاعتماد على اسمه. حدّد اليوم معركة صغيرة، وادخلها وأنت تقول: باسم الرب إلهنا.\",\"p\":\"يا رب، خلّص ملكك واستجب لنا يوم ندعوك. باسمك ننمو وبك نقوم وننتصب، فكن قوتنا في الجهاد. آمين.\",\"x\":\"يقول المرنم إن البعض يعتمدون على المركبات والخيل، أما نحن فباسم الرب. الاتكال على الله قرار يومي. تدريب: ما الذي تتكل عليه غير الله هذا الأسبوع؟ أخرجه من مكانه في قلبك.\"},{\"t\":\"الجري في الميدان\",\"ref\":\"كورنثوس الأولى ٩: ٢٤\",\"bk\":\"كورنثوس الأولى\",\"v\":\"ألستم تعلمون أن الذين يركضون في الميدان جميعهم يركضون، ولكن واحدا يأخذ الجعالة؟ هكذا اركضوا لكي تنالوا.\",\"r\":\"صاحب السباق يخفف حمله ويثبت نظره على خط النهاية. والرسول يطلب منا أن نطرح «كل ثقل والخطية المحيطة بنا بسهولة». أحيانًا ما يعطلني ليس خطية كبيرة بل أثقال لا لزوم لها: التزامات، أو مقارنات، أو أحقاد. وقبل أن أجري، أحتاج أن أخلع.\",\"p\":\"يا رب يسوع، مبدئ إيماني ومكمله، أنظر إليك فلا أفتر. أطرح عني كل ثقل وكل خطية تعثرني. اجعلني أجري بصبر في الميدان الذي وضعتني فيه. آمين.\",\"x\":\"الكاتب لا يطلب أن نركض بقوتنا بل أن نعتمد على «سحابة من الشهود» وعلى يسوع نفسه. وحين يتعب الجاري ينظر إلى من نجح قبله. والتلمذة ليست جريًا منفردًا، بل شركة مع قديسين سبقونا ويصلون عنا. وعلينا ألا نملّ فنخور.\\nاكتب ثقلًا واحدًا يعطلك روحيًا، وخذ قرارًا باتخاذ خطوة لتركه هذا الأسبوع، ثم اطلب شفاعة قديس تحبه.\"},{\"t\":\"أن يغصب نفسه في كل شيء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يسأل الأب مكاريوس عن عمل الراهب، فيجيب الأب زخريا: من غصب نفسه في كل شيء. ليس الجهاد حدثًا كبيرًا بل هو غصب النفس في أمور كثيرة صغيرة. اختر اليوم أمرًا واحدًا تغصب فيه نفسك على الخير.\",\"p\":\"يا رب، أعطني أن أغصب نفسي على الخير في الصغير والكبير. وقوّني بنعمتك حتى أنتصر في جهادي اليومي. آمين.\",\"x\":\"من غصب نفسه على الخير في كل شيء، كبر في الروح. تدريب: اختر اليوم أمرًا ثقيلًا على نفسك تفعله لله، مثل اتصال أو اعتذار.\",\"fq\":117}]},\"2-12\":{\"th\":\"العطش إلى الله\",\"m\":[{\"t\":\"رحمتك أفضل من الحياة\",\"ref\":\"المزمور ٦٣ — باكر\",\"v\":\"هكذا ظهرت لك في القدس. لأرى قوتك ومجدك. لأن رحمتك أفضل من الحياة. شفتاي تسبحانك.\",\"r\":\"يتجه عطش المرنم إلى رؤية قوة الله ومجده في القدس، ويقرّ أن رحمته أفضل من الحياة نفسها. حين أضع الله في المقام الأول يصير العطش دليل حياة لا نقصًا. اسأل نفسك اليوم: ما الذي أعطشه أكثر من الله؟\",\"p\":\"يا رب، لأرى قوتك ومجدك في قدسك. رحمتك أفضل عندي من الحياة، فلتسبّحك شفتاي كل أيامي. آمين.\",\"x\":\"رحمة الله أفضل من الحياة لأنها تعطي الحياة معنى. والمرنم يعطش لرؤية مجده في القدس. تدريب: ادخل الكنيسة اليوم أو تخيّلها، وقف دقيقة تشكر الله على رحمته.\"},{\"t\":\"طوبى للجياع\",\"ref\":\"متى ٥: ٦\",\"bk\":\"متى\",\"v\":\"طوبى للجياع والعطاش إلى البر، لأنهم يشبعون.\",\"r\":\"قد نجوع إلى أشياء كثيرة: نجاح، أو تقدير، أو راحة. لكن المسيح يمدح من يجوع إلى البر، أي إلى أن يكون على الاستقامة أمام الله. وحين يكون هذا هو جوعي الأكبر، يعدني الله بالشبع. لا يعد بإشباع الأشياء الأخرى، لكنه يعد بما هو أهم.\",\"p\":\"يا رب، اجعلني أجوع وأعطش إلى البر. أشبعني من كلمتك وروحك، ولا تدعني أكتفي بما هو أدنى. أعطني شهية روحية صحيحة. آمين.\",\"x\":\"الجوع إلى البر ليس رغبة سلبية بل شهية روحية تدفع إلى الطلب والعمل. والبر هنا يشمل أن أكون صالحًا في ذاتي وأن أرى العدل في العالم. والله يشبع الاثنين: يحوّلني ويستخدمني. ومن لا يشتهي البر قد فقد شهيته الروحية فيحتاج إلى علاج.\\nاكتب مجالًا واحدًا في حياتك تشعر فيه بجوع إلى البر، وصلّ طالبًا من الله قوة للتغيير.\"},{\"t\":\"أطلب الله ولا تسأل عن مكانه\",\"ref\":\"\",\"v\":\"\",\"r\":\"وصية الأب سيسوى مختصرة: «أطلب الله ولا تسأل عن مكان سكناه». أي لا تشغل نفسك بتفاصيل الوسائل وابدأ بالطلب نفسه. العطش الحقيقي لا ينتظر المكان المثالي. ابدأ بالطلب الآن حيث أنت.\",\"p\":\"يا رب، أطلبك في مكاني هذا وزماني. علّمني ألا أؤجل لقاءك حتى تكتمل الظروف، وأن أعطش إليك أكثر كل يوم. آمين.\",\"x\":\"يطلب الأب الله لا مكانه، فالله ليس محصورًا في موضع. تدريب: ابحث عن الله اليوم في موقف عادي، مثل زحام أو عمل، وقل: أنت هنا.\",\"fq\":503}]},\"2-13\":{\"th\":\"الحرية في المسيح\",\"m\":[{\"t\":\"أخرجني إلى الرحب\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"فاستجاب لي وأخرجني إلى الرحب. الرب عوني فلا أخشى ماذا يصنع بي الإنسان.\",\"r\":\"الحرية عند المرنم خروج من الضيق إلى الرحب، وهي ثمرة صراخ إلى الرب واستجابته. وهي تأتي بثقة: الرب عوني فلا أخشى. ما الذي يضيّق صدرك اليوم؟ اطرحه أمام الله بصراحة واطلب رحبًا جديدًا.\",\"p\":\"في ضيقتي صرخت إليك يا رب، فاستجبتَ لي وأخرجتني إلى الرحب. أنت عوني فلا أخشى ماذا يصنع بي الإنسان. آمين.\",\"x\":\"الرحب نقيض الضيق، والله هو الذي ينقلنا من الأول إلى الثاني. تدريب: في ضيقك اصرخ إلى الله بكلمة واحدة، وانتظر رحبه بصبر.\"},{\"t\":\"تعرفون الحق والحق يحرركم\",\"ref\":\"يوحنا ٨: ٣١–٣٢\",\"bk\":\"يوحنا\",\"v\":\"فقال يسوع لليهود الذين آمنوا به: «إنكم إن ثبتم في كلامي فبالحقيقة تكونون تلاميذي، وتعرفون الحق، والحق يحرركم».\",\"r\":\"الحرية هنا تأتي من معرفة الحق، وليس أي حق بل الحق الذي هو المسيح نفسه. وهذا يبدأ بالثبات في كلمته. فمن لا يثبت في الكلمة لا يعرف الحق، ومن لا يعرف الحق لا يتحرر. والعبودية ليست بالضرورة جسدية، فقد أكون عبدًا لعادة أو فكرة.\",\"p\":\"يا رب، أعترف أني كنت عبدًا لـ(ما أخفيه). يا من يحرر الأسرى، أعتقني بحقك. ثبتني في كلمتك لأعرف الحق فيحررني. آمين.\",\"x\":\"اليهود قالوا للمسيح: «لم نُستعبد لأحد قط»، وهذا إنكار يمنع الشفاء. وأول خطوة في التحرر أن أعترف بقيدي. ثم أطلب من الابن أن يعتقني، فهو وحده القادر. وكل من يسلم نفسه لخطية يتحول إلى عبد لها.\\nاعترف بنقطة ضعف أمام الله وأمام أب اعترافك، فالاعتراف باب التحرر الأول.\"},{\"t\":\"تحرر من الاهتمامات\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أفربيوس إننا إذا فقدنا شيئًا، فعلينا أن نقبل هذا بفرح وحمد لأننا انعتقنا من بعض الاهتمامات. هذه نظرة للحرية مختلفة: أن أرى في الخسارة مساحة جديدة. فكّر في شيء فقدته، وجرّب أن تشكر الله على الحرية التي أعطاك إياها.\",\"p\":\"يا رب، حرّرني من تعلق قلبي بما يزول. علّمني أن أقبل الفقد بحمد، وأن أجد حريتي الحقيقية فيك وحدك. آمين.\",\"x\":\"التحرر من الاهتمامات الكثيرة هو بداية الحرية، فلا نحزن على ما فقدناه. تدريب: أطلق اليوم شيئًا تتعلق به بشدة، سلّمه لله وعش بدونه ساعة.\",\"fq\":104}]},\"2-14\":{\"th\":\"المحبة العملية\",\"m\":[{\"t\":\"طوبى لمن يتعطف\",\"ref\":\"المزمور ٤٠ (٤١) — الثالثة\",\"v\":\"طوبى لمن يتعطف على المسكين، في يوم الشر ينجيه الرب. الرب يحفظه ويحييه. ويجعله في الأرض مغبوطا، ولا يسلمه لأيدي أعدائه.\",\"r\":\"يمدح المرنم من يتعطف على المسكين، فيكون الرب حافظه ومحييه في يوم الشر. المحبة العملية لا تنتظر الشعور، بل تبدأ بخطوة صغيرة نحو المحتاج. من في دائرتك يحتاج اليوم مكالمة أو زيارة أو مساعدة بسيطة؟\",\"p\":\"يا رب، اجعلني أتعطف على كل مسكين. علّمني أن أحب بالفعل لا بالكلام، وكن أنت حافظي ومحييّ في يوم الشر. آمين.\",\"x\":\"المحبة العملية تبدأ بالتعطف على المسكين، ووعد الرب أنه يحفظه. تدريب: قدم اليوم شيئًا حقيقيًا لمحتاج: وقتًا أو مالًا أو مساعدة.\"},{\"t\":\"المحبة تغطي كثرة من الخطايا\",\"ref\":\"بطرس الأولى ٤: ٨\",\"bk\":\"بطرس الأولى\",\"v\":\"ولكن قبل كل شيء، لتكن محبتكم بعضكم لبعض شديدة، لأن المحبة تستر كثرة من الخطايا.\",\"r\":\"في العلاقات القريبة نرى العيوب بوضوح. والمحبة تختار ألا تنشر هذه العيوب ولا تضخمها. «تغطي» لا تعني أن أنكر الخطأ، بل أن أتعامل معه في الخفاء بحكمة ومحبة. وحين يسقط أحد أحبائي، أكون أول من يستره لا من يفضحه.\",\"p\":\"يا رب، علّمني محبة حارة تغطي كثرة من الخطايا. امنع لساني من الإذاعة بعيوب إخوتي. اجعلني أستر وأصلح كما فعلت معي. آمين.\",\"x\":\"قال بطرس «محبة حارة» أي ملتهبة ومستمرة، لا مجرد ودّ بارد. والمحبة الحارة لا تتراجع أمام العيوب. وهي تعمل على الإصلاح بلطف. وغطاء المحبة ليس تغطية للشر بل رحمة تُعطي فرصة للتوبة. وهذا ما فعله الله معنا.\\nاذكر شخصًا انتقدته في غيابه، واعتذر في قلبك لله، ثم قرّر أن تذكره اليوم بكلمة حسنة.\"},{\"t\":\"أعظم المحبة بذل النفس\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشرح الأب بيمن أن أعظم محبة هي بذل النفس عن القريب، وأن من يجاهد ألا ينطق بما يجرح أو يحتمل الظلم والطمع قادر أن يبذل حياته. المحبة تبدأ من الصغائر. ابدأ اليوم بكلمة لا تقولها أو أمر تحتمله من أجل أخيك.\",\"p\":\"يا رب، علّمني أن أبذل نفسي من أجل قريبي في الصغير قبل الكبير. اجعل محبتي عملية تشبه محبتك. آمين.\",\"x\":\"أعظم المحبة بذل النفس، أي أن أضع حاجة أخي قبل راحتي. تدريب: اختر اليوم تضحية صغيرة، مثل التنازل عن مقعد أو رأي، حبًا في قريبك.\",\"fq\":394}]},\"2-15\":{\"th\":\"تقدمة السيد إلى الهيكل\",\"m\":[{\"t\":\"عيناي أبصرتا خلاصك\",\"ref\":\"إنجيل النوم\",\"v\":\"الآن يا سيدي تطلق عبدك بسلام حسب قولك، لأن عيني قد أبصرتا خلاصك الذي أعددته قدام جميع الشعوب. نورا تجلى للأمم، ومجدا لشعبك إسرائيل.\",\"r\":\"في عيد دخول السيد إلى الهيكل يحمل سمعان الشيخ الطفل على ذراعيه ويرى في هذا الطفل الخلاص كله. بعد سنين طويلة من الانتظار صار وداعه سلامًا. وما ينتظره قلبك اليوم قد يأتي في صورة بسيطة، فكن مستعدًا لتعرفه.\",\"p\":\"الآن يا سيدي أطلق عبدك بسلام، فقد أبصرت عيناي خلاصك. اجعلني دائمًا منتظرًا لك بقلب مستعد وروح تتعرف عليك. آمين.\",\"x\":\"في تقدمة السيد إلى الهيكل يحمل سمعان الشيخ الطفل ويقول: عيناي أبصرتا خلاصك. ومن ينتظر الله يُكافأ بلقائه. تدريب: ابحث اليوم عن لحظة تحمل فيها المسيح في صلاتك كما حمله سمعان.\"},{\"t\":\"تقدمة الذات\",\"ref\":\"رومية ١٢: ١\",\"bk\":\"رومية\",\"v\":\"فأطلب إليكم أيها الإخوة برأفة الله أن تقدموا أجسادكم ذبيحة حية مقدسة مرضية عند الله، عبادتكم العقلية.\",\"r\":\"في هذا العيد قدّمت العذراء ابنها لله حسب الناموس. وفي كل يوم أنا مدعو أن أقدم حياتي له: وقتي وجسدي وقراري. والتقدمة ليست حدثًا واحدًا بل حياة. وهي «عبادة عقلية»، أي واعية، ولا تأتي من الجبر بل من الاقتناع بمراحم الله.\",\"p\":\"يا رب، أقدّم لك نفسي ذبيحة حية. أقدم جسدي وفكري ووقتي. اقبلني كما قبلت تقدمة ابنك في الهيكل، وجدد ذهني لأعرف مشيئتك. آمين.\",\"x\":\"بولس يبدأ بـ«أطلب إليكم بمراحم الله»، أي أن التقدمة جواب على عطية. ثم يحذر: لا تشاكلوا هذا الدهر بل تغيروا بتجديد أذهانكم. فالتقدمة تبدأ في العقل، ثم تظهر في السلوك. وحين أقدم نفسي، لا أخسر بل أجد ذاتي الحقيقية.\\nقدّم اليوم شيئًا محددًا لله: ساعة من وقتك أو مهارتك أو مالك، واجعلها واضحة في نيتك.\"},{\"t\":\"لنحترم الواحد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوحنا الكولوفي لتلميذه: لنحترم الواحد فيحترمنا الجميع، ويقصد بالواحد الله. تقدمة السيد إلى الهيكل تذكّرنا أن الله هو الأول، وأن كل علاقة تنتظم حين يكون هو المركز. ضع الله اليوم أول اهتماماتك.\",\"p\":\"يا رب، أنت الواحد الذي أحترمه وأخافه. ضعني في مكاني أمامك، ورتّب علاقاتي كلها بمحبتك. آمين.\",\"x\":\"من يحترم الواحد يحترمه الجميع، فالاحترام يبدأ بشخص ثم يتسع. تدريب: اعامل اليوم شخصًا مهملًا باحترام خاص.\",\"fq\":160}]},\"2-16\":{\"th\":\"البصيرة الروحية\",\"m\":[{\"t\":\"أنر عيني\",\"ref\":\"المزمور ١٢ (١٣) — باكر\",\"v\":\"انظر واستجب لي يا ربي وإلهي. أنر عيني لئلا أنام نوم الموت، لئلا يقول عدوي: إني قد قويت عليه.\",\"r\":\"يصلي المرنم: «أنر عيني لئلا أنام نوم الموت». البصيرة الروحية تبدأ بالاعتراف أننا لا نرى بذواتنا. وحين تنفتح العيون نرى الله في الأحداث التي كنا نعدها عادية. اطلب اليوم عينًا ترى حضوره في موقف واحد.\",\"p\":\"انظر واستجب لي يا ربي وإلهي، وأنر عيني لئلا أنام نوم الموت. افتح بصيرتي لأرى عملك، وأبتهج بخلاصك. آمين.\",\"x\":\"يطلب المرنم نورًا لعينيه لئلا ينام نوم الموت، فالبصيرة الروحية عطية. تدريب: اطلب من الله أن ينير عينيك لترى اليوم فرصة خدمة لم تلاحظها.\"},{\"t\":\"شفاء الأعمى\",\"ref\":\"يوحنا ٩: ٢٥\",\"bk\":\"يوحنا\",\"v\":\"فأجاب ذاك وقال: «أخاطئ هو؟ لست أعلم. إنما أعلم شيئا واحدا: أني كنت أعمى والآن أبصر».\",\"r\":\"أُلقيت على الأعمى أسئلة وتشكيكات كثيرة، لكنه لم يدخل في جدال لاهوتي. قال ببساطة: «أنا أعلم شيئًا واحدًا: أني كنت أعمى والآن أبصر». شهادتك لا تحتاج أن تكون معقدة. يكفي أن تحكي ما فعله المسيح فيك.\",\"p\":\"يا رب يسوع، كنت أعمى والآن أبصر بنعمتك. اشفِ عمى قلبي وأفهمني ما لا أراه. اجعلني شاهدًا بسيطًا صادقًا لعملك فيّ. آمين.\",\"x\":\"المسيح استخدم الطين والماء، وطلب من الأعمى أن يذهب ويغتسل. أي أن الشفاء يتطلب طاعة. ثم رفضه القادة الدينيون لأن الشفاء حدث يوم السبت. وهذا يذكّرنا بأن العمى الحقيقي هو عمى من يظن أنه يبصر. والأعمى اكتسب بصرًا جسديًا ثم روحيًا.\\nاكتب في ثلاثة أسطر: كيف كنت قبل أن أعرف المسيح وكيف أصبحت، وشاركها مع شخص قريب.\"},{\"t\":\"ثلاث فضائل ترفع النفس\",\"ref\":\"\",\"v\":\"\",\"r\":\"يلخّص الأب بيمن ما ترتفع به النفس في ثلاث: الانتباه والصحو والتمييز. هذه هي عيون القلب. وحين تضعف إحداها يضعف النظر. فأي واحدة منها تحتاج إلى تدريب اليوم؟ اختر واحدة وعالجها.\",\"p\":\"يا رب، امنحني انتباهًا وصحوًا وتمييزًا. افتح بصيرتي بنعمتك لأرى كل شيء كما تراه أنت. آمين.\",\"x\":\"الانتباه والصحو والصلاة ثلاث فضائل ترفع النفس عن الانشغال بالأرضيات. تدريب: طبّق واحدة منها اليوم عمدًا: خصص ثلاث دقائق للصحو والانتباه.\",\"fq\":333}]},\"2-17\":{\"th\":\"الصبر على الناس\",\"m\":[{\"t\":\"إلى جيلٍ فجيل حقه\",\"ref\":\"المزمور ٩٩ (١٠٠) — التاسعة\",\"v\":\"فإن الرب صالح هو، وإلى الأبد رحمته. وإلى جيل فجيل حقه.\",\"r\":\"يذكّرنا المرنم أن الرب صالح ورحمته إلى الأبد وحقه إلى جيل فجيل. من يتأمل صبر الله على الأجيال يتعلم الصبر على من أمامه. فكّر في شخص يتعبك اليوم، وتذكّر كم صبر الله عليك.\",\"p\":\"يا رب، أنت صالح ورحمتك إلى الأبد وحقك إلى جيل فجيل. علّمني أن أصبر على الناس كما صبرت أنت عليّ. آمين.\",\"x\":\"حق الله يمتد إلى جيل فجيل، فنحن حلقة في سلسلة وعده. تدريب: كلم أحد الأصغر منك عن أمانة الله في حياتك، فهذا ينقل الوعد للجيل القادم.\"},{\"t\":\"طول الأناة\",\"ref\":\"غلاطية ٥: ٢٢\",\"bk\":\"غلاطية\",\"v\":\"وأما ثمر الروح فهو: محبة فرح سلام، طول أناة لطف صلاح، إيمان\",\"r\":\"طول الأناة تعني أن «روحي طويلة» لا تنفد بسرعة. وأنا أعلم أنني أنفد سريعًا حين أكون متعبًا أو مضغوطًا. لكن الصبر من ثمار الروح، أي أنه ينمو حين أتغذى من الروح. وكلما اقتربت من الله اتسعت صدري للآخرين.\",\"p\":\"أيها الروح القدس، اغرس فيّ ثمر طول الأناة. اجعل صدري واسعًا وروحي هادئة. ذكّرني بصبرك عليّ حين أضيق بغيري. آمين.\",\"x\":\"الله يوصف في الكتاب بأنه «طويل الروح وكثير الرحمة». وحين أتأمل صبره على خطاياي المتكررة، أخجل من نفاد صبري على غيري. والتدرب على الصبر يبدأ بالأمور الصغيرة: الازدحام، وانتظار الرد، وتأخر الآخرين. فهي مدرسة صغيرة لصبر أكبر.\\nاليوم عند أول موقف تضيق فيه من الانتظار، حوّله إلى صلاة قصيرة لمن تنتظره أو لمن حولك.\"},{\"t\":\"القوس إذا شُدّ فوق القياس\",\"ref\":\"\",\"v\":\"\",\"r\":\"أراه القديس أنطونيوس لصياد أن القوس إذا شُدّ فوق قياسه انكسر، وكذلك الإخوة إذا ضُغط عليهم فوق طاقتهم. الصبر على الناس يعني أن أراعي قدرتهم. وأنت اليوم، أي شخص تضغط عليه أكثر مما يحتمل؟ خفّف عنه.\",\"p\":\"يا رب، علّمني الرفق بمن حولي، وألا أطلب من أحد ما لا يطيق. اجعلني صبورًا ومتنازلًا بمحبة. آمين.\",\"x\":\"القوس إذا شُد فوق قياسه انكسر، فلا نحمّل أنفسنا أو غيرنا ما لا يطاق. تدريب: راجع جدول اليوم وأعد منه شيئًا يرهقك فوق الطاقة.\",\"fq\":9}]},\"2-18\":{\"th\":\"الاعتراف بالخطية\",\"m\":[{\"t\":\"انظر إلى ذلي وتعبي\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"انظر إلى ذلي وتعبي. واغفر لي جميع خطاياي.\",\"r\":\"الاعتراف يبدأ بنظرة الله إلى ذلّنا وتعبنا قبل أن يطلب منا شيئًا: «انظر إلى ذلي وتعبي واغفر لي جميع خطاياي». يجتمع هنا الألم والتوبة. فلا تخف أن تعرض على الله حقيقتك كما هي، ففي نظرته شفاء.\",\"p\":\"انظر يا رب إلى ذلي وتعبي، واغفر لي جميع خطاياي. اقبل اعترافي الصادق، وأعد إليّ فرحك. آمين.\",\"x\":\"الاعتراف يبدأ بنظر الله إلى ذلنا قبل أن نعترف نحن. فهو يسبقنا بالرحمة. تدريب: خذ وقتًا اليوم لتحضر لاعترافك القادم بكتابة نقاط قليلة.\"},{\"t\":\"الجابي في الهيكل\",\"ref\":\"لوقا ١٨: ١٣\",\"bk\":\"لوقا\",\"v\":\"وأما العشار فوقف من بعيد، لا يشاء أن يرفع عينيه نحو السماء، بل قرع على صدره قائلا: اللهم ارحمني، أنا الخاطئ.\",\"r\":\"الفريسي صلّى عن نفسه ومقارنًا نفسه بغيره. أما الجابي فوقف من بعيد ولم يرفع عينيه. صلاة الجابي بسيطة وقصيرة: «ارحمني». ولهذا خرج مبررًا. فالمهم ليس طول الصلاة ولا جمالها بل صدق القلب.\",\"p\":\"اللهم ارحمني أنا الخاطئ. لا أرفع عينيّ إليك بل أقرع صدري. اغفر لي كبريائي وقسوتي، واقبلني كما قبلت الجابي. آمين.\",\"x\":\"صلاة الجابي صارت قاعدة صلاة يسوع في التقليد الشرقي. وهي تعترف بالحال دون تبرير. والمسيح يقول: «من يضع نفسه يرتفع». وهذا يخالف منطق العالم. ويحذّرنا من أن نكون متدينين وبعيدين عن الله بالكبرياء.\\nردد اليوم هذه الصلاة بصدق في كل وقت انتظار: «اللهم ارحمني أنا الخاطئ»، وراقب ما يحدث لقلبك.\"},{\"t\":\"«خطئت» لا يعود مذنبًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعطينا الأب بيمن رجاءً عظيمًا: عندما يخطئ الإنسان ويقول «خطئت» لا يعود مذنبًا. فالاعتراف الصادق ينهي سطوة الخطيئة. إن كان على ضميرك شيء اليوم فقله لله كاملًا ولا تؤجله.\",\"p\":\"يا رب، أقول لك خطئت، فاغفر لي. لا تتركني أحمل خطيتي في الظلام، وألبسني ثوب التوبة والفرح. آمين.\",\"x\":\"حين يقول الإنسان «أخطأت» بصدق يخرج من سلطان الخطية. تدريب: انطق لله اليوم بكلمة «أخطأت» عن خطأ محدد بلا أعذار.\",\"fq\":384}]},\"2-19\":{\"th\":\"الجسد الواحد\",\"m\":[{\"t\":\"ندى حرمون\",\"ref\":\"المزمور ١٣٢ — النوم\",\"v\":\"ومثل ندى حرمون المنحدر على جبل صهيون. لأن هناك أمر الرب بالبركة والحياة إلى الأبد هلليلويا.\",\"r\":\"يشبّه المرنم الوحدة بندى حرمون الذي ينحدر على جبل صهيون فيحيي أرضًا. هكذا الجسد الواحد: كل عضو ينفع الآخر، وحيث الوحدة تأتي البركة. اسأل نفسك اليوم من هو العضو الذي أهملته في جسدك الروحي؟\",\"p\":\"يا رب، حيث تكون الوحدة هناك تأمر بالبركة والحياة. اجعلنا جسدًا واحدًا بمحبتك، وأنزل ندى بركتك على بيوتنا وكنيستنا. آمين.\",\"x\":\"ندى حرمون يرطب كل ما يقع عليه، والوحدة بين الإخوة كالندى تحيي. تدريب: قبل يومك، اتصل بشخص بينك وبينه جفاء، وارفع سلامًا بسيطًا.\"},{\"t\":\"فرحًا مع الفرحين\",\"ref\":\"رومية ١٢: ١٥\",\"bk\":\"رومية\",\"v\":\"فرحا مع الفرحين وبكاء مع الباكين.\",\"r\":\"من السهل أن أبكي مع الباكين وأنا أراهم يتألمون، لكن الأصعب أحيانًا أن أفرح مع الفرحين حين يكون عندهم ما ليس عندي. هنا تُختبر المحبة: هل أستطيع أن أفرح بنجاح غيري دون شعور بالنقص؟ فرحي بنجاحهم علامة صحة قلبي.\",\"p\":\"يا رب، أعطني قلبًا يفرح مع الفرحين ويبكي مع الباكين. طهّرني من الحسد والأنانية. علّمني أن أشارك إخوتي في كل ظروفهم بمحبة. آمين.\",\"x\":\"الحسد يمنع الفرح مع الآخرين، والأنانية تمنع البكاء معهم. والشركة تتطلب تحررًا من الاثنين. والله نفسه فرح مع العروسين في قانا وبكى مع مريم ومرثا. ومن تعلّم هذا ينضج في المحبة ويبني علاقات حقيقية.\\nاليوم، أرسل رسالة تهنئة لشخص نجح أو فرح، ورسالة مواساة لآخر يتألم، وانتبه لمشاعرك أثناء ذلك.\"},{\"t\":\"لم أؤثر مصلحتي على أخي\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينقل الأب يوحنا الخصي عن القديس أنطونيوس: «لم أؤثر مرة مصلحتي على مصلحة أخي». جملة قصيرة لكنها منهج حياة كاملة. هل يمكنك اليوم أن تقدّم مصلحة أخيك في أمر ولو بسيط؟\",\"p\":\"يا رب، علّمني أن أضع أخي قبل نفسي. وحّد قلوبنا ونفوسنا لنكون جسدًا واحدًا لك. آمين.\",\"x\":\"لم يؤثر القديس مصلحته على أخيه، فالمحبة تضع الأخ أولًا. تدريب: اقبل اليوم أن تخسر نقطة صغيرة في نقاش حتى تكسب الأخ.\",\"fq\":193}]},\"2-20\":{\"th\":\"الميراث السماوي\",\"m\":[{\"t\":\"الرب نصيب ميراثي\",\"ref\":\"المزمور الخامس عشر — باكر\",\"v\":\"الرب هو نصيب ميراثي وكأسي. أنت الذي ترد إلى ميراثي. حبال المساحة وقعت لي في أرض خصبة، وإن ميراثي لثابت لي.\",\"r\":\"يرى المرنم أن ميراثه الحقيقي هو الرب نفسه، وأن حبال المساحة وقعت له في أرض خصبة. من ينظر إلى ميراثه هكذا لا يحسد أحدًا. فتأمّل اليوم: ما الذي أعدّه ميراثي، وهل هو الله أم ما يعطيه؟\",\"p\":\"يا رب، أنت نصيب ميراثي وكأسي، وأنت الذي ترد إلي ميراثي. اجعل قلبي يطمئن لأن ميراثي ثابت في يدك. آمين.\",\"x\":\"يرى المرنم أن الرب نفسه ميراثه، وهذا أجمل ما يملكه الإنسان. تدريب: اكتب ما تعتبره ميراثك الحقيقي، وقارنه بما تسعى إليه كل يوم.\"},{\"t\":\"كنز في السماء\",\"ref\":\"متى ٦: ١٩–٢٠\",\"bk\":\"متى\",\"v\":\"«لا تكنزوا لكم كنوزا على الأرض حيث يفسد السوس والصدأ، وحيث ينقب السارقون ويسرقون. بل اكنزوا لكم كنوزا في السماء، حيث لا يفسد سوس ولا صدأ، وحيث لا ينقب سارقون ولا يسرقون،\",\"r\":\"السؤال الأهم ليس كم أملك بل أين قلبي. المسيح يربط الكنز بالقلب: «حيث يكون كنزك هناك يكون قلبك أيضًا». فإذا كان كنزي في الأرض يكون قلبي هناك يتأرجح مع الأسعار والأخبار. أما إن كان في السماء فيستقر. والاستثمار هناك يبدأ بالعطاء.\",\"p\":\"يا رب، حيث يكون كنزي هناك يكون قلبي. علّمني أن أكنز في السماء بالعطاء والصلاة. حرر قلبي من محبة المال، واجعلك أنت كنزي. آمين.\",\"x\":\"الكنوز السماوية تُجمع بأعمال بسيطة: صدقة في الخفاء، وكلمة طيبة، وصلاة بإخلاص، وخدمة بلا مقابل. ولا شيء من هذا يفسد أو يُسرق. والمسيح لا يمنع الادخار الحكيم، لكنه يحذر من أن يصير المال سيدًا. فلا يمكن خدمة سيدين.\\nاختر عملًا صغيرًا للعطاء في الخفاء اليوم، ولا تخبر به أحدًا، واعتبره إيداعًا في حسابك السماوي.\"},{\"t\":\"ذكر الملكوت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصينا الأب إيبريخيوس: «فليكن ذكر ملكوت السماوات أمامك كل حين، فترثه سريعًا». من يذكر وجهته لا يضل في الطريق. اجعل لك اليوم لحظة تذكّر فيها أنك غريب في هذا العالم وأن لك ميراثًا.\",\"p\":\"يا رب، ليكن ملكوتك أمام عيني كل حين. أعطني أن أعيش كابن لك ينتظر ميراثه بصبر ورجاء. آمين.\",\"x\":\"ذكر ملكوت السماوات يرتب الأولويات، فما لا يدخل الملكوت يخف وزنه. تدريب: عند كل ضيق اليوم، اسأل: ماذا سيكون وزن هذا في الملكوت؟\",\"fq\":554}]},\"2-21\":{\"th\":\"المصالحة قبل التقدمة\",\"m\":[{\"t\":\"اغضبوا ولا تخطئوا\",\"ref\":\"المزمور الرابع — باكر\",\"v\":\"أغضبوا ولا تخطئوا، الذي تقولونه في قلوبكم اندموا عليه في مضاجعكم. اذبحوا ذبيحة البر، وتوكلوا على الرب.\",\"r\":\"ليس الغضب نفسه خطيئة، لكن ما نفعله به قد يكون. ينصحنا المرنم أن نراجع في مضاجعنا ما قلناه في قلوبنا وأن نذبح ذبيحة البر. اليوم قبل أن تنام راجع أي كلمة غاضبة قلتها، وصالح.\",\"p\":\"يا رب، علّمني أن أغضب دون أن أخطئ، وأن أندم على ما يقوله قلبي في غضبه. أقدّم لك ذبيحة البر، وأتكل عليك. آمين.\",\"x\":\"الغضب يمكن أن يكون نقطة بداية، لكن المصالحة قبل التقدمة هي الحل. وتصلي الكنيسة في المزمور الرابع هذه الحقيقة. تدريب: اصطلح مع من اختلفت معه قبل أن تصلي الليلة.\"},{\"t\":\"سالموا جميع الناس\",\"ref\":\"رومية ١٢: ١٨\",\"bk\":\"رومية\",\"v\":\"إن كان ممكنا فحسب طاقتكم سالموا جميع الناس.\",\"r\":\"«إن كان ممكنًا فحسب طاقتكم سالموا جميع الناس». عبارة صادقة وواقعية: لا يطلب مني ما لا أقدر، لكنه يطلب كل ما أقدر. قد لا يتصالح الآخر معي، لكن عليّ أن أكون قد فعلت نصيبي: كلمة لينة، أو صمت حكيم، أو صلاة من أجله. السلام عملي قبل أن يكون شعورًا.\",\"p\":\"يا ملك السلام، اجعلني أداة لسلامك في بيتي وعملي. أعطني لسانًا هادئًا وقلبًا متواضعًا، وعلّمني أن أفعل نصيبي في المصالحة دون كبرياء. آمين.\",\"x\":\"السلام لا يعني الموافقة على الخطأ ولا الضعف، بل أن أرفض أن أكون سبب الشقاق. وفي التطبيق: أبدأ بالتحية، أتجنب الجدال العقيم، أتكلم بما يبني. والمسيح نفسه سمّاه الكتاب «رئيس السلام». ومن يحمل سلامه معه يهدّئ المكان الذي يدخله. وحين أفشل، لا أيأس، بل أعود وأحاول.\\nاختر اليوم موقفًا قد يشتعل فيه خلاف، وقرر مسبقًا أن تكون أنت صانع السلام فيه.\"},{\"t\":\"أخ ظلمك يدخل صلاتك\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينبهنا الأب نيلوس أن الأخ الذي نقاومه سيدخل إلى قلبنا ساعة الصلاة. أي أن الخصومة تعيق اللقاء مع الله. قبل أن تقف لتصلي اليوم، تخلص من مقاومة أحد، أو على الأقل ضعه في صلاتك.\",\"p\":\"يا رب، لا تدع خصومة تقف بيني وبينك. اغفر لي ولمن ظلمني، وصالحنا بسلامك قبل أن نقف في حضرتك. آمين.\",\"x\":\"الأخ الذي ظلمناه أو ظلمنا يدخل صلاتنا شئنا أم أبينا. تدريب: اذكر اسمه في صلاتك اليوم بخير، وانظر كيف يتغير شعورك.\",\"fq\":288}]},\"2-22\":{\"th\":\"مخافة الرب\",\"m\":[{\"t\":\"خشية الرب زكية\",\"ref\":\"المزمور الثامن عشر — باكر\",\"v\":\"خشية الرب زكية:، دائمة إلى أبد الأبد. أحكام الرب أحكام حق وعادلة معا.\",\"r\":\"«خشية الرب زكية دائمة»: كلمة تصف رائحة طيبة تدوم. مخافة الرب ليست رعبًا بل احترام يحفظنا من الاستهانة. وأحكامه حق وعادلة معًا. اقترب اليوم من الله بخشوع يحفظ قلبك من الاعتياد.\",\"p\":\"يا رب، ضع في قلبي خشيتك الزكية الدائمة. علّمني أن أسير بأحكامك الحق العادلة، وأقف أمامك بخشوع محب. آمين.\",\"x\":\"مخافة الرب رائحة طيبة تدوم، تشبه عطرًا يعلق بالثياب. تدريب: اترك اليوم أثرًا طيبًا في كل مكان تدخله، بكلمة أو تصرف يشبه رائحة المسيح.\"},{\"t\":\"بدء المعرفة\",\"ref\":\"الأمثال ١: ٧\",\"bk\":\"الأمثال\",\"v\":\"مخافة الرب رأس المعرفة، أما الجاهلون فيحتقرون الحكمة والأدب.\",\"r\":\"«مخافة الرب رأس المعرفة». لا أفهم المخافة هنا رعبًا من إله قاسٍ، بل توقيرًا لمن أحبني. كما يخشى الابن أن يجرح قلب أبيه. هذه المخافة لا تقيّدني، بل تحميني، وتجعلني أفكر قبل أن أتكلم وأتصرف: هل هذا يفرح الله؟\",\"p\":\"يا رب، ازرع في قلبي مخافة بنوية ومحبة صادقة. علّمني أن أعتبرك في كل قراراتي، وأن لا أحزن روحك القدوس بتصرف أو كلمة. آمين.\",\"x\":\"يقول الآباء إن المخافة نوعان: خوف العبيد من العقاب، وخوف الأبناء من فقدان الشركة. والثاني هو المقصود هنا، وهو بداية الحكمة لأنه يضع الله في مكانه الصحيح في حياتي. وكل من نسي هذه المخافة صار يقيس الأمور بمقاييس الناس فقط، فيضل. أما من يحفظها فإنه يزداد فهمًا للحياة، لأن من عرف الله عرف قيمة كل شيء.\\nاسأل نفسك قبل قرار اليوم: هل يرضي هذا الله؟ ودرّب نفسك على هذا السؤال ثلاث مرات.\"},{\"t\":\"ضع مخافة الله نصب عينيك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي القديس أنطونيوس: «ضع مخافة الله نصب عينيك دائمًا. وتذكّر هذا الذي يميت ويحيي». هذه الوصية لا تقصد إرهابنا بل إيقاظ وعينا. فاجعل مخافة الله اليوم مرجعًا لقرار واحد على الأقل تتخذه.\",\"p\":\"يا رب، اجعل مخافتك رفيقة لي في كل قرار. أعطني قلبًا يراك دائمًا، ويحيا بوعده وعهده معك. آمين.\",\"x\":\"وضع مخافة الله نصب العين يحفظ من أن نظن أن أحدًا لا يرانا. تدريب: عندما تكون وحدك اليوم، تصرف كأن الله بجانبك، لأنه كذلك.\",\"fq\":18}]},\"2-23\":{\"th\":\"السهر والاستعداد\",\"m\":[{\"t\":\"طوبى للعبد المستيقظ\",\"ref\":\"قطعة الخدمة الأولى (١) — نصف الليل — الخدمة الأولى\",\"v\":\"هاهوذا العريس يأتي في نصف الليل. طوبى للعبد الذي يجده مستيقظا. أما الذي يجده متغافلا، فإنه غير مستحق المضي معه. فانظري يا نفسي لئلا تثقلي نوما، فتلقي خارج الملكوت. بل اسهري.\",\"r\":\"تذكّرنا الكنيسة بالعريس الذي يأتي في ساعة لا نعرفها. السهر ليس قلقًا من الوقت، بل حياة تعيش كل لحظة كأنها لقاء محتمل. اسأل نفسك الليلة: لو جاء الآن، هل يجدني مشغولًا بما يليق به؟\",\"p\":\"أيها العريس السماوي، لا تدعني أثقل نومًا فألقى خارجًا. أيقظ نفسي لأسهر وأصرخ إليك، وكن أنت رجائي عند مجيئك. آمين.\",\"x\":\"العريس يأتي في ساعة لا نعرفها، فاليقظة هي الاستعداد المستمر لا الذعر. تدريب: اختر اليوم أمرًا مؤجلًا لإصلاح علاقة أو فعل خير، وأنجزه قبل الليل.\"},{\"t\":\"اصحوا واسهروا\",\"ref\":\"بطرس الأولى ٥: ٨\",\"bk\":\"بطرس الأولى\",\"v\":\"اصحوا واسهروا. لأن إبليس خصمكم كأسد زائر، يجول ملتمسا من يبتلعه هو.\",\"r\":\"«اصحوا واسهروا لأن إبليس خصمكم كأسد زائر يجول ملتمسًا من يبتلعه هو». يخبرني الرسول بالحقيقة ليحميني لا ليخيفني. العدو حقيقي، لكن المسيح انتصر عليه. وسلاحي هو الانتباه والصلاة والتمسك بكلمة الله، وأن لا أتهاون في الصغائر.\",\"p\":\"يا رب، احرسني من كل هجمة للعدو. علّمني أن أصحو وأقاوم بصلاة يسوع، وثبّتني في إيمانك. أنت قوتي وحصني. آمين.\",\"x\":\"الأسد يهاجم الفريسة المنعزلة والضعيفة، ولذلك ننصح بالبقاء في جماعة الكنيسة وفي الأسرار. وقد قال الآباء إن الحرب الروحية تبدأ بالفكر، فمن ردّ الفكر الشرير في بدايته لم يسقط. والمقاومة ليست بالقوة البشرية بل باسم يسوع. وبعد هذه الآية يقول بطرس إن الله يكمّلنا ويثبّتنا بعد ألم يسير.\\nعندما يأتيك فكر سلبي اليوم، قل في الحال: «يا يسوع ارحمني»، ولا تتحاور معه.\"},{\"t\":\"افحص أفكارك\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح القديس أمون الأخ بأن يفحص أفكاره كما يفعل فاعلو الشر في السجن، يسألون عن الرئيس ومتى يأتي. أي أن ننتظر لقاء مع الله بمحاسبة يومية. خصص الليلة خمس دقائق لمراجعة يومك أمام الله.\",\"p\":\"يا رب، علّمني أن أحاسب نفسي كل يوم وأتيقظ للقائك. ليكن ذهني مستعدًا وقلبي ساهرًا. آمين.\",\"x\":\"يدعونا القديس إلى فحص الأفكار كما يفحص الصانع قطعته. تدريب: في المساء، اكتب ثلاث أفكار شغلتك اليوم، وقيّمها أمام الله.\",\"fq\":60}]},\"2-24\":{\"th\":\"العطاء بفرح\",\"m\":[{\"t\":\"فرّق وأعطى المساكين\",\"ref\":\"المزمور ١١١ (١١٢) — التاسعة\",\"v\":\"قلبه مستعد متكل على الرب. قلبه ثابت لا يتزعزع حتى يرى بأعدائه. فرق وأعطى المساكين.\",\"r\":\"يصف المرنم الرجل المتقي الرب بأن قلبه مستعد وثابت، ومن ثمرة هذا الثبات أنه يفرّق ويعطي المساكين. العطاء ليس تبذيرًا بل علامة قلب متكل على الرب. اعطِ اليوم شيئًا، ولو صغيرًا، بفرح ودون إعلان.\",\"p\":\"يا رب، اجعل قلبي مستعدًا متكلًا عليك. علّمني أن أعطي المساكين بفرح، وثبّت قلبي فلا يتزعزع. آمين.\",\"x\":\"ثمرة المتقي الرب أن قلبه مستعد وثابت، فيعطي دون خوف من النقص. تدريب: أعط اليوم شيئًا حتى لو كان قليلًا بفرح، ولا تحسب ما بقي.\"},{\"t\":\"فلسا الأرملة\",\"ref\":\"لوقا ٢١: ١–٤\",\"bk\":\"لوقا\",\"v\":\"وتطلع فرأى الأغنياء يلقون قرابينهم في الخزانة، ورأى أيضا أرملة مسكينة ألقت هناك فلسين. فقال: «بالحق أقول لكم: إن هذه الأرملة الفقيرة ألقت أكثر من الجميع، لأن هؤلاء من فضلتهم ألقوا في قرابين الله، وأما هذه فمن إعوازها، ألقت كل المعيشة التي لها».\",\"r\":\"رأى المسيح الأغنياء يلقون من فضلتهم، وأرملة تلقي فلسين، فقال: «هذه الأرملة الفقيرة ألقت أكثر من الجميع». لأن القيمة عند الله ليست في الرقم بل في التضحية. هي لم تحتفظ لنفسها بشيء، فكانت تثق أن الله يعولها. فما أجمل ثقتها!\",\"p\":\"يا رب، علّمني ثقة الأرملة في عنايتك. اقبل مني ما أقدمه ولو قليلًا، واجعلني أعطي من قلبي دون حساب. آمين.\",\"x\":\"المسيح كان يجلس مقابل الخزانة ويراقب. وهذا يعني أنه يرى كل عطاء مهما كان خفيًا. وهو لا يقارن بين الناس، بل يزن القلوب. وحين نعطي من أعوازنا نكتشف عناية الله كما اكتشفت أرملة صرفة صيدا. وقد لا نملك مالًا لكننا نملك وقتًا وموهبة وصلاة. وكلها «فلوس» ثمينة في عيني المسيح.\\nاسأل نفسك: ما الذي يكلفني فعلًا أن أعطيه اليوم؟ وكن مستعدًا أن تقدمه بثقة.\"},{\"t\":\"أيديكم للعطاء\",\"ref\":\"\",\"v\":\"\",\"r\":\"أوصى الأب خومة أبناءه قبل رحيله ألا يمدوا أيديهم للأخذ بل للعطاء. وصية تعبّر عن روح المسيح الذي قال إن العطاء أفضل من الأخذ. فكّر اليوم: ماذا تستطيع أن تعطي، من وقتك أو مالك أو انتباهك؟\",\"p\":\"يا رب، علّمني أن أمد يدي للعطاء لا للأخذ. اجعل عطائي فرحًا يحمل بركتك للآخرين. آمين.\",\"x\":\"أيدينا للعطاء لا للأخذ، وصية جعلها الأب لمن يخلفه. تدريب: اطلب اليوم أقل مما تستحق في موقف ما، وأعط أكثر.\",\"fq\":558}]},\"2-25\":{\"th\":\"الاستقامة والنزاهة\",\"m\":[{\"t\":\"السالك بلا عيب\",\"ref\":\"المزمور الرابع عشر — باكر\",\"v\":\"السالك بلا عيب والفاعل البر، والمتكلم بالحق في قلبه، الذي لا يغش بلسانه، ولا يصنع بقريبه سوءا، ولا يقبل عارا على جيرانه. فاعل الشر مرذول أمامه؛ ويمجد الذين يتقون الرب.\",\"r\":\"يصف المرنم الساكن في بيت الرب بأنه سالك بلا عيب، متكلم بالحق، لا يغش ولا يسيء إلى قريبه. هذه هي النزاهة اليومية: كلمة صادقة وفعل عادل. اختبر اليوم صدقك في أمر صغير لا يراه أحد.\",\"p\":\"يا رب، من يسكن في مسكنك؟ اجعلني سالكًا بلا عيب، فاعلًا للبر، ومتكلمًا بالحق في قلبي. آمين.\",\"x\":\"السالك بلا عيب يتكلم بالحق ويكرم الذين يتقون الرب. النزاهة صفة لا تخفى. تدريب: اختر اليوم موقفًا تقول فيه الحق بلطف، ولو كان في الصمت خسارة صغيرة.\"},{\"t\":\"زكا يرد المال\",\"ref\":\"لوقا ١٩: ٨\",\"bk\":\"لوقا\",\"v\":\"فوقف زكا وقال للرب: «ها أنا يارب أعطي نصف أموالي للمساكين، وإن كنت قد وشيت بأحد أرد أربعة أضعاف».\",\"r\":\"لم يطلب المسيح من زكا أن يرد شيئًا، لكن اللقاء به غيّر قلبه فقال: «ها أنا يا رب أعطي نصف أموالي للمساكين وإن كنت قد وشيت بأحد أرد أربعة أضعاف». التوبة الحقيقية تلمس الجيب والعلاقات، وليست كلامًا فقط. والنعمة تغيّر ما لم يستطع الناموس أن يغيّره.\",\"p\":\"يا رب، كما زرت زكا زر قلبي. أعطني توبة صادقة ترد الحقوق وتصلح العلاقات، وأنعم عليّ بفرح الخلاص. آمين.\",\"x\":\"زكا كان غنيًا لكنه كان يشعر بالوحدة. وحين قبله المسيح نزل من الشجرة وفتح بيته وقلبه ثم محفظته. وما أجمل أن التوبة لديه كانت فرحًا لا ثقلًا. وفي حياتنا قد نكون ظلمنا أحدًا بكلمة أو حق ضائع. والله يطلب منا أن نصلح ما نقدر عليه بحكمة. وبهذا تتم المصالحة الكاملة مع الله والناس.\\nتذكّر حقًّا أو دينًا لأحد عليك لم تؤدّه، وضع خطة لرده في أقرب وقت.\"},{\"t\":\"ضمير نقي تجاه القريب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بمفو للأخوين اللذين يصومان ويتعبّدان: حسنة هي الأعمال، لكن إن حفظتما ضميركما نقيًا تجاه القريب تخلصان. فالنزاهة أن لا يكون في قلبي حيلة أو أذى نحو أحد. هل ضميرك اليوم نقي نحو الجميع؟\",\"p\":\"يا رب، احفظ ضميري نقيًا تجاه كل قريب. لتكن أعمالي كلها بصدق ونزاهة أمامك. آمين.\",\"x\":\"الصوم والعبادة بلا ضمير نقي تجاه القريب ناقصة. تدريب: قبل أن تؤدي عبادتك اليوم، أصلح علاقة خرجت فيها بإساءة.\",\"fq\":456}]},\"2-26\":{\"th\":\"النهوض بعد السقوط\",\"m\":[{\"t\":\"الرب يقيم الساقطين\",\"ref\":\"المزمور ١٤٥ — النوم\",\"v\":\"الرب يحل المربوطين الرب يقيم الساقطين. الرب يحكم العميان. الرب يحب الصديقين.\",\"r\":\"كل سقوط قابل للقيام لأن الرب هو الذي يقيم الساقطين ويحل المربوطين. لا يبقى الساقط طويلًا على الأرض إن مدّ يده. مهما كان سقوطك الأخير، قل اليوم لله: أقمني، ثم قم وامشِ.\",\"p\":\"أيها الرب الذي يحل المربوطين ويقيم الساقطين، أقمني من سقوطي. أنت تحب الصديقين، فاجعلني منهم بنعمتك. آمين.\",\"x\":\"الرب يقيم الساقطين ويحل المربوطين، فلا سقوط بلا قيامة إن رجعنا إليه. تدريب: لا تتأخر في النهوض بعد أي سقطة اليوم، قم فورًا وقل: يا رب أقمني.\"},{\"t\":\"أتحبني أكثر من هؤلاء\",\"ref\":\"يوحنا ٢١: ١٥\",\"bk\":\"يوحنا\",\"v\":\"فبعد ما تغدوا قال يسوع لسمعان بطرس: «يا سمعان بن يونا، أتحبني أكثر من هؤلاء؟» قال له: «نعم يارب أنت تعلم أني أحبك». قال له: «ارع خرافي».\",\"r\":\"أنكر بطرس سيده ثلاث مرات، ولم يوبخه المسيح بعد القيامة بل سأله ثلاث مرات: «أتحبني؟». السؤال لم يكن عن الماضي بل عن الحب. والمسيح لا يعيّر ساقطًا بل يعيده إلى مكانه ويكلفه برعاية خرافه. هكذا يتعامل معي: يسألني عن قلبي ثم يعطيني رسالة.\",\"p\":\"يا رب، أنت تعلم كل شيء، أنت تعلم أني أحبك. اغفر لي إنكاري وضعفي، وأعد إليّ ثقتك، واستخدمني في خدمة خرافك. آمين.\",\"x\":\"ثلاثة أسئلة قابلت ثلاثة إنكارات، فكأن المسيح يمحو كل إنكار بإعلان حب. وفي كل مرة يعطي بطرس مهمة: ارعَ خرافي. فالتوبة الحقيقية لا تتركنا في الندم، بل تقودنا إلى الخدمة. وقد صار بطرس بعد ذلك عمودًا في الكنيسة. فلا تحكم على نفسك بسقطتك، بل بمحبة المسيح التي تعيدك.\\nأجب المسيح بصدق اليوم: «يا رب أنت تعلم كل شيء، أنت تعلم أني أحبك»، ثم اسأله ماذا يريدك أن تفعل.\"},{\"t\":\"انهض أيضًا من جديد\",\"ref\":\"\",\"v\":\"\",\"r\":\"حين سأل أخ الأب سيسوى ماذا يعمل بعد أن سقط، قال: انهض. وحين عاد وسقط قال: انهض أيضًا من جديد، إلى أن تنتهي إما إلى الخير أو إلى السقطة. معنى هذا أن النهوض هو الشيء الوحيد المطلوب. انهض الآن.\",\"p\":\"يا رب، أنهض مرة بعد مرة بنعمتك. لا تدعني أيأس مهما سقطت، وأعطني أن أنتهي إليك في كل مرة. آمين.\",\"x\":\"الجواب البسيط: انهض، وحين يسقط ثانية: انهض ثانية. الله لا يمل من قيامتنا. تدريب: اكتب في دفترك: كلما سقطت سأنهض، وعلقه حيث تراه.\",\"fq\":501}]},\"2-27\":{\"th\":\"الإيمان العامل\",\"m\":[{\"t\":\"بماذا أكافئ الرب؟\",\"ref\":\"المزمور ١١٥ — التاسعة\",\"v\":\"بماذا أكافئ الرب عن كل ما أعطانيه؟ كأس الخلاص آخذ وباسم الرب أدعو. أوفي نذوري للرب قدام كل شعبه.\",\"r\":\"يسأل المرنم: بماذا أكافئ الرب عن كل ما أعطانيه؟ وجوابه عمل: آخذ كأس الخلاص، وأوفي نذوري. الإيمان الحي يتحول إلى وفاء. ما الوعد الذي وعدت الله به ولم تنفذه؟ نفّذ جزءًا منه اليوم.\",\"p\":\"بماذا أكافئك يا رب عن كل ما أعطيتني؟ آخذ كأس الخلاص وباسمك أدعو، وأوفي نذوري لك أمام شعبك. آمين.\",\"x\":\"يسأل المرنم بماذا يكافئ الرب، وجوابه أخذ كأس الخلاص والوفاء بالنذور. الشكر يتحول إلى عمل. تدريب: حوّل شكرك إلى عمل اليوم: خدمة أو عطاء يعبر عن امتنانك.\"},{\"t\":\"الإيمان العامل بالمحبة\",\"ref\":\"غلاطية ٥: ٦\",\"bk\":\"غلاطية\",\"v\":\"لأنه في المسيح يسوع لا الختان ينفع شيئا ولا الغرلة، بل الإيمان العامل بالمحبة.\",\"r\":\"«في المسيح يسوع لا الختان ينفع شيئًا ولا الغرلة بل الإيمان العامل بالمحبة». كل مظاهري الدينية بدون محبة لا قيمة لها. والإيمان الذي يقبله الله هو الذي يعمل بالمحبة: يخدم ويسامح ويصبر. وأحتاج أن أراجع ما إذا كان تديّني مظهرًا أو حياة.\",\"p\":\"يا رب، علّمني أن تكون كل عبادتي محبة. حوّل ممارساتي الروحية إلى ثمر في حياتي، وازرع في قلبي إيمانًا يعمل بالمحبة. آمين.\",\"x\":\"في زمن بولس كان بعضهم يظنون أن الطقس الخارجي يكفي. واليوم قد نظن أن مجرد حضور القداس أو الصوم يكفي، دون أن نغير سلوكنا. لكن الطقوس وُضعت لتثمر محبة. والصوم الذي لا يجعلني أرحم صوم ناقص. والصلاة التي لا تجعلني ألين صلاة ناقصة. والمحبة هي الميزان الذي يقيس صدق كل ممارسة.\\nاسأل نفسك: ما الذي غيّرته صلاتي وصومي في معاملتي لمن حولي؟ واعمل شيئًا بسيطًا تعبّر به عن المحبة.\"},{\"t\":\"العمل بما نسمع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب فيلكس إن الإخوة كانوا يسألون الشيوخ ويعملون بما يسمعونه فيمنحهم الله القدرة على الكلام، أما الآن فيسألون ولا يعملون. الإيمان العامل هو الطاعة الفورية لما نعرفه. اختر كلمة سمعتها هذا الأسبوع وطبّقها اليوم.\",\"p\":\"يا رب، اجعلني عاملًا بما أسمع لا سامعًا فقط. أعطني قوة لتنفيذ ما تعلّمه كلمتك. آمين.\",\"x\":\"يقول الأب إن الإخوة كانوا يسألون ثم يعملون بما يسمعون، فالمعرفة بلا عمل لا تنفع. تدريب: اختر نصيحة روحية سمعتها مؤخرًا ولم تعمل بها، وابدأ بتنفيذها.\",\"fq\":556}]},\"2-28\":{\"th\":\"القناعة\",\"m\":[{\"t\":\"لا يعوزهم شيء\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"فإن الذين يتقونه لا يعوزهم شيء. الأغنياء افتقروا وجاعوا، أما الذين يبتغون الرب فلا يعوزهم أي خير.\",\"r\":\"يقول المرنم إن الذين يتقون الرب لا يعوزهم شيء، بينما الأغنياء افتقروا وجاعوا. القناعة ليست قلة طموح بل ثقة في أن الله يعطي الخير. أحصِ اليوم ثلاثة أشياء عندك ولا تلتفت لما ينقصك.\",\"p\":\"يا رب، من يتقيك لا يعوزه شيء. علّمني القناعة بما أعطيتني، وأن أبتغيك قبل كل خير. آمين.\",\"x\":\"الذين يتقون الرب لا يعوزهم شيء، فالقناعة ثروة. تدريب: اكتب ما عندك مما يكفيك، وشكر الله عليه قبل أن تفكر فيما ينقصك.\"},{\"t\":\"احترزوا من الطمع\",\"ref\":\"لوقا ١٢: ١٥\",\"bk\":\"لوقا\",\"v\":\"وقال لهم: «انظروا وتحفظوا من الطمع، فإنه متى كان لأحد كثير فليست حياته من أمواله».\",\"r\":\"«انظروا وتحفظوا من الطمع، فإنه ليس في كثرة الأموال حياة». هذا التحذير جاء ردًّا على من طلب عدلًا في ميراث. فالمسيح يكشف أن المشكلة أعمق من المال: هي الطمع الذي يجعلني أظن أن الأمان في الأشياء. لكن الحياة هبة من الله لا من المخزون.\",\"p\":\"يا رب، احفظني من الطمع. علّمني أن أكون غنيًا لك، وأن أستخدم ما أعطيتني لمجدك وخير إخوتي، ولا أعتمد على المخزون بل عليك. آمين.\",\"x\":\"في مثل الغني الغبي سمع المسيح الرجل يقول لنفسه: «يا نفسي لكِ خيرات كثيرة». لاحظ كلمة «لي» التي تكررت. وكانت نهايته: «هذه الليلة تُطلب نفسك منك». لا يحرم المسيح الاجتهاد، لكنه يحذر من أن أعيش لنفسي فقط. والغني الحكيم هو من يكون «غنيًا لله». وهذا يعني أن أستخدم ما عندي لخدمة الله والناس.\\nاسأل نفسك: هل أخزن شيئًا لا أحتاجه بينما يحتاجه غيري؟ قرر أن تعطي منه اليوم.\"},{\"t\":\"لا نقتني شيئًا بسبب مخافة الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقارن الأم سينكليتيكي بين الذين يجمعون الغنى ولا يكتفون وبين الذين يتركون الأمور المرغوب فيها بسبب مخافة الله. القناعة هنا اختيار حر. هل في حياتك شيء تستطيع أن تتخلى عنه بفرح اليوم؟\",\"p\":\"يا رب، علّمني أن أقنع بما عندي، وألا ألهث وراء المزيد. اجعل مخافتك كنزي الحقيقي. آمين.\",\"x\":\"من يجمع بلا حدود لا يشبع، ومن يتقي الله يكتفي. تدريب: تنازل اليوم عن رغبة شراء غير ضرورية، وأعط ما وفرته.\",\"fq\":538}]},\"2-29\":{\"th\":\"افتداء الوقت\",\"m\":[{\"t\":\"احسبني مع أصحاب الساعة الحادية عشرة\",\"ref\":\"قطعة الغروب (١)\",\"v\":\"إذا كان الصديق بالجهد يخلص فأين أظهر أنا الخاطئ. ثقل النهار وحره لم أحتمل لضعف بشريتي. لكن أنت يا الله الرحوم احسبني مع أصحاب الساعة الحادية عشر.\",\"r\":\"في نهاية شهر قصير نتذكر أن الوقت ثمين ومحدود، وأن الله يقبل من جاء في آخر النهار. لا ننتظر الوقت المثالي ليقترب الإنسان، ولا نيأس لأن الوقت مضى. استخدم اليوم ما بقي منه لتبدأ شيئًا طال تأجيله.\",\"p\":\"اللهم الرحوم، احسبني مع أصحاب الساعة الحادية عشرة. اقبل ما بقي من عمري، واجعل أيامي القادمة لك. آمين.\",\"x\":\"أصحاب الساعة الحادية عشرة نالوا أجرتهم كاملة، فالله لا يحسب بالزمن بل بالقلب. تدريب: إن كنت تشعر أنك تأخرت في أمر روحي، ابدأ اليوم ولا تؤجل بعد.\"},{\"t\":\"فرصة للصلاح\",\"ref\":\"غلاطية ٦: ١٠\",\"bk\":\"غلاطية\",\"v\":\"فإذا حسبما لنا فرصة فلنعمل الخير للجميع، ولا سيما لأهل الإيمان.\",\"r\":\"«فإذًا حسبما لنا فرصة فلنعمل الخير للجميع». كلمة «فرصة» تذكّرني أن الخير له وقت. أمامي اليوم من يحتاج كلمة أو مساعدة أو سؤالًا. إن أجّلت قد تفوت الفرصة. وأعمال المحبة الصغيرة، إذا أُجلّت، تتحول إلى ندم كبير. فليكن شعاري: اليوم لا غدًا.\",\"p\":\"يا رب، افتح عينيّ لفرص الخير التي تضعها أمامي. اجعلني سريعًا في المحبة، ولا تدعني أؤجل رحمة يمكن أن أقدمها اليوم. آمين.\",\"x\":\"لا ننتظر ظروفًا مثالية لنفعل الخير، فقد لا تأتي. والسامري الصالح لم يكن عنده وقت فائض، لكنه توقف. والفرصة قد تكون زيارة مريض أو مكالمة لمهموم أو مساعدة لطالب. وعلى كل منا أن يمتلك عين الانتباه. وبولس يخص «أهل الإيمان» بالأولوية، أي أن نبدأ بالأقرب في العائلة والكنيسة ثم نتسع.\\nاعمل اليوم خيرًا واحدًا كنت تؤجله منذ زمن، ولا تخبر أحدًا به.\"},{\"t\":\"حياتنا يوم واحد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس غريغوريوس اللاهوتي إن حياة الإنسان كلها يوم واحد بالنسبة للذين يتعبون بشوق. من يرى العمر يومًا واحدًا لا يضيعه في تأجيل. اجعل اليوم الذي لك أمانة أمام الله وقدّمه كله له.\",\"p\":\"يا رب، علّمني أن أحصي أيامي وأفتدي الوقت. اجعل اليوم الذي أنا فيه يومًا لك، فأتعب فيه بشوق وفرح. آمين.\",\"x\":\"حياتنا يوم واحد في نظر الأب، فكل ساعة فيه ثمينة. تدريب: قسّم هذا اليوم إلى ثلاث فترات، وقدّم كل فترة لله بصلاة قصيرة.\",\"fq\":88}]},\"3-1\":{\"th\":\"جمال الخليقة\",\"m\":[{\"t\":\"أعمال أصابعك\",\"ref\":\"المزمور الثامن — باكر\",\"v\":\"لأني أرى السموات أعمال أصابعك. القمر والنجوم أنت أسستها.\",\"r\":\"يقف المرنم أمام السماء والقمر والنجوم فلا يرى مجرد مشهد، بل أعمال أصابع الله. الجمال حولنا دعوة إلى الشكر. اخرج اليوم إلى شرفة أو شباك أو شارع، وانظر دقيقة واحدة إلى السماء دون أن تنشغل بشيء، ثم قل: ما أعظم أعمالك.\",\"p\":\"يا رب، أرى السماوات أعمال أصابعك، والقمر والنجوم التي أسستها. افتح عيني على جمال خليقتك، وعلّمني أن أشكرك عليها ولا أمر بها غافلًا. آمين.\",\"x\":\"ينظر المرنم إلى السماء والقمر والنجوم فيرى أعمال أصابع الله، فيتساءل بدهشة عن الإنسان. الخليقة كتاب مفتوح يعلمنا التواضع والشكر. تدريب: اخرج اليوم أو انظر من نافذتك، وتأمل شيئًا من الخليقة دقيقة كاملة وسبّح الله عليه.\"},{\"t\":\"السماوات تحدّث بمجد الله\",\"ref\":\"المزامير ١٩: ١\",\"bk\":\"المزامير\",\"v\":\"السماوات تحدث بمجد الله، والفلك يخبر بعمل يديه.\",\"r\":\"«السماوات تحدث بمجد الله والفلك يخبر بعمل يديه». لا تحتاج السماء إلى كلمات لتعلن عظمة الله، فهي تتكلم بنظامها وجمالها. وأنا أحتاج أحيانًا أن أرفع نظري من شاشتي ومشاغلي إلى السماء لأتذكر أن لي أبًا عظيمًا يهتم بالتفاصيل.\",\"p\":\"يا خالق السماء والأرض، افتح عينيّ لأرى جمال أعمالك وأسبّحك بها. علّمني أن أتأمل في خليقتك فأزداد معرفة بمحبتك وحكمتك. آمين.\",\"x\":\"الخليقة هي الكتاب الأول الذي كتبه الله، وهو يسبق الكتاب المقدس. ومن يتأمل في شروق الشمس وتعاقب الفصول يتعلم أمانة الله ونظامه. وقد كان القديس أنطونيوس يقول إن الطبيعة كتابه، ففيها يقرأ كلمة الله متى شاء. والتسبيح يبدأ بالانتباه، فمن لا ينتبه لا يشكر.\\nاخرج اليوم دقيقتين لتنظر إلى السماء أو شجرة أو غروب، وقل: «ما أعظم أعمالك يا رب».\"},{\"t\":\"ما ندمت على الصمت\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال القديس أرسانيوس لتلاميذه قبيل رحيله: «مرارًا كثيرة ندمت لأني تكلمت، ولكن عن الصمت لم أندم». الصمت يفتح الأذن لسماع الخليقة وهي تسبّح. اجعل لك اليوم دقائق تصمت فيها وتتأمل ما حولك.\",\"p\":\"يا رب، علّمني أن أصمت لأسمع تسبيح خليقتك. وأعطني قلبًا هادئًا يرى فيها يدك ويشكر. آمين.\",\"x\":\"الصمت يحمي من الندم على كلام قيل، لأن الكلمة بعد خروجها لا تُسترد. تدريب: قبل أن تعلق على أمر اليوم، اسأل: هل يحتاج الأمر إلى كلامي؟\",\"fq\":42}]},\"3-2\":{\"th\":\"القلب المنسحق\",\"m\":[{\"t\":\"قريب من منسحقي القلب\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"قريب هو الرب من منسحقي القلب، ويخلص المتواضعين بالروح. كثيرة هي أحزان الصديقين، ومن جميعها ينجيهم الرب. يحفظ الرب جميع عظامهم. وواحدة منها لا تنكسر.\",\"r\":\"كسر القلب في عين الله ليس عيبًا، فهو «قريب من منسحقي القلب ويخلص المتواضعين بالروح». كثيرة أحزان الصديقين، لكن الرب ينجيهم منها كلها. إن كان في داخلك كسر لا تبوح به، فاعرضه اليوم على الله بكلمات قليلة.\",\"p\":\"قريب أنت يا رب من منسحقي القلب. خلّصني متواضعًا بالروح، وانجني من أحزاني، واحفظ كياني فلا ينكسر. آمين.\",\"x\":\"كسر القلب في عين الله فرصة لا عيب، فهو قريب من المنسحقين. من يعرف ضعفه يفتح الباب للنعمة. تدريب: اعترف الآن بما يكسر قلبك، وقل: يا رب أنت قريب مني في هذا.\"},{\"t\":\"اتضعوا قدام الرب\",\"ref\":\"يعقوب ٤: ١٠\",\"bk\":\"يعقوب\",\"v\":\"اتضعوا قدام الرب فيرفعكم.\",\"r\":\"«اتضعوا قدام الرب فيرفعكم». المعادلة بسيطة وصعبة: أنزل أنا فيرفعني هو. لست مضطرًا أن أدافع عن نفسي أو أثبت قيمتي بالمنافسة. أضع نفسي في يده وهو يتولى الباقي، في الوقت الذي يراه. وهذا يعطيني سلامًا.\",\"p\":\"يا رب، علّمني أن أتضع أمامك فترفعني في الوقت الذي تراه. احفظني من الكبرياء والدفاع عن نفسي، واملأني بنعمتك. آمين.\",\"x\":\"من يرفع نفسه يتعب في الحفاظ على صورته، ومن يتضع يستريح. والاتضاع يظهر في الأمور الصغيرة: قبول النقد، وطلب المساعدة، والاعتراف بالخطأ. فالمتضع يملك نعمة، والمستكبر يملك صراعًا. ولنتذكر أن المسيح نفسه غسل أرجل تلاميذه.  اعترف اليوم بخطأ صغير أمام أحد دون تبرير، وراقب كيف يمنحك الله سلامًا.\\n\"},{\"t\":\"اجلس وابكِ خطاياك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يجيب الأب مكاريوس عن معنى الهرب من الناس بأنه أن يجلس الإنسان في قلايته ويبكي خطاياه. ليس البكاء ضعفًا بل صدق. خصّص دقائق الليلة تجلس فيها أمام الله وتقول له ما يثقل ضميرك.\",\"p\":\"يا رب، امنحني دموع التوبة الصادقة. علّمني أن أجلس أمامك بصدق، وأعترف بخطاياي فتغسلها نعمتك. آمين.\",\"x\":\"الجلوس في الصمت مع البكاء على الخطايا يطهّر القلب أكثر من الكلام الكثير. تدريب: خصص اليوم خمس دقائق لتجلس وتتأمل خطاياك أمام الله، بلا تبرير.\",\"fq\":244}]},\"3-3\":{\"th\":\"الصوم المقبول\",\"m\":[{\"t\":\"تعبتُ في تنهدي\",\"ref\":\"المزمور السادس — باكر\",\"v\":\"تعبت في تنهدي. أعوم كل ليلة سريري، وبدموعي أبل فراشي. تعكرت من الغضب عيناي.\",\"r\":\"يبوح المرنم بتعبه وتنهده ودموعه. الصوم الحقيقي ينفتح على هذا الصدق: لا مظهر ولا استعراض بل رجوع إلى الله بكل القلب. ليكن صومك اليوم، بأي صورة تلتزم بها، فرصة أن تقول لله ما في داخلك كاملًا.\",\"p\":\"يا رب، تعبت في تنهدي، وأبلّ فراشي بدموعي. اسمع بكائي وتضرعي، واجعل صومي رجوعًا إليك بكل قلبي. آمين.\",\"x\":\"الصوم الذي يفتح على التنهد والدموع صوم صادق، لأنه يجمع الجسد مع الروح في التوبة. تدريب: اجعل صومك اليوم مصحوبًا بصلاة طويلة قليلًا من المعتاد.\"},{\"t\":\"ارجعوا إليّ بكل قلوبكم\",\"ref\":\"يوئيل ٢: ١٢–١٣\",\"bk\":\"يوئيل\",\"v\":\"« ولكن الآن، يقول الرب، ارجعوا إلي بكل قلوبكم، وبالصوم والبكاء والنوح. ومزقوا قلوبكم لا ثيابكم». وارجعوا إلى الرب إلهكم لأنه رؤوف رحيم، بطيء الغضب وكثير الرأفة ويندم على الشر.\",\"r\":\"«ارجعوا إليّ بكل قلوبكم وبالصوم والبكاء والنوح، ومزقوا قلوبكم لا ثيابكم». الله لا يريد مظهرًا بل قلبًا. والرجوع إليه ليس رحلة مخيفة، فهو رحوم ورؤوف بطيء الغضب وكثير الرأفة. والباب مفتوح، وأنا أحتاج فقط أن أرجع بصدق.\",\"p\":\"يا رب، أنت حنان ورحيم. أرجع إليك بكل قلبي، فاقبلني ومزّق كل ما يحجبني عنك، وامنحني فرح الرجوع إلى بيت أبي. آمين.\",\"x\":\"الصوم وسيلة، والرجوع هدف. وقد ترتبط الأصوام بالطقوس لكن جوهرها هو التوبة. وكلمة «كل قلوبكم» تعني بلا استثناء ولا تحفظات. فالله يريد العودة الكاملة. والنبي يذكر صفات الله الأربع: حنان ورأفة وطول أناة وكثرة إحسان. فلا نخاف الرجوع. وفي كنيستنا نقرأ هذه الأيام في الصوم لأن الله ما زال ينادي.\\nحدد اليوم شيئًا تريد أن ترجع به إلى الله من كل قلبك، وقل له: «ها أنا راجع».\"},{\"t\":\"الصلاة مع الصوم\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سينكليتيكي: كما تبعد الأدوية القوية الوحوش السامة، هكذا تبعد الصلاة مع الصوم الفكر الشرير. الصوم وحده قد يصير مجرد حرمان، لكن اقترانه بالصلاة يجعله جهادًا. اجعل لكل امتناع اليوم صلاة قصيرة.\",\"p\":\"يا رب، اجعل صومي مقترنًا بالصلاة، وأبعد عني بهما كل فكر شرير. علّمني أن أصوم لك لا لنفسي. آمين.\",\"x\":\"الصوم بلا صلاة جوع، والصلاة بلا صوم ثقيلة، فالاثنان يتكاملان. تدريب: ثبّت اليوم قاعدة صلاة صغيرة مع صومك، ولو مزمورًا واحدًا.\",\"fq\":532}]},\"3-4\":{\"th\":\"الغلبة بالمسيح\",\"m\":[{\"t\":\"قوتي وتسبحتي\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"قوتي وتسبحتي هو الرب وقد صار لي خلاصا.\",\"r\":\"الغلبة في المسيح تبدأ بالاعتراف: «قوتي وتسبحتي هو الرب وقد صار لي خلاصًا». لا أنتصر بخبرتي ولا بقوتي، بل بمن صار لي خلاصًا. اذكر اليوم صراعًا تعبت منه، وقل لله إنك تسلّمه له لأنك ضعيف ولأنه أقوى.\",\"p\":\"أنت قوتي وتسبحتي يا رب، وقد صرت لي خلاصًا. اغلب عني وفيّ، واجعل انتصاري دائمًا باسمك. آمين.\",\"x\":\"الغلبة تبدأ بالاعتراف أن قوتنا في الرب، فلا نخوض الحرب منفردين. تدريب: قبل أول مواجهة اليوم، قل: قوتي وتسبحتي هو الرب.\"},{\"t\":\"أكثر من غالبين\",\"ref\":\"رومية ٨: ٣٧\",\"bk\":\"رومية\",\"v\":\"ولكننا في هذه جميعها يعظم انتصارنا بالذي أحبنا.\",\"r\":\"«ولكننا في هذه جميعها يعظم انتصارنا بالذي أحبنا». ليس انتصارنا بقوتنا بل بمحبته. حتى الشدة والضيق والاضطهاد لا تفصلني عنه. ما دام هو يحبني فأنا في أمان. وهذه المحبة هي الحصن الذي أختبئ فيه حين يعصف بي الألم.\",\"p\":\"يا رب، أشكرك لأن محبتك أقوى من كل شيء. ثبّتني فيها، ولا تدع الضيق أو الخوف يفصلني عنك، وامنحني أن أنتصر بك. آمين.\",\"x\":\"بولس يذكر قائمة طويلة مما قد يظن البعض أنه يفصلنا عن الله: الموت والحياة والملائكة والرياسات والحاضر والمستقبل. ثم يعلن أن لا شيء يقدر. وهذا اليقين ليس عاطفة بل إيمان بمن مات من أجلنا. وفي ضعفي أكتشف أن الغلبة ليست غياب المعركة بل الثبات في المحبة.\\nاقرأ رومية ٨: ٣٥–٣٩ بصوت عالٍ مرة، وضع اسمك مكان «نا» في نهايتها.\"},{\"t\":\"المسيح هو الذي غلبك\",\"ref\":\"\",\"v\":\"\",\"r\":\"قالت الأم سارة للشيطان الذي حاربها: «سيدي المسيح هو الذي غلبك لا أنا». ما أجمل التواضع الذي ينسب الانتصار لصاحبه! نحن لا ننتصر لنفتخر بل لنشكر. بعد أي نجاح روحي اليوم، لا تنسَ أن تعيده له.\",\"p\":\"يا ربي يسوع، أنت الذي تغلب في ضعفي. اجعلني أنسب إليك كل نصرة، وأتكل عليك في كل معركة. آمين.\",\"x\":\"المسيح هو الذي غلب فينا، فلا ننسب النصر لأنفسنا ولا نيأس عند السقوط. تدريب: عند كل نجاح اليوم قل: هذا من فضلك يا رب.\",\"fq\":526}]},\"3-5\":{\"th\":\"كلمة الله غذاء\",\"m\":[{\"t\":\"أحلى من العسل\",\"ref\":\"المزمور الثامن عشر — باكر\",\"v\":\"أفضل من الذهب والحجر الكثير الثمن، وأحلى من العسل والشهد.\",\"r\":\"يقارن المرنم كلمة الله بالذهب وبالعسل: أغلى من الذهب وأحلى من العسل. فهي غذاء يُتذوق وليست معلومة تُحفظ. اقرأ اليوم آية واحدة ببطء، وكأنك تتذوق كل كلمة فيها، وانظر هل تعطيك شبعًا أم تشتهي المزيد.\",\"p\":\"كلمتك يا رب أفضل من الذهب والحجر الكثير الثمن، وأحلى من العسل والشهد. اجعلني أشتهيها وأتغذى بها كل يوم. آمين.\",\"x\":\"كلمة الله أغلى من الذهب وأحلى من العسل، لأنها تغذي ما لا يغذيه شيء. تدريب: اقرأ اليوم آية قبل الأكل كما تتذوق الطعام، بتمهل.\"},{\"t\":\"ليس بالخبز وحده\",\"ref\":\"متى ٤: ٤\",\"bk\":\"متى\",\"v\":\"فأجاب وقال: «مكتوب: ليس بالخبز وحده يحيا الإنسان، بل بكل كلمة تخرج من فم الله».\",\"r\":\"«مكتوب: ليس بالخبز وحده يحيا الإنسان بل بكل كلمة تخرج من فم الله». المسيح كان جائعًا بعد أربعين يومًا، ومع ذلك قدّم كلمة الله على الخبز. وأنا كثيرًا ما أُطعم جسدي ثلاث مرات وأنسى أن أُطعم روحي مرة واحدة.\",\"p\":\"يا رب، أنت خبز الحياة. أشبع روحي بكلمتك كل يوم، وعلّمني أن أشتاق إليها أكثر من الطعام، وأعمل بها في حياتي. آمين.\",\"x\":\"الجسد يجوع فنشبعه، والروح تجوع ولا ننتبه. وعلامات جوع الروح: القلق والفراغ وسرعة الغضب. وعلاجها كلمة الله. وقد بدأ المسيح خدمته بهذا الجواب، مقتبسًا من سفر التثنية. فمعرفة الكتاب سلاح ضد التجربة. وقراءة آية واحدة مع التأمل خير من صفحات تُقرأ بسرعة. والآباء كانوا يحفظون المزامير ويرددونها كل يوم.\\nاختر اليوم آية واحدة واكتبها في مكان تراه كثيرًا، وردّدها كلما أكلت شيئًا.\"},{\"t\":\"حياة بكلمة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس: «حياة بدون كلام خير من كلام بدون حياة». كلمة الله تغذّينا حين نعيشها. لا يكفي أن نقرأها، بل يجب أن تتحول إلى سلوك. اختر اليوم كلمة قرأتها أخيرًا واجعلها حياة في موقف واحد.\",\"p\":\"يا رب، اجعل كلمتك حياة فيّ لا مجرد معرفة. أعطني أن أعيش ما أقرأ، فتكون حياتي كلمة مقروءة من الناس. آمين.\",\"x\":\"الحياة بالكلمة هي الغذاء اليومي الذي لا يستغنى عنه. تدريب: لا تبدأ نشاطك اليوم قبل أن تقرأ سطرًا من الكتاب.\",\"fq\":172}]},\"3-6\":{\"th\":\"الشهادة للمسيح\",\"m\":[{\"t\":\"بشروا من يوم إلى يوم\",\"ref\":\"المزمور ٩٥ (٩٦) — التاسعة\",\"v\":\"بشروا من يوم إلى يوم بخلاصه. حدثوا في الأمم بمجده وبين جميع الشعوب بعجائبه، لأن الرب عظيم هو ومسبح جدا.\",\"r\":\"يدعو المرنم إلى التبشير اليومي: يومًا بعد يوم، وبخلاص الله لا بأفكارنا. الشهادة ليست حدثًا استثنائيًا بل عادة أن نحدّث بعجائب الله. فاليوم، أخبر شخصًا واحدًا بفضل إلهي عليك، بكلمات صادقة وبسيطة.\",\"p\":\"يا رب، أبشر بخلاصك من يوم إلى يوم، وأحدّث بمجدك وعجائبك بين الناس. اجعل شهادتي صادقة وحياتي مرآة لمحبتك. آمين.\",\"x\":\"التبشير اليومي لا يعني خطابات، بل حياة تشهد في العمل والكلام. تدريب: اذكر اليوم أمام شخص ما أنك تصلي من أجله، أو شارك آية في رسالة.\"},{\"t\":\"فليضئ نوركم\",\"ref\":\"متى ٥: ١٦\",\"bk\":\"متى\",\"v\":\"فليضئ نوركم هكذا قدام الناس، لكي يروا أعمالكم الحسنة، ويمجدوا أباكم الذي في السماوات.\",\"r\":\"«فليضئ نوركم هكذا قدام الناس لكي يروا أعمالكم الحسنة ويمجدوا أباكم الذي في السماوات». الغاية ليست أن يمدحوني بل أن يمجدوا الله. والنور لا يتكلف، يضيء فقط. وكل عمل صالح أعمله بروح محبة يصير إضاءة صغيرة لمن حولي.\",\"p\":\"يا نور العالم، اجعلني أضيء بنورك وحدك. أعطني أعمالًا حسنة تمجّد أباك، وبعّد عني حب الظهور، وألهمني أن أعكس محبتك. آمين.\",\"x\":\"فالحياة المسيحية الحقة ظاهرة. لكنها ليست استعراضًا، فالنور يشير إلى مصدره. والسؤال: هل يرى من يعيش معي المسيح فيّ؟ والمقصود بالأعمال الحسنة أمور بسيطة: أمانة في العمل، ولطف في المعاملة، وهدوء في الضغط. وكل هذه تمجد الآب. اختر موقفًا اليوم تضيء فيه بلطف أو أمانة، ولا تنتظر شكرًا من أحد. \\n\"},{\"t\":\"يتكلمون كثيرًا ويعملون قليلًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"ملاحظة الأب بيمن قصيرة: الناس في أغلب الأحوال يتكلمون وفي القليل يعملون. وأقوى شهادة هي العمل الذي يسبق الكلام. اسأل نفسك اليوم: ماذا قلتُ عن المسيح ولم أعشه؟ وابدأ بالفعل لا بالقول.\",\"p\":\"يا رب، علّمني أن أشهد بأعمالي قبل أقوالي. اجعل حياتي موافقة لما أقول عنك. آمين.\",\"x\":\"الكلام الكثير بلا عمل يفقد قيمته، والشهادة الأقوى هي سلوك يوافق الكلمة. تدريب: اختر قولًا تردده كثيرًا وطبّقه اليوم عمليًا.\",\"fq\":354}]},\"3-7\":{\"th\":\"المسيح الشافي\",\"m\":[{\"t\":\"يشفي المنكسري القلوب\",\"ref\":\"المزمور ١٤٦ — النوم\",\"v\":\"الرب يشفي المنكسري القلوب. ويجبر جميع كسرهم.\",\"r\":\"يعلن المرنم أن الرب يشفي المنكسري القلوب ويجبر جميع كسرهم. الشفاء الأعمق هو شفاء الداخل. فقل له اليوم من أعماقك: ما انكسر فيّ أنت تعرفه، فاجبره أنت. ثم صلِّ لمن تعرف أنه مريض في جسده أو نفسه.\",\"p\":\"يا رب، أنت تشفي المنكسري القلوب وتجبر جميع كسرهم. اشفِ كل ما انكسر فيّ وفي أحبائي، وكن طبيب نفوسنا وأجسادنا. آمين.\",\"x\":\"الرب يشفي المنكسري القلوب ويجبر كسرهم، فهو الطبيب الذي لا يهمل جرحًا. تدريب: قدّم له جرحًا قديمًا لم يلتئم، وقل: يا رب اشفِ هذا أيضًا.\"},{\"t\":\"إن أردت تقدر\",\"ref\":\"لوقا ٥: ١٢–١٣\",\"bk\":\"لوقا\",\"v\":\"وكان في إحدى المدن، فإذا رجل مملوء برصا. فلما رأى يسوع خر على وجهه وطلب إليه قائلا: «يا سيد، إن أردت تقدر أن تطهرني». فمد يده ولمسه قائلا: «أريد، فاطهر!». وللوقت ذهب عنه البرص.\",\"r\":\"«يا سيد إن أردت تقدر أن تطهرني». ما أجمل هذا الإيمان المتواضع! لم يطالب بل رجا. والمسيح لمس الأبرص، وكان اللمس ممنوعًا، فكسر حاجز النجاسة والعزلة. جاوب الرب بكلمتين: «أريد فاطهر». وهكذا أتعلم أن إرادته نحوي هي الشفاء.\",\"p\":\"يا رب، إن أردت تقدر أن تطهرني وتشفيني. المس جراحي الخفية، واكسر عزلتي، وأعدني إلى الشركة معك ومع إخوتي. آمين.\",\"x\":\"البرص كان مرضًا يعزل صاحبه عن المجتمع. والمسيح لم يشفه بالكلمة فقط، بل لمسه أولًا. ففي حياتنا جراح تعزلنا بالخجل والشعور بعدم الاستحقاق. والمسيح يقترب منها ولا يخاف. ثم ينصحه أن يذهب للكاهن، فالشفاء يعيده إلى الجماعة. وبعد ذلك كان المسيح ينفرد في البرية ليصلي، فهو مصدر قوته.\\nقل اليوم للمسيح عن جرح تخجل منه: «إن أردت تقدر أن تشفيني»، وانتظر لمسته.\"},{\"t\":\"مرض بلا شكوى\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سينكليتيكي: إذا أزعجنا المرض فلا نحزن إن لم نقدر أن نسبّح الرب بصوتنا، لأن هذا لتنقية الأهواء. المرض تعب، لكنه قد يصير مدرسة صبر وشكر. صلِّ اليوم من أجل مريض واشكر على صحتك.\",\"p\":\"يا رب، اشفِ المرضى واعطِهم صبرًا وسلامًا. وعلّمني أن أشكرك في المرض وفي الصحة، وأجد فيهما محبتك. آمين.\",\"x\":\"المرض بلا شكوى مدرسة في الشكر والصبر، وهي نعمة لمن يتقبلها. تدريب: ما الذي تتذمر منه اليوم؟ حوّله إلى شكر ولو بكلمة.\",\"fq\":536}]},\"3-8\":{\"th\":\"الإيمان الواثق\",\"m\":[{\"t\":\"عليك توكلت\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"يا إلهي عليك توكلت. فلا تخزني إلى الأبد.\",\"r\":\"عبارة المرنم قصيرة وصادقة: «يا إلهي عليك توكلت، فلا تخزني إلى الأبد». الإيمان الواثق ليس أن أضمن النتيجة بل أن أسلّمها. في أمر لا تعرف كيف سينتهي اليوم، كرّر هذه الجملة بهدوء كلما عاد القلق.\",\"p\":\"يا إلهي، عليك توكلت، فلا تخزني إلى الأبد. ثبّت إيماني حين تغيب النتائج، واجعلني واثقًا بأنك أمين. آمين.\",\"x\":\"كلمة التوكل أصغر من أن نتأملها طويلًا، لكنها أعمق من أن نستنفدها: عليك توكلت. تدريب: كرر هذه العبارة بين مشاغل اليوم كلما شعرت بقلق.\"},{\"t\":\"لا تخف آمن فقط\",\"ref\":\"مرقس ٥: ٣٦\",\"bk\":\"مرقس\",\"v\":\"فسمع يسوع لوقته الكلمة التي قيلت، فقال لرئيس المجمع: «لا تخف! آمن فقط».\",\"r\":\"«لا تخف، آمن فقط». قيلت هذه الكلمات لرجل سمع أسوأ خبر في حياته. وسط اليأس يأتيه صوت المسيح الهادئ. الإيمان لا ينكر الواقع، لكنه يضع المسيح فوقه. وأنا أحتاج أن أسمع هذه الكلمة في كل مرة تأتيني فيها أخبار مخيفة.\",\"p\":\"يا رب، اسمع صراخي في ضيقي. قل لقلبي: لا تخف. ثبّت إيماني في كل خوف، وأقم ما مات من رجاء وفرح في حياتي. آمين.\",\"x\":\"لاحظ أن المسيح قالها بعد سماع الخبر، لا قبله. فالإيمان يُختبر عند المحنة. وقد سار معه إلى بيته ودخل وهو يعلم النتيجة. وهذا يؤكد أن حضوره يغيّر الأمور. وقد صرف المنتحبين وأخذ والدي الصبية وأمسك بيدها. فهو إله يهتم بالتفاصيل. ويمكننا أن نصلي في وقت الألم ونتشبث بكلمته.\\nعندما يأتيك خبر مقلق اليوم، قل بصوت داخلي: «لا تخف آمن فقط»، وسلمه لله.\"},{\"t\":\"الله محب\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل ثلاثة شيوخ الأب سيسوى عن أمور مخيفة، فأجاب أنه لا يذكر شيئًا منها لأنه يعرف أن الله محب ويرجو أن يرحمه. هذا هو الإيمان الواثق: أن أثق بمحبته أكثر من خوفي. هذه الجملة تكفي لنهارك.\",\"p\":\"يا رب، أعرف أنك محب، وأرجو رحمتك. ثبّتني على هذا الإيمان البسيط في كل ظرف. آمين.\",\"x\":\"الله محب، وهذه أساس كل ما نؤمن به، وعلى أساسها نحتمل. تدريب: عند أول ضيق اليوم، ذكّر نفسك أن الله محب قبل أن تتحرك.\",\"fq\":493}]},\"3-9\":{\"th\":\"محبة الأعداء\",\"m\":[{\"t\":\"باركناكم باسم الرب\",\"ref\":\"المزمور ١٢٨ (١٢٩) — الغروب\",\"v\":\"ولم يقل المجتازون إن بركة الرب عليكم. باركناكم باسم الرب هلليلويا.\",\"r\":\"بعد ذكر الأعداء الذين حاربوا شعب الله، يختم المزمور بكلمة بركة: «باركناكم باسم الرب». هذه محبة تتحدى المنطق. وهي ثمرة قلب لا يحمل مرارة. من أساء إليك مؤخرًا؟ ابدأ اليوم بأن تذكره في صلاتك بالخير.\",\"p\":\"يا رب، علّمني أن أبارك من حاربني. انزع من قلبي المرارة والحقد، واملأه بمحبتك التي تغفر وتبارك. آمين.\",\"x\":\"يختم المزمور بالبركة بعد ذكر الأعداء، فالمؤمن يحمل بركة حتى لمن عاداه. تدريب: ادع اليوم بخير لمن أساء إليك بالاسم.\"},{\"t\":\"يا أبتاه اغفر لهم\",\"ref\":\"لوقا ٢٣: ٣٤\",\"bk\":\"لوقا\",\"v\":\"فقال يسوع: «ياأبتاه، اغفر لهم، لأنهم لا يعلمون ماذا يفعلون». وإذ اقتسموا ثيابه اقترعوا عليها.\",\"r\":\"«يا أبتاه اغفر لهم لأنهم لا يعلمون ماذا يفعلون». هذه كلمات المسيح بين المسامير. لم يهدد ولم يلعن، بل صلّى. وإن كان هذا فعل المسيح بمن صلبه، فما حجة من لا يغفر لأخيه؟ أحتاج أن أنظر إلى الصليب حين أصعب عليّ المسامحة.\",\"p\":\"يا رب يسوع، يا من غفرت لصالبيك، علّمني أن أغفر. حرر قلبي من المرارة، وأعطني أن أصلي لأعدائي كما صليت أنت. آمين.\",\"x\":\"الغفران ليس نسيانًا بل قرار بتسليم الحق لله. والمسيح غفر قبل أن يعتذر أحد. وكثير من الأحيان لا يأتي الاعتذار أبدًا، فإن انتظرناه عشنا أسرى. والغفران يحررنا نحن أولًا. وقد غفر استفانوس بالمثل. فالكنيسة نمت بدماء الشهداء وغفرانهم. ولنطلب النعمة لنغفر ما لا نقدر أن نغفره بقوتنا.\\nقل اليوم هذه الكلمات عن شخص أساء إليك: «يا رب اغفر له»، حتى لو لم تشعر بها بعد.\"},{\"t\":\"صلِّ أولًا من أجل أعدائك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب زينون أن من يريد الله أن يستجيب صلاته عليه، حين ينهض للصلاة، أن يصلّي أولًا من أجل أعدائه. تبدأ استجابة الله من داخلنا بالتطهر من الحقد. قبل أن تطلب لنفسك اليوم، اطلب لمن يعاديك.\",\"p\":\"يا رب، أصلي من أجل أعدائي وأطلب لهم الخير. طهّر قلبي من كل حقد، واستجب صلاتي كما استجبت لمن غفر. آمين.\",\"x\":\"الصلاة من أجل الأعداء أولًا تنزع المرارة من القلب، وتفتح الباب لمحبة المسيح. تدريب: ابدأ صلاتك اليوم بذكر من لا تحبه، قبل من تحبهم.\",\"fq\":116}]},\"3-10\":{\"th\":\"الحضور الإلهي\",\"m\":[{\"t\":\"عيناي إلى الرب في كل حين\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"عيناي تنظران إلى الرب في كل حين. لأنه يجتذب من الفخ رجلي.\",\"r\":\"يعلّمنا المرنم أن نبقي عيوننا على الرب في كل حين، لأنه يجتذب من الفخ رجلنا. الحضور الإلهي ليس شعورًا يومًا ويغيب يومًا، بل التفات مستمر. اجعل ساعة هاتفك مذكّرًا: عند كل ساعة تامة ارفع عينيك إلى الرب لحظة.\",\"p\":\"عيناي تنظران إليك يا رب في كل حين، فاجتذب من الفخ رجلي. اجعلني واعيًا لحضورك في عملي وطريقي وبيتي. آمين.\",\"x\":\"العيون المرفوعة إلى الرب في كل حين تتحرر من الفخاخ، فمن ينظر إليه لا ينظر إلى ما يضله. تدريب: اختر لحظة اليوم ترفع فيها عينيك للسماء ببساطة قبل أن تعود إلى عملك.\"},{\"t\":\"حقًا إن الرب في هذا المكان\",\"ref\":\"التكوين ٢٨: ١٦\",\"bk\":\"التكوين\",\"v\":\"فاستيقظ يعقوب من نومه وقال: «حقا إن الرب في هذا المكان وأنا لم أعلم!».\",\"r\":\"«حقًا إن الرب في هذا المكان وأنا لم أعلم». كان يعقوب هاربًا خائفًا وحيدًا، ومع ذلك كان الله هناك. وكم مرة كان الله في مكاني وأنا لم أنتبه! ربما أحتاج أن أقول في كل مكان: «حقًا إن الرب هنا».\",\"p\":\"يا رب، افتح عينيّ لأعرف أنك حاضر في كل مكان. اجعل بيتي وعملي بيوتًا لك، وعلّمني أن أبني مذبح صلاة حيثما أكون. آمين.\",\"x\":\"قبل هذا اللقاء كان يعقوب يعتمد على حيلته. والله ظهر له في أضعف حالاته ليعطيه وعد البركة والحماية. وقد سمّى المكان «بيت إيل» أي بيت الله. وكل مكان نذكر فيه الله يصير بيتًا له. وربما يكون مكتبك أو مطبخك أو سريرك. فلنتعلم أن نبني «مذبحًا» صغيرًا من الصلاة في كل مكان نحل فيه.\\nاختر مكانًا في بيتك أو عملك وسمّه «بيت إيل» اليوم بصلاة قصيرة فيه.\"},{\"t\":\"كجندي في حضرة الملك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب سيرابيون الإنسان القائم في حضرة الله بجنود الملك الذين لا يلتفتون يمنة ويسرة، فلا تخيفه أعمال العدو. من يركّز على الله لا تشغله التفاصيل المخيفة. حدّد اليوم ما يشتتك وأعد عينك إلى الله.\",\"p\":\"يا رب، ثبّت نظري عليك فلا يخيفني العدو ولا تشغلني الأمور. كن أمامي في كل حين. آمين.\",\"x\":\"الجندي في حضرة الملك لا يتهاون ولا يتشتت، وهكذا نحن في حضرة الله. تدريب: تعامل اليوم مع كل ما تفعله كأن الله يراه، لأنه يراه.\",\"fq\":520}]},\"3-11\":{\"th\":\"الصليب قوة الله\",\"m\":[{\"t\":\"بسطتَ يديك على الصليب\",\"ref\":\"قطعة السادسة (٤)\",\"v\":\"صنعت خلاصا في وسط الأرض كلها أيها المسيح إلهنا، عندما بسطت يديك الطاهرتين على عود الصليب.\",\"r\":\"في وسط الأرض بسط المسيح يديه ليحتضن العالم كله. الصليب في أعيننا ليس رمز ضعف بل مكان انتصار المحبة. اصنع اليوم علامة الصليب ببطء وتأمل أن هذه اليد التي بُسطت لك لا تزال مفتوحة.\",\"p\":\"أيها المسيح إلهنا، صنعت خلاصًا في وسط الأرض عندما بسطت يديك على الصليب. أنا أيضًا أتمسك بصليبك قوةً وفخرًا لي. آمين.\",\"x\":\"بسط المسيح يديه على الصليب ليحتضن العالم، فالصليب لقاء لا عقاب. تدريب: اصنع علامة الصليب الليلة ببطء وبوعي، وفكر في الأيدي المبسوطة.\"},{\"t\":\"أجذب إليّ الجميع\",\"ref\":\"يوحنا ١٢: ٣٢\",\"bk\":\"يوحنا\",\"v\":\"وأنا إن ارتفعت عن الأرض أجذب إلي الجميع».\",\"r\":\"«وأنا إن ارتفعت عن الأرض أجذب إليّ الجميع». ارتفاع المسيح على الصليب ليس إذلالًا بل جاذبية. كل من نظر إليه بإيمان وجد فيه حبًا لا يُقاوم. وأنا أيضًا قد انجذبت إليه بمحبته الكبيرة لي.\",\"p\":\"يا رب يسوع المرفوع على الصليب، اجذبني إليك وأجذب كل من أحب. اجمع المتفرقين، واشفِ كل انقسام بمحبتك التي لا تنتهي. آمين.\",\"x\":\"اليهود ظنوا أن الصلب يمحو اسم المسيح، لكنه صار سبب انتشار الكنيسة. وفي البرية، رُفعت الحية النحاسية فمن نظر إليها شُفي، وهذه صورة للمسيح المرفوع. وعندما نشعر بالتشتت والانقسام، فإن الصليب يجمعنا. فهو يقرّبنا من الله ويقرّبنا من بعضنا. والمحبة التي علّقته هناك هي التي تسع الجميع.\\nاجلس لحظات أمام صورة الصليب أو أيقونته، وأعد قلبك إلى الله، ثم صلِّ لمن تعرفه ابتعد عن الكنيسة.\"},{\"t\":\"احمل صليبك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يرشد الأب نيلوس من أراد أن يصلي دون ارتباك أن يذهب ويبيع ما له ويعطيه للمساكين، ثم يحمل صليبه وينكر نفسه. قوة الصليب تظهر في تخلينا عما يعطلنا. ما الذي تحتاج أن تتخلى عنه اليوم لتصلي بحرية؟\",\"p\":\"يا رب، أعطني أن أحمل صليبي وأنكر نفسي. حرّرني مما يربطني بالأرض حتى أصلي إليك بقلب حر. آمين.\",\"x\":\"حمل الصليب يعني قبول ما يأتي من الله والناس بصبر. تدريب: ما الصليب الذي تتهرب منه؟ اقبله اليوم بلا شكوى.\",\"fq\":291}]},\"3-12\":{\"th\":\"الرجاء في الألم\",\"m\":[{\"t\":\"في العشاء بكاء وفي الصباح سرور\",\"ref\":\"المزمور ٢٩ (٣٠) — الثالثة\",\"v\":\"في العشاء يحل البكاء. وفي الصباح السرور.\",\"r\":\"كلمات المرنم القليلة تحمل منطق الرجاء: البكاء لا يبقى، والسرور يأتي في الصباح. الألم مرحلة وليس هوية. إن كنت في ليلة ثقيلة اليوم، ضع الصباح في قلبك كوعد من الله، حتى لو لم تره بعد.\",\"p\":\"يا رب، إن حلّ البكاء في العشاء فاجعل السرور في الصباح. ارفعني من حزني، وأعطني أن أرجو فيك مهما طالت ليلتي. آمين.\",\"x\":\"في العشاء بكاء وفي الصباح سرور، فالألم له نهاية. الله لا يترك محنة بلا فرج. تدريب: اكتب أمرًا مؤلمًا وأتبعه بعبارة: وفي الصباح سرور، وصلّ بها.\"},{\"t\":\"أحسب أن آلام هذا الزمان\",\"ref\":\"رومية ٨: ١٨\",\"bk\":\"رومية\",\"v\":\"فإني أحسب أن آلام الزمان الحاضر لا تقاس بالمجد العتيد أن يستعلن فينا.\",\"r\":\"«فإني أحسب أن آلام الزمان الحاضر لا تقاس بالمجد العتيد أن يستعلن فينا». لا ينكر بولس الألم، لكنه يضعه في الميزان. وحين أرى الصورة الكاملة أجد أن الضيق مؤقت والمجد دائم. وهذا الرجاء لا يلغي دموعي، لكنه يمنعها من أن تصير يأسًا.\",\"p\":\"يا رب، علّمني أن أحتمل الألم بالرجاء. أرني المجد الذي تعدّه، وامنحني قوة وصبرًا، وكن معي في كل ضيق. آمين.\",\"x\":\"بولس تحدث عن آلام شخصية تحملها من ضرب وسجن وغرق. ومع ذلك يقول إنها لا تقاس. وهذه ليست رومانسية بل يقين من عاش القيامة. والكنيسة تعلّم أن الألم مشاركة في آلام المسيح. وعندما نتألم نكون أقرب منه، وهو يشعر بنا. وكل دمعة محسوبة عنده. فالرجاء يجعلنا نحتمل بسلام.\\nاكتب ألمًا تحمله الآن، وبجواره جملة: «هذا مؤقت والمجد أعظم»، وصلِّ بها.\"},{\"t\":\"بصبركم تقتنون نفوسكم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس إن الخلاص يُقتنى في وقت الضيقات، وإن الأردأ أن يتبع الإنسان قلبه بدل شريعة الله. فالضيق فرصة لا عقوبة. فكّر في ضيق تمرّ به: ما الخير الذي يمكن أن يخرج من الصبر عليه؟\",\"p\":\"يا رب، علّمني أن أقتني نفسي بالصبر في الضيقات. وفي ألمي أرني خيرًا ينمو بنعمتك. آمين.\",\"x\":\"الألم يعلمنا ما لا يعلمه الراحة، وما نتعلمه في الظلمة نحمله في النور. تدريب: اسأل نفسك ماذا علمني الألم هذا العام، واشكر عليه.\",\"fq\":171}]},\"3-13\":{\"th\":\"لص اليمين\",\"m\":[{\"t\":\"اذكرني يا رب\",\"ref\":\"قطعة التاسعة (٤)\",\"v\":\"لما أبصر اللص رئيس الحياة على الصليب معلقا، قال: ... اذكرني يا رب متى جئت في ملكوتك.\",\"r\":\"في الصلب يرى اللص ما لم يره المتعلمون: أن المصلوب إله. وبكلمة واحدة تحوّل من مجرم إلى شريك في الفردوس. ليس التبرير في كثرة الأعمال بل في صدق الطلب. قلها اليوم لله من قلبك: اذكرني يا رب.\",\"p\":\"اذكرني يا رب متى جئت في ملكوتك. أنا الخاطئ، أعترف أنك الإله المتجسد. اقبل بساطة اعترافي، وأدخلني فردوسك برحمتك. آمين.\",\"x\":\"صلاة اللص كلمة واحدة: اذكرني. فكانت كافية. الله لا يطلب أدلة طويلة، بل قلبًا صادقًا. تدريب: صلِّ اليوم بكلمة واحدة تخرج من القلب، دون تنميق.\"},{\"t\":\"اطلبوا الرب\",\"ref\":\"إشعياء ٥٥: ٦–٧\",\"bk\":\"إشعياء\",\"v\":\"اطلبوا الرب ما دام يوجد. ادعوه وهو قريب. ليترك الشرير طريقه، ورجل الإثم أفكاره، وليتب إلى الرب فيرحمه، وإلى إلهنا لأنه يكثر الغفران.\",\"r\":\"«اطلبوا الرب ما دام يوجد، ادعوه وهو قريب». الدعوة ليست مجرد فرصة، بل هي نعمة. فالله قريب الآن. وربما لا أشعر بقربه دائمًا لكنه يقول إنه قريب. وعندما أرجع إليه يرحمني ويكثر الغفران. لا شروط معقدة، فقط رجوع.\",\"p\":\"يا رب، أنت قريب مني. أطلبك الآن وأعود إليك، فارحمني واغفر لي كثيرًا، وأعطني قوة أن أتوب كل يوم. آمين.\",\"x\":\"ثم يقول الله: «لأن أفكاري ليست أفكاركم». فمقاييس الله في الغفران أوسع من مقاييسنا. نحن نحاسب بالعدل البشري، وهو يغفر بالنعمة. وهذا لا يسوغ التأجيل، فالكلمات «ما دام يوجد» تنبهنا إلى الإلحاح. ولنتذكر أن التوبة ليست بداية جديدة بالقوة بل بنعمة الله التي تعمل فينا. فنبدأ من حيث نحن.\\nحدد اليوم وقتًا للتوبة والاعتراف، وإن كان سريعًا فاكتب موعدك مع أب اعترافك.\"},{\"t\":\"برّر بكلمة واحدة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب كسنثيا إن اللص على الصليب تبرر بكلمة واحدة، بينما خسر يهوذا في ليلة واحدة كل ما كان له. لا يفتخر أحد بسيرته ولا ييأس أحد من سقوطه. صلِّ اليوم بتواضع: لا أعتمد على ما أنا فيه بل على رحمتك.\",\"p\":\"يا رب، لا أعتمد على برّي ولا ييأس قلبي من خطاياي. اقبلني كما قبلت اللص التائب وأعطني فردوسك. آمين.\",\"x\":\"كلمة واحدة تبرر إن كانت صادقة، وهي توبة اللص. تدريب: قبل أن تنام، قل لله كلمة اعتراف واحدة بصدق كامل.\",\"fq\":307}]},\"3-14\":{\"th\":\"الراعي الصالح\",\"m\":[{\"t\":\"الرب يرعاني\",\"ref\":\"المزمور ٢٢ (٢٣) — الثالثة\",\"v\":\"الرب يرعاني فلا يعوزني شئ. في مراع خضر يسكنني، إلى ماء الراحة يوردني. يرد نفسي. يهدني إلى سبل البر من أجل اسمه.\",\"r\":\"أول ما يقوله المرنم عن الراعي أنه لا ينقص شيئًا: الرعي والماء والراحة والهداية. المسيح هو الراعي الصالح الذي بذل نفسه عن الخراف. فتأمّل اليوم في ما يعوزك فعلًا، وهل هو ما تظن أم ما يعرفه الراعي؟\",\"p\":\"الرب راعيّ فلا يعوزني شيء. أسكنني في مراع خضر، وأوردني إلى ماء الراحة، وردّ نفسي، واهدني إلى سبل البر من أجل اسمك. آمين.\",\"x\":\"الرب راعٍ لا ينقص معه شيء، فالرعاية تشمل الماء والمرعى والحماية. تدريب: اذكر ثلاث رعايات من الله لك هذا الأسبوع وشكره عليها.\"},{\"t\":\"يبذل نفسه عن الخراف\",\"ref\":\"يوحنا ١٠: ١١\",\"bk\":\"يوحنا\",\"v\":\"أنا هو الراعي الصالح، والراعي الصالح يبذل نفسه عن الخراف.\",\"r\":\"«أنا هو الراعي الصالح، والراعي الصالح يبذل نفسه عن الخراف». لست مجرد عضو في قطيع كبير، بل أنا خروفه الذي يعرفه بالاسم ويبذل نفسه عنه. وكل ما أمر به، يمر به راعيّ الذي لا يهرب. وهذا يعطيني أمانًا عميقًا لا تعطيه أي مؤسسة.\",\"p\":\"يا راعي الخراف العظيم، أشكرك لأنك بذلت نفسك عني. احفظني في قطيعك، ولا تدعني أضل، وبارك رعاتنا وكل من يخدم ويتعب. آمين.\",\"x\":\"الراعي في الشرق كان يعيش مع قطيعه ويعرف كل واحد. والمسيح يستعمل هذه الصورة ليبين قربه. والأجير يهرب لأن الخراف ليست له. أما المسيح فقد بذل نفسه حقيقة على الصليب. ونحن نرى في الكهنة والمسؤولين وجهًا من رعايته، لكن الراعي الأعظم هو هو. وكلما شعرت بالضياع تذكر أنه يبحث عنك.\\nاشكر الله اليوم على من استخدمهم راعين في حياتك، وصلِّ من أجل راعيك.\"},{\"t\":\"التصق بمن يعرف طريق الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوجّه الأب بيمن من تعب من نفسه: اذهب والتصق بإنسان يخاف الله، وبملازمتك إياه يعلمك كيف تخاف الله. هكذا تُعرف الخراف: تتبع راعيًا وتتعلم من رعاته. من تتبع اليوم في حياتك الروحية؟ ومن هو الأب الذي تسأله؟\",\"p\":\"يا راعي نفسي، ضع في طريقي من يعلّمني مخافتك. وثبّتني في اتباعك أنت الراعي الصالح. آمين.\",\"x\":\"الالتصاق بمن يعرف طريق الله يحفظ من الضلال، لأن الراعي يُعرف بقطيعه. تدريب: اختر شخصًا حكيمًا واستشره في أمر يخص حياتك الروحية.\",\"fq\":362}]},\"3-15\":{\"th\":\"سماع الصوت\",\"m\":[{\"t\":\"إني أسمع ما يتكلم به الرب\",\"ref\":\"المزمور ٨٤ (٨٥) — السادسة\",\"v\":\"إني أسمع ما يتكلم به الرب الإله، لأنه يتكلم بالسلام لشعبه ولقديسيه؛ وللذين رجعوا إليه بكل قلوبهم.\",\"r\":\"يعلن المرنم أنه مستعد لأن يسمع ما يتكلم به الرب، لأنه يتكلم بالسلام لشعبه وللذين رجعوا إليه بكل قلوبهم. السمع يسبق السلام. فاجلس اليوم خمس دقائق دون طلب ولا شكوى، وقل: تكلم يا رب فعبدك سامع.\",\"p\":\"يا رب، إني أسمع ما تتكلم به، فتكلّم بالسلام لشعبك ولقديسيك. اجعلني من الراجعين إليك بكل قلوبهم. آمين.\",\"x\":\"المرنم مستعد لأن يسمع ما يتكلم به الرب، لأن الله يتكلم بالسلام لشعبه. السماع أول الطاعة. تدريب: اجلس اليوم دقيقة صمت وقل: تكلم يا رب فإن عبدك يسمع.\"},{\"t\":\"يدعو خرافه بأسمائها\",\"ref\":\"يوحنا ١٠: ٣\",\"bk\":\"يوحنا\",\"v\":\"لهذا يفتح البواب، والخراف تسمع صوته، فيدعو خرافه الخاصة بأسماء ويخرجها.\",\"r\":\"«ويدعو خرافه الخاصة بأسماء ويخرجها». المسيح يعرفني باسمي، لست رقمًا في كنيسة. ويخرجني من حظيرة الخوف والتعود إلى مرعى جديد. وكل مرة يناديني فيها باسمي أشعر بقيمتي، وأطمئن أنني معروف ومحبوب كما أنا.\",\"p\":\"يا رب، أنت تعرفني باسمي. ناد قلبي ولا تدعني أتجاهل صوتك، وأخرجني من كل ما يعيقني، لأتبعك بفرح وثقة. آمين.\",\"x\":\"النداء بالاسم علامة قرب. وقد ناد المسيح مريم المجدلية باسمها عند القبر فعرفته. وكل واحد منا له نداء خاص. وقد يكون النداء إلى خدمة أو توبة أو راحة. ومن يعلم أنه معروف باسمه يتشجع أن يتبع. والمهم ألا ننتظر صوتًا مدويًا، فهو غالبًا همسة هادئة.\\nاسأل المسيح اليوم: ماذا تريدني أن أترك لأتبعك؟ ودوّن ما يخطر ببالك.\"},{\"t\":\"الغني الذي لا نسمعه\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب مكاريوس: ربنا هو الغني ويحبنا ولكننا لا نريد أن نسمع له، أما عدونا فهو فقير ويكرهنا إلا أننا نحبه ونحب نتانته. نسمع أصواتًا كثيرة تبدو جذابة وتفرغنا. اختر اليوم أن تنصت لصوت الله قبل كل صوت آخر.\",\"p\":\"يا رب، أنت الغني الذي يحبنا، فاجعلني أسمع صوتك وأعرضه على ضجيج العالم. آمين.\",\"x\":\"الغني الذي لا نسمعه هو الله، لأن ضجيج الحياة أعلى منه. تدريب: أغلق الضجيج لدقائق اليوم، وانتبه لما يقوله الله في هدوء.\",\"fq\":243}]},\"3-16\":{\"th\":\"الكنيسة بيت الله\",\"m\":[{\"t\":\"ما أحلى مساكنك\",\"ref\":\"المزمور ٨٣ (٨٤) — السادسة\",\"v\":\"مساكنك محبوبة يا رب إله القوات. تشتاق وتذوب نفسي للدخول إلى ديار الرب. قلبي وجسمي قد ابتهجا بالإله الحي.\",\"r\":\"يعبّر المرنم عن شوق إلى بيت الله: مساكنك محبوبة، ونفسي تشتاق وتذوب للدخول إلى ديار الرب. الكنيسة بيت يبتهج فيه القلب والجسد. فكّر في آخر مرة اشتقت فيها إلى الكنيسة، وجدد هذا الشوق اليوم بصلاة.\",\"p\":\"ما أحلى مساكنك يا رب الجنود. تشتاق نفسي للدخول إلى ديارك، فيبتهج قلبي وجسمي بالإله الحي. آمين.\",\"x\":\"الشوق إلى بيت الله علامة محبة، ومساكنه محبوبة. والكنيسة بيتنا الذي نرجع إليه. تدريب: خصص وقتًا في الأسبوع لزيارة الكنيسة بغير مناسبة.\"},{\"t\":\"كانوا يواظبون\",\"ref\":\"أعمال الرسل ٢: ٤٢\",\"bk\":\"أعمال الرسل\",\"v\":\"وكانوا يواظبون على تعليم الرسل، والشركة، وكسر الخبز، والصلوات.\",\"r\":\"«وكانوا يواظبون على تعليم الرسل والشركة وكسر الخبز والصلوات». أربعة أعمدة: التعليم والشركة والإفخارستيا والصلاة. ومن واظب عليها ثبت. والمواظبة ليست سهلة، لكنها سر النمو. وحين أنتظم فيها أجد قوة تحملني في الأيام الثقيلة.\",\"p\":\"يا رب، علّمني المواظبة على تعليمك وصلواتك وأسرارك. اجعلني عضوًا في جسدك أحب إخوتي وأخدمهم، وأشارك في فرح كنيستك. آمين.\",\"x\":\"ثمرة هذه المواظبة كانت فرحًا وبساطة قلب ومحبة عملية: «كان عندهم كل شيء مشتركًا». فالعبادة لا تفصل عن الحياة. ومن يعيش الشركة لا يحتمل جوع أخيه. وبهذا كانوا «ذوي نعمة عند جميع الشعب». وكل واحد منا مدعو أن يعيش هذه الأعمدة في حدود ظروفه.\\nاختر عمودًا من الأربعة تحتاج أن تقوّيه هذا الأسبوع، وضع له خطة بسيطة.\"},{\"t\":\"ساعات الاجتماع وساعات الخلوة\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينبّه الأب بيمن إلى النمو الخفي: ألا نهمل ساعات الاجتماع وساعات الاختلاء. أي نعيش الكنيسة جماعة وفردًا معًا. هل تنتظم في اجتماعك الكنسي كما تنتظم في خلوتك؟ اختر ما تحتاج أن تقوّيه.\",\"p\":\"يا رب، علّمني أن أحب الاجتماع في بيتك كما أحب الخلوة معك. اجعلني عضوًا حيًا في كنيستك. آمين.\",\"x\":\"لكل شيء وقته: وقت للاجتماع ووقت للخلوة، ومن يحفظ التوازن بينهما يثمر. تدريب: نظم يومك اليوم ليكون فيه وقت للجماعة ووقت للخلوة.\",\"fq\":439}]},\"3-17\":{\"th\":\"خبز الحياة\",\"m\":[{\"t\":\"أعطوهم أنتم ليأكلوا\",\"ref\":\"إنجيل التاسعة\",\"v\":\"فأخذ الخمس خبزات والسمكتين، ونظر إلى السماء، وباركها وقسمها، وأعطى التلاميذ ليضعوا أمام الجموع. فأكلوا جميعهم وشبعوا.\",\"r\":\"أمام جموع جائعة لم يكن عند التلاميذ إلا خمس خبزات وسمكتان، لكن في يد المسيح صارت كافية. الخبز المبارك يشبع الجميع. ما القليل الذي في يدك اليوم؟ سلّمه للمسيح ليباركه، ولا تقل إنه لا يكفي.\",\"p\":\"يا رب، خذ القليل الذي عندي وباركه. أشبع به جوعي وجوع من حولي، وعلّمني أن أسلّم لك ما عندي بثقة. آمين.\",\"x\":\"خمس خبزات وسمكتان لم تكفِ بحساب البشر، لكنها كفت حين وضعت في يد الرب. الله يستخدم القليل المقدم. تدريب: قدّم اليوم ما عندك مهما بدا قليلًا، وقل: بارك يا رب.\"},{\"t\":\"الخبز الحي\",\"ref\":\"يوحنا ٦: ٥١\",\"bk\":\"يوحنا\",\"v\":\"أنا هو الخبز الحي الذي نزل من السماء. إن أكل أحد من هذا الخبز يحيا إلى الأبد. والخبز الذي أنا أعطي هو جسدي الذي أبذله من أجل حياة العالم».\",\"r\":\"«أنا هو الخبز الحي الذي نزل من السماء، إن أكل أحد من هذا الخبز يحيا إلى الأبد». المسيح لا يعطيني تعليمًا فقط بل يعطيني نفسه. وفي سر الإفخارستيا أتناول جسده ودمه لأثبت فيه ويثبت فيّ. فما أعظم نعمة القداس!\",\"p\":\"يا رب يسوع، أنت الخبز الحي. أشكرك لأنك تعطيني نفسك. اجعلني أستعد للمناولة بقلب نقي، وأثبت فيك وتثبت فيّ. آمين.\",\"x\":\"قال المسيح هذا بعد معجزة إشباع الجموع، فانتقل من الخبز المادي إلى الخبز السماوي. وكثيرون تركوه لأن الكلام صعب، لكن بطرس قال: «إلى من نذهب؟ كلام الحياة الأبدية عندك». ونحن في الكنيسة نؤمن بالحضور الحقيقي. ولذلك نستعد للمناولة بالتوبة والصوم. والمناولة تعطينا قوة نحيا بها وحياة لا تفنى.\\nإن كنت تناول فاستعد لها بصلاة وتوبة، وإن لم تتناول اليوم فاشتق إليها بكلمة شكر.\"},{\"t\":\"يد الله التي تشبع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيرينيوس إنه أمضى السنة يجني ويخيط ويحوك، لكن لولا يد الله التي كانت تشبعه ما أمكن أن يشبع. العمل وسيلة والشبع من الله. تأمّل اليوم في خبزك اليومي كيف جاءك، واشكر الذي يعطي.\",\"p\":\"يا رب، أنت الذي تشبعنا بعمل أيدينا وبنعمتك. أشكرك على خبزي اليومي، ولا تحرم أحدًا من هذا الشبع. آمين.\",\"x\":\"يد الله هي التي تشبع، لا مصادرنا. تدريب: اعطِ طعامًا أو مساعدة لشخص اليوم وانظر كيف يبارك الله القليل.\",\"fq\":524}]},\"3-18\":{\"th\":\"القيامة والحياة\",\"m\":[{\"t\":\"فلن أموت بل أحيا\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"فلن أموت بعد، بل أحيا وأحدث بأعمال الرب. تأديبا أدبني الرب وإلى الموت لم يسلمني.\",\"r\":\"بعد التأديب والألم يعلن المرنم أنه لن يموت بل يحيا ويحدّث بأعمال الرب. هذه لغة الرجاء الذي بلغ القيامة. المسيح يهب الحياة التي لا تنتهي، فالموت لم يعد آخر الكلام. اذكر اليوم عزيزًا فارقك، وقل: الذي أحيا المسيح سيحيينا.\",\"p\":\"يا رب، أنا لن أموت بعد بل أحيا وأحدّث بأعمالك. أدبتني، لكنك إلى الموت لم تسلمني. أشكرك على رجاء القيامة. آمين.\",\"x\":\"بعد التأديب يعلن المرنم أنه لن يموت بل يحيا، فالقيامة تتجاوز الموت. تدريب: ما الذي مات فيك وتريد أن يقوم؟ اطلب من الله أن يقيمه.\"},{\"t\":\"باكورة الراقدين\",\"ref\":\"كورنثوس الأولى ١٥: ٢٠\",\"bk\":\"كورنثوس الأولى\",\"v\":\"ولكن الآن قد قام المسيح من الأموات وصار باكورة الراقدين.\",\"r\":\"«ولكن الآن قد قام المسيح من الأموات وصار باكورة الراقدين». الباكورة هي أول الثمر الذي يضمن أن الحصاد قادم. وقيامة المسيح هي ضمان قيامتي. ما يحدث له سيحدث لي. وهذا يغير نظرتي إلى الموت: إنه عبور لا فناء.\",\"p\":\"يا رب المسيح القائم، أشكرك لأنك باكورة الراقدين. ثبّت يقيني بقيامتك، واجعلني أعمل بلا يأس، وأحيا كمن ينتظر لقاءك. آمين.\",\"x\":\"قال بولس: «إن كان المسيح لم يقم فباطل إيماننا». فالقيامة هي أساس الإيمان كله. وليست حادثة معنوية بل واقعية. وهي تعطي معنى للحياة والجهاد والخدمة. لأن «تعبكم ليس باطلًا في الرب». فكل عمل نعمله بمحبة له قيمة أبدية. والموت آخر عدو يبطل.\\nاسأل نفسك: كيف يغير يقيني بالقيامة قراراتي هذا اليوم؟ وعش بهذا اليقين.\"},{\"t\":\"الموت نصب العينين\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سارة: «أضع رجلي على السلّم، وقبل أن أصعد عليه أجعل الموت نصب عيني». ذكر الموت عند المؤمن ليس تشاؤمًا بل يقظة، لأن وراءه القيامة. أي قرار اليوم يتغير إذا تذكرت أن عمرك محدود؟\",\"p\":\"يا رب، علّمني أن أذكر الموت بيقظة لا بخوف، وأن أحيا اليوم لك في رجاء قيامتك. آمين.\",\"x\":\"ذكر الموت دائمًا يرتب الأولويات ويعلّم الإنسان أن يحيا لما يبقى. تدريب: اسأل نفسك الليلة: لو كان هذا آخر يوم، هل أنا مصالح مع الجميع؟\",\"fq\":529}]},\"3-19\":{\"th\":\"نور المسيح\",\"m\":[{\"t\":\"أرسل نورك وحقك\",\"ref\":\"المزمور ٤٢ (٤٣) — الثالثة\",\"v\":\"أرسل نورك وحقك. فإنهما يهديانني ويصعدانني إلى جبلك المقدس وإلى مسكنك. فأدخل إلى مذبح الله تجاه وجه الله الذي يفرح شبابي.\",\"r\":\"يطلب المرنم نور الله وحقه ليهدياه إلى جبله المقدس. المسيح هو النور الذي يضيء كل إنسان. والنور لا يفرض نفسه بل يُطلب. اطلب اليوم نورًا لقرار محيّر، ثم تقدّم خطوة صغيرة بما يظهر لك.\",\"p\":\"أرسل نورك وحقك يا رب، فيهدياني ويصعداني إلى جبلك المقدس. أدخلني مذبحك، فيفرح شبابي بوجهك. آمين.\",\"x\":\"يطلب المرنم نور الله وحقه ليهدياه إلى جبله المقدس. نور المسيح هو دليلنا. تدريب: عند أي قرار اليوم قل: أرسل نورك وحقك يا رب.\"},{\"t\":\"كأولاد نور\",\"ref\":\"أفسس ٥: ٨\",\"bk\":\"أفسس\",\"v\":\"لأنكم كنتم قبلا ظلمة، وأما الآن فنور في الرب. اسلكوا كأولاد نور.\",\"r\":\"«لأنكم كنتم قبلًا ظلمة وأما الآن فنور في الرب، اسلكوا كأولاد نور». لاحظ: لم يقل «تحت النور» بل «نور»! النعمة غيّرت هويتي. وحياتي اليومية هي ترجمة هذه الهوية: صدق وطيبة وعدل. فلا أعيش كما كنت قبلًا.\",\"p\":\"يا رب، أشكرك لأنك جعلتني نورًا فيك. علّمني أن أسلك في الصلاح والبر والحق، وأمتحن ما يرضيك، وأبتعد عن أعمال الظلمة. آمين.\",\"x\":\"ثم يقول بولس: «ثمر النور هو في كل صلاح وبر وحق». وأعمال الظلمة ليست لنا، فنوبخها. لكن التوبيخ يبدأ من حياتنا نفسها. والسلوك يتطلب انتباهًا: «امتحنوا ما هو مرضي عند الرب». فلنختبر قراراتنا بهذه الأسئلة: هل هذا صلاح؟ هل هو حق؟ هل يجلب ضياء أم ظلمة؟\\nاسأل نفسك عن قرار اليوم: هل هو من ثمار النور؟ وعدّل ما يحتاج تعديلًا.\"},{\"t\":\"روح الله يستقر\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب كرونيوس: النفس إذا سهرت وجمعت ذاتها من التشتت وهجرت إرادتها، يستقر عليها روح الله. هذا هو النور الداخلي: سكنى الروح. ما الذي يشتتك اليوم؟ حدده، واجمع نفسك حول كلمة واحدة من الله.\",\"p\":\"يا رب، اجمع شتات فكري، ودعني أهجر إرادتي من أجلك. فيستقر عليّ روحك وينير داخلي. آمين.\",\"x\":\"يستقر روح الله على القلب الهادئ المتضع. تدريب: ابتعد اليوم عن الصراع الكلامي وابحث عن هدوء داخلي ليسكن فيك الروح.\",\"fq\":217}]},\"3-20\":{\"th\":\"العمل في الخفاء\",\"m\":[{\"t\":\"أسلك بدعة قلبي في بيتي\",\"ref\":\"المزمور ١٠٠ (١٠١) — التاسعة\",\"v\":\"لقد كنت أسلك بدعة قلبي في وسط بيتي. لم أضع أمام عيني أمرا يخالف الناموس.\",\"r\":\"يتعهد المرنم أن يسلك بدعة القلب في وسط بيته، حيث لا أحد يراه إلا الله. العمل في الخفاء هو الامتحان الحقيقي للحياة. اختر اليوم عملًا صغيرًا للخير لا يعرفه أحد، واجعله سرًا بينك وبين الله.\",\"p\":\"يا رب، أسلك بدعة قلبي في وسط بيتي، ولا أضع أمام عيني أمرًا يخالف ناموسك. اجعل خفايا حياتي مرضية لك. آمين.\",\"x\":\"السلوك بدعة القلب في البيت هو الاختبار الحقيقي، فما نفعله حين لا يرانا أحد يكشف من نحن. تدريب: افعل اليوم عملًا صالحًا في الخفاء لا يعلم به أحد.\"},{\"t\":\"عبيد بطّالون\",\"ref\":\"لوقا ١٧: ١٠\",\"bk\":\"لوقا\",\"v\":\"كذلك أنتم أيضا، متى فعلتم كل ما أمرتم به فقولوا: إننا عبيد بطالون، لأننا إنما عملنا ما كان يجب علينا».\",\"r\":\"«هكذا أنتم أيضًا متى فعلتم كل ما أمرتم به فقولوا إننا عبيد بطالون، لأننا إنما عملنا ما كان يجب علينا». ليست دعوة لتحقير الذات، بل لحماية الخدمة من الكبرياء. فكل ما أقوم به هو بنعمته، فلا أطالب بمكافأة بل أشكره أنه أشركني.\",\"p\":\"يا رب، أنت صاحب الفضل في كل ما أعمل. اجعلني عبدًا أمينًا فرحًا، يخدم بتواضع ويشكر دائمًا، ولا يطلب مجدًا لنفسه. آمين.\",\"x\":\"كلمة «بطالون» تعني أن لا فضل لنا. وهي حقيقة تحررنا من ضغط الإنجاز المستمر، وتفتح لنا باب الشكر. فإن نجحت فالفضل لله، وإن أخفقت فهو معي. والعبد الأمين يخدم بفرح لأنه يعرف أن سيده صالح. وكثيرًا ما يكون المتواضعون أكثر الناس راحة. فلنخدم دون أن نحمل هم التقدير.\\nعندما تنجز عملًا اليوم، قل: «شكرًا يا رب أنك أشركتني»، ولا تنتظر مديحًا.\"},{\"t\":\"أعمال بلا عين بشرية\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعدّد الأب يوسف الطيبي ثلاثة أمور مكرمة في عين الرب، منها أن يُتمّ الإنسان أعماله أمام الرب بدون أي أمر بشري. تتحول أعمالنا بهذا إلى صلاة. اختر أمرًا تفعله اليوم دون أن تنتظر شكرًا أو تقديرًا.\",\"p\":\"يا رب، علّمني أن أعمل لك وحدك، لا لأجل مديح الناس. اقبل خفي عملي واجعله بركة. آمين.\",\"x\":\"الأعمال بلا عين بشرية هي التي ينظر إليها الله بفرح. تدريب: أعطِ أو اخدم دون أن يعرف أحد، واحتفظ بالسر مع الله.\",\"fq\":205}]},\"3-21\":{\"th\":\"إكرام الوالدين\",\"m\":[{\"t\":\"البنون ميراث من الرب\",\"ref\":\"المزمور ١٢٦ (١٢٧) — الغروب\",\"v\":\"البنون ميراث من الرب أجرة ثمرة البطن. كالسهام بيد القوي كذلك أبناء المتيقظين.\",\"r\":\"ينظر المزمور إلى الأبناء كعطية من الله وميراث. من يقبل هذه النظرة يكرّم والديه ويكرّم أبناءه. الإكرام رباط يمتد في الاتجاهين. اتصل اليوم بأحد والديك أو من ربّاك، وقل له كلمة شكر صادقة.\",\"p\":\"يا رب، أشكرك على نعمة الأسرة التي أعطيتني. باركها واحفظها، وعلّمني أن أكرم والدي كما تريد، وأن أرى في الأبناء ميراثًا منك. آمين.\",\"x\":\"الأبناء ميراث من الرب، وإكرام الوالدين يبدأ من رؤية قيمة الأسرة كعطية. تدريب: اتصل بوالديك اليوم أو عبّر عن شكرك لهم، واطلب بركتهم.\"},{\"t\":\"تنهض بنوها ويطوبونها\",\"ref\":\"الأمثال ٣١: ٢٨\",\"bk\":\"الأمثال\",\"v\":\"يقوم أولادها ويطوبونها. زوجها أيضا فيمدحها:\",\"r\":\"«تقوم بنوها ويطوبونها، زوجها أيضًا فيمدحها». في اليوم الذي نكرّم فيه الأمهات أتأمل في ثمرة التعب الصامت: سنوات سهر وصلاة وعطاء. وأفكّر: كم مرة قلت لأمي «شكرًا» دون مناسبة؟ المديح الصادق هو أجمل هدية.\",\"p\":\"يا رب، أشكرك على كل أم ومن قامت مقامها. بارك تعبهن وعوّضهن، وامنحنا أن نكرمهن بالمحبة والشكر والصلاة. آمين.\",\"x\":\"المرأة المذكورة في الأمثال ليست بلا تعب، فهي تقوم باكرًا وتعمل بيديها. لكن غايتها خدمة بيتها بمخافة الرب. و«الحسن غش والجمال باطل، أما المرأة المتقية الرب فهي تمدح». فالقيمة في التقوى لا المظهر. وكل أم تحمل أولادها في صلاتها قبل ذراعيها. ومن عاش أمومة روحية في الكنيسة أو العمل فله نصيب في هذا المديح.\\nاكتب رسالة قصيرة بخط يدك تشكر فيها امرأة كان لها فضل في حياتك، وسلّمها لها.\"},{\"t\":\"الطاعة بالطاعة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ميّوس: «الطاعة تكون من أجل الطاعة، فالإنسان إذا أطاع الله فإن الله يطيعه». ليس هذا إذلالًا، بل ثقة بالله الذي يستجيب لمن يسمع له. أطع اليوم بفرح في أمر صغير يطلبه منك والداك أو من هو مسؤول عنك.\",\"p\":\"يا رب، علّمني الطاعة التي تكرّم، والسمع الذي يبني. بارك بيوتنا بوصيتك الأولى. آمين.\",\"x\":\"الطاعة بالطاعة تبني النفس، فمن يطيع في الصغير يطيع في الكبير. تدريب: نفذ اليوم توجيهًا صغيرًا بلا مجادلة.\",\"fq\":284}]},\"3-22\":{\"th\":\"حنان الله\",\"m\":[{\"t\":\"يا أم الرحمة والخلاص\",\"ref\":\"قطعة الخدمة الثانية (٣) — نصف الليل — الخدمة الثانية\",\"v\":\"السموات تطوبك أيتها الممتلئة نعمة. العروس التي بلا زواج. ونحن أيضا نمجد ميلادك غير المدرك. يا والدة الإله يا أم الرحمة والخلاص؛ تشفعي من أجل خلاص نفوسنا.\",\"r\":\"نرى حنان الله في صورة الأم التي تحتضن، وتذكّرنا الكنيسة بالعذراء أم الرحمة. فكل عطف تعرفه في الأسرة ظل ضعيف لحنان أعظم. تأمل اليوم في أمٍّ أو امرأةٍ حملتك بحنانها، واشكر الله من أجلها.\",\"p\":\"يا رب، أشكرك لأنك تحنو علينا كما تحنو الأم على أبنائها. بشفاعة والدة الإله، ارحمني واحمني تحت ظلال حنانك. آمين.\",\"x\":\"العطف في الكتاب يشبه حنان الأم التي لا تنسى ابنها. والكنيسة تدعو العذراء أم الرحمة لأنها حملت رحمة الله. تدريب: اطلب من العذراء أن تشفع لك في ضيق تحمله اليوم.\"},{\"t\":\"كإنسان تعزيه أمه\",\"ref\":\"إشعياء ٦٦: ١٣\",\"bk\":\"إشعياء\",\"v\":\"كإنسان تعزيه أمه هكذا أعزيكم أنا، وفي أورشليم تعزون.\",\"r\":\"«كإنسان تعزيه أمه هكذا أنا أعزيكم». يستخدم الله صورة حنان الأم ليصف عنايته. ليس في الله ضعف، لكنه يعرف كيف يضمّ ويمسح الدموع. وعندما أتألم لا أحتاج إلى خطب طويلة، بل إلى حضن، والله يقدّمه لي.\",\"p\":\"يا رب، أنت المعزي الحنون. عزّ قلبي في ضيقي، وامسح دموعي، وعلّمني أن أعزي غيري بالحنان الذي تلقيته منك. آمين.\",\"x\":\"تجمع نصوص الكتاب بين صورة الله الأب وصورة الأم، فالله فوق الجنسين، لكنه يعبّر عن محبته بما نفهمه. والتعزية التي يمنحها ليست مسكنًا مؤقتًا بل شفاء عميق. وقد تأتي عن طريق شخص يضمّنا أو كلمة أو صمت. ومن اختبر هذه التعزية صار قادرًا أن يعزي غيره.\\nكن اليوم «حضنًا» لشخص يحتاج: استمع له بلا نصائح وبلا مقاطعة.\"},{\"t\":\"بشريتي وإلهيتك\",\"ref\":\"\",\"v\":\"\",\"r\":\"كان الأب أبو للوس يردد دائمًا: «لقد خطئت كإنسان، ولكن أنت كإله ارحمني». هذه الصلاة تلخص حنان الله: خطيتي بحجم بشريتي، ورحمته بحجم ألوهيته. رددها اليوم مراتٍ كلما شعرت بثقل.\",\"p\":\"لقد خطئت كإنسان، ولكن أنت كإله ارحمني. أعطني ثقة في حنانك الذي لا ينفد. آمين.\",\"x\":\"يعلمنا الأب أن نعترف بضعف بشريتنا وعظمة إلهيته، فلا نتكبر ولا ننكسر. تدريب: قل لله اليوم: أنا بشر ضعيف وأنت إله قوي، فاعتن بي.\",\"fq\":76}]},\"3-23\":{\"th\":\"المحبة في البيت\",\"m\":[{\"t\":\"امرأتك مثل كرمة مخصبة\",\"ref\":\"المزمور ١٢٧ (١٢٨) — الغروب\",\"v\":\"امرأتك تصير مثل كرمة مخصبة في جوانب بيتك. بنوك مثل غروس الزيتون الجدد حول مائدتك. هكذا يبارك الإنسان المتقي الرب.\",\"r\":\"يرسم المرنم صورة بيت مبارك: كرمة مخصبة وغروس زيتون حول المائدة. الحب في البيت يظهر على مائدة تجمع. اجعل وجبة اليوم أو الليلة وقتًا بلا شاشات، تجلس فيه مع أسرتك وتنصت إلى كل واحد.\",\"p\":\"يا رب، بارك بيتي واجعله مثل كرمة مخصبة وغروس زيتون حول مائدتك. أعطنا محبة تغفر وتبني وتجمع. آمين.\",\"x\":\"البيت المبارك صورة الكرمة والزيتون، أي حياة وثمر وسلام. تدريب: اصنع اليوم لحظة بركة في بيتك: صلاة جماعية قصيرة أو كلمة تقدير.\"},{\"t\":\"فوق كل هذا المحبة\",\"ref\":\"كولوسي ٣: ١٤\",\"bk\":\"كولوسي\",\"v\":\"وعلى جميع هذه البسوا المحبة التي هي رباط الكمال.\",\"r\":\"«وعلى جميع هذه البسوا المحبة التي هي رباط الكمال». المحبة تلبس كما نلبس الثوب، وتربط كل الفضائل معًا. فبدونها يصير اللطف مجاملة، والتواضع ضعفًا. وفي البيت يتجلى هذا اللباس في أصغر التفاصيل: نبرة الصوت، ونظرة العين، وطريقة الاعتذار.\",\"p\":\"يا رب، ألبسني محبتك فوق كل شيء. اجعلني ليّنًا صبورًا غافرًا، وأجمع شمل أسرتي برباط الكمال والسلام. آمين.\",\"x\":\"قبلها يعدد بولس مجموعة ملابس: رأفة ولطف وتواضع ووداعة وطول أناة، ثم احتمال وغفران. وكلها تحتاج جهدًا يوميًا. وتأتي المحبة كالحزام الذي يجمعها. ومن تعلّم هذا في بيته حمله إلى العمل والكنيسة. والمحبة ليست شعورًا يأتي ويذهب، بل اختيار نكرره كل صباح.\\nاختر اليوم «ثوبًا» واحدًا من هذه، كالصبر أو اللطف، وارتده طوال اليوم في بيتك.\"},{\"t\":\"أن أحب من يحبني كنفسي\",\"ref\":\"\",\"v\":\"\",\"r\":\"جواب الأب ماتوى صادق وبسيط: «حتى الآن أنا أحب من يحبني كنفسي». يعترف بحدود محبته، فيطلب الأكثر. في البيت، المحبة الحقيقية تتجاوز المقابل. اختر اليوم أن تحب أحد أهل بيتك دون أن تنتظر رد الفعل.\",\"p\":\"يا رب، وسّع محبتي لتشمل من لا يحبني بسهولة. علّمني أن أحب في بيتي كما أحببتني أنت. آمين.\",\"x\":\"أن أحب من يحبني كنفسي بداية، لكن المسيح يطلب أكثر: أن أحب من لا يحبني. تدريب: وسّع دائرة محبتك اليوم إلى شخص خارجها.\",\"fq\":271}]},\"3-24\":{\"th\":\"الصلاة الربانية\",\"m\":[{\"t\":\"أصغِ إلى صوت طلبتي\",\"ref\":\"المزمور الخامس — باكر\",\"v\":\"أنصت يا رب لكلماتي. واسمع صراخي. أصغ إلى صوت طلبتي يا ملكي وإلهي، لأني إليك أصلى. يا رب بالغداة تسمع صوتي، بالغداة أقف أمامك وتراني.\",\"r\":\"قبل أن يقدّم المرنم طلبه يقول: أصغ إلى صوت طلبتي يا ملكي وإلهي، لأني إليك أصلي. الصلاة الربانية تبدأ بالمخاطبة قبل الطلب. افتتح صلاتك اليوم بهذا الوعي: أنت تخاطب ملكًا هو أب، وتقول له: أبانا.\",\"p\":\"أنصت يا رب لكلماتي واسمع صراخي. أصغِ إلى صوت طلبتي يا ملكي وإلهي، فبالغداة تسمع صوتي وبالغداة أقف أمامك. آمين.\",\"x\":\"قبل أن يقدم المرنم طلبه يطلب الإصغاء. فالصلاة حوار وليست مونولوجًا. تدريب: صلِّ اليوم ثم اصمت دقيقة كاملة لتسمع.\"},{\"t\":\"أبانا الذي في السماوات\",\"ref\":\"متى ٦: ٩–١٠\",\"bk\":\"متى\",\"v\":\"«فصلوا أنتم هكذا: أبانا الذي في السماوات، ليتقدس اسمك. ليأت ملكوتك. لتكن مشيئتك كما في السماء كذلك على الأرض.\",\"r\":\"«فصلوا أنتم هكذا: أبانا الذي في السماوات ليتقدس اسمك، ليأتِ ملكوتك، لتكن مشيئتك». تبدأ الصلاة بـ«أبانا» لا بـ«أبي»، لأنني لا أصلي وحدي بل مع كل الكنيسة. وتبدأ بالله لا بحاجاتي، فأتعلم أن أضع مشيئته قبل رغباتي.\",\"p\":\"أبانا الذي في السماوات، ليتقدس اسمك. ليأتِ ملكوتك. لتكن مشيئتك. علّمني أن أضع إرادتك فوق رغباتي، وأن أصلي بقلب ابن. آمين.\",\"x\":\"ثلاث طلبات تخص الله: اسمه وملكوته ومشيئته. وبعدها تأتي حاجاتنا. وهذا الترتيب يعلّمنا أن حياتنا تدور حول الله لا حوله. ومن يقول «لتكن مشيئتك» بصدق يخلو من القلق، لأنه يسلم أموره. وكان الآباء يرددون هذه الصلاة بتمهّل، كلمة كلمة. ويعتبرونها خلاصة الإنجيل.\\nردّد الصلاة الربانية اليوم ببطء، وتوقف عند كلمة «أبانا» دقيقة واحدة.\"},{\"t\":\"الصلاة ليلًا ونهارًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يحكي الأب إيسيذورس أنه في صغره لم يكن له مقياس للصلاة، لأن الصلاة كانت له في الليل والنهار. هكذا تنمو الصلاة الربانية فينا: من كلمات نحفظها إلى حياة نعيشها. رددها اليوم ببطء، كلمة كلمة.\",\"p\":\"يا أبانا الذي في السماوات، علّمني أن أصلي ليلًا ونهارًا. ليكن اسمك مقدسًا في فمي وقلبي. آمين.\",\"x\":\"الصلاة ليلًا لها طعم خاص، لأن الجسد يسكت والروح تتكلم. تدريب: استيقظ الليلة قليلًا أو أطل صلاتك قبل النوم بخمس دقائق.\",\"fq\":169}]},\"3-25\":{\"th\":\"الدعوة والاختيار\",\"m\":[{\"t\":\"اهدني إلى طريقك\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"اهدني يا رب إلى طريقك فأسلك في حقك. ليفرح قلبي عند خوفه من اسمك. أعترف لك أيها الرب إلهي من كل قلبي.\",\"r\":\"الدعوة تبدأ بسؤال: ما طريقك يا رب؟ يصلي المرنم: اهدني إلى طريقك فأسلك في حقك. ثم يعترف بقلبه كله. من لا يعرف دعوته لا ييأس، فالمهم أن يطلب الاهتداء بقلب صادق. اسأل الله اليوم عن خطوة واحدة.\",\"p\":\"اهدني يا رب إلى طريقك فأسلك في حقك، وليفرح قلبي عند خوفه من اسمك. أعترف لك من كل قلبي، فأرشدني. آمين.\",\"x\":\"الدعوة تبدأ بسؤال: ما طريقك يا رب؟ ومن يسأل بصدق يُهدى. تدريب: اطلب اليوم من الله أن يريك طريقًا في أمر يحيرك، وانتبه للإشارات.\"},{\"t\":\"أنا اخترتكم\",\"ref\":\"يوحنا ١٥: ١٦\",\"bk\":\"يوحنا\",\"v\":\"ليس أنتم اخترتموني بل أنا اخترتكم، وأقمتكم لتذهبوا وتأتوا بثمر، ويدوم ثمركم، لكي يعطيكم الآب كل ما طلبتم باسمي.\",\"r\":\"«لستم أنتم اخترتموني بل أنا اخترتكم وأقمتكم لتذهبوا وتأتوا بثمر». يا لهذه النعمة: لست مضطرًا أن أبحث عن قيمتي لأنني مختار. وقد اخترني ليس لأنني مستحق بل لأنه أحبني. والثمر هو أن أحيا في محبته وأخدم.\",\"p\":\"يا رب يسوع، أشكرك لأنك اخترتني. اجعلني أثمر ثمرًا يدوم، ودعني أحب إخوتي كما أحببتني، وأخدمك بقلب شاكر. آمين.\",\"x\":\"الاختيار هنا ليس تفضيلًا يتبعه تكبر بل رسالة. فالمختار يُرسل: «لتذهبوا». والثمر الذي يطلبه المسيح يدوم: ليس إنجازًا مؤقتًا بل شخصية تتغير وناس يتغيرون. ثم يلخص الوصية: «أن تحبوا بعضكم بعضًا». فكل خدمة لا تثمر محبة تفقد معناها. والمسيح يعدنا أن ما نطلبه باسمه يعطيه الآب.\\nاسأل نفسك: ما الثمر الذي يريده المسيح مني اليوم؟ وكن مستعدًا أن تقدم محبة عملية.\"},{\"t\":\"اسأل أباك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يلاحظ القديس أنطونيوس رهبانًا سقطوا بعد أتعاب كثيرة لأنهم اتكلوا على أعمالهم واحتقروا وصية: «اسأل أباك فيقول لك». من يطلب الدعوة يحتاج إلى مرشد. إن كنت متحيرًا في اختيارك، فاسأل أب اعترافك أو معلمًا حكيمًا.\",\"p\":\"يا رب، أعطني قلبًا يطلب المشورة، ولا يتكل على فهمه. ضع في طريقي أبًا روحيًا يقودني إلى ما تدعوني إليه. آمين.\",\"x\":\"اسأل أباك الروحي لأنه رأى ما لم تره، فالمشورة حماية. تدريب: ابعث اليوم برسالة لأب اعترافك أو لمرشدك تسأله عن أمر يشغلك.\",\"fq\":21}]},\"3-26\":{\"th\":\"السلام الداخلي\",\"m\":[{\"t\":\"بالسلامة أضطجع وأنام\",\"ref\":\"المزمور الرابع — باكر\",\"v\":\"كثيرون يقولون: من يرينا الخيرات؟ قد أضاء علينا نور وجهك يا رب. أعطيت سرورا لقلبي أوفر من الذين كثرت حنطتهم وخمرهم وزيتهم. فبالسلامة أضطجع أيضا وأنام، لأنك أنت وحدك يا رب أسكنتني على الرجاء هلليلويا.\",\"r\":\"السلام الداخلي عند المرنم ليس نتيجة غياب الأسئلة، بل نور وجه الرب الذي يعطي سرورًا أوفر من الحنطة والخمر. وهو ينام مطمئنًا لأن الله أسكنه على الرجاء. الليلة اترك هواجسك لله قبل أن تنام.\",\"p\":\"قد أضاء علينا نور وجهك يا رب، وأعطيت سرورًا لقلبي. بالسلامة أضطجع وأنام لأنك أنت وحدك أسكنتني على الرجاء. آمين.\",\"x\":\"السلام الداخلي يأتي من نور وجه الله، لا من غياب الأسئلة. ينام المرنم بسلام. تدريب: قبل النوم قل لله: بالسلامة أضطجع وأنام لأنك وحدك تحفظني.\"},{\"t\":\"ليملك في قلوبكم سلام الله\",\"ref\":\"كولوسي ٣: ١٥\",\"bk\":\"كولوسي\",\"v\":\"وليملك في قلوبكم سلام الله الذي إليه دعيتم في جسد واحد، وكونوا شاكرين.\",\"r\":\"«وليملك في قلوبكم سلام الله الذي إليه دُعيتم في جسد واحد وكونوا شاكرين». كلمة «يملك» تعني أنه الحكم في قراراتي. فإن فقدت السلام في أمر فهذا مؤشر لأعيد النظر. وهو ليس لي وحدي بل للجسد الواحد، فلا سلام مع خصام الإخوة.\",\"p\":\"يا رب، املك على قلبي بسلامك. اجعله حكمًا في قراراتي، ووحّدنا في جسدك الواحد، وعلّمني أن أكون شاكرًا في كل شيء. آمين.\",\"x\":\"السلام هنا يعمل كحكم على أرض الملعب: يقرر ما يصح وما لا يصح. وهذا لا يعني أن أتبع مشاعري، بل أن أصلي وأفحص بعمق هل قراري يوافق محبة الله ويحافظ على وحدة الكنيسة. والشكر مرافق للسلام: فمن شكر قلّ اضطرابه. وكل قرار يجلب سلامًا عميقًا مع الاتساق مع الإنجيل غالبًا من الله.\\nقبل قرار اليوم اسأل: هل هذا يجلب سلام الله لي وللآخرين؟ ثم اشكر الله وقرر.\"},{\"t\":\"محبّ السكينة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب نيلوس إن الذي يحب السكينة لا يمكن لسهام العدو أن تجرحه، أما من يتدخل في كل شيء فيحتمل جراحات مستمرة. السلام الداخلي يحتاج حدودًا. ما الأمر الذي ليس من شأنك وتتوقف عن التدخل فيه اليوم؟\",\"p\":\"يا رب، علّمني أن أحب السكينة، وأترك ما ليس لي. احفظ قلبي هادئًا في كل ما يحدث حولي. آمين.\",\"x\":\"محب السكينة يقتني السلام، فالضوضاء تسرق ما يبنيه الهدوء. تدريب: اطفئ شيئًا يضجّ حولك لمدة ساعة اليوم.\",\"fq\":296}]},\"3-27\":{\"th\":\"الشباب والنقاء\",\"m\":[{\"t\":\"الطاهر اليدين النقي القلب\",\"ref\":\"المزمور ٢٣ (٢٤) — الثالثة\",\"v\":\"من يصعد إلى جبل الرب، أو من يقوم في موضع قدسه \\\"؟ الطاهر اليدين: النقي القلب. الذي لم يحمل نفسه إلى الباطل ولم يحلف بالغش. هذا ينال بركة من الرب، ورحمة من الله مخلصه. هذا هو جيل الذين يطلبون الرب ويبتغون وجه إله يعقوب.\",\"r\":\"السؤال القديم لا يزال حيًا: من يصعد إلى جبل الرب؟ والجواب عن الطهارة واضح: الطاهر اليدين، النقي القلب، الذي لم يحمل نفسه إلى الباطل. ليست الطهارة مجرد امتناع، بل اتجاه نحو الله. ما الذي يحتاج قلبك إلى التنقية منه اليوم؟\",\"p\":\"يا رب، أريد أن أصعد إلى جبلك. اجعلني طاهر اليدين نقي القلب، وأعطني بركتك ورحمتك يا إلهي ومخلصي. آمين.\",\"x\":\"من يصعد إلى جبل الرب؟ الطاهر اليدين النقي القلب. الطهارة بوابة الحضور. تدريب: اجعل نظرك وفكرك اليوم نقيين، وتجنب ما يلوّثهما.\"},{\"t\":\"لم يتنجس بطعام الملك\",\"ref\":\"دانيال ١: ٨\",\"bk\":\"دانيال\",\"v\":\"أما دانيآل فجعل في قلبه أنه لا يتنجس بأطايب الملك ولا بخمر مشروبه، فطلب من رئيس الخصيان أن لا يتنجس.\",\"r\":\"«وأما دانيال فجعل في قلبه أنه لا يتنجس بأطايب الملك». كان بعيدًا عن أهله في بلد غريب، ومع ذلك قرر أن يحفظ نفسه. والقرار «في القلب» أولًا. وكانت بداية رحلة طويلة من الأمانة. وكل أمانة كبيرة تبدأ بقرار صغير سري.\",\"p\":\"يا رب، أعطني قرارًا في قلبي أن أحفظ نفسي لك. ثبّتني في الغربة والضغط، وامنحني حكمة ومحبة وأمانة كدانيال. آمين.\",\"x\":\"لم يتحدّ دانيال الملك بعنف، بل بحكمة: اقترح تجربة. وأعطاه الله نعمة عند رئيس الخصيان. ثم نما في الحكمة حتى «فاق الجميع عشر مرات». فالتمسك بالنقاء لا يعزلنا بل يميزنا بالإيجابية. وقد نجد في عملنا أو دراستنا ضغطًا لنجاري الآخرين، لكن الله يعطي القوة لمن يقرر من الداخل. وكل «لا» نقولها بحكمة تفتح لنا «نعم» أكبر.\\nحدد أمرًا واحدًا تقرر اليوم في قلبك ألا تتنازل فيه، وصلِّ أن يثبتك الله.\"},{\"t\":\"آنية للاستعمال الشريف\",\"ref\":\"\",\"v\":\"\",\"r\":\"يذكّر الأب بيمن في جوابه لأخ بأنه في البيت الكبير آنية من ذهب وفضة وأخرى من خشب وخزف، وبعضها لاستعمال شريف. الشاب الذي ينقي نفسه يصير إناءً شريفًا للرب. ما العادة التي تحتاج أن تنظفها اليوم؟\",\"p\":\"يا رب، طهّرني لأكون إناءً شريفًا في بيتك. انزع عني ما يدنس، وتمم فيّ عمل نعمتك. آمين.\",\"x\":\"الآنية الصالحة للاستعمال الشريف هي التي نحفظها نظيفة. تدريب: ما الذي يلوّث إنائي؟ نقِّ شيئًا واحدًا منه اليوم.\",\"fq\":385}]},\"3-28\":{\"th\":\"سر الاعتراف\",\"m\":[{\"t\":\"من يثبت لأن من عندك المغفرة\",\"ref\":\"المزمور ١٢٩ (١٣٠) — النوم\",\"v\":\"إن كنت للآثام راصدا يا رب. يا رب من يثبت لأن من عندك المغفرة. من أجل اسمك صبرت لك يا رب.\",\"r\":\"يقف المرنم أمام الله بحقيقة بسيطة: إن حسبت الآثام فمن يثبت؟ لكن عندك المغفرة. الاعتراف ليس محاكمة بل لقاء مع غفران سابق. ابدأ اليوم بتسمية خطية واحدة تثقلك، وحضّر نفسك للاعتراف بها أمام أب اعترافك.\",\"p\":\"إن كنت للآثام راصدًا يا رب فمن يثبت؟ لكن عندك المغفرة، ومن أجل اسمك صبرت لك. اغفر لي واقبل اعترافي. آمين.\",\"x\":\"إن حسبت الآثام فمن يثبت؟ لكن من عند الله المغفرة، وهذا أساس الاعتراف. تدريب: لا تؤجل اعترافك، حدد موعدًا هذا الأسبوع.\"},{\"t\":\"من غفرتم خطاياه\",\"ref\":\"يوحنا ٢٠: ٢٢–٢٣\",\"bk\":\"يوحنا\",\"v\":\"ولما قال هذا نفخ وقال لهم: «اقبلوا الروح القدس. من غفرتم خطاياه تغفر له، ومن أمسكتم خطاياه أمسكت».\",\"r\":\"«اقبلوا الروح القدس. من غفرتم خطاياه تُغفر له ومن أمسكتم خطاياه أمسكت». في مساء القيامة أعطى المسيح تلاميذه هذا السلطان. وهذا أساس سر التوبة والاعتراف في الكنيسة. فالغفران ليس فكرة بل عطية تُمنح عبر الكنيسة.\",\"p\":\"يا رب يسوع، أشكرك على سلطان الغفران الذي أعطيته لكنيستك. اغسلني بدمك، وأعطني سلامك، وثبّتني في توبة مستمرة. آمين.\",\"x\":\"بدأ المسيح بقوله: «سلام لكم»، ثم أراهم يديه وجنبه. فالغفران يخرج من جراح الصليب. ثم أرسلهم كما أرسله الآب. والكنيسة تنفذ هذه الرسالة، فيحل الكاهن من الخطايا باسم المسيح. وعندما أسمع كلمات الحل أعلم أن الله نفسه يغفر. وهذه ثقة تحررني من اجترار الماضي.\\nإذا اعترفت مؤخرًا، فاشكر الله على الحل اليوم، وقل: «أنا مغفور لي».\"},{\"t\":\"العدو يحب الأفكار المخفية\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوحنا الكولوفي: إن العدو لا يفرح كثيرًا إلا من الذين لا يظهرون أفكارهم. فالاعتراف يفضح خطة العدو ويجعلنا أحرارًا. ما الفكرة التي تخفيها ولا تقولها لأحد؟ قلها اليوم لله، وفي الاعتراف المقبل لأب اعترافك.\",\"p\":\"يا رب، لا أريد أن أخفي شيئًا عنك. أظهر لك أفكاري، وحرّرني من سلطان العدو بسر الاعتراف. آمين.\",\"x\":\"العدو يحب الأفكار التي نحتفظ بها في الظلمة، فإخراجها للنور يضعفه. تدريب: قل فكرة تزعجك لشخص أمين اليوم، وستخف قبضتها.\",\"fq\":386}]},\"3-29\":{\"th\":\"الكنيسة الواحدة\",\"m\":[{\"t\":\"القائمون في بيت الرب\",\"ref\":\"المزمور ١٣٣ — النوم\",\"v\":\"ها باركوا الرب يا عبيد الرب، القائمين في بيت الرب في ديار إلهنا. في الليالي ارفعوا أيديكم إلى القدس وباركوا الرب. يبارككم الرب من صهيون الذي خلق السماء والأرض هلليلويا.\",\"r\":\"تتحد الكنيسة في الصلاة، حتى في الليل يرفع المؤمنون أيديهم إلى القدس. نبارك الرب معًا لا منفردين. فالصلاة الجماعية تحمل من لا يقدر على الصلاة. صلِّ اليوم من أجل كنيستك ومن أجل أسماء تعرفها من أعضائها.\",\"p\":\"يا رب، يبارك عبيدك القائمون في بيتك ويرفعون أيديهم إلى القدس. بارك كنيستك، وبارك كل واحد فيها، يا خالق السماء والأرض. آمين.\",\"x\":\"القائمون في بيت الرب يرفعون أيديهم في الليل، فالكنيسة جماعة صلاة لا تنام. تدريب: ارفع يديك الليلة قليلًا وصلِّ مع الكنيسة في كل مكان.\"},{\"t\":\"يحمل بعضكم أثقال بعض\",\"ref\":\"غلاطية ٦: ٢\",\"bk\":\"غلاطية\",\"v\":\"احملوا بعضكم أثقال بعض، وهكذا تمموا ناموس المسيح.\",\"r\":\"«احملوا بعضكم أثقال بعض وهكذا تمموا ناموس المسيح». لا أحد يقدر أن يحمل ثقله وحده. والكنيسة ليست مكانًا للمتفرجين بل لحاملي الأثقال. وأن أحمل أثقال غيري يعني أن أشاركه بكلمة ووقت وصلاة وربما بمال. وهكذا أتمم محبة المسيح.\",\"p\":\"يا رب، علّمني أن أحمل أثقال إخوتي وأن أسمح لهم بأن يحملوا أثقالي. اجعل كنيستنا جماعة محبة ومشاركة تتمم ناموسك. آمين.\",\"x\":\"الثقل قد يكون مرضًا أو دَينًا أو وحدة أو خطية. وحمله يبدأ بالانتباه والسؤال. ونحن نقع في خطأ افتراض أن الآخرين بخير. وربما ينتظر أحدهم سؤالك. وفي الوقت نفسه، يجب أن أسمح للآخرين بأن يحملوا ثقلي، فالاتضاع يعني أن أطلب العون. وبذلك تقوى الجماعة وتتدفأ.\\nاسأل اليوم شخصًا بصدق: «كيف أقدر أن أساعدك؟»، وكن مستعدًا لتنفيذ ما يطلبه.\"},{\"t\":\"التصق بمن يسلك حسنًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"وصية الأب بيمن: «لا تعتدّ بنفسك إنما التصق بمن يسلك حسنًا». الكنيسة الواحدة تنمو بالصحبة الصالحة. فمن هم الذين يسلكون حسنًا في كنيستك؟ ابحث عن فرصة تقترب فيها منهم وتتعلم.\",\"p\":\"يا رب، اجعلني أتعلم من الصالحين في كنيستك، ولا أتكل على فهمي. ضعني في صحبة تقودني إليك. آمين.\",\"x\":\"الالتصاق بمن يسلك حسنًا يعلّمنا بالقدوة. تدريب: اختر مثالًا في حياتك واسأل نفسك: ماذا أتعلم منه اليوم؟\",\"fq\":367}]},\"3-30\":{\"th\":\"السلام مع الله\",\"m\":[{\"t\":\"اسألوا السلام\",\"ref\":\"المزمور ١٢١ (١٢٢) — الغروب\",\"v\":\"اسألوا السلام لأورشليم والخصب لمحبيك. ليكن السلام في حصنك والخصب في أبراجك الرصينة. من أجل اخوتي وأقربائي تكلمت من أجلك بالسلام، ومن أجل بيت الرب إلهنا التمست لك الخيرات هلليلويا.\",\"r\":\"يدعو المرنم إلى السؤال من أجل سلام المدينة، لأجل الإخوة والأقرباء وبيت الرب. السلام مع الله يظهر في أن نطلب السلام للآخرين. من هو الشخص أو المكان الذي يحتاج إلى سلام اليوم؟ صلِّ له بالاسم.\",\"p\":\"اسألك يا رب السلام لأورشليم وللكنيسة ولبيوتنا. ليكن السلام في حصنك والخصب في أبراجك، من أجل إخوتي وأقربائي. آمين.\",\"x\":\"اسألوا سلام المدينة: الصلاة من أجل المكان الذي نعيش فيه جزء من محبتنا. تدريب: صلِّ اليوم من أجل بلدك ومدينتك والمسؤولين فيها.\"},{\"t\":\"السلام لكم\",\"ref\":\"يوحنا ٢٠: ١٩\",\"bk\":\"يوحنا\",\"v\":\"ولما كانت عشية ذلك اليوم، وهو أول الأسبوع، وكانت الأبواب مغلقة حيث كان التلاميذ مجتمعين لسبب الخوف من اليهود، جاء يسوع ووقف في الوسط، وقال لهم: «سلام لكم!»\",\"r\":\"«ولما كانت عشية ذلك اليوم والأبواب مغلقة حيث كان التلاميذ مجتمعين لسبب الخوف جاء يسوع ووقف في الوسط وقال لهم سلام لكم». المسيح لا ينتظر أن يفتح التلاميذ الأبواب، بل يدخل إليهم وهي مغلقة. وأنا أيضًا قد أغلق قلبي خوفًا، لكنه يدخل ويقف في وسطي.\",\"p\":\"يا رب يسوع القائم، ادخل إلى قلبي المغلق خوفًا، وقف في وسطي وقل لي: سلام لك. حوّل خوفي فرحًا، وارسلني بسلامك. آمين.\",\"x\":\"كان التلاميذ خائفين من اليهود ومن أنفسهم بعد أن تركوا المعلم. ولم يوبخهم المسيح، بل قال: «سلام لكم»، وأراهم يديه وجنبه. فهو يطمئن بجراحه. وفرح التلاميذ لما رأوه. والسلام الذي يعطيه هو غير سلام العالم. وهو يريد أن يعطيه اليوم لكل خائف.\\nاكتب مخاوفك على ورقة، وتخيل المسيح واقفًا في وسطها يقول لك «سلام لك»، ثم مزّقها بصلاة شكر.\"},{\"t\":\"هذا هو السلام\",\"ref\":\"\",\"v\":\"\",\"r\":\"يرسم الأب موسى الحبشي سلامًا عمليًا: لا تثلب أحدًا، لا توافق المتكلم بالسوء، لا تحقد على أحد، لا يكن لك عداوة. ثم يقول: هذا هو السلام. السلام مع الله يبدأ بأمور صغيرة نتجنبها. أيّها تحتاج إليه اليوم؟\",\"p\":\"يا رب، اجعلني صانع سلام لا أثلب ولا أحقد. وأعطني قلبًا يعيش بسلامك في كل علاقاتي. آمين.\",\"x\":\"السلام الحقيقي هو أن لا نرى أحدًا أقل منا، وأن نرى أنفسنا مقصرين. تدريب: ابحث اليوم عن عمل واحد تقيّم نفسك فيه بتواضع.\",\"fq\":267}]},\"3-31\":{\"th\":\"أنسى ما هو وراء\",\"m\":[{\"t\":\"هذا هو اليوم الذي صنعه الرب\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"هذا هو اليوم الذي صنعه الرب. فلنبتهج ونفرح فيه.\",\"r\":\"ننهي مارس بفرح اللحظة: «هذا هو اليوم الذي صنعه الرب، فلنبتهج ونفرح فيه». ننسى ما وراء ونمتد إلى ما أمام، وتبقى عطية اليوم أمامنا. ابدأ هذا اليوم بتهليل قصير حتى لو كانت الأخبار ثقيلة.\",\"p\":\"هذا هو اليوم الذي صنعته يا رب، فلنبتهج ونفرح فيه. أنسني ما وراء وامتد بي إلى ما قدام. آمين.\",\"x\":\"هذا اليوم صنعه الرب، فلنفرح فيه. الفرح هنا قرار وليس شعورًا عابرًا. تدريب: ابدأ الصباح بقول المزمور الثامن عشر بعد المئة بفرح، وقلها عدة مرات.\"},{\"t\":\"أسعى نحو الغرض\",\"ref\":\"فيلبي ٣: ١٣–١٤\",\"bk\":\"فيلبي\",\"v\":\"أيها الإخوة، أنا لست أحسب نفسي أني قد أدركت. ولكني أفعل شيئا واحدا: إذ أنا أنسى ما هو وراء وأمتد إلى ما هو قدام، أسعى نحو الغرض لأجل جعالة دعوة الله العليا في المسيح يسوع.\",\"r\":\"«ولكني أفعل شيئًا واحدًا: إذ أنا أنسى ما هو وراء وأمتد إلى ما هو قدام أسعى نحو الغرض». في نهاية شهر قد أجمع خسائر وإخفاقات، لكن الرسول يعلّمني ألا أبقى في الماضي. أتعلم ثم أتحرك. والغرض هو المسيح نفسه. فأمدّ يدي إلى الغد بثقة.\",\"p\":\"يا رب، علّمني أن أنسى ما هو وراء وأمتد إلى ما هو قدام. حرّرني من ندم الماضي، وقدني نحو غايتي فيك، وأعطني مثابرة. آمين.\",\"x\":\"«شيئًا واحدًا» تعني تركيز. والنسيان هنا لا يعني تجاهل الدروس، بل ألا أُقيّد بالندم. وبولس نفسه كان له ماض صعب، ومع ذلك لم يبقَ فيه. والمسيرة تحتاج مثابرة. وكل يوم خطوة. وغايتها الشركة مع المسيح. والعبارة «لأجل جعالة دعوة الله العليا» تذكّرنا بأن هناك مكافأة أبدية لمن يسعى.\\nاكتب أمرًا من الماضي عليك أن تتركه، وأمرًا واحدًا تمد إليه يدك في الأسبوع القادم.\"},{\"t\":\"ابدأ من جديد كل صباح\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب يوحنا الكولوفي: عندما تستيقظ كل صباح ابدأ من جديد في كل فضيلة ووصية، بصبر عظيم وخوف وطول أناة ومحبة لله. أنسى ما وراء يعني أن كل صباح بدء جديد. ابدأ اليوم كأنه أول يوم.\",\"p\":\"يا رب، أبدأ من جديد معك. أعطني صبرًا وخوفًا ومحبة لك، وساعدني أن أترك ما مضى. آمين.\",\"x\":\"البدء من جديد حركة روحية أصيلة، فلا نعيش في الماضي. تدريب: اختم الشهر بتسليم ما فات لله والبدء من صفحة جديدة.\",\"fq\":163}]},\"4-1\":{\"th\":\"الصدق في القول والعمل\",\"m\":[{\"t\":\"شفاه غاشة\",\"ref\":\"المزمور الحادي عشر — باكر\",\"v\":\"تكلم كل واحد مع قريبه بالأباطيل. شفاه غاشة في قلوبهم وبقلوبهم تخاطبوا.\",\"r\":\"يشكو المرنم من زمن قلّت فيه الأمانة وتكلم الناس بالأباطيل بشفاه غاشة وقلوب منقسمة. الصدق أن يتفق ما في القلب مع ما على اللسان. قبل أن تتكلم اليوم في موضوع حساس، اسأل: هل ما سأقوله هو ما أعتقده فعلًا؟\",\"p\":\"خلصني يا رب من الغش، وقوّم لساني ليوافق قلبي. أعطني أن أتكلم مع قريبي بالحق، وأن أسير أمامك بنزاهة. آمين.\",\"x\":\"يشكو المرنم من أن الناس يتكلمون بشفاه غاشة، فيطلب أن يحفظه الله من هذا الجيل. الصدق في القول والعمل هو وعد الله لمن يتكل عليه. تدريب: قل اليوم كلمة حق واحدة بلطف في موقف تميل فيه للمجاملة.\"},{\"t\":\"تكلموا بالصدق\",\"ref\":\"أفسس ٤: ٢٥\",\"bk\":\"أفسس\",\"v\":\"لذلك اطرحوا عنكم الكذب، وتكلموا بالصدق كل واحد مع قريبه، لأننا بعضنا أعضاء البعض.\",\"r\":\"«لذلك اطرحوا عنكم الكذب وتكلموا بالصدق كل واحد مع قريبه لأننا بعضنا أعضاء البعض». الكذب يمزق الجسد الواحد كما يمزق العضو المصاب بقية الأعضاء. والصدق ليس قسوة بل محبة تحترم الآخر. وأحتاج اليوم أن أراجع: هل أقول الحق بمحبة، أم أجامل على حساب الحقيقة؟\",\"p\":\"يا رب، أنت الحق. طهّر لساني من كل كذب ومبالغة، وعلّمني أن أتكلم بالصدق في المحبة، فأبني الثقة بيني وبين إخوتي. آمين.\",\"x\":\"بولس لا يعتبر الصدق فضيلة فردية فقط بل ضرورة للجماعة، لأننا أعضاء بعضنا. وإذا كذب العضو على الجسد ضعف الجميع. والكذب يبدأ صغيرًا: مبالغة أو تجميل أو وعد لا ننوي تنفيذه. لكنه يكبر. والصدق يتطلب شجاعة ولطفًا معًا: «صادقين في المحبة». أي أن نقول الحق دون جرح، ونتقبل الحق دون دفاع.\\nراقب كلامك اليوم، وأصلح أي مبالغة أو وعد غير دقيق بتصحيح بسيط ومحترم.\"},{\"t\":\"عين ماء لا تنظف نفسها\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب بيمن من يعلّم ولا يعمل بعين ماء تسقي وتروي وتغسل كل شيء لكنها لا تقدر أن تنظف نفسها. الصدق ليس في الكلام الجميل، بل في أن أعيش ما أقوله. اختر اليوم كلمة نصحت بها غيرك وطبّقها أنت أولًا.\",\"p\":\"يا رب، اجعل أقوالي وأعمالي واحدة. لا تدعني أعلّم بما لا أعيشه، وأعطني نعمة الصدق الكامل أمامك وأمام الناس. آمين.\",\"x\":\"العين التي لا تنظف نفسها مثال للإنسان الذي يحتاج إلى غيره ليُصلح عيبه. تدريب: اطلب اليوم من شخص تثق به أن يخبرك بملاحظة عن نفسك، واستمع بلا دفاع.\",\"fq\":343}]},\"4-2\":{\"th\":\"الإلحاح في الصلاة\",\"m\":[{\"t\":\"إلى متى يا رب؟\",\"ref\":\"المزمور ١٢ (١٣) — باكر\",\"v\":\"إلى متى يا رب تنساني؟ إلى الانقضاء؟ حتى متى تصرف وجهك عني؟\",\"r\":\"الإلحاح في الصلاة يبدأ أحيانًا بسؤال يخرج من التعب: إلى متى؟ والمرنم لا يخاف أن يسأل الله هكذا، وهذا هو صدق العلاقة. اسأل الله اليوم بصراحة عما تأخر، وخذ قراري ألا تصمت حتى تسمع جوابه، ولو بعد حين.\",\"p\":\"إلى متى يا رب تنساني؟ حتى متى تصرف وجهك عني؟ أنا لا أمل من الصلاة، فانظر إليّ واستجب في وقتك الحسن. آمين.\",\"x\":\"إلى متى يا رب؟ سؤال التعب الصادق، والله لا يرفضه. فالإلحاح في الصلاة صورة من صور الإيمان. تدريب: اذكر طلبة تأخرت إجابتها، وجددها اليوم بكلمة بسيطة.\"},{\"t\":\"صلاة من أجله\",\"ref\":\"أعمال الرسل ١٢: ٥\",\"bk\":\"أعمال الرسل\",\"v\":\"فكان بطرس محروسا في السجن، وأما الكنيسة فكانت تصير منها صلاة بلجاجة إلى الله من أجله.\",\"r\":\"«فكان بطرس محروسًا في السجن، وأما الكنيسة فكانت تصلي إلى الله بلجاجة من أجله». سجن وحراس وسلاسل، وفي مقابلها كنيسة تصلي. وانتهى الأمر بتحرير بطرس. والصلاة الجماعية ليست رمزًا بل قوة. وكل واحد منا يمكنه أن يحمل إنسانًا في سجنه بالصلاة.\",\"p\":\"يا رب، أشكرك على قوة الصلاة الجماعية. حرّر المسجونين بالمرض والخطية واليأس، وعلّمنا أن نصلي بإيمان ولجاجة معًا. آمين.\",\"x\":\"ما أجمل أن بطرس كان نائمًا بسلام بين الجنديين! فالصلاة المبذولة من أجله منحته طمأنينة. وحين خرج جاء إلى بيت الكنيسة، فوجدهم يصلون ولم يصدقوا أنه حر! وهذا يعلمنا أن نؤمن بما نطلب. وفي حياتنا قد يكون هناك أشخاص في «سجون» المرض أو الإدمان أو اليأس. ولنصلي من أجلهم بالجماعة.\\nاطلب من صديقين أن يصليا معك لأجل شخص بعينه هذا الأسبوع، وتابعوا بعضكم في الأمر.\"},{\"t\":\"أسرع واطلب\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال القديس أنطونيوس لأخ طلب منه الصلاة: «لا أنا أرحمك ولا الله، إذا كنت أنت نفسك لا تسرع لتطلب هذا منه». الإلحاح مسؤوليتنا، والله ينتظر أن نطلب. ما الطلب الذي تؤجل رفعه إلى الله؟ ارفعه اليوم.\",\"p\":\"يا رب، علّمني أن أطلب بنفسي وألحّ ولا أتكل على صلاة الآخرين وحدها. افتح لي بابك في كل مرة أقرع فيها. آمين.\",\"x\":\"الإسراع في الصلاة والتعب فيها يفتح الأبواب، فلا نكل. تدريب: زد صلاتك اليوم خمس دقائق عن المعتاد، بلا ملل.\",\"fq\":11}]},\"4-3\":{\"th\":\"الإيمان والشك\",\"m\":[{\"t\":\"على رحمتك توكلت\",\"ref\":\"المزمور ١٢ (١٣) — باكر\",\"v\":\"أما أنا فعلى رحمتك توكلت. يبتهج قلبي بخلاصك.\",\"r\":\"لا يخلو الإيمان من لحظات تساؤل، لكن المرنم يقفز فوق الشك بإعلان بسيط: أما أنا فعلى رحمتك توكلت. التوكل قرار يواجه الشك ولا ينكره. إذا مرّ بك سؤال بلا جواب اليوم، لا تهرب منه، ضعه في حضن رحمة الله.\",\"p\":\"أما أنا فعلى رحمتك توكلت، ويبتهج قلبي بخلاصك. يا رب، حين يأتي الشك ثبّتني، وأرني وجهك فيما لا أفهمه. آمين.\",\"x\":\"لا يخلو الإيمان من الشك، لكن المرنم يتجاوزه بإعلان توكله على رحمة الله. تدريب: اكتب الشك الذي يلازمك، وضع تحته: على رحمتك توكلت.\"},{\"t\":\"طوبى للذين آمنوا ولم يروا\",\"ref\":\"يوحنا ٢٠: ٢٧–٢٩\",\"bk\":\"يوحنا\",\"v\":\"ثم قال لتوما: «هات إصبعك إلى هنا وأبصر يدي، وهات يدك وضعها في جنبي، ولا تكن غير مؤمن بل مؤمنا». أجاب توما وقال له: «ربي وإلهي!». قال له يسوع: «لأنك رأيتني يا توما آمنت! طوبى للذين آمنوا ولم يروا».\",\"r\":\"«هات إصبعك إلى هنا وأبصر يديّ، وهات يدك وضعها في جنبي، ولا تكن غير مؤمن بل مؤمنًا». لم يوبخ المسيح توما على شكه، بل قدّم له ما يحتاجه. وهذا ما يفعله معي: يقابل أسئلتي بحنان. وانتهى شك توما باعتراف عظيم: «ربي وإلهي».\",\"p\":\"يا رب، لا تؤنبني على أسئلتي بل قدني بها إليك. زد إيماني، وأعطني أن أقول من قلبي: ربي وإلهي، وأن أثق بك وإن لم أرَ. آمين.\",\"x\":\"الشك ليس عكس الإيمان بل قد يكون بابًا للإيمان الأعمق، إذا قادنا إلى المسيح. وتوما أراد أن يرى الجراح، فعرف المسيح الذي جُرح. وكلنا في مواقف نحتاج أن نسأل. والكنيسة لا تخاف الأسئلة، بل ترحب بها. والبركة الأخيرة: «طوبى للذين آمنوا ولم يروا» وتعني كل من آمن بكلمة الشهود، أي نحن.\\nاكتب سؤالًا يشغلك عن الإيمان، وتحدث فيه مع أب اعترافك أو معلم موثوق هذا الأسبوع.\"},{\"t\":\"نبكي أمام الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"نصح الأب بيمن من أزعجته الاضطرابات بأن نبكي أمام الله في كل أتعابنا إلى أن يعلن لنا رحمته. لا يطلب منا أن نفهم كل شيء بل أن نبقى أمامه. قل له اليوم كل ما يربكك دون ترتيب، وانتظر.\",\"p\":\"يا رب، أبكي أمامك أتعابي واضطراباتي، وأنتظر رحمتك. ثبّت إيماني فلا يتزعزع في ضعفي وأسئلتي. آمين.\",\"x\":\"البكاء أمام الله ليس ضعفًا بل صلاة صامتة يفهمها. تدريب: اترك لنفسك لحظة صادقة اليوم تبكي فيها أو تتنهد أمام الله بلا كلمات.\",\"fq\":400}]},\"4-4\":{\"th\":\"إلقاء الهم على الله\",\"m\":[{\"t\":\"سترني بستر مظلته\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"لأنه أخفاني في خيمته. في يوم شدتي؛ سترني بستر مظلته. وعلى صخرة رفعني.\",\"r\":\"في يوم الشدة يجد المرنم مكانًا: خيمة الله وستر مظلته وصخرة ترفعه. إلقاء الهم على الله هو أن أترك الحمل عند من هو أقوى مني. ما الهمّ الذي تحمله اليوم وحدك؟ سمِّه بصوت مسموع، ثم قل: هذا لك يا رب.\",\"p\":\"أخفني يا رب في خيمتك في يوم شدتي، واسترني بستر مظلتك، وارفعني على صخرة. ألقي عليك همومي لأنك تعتني بي. آمين.\",\"x\":\"في يوم الشدة وجد المرنم خيمة الله وستر مظلته. من يلتجئ إليه لا يُترك. تدريب: عند أول ضغط اليوم تخيل نفسك تدخل خيمة الله وتجلس عنده.\"},{\"t\":\"ألقوا كل همكم عليه\",\"ref\":\"بطرس الأولى ٥: ٧\",\"bk\":\"بطرس الأولى\",\"v\":\"ملقين كل همكم عليه، لأنه هو يعتني بكم.\",\"r\":\"«ملقين كل همكم عليه لأنه هو يعتني بكم». كلمة «كل» تعني الصغير والكبير. لا أحتاج أن أنتقي مما أعرضه عليه. وهو يعتني بي كما يعتني الأب بطفله. وإلقاء الهم فعل إرادي: أن أضع الحمل عند قدميه وأرفع يدي فارغة.\",\"p\":\"يا رب، ألقي عليك كل همّي لأنك تعتني بي. أعطني أن أتوكل عليك وأترك ما لا أستطيع، فأعيش بسلام وثقة في رعايتك. آمين.\",\"x\":\"كثيرون يحملون همومهم ويصلون وهم لا يتركونها. لكن بطرس يقول «ملقين»، أي نرمي بها خارجنا. وهذا يتطلب ثقة بأن الله يهتم. وهو لا يقول إنه سيحل كل مشكلة كما نريد، بل إنه «يعتني». وأحيانًا تكون عنايته بأن يعطينا قوة نحتملها. والآية السابقة تدعونا إلى التواضع: الاعتراف بأننا لا نتحكم في كل شيء.\\nاذكر اليوم همًا يشغلك، وارفع يديك وقل: «يا رب ألقيته عليك»، ولا تعد تحمله بقية اليوم.\"},{\"t\":\"على قدر مشيئة الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب نيلوس ألا نرغب أن تأتي الأمور كما نتمنى بل كما يشاء الله، فنكون بلا اضطراب ولا همّ ومسرورين في صلاتنا. هذه خلاصة إلقاء الهم: قبول المشيئة. ما الأمر الذي تريده بطريقتك وتتعب بسببه اليوم؟\",\"p\":\"يا رب، لتكن مشيئتك لا مشيئتي. علّمني أن أرضى بما ترتبه، وأن أصلي بلا اضطراب أو همّ. آمين.\",\"x\":\"على قدر مشيئة الله نقبل ما يأتينا، فالقبول يعطي سلامًا. تدريب: اختر أمرًا لا تستطيع تغييره، وسلّمه لمشيئة الله اليوم.\",\"fq\":294}]},\"4-5\":{\"th\":\"التحرر من الخوف\",\"m\":[{\"t\":\"أنا هو، لا تخافوا\",\"ref\":\"إنجيل الستار\",\"v\":\"نظروا يسوع ماشيا على البحر، مقتربا إلى السفينة فخافوا. فقال لهم: أنا هو، لا تخافوا. فقبلوا أن يحملوه معهم في السفينة، وللوقت جاءت السفينة إلى شاطئ الأرض التي كانوا ذاهبين إليها.\",\"r\":\"كان البحر هائجًا والظلام قد حل ولم يكن يسوع معهم، فلما اقترب خافوا أيضًا. ثم قال لهم: أنا هو، لا تخافوا. حين قبلوه في السفينة وصلوا في الحال. الخوف يتحرر حين نقبل حضور المسيح في قاربنا. ادعه اليوم إلى قارب يومك.\",\"p\":\"يا يسوع، أنت تقترب وسط الأمواج وتقول لي: أنا هو لا تخافوا. أقبلك في سفينة حياتي، فتوصلني بسلام إلى حيث ترسلني. آمين.\",\"x\":\"البحر هائج والظلام والمسيح غير حاضر في نظر التلاميذ، فلما اقترب قال: أنا هو لا تخافوا. حضوره يغير المشهد دون أن يغير البحر فورًا. تدريب: في أكثر ما يخيفك قل: أنا هو لا تخف، وكأن المسيح يكلمك.\"},{\"t\":\"لا تخف لأني معك\",\"ref\":\"إشعياء ٤١: ١٠\",\"bk\":\"إشعياء\",\"v\":\"لا تخف لأني معك. لا تتلفت لأني إلهك. قد أيدتك وأعنتك وعضدتك بيمين بري.\",\"r\":\"«لا تخف لأني معك، لا تتلفت لأني إلهك. قد أيدتك وأعنتك وعضدتك بيمين برّي». خمسة أفعال إلهية تواجه خوفي: معية، إلوهية، تأييد، معونة، عضد. ولا أحتاج أن أنظر حولي بقلق فهو كل ما أحتاجه. والخوف يفقد قوته حين أضع عيني على الله.\",\"p\":\"يا رب، أنت معي فلا أخاف. شددني وأعني وعضدني بيمين بِرّك، وأبعد عني كل تلفت وقلق، وثبّت نظري عليك. آمين.\",\"x\":\"الله يعالج الخوف بوعد حضوره قبل أن يعالجه بحل المشكلة. فالحضور أهم من الحل. وهو «يمين البر» أي قوة العدل. وبهذا يكون سندنا موثوقًا. والخوف يتغذى على التخيل والتلفت. أما الإيمان فيتغذى على الوعد. وفي سير القديسين نرى كيف عبروا الخطر بسلام لأنهم ركزوا على «إلهي معي».\\nاكتب أكبر خوف عندك الآن، وضع تحته: «لا تخف لأني معك»، وردد الآية عندما يظهر الخوف.\"},{\"t\":\"لا تخف من الأموات\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب كيرس لأخ تزعجه ذكريات الأفكار القديمة: لا تكن من الأموات خائفًا، بل تحاش الأحياء وأطل صلاتك. أي لا تدع الماضي يرعبك، بل اجعل الصلاة ملجأ. ما الذي يخيفك من الماضي؟ ضعه في صلاتك اليوم.\",\"p\":\"يا رب، حرّرني من خوف الماضي ومن أفكاره القديمة. أطل صلاتي وأقوّ إيماني، وكن أنت سلامي. آمين.\",\"x\":\"لا نخاف من الأموات ولا من المجهول إن كان الله معنا. تدريب: اذكر خوفًا مبالغًا فيه، وقدّمه لله ببساطة.\",\"fq\":225}]},\"4-6\":{\"th\":\"الثبات في المسيح\",\"m\":[{\"t\":\"اثبتوا فيّ وأنا فيكم\",\"ref\":\"إنجيل الثالثة\",\"v\":\"أنا هو الكرمة الحقيقية وأبى الكرام. كل غصن في لا يأتي بثمر يقطعه. وكل ما يأتي بثمر ينقيه ليأتي بثمر أكثر. وأنتم من قبل أنقياء من أجل الكلام الذي كلمتكم به. اثبتوا في وأنا أيضا فيكم.\",\"r\":\"يشبّه المسيح علاقتنا به بالكرمة والأغصان: غصن بلا كرمة لا يثمر، وغصن في الكرمة ينقّيه الآب ليأتي بثمر أكثر. الثبات ليس مجهودًا بل بقاء في المصدر. أبقِ قلبك اليوم متصلًا بالمسيح بصلاة قصيرة بين كل عمل وآخر.\",\"p\":\"يا رب يسوع، أنت الكرمة الحقيقية وأنا الغصن. ثبّتني فيك وثبّت كلامك فيّ، ونقِّني لأثمر ثمرًا أكثر. آمين.\",\"x\":\"الغصن لا يثمر إن انفصل عن الكرمة، فالثبات في المسيح شرط الثمر. تدريب: اربط يومك بالمسيح بثلاث نقاط صلاة: الصباح والظهر والمساء.\"},{\"t\":\"سيروا فيه\",\"ref\":\"كولوسي ٢: ٦–٧\",\"bk\":\"كولوسي\",\"v\":\"فكما قبلتم المسيح يسوع الرب اسلكوا فيه، متأصلين ومبنيين فيه، وموطدين في الإيمان، كما علمتم، متفاضلين فيه بالشكر.\",\"r\":\"«فكما قبلتم المسيح يسوع الرب اسلكوا فيه، متأصلين ومبنيين فيه وموطدين في الإيمان». كما بدأت العلاقة بقبول المسيح، تستمر بالسلوك فيه. ثلاث صور: شجرة متأصلة، وبناء، وإيمان موطد. وكل صورة تذكرني أن الإيمان ينمو بالعمق والاستقرار.\",\"p\":\"يا رب، كما قبلتك أسلك فيك. أصّلني فيك وابنِني عليك ووطّدني في الإيمان، واملأني شكرًا يفيض على كل من حولي. آمين.\",\"x\":\"التأصل للجذور والبناء للأساس والتوطيد للثبات. وكلها صور للنمو في الخفاء، ثم الثمر في العلن. والنتيجة «فائضين فيه بالشكر». فالنمو الروحي الحقيقي يظهر شكرًا. وإذا لم نشكر فهناك شيء ناقص. وبولس يحذر في الآية التالية من أن «لا يسبيكم أحد بالفلسفة». فالجذور العميقة تحمي من الأفكار المتقلبة.\\nاكتب خمسة أشياء تشكر الله عليها اليوم، وراقب كيف يتغير قلبك.\"},{\"t\":\"النار تحت المرجل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب بيمن الإنسان الثابت بالمرجل الذي تشتعل تحته النار، فلا تقدر الذبابة أن تدنو منه، أما إذا برد فتقترب منه الحشرات. الحرارة الروحية هي الحماية. ما الذي يحفظ حرارتك الروحية اليوم؟ لا تتركه.\",\"p\":\"يا رب، أشعل فيّ نار محبتك لتحميني من كل فتور. أبقني ثابتًا فيك وملتهبًا بالروح. آمين.\",\"x\":\"النار تحت المرجل تُبقي الماء ساخنًا، والثبات في الروح يحتاج مصدر حرارة دائمًا. تدريب: اجعل لك طقسًا يوميًا ثابتًا، كالقراءة، ولا تكسره اليوم.\",\"fq\":391}]},\"4-7\":{\"th\":\"عيد البشارة\",\"m\":[{\"t\":\"اسمعي يا ابنتي وانظري\",\"ref\":\"المزمور ٤٤ (٤٥) — الثالثة\",\"v\":\"اسمعي يا ابنتي وانظري وأميلي أذنك، وانسي شعبك وبيت أبيك. فإن الملك قد اشتهى حسنك.\",\"r\":\"في عيد البشارة تسمع الكنيسة صدى هذا المزمور مع كلام الملاك للعذراء. «اسمعي وأميلي أذنك»: بداية الدعوة أن نصغي. قبلت مريم الرسالة بتواضع قائلة: هوذا أنا أمة الرب. ما رسالة الله إليك اليوم؟ أصغِ إليها بقلب مفتوح.\",\"p\":\"افتح يا رب أذني لأسمعك كما سمعت العذراء، وقلبي لأقبل ما تقوله لي. ليكن لي حسب قولك، وأنت تظلل على حياتي. آمين.\",\"x\":\"في البشارة يقول الملاك لمريم: الرب معك، وتجيب بطاعة كاملة. والمزمور يدعو: اسمعي يا ابنتي وانظري. تدريب: اقرأ لوقا ١: ٢٦-٣٨ بتأن، وردد جواب مريم.\"},{\"t\":\"لا تخافي يا مريم\",\"ref\":\"لوقا ١: ٣٠–٣١\",\"bk\":\"لوقا\",\"v\":\"فقال لها الملاك: «لا تخافي يا مريم، لأنك قد وجدت نعمة عند الله. وها أنت ستحبلين وتلدين ابنا وتسمينه يسوع.\",\"r\":\"«لا تخافي يا مريم لأنك قد وجدت نعمة عند الله». أول ما يقوله الله لمن يدعوه هو «لا تخف». لأن الدعوة الكبرى تحمل خوفًا طبيعيًا. وما يطمئن ليس غياب الصعوبة بل «نعمة عند الله». وهكذا أتعلم أن أقابل دعوات الله بإيمان لا بقلق.\",\"p\":\"يا رب، علّمني ألا أخاف من دعوتك. كما وجدت مريم نعمة عندك، أنعم عليّ بقلب مؤمن مطيع، يسأل بصدق ويقبل بفرح. آمين.\",\"x\":\"سؤال مريم: «كيف يكون هذا وأنا لست أعرف رجلًا؟» ليس شكًا بل استفهام يطلب الفهم. فأجابها الملاك. والله يرحب بالأسئلة الصادقة. وقد أعلن لها اسم «يسوع» أي المخلص، وأنه «ابن العلي» وأن «لملكه نهاية لا تكون». فكل الوعود جاءت في تلك اللحظة. وكل ما كان مجهولًا لمريم أصبح بالإيمان طريقًا. وكذلك دعوة كل واحد منا.\\nإن كان الله يدعوك لخطوة تخيفك، فاسأله كما سألت مريم بصدق، وانتظر إرشاده.\"},{\"t\":\"الطاعة أمّ الفضائل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يهتف الأب روفو بالطاعة: يا خلاص جميع المؤمنين، يا أمّ جميع الفضائل، يا محقّقة الملكوت. وتعلمنا العذراء أن الطاعة لا تعني ضعفًا بل قبولًا حرًا لمشيئة الله. اجعل «ليكن لي» عبارة تقولها اليوم أمام أول أمر لا تفهمه.\",\"p\":\"يا رب، علّمني طاعة العذراء. اجعل «ليكن لي» تتردد في قلبي كل يوم، فتتم مشيئتك فيّ. آمين.\",\"x\":\"الطاعة أم الفضائل لأنها تفتح الباب لكل نعمة. تدريب: نفذ اليوم أمرًا من أب اعترافك أو مسؤولك بلا نقاش.\",\"fq\":482}]},\"4-8\":{\"th\":\"الطاعة الكاملة\",\"m\":[{\"t\":\"علّمني يا رب طريقك\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"علمني يا رب طريقك. واهدني في سبيل مستقيم من أجل أعدائي.\",\"r\":\"الطاعة الكاملة تبدأ بتعلّم الطريق: «علّمني يا رب طريقك واهدني في سبيل مستقيم». لا نطيع في الظلام بل بإرشاد. ومن يسأل بتواضع يُهدَ. اطلب اليوم من الله أن يريك الخطوة التالية في أمر لم تحسمه.\",\"p\":\"علّمني يا رب طريقك، واهدني في سبيل مستقيم. أعطني قلبًا يطيع وأذنًا تسمع، فأسير بسلام في مشيئتك. آمين.\",\"x\":\"الطاعة الكاملة تبدأ بالتعلم: علمني يا رب طريقك. تدريب: قبل أن تتصرف اليوم في موقف جديد قل: علمني يا رب طريقك.\"},{\"t\":\"الله العامل فيكم\",\"ref\":\"فيلبي ٢: ١٢–١٣\",\"bk\":\"فيلبي\",\"v\":\"إذا يا أحبائي، كما أطعتم كل حين، ليس كما في حضوري فقط، بل الآن بالأولى جدا في غيابي، تمموا خلاصكم بخوف ورعدة، لأن الله هو العامل فيكم أن تريدوا وأن تعملوا من أجل المسرة.\",\"r\":\"«تمموا خلاصكم بخوف ورعدة، لأن الله هو العامل فيكم أن تريدوا وأن تعملوا من أجل المسرة». الطاعة ليست نتيجة جهدي وحده، فالله يعمل في إرادتي وفعلي. وأنا مدعو أن أتعاون معه. وهذا يحميني من اليأس والكبرياء معًا.\",\"p\":\"يا رب، أنت العامل فيّ أن أريد وأن أعمل. قوِّ إرادتي وأعنّي على الطاعة، وتمم فيّ خلاصك بنعمتك وجهادي. آمين.\",\"x\":\"التعاون بين النعمة والجهاد أساس الحياة الروحية. فنحن لا نخلص بأعمالنا لكن لا نخلص بغير جهاد. و«خوف ورعدة» لا تعني ذعرًا، بل جدية وتوقيرًا. والله يعطي الإرادة والقدرة. وإن شعرت بضعف في الإرادة فاطلب أن يعمل هو فيك. وقد وعد المزمور: «افتح فمك فأملأه». فنطلب نعمة الإرادة.\\nاطلب من الله اليوم أن يقوّي إرادتك في أمر معين، ثم خطُ خطوة صغيرة نحوه.\"},{\"t\":\"أطاع حتى الموت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيبريخيوس إن الطاعة جوهرة موروثة، ومن يمتلكها يحفظه المصلوب، لأن الرب الذي صُلب من أجلنا أطاع حتى الموت. الطاعة الحقيقية تشبه طاعة المسيح: محبة وليست خوفًا. اطع اليوم فيما لا تحب، متذكرًا طاعته.\",\"p\":\"أيها الرب المصلوب، علّمني الطاعة التي أطعتها لأبيك. ألبسني هذه الجوهرة، وثبّتني في مشيئتك. آمين.\",\"x\":\"يعلمنا أن المسيح أطاع حتى الموت، فنحن في طاعتنا نتبعه. تدريب: اقبل اليوم أمرًا ثقيلًا باتضاع ككل خطوة تتبع بها المسيح.\",\"fq\":555}]},\"4-9\":{\"th\":\"رحمة الله الجديدة\",\"m\":[{\"t\":\"أسمعني رحمتك بالغداة\",\"ref\":\"المزمور المئة والثاني والأربعون — باكر\",\"v\":\"فلأسمع في الغدوات رحمتك، فإني عليك توكلت. عرفني يا رب الطريق التي أسلك فيها، لأني إليك رفعت نفسي.\",\"r\":\"يبدأ المرنم يومه بطلب رحمة الله في الصباح، كأن الرحمة تتجدد مع كل غداة. لا يعيش الله على رصيد الأمس فينا، بل يجدد رحمته. ابدأ يومك اليوم بكلمة: يا رب لا أستحق، لكنك رحوم. وقم بثقة جديدة.\",\"p\":\"أسمعني رحمتك بالغداة يا رب لأني عليك توكلت. عرّفني الطريق التي أسلك فيها، فإني إليك رفعت نفسي. آمين.\",\"x\":\"يبدأ المرنم يومه بطلب الرحمة في الصباح، فرحمة الله جديدة كل غداة. تدريب: ابدأ اليوم بقول: أسمعني رحمتك بالغداة، ثم اعمل بقية يومك على هذا الأساس.\"},{\"t\":\"هي جديدة كل صباح\",\"ref\":\"مراثي إرميا ٣: ٢٢–٢٣\",\"bk\":\"مراثي إرميا\",\"v\":\"إنه من إحسانات الرب أننا لم نفن، لأن مراحمه لا تزول. هي جديدة في كل صباح. كثيرة أمانتك.\",\"r\":\"«إحسانات الرب إنها لا تفنى، لأن مراحمه لا تزول. هي جديدة في كل صباح، كثيرة أمانتك». كتبها إرميا وسط خراب أورشليم. وفي أحلك الأوقات وجد رجاءه في أمانة الله. وكل صباح يبدأ برحمة جديدة، فلا أبدأ بحمل أخطاء الأمس، بل بمراحم اليوم.\",\"p\":\"يا رب، أشكرك لأن مراحمك جديدة كل صباح. اغفر لي أخطاء الأمس، وامنحني بداية جديدة اليوم، وعلّمني أن أثق في أمانتك الكثيرة. آمين.\",\"x\":\"قد لا يكون لدينا في الأيام الصعبة ما نفرح به، لكن لدينا ما نتذكره: أمانة الله. وذكرها يجدد الرجاء. وقد أصبحت هذه الآيات ترنيمة في الكنيسة: «كثيرة أمانتك». وكل صباح هو فرصة جديدة. والله لا يُحصي سقطاتي بل يمنحني بداية جديدة. وهذه هي الصورة التي تقود التوبة اليومية.\\nعند الاستيقاظ غدًا قل: «مراحمك جديدة هذا الصباح يا رب»، وابدأ يومك بها.\"},{\"t\":\"انتبه للمستقبل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّمنا الأب بيمن كيف نتعامل مع من أخطأ: لا نبكته فنثبّط عزيمته، بل نقول له: لا تحزن يا أخي، انتبه للمستقبل. هكذا يعاملنا الله برحمته الجديدة. فتعامل اليوم مع نفسك ومع غيرك بهذه اللغة.\",\"p\":\"يا رب، ارحمني برحمتك الجديدة كل صباح. وعلّمني أن أكون رحيمًا بمن أخطأ، وأن أشجعه على البدء من جديد. آمين.\",\"x\":\"الانتباه للمستقبل يعني أن نبني اليوم ما سنحصده لاحقًا، فلنضع بذرة خير. تدريب: ابدأ عادة صغيرة اليوم تفيدك بعد سنة.\",\"fq\":324}]},\"4-10\":{\"th\":\"الحياة الأبدية\",\"m\":[{\"t\":\"البهجة في يمينك\",\"ref\":\"المزمور الخامس عشر — باكر\",\"v\":\"تملأني فرحا مع وجهك. البهجة في يمينك إلى الانقضاء.\",\"r\":\"الحياة الأبدية في كلمات المرنم ليست بعيدة: فرح مع وجه الله وبهجة في يمينه إلى الانقضاء. تبدأ الأبدية حين نعرف الله. اسأل نفسك اليوم: هل ما أطلبه من الحياة يوصلني إلى هذه البهجة أم يبعدني عنها؟\",\"p\":\"تملأني فرحًا مع وجهك يا رب، والبهجة في يمينك إلى الانقضاء. اجعل شوقي إلى حياتك الأبدية أقوى من كل رغبة. آمين.\",\"x\":\"الحياة الأبدية فرح في يمين الله، وهي تبدأ هنا لمن يعرفه. تدريب: اطلب اليوم لحظة فرح حقيقي من الله، وانتبه لها حين تأتي.\"},{\"t\":\"هذه هي الحياة الأبدية\",\"ref\":\"يوحنا ١٧: ٣\",\"bk\":\"يوحنا\",\"v\":\"وهذه هي الحياة الأبدية: أن يعرفوك أنت الإله الحقيقي وحدك ويسوع المسيح الذي أرسلته.\",\"r\":\"«وهذه هي الحياة الأبدية: أن يعرفوك أنت الإله الحقيقي وحدك ويسوع المسيح الذي أرسلته». الحياة الأبدية تبدأ الآن بمعرفة الله، وليست مجرد حياة بعد الموت. والمعرفة هنا ليست معلومات بل علاقة حية. وكلما تعمقت علاقتي به عشت أبديتي الآن.\",\"p\":\"يا رب، أشتاق أن أعرفك أكثر. علّمني أن أعيش الحياة الأبدية الآن بالشركة معك، وافتح قلبي لتعرف الآب والابن بروحك القدوس. آمين.\",\"x\":\"المعرفة في الكتاب تعني اتحادًا وشركة، كما في «عرف آدم امرأته». وهكذا فإن معرفة الله هي اختبار حبه. وهي تنمو بالصلاة والكلمة والأسرار. وكل يوم يزيد فيه معرفتي به هو يوم في الحياة الأبدية. فلا أنتظر إلى ما بعد الموت لأبدأ. والمسيح قال هذا قبل صلبه بساعات، فهو أهم ما يريده لنا.\\nاسأل نفسك: ماذا أعرف عن الله هذا الأسبوع لم أكن أعرفه؟ وخصص وقتًا لتتعرف عليه أكثر.\"},{\"t\":\"اعمل ما يقودك إلى الخلاص\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس: «إذا كنت تشتاق إلى الخلاص، اعمل كل ما من شأنه أن يقودك إليه». الشوق وحده لا يكفي، بل الخطوة العملية. ماذا يمكن أن تفعله اليوم لتقترب من الله: صلاة أو اعتراف أو صدقة؟\",\"p\":\"يا رب، أنا أشتاق إلى خلاصك، فأعطني قوة أن أعمل ما يقودني إليك. آمين.\",\"x\":\"اعمل ما يقودك إلى الله وابتعد عما يبعدك، وهي قاعدة بسيطة. تدريب: اختر اليوم نشاطًا يقربك من الله ونشاطًا يبعدك، وقدّم الأول.\",\"fq\":202}]},\"4-11\":{\"th\":\"الوكالة الأمينة\",\"m\":[{\"t\":\"الذي يتراءف ويقرض\",\"ref\":\"المزمور ١١١ (١١٢) — التاسعة\",\"v\":\"صالح هو الرجل الذي يتراءف ويقرض ويدبر أقواله بالحق، لأنه لا يتزعزع إلى الدهر. ذكر الصديق يدوم إلى الأبد، ولا يخشى من خبر السوء.\",\"r\":\"يصف المرنم الصالح بأنه يتراءف ويقرض ويدبر أقواله بالحق، فلا يخشى خبر السوء. هذه هي الوكالة الأمينة: أن أعتبر ما عندي أمانة أتصرف فيها بحكمة ورحمة. أي أمانة تحتاج إلى تدبير أفضل في وقتك أو مالك اليوم؟\",\"p\":\"يا رب، علّمني أن أدبّر أقوالي وأموالي بالحق والرحمة. اجعلني وكيلًا أمينًا لما استودعتني، فلا أخشى خبر السوء. آمين.\",\"x\":\"الصالح يتراءف ويقرض ويدبر أقواله بالحق، فالأمانة في المال والكلام معًا. تدريب: راجع إنفاقك الأسبوع، وخصص جزءًا للعطاء.\"},{\"t\":\"أعطى كل واحد حسب طاقته\",\"ref\":\"متى ٢٥: ١٥\",\"bk\":\"متى\",\"v\":\"فأعطى واحدا خمس وزنات، وآخر وزنتين، وآخر وزنة. كل واحد على قدر طاقته. وسافر للوقت.\",\"r\":\"«فأعطى واحدًا خمس وزنات وآخر وزنتين وآخر وزنة، كل واحد على قدر طاقته». الله لا يظلمني بمقارنة غيري، ولا يطلب مني ما لم يعطني. وأنا مسؤول عن وزنتي أنا لا وزنات الآخرين. وهذا يحميني من الحسد والاستهانة بنفسي.\",\"p\":\"يا رب، أشكرك على ما أعطيتني على قدر طاقتي. علّمني ألا أحسد غيري ولا أحتقر وزنتي، بل أستخدمها بفرح وأمانة. آمين.\",\"x\":\"العبد الذي نال وزنتين ربح وزنتين، وقال السيد له ما قاله لمن ربح خمسًا: «نعمًّا أيها العبد الصالح». فالمدح لم يختلف لأن الأمانة واحدة. وهذا يفتح لنا الباب: الصغير والكبير مدعوان لنفس الأمانة. وإن كانت وزنتي صغيرة فلا أحتقرها. فصلاة بسيطة أو ابتسامة أو خدمة منسية قد تساوي عند الله أكثر من أعمال ظاهرة.\\nلا تقارن نفسك اليوم بأحد. اسأل: ما الوزنة الصغيرة التي أعطاني الله اليوم؟ واستخدمها.\"},{\"t\":\"أتمم عملي وأنا أعولك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سلوان: أنا عبد وسيدي قال لي: أتمم عملي وأنا أعولك. الوكيل الأمين يقوم بما عليه ويترك الباقي للسيد. لا تتوقف اليوم عن العمل خوفًا من النتائج، بل أتمّ ما كُلفت به وسلّم الباقي.\",\"p\":\"يا رب، أنا عبدك، فأتمم عملي بأمانة وأنت تعولني. أعطني ثقة في تدبيرك لما لا أستطيعه. آمين.\",\"x\":\"أتمم عمله وهو يعمل بيديه صلاة، فالوكالة الأمينة تجمع العمل والعبادة. تدريب: أتقن عملك اليوم كأنك تقدمه لله.\",\"fq\":513}]},\"4-12\":{\"th\":\"فرح القيامة\",\"m\":[{\"t\":\"حولتَ نوحي إلى فرح\",\"ref\":\"المزمور ٢٩ (٣٠) — الثالثة\",\"v\":\"سمع الرب فرحمني، الرب صار لي عونا. حولت نوحي إلى فرح لي؛ مزقت مسحي ومنطقتني سرورا. لكي ترتل لك نفسي ولا يحزن قلبي.\",\"r\":\"يشهد المرنم لفرح ما بعد الحزن: حولت نوحي إلى فرح، ومزقت مسحي ومنطقتني سرورًا. هذه صورة القيامة: الحزن لا يُمحى بل يتحول. تذكّر اليوم موقفًا حزينًا حوّله الله فرحًا، وسبّحه عليه بصوت عالٍ.\",\"p\":\"سمعت يا رب فرحمتني، وصرت لي عونًا. حولت نوحي إلى فرح، لترتل لك نفسي ولا يحزن قلبي. لك المجد. آمين.\",\"x\":\"حول الله نوح المرنم إلى فرح ومزق مسحه، فالقيامة تنزع ثياب الحزن. تدريب: غيّر شيئًا صغيرًا اليوم يرمز للفرح، مثل ثوب أو ترنيمة.\"},{\"t\":\"فرح التلاميذ\",\"ref\":\"يوحنا ٢٠: ٢٠\",\"bk\":\"يوحنا\",\"v\":\"ولما قال هذا أراهم يديه وجنبه، ففرح التلاميذ إذ رأوا الرب.\",\"r\":\"«فلما قال هذا أراهم يديه وجنبه، ففرح التلاميذ إذ رأوا الرب». الفرح لم يأتِ من تغيير الظروف بل من رؤية الرب. والجراح التي يحملها تؤكد أنه هو، وأنه انتصر. وأنا أيضًا أجد فرحي الأول في لقائه، قبل أن تتغير ظروفي.\",\"p\":\"يا رب القائم، أرني يديك وجنبك فأفرح. حوّل حزني فرحًا بلقائك، وامنحني فرحًا لا ينزعه أحد منّي. المسيح قام، بالحقيقة قام. آمين.\",\"x\":\"فرح القيامة مختلف: إنه فرح خرج من القبر. وقد وعد المسيح: «فرحكم لا ينزعه أحد منكم». وهذا الفرح لا يلغي الألم، لكنه يحمله. وكل قداس هو لقاء مع القائم. وكل قراءة في الإنجيل نظرة إليه. والفرح هو العلامة الأولى لحضور المسيح. وإن افتقدناه فلنقترب إليه.\\nاجلس اليوم عند صورة المسيح القائم أو اقرأ نص القيامة، وانتظر أن يفرح قلبك برؤيته.\"},{\"t\":\"فرح لا يوصف\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سينكليتيكي إن التعب والجهاد يكثران في البداية عند الذين يتقدمون نحو الله، لكن بعد ذلك يغمرهم فرح لا يوصف، كمن يشعل النار فيلفحه الدخان ثم يفرح بالنور. لا تيأس من دخان الجهاد، فوراءه فرح.\",\"p\":\"يا رب، قوّني في الجهاد، ولا تدعني أتوقف عند دخان البداية. أذقني فرحك الذي لا يوصف. آمين.\",\"x\":\"فرح القيامة لا يوصف، ومن ذاقه يطلبه دائمًا. تدريب: قل لشخص اليوم: المسيح قام، بفرح حقيقي.\",\"fq\":531}]},\"4-13\":{\"th\":\"المسيح رفيق الطريق\",\"m\":[{\"t\":\"لأنك أنت معي\",\"ref\":\"المزمور ٢٢ (٢٣) — الثالثة\",\"v\":\"إن سلكت في وسط ظلال الموت فلا أخاف شرا، لأنك أنت معي. عصاك وعكازك هما يعزيانني.\",\"r\":\"لا يعد الراعي بغياب ظلال الموت، بل بأن يكون معنا فيها: «لا أخاف شرًا لأنك أنت معي». ورفيق الطريق يظهر في أضيق الأماكن. هل في طريقك اليوم ظل ثقيل؟ تذكّر أنك لا تسير فيه وحدك.\",\"p\":\"إن سلكت في وسط ظلال الموت فلا أخاف شرًا لأنك أنت معي، وعصاك وعكازك يعزيانني. كن معي في طريقي كله. آمين.\",\"x\":\"الراعي لا يعد بغياب ظلال الموت بل بوجوده فيها، فلا أخاف شرًا لأنك معي. تدريب: ردد: لأنك أنت معي في أي ممر مظلم تمر به اليوم.\"},{\"t\":\"أمكث معنا\",\"ref\":\"لوقا ٢٤: ٢٩\",\"bk\":\"لوقا\",\"v\":\"فألزماه قائلين: «امكث معنا، لأنه نحو المساء وقد مال النهار». فدخل ليمكث معهما.\",\"r\":\"«أمكث معنا لأنه نحو المساء وقد مال النهار». كانت دعوة بسيطة من قلب محتاج. والمسيح «تظاهر أنه منطلق»، لكنه ينتظر الدعوة. وكم مرة يتيح لي الله الاختيار أن أدعوه! والدعوة تفتح باب الشركة. وفي المساء تزداد حاجتي إليه.\",\"p\":\"يا رب، أمكث معنا لأنه نحو المساء. ادخل بيتي وقلبي، وكن ضيفي ثم مضيفي، وافتح عينيّ لأعرفك في كل ما أمرّ به. آمين.\",\"x\":\"هذه العبارة صارت صلاة في الكنيسة، ويرددها المؤمنون في المساء: «أمكث معنا». فنحن نحتاج حضوره عند غروب اليوم أو العمر أو الفرح. والله لا يفرض نفسه، بل يطلب دعوة. وبعد أن دخل، جلس معهما وكسر الخبز فانفتحت أعينهما. فالدعوة تقود إلى معرفة. وعندما نفتح بابنا له يصير ضيفًا ثم يصير مضيفًا.\\nقبل أن تنام اليوم قل بصدق: «أمكث معي يا رب هذه الليلة».\"},{\"t\":\"ليكن الله نصب عينيك\",\"ref\":\"\",\"v\":\"\",\"r\":\"أجاب القديس أنطونيوس من سأله ماذا يحفظ لكي يرضي الله: حيثما تذهب ليكن الله نصب عينيك. هذه هي الصحبة: أن يرافقنا في كل خطوة. فاسأل نفسك وأنت في الطريق اليوم: أين أنت من حضور الله؟\",\"p\":\"يا رب، ليكن حضورك أمام عيني حيثما ذهبت. ارافقني كما رافقت تلميذي عمواس، وافتح عيني لأعرفك. آمين.\",\"x\":\"ليكن الله في فكرنا أولًا، فيصير كل شيء تحت نظره. تدريب: اجعل اسم الله أول ما تذكره عند الاستيقاظ.\",\"fq\":1}]},\"4-14\":{\"th\":\"الروح القدس المعزي\",\"m\":[{\"t\":\"هلمّ تفضل وحل فينا\",\"ref\":\"قطعة مشتركة — نصف الليل — الخدمة الثالثة\",\"v\":\"أيها الملك السمائي المعزي، روح الحق، الحاضر في كل مكان والمالئ الكل، كنز الصالحات ومعطي الحياة، هلم تفضل وحل فينا، وطهرنا من كل دنس أيها الصالح، وخلص نفوسنا.\",\"r\":\"هذه صلاة الكنيسة للروح القدس المعزي: حاضر في كل مكان ومالئ الكل، لكننا نطلب أن يحل فينا. وجوده معنا ليس إلغاء لسؤالنا، فالروح يحل حيث يُدعى. اطلبه اليوم بهذه الكلمات قبل أول عمل مهم.\",\"p\":\"أيها الملك السمائي المعزي، روح الحق، هلم تفضل وحل فينا. طهرنا من كل دنس، وخلص نفوسنا، واعزِّني في كل ضيق. آمين.\",\"x\":\"صلاة الكنيسة للروح القدس تدعوه: هلم تفضل وحل فينا. الروح المعزي حاضر في كل مكان ويملأ كل شيء. تدريب: قبل أن تبدأ عملًا اليوم قل: هلم حل فينا.\"},{\"t\":\"أبناء الله\",\"ref\":\"رومية ٨: ١٤\",\"bk\":\"رومية\",\"v\":\"لأن كل الذين ينقادون بروح الله، فأولئك هم أبناء الله.\",\"r\":\"«لأن كل الذين ينقادون بروح الله فأولئك هم أبناء الله». أن أكون ابنًا ليس مجرد لقب بل حياة تنقاد. والروح ينقاد بها من يصغي. وهو يقودني إلى الحق والسلام والمحبة. وكلما استسلمت لقيادته تعمّقت بنوتي.\",\"p\":\"يا روح الله، قُدني كما يُقاد الأبناء. أعطني روح التبني لأصرخ: يا أبا الآب، وحرّرني من الخوف، وثبّتني في بنوّتي لك. آمين.\",\"x\":\"بولس يتابع: «لأنكم لم تأخذوا روح العبودية أيضًا للخوف بل أخذتم روح التبني الذي به نصرخ يا أبا الآب». فالروح يحررنا من الخوف ويعطينا ثقة الأبناء. ونحن نصلي «أبانا» لأن الروح فينا. والانقياد ليس إلغاء للإرادة بل اتحاد بها بإرادة الله. ومن انقاد بالروح عرف السلام حتى في الضغوط.\\nقل اليوم «أبا الآب» بقلب مطمئن في صلاتك، وانتبه لشعور البنوة.\"},{\"t\":\"أهرع إلى الشجرة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يصف الأب يوحنا الكولوفي نفسه بإنسان تحت شجرة كبيرة يرى وحوشًا تقترب، فيهرع إلى الشجرة فينجو. هكذا نلجأ إلى الله. الروح القدس هو العزاء في الخطر. اللجوء الفوري في أول خوف أفضل من محاولة المواجهة وحدنا.\",\"p\":\"يا رب، أهرع إليك عندما تقترب الوحوش. كن أنت ملجئي وعزائي، وأنا آمن في ظلك. آمين.\",\"x\":\"الإسراع إلى الله عند الخطر هو أصل الأمان. تدريب: عند أول تجربة اليوم أهرع إلى صلاة قصيرة قبل أن تفكر.\",\"fq\":154}]},\"4-15\":{\"th\":\"مواهب الروح\",\"m\":[{\"t\":\"رتلوا بفهم\",\"ref\":\"المزمور ٤٦ (٤٧) — الثالثة\",\"v\":\"رتلوا لإلهنا رتلوا، رتلوا لمليكنا رتلوا، لأن الرب هو ملك الأرض كلها. رتلوا بفهم لأن الرب قد ملك على جميع الأمم.\",\"r\":\"التسبيح بفهم يعني أن نغني ونعرف لمن نغني. والروح القدس يعطي كل واحد موهبة للنفع المشترك، وكل موهبة تصلح أن تتحول إلى تسبيح في الكنيسة. ما الذي أعطاك الله إياه ولا تستخدمه؟ قدمه اليوم ولو في خدمة صغيرة.\",\"p\":\"رتلوا لإلهنا رتلوا، رتلوا بفهم. يا رب، أنت ملك الأرض كلها، فاستخدم مواهبي لمجدك ولبنيان إخوتي. آمين.\",\"x\":\"التسبيح بفهم يعني أن نعرف لمن ولماذا نسبح، والروح يعطي مواهب متنوعة للبنيان. تدريب: اختر آية تسبيح تفهم معناها وردّدها اليوم بتأمل.\"},{\"t\":\"لبنيان جسد المسيح\",\"ref\":\"أفسس ٤: ١١–١٢\",\"bk\":\"أفسس\",\"v\":\"وهو أعطى البعض أن يكونوا رسلا، والبعض أنبياء، والبعض مبشرين، والبعض رعاة ومعلمين، لأجل تكميل القديسين لعمل الخدمة، لبنيان جسد المسيح،\",\"r\":\"«وهو أعطى البعض أن يكونوا رسلًا والبعض أنبياء والبعض مبشرين والبعض رعاة ومعلمين، لأجل تكميل القديسين لعمل الخدمة لبنيان جسد المسيح». غاية الخدمة ليست أن يفعل الخادم كل شيء، بل أن يعد كل المؤمنين للخدمة. فكل واحد في الكنيسة خادم بنوع ما.\",\"p\":\"يا رب، أشكرك على من أعطيتهم لكنيستك رعاة ومعلمين. أهّلنا جميعًا لعمل الخدمة، واجعلنا نبني بعضنا في الوحدة والمحبة. آمين.\",\"x\":\"هذا يغير نظرتنا: الكنيسة ليست كهنة يخدمون وشعبًا يشاهد، بل جماعة كلها تخدم بمواهبها. والرعاة والمعلمون مهمتهم تدريب الباقين. والنتيجة: «إلى أن ننتهي جميعنا إلى وحدانية الإيمان». فالنمو جماعي. ولا نكون «أطفالًا مضطربين». والاستقرار الروحي يأتي من العمل المشترك. وكل خدمة، مهما صغرت، تبني.\\nاعرض على خادم في كنيستك أن تقدم ساعة خدمة هذا الأسبوع في مجال تجيده.\"},{\"t\":\"الكلام كثير والعمل قليل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يعقوب إن حاجتنا ليست إلى الكلام لأنه في هذا الزمان كثير، إنما إلى العمل. المواهب تتحول إلى خدمة بالعمل لا بالكلام. اسأل: ما عمل اليوم الذي أعدّه الروح لي؟ ابدأ به ولا تؤجله.\",\"p\":\"يا رب، أعطني أن أعمل بما أعطيتني. لا يكفي الكلام، فاجعل مواهبي ثمرًا ينفع كنيستك. آمين.\",\"x\":\"الكلام كثير والعمل قليل مشكلة قديمة. تدريب: نفذ اليوم وعدًا قلته ولم تحققه.\",\"fq\":190}]},\"4-16\":{\"th\":\"التربية بمحبة\",\"m\":[{\"t\":\"طوبى للسالكين في طرقه\",\"ref\":\"المزمور ١٢٧ (١٢٨) — الغروب\",\"v\":\"طوبى لجميع الذين يتقون الرب السالكين في طرقه. تأكل من ثمرة أتعابك تصير مغبوطا ويكون لك الخير.\",\"r\":\"يربط المزمور بين تقوى الأب وسلام البيت. التربية بمحبة تبدأ من سلوك الوالدين أنفسهم في طرق الرب، فالأبناء يتعلمون بالنظر أكثر من الاستماع. ما الذي يراه أبناؤك أو أخوتك الصغار منك اليوم؟ اجعله يستحق التقليد.\",\"p\":\"طوبى لجميع الذين يتقون الرب السالكين في طرقه. اجعلني قدوة صالحة لمن أربيهم، وبارك تعبي في بيتي ليأتي بخير. آمين.\",\"x\":\"طوبى للسالكين في طرقه، فبيت الأب التقي هو بيت السلام. تدريب: ابدأ مع أولادك أو أخوتك لحظة صلاة بسيطة قبل النوم.\"},{\"t\":\"نخبر الجيل الآتي\",\"ref\":\"المزامير ٧٨: ٤\",\"bk\":\"المزامير\",\"v\":\"لا نخفي عن بنيهم إلى الجيل الآخر، مخبرين بتسابيح الرب وقوته وعجائبه التي صنع.\",\"r\":\"«لا نخفي عن بنيهم إلى الجيل الأخير مخبرين بتسابيح الرب وقوته وعجائبه التي صنع». قصص الله في حياتنا ليست لنا وحدنا، إنها ميراث للجيل التالي. وأن أحكي لأولادي كيف نصرني الله هو أعمق أشكال التعليم. والتسبيح ينتقل بالحكي.\",\"p\":\"يا رب، علّمنا أن نخبر الجيل الآتي بعجائبك. ولا تدعنا ننسى أعمالك معنا، وأعطنا أن نرويها بفرح لتثبّت إيمان أبنائنا فيك. آمين.\",\"x\":\"نقل الإيمان لا يتم بالمعلومات فقط بل بالقصص. وكل عائلة لها قصص عن عناية الله: شفاء وحماية وإجابة صلاة. ولو لم نحكها ضاعت. والمزمور ٧٨ يستعرض تاريخ شعب الله ليتعلم الأبناء ألا ينسوا. وقد قال: «لكي يجعلوا على الله اتكالهم ولا ينسوا أعمال الله». فالذاكرة سلاح الإيمان.\\nاحكِ اليوم لشخص أصغر منك قصة قصيرة عن موقف رأيت فيه يد الله في حياتك.\"},{\"t\":\"ثلاثة أمور نافعة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يلخّص الأب بيمن ما ينفع في ثلاث كلمات: مخافة الرب والصلاة والإحسان إلى القريب. وهي أيضًا أساس التربية الناجحة: أن يرى الصغير الصلاة والإحسان ويتعلم المخافة. أي واحدة منها تحتاج إلى مزيد من حضور في بيتك؟\",\"p\":\"يا رب، اجعل في بيتي مخافتك والصلاة والإحسان. ربِّ أبناءنا بمحبتك، وأعطنا حكمة أن نعلمهم بأعمالنا. آمين.\",\"x\":\"ثلاثة أمور نافعة تحفظ النفس، فاختر واحدًا منها لتعمل به اليوم. تدريب: اسأل أب اعترافك عن الأمور الثلاثة ونفذ واحدة.\",\"fq\":433}]},\"4-17\":{\"th\":\"قبول الآخر\",\"m\":[{\"t\":\"الرب يحفظ الغرباء\",\"ref\":\"المزمور ١٤٥ — النوم\",\"v\":\"الرب يحفظ الغرباء. ويعضد اليتيم والأرملة.\",\"r\":\"يمدح المرنم الله الذي يحفظ الغرباء ويعضد اليتيم والأرملة. قبول الآخر يبدأ حين أنظر إليه بنظرة الله. من هو الغريب في محيطك: زميل جديد، جار، أو شخص مختلف عنك؟ اقترب منه اليوم بكلمة ترحيب.\",\"p\":\"أيها الرب الذي تحفظ الغرباء وتعضد اليتيم والأرملة، علّمني أن أقبل كل إنسان كما قبلتني. وسّع قلبي بمحبتك. آمين.\",\"x\":\"الرب يحفظ الغرباء ويعضد اليتيم والأرملة، فمن يقبل الغريب يقبل المسيح. تدريب: رحب اليوم بشخص جديد في كنيستك أو عملك.\"},{\"t\":\"اقبلوا بعضكم بعضًا\",\"ref\":\"رومية ١٥: ٧\",\"bk\":\"رومية\",\"v\":\"لذلك اقبلوا بعضكم بعضا كما أن المسيح أيضا قبلنا، لمجد الله.\",\"r\":\"«لذلك اقبلوا بعضكم بعضًا كما أن المسيح أيضًا قبلنا لمجد الله». المسيح قبلني بضعفي وخطاياي. فكيف لا أقبل أخي؟ وقبوله ليس عاطفة بل قرار: أن أرحب به وأفتح له مكانًا. وهذا يمجد الله لأنه يظهر محبته في الجماعة.\",\"p\":\"يا رب، قبلتني كما أنا لمجدك. أعطني أن أقبل إخوتي بنفس المحبة، وأن نمجدك معًا بقلب واحد وفم واحد. آمين.\",\"x\":\"قبل هذه الآية يصلي بولس: «وإله الصبر والتعزية يعطيكم أن تهتموا اهتمامًا واحدًا بعضكم لبعض». فالقبول عطية من الله نطلبها. وقبول المسيح لنا لم يكن بعد أن تحسّنا بل ونحن بعد خطاة. وكذلك ينبغي أن نقبل بعضنا. وحين تظهر بيننا اختلافات فلنتذكر هذا النموذج. ونصلي معًا لنمجد الله بفم واحد.\\nقدم اليوم ترحيبًا خاصًا لشخص جديد أو منعزل في كنيستك أو عملك.\"},{\"t\":\"مددتُ المائدة ست مرات\",\"ref\":\"\",\"v\":\"\",\"r\":\"يحكي الشيخ لكسيانوس أنه من أجل الإخوة الزوار مدّ المائدة ست مرات وهو يتوسل إلى كل واحد أن يأكل ويأكل معه. القبول فعل ضيافة، لا مجرد تسامح. استقبل اليوم أحدًا في بيتك أو في وقتك بسخاء حقيقي.\",\"p\":\"يا رب، علّمني الضيافة والترحيب بالجميع. اجعل بيتي وقلبي مفتوحين لكل من ترسله إليّ. آمين.\",\"x\":\"مدّ المائدة مرات كثيرة لاستقبال الضيف، فقبول الآخر عمل صبور. تدريب: افتح بيتك لشخص هذا الأسبوع ولو لفنجان قهوة.\",\"fq\":210}]},\"4-18\":{\"th\":\"بيت الله\",\"m\":[{\"t\":\"طوبى للساكنين في بيتك\",\"ref\":\"المزمور ٨٣ (٨٤) — السادسة\",\"v\":\"طوبى لكل الساكنين في بيتك. يباركونك إلى الأبد.\",\"r\":\"بيت الله ليس مبنى فقط بل مكان يسكن فيه المؤمنون ويباركون الله إلى الأبد. السكنى فيه علاقة وليست زيارة. هل علاقتك بالكنيسة حضور شكلي أم سكنى؟ شارك اليوم بكلمة أو خدمة تجعلك أقرب.\",\"p\":\"طوبى للساكنين في بيتك، يباركونك إلى الأبد. اجعلني ساكنًا في كنيستك بقلبي، وأجد فيها بيتي الروحي. آمين.\",\"x\":\"طوبى للساكنين في بيت الله، فهم يباركونه دائمًا. تدريب: خصص اليوم لحظة تشكر فيها الله على الكنيسة التي تصلي فيها.\"},{\"t\":\"يوم في ديارك\",\"ref\":\"المزامير ٨٤: ١٠\",\"bk\":\"المزامير\",\"v\":\"لأن يوما واحدا في ديارك خير من ألف. اخترت الوقوف على العتبة في بيت إلهي على السكن في خيام الأشرار.\",\"r\":\"«لأن يومًا واحدًا في ديارك خير من ألف. اخترت الوقوف على العتبة في بيت إلهي على السكنى في خيام الأشرار». هذا ليس ترفًا لفظيًا بل اشتياق حقيقي. ما قيمة ألف يوم بعيدًا عن الله؟ ويوم واحد معه يملأ العمر. فأين أضع أولوية زمني؟\",\"p\":\"يا رب، ما أحلى مساكنك. اجعلني أشتاق إلى بيتك أكثر من أي مكان، وأحب الوقوف على عتبته بتواضع، وأعيش فيه بقلبي حتى حين أكون بعيدًا عنه بجسدي. آمين.\",\"x\":\"المرنم يشتاق إلى بيت الله لأنه يرى الله فيه. وقد نذهب إلى الكنيسة بعادة، لكن القلب يمكن أن يتوق إليها كما يتوق العطشان إلى الماء. وقد يكون المقصود الوقوف حتى على «العتبة» بالتواضع. ولا نحتاج مكانة، بل حضورًا. ومن يحب بيت الله يحب شعبه ويصير جزءًا من أسرته.\\nاحضر إلى الكنيسة قبل ميعاد الخدمة بدقائق اليوم أو في أقرب فرصة، واجلس بهدوء قبل البدء.\"},{\"t\":\"ما نحفظه عندما نخرج\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيرينيوس إن حفظ القانون في القلاية ليس فضيلة كبيرة، إنما المهم أن نحفظه عندما نخرج. ما نتعلمه في بيت الله يمتحن في الطريق والعمل. فاحمل اليوم شيئًا من الكنيسة إلى أول موقف صعب.\",\"p\":\"يا رب، ما أسمعه في بيتك أحفظه حين أخرج. اجعل حياتي كلها امتدادًا لعبادتي لك. آمين.\",\"x\":\"ما نحفظه عند الخروج من الكنيسة يحدد قيمة العبادة. تدريب: خذ معك من القداس القادم كلمة واحدة واعمل بها.\",\"fq\":523}]},\"4-19\":{\"th\":\"الخضوع لله\",\"m\":[{\"t\":\"كعيون العبيد إلى أيدي مواليهم\",\"ref\":\"المزمور ١٢٢ (١٢٣) — الغروب\",\"v\":\"إليك رفعت عيني يا ساكن السماء. فها هما مثل عيون العبيد إلى أيدي مواليهم. ومثل عيني الأمة إلى يدي سيدتها. كذلك أعيننا نحو الرب إلهنا حتى يتراءف علينا.\",\"r\":\"الخضوع لله ينظر إلى يد السيد في كل حاجة ولا يتكل على نفسه. هو يرفع عينيه إلى ساكن السماء ينتظر أن يتراءف. الخضوع ليس إذلالًا بل ثقة. هل ترفع عينيك اليوم إلى الله أم إلى حيلك؟ اجعل نظرك إليه.\",\"p\":\"إليك رفعت عيني يا ساكن السماء، كعيون العبيد إلى أيدي مواليهم. أعيننا نحوك حتى تتراءف علينا. آمين.\",\"x\":\"كعيون العبيد إلى أيدي مواليهم تكون عيوننا إلى الرب، ننتظر عطيته في كل حاجة. تدريب: قبل أي طلب اليوم، قل: عيناي إليك يا رب.\"},{\"t\":\"الرب أعطى والرب أخذ\",\"ref\":\"أيوب ١: ٢١\",\"bk\":\"أيوب\",\"v\":\"وقال: «عريانا خرجت من بطن أمي، وعريانا أعود إلى هناك. الرب أعطى والرب أخذ، فليكن اسم الرب مباركا».\",\"r\":\"«عريانًا خرجت من بطن أمي وعريانًا أعود إلى هناك. الرب أعطى والرب أخذ فليكن اسم الرب مباركًا». لم يتجاهل أيوب الألم، فقد مزّق ثوبه وجز شعره، لكنه سجد وبارك. والخضوع ليس إنكارًا للجرح بل ثقة في سيادة الله.\",\"p\":\"يا رب، أنت أعطيت وأنت أخذت، فليكن اسمك مباركًا. أسلم لك ما أملك وما فقدت، وأعطني قلبًا يسجد ويثق في كل حال. آمين.\",\"x\":\"يقول الكتاب: «في كل هذا لم يخطئ أيوب ولم ينسب لله جهالة». أي لم يتهمه. ولا يعني هذا أن التساؤلات ممنوعة، فقد سأل أيوب كثيرًا فيما بعد. لكن في اللحظة الأولى اختار التسبيح. وهذا يعلمنا أن نبدأ بالتسليم حتى ونحن نبكي. ثم تأتي الأسئلة والفهم. وكل ما نملكه عطية يمكن أن تُسترد.\\nإن كنت تمر بخسارة فاذكر اسم الله بالبركة اليوم ولو بكلمة واحدة: «مبارك اسمك».\"},{\"t\":\"السور النحاسي\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن إرادة الإنسان سور نحاسي بينه وبين الله. الخضوع يهدم هذا السور. ما الذي تصرّ عليه بإرادتك رغم أنك تعلم أنه يبعدك عن الله؟ اترك قرارك اليوم لمشيئته.\",\"p\":\"يا رب، أهدم سور إرادتي الذي يفصلني عنك. علّمني الخضوع لمشيئتك الصالحة المرضية. آمين.\",\"x\":\"السور النحاسي يحمي المدينة، وهكذا يحمي الصبر والاتضاع النفس. تدريب: ابنِ لنفسك سورًا واحدًا اليوم، مثل عدم الاستجابة لاستفزاز.\",\"fq\":352}]},\"4-20\":{\"th\":\"الكتاب المقدس\",\"m\":[{\"t\":\"فرائض الرب تفرح القلب\",\"ref\":\"المزمور الثامن عشر — باكر\",\"v\":\"فرائض الرب مستقيمة، تفرح القلب. وصية الرب مضيئة؛ تنير العينين عن بعد.\",\"r\":\"تحدّث المرنم عن فرائض الرب كأنها فرحة: تفرح القلب وتنير العينين. الكتاب المقدس ليس عبئًا بل نور. قبل أن تشغل بالك بأخبار اليوم، افتح الإنجيل وخصص له نفس الوقت الذي تعطيه لهاتفك.\",\"p\":\"فرائض الرب مستقيمة تفرح القلب، ووصية الرب مضيئة تنير العينين. يا رب، نوّر عيني بكلمتك كل يوم. آمين.\",\"x\":\"فرائض الرب تفرح القلب وتنير العينين، فليست الوصية ثقلًا بل نور. تدريب: اقرأ وصية واحدة اليوم وتأمل كيف تجلب فرحًا.\"},{\"t\":\"كلمة الله حية وفعالة\",\"ref\":\"العبرانيين ٤: ١٢\",\"bk\":\"العبرانيين\",\"v\":\"لأن كلمة الله حية وفعالة وأمضى من كل سيف ذي حدين، وخارقة إلى مفرق النفس والروح والمفاصل والمخاخ، ومميزة أفكار القلب ونياته.\",\"r\":\"«لأن كلمة الله حية وفعالة وأمضى من كل سيف ذي حدين». الكلمة ليست حبرًا على ورق، إنها حية تعمل فيّ. تخترق وتكشف وتشفي. وقد تؤلمني أحيانًا، لكنها كالمشرط الذي يعالج. وكلما قرأتها بتواضع كشفت لي نفسي بحنان.\",\"p\":\"يا رب، كلمتك حية وفعالة. اخترق قلبي بنورها واكشف ما يحتاج إلى شفاء، وقوّني لأطيعها وأعيش بها كل يوم. آمين.\",\"x\":\"الكلمة «تميز أفكار القلب ونياته». أي أنها تعرّي ما نخفيه حتى عن أنفسنا. وهذا ليس لإذلالنا بل لشفائنا. ثم يقول الكاتب إن كل شيء «عريان ومكشوف لعيني ذلك الذي معه أمرنا». فالله يعرف كل شيء. وهذا يدعونا إلى الصدق والنقاء. والاستعداد لسماع الكلمة يتطلب قلبًا مفتوحًا لا مدافعًا.\\nاقرأ اليوم نصًا قصيرًا واسأل: «ما الذي تكشفه هذه الكلمة في داخلي؟»، ثم قدم ما يظهر لله.\"},{\"t\":\"جهل الكتب هاوية\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس إبيفانيوس إن جهل الكتب المقدسة هاوية عميقة ومنخفض سحيق. من لا يعرف الكتاب يضل في طرق كثيرة. فاسأل نفسك: ما أقل ما أعرفه من الكتاب وما أحتاج إليه؟ ابدأ به.\",\"p\":\"يا رب، احفظني من هاوية الجهل. افتح ذهني لفهم كتبك، واجعلني أنمو في معرفتك كل يوم. آمين.\",\"x\":\"من يقرأ الكتب المقدسة يملك ضمانة قوية ضد الخطية. تدريب: اجعل القراءة أول ما تفعله بعد الاستيقاظ.\",\"fq\":101}]},\"4-21\":{\"th\":\"الصبر على النفس\",\"m\":[{\"t\":\"إلى متى أردد هذه المشورات؟\",\"ref\":\"المزمور ١٢ (١٣) — باكر\",\"v\":\"إلى متى أردد هذه المشورات في نفسي، وهذه الأوجاع في قلبي النهار كله؟\",\"r\":\"يعبّر المرنم عن تعب النفس من أفكارها: إلى متى أردد هذه المشورات في نفسي وهذه الأوجاع في قلبي؟ الصبر على النفس يبدأ بالاعتراف بالتعب بلا جلد للذات. ارفق بنفسك اليوم، فالله يرفق بك، وضع أمامه ما يدور في ذهنك.\",\"p\":\"إلى متى أردد هذه المشورات في نفسي وهذه الأوجاع في قلبي النهار كله؟ يا رب، أنت صبور على نفسي، فعلّمني الصبر عليها. آمين.\",\"x\":\"يتعب المرنم من أفكاره: إلى متى أردد هذه المشورات؟ والنفس التي تحاور نفسها طويلًا تحتاج إلى الله. تدريب: اكتب فكرة تكررها ثم سلّمها لله بجملة صلاة.\"},{\"t\":\"الكتب مكتوبة لتعليمنا\",\"ref\":\"رومية ١٥: ٤\",\"bk\":\"رومية\",\"v\":\"لأن كل ما سبق فكتب كتب لأجل تعليمنا، حتى بالصبر والتعزية بما في الكتب يكون لنا رجاء.\",\"r\":\"«لأن كل ما سبق فكتب كتب لأجل تعليمنا حتى بالصبر والتعزية بما في الكتب يكون لنا رجاء». الكتاب يعلّمني ويعزيني ويعطيني صبرًا ورجاء. وقصص الأنبياء والأبرار فيه ليست تاريخًا فقط بل مرايا لحياتي. وكلما قرأت شعرت أنني لست وحدي في الصراع.\",\"p\":\"يا رب، أشكرك على قصص الأبرار التي تعلّمني. اجعل كلمتك تعزيتي وصبري ورجائي، وقوّني بها في أوقات الانتظار الطويلة. آمين.\",\"x\":\"قصص إبراهيم الذي انتظر سنين، ويوسف الذي صبر على السجن، وأيوب الذي تحمل الفقد، كلها تعطينا صبرًا ورجاء. والله لم يتركهم. وهكذا لن يتركنا. فنقرأ الكتاب لنتغذى بالأمل. وعندما نمر بوقت ضعف فلنفتح الكتاب على المزامير أو الأناجيل ونصلي بكلماتها. فالتعزية تأتي من الكلمة الحية.\\nاقرأ اليوم قصة من قصص الصبر في الكتاب (مثل يوسف) وتأمل في كيف عمل الله في الانتظار.\"},{\"t\":\"الأفكار تموت مع الوقت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب بيمن الأفكار الشريرة بثعبان أو عقرب في وعاء، يموتان مع الوقت إذا لم نغذِّهما. الصبر على النفس أن أنتظر موت فكر دون أن أتبعه. ما الفكرة التي تغذيها ولا تحتاج إليها؟ توقف عن تغذيتها اليوم.\",\"p\":\"يا رب، أعطني صبرًا على أفكاري لأتركها تموت ولا أغذيها. نقِّ ذهني بنعمتك. آمين.\",\"x\":\"الأفكار تموت إذا لم نغذها، فلا نقاتلها بل نتركها. تدريب: لا تحاور فكرة سلبية اليوم، حوّل انتباهك إلى عمل.\",\"fq\":323}]},\"4-22\":{\"th\":\"الخطايا الخفية\",\"m\":[{\"t\":\"من الخطايا المستترة طهرني\",\"ref\":\"المزمور الثامن عشر — باكر\",\"v\":\"الهفوات من يشعر بها؟ من الخطايا المستترة يا رب طهرني.\",\"r\":\"يسأل المرنم: الهفوات من يشعر بها؟ ثم يطلب: من الخطايا المستترة يا رب طهرني. نحن لا نرى كل ما فينا، فنحتاج أن يكشفه الله. أنهِ يومك اليوم بخمس دقائق تسأل فيها الله أن يريك ما خفي عنك.\",\"p\":\"الهفوات من يشعر بها؟ من الخطايا المستترة يا رب طهرني. افحص قلبي وأرني ما أخفيه عن نفسي. آمين.\",\"x\":\"يطلب المرنم أن يطهره الله من الخطايا المستترة، فهناك ما لا نراه في أنفسنا. تدريب: اطلب من الله أن يكشف لك عيبًا خفيًا، وكن مستعدًا لسماعه.\"},{\"t\":\"اختبرني يا الله\",\"ref\":\"المزامير ١٣٩: ٢٣–٢٤\",\"bk\":\"المزامير\",\"v\":\"اختبرني يا الله واعرف قلبي. امتحني واعرف أفكاري. وانظر إن كان في طريق باطل، واهدني طريقا أبديا.\",\"r\":\"«اختبرني يا الله واعرف قلبي، امتحني واعرف أفكاري، وانظر إن كان فيّ طريق باطل واهدني طريقًا أبديًا». هذه شجاعة روحية: أن أدعو الله ليفحصني. وهو لا يفحص ليدين بل ليهدي. فالفحص مدخل للهداية.\",\"p\":\"اختبرني يا الله واعرف قلبي، امتحنني واعرف أفكاري. وانظر إن كان فيّ طريق باطل، واهدني طريقًا أبديًا بنعمتك. آمين.\",\"x\":\"قبل هذه الآيات تأتي أعداد قاسية عن الأشرار، وكأن داود يتدارك: «لا بد أن أبدأ بنفسي». وهذا درس مهم: عندما نغضب من الشر ننظر أولًا إلى قلوبنا. وفحص الضمير المسائي ممارسة قديمة في الكنيسة. نسأل: ماذا فعلت اليوم؟ وأين قصّرت؟ وأين شكرت؟ ثم نطلب الهداية.\\nقبل النوم قم بفحص ضمير في خمس دقائق: ثلاثة أشياء للشكر، وواحد للتوبة، وواحد للغد.\"},{\"t\":\"أن يشعر بأنه خاطئ\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب موسى الحبشي إن الإنسان إذا لم يشعر في أعماقه أنه خاطئ لا يصغي إليه الله. الإحساس بالخطية بداية الاستجابة، وهو نعمة. اطلب اليوم هذا الإحساس بلا قلق مرضي ولا يأس.\",\"p\":\"يا رب، أعطني أن أشعر بخطيتي وأقف أمامك بتواضع. اسمع صلاتي واغفر لي. آمين.\",\"x\":\"الشعور بالخطية نعمة، فمن لا يشعر لا يتوب. تدريب: اطلب أن تشعر بخطاياك بنور لا بيأس.\",\"fq\":262}]},\"4-23\":{\"th\":\"الشهادة بالأمانة\",\"m\":[{\"t\":\"أمام الملائكة أرتل لك\",\"ref\":\"المزمور ١٣٧ — النوم\",\"v\":\"أعترف لك يا رب من كل قلبي لأنك استمعت كل كلمات فمي. أمام الملائكة أرتل لك وأسجد قدام هيكلك المقدس، وأعترف لاسمك على رحمتك وحقك.\",\"r\":\"يعلن المرنم اعترافه أمام الملائكة وفي الهيكل. الشهادة بالأمانة تبدأ باعتراف علني بالإيمان في الأمور الصغيرة قبل الكبيرة. هل تخجل من إعلان إيمانك في مكان عملك أو دراستك؟ تقدم اليوم بخطوة اعتراف بسيطة.\",\"p\":\"أعترف لك يا رب من كل قلبي، وأرتل لك أمام الملائكة، وأسجد قدام هيكلك المقدس. اجعلني شاهدًا أمينًا لاسمك. آمين.\",\"x\":\"يرتل المرنم أمام الملائكة، فعبادتنا تتحد بالسماء. تدريب: قبل أن تصلي اليوم تذكر أن الملائكة تحيط بك.\"},{\"t\":\"من اعترف بي قدام الناس\",\"ref\":\"متى ١٠: ٣٢\",\"bk\":\"متى\",\"v\":\"فكل من يعترف بي قدام الناس أعترف أنا أيضا به قدام أبي الذي في السماوات،\",\"r\":\"«فكل من يعترف بي قدام الناس أعترف أنا أيضًا به قدام أبي الذي في السماوات». وعد جميل: المسيح لا ينسى من يشهد له. والاعتراف لا يعني صراخًا بل صدقًا في إعلان الانتماء. وأنا مدعو أن أعيش علنًا كمسيحي: في كلامي وسلوكي وأخلاقي.\",\"p\":\"يا رب يسوع، أعترف بك أمام الناس بفرح. لا تدعني أخجل منك، واعترف بي أمام أبيك في السماء، وقوّني لأحمل صليبي وأتبعك. آمين.\",\"x\":\"الاعتراف يشمل الكلمة والسلوك والاختيارات. وقد يكلفنا السخرية أو الخسارة، لكن المسيح يعتبر ذلك شركة معه. وبعد الآية يقول إن من لا يحمل صليبه لا يستحقه. والصليب هنا يعني القبول بالتضحية لأجل الحق. ويضيف: «من وجد حياته يضيعها ومن أضاع حياته من أجلي يجدها». فالخسارة من أجل المسيح ربح.\\nلا تخجل اليوم من إظهار إيمانك بطريقة طبيعية: إشارة الصليب قبل الأكل، أو ذكر اسم الله بمحبة في كلامك.\"},{\"t\":\"لا خلاص بدون تجارب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أنطونيوس: «لا أحد يقدر أن يدخل ملكوت السموات بدون تجارب، ارفع التجارب فلا يخلص أحد». الشاهد الأمين لا يفرّ من التجربة بل يجتازها بالله. ما التجربة التي تواجهها وتظن أنها تعطلك؟ قد تكون هي طريقك.\",\"p\":\"يا رب، قوّني في التجارب لأثبت شاهدًا لك. علّمني أن أرى فيها طريقًا إلى ملكوتك. آمين.\",\"x\":\"الأمانة في الشهادة تحتاج إلى ثبات. تدريب: قل اليوم الحقيقة في أمر ما حتى لو أحرجتك.\",\"fq\":3}]},\"4-24\":{\"th\":\"هأنذا أرسلني\",\"m\":[{\"t\":\"مستعد قلبي يا الله\",\"ref\":\"المزمور ٥٦ (٥٧) — السادسة\",\"v\":\"مستعد قلبي يا الله مستعد قلبي. أسبح وأرتل في تمجيدي.\",\"r\":\"«هأنذا أرسلني» تبدأ بقلب مستعد: مستعد قلبي يا الله مستعد قلبي. الاستعداد يعني أن أقف على باب العمل قبل أن أعرف ما هو. فكّر اليوم: لو ناداك الله الآن لمهمة محددة، هل قلبك مستعد؟\",\"p\":\"مستعد قلبي يا الله، مستعد قلبي. أسبح وأرتل في تمجيدي. أرسلني يا رب إلى حيث تشاء، وقوّني لأحمل رسالتك. آمين.\",\"x\":\"هأنذا أرسلني تبدأ بقلب مستعد: مستعد قلبي يا الله. تدريب: قل لله اليوم: هأنذا، ثم انتظر أن يريك خدمة تقدمها.\"},{\"t\":\"إناء مختار\",\"ref\":\"أعمال الرسل ٩: ١٥–١٦\",\"bk\":\"أعمال الرسل\",\"v\":\"فقال له الرب: «اذهب! لأن هذا لي إناء مختار ليحمل اسمي أمام أمم وملوك وبني إسرائيل. لأني سأريه كم ينبغي أن يتألم من أجل اسمي».\",\"r\":\"«اذهب لأن هذا لي إناء مختار ليحمل اسمي أمام أمم وملوك وبني إسرائيل». كان شاول مضطهِدًا، لكن الله رأى فيه ما لا يراه الناس. وهذا يعطيني رجاء: ربما يرى الله فيّ إناءً مختارًا رغم ماضيّ. وفي الوقت نفسه يذكر الألم: فالدعوة ليست رخاءً.\",\"p\":\"يا رب، اجعلني إناءً مختارًا لاسمك. أعطني طاعة حنانيا وشجاعة بولس، واستخدمني لتبلغ محبتك إلى من لا أتوقعهم، واحتمل معي الألم. آمين.\",\"x\":\"حنانيا كان خائفًا من شاول، لكنه أطاع. فصار سببًا لتحول أعظم رسول. وقد نكون مثل حنانيا نُطلب لنخدم من نخافه أو نشك فيه، ويكون في طاعتنا بركة كبيرة. وقد نكون مثل شاول، يُغير الله قلبنا. وعلى كل حال، الدعوة تحتاج استعدادًا للألم والتعب. لكنها تحمل مجدًا أعظم. والله يرافق من يرسله.\\nاسأل نفسك: هل هناك شخص أخاف من الاقتراب منه وأشعر أن الله يريدني أن أخدمه؟ اتخذ خطوة صغيرة نحوه.\"},{\"t\":\"ذلّل نفسك لأخيك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب بيمن: «لا تشبع مشيئتك، لكن بالأحرى ذلِّل نفسك لأخيك». الإرسالية خدمة للآخر قبل أن تكون إنجازًا. ما الذي يمكنك اليوم أن تتنازل عنه لأجل راحة أخ؟ ابدأ بهذه الخطوة.\",\"p\":\"يا رب، علّمني أن أذلل نفسي لأخي وأضع مشيئتك فوق مشيئتي. أرسلني لأخدم من أجلك. آمين.\",\"x\":\"تذليل النفس للأخ يعني أن نتنازل عن كبرياء الموقف. تدريب: اعتذر لأخ اليوم عن موقف تلكأت في الاعتذار عنه.\",\"fq\":431}]},\"4-25\":{\"th\":\"ثمر الحياة\",\"m\":[{\"t\":\"كالشجرة المغروسة\",\"ref\":\"المزمور الأول — باكر\",\"v\":\"لكن في ناموس الرب إرادته، وفي ناموسه يلهج نهارا وليلا. فيكون كالشجرة المغروسة على مجارى المياه التي تعطى ثمرها في حينه. وورقها لا ينتثر، وكل ما يصنع ينجح فيه.\",\"r\":\"يصور المرنم المؤمن شجرة مغروسة على مجاري المياه، تعطي ثمرها في حينه ولا ينتثر ورقها. الثمر نتيجة جذور وصبر، وليس شيئًا يُصنع بالقوة. ما الذي تغذي به جذورك اليوم: وقتًا مع كلمة الله أم مجرد انشغال؟\",\"p\":\"يا رب، اجعل إرادتي في ناموسك، وأمل بي كشجرة على مجاري المياه تعطي ثمرها في حينه. بارك كل ما أصنع بنعمتك. آمين.\",\"x\":\"كالشجرة المغروسة على المياه، يثمر المؤمن في وقته، فالثمر لا يُستعجل. تدريب: اسأل نفسك أي ثمر ينتظره الله منك، واسق جذوره بالصلاة.\"},{\"t\":\"اتركها هذه السنة أيضًا\",\"ref\":\"لوقا ١٣: ٦–٩\",\"bk\":\"لوقا\",\"v\":\"وقال هذا المثل: «كانت لواحد شجرة تين مغروسة في كرمه، فأتى يطلب فيها ثمرا ولم يجد. فقال للكرام: هوذا ثلاث سنين آتي أطلب ثمرا في هذه التينة ولم أجد. اقطعها! لماذا تبطل الأرض أيضا؟ فأجاب وقال له: يا سيد، اتركها هذه السنة أيضا، حتى أنقب حولها وأضع زبلا. فإن صنعت ثمرا، وإلا ففيما بعد تقطعها».\",\"r\":\"«يا سيد اتركها هذه السنة أيضًا حتى أنقب حولها وأضع زبلًا، فإن صنعت ثمرًا وإلا ففيما بعد تقطعها». الكرام يشفع في الشجرة. والمسيح يشفع فينا. ويعطينا مهلة، لا للتهاون بل للعمل. والله يعتني بنا بالتنقيب والسماد، أي بالتأديب والنعمة.\",\"p\":\"يا رب، أشكرك لأنك تشفع فيّ وتمهلني. افلح حول قلبي، وضع فيه سمادك، وأعطني أن أثمر ثمرًا يرضيك قبل أن تنتهي مهلتي. آمين.\",\"x\":\"المسيح لم يقل إن الشجرة ستثمر حتمًا، بل قال إنه سيعتني. والمسؤولية علينا أن نتجاوب. وقد تكون هذه السنة هي الفرصة الأخيرة. فنحن نعيش بمهلة الله. وتنقيب التربة قد يكون ألمًا، لكنه يفتح الجذور للماء. وسماد الحياة (الأحزان والصعوبات) قد يتحول إلى غذاء. فلنقبل عمل الله.\\nاسأل: ما «السماد» الذي يستخدمه الله في حياتي الآن؟ وكيف أقبل عمله لأثمر؟\"},{\"t\":\"الورق والثمر\",\"ref\":\"\",\"v\":\"\",\"r\":\"سُئل القديس أغاثون: أيهما أعظم، التعب الجسدي أم ضبط ما في الداخل؟ فشبّه الإنسان بشجرة: التعب الجسدي هو الورق وضبط الداخل هو الثمر. الله يطلب الثمر. ما الثمر الداخلي الذي تعمل عليه اليوم؟\",\"p\":\"يا رب، لا تدعني أكتفي بورق مظهر خارجي. اجعلني أحمل ثمر قلب نقي ومتضع ينفع الآخرين. آمين.\",\"x\":\"الورق والثمر مثل الكلام والعمل، والله يطلب الثمر. تدريب: ركز اليوم على عمل ملموس لا على كلام.\",\"fq\":49}]},\"4-26\":{\"th\":\"العدل والرحمة\",\"m\":[{\"t\":\"رحمة وحكمًا أسبحك\",\"ref\":\"المزمور ١٠٠ (١٠١) — التاسعة\",\"v\":\"رحمة وحكما أسبحك يا رب. أترنم لك. وأتفهم في طريق بلا عيب.\",\"r\":\"يربط المرنم بين الرحمة والحكم، كأنهما جناحا العدل. والعدل بدون رحمة قسوة، والرحمة بدون حق ضعف. وهو يتعهد أن يتفهم في طريق بلا عيب. في قرار تتخذه اليوم، اسأل: هل فيه رحمة وعدل معًا؟\",\"p\":\"رحمة وحكمًا أسبحك يا رب، وأترنم لك. اجعلني أتفهم في طريق بلا عيب، وأقضي بالعدل والرحمة. آمين.\",\"x\":\"الرحمة والحكم جناحا العدل، فلا عدل بلا رحمة ولا رحمة بلا حق. تدريب: عند الحكم على أحد اليوم، امزج الحق بالرحمة.\"},{\"t\":\"ما يطلبه الرب منك\",\"ref\":\"ميخا ٦: ٨\",\"bk\":\"ميخا\",\"v\":\"قد أخبرك أيها الإنسان ما هو صالح، وماذا يطلبه منك الرب، إلا أن تصنع الحق وتحب الرحمة، وتسلك متواضعا مع إلهك.\",\"r\":\"«قد أخبرك أيها الإنسان ما هو صالح وماذا يطلبه منك الرب: إلا أن تصنع الحق وتحب الرحمة وتسلك متواضعًا مع إلهك». ثلاثة أشياء بسيطة وصعبة معًا: عدل في التعامل، ورحمة في القلب، وتواضع في السير مع الله. وهذا هو جوهر الدين.\",\"p\":\"يا رب، علّمني أن أصنع الحق وأحب الرحمة وأسلك متواضعًا معك. اجعل حياتي تعكس ما تطلبه منّي، لا مظاهر خارجية فقط. آمين.\",\"x\":\"ميخا يقول ذلك بعد أن سأل الشعب عن الذبائح الكثيرة. وكأن الله يقول: لا أحتاج إلى مظاهر بل إلى حياة. والعدل يعني ألا أظلم، والرحمة ألا أقسو، والتواضع ألا أتكبر. وكل واحدة تحمي الأخرى: فالعدل بلا رحمة قسوة، والرحمة بلا عدل ضعف، وكلاهما بلا تواضع كبرياء. فلنمارسها معًا.\\nاختر من الثلاثة الجانب الأضعف عندك، وضع له عملًا ملموسًا اليوم.\"},{\"t\":\"الشر لا يبطل الشر\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: «الشر لا يبطل الشر أبدًا. إنما إذا أساء إليك أحد، أحسن إليه، لأنك بذلك تضحد الشر». هذا هو العدل المسيحي: لا مقابلة بالمثل بل إحسان يهزم الإساءة. من أساء إليك مؤخرًا؟ أحسن إليه بشيء بسيط.\",\"p\":\"يا رب، علّمني أن أغلب الشر بالخير. أعطني قلبًا يحسن لمن أساء إليّ، ولا يردّ الشر بشر. آمين.\",\"x\":\"الشر لا يبطل الشر، وحده الخير يبطله. تدريب: قابل إساءة اليوم بكلمة طيبة.\",\"fq\":446}]},\"4-27\":{\"th\":\"الإنسان الجديد\",\"m\":[{\"t\":\"أنت تعود فتحيينا\",\"ref\":\"المزمور ٨٤ (٨٥) — السادسة\",\"v\":\"أنت يا الله تعود فتحيينا، وشعبك يفرح بك. أرنا يا رب رحمتك. وأعطنا خلاصك.\",\"r\":\"الإنسان الجديد ليس صناعة ذاتية بل عودة الله إلينا وإحياؤه لنا: «أنت يا الله تعود فتحيينا وشعبك يفرح بك». نحن نطلب رحمته وخلاصه. ما الجزء من حياتك الذي تحتاج أن يعيد الله إحياءه؟ ارفعه اليوم بصلاة محددة.\",\"p\":\"أنت يا الله تعود فتحيينا، وشعبك يفرح بك. أرنا يا رب رحمتك وأعطنا خلاصك، وجدد فيّ إنساني الجديد. آمين.\",\"x\":\"أنت تعود فتحيينا: الإنسان الجديد عطية يعيدها الله لنا. تدريب: اطلب من الله أن يجدد فيك صفة واحدة، وتعاون معه بتغيير عادة.\"},{\"t\":\"لا تشاكلوا هذا الدهر\",\"ref\":\"رومية ١٢: ٢\",\"bk\":\"رومية\",\"v\":\"ولا تشاكلوا هذا الدهر، بل تغيروا عن شكلكم بتجديد أذهانكم، لتختبروا ما هي إرادة الله: الصالحة المرضية الكاملة.\",\"r\":\"«ولا تشاكلوا هذا الدهر بل تغيروا عن شكلكم بتجديد أذهانكم لتختبروا ما هي إرادة الله الصالحة المرضية الكاملة». هناك ضغط خفي لأتشبه بالعالم في تفكيره. لكن الله يدعوني لأتغير من الداخل. وبهذا التغيير أعرف إرادته: «صالحة مرضية كاملة».\",\"p\":\"يا رب، لا تدعني أشاكل هذا الدهر. غيّر أفكاري وقلبي بروحك، وأعطني أن أميّز إرادتك الصالحة المرضية الكاملة وأعمل بها. آمين.\",\"x\":\"تشاكل الدهر قد يظهر في التسرع والاستهلاك والمقارنة والسطحية. والتغيير يحدث بالتجديد الذي يعمله الروح فينا. وكلمة «تتغيروا» في اليونانية قريبة من «التحول» (metamorphosis)، أي كما تتحول اليرقة. وهذا تغيير عميق لا سطحي. ونتيجته: القدرة على تمييز إرادة الله. فالحكمة تأتي من التجديد.\\nانتبه اليوم لفكرة واحدة تتبناها من العالم، وقارنها بما يقوله الإنجيل.\"},{\"t\":\"التثاقل في كل بداية\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن التثاقل موجود في كل بداءة وليس هوى أردأ منه، لكن إذا عرف الإنسان ماهيته يرتاح. أي أن الإنسان الجديد يبدأ بمعرفة أن الفتور طبيعي في البدايات. لا تيأس من ثقل أول الطريق.\",\"p\":\"يا رب، أعطني نشاطًا في كل بداية، وصبرًا على ثقل أول الطريق. جدّد فيّ الحماس والمثابرة. آمين.\",\"x\":\"التثاقل في كل بداية أمر طبيعي، فلا نيأس منه. تدريب: ابدأ عملًا مؤجلًا بخمس دقائق فقط، وسترى أن البداية أصعب ما فيه.\",\"fq\":424}]},\"4-28\":{\"th\":\"العبادة الجماعية\",\"m\":[{\"t\":\"فرحت بالقائلين لي إلى بيت الرب نذهب\",\"ref\":\"المزمور ١٢١ (١٢٢) — الغروب\",\"v\":\"فرحت بالقائلين لي إلى بيت الرب نذهب. وقفت أرجلنا في ديار أورشليم: أورشليم المبنية مثل مدينة متصلة بعضها ببعض. لأن هناك صعدت القبائل؛ قبائل الرب، شهادة لإسرائيل؛ يعترفون لاسم الرب.\",\"r\":\"فرح المرنم حين دعاه الآخرون إلى بيت الرب، فالعبادة الجماعية تزرع الفرح حين نذهب معًا. وقفت الأرجل في ديار أورشليم المتصلة بعضها ببعض. من يمكنك أن تدعوه اليوم أو هذا الأسبوع ليذهب معك إلى الكنيسة؟\",\"p\":\"فرحت بالقائلين لي إلى بيت الرب نذهب. اجعل عبادتي مع إخوتي فرحًا وشركة، وبارك اجتماعنا باسمك. آمين.\",\"x\":\"فرح المرنم حين دعوه إلى بيت الرب، فالعبادة الجماعية فرح وليست واجبًا. تدريب: ادع شخصًا ليصلي معك أو ليحضر القداس.\"},{\"t\":\"ادخلوا أبوابه بحمد\",\"ref\":\"المزامير ١٠٠: ٤\",\"bk\":\"المزامير\",\"v\":\"ادخلوا أبوابه بحمد، دياره بالتسبيح. احمدوه، باركوا اسمه.\",\"r\":\"«ادخلوا أبوابه بحمد، دياره بالتسبيح، احمدوه باركوا اسمه». هذا هو أسلوب الدخول إلى الكنيسة والصلاة: بحمد لا بشكوى. وإن جئت متعبًا فأبدأ بالشكر، فهو يرفع القلب. والتسبيح يغيّر الجو الداخلي ويفتح للحضور الإلهي.\",\"p\":\"يا رب، أدخل أبوابك بحمد ودارك بتسبيح. أشكرك وأبارك اسمك، فأنت صالح وإلى الأبد رحمتك، وأعطني أن أعبدك بفرح مع الجماعة. آمين.\",\"x\":\"المزمور ١٠٠ يبدأ بـ«اهتفي للرب يا كل الأرض»، فالفرح هو بداية العبادة. ثم يؤكد: «اعلموا أن الرب هو الله، هو صنعنا ولسنا نحن». فالتسبيح اعتراف بالحقيقة. وفي ختام الآيات: «لأن الرب صالح، إلى الأبد رحمته». ونحن نردد هذا المزمور في الكنيسة. فتحية الدخول تتكرر لنا ولو كنا ندخل كل يوم.\\nعند دخولك الكنيسة أو بدء صلاتك اليوم، ابدأ بثلاث جمل شكر قبل أي طلب.\"},{\"t\":\"ماذا كان في فكرك؟\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح الأب بيمن من لم ينتفع بزيارة أخ أن يفتش في فكره عما كان فيه قبل دخوله، فيدرك سبب عدم انتفاعه. في اجتماع الكنيسة اليوم، افحص قلبك قبل أن تدخل: أي فكر تحمله معك؟\",\"p\":\"يا رب، طهّر فكري قبل أن أدخل بيتك. وأعطني أن أنتفع بكل اجتماع وأحتمل عيوب إخوتي بتواضع. آمين.\",\"x\":\"الذهاب إلى الجماعة يقوي النفس الضعيفة. تدريب: لا تتغيب اليوم عن اجتماع روحي بحجة التعب.\",\"fq\":444}]},\"4-29\":{\"th\":\"السكون والهدوء\",\"m\":[{\"t\":\"ثابروا واعلموا أني أنا الله\",\"ref\":\"المزمور ٤٥ (٤٦) — الثالثة\",\"v\":\"ثابروا واعلموا أني أنا هو الله، أرتفع بين الأمم وأتعالى في الأرض.\",\"r\":\"في وسط الحروب والضجيج يقول الله: ثابروا واعلموا أني أنا هو الله. السكون ليس غياب النشاط بل معرفة من هو الله. اجلس اليوم دقيقتين في صمت واحد بلا طلب، وقل فقط: أنت الله.\",\"p\":\"يا رب، أنت الله، ترتفع بين الأمم وتتعالى في الأرض. علّمني أن أسكن في حضرتك وأعلم أنك أنت الله. آمين.\",\"x\":\"وسط الضجيج يقول الله: اثبتوا واعلموا أني أنا الله. السكون بداية معرفته. تدريب: اجلس خمس دقائق بلا حركة، وقل فقط: أنت الله.\"},{\"t\":\"بالرجوع والسكون تخلصون\",\"ref\":\"إشعياء ٣٠: ١٥\",\"bk\":\"إشعياء\",\"v\":\"لأنه هكذا قال السيد الرب قدوس إسرائيل: «بالرجوع والسكون تخلصون. بالهدوء والطمأنينة تكون قوتكم». فلم تشاءوا.\",\"r\":\"«بالرجوع والسكون تخلصون، بالهدو والطمأنينة تكون قوتكم». معادلة غريبة على العالم: القوة في السكون. لكنها حقيقة روحية: من يرجع إلى الله ويهدأ يجد قوة. لكن الشعب «لم يشاءوا» وأرادوا الاعتماد على الخيل والسرعة. وأنا أتأمل: على ماذا أتكل؟\",\"p\":\"يا رب، أرجع إليك وأسكن في حضورك. علّمني أن قوتي في الهدوء والاتكال عليك، لا في السرعة والحلول البشرية. ورأف بي في انتظارك. آمين.\",\"x\":\"في الآية التالية يقول الله: «على خيل نهرب». أي أنهم اختاروا حلولًا بشرية سريعة. وهذا يحدث لنا حين نختار الانشغال بدل الصلاة. لكن الله لا يتخلى: «لذلك ينتظر الرب ليتراءف عليكم». فهو ينتظرنا بصبر. وهذا يعزينا. والرجوع هو التوبة، والسكون هو الثقة. وكلاهما يحتاجان إلى قرار واعٍ يتكرر كل يوم.\\nاختر أمرًا تتعجل فيه اليوم وتوقف عن التسرع فيه، وصل أولًا بهدوء ثم تصرف.\"},{\"t\":\"ما هي السكينة؟\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعرّف الأب روفو السكينة بأنها أن يقيم المرء بمعرفة الله وخوفه، مبتعدًا عن الإساءة والعجب، وتولد منها كل الفضائل. ليس السكون غياب الضجة بل حضور الله. ابحث اليوم عن مكان هادئ ولو قليلًا.\",\"p\":\"يا رب، علّمني السكينة التي بمعرفتك وخوفك. أبعد عني الإساءة والعجب، وأنبت فيّ فضائلك. آمين.\",\"x\":\"السكينة تعني ألا تنزعج الروح من الأحداث. تدريب: حافظ على هدوئك في ثلاثة مواقف اليوم.\",\"fq\":481}]},\"4-30\":{\"th\":\"أمانة الله\",\"m\":[{\"t\":\"كلام الرب كلام نقي\",\"ref\":\"المزمور الحادي عشر — باكر\",\"v\":\"كلام الرب كلام نقي، فضة محماة مجربة في الأرض، قد صفيت سبعة أضعاف. وأنت يا رب تنجينا وتحفظنا من هذا الجيل وإلى الدهر.\",\"r\":\"بعد زمن قلّ فيه الأمين، يشهد المرنم أن كلام الرب كلام نقي، فضة محماة مصفاة سبعة أضعاف. الله أمين في كلامه ووعده. وأنت يا رب تنجينا وتحفظنا. تأمل اليوم أي وعد من الله مرّت عليه تجربة ثم ثبت.\",\"p\":\"كلامك يا رب نقي كالفضة المصفاة سبع مرات، وأنت أمين. أنت تنجينا وتحفظنا من هذا الجيل وإلى الدهر. آمين.\",\"x\":\"كلام الرب نقي كفضة مصفاة، وبه نختم الشهر بأمانة الله. تدريب: اختر وعدًا من الكتاب وعلقه على حائطك.\"},{\"t\":\"الإله الأمين\",\"ref\":\"التثنية ٧: ٩\",\"bk\":\"التثنية\",\"v\":\"فاعلم أن الرب إلهك هو الله، الإله الأمين، الحافظ العهد والإحسان للذين يحبونه ويحفظون وصاياه إلى ألف جيل،\",\"r\":\"«فاعلم أن الرب إلهك هو الله، الإله الأمين الحافظ العهد والإحسان للذين يحبونه ويحفظون وصاياه إلى ألف جيل». الله يحفظ عهده عبر ألف جيل. وأنا ثمرة أمانته لأجدادي. وقد أكون أنا أيضًا سببًا في بركة لأجيال بعدي بأمانتي له.\",\"p\":\"يا رب، أنت الإله الأمين الحافظ العهد والإحسان. أشكرك على أمانتك عبر الأجيال، واجعلني حلقة أمينة في سلسلة الإيمان لمن بعدي. آمين.\",\"x\":\"المعرفة التي يطلبها موسى هنا ليست معلومات بل اختبار: «فاعلم». فبعد أن عاش الشعب العبور والبرية، عليهم أن يتذكروا أمانة الله. وذكر الأجيال يذكّرنا بأن إيماننا ميراث وأن أمانتنا تؤثر في من بعدنا. وفي الوقت نفسه يحذّر موسى: «ويجازي مبغضيه في وجوههم». فالله جاد في عهده. لكن الرحمة هي الأعلى.\\nاشكر الله اليوم على جيل أو أكثر قبلك حافظوا على الإيمان، وصلِّ لأجيال قادمة.\"},{\"t\":\"يدبّرني الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب فورتا: إذا أرادني الله أن أعيش هو يعرف تمامًا كيف يدبّرني، وإذا لم يرد ذلك فما حاجتي إلى هذه الحياة؟ كلمات أمانة وتسليم. اختم الشهر بهذا اليقين: الله الذي يدبّرني أمين.\",\"p\":\"يا رب، أنت أمين في تدبيرك لحياتي. أسلّم لك أيامي كلها، وأعرف أنك لن تتركني. آمين.\",\"x\":\"الله يدبر حياتي أفضل مما أفعل أنا. تدريب: سلّم له تدبير أمر واحد اليوم، وكف عن التفكير فيه.\",\"fq\":557}]},\"5-1\":{\"th\":\"كرامة العمل\",\"m\":[{\"t\":\"من قوة إلى قوة\",\"ref\":\"المزمور ٨٣ (٨٤) — السادسة\",\"v\":\"لأن البركات يعطيها واضع الناموس. يسيرون من قوة إلى قوة، يتجلى إله الآلهة في صهيون.\",\"r\":\"يرى المرنم الحياة مع الله سيرًا من قوة إلى قوة، وكل خطوة فيها بركة من واضع الناموس. العمل جزء من هذا الطريق وليس عائقًا له. اعمل اليوم أول مهمة بتركيز كامل كأنك تؤديها لله نفسه، وستجد أنها تصير صلاة.\",\"p\":\"يا رب، أعطني أن أسير في عملي من قوة إلى قوة. بارك جهدي، واجعل كرامة العمل تذكّرني أنك خلقتني للعمل معك. آمين.\",\"x\":\"يسير المؤمن في حياته مع الله من قوة إلى قوة، فكل خطوة تعطي قوة للخطوة التالية. العمل الذي نقوم به بأمانة يبني فينا القوة. تدريب: أنجز اليوم مهمة صغيرة مؤجلة بأمانة، وراقب كيف تعطيك طاقة.\"},{\"t\":\"من لا يعمل لا يأكل\",\"ref\":\"تسالونيكي الثانية ٣: ١٠–١٢\",\"bk\":\"تسالونيكي الثانية\",\"v\":\"فإننا أيضا حين كنا عندكم، أوصيناكم بهذا: «أنه إن كان أحد لا يريد أن يشتغل فلا يأكل أيضا». لأننا نسمع أن قوما يسلكون بينكم بلا ترتيب، لا يشتغلون شيئا بل هم فضوليون. فمثل هؤلاء نوصيهم ونعظهم بربنا يسوع المسيح أن يشتغلوا بهدوء، ويأكلوا خبز أنفسهم.\",\"r\":\"«إن كان أحد لا يريد أن يشتغل فلا يأكل أيضًا». عبارة حازمة موجهة للمتكاسلين المتطفلين على غيرهم. وبولس نفسه عمل بيديه ليكون قدوة. والعمل يحفظ كرامتي ويجعلني قادرًا على العطاء. وفيه انضباط يحميني من التسيب والثرثرة.\",\"p\":\"يا رب، أعطني نشاطًا وأمانة في عملي. احفظني من الكسل والتطفل، وعلّمني أن أعمل بهدوء وأكسب خبزي وأعطي من تعبي لمن يحتاج. آمين.\",\"x\":\"بولس لا يتحدث عن العاجز بل عن المتكاسل. وعلى الكنيسة أن ترحم الضعفاء وتحثّ القادرين. ثم يضيف: «ولا تملّوا من عمل الخير». فلا نيأس من الخدمة. وفي نهاية المقطع يوصي: «لا تحسبوه كعدو بل أنذروه كأخ». فالتصحيح يتم بمحبة. وعلينا أن نراجع أنفسنا: هل نؤدي مسؤولياتنا بأمانة أم نؤجلها؟\\nاكتب مهمة مؤجلة منذ زمن، وأنجزها اليوم أو حدد لها موعدًا قريبًا واضحًا.\"},{\"t\":\"لا تتخلَّ عن عمل اليد\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب بيستامون لأخ مؤمّنة حاجاته: مهما كان لديك لا تتخلَّ عن عمل اليد، اعمل ما في وسعك دونما اضطراب. العمل كرامة حتى عندما لا نحتاج إليه للمعيشة. اعمل اليوم بيديك شيئًا ملموسًا ولو صغيرًا.\",\"p\":\"يا رب، علّمني كرامة العمل وبهجة اليد التي تعمل. وأعطني أن أعمل بما في وسعي دون اضطراب. آمين.\",\"x\":\"العمل اليدوي حماية للنفس من الفراغ، فلا نتخلى عن عملنا بحجة العبادة. تدريب: اجعل عملك اليوم صلاة، وامنحه انتباهك الكامل.\",\"fq\":471}]},\"5-2\":{\"th\":\"طاعة الرعاة\",\"m\":[{\"t\":\"كانوا يدعون الرب فيستجيب\",\"ref\":\"المزمور ٩٨ (٩٩) — التاسعة\",\"v\":\"موسى وهرون بين كهنته وصموئيل بين الذين يدعون باسمه. كانوا يدعون الرب فيستجيب لهم، بعمود الغمام كان يكلمهم.\",\"r\":\"يذكر المرنم موسى وهرون وصموئيل، كهنة وأنبياء كان الله يكلمهم ويستجيب لهم. الرعاة ليسوا فوق الجماعة بل في خدمتها ويحملون صلاتها. صلِّ اليوم بالاسم من أجل راعيك أو أب اعترافك، واطلب له قوة وحكمة.\",\"p\":\"يا رب، احفظ رعاة كنيستك وأعطهم حكمة وقوة. استجب لهم كما استجبت لموسى وهرون وصموئيل، وعلّمنا أن نصلي من أجلهم ونطيعهم بمحبة. آمين.\",\"x\":\"موسى وهرون وصموئيل كانوا يدعون الرب فيستجيب، فالصلاة الأمينة لا تضيع. وهم رعاة بُنيت بهم جماعة. تدريب: صلِّ اليوم من أجل راعي كنيستك بالاسم.\"},{\"t\":\"اعرفوا الذين يتعبون\",\"ref\":\"تسالونيكي الأولى ٥: ١٢–١٣\",\"bk\":\"تسالونيكي الأولى\",\"v\":\"ثم نسألكم أيها الإخوة أن تعرفوا الذين يتعبون بينكم ويدبرونكم في الرب وينذرونكم، وأن تعتبروهم كثيرا جدا في المحبة من أجل عملهم. سالموا بعضكم بعضا.\",\"r\":\"«ثم نسألكم أيها الإخوة أن تعرفوا الذين يتعبون بينكم ويدبرونكم في الرب وينذرونكم». كلمة «يتعبون» تذكّرني بأن الخدمة تعب. وقد لا أرى ما وراء الكواليس. وكل خادم يحتاج أن أُعرّفه وأشجعه، وأن أعتبره «كثيرًا جدًا في المحبة».\",\"p\":\"يا رب، بارك الذين يتعبون في خدمتنا. علّمني أن أقدّرهم بالمحبة، وأن أشاركهم في رعاية إخوتي بالتشجيع والإسناد والصبر. آمين.\",\"x\":\"بولس يطلب «اعتبارهم» في المحبة، لا المبالغة في التمجيد. والتقدير يشمل الإنذار أيضًا، فمن يحبنا يصحح لنا. ثم يعطينا وصايا للجماعة: «أنذروا الذين بلا ترتيب، شجعوا صغار النفوس، أسندوا الضعفاء، تأنوا على الجميع». وهكذا تتكامل الأدوار. ولا يبقى الرعاة وحدهم، بل كل المؤمنين يشاركون في الرعاية.\\nاختر أحد هذه الوصايا الأربع التي تحتاجها جماعتك (إنذار، تشجيع، إسناد، تأنٍّ) وطبقها اليوم.\"},{\"t\":\"ألا نستعبد لرأينا\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سينكليتيكي إن علينا في الشركة أن نسوس أنفسنا بالتمييز، فلا نطلب ما هو لنا ولا نستعبد لرأينا. طاعة الرعاة حرية من أنانية الرأي. في قرار واحد اليوم، اسمع للمشورة قبل أن تتمسك برأيك.\",\"p\":\"يا رب، أعطني روح التمييز والطاعة. حرّرني من التمسك الأعمى برأيي، واجعلني أنصت إلى من وضعتهم رعاة لي. آمين.\",\"x\":\"لا نقلل من قيمة من يرعوننا، فالله يعمل بهم. تدريب: اشكر راعيك أو معلمك بكلمة اليوم.\",\"fq\":543}]},\"5-3\":{\"th\":\"فرح الخدمة\",\"m\":[{\"t\":\"يعودون بالفرح\",\"ref\":\"المزمور ١٢٥ (١٢٦) — الغروب\",\"v\":\"الذين يزرعون بالدموع يحصدون بالابتهاج. سيرا كانوا يسيرون وهم باكون حاملين بذارهم: ويعودون بالفرح حاملين أغمارهم هلليلويا.\",\"r\":\"صورة الزارع الباكي الذي يعود حاملًا أغماره بفرح هي صورة الخدمة: تعب البذار ثم فرح الحصاد. الخدمة بذار لا يرى ثمره دائمًا في يوم زرعه. اخدم اليوم في أمر صغير دون أن تنتظر نتيجة فورية، وثق في موسم الحصاد.\",\"p\":\"يا رب، الذين يزرعون بالدموع يحصدون بالابتهاج. قوّني في بذار الخدمة، وأعطني أن أعود بالفرح حاملًا أغمارًا لك. آمين.\",\"x\":\"الزارع الباكي يعود بفرح حاملًا أغماره، فالدموع في الخدمة بذار. تدريب: لا تيأس من تعب خدمة لم ترَ ثمرها بعد، وقل: سأعود بفرح.\"},{\"t\":\"طعامي أن أعمل مشيئة الذي أرسلني\",\"ref\":\"يوحنا ٤: ٣٤\",\"bk\":\"يوحنا\",\"v\":\"قال لهم يسوع: «طعامي أن أعمل مشيئة الذي أرسلني وأتمم عمله.\",\"r\":\"«طعامي أن أعمل مشيئة الذي أرسلني وأتمم عمله». كان المسيح متعبًا وجائعًا، لكنه شبع بلقاء السامرية. فالخدمة حين تتم بحسب مشيئة الآب تعطي شبعًا داخليًا. وأنا أحتاج أن أتعلم هذا: أن أجد الشبع في طاعة الله لا في إنجازاتي.\",\"p\":\"يا رب يسوع، علّمني أن يكون طعامي مشيئة الآب. أشبعني بطاعتك وخدمتك، وافتح عيني على الحقول المبيضة، واجعلني عاملًا فرحًا في حصادك. آمين.\",\"x\":\"التلاميذ عادوا بطعام مادي، فتفاجأوا بكلام المسيح. وقد يحدث لنا ذلك: نهتم بالمادة وننسى الروح. والمسيح بعد ذلك قال: «ارفعوا أعينكم وانظروا الحقول إنها قد ابيضّت للحصاد». أي أن هناك فرصة للخدمة أمامنا. والفرح بالحصاد مشترك بين الزارع والحاصد. فنحن جميعًا شركاء في العمل. وهذا يعطينا تواضعًا وفرحًا.\\nاسأل نفسك: هل أفرح بعمل مشيئة الله أم أشعر بها عبئًا؟ وقدّم له ذلك بصدق.\"},{\"t\":\"خدمة بفكر طاهر\",\"ref\":\"\",\"v\":\"\",\"r\":\"يصف الأب بيمن ثلاثة معًا: أحدهم يحيا السكينة، والثاني يمرض ويشكر، والثالث يخدم بفكر طاهر، والثلاثة يقومون بالعمل نفسه. فرح الخدمة أن أراها عملًا مقدسًا. اخدم اليوم بفكر نقي بعيدًا عن المقارنة.\",\"p\":\"يا رب، اجعل خدمتي بفكر طاهر وقلب فرح. علّمني أن أقدر عمل كل أخ، وأن أراك في كل خدمة. آمين.\",\"x\":\"الخدمة بفكر طاهر تحفظ الخادم من الفخار، فالدوافع تحدد قيمة العمل. تدريب: افحص دافعك قبل أن تخدم اليوم: لمن أخدم؟\",\"fq\":329}]},\"5-4\":{\"th\":\"طلب المشورة\",\"m\":[{\"t\":\"أظهر لي طرقك\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"أظهر لي يا رب طرقك؛ وعلمني سبلك. اهدني إلى عدلك وعلمني.\",\"r\":\"يطلب المرنم تعليمًا واهتداءً: أظهر لي طرقك، علّمني سبلك، اهدني إلى عدلك. وهو يعلم أن الطريق لا يُعرف بالتخمين. فلا تتردد في سؤال من هو أخبر منك، ولكن ابدأ بالسؤال الأول: ما مشيئتك يا رب في هذا الأمر؟\",\"p\":\"أظهر لي يا رب طرقك وعلّمني سبلك. اهدني إلى عدلك وعلّمني، وضع في طريقي من ينصحني بحكمة. آمين.\",\"x\":\"أظهر لي طرقك، علمني سبلك، اهدني: ثلاثة طلبات في آية واحدة. الله لا يمل من السؤال. تدريب: اسأل أحدًا خبيرًا عن أمر يشغلك قبل أن تقرر.\"},{\"t\":\"اسمع المشورة\",\"ref\":\"الأمثال ١٩: ٢٠\",\"bk\":\"الأمثال\",\"v\":\"اسمع المشورة واقبل التأديب، لكي تكون حكيما في آخرتك.\",\"r\":\"«اسمع المشورة واقبل التأديب لكي تكون حكيمًا في آخرتك». الحكمة تنمو بالاستماع. والتأديب جزء من تعليمي. وكثيرًا ما ننفر منه لأنه يؤلم الكبرياء، لكنه يحمي مستقبلنا. فالسماع الحكيم استثمار في المستقبل.\",\"p\":\"يا رب، علّمني أن أسمع المشورة وأقبل التأديب بتواضع. اجعلني أنمو في الحكمة كل يوم، وأشكر كل من أرشدني بمحبة. آمين.\",\"x\":\"من يقبل التأديب يتعلم أسرع. والمتكبر يكرر أخطاءه. وقد لا يكون التأديب من شخص كامل لكن الله يستخدمه. والتمييز بين نصيحة صالحة وطعنة يحتاج صلاة. لكن علينا أن نبدأ بحسن الظن. وفي آخر المطاف نشكر من أرشدنا. وكلمة «آخرتك» تذكّرنا بأن أعمالنا اليوم تؤثر في مستقبلنا الأبدي. فلنكن سامعين.\\nاطلب من شخص تثق به أن يعطيك ملاحظة صادقة عن جانب تحتاج أن تنمو فيه، وتقبلها بشكر.\"},{\"t\":\"أن أبني بيتي\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن تعليم الإنسان لقريبه من شأن الصُّم والعديمي الأهواء، وإلا فما قيمته إذا بنى بيت قريبه وهدم بيته؟ طلب المشورة يحميني من التسرع في إرشاد غيري قبل نفسي. اسأل اليوم من يكبرك خبرة عن أمر يهمّك.\",\"p\":\"يا رب، علّمني أن أبني بيتي أولًا وأطلب المشورة بتواضع. احفظني من التسرع في تعليم غيري قبل أن أتعلم. آمين.\",\"x\":\"من يبني بيته على المشورة يثبت، فلا نعتمد على فهمنا وحده. تدريب: اطلب اليوم رأي شخصين في قرار قريب.\",\"fq\":405}]},\"5-5\":{\"th\":\"الكنز الحقيقي\",\"m\":[{\"t\":\"ميراث لخائفي اسمك\",\"ref\":\"المزمور ٦٠ (٦١) — السادسة\",\"v\":\"أعطيت ميراثا لخائفي اسمك.\",\"r\":\"الكنز الحقيقي في كلمات المرنم عطية من الله لمن يخافونه: «أعطيت ميراثًا لخائفي اسمك». هذا ما لا يسرقه سارق ولا يفسده سوس. اسأل قلبك اليوم عن الكنز الذي تنشغل به أكثر: هل هو الباقي أم الزائل؟\",\"p\":\"أعطيتَ يا رب ميراثًا لخائفي اسمك. اجعل مخافتك كنزي الأعظم، وعلّمني أن أدخر في السماء ما لا يفنى. آمين.\",\"x\":\"الميراث الذي ينتظر خائفي الله لا يزول، فهو أعظم من الأرض. تدريب: اكتب ثلاثة كنوز لا تُسرق، وانظر كم من وقتك تخصصه لها.\"},{\"t\":\"اكنزوا لأنفسكم كنزًا\",\"ref\":\"لوقا ١٢: ٣٣\",\"bk\":\"لوقا\",\"v\":\"بيعوا ما لكم وأعطوا صدقة. اعملوا لكم أكياسا لا تفنى وكنزا لا ينفد في السماوات، حيث لا يقرب سارق ولا يبلي سوس،\",\"r\":\"«بيعوا ما لكم وأعطوا صدقة. اعملوا لكم أكياسًا لا تفنى وكنزًا لا ينفد في السماوات». المسيح يعلمني أن ما أعطيه يبقى، وما أحتفظ به يزول. والأكياس التي لا تبلى هي أعمال الرحمة. وهذه رؤية مختلفة للغنى: غنى العطاء.\",\"p\":\"يا رب، علّمني أن أكنز في السماء. حرر قلبي من التعلق بما يبلى، وأعطني أن أعطي بسخاء وفرح من واقع ثقتي بأنك تعطيني الملكوت. آمين.\",\"x\":\"الآية السابقة: «لا تخف أيها القطيع الصغير لأن أباكم قد سرّ أن يعطيكم الملكوت». فالدافع للعطاء هو الأمان. فمن عرف أن الله يعطيه الملكوت يعطي بسهولة. وقد لا يطلب الله من الجميع أن يبيعوا كل شيء، لكن يطلب قلبًا متحررًا. والعطاء يدرب القلب على الثقة. ومن ثمَّ نحصد فرحًا وسلامًا. والكنز في السماء يبقى لأنه في يد الله.\\nقدم اليوم عطاءً مدروسًا: مالًا أو وقتًا أو أشياء زائدة عن حاجتك، لمن يحتاجها.\"},{\"t\":\"فاكنز في السماء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب إيبريخيوس بأن كنز الراهب هو عدم القنية الطوعي، ويقول: فاكنز يا أخي في السماء لأن أزمنة الراحة لا تنتهي. الكنز الحقيقي يُدّخر بالتخلي لا بالجمع. ما الذي يمكنك أن تعطيه اليوم فتدخره عند الله؟\",\"p\":\"يا رب، أنا أريد كنزي عندك. حرّرني من التعلق بما يزول، وأعطني فرح من لا يملك شيئًا وهو يملك كل شيء بك. آمين.\",\"x\":\"الكنز في السماء لا تأكله الأرضة، فنعطي لنأخذ هناك. تدريب: اعطِ شيئًا عزيزًا اليوم لمن يحتاجه.\",\"fq\":553}]},\"5-6\":{\"th\":\"فقر الروح\",\"m\":[{\"t\":\"لأني ابن وحيد وفقير\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"انظر إلي وارحمني، لأني ابن وحيد وفقير أنا. أحزان قلبي قد كثرت، أخرجني من شدائدي.\",\"r\":\"يقدم المرنم نفسه إلى الله مسكينًا: فقيرًا وحيدًا كثرت أحزان قلبه. فقر الروح ليس ضعف الشخصية بل صدق الوقوف أمام الله بلا ادعاء. اجلس اليوم أمامه في صلاة قصيرة وقل: يا رب أنا فقير إليك.\",\"p\":\"انظر إليّ وارحمني يا رب لأني وحيد وفقير. أخرجني من شدائدي، واملأ فقري من غناك. آمين.\",\"x\":\"يقدم المرنم نفسه مسكينًا وحيدًا أمام الله، فالفقر الروحي بداية الملكوت. تدريب: قل لله اليوم: أنا فقير إليك في كل شيء.\"},{\"t\":\"يرفع المتواضع\",\"ref\":\"لوقا ١٨: ١٤\",\"bk\":\"لوقا\",\"v\":\"أقول لكم: إن هذا نزل إلى بيته مبررا دون ذاك، لأن كل من يرفع نفسه يتضع، ومن يضع نفسه يرتفع».\",\"r\":\"«كل من يرفع نفسه يتضع ومن يضع نفسه يرتفع». الفريسي صلّى بغرور فخرج غير مبرر، والعشار صلّى بانسحاق فخرج مبررًا. وهذا يعلمني أن شكل الصلاة لا يكفي، بل قلبها. والاتضاع يفتح باب النعمة.\",\"p\":\"يا رب، ارحمني أنا الخاطئ. احفظني من غرور الفريسي، وعلّمني اتضاع العشار، وأعطني أن أنزل لأرتفع بنعمتك. آمين.\",\"x\":\"مثل الفريسي والعشار موجه لـ«قوم واثقين بأنفسهم أنهم أبرار ويحتقرون الآخرين». وهذا الخطر قريب منّا، فكلنا قد نقارن أنفسنا بغيرنا ونشعر بالتفوق. والصلاة الحقيقية تبدأ بالنظر إلى الله لا إلى الآخرين. والعشار لم يرفع عينيه إلى السماء لكنه نال الغفران. فالقلب الصادق أقرب من لسان طويل.\\nاحذر اليوم من أي مقارنة تجعلك تشعر بالتفوق، وحوّلها إلى صلاة شكر على نعمة الله.\"},{\"t\":\"«هنيئًا للمساكين بالروح»\",\"ref\":\"\",\"v\":\"\",\"r\":\"يرى الأب يوحنا رجل القلالي أن الراهب يجب قبل كل شيء أن يكون متواضعًا، لأن هذه هي وصية السيد الأولى: هنيئًا للمساكين بالروح لأن لهم ملكوت السماوات. فقر الروح باب الملكوت. بأي أمر تحتاج أن تتواضع اليوم؟\",\"p\":\"يا رب، اجعلني مسكينًا بالروح لأرث ملكوتك. انزع الكبرياء من قلبي، وأعطني تواضع المحتاج إليك. آمين.\",\"x\":\"هنيئًا لمن يعرف نفسه مسكينًا، فهو يمتلئ. تدريب: اترك لنفسك دقيقة اعتراف بالاحتياج قبل أن تبدأ يومك.\",\"fq\":196}]},\"5-7\":{\"th\":\"تعزية الحزانى\",\"m\":[{\"t\":\"أعنتني وعزيتني\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"اصنع معي آية صالحة؛: ليرى ذلك مبغضي فيخزوا. لأنك أنت يا رب أعنتني وعزيتني.\",\"r\":\"يختم المرنم طلبه بشهادة: «أنت يا رب أعنتني وعزيتني». التعزية في الحزن ليست نسيانًا بل حضور. من يحزن يجد الله قريبًا، ومن يعزّي يشاركه في عمل الله. اتصل اليوم بشخص حزين وكن معه بلا كثرة كلام.\",\"p\":\"أنت يا رب أعنتني وعزيتني. اصنع معي آية صالحة، وعزِّ الحزانى الذين أعرفهم، وكن أنت سلامهم وتعزيتهم. آمين.\",\"x\":\"أنت أعنتني وعزيتني، شهادة المرنم بعد ضيق. التعزية تأتي في وقتها. تدريب: اذكر لحظة عزاك الله فيها، وشاركها لتعزي غيرك.\"},{\"t\":\"الحزن حسب مشيئة الله\",\"ref\":\"كورنثوس الثانية ٧: ١٠\",\"bk\":\"كورنثوس الثانية\",\"v\":\"لأن الحزن الذي بحسب مشيئة الله ينشئ توبة لخلاص بلا ندامة، وأما حزن العالم فينشئ موتا.\",\"r\":\"«لأن الحزن الذي بحسب مشيئة الله ينشئ توبة لخلاص بلا ندامة، وأما حزن العالم فينشئ موتًا». هناك حزن يكسرني وهناك حزن يرفعني. الأول يقودني إلى الله، والثاني إلى اليأس. وأنا أحتاج أن أفحص حزني: هل يدفعني إلى التوبة والأمل أم إلى الاستسلام؟\",\"p\":\"يا رب، حوّل حزني إلى توبة وخلاص. احفظني من حزن العالم الذي يميت، وأعطني الحزن الذي بحسب مشيئتك فيثمر حياة وفرحًا. آمين.\",\"x\":\"بولس شاهد في الكورنثيين ثمر الحزن الإلهي: اجتهاد وإجابة وغيرة وانتقام من الخطية. وهذا يدل على توبة حقيقية. أما حزن العالم فهو ندم على النتائج بلا توبة. ويمكننا تمييزهما: الأول يجذبني إلى الله والثاني يبعدني. وإن شعرت بحزن ثقيل، فلأسأل: هل يقودني إلى عمل خير وتوبة أم إلى انزواء؟ والله يحوّل حتى الحزن إلى بركة إذا سلمناه له.\\nاكتب مصدر حزنك الحالي واسأل: كيف أحوّل هذا الحزن إلى توبة أو عمل محبة؟\"},{\"t\":\"كن دون الجميع\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح الأب ماتوى أخًا طلب كلمة: اذهب وتضرع إلى الرب أن يجعل في قلبك الحزن والتواضع، وانتبه لخطاياك دائمًا ولا تدن أحدًا. هذا الحزن الصحي يقود إلى تعزية. لا تهرب اليوم من حزن يعلّمك التواضع.\",\"p\":\"يا رب، اجعل فيّ حزنًا بحسب مشيئتك يقودني إلى التوبة والتعزية. وكن أنت عزائي في كل حزن. آمين.\",\"x\":\"كن دون الجميع في نظر نفسك، فهذا يريحك من المقارنات. تدريب: افرح اليوم بنجاح أحد بلا مقارنة.\",\"fq\":276}]},\"5-8\":{\"th\":\"صانعو السلام\",\"m\":[{\"t\":\"الرحمة والحق تلاقيا\",\"ref\":\"المزمور ٨٤ (٨٥) — السادسة\",\"v\":\"الرحمة والحق تلاقيا، البر والسلام تلاثما. الحق من الأرض أشرق.\",\"r\":\"يصف المرنم لقاء ما لا يلتقي عادة: الرحمة مع الحق، والبر مع السلام. صانع السلام هو من يجمع الاثنين، فلا يتنازل عن الحق ولا يترك الرحمة. في خلاف يخصّك اليوم، فكّر كيف تجمع الصدق واللطف معًا.\",\"p\":\"يا رب، لتتلاقَ الرحمة والحق في قلبي، وليتعانق البر والسلام. اجعلني صانع سلام في بيتي وكنيستي وعملي. آمين.\",\"x\":\"الرحمة والحق تلاقيا والبر والسلام تعانقا، وهذا اللقاء يتم في الصليب. تدريب: ابحث اليوم عن حل وسط يجمع بين الحق والمحبة في خلاف.\"},{\"t\":\"ثمر البر يُزرع في السلام\",\"ref\":\"يعقوب ٣: ١٧–١٨\",\"bk\":\"يعقوب\",\"v\":\"وأما الحكمة التي من فوق فهي أولا طاهرة، ثم مسالمة، مترفقة، مذعنة، مملوة رحمة وأثمارا صالحة، عديمة الريب والرياء. وثمر البر يزرع في السلام من الذين يفعلون السلام.\",\"r\":\"«أما الحكمة التي من فوق فهي أولًا طاهرة ثم مسالمة مترفقة مذعنة مملوءة رحمة وأثمارًا صالحة». هذه قائمة صفات الحكمة السماوية، وأولها الطهارة. فلا سلام حقيقي بدون نقاء. وعندما أعيش بهذه الصفات، ثمر البر ينمو في بيئتي.\",\"p\":\"يا رب، أعطني الحكمة التي من فوق: طاهرة مسالمة مترفقة مملوءة رحمة. ازرع في حياتي وبيتي ثمر البر بالسلام الذي تصنعه بنا. آمين.\",\"x\":\"الصفات المذكورة تشمل الرفق والاستعداد للإذعان بمعنى عدم التعنت. وهذا عكس الحكمة الأرضية التي فيها غيرة ومنافسة. والنتيجة: «ثمر البر في السلام يزرع للذين يصنعون السلام». فالبر ثمرة سلام. والمجتمعات التي تعيش بالعنف لا تنمو. أما المجتمعات المسالمة فتثمر. وهذا ينطبق على بيوتنا وكنائسنا. فلنحرص على أن نكون زراع سلام.\\nاختر صفة واحدة من الصفات (مترفقة، مذعنة، رحيمة) وطبقها عمليًا اليوم في موقف حقيقي.\"},{\"t\":\"أظهر توبتك أمام أخيك\",\"ref\":\"\",\"v\":\"\",\"r\":\"عندما سأل أحدهم الأب بيمن عمن حزن بسببه، أرشده أن يأخذ معه اثنين ثم خمسة ثم كاهنًا ليُظهر توبته، فإذا لم يقتنع صلّى إلى الله بلا انزعاج. صنع السلام يتطلب تواضعًا وسعيًا. من لك عنده شيء؟ ابدأ بالسعي.\",\"p\":\"يا رب، اجعلني أسعى إلى المصالحة بتواضع وصبر. وإن لم يقتنع الآخر، علّمني أن أصلي وأتركه لك بلا همّ. آمين.\",\"x\":\"إظهار التوبة أمام الآخرين تحرير من الكبرياء. تدريب: اعتذر علانية عن خطأ صغير اليوم.\",\"fq\":429}]},\"5-9\":{\"th\":\"الاضطهاد من أجل البر\",\"m\":[{\"t\":\"لم يقدروا عليّ\",\"ref\":\"المزمور ١٢٨ (١٢٩) — الغروب\",\"v\":\"مرارا كثيرة حاربوني منذ صباي - ليقل إسرائيل مرارا كثيرة قاتلوني منذ شبابي، وإنهم لم يقدروا علي. على ظهري جلدني الخطاة وأطالوا إثمهم.\",\"r\":\"يتذكر المرنم محاربة الأعداء منذ الصبا وجلدهم ظهره، ومع ذلك يعلن: لم يقدروا عليّ. الاضطهاد من أجل البر يجرح لكنه لا يهزم. إن عانيت اليوم من سخرية أو ضغط بسبب إيمانك، فتذكّر أن الله لا ينسى وأن ثباتك شهادة.\",\"p\":\"مرارًا كثيرة حاربوني منذ صباي، لكنهم لم يقدروا عليّ لأنك معي. قوّني في الاضطهاد، واحفظ فرحي وسلامي. آمين.\",\"x\":\"حاربني أعدائي منذ صباي ولم يقدروا علي، شهادة بثبات الله مع شعبه. تدريب: اذكر حربًا خرجت منها سالمًا، وسبح الله عليها.\"},{\"t\":\"إن تألمتم من أجل البر\",\"ref\":\"بطرس الأولى ٣: ١٤\",\"bk\":\"بطرس الأولى\",\"v\":\"ولكن وإن تألمتم من أجل البر، فطوباكم. وأما خوفهم فلا تخافوه ولا تضطربوا،\",\"r\":\"«ولكن وإن تألمتم من أجل البر فطوباكم، وأما خوفهم فلا تخافوه ولا تضطربوا». الخوف هو أول سلاح المضطهد. وبطرس يقول: لا تخف من خوفهم. فالثبات يبدأ بالقلب. ثم يوصي: «قدسوا الرب الإله في قلوبكم». أي اجعلوا الله هو الأول.\",\"p\":\"يا رب، قدّسك في قلبي. اجعلني مستعدًا أن أجاوب عن رجائي بوداعة وخوف، وأثبت بضمير صالح، ولا أخاف من خوف أحد. آمين.\",\"x\":\"بعد هذه الآية يقول بطرس: «كونوا مستعدين دائمًا لمجاوبة كل من يسألكم عن سبب الرجاء الذي فيكم بوداعة وخوف». فالدفاع يكون بوداعة لا بعنف. ويضيف: «ولكم ضمير صالح». فالسلوك الحسن يخزي المفترين. وقد نتألم لفعل الخير أفضل من أن نتألم لفعل الشر. وبهذا نشبه المسيح. وكل ظلم نتحمله بصبر يصير شهادة.\\nحضّر جملة قصيرة بسيطة تعبر عن سبب رجائك بالمسيح، لتكون جاهزًا لأي سؤال بوداعة.\"},{\"t\":\"الشتم يروي الشجرة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أشعيا إنه لا شيء ينفع المبتدئ كالشتم والإهانة، فكما أن الشجرة ترتوي كل يوم هكذا المبتدئ الذي يُشتم فيحتمل. الاضطهاد قد يصير ماءً يرويني. كيف تقابل إهانة اليوم؟ جرّب الاحتمال بسلام.\",\"p\":\"يا رب، علّمني أن أحتمل الإهانة بفرح كمن يشرب ماءً يرويه. ولا تدعني أرد الشر بشر. آمين.\",\"x\":\"الشتم يروي النفس المتواضعة كالماء، فمن يتقبله ينمو. تدريب: تقبل نقدًا اليوم بلا دفاع، واشكر الشخص.\",\"fq\":120}]},\"5-10\":{\"th\":\"ملح الأرض\",\"m\":[{\"t\":\"أنتم ملح الأرض\",\"ref\":\"إنجيل السادسة\",\"v\":\"أنتم ملح الأرض، فإذا فسد الملح فبماذا يملح؟ ... أنتم نور العالم. ... هكذا فليضئ نوركم قدام الناس لكي يروا أعمالكم الصالحة فيمجدوا أباكم الذي في السموات.\",\"r\":\"الملح لا يُرى لكنه يعطي الطعم، ولا يظهر في الوجبة لكن غيابه يُلاحَظ فورًا. هذا هو تأثير المؤمن في بيته وعمله. لا يحتاج أن يتكلم كثيرًا، بل أن يحافظ على طعمه. ما الذي يعطي حياتك طعم المسيح اليوم؟\",\"p\":\"يا رب، اجعلني ملحًا يحفظ ولا يفسد، ونورًا يضيء لمن حولي. ليرى الناس أعمالي الصالحة فيمجدوك أبانا الذي في السماوات. آمين.\",\"x\":\"الملح يعطي الطعم ولا يظهر، وغيابه يُلاحظ. هكذا المؤمن في عمله. تدريب: كن اليوم سببًا في حسن مزاج مكان عملك بلا فرض.\"},{\"t\":\"كلامكم كل حين بنعمة\",\"ref\":\"كولوسي ٤: ٦\",\"bk\":\"كولوسي\",\"v\":\"ليكن كلامكم كل حين بنعمة، مصلحا بملح، لتعلموا كيف يجب أن تجاوبوا كل واحد.\",\"r\":\"«ليكن كلامكم كل حين بنعمة مصلحًا بملح لتعلموا كيف يجب أن تجاوبوا كل واحد». كلام النعمة لطيف ومملوء بالقبول. والملح هو الحكمة التي تحفظ من الفساد. فأتعلم أن أتكلم بلطف دون مجاملة كاذبة، وبصدق دون جرح.\",\"p\":\"يا رب، ليكن كلامي كل حين بنعمة مصلحًا بملح. علّمني متى أتكلم ومتى أصمت، وكيف أجاوب كل واحد بحكمة ولطف وصدق. آمين.\",\"x\":\"قد ننقسم بين اللطف الفارغ والصراحة القاسية. لكن بولس يجمع الاثنين: نعمة وملح. وذلك يحتاج انتباهًا لحال كل شخص: «كيف يجب أن تجاوبوا كل واحد». فلا توجد وصفة واحدة. وهذا يتطلب صلاة قبل الكلام. وقد يكون الصمت أحيانًا هو الجواب المناسب. وقبل هذه الآية يوصي بالسلوك بحكمة. فالكلام جزء من الشهادة.\\nقبل أن ترد على رسالة أو شخص اليوم، خذ نفسًا وصلِّ: «يا رب كلمة بنعمة وملح»، ثم أجب.\"},{\"t\":\"الملح والمحبة بلا رياء\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينبه الأب أور ألا نقول في قلوبنا نحو أخينا: أنا أكثر نسكًا منه، بل نطيع نعمة المسيح بروح الفقر والمحبة التي لا رياء فيها. الملح الذي يحفظ هو الاتضاع الصادق. اختبر اليوم نيتك قبل كل عمل مفيد.\",\"p\":\"يا رب، احفظ فيّ ملح التواضع. لا تدعني أفتخر بنسكي، بل أطع نعمتك بمحبة بلا رياء. آمين.\",\"x\":\"الملح والمحبة بلا رياء، فلا نظهر ما لا نعيشه. تدريب: أعطِ دون أن تذكر ذلك.\",\"fq\":564}]},\"5-11\":{\"th\":\"كمال المحبة\",\"m\":[{\"t\":\"رحمة ونقاء وسلام\",\"ref\":\"إنجيل السادسة\",\"v\":\"طوبى للرحماء لأنهم يرحمون. طوبى لأنقياء القلب لأنهم يعاينون الله. طوبى لصانعي السلام، لأنهم يدعون أبناء الله.\",\"r\":\"يضع الرب أمامنا ثلاث علامات للمحبة الكاملة: رحمة تعطي، وقلب نقي يرى الله، وسلام يصالح. كمال المحبة أن تتكامل هذه الثلاث فيّ. أي واحدة منها أحتاج أن أنمّيها اليوم؟ اختر واحدة وصلِّ لأجل نموها.\",\"p\":\"يا رب، اجعلني رحيمًا ونقي القلب وصانع سلام. وأتمم فيّ محبتك الكاملة لأكون ابنًا لك في كل شيء. آمين.\",\"x\":\"رحمة تعطي وقلب نقي وسلام يصنع: ثلاث علامات للمحبة الكاملة. تدريب: اختر علامة منها وركز عليها اليوم.\"},{\"t\":\"كونوا كاملين\",\"ref\":\"متى ٥: ٤٨\",\"bk\":\"متى\",\"v\":\"فكونوا أنتم كاملين كما أن أباكم الذي في السماوات هو كامل.\",\"r\":\"«فكونوا أنتم كاملين كما أن أباكم الذي في السماوات هو كامل». الكمال هنا في سياق المحبة: أن أحب الجميع كما يحب الله، فهو يشرق شمسه على الأشرار والصالحين. وليس مطلوبًا ألا أخطئ أبدًا، بل أن أنمو باستمرار في هذه المحبة.\",\"p\":\"أبانا السماوي، أنت كامل في محبتك. علّمني أن أنمو في الكمال بنعمتك، وأحب كما تحب، وأسامح كما تسامح، حتى أشبهك. آمين.\",\"x\":\"الكمال في الكتاب يعني النضج والاكتمال. وهو رحلة طويلة نخطوها بنعمة الله. ولا ننتظر الوصول لنبدأ، بل نتحرك. ومقياسه محبة الأعداء. فالآباء كانوا يقولون إن درجة المحبة هي مقياس النمو الروحي. وقد يرهقنا طموح الكمال إن نظرنا لأنفسنا، لكن إن نظرنا إلى الآب فنحن نتغير. وكل خطوة صغيرة تقرّبنا.\\nاختر موقفًا اليوم تتعامل فيه بمحبة مع شخص صعب، وطبق «الكمال» في هذا الموقف فقط.\"},{\"t\":\"المحبة الكاملة\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال القديس أغاثون: «لو كان ممكنًا أن أجد أبرص أعطيه جسدي وآخذ جسده لكنت سعيدًا، لأن هذه هي المحبة الكاملة». عبارة تهز القلب: المحبة التي تقبل أن تحمل ثقل الآخر. ما الثقل الذي يمكنك أن تحمله عن أحد اليوم؟\",\"p\":\"يا رب، اجعل محبتي كاملة تقبل أن تتحمل عن الآخر. علّمني أن أحب كما أحببتني، حتى الصليب. آمين.\",\"x\":\"المحبة الكاملة لا تعرف التمييز بين الناس. تدريب: عامل اليوم شخصًا لا تحبه بنفس لطفك مع من تحبه.\",\"fq\":58}]},\"5-12\":{\"th\":\"نعم نعم لا لا\",\"m\":[{\"t\":\"نجِّ نفسي من اللسان الغاش\",\"ref\":\"المزمور ١١٩ (١٢٠) — الغروب\",\"v\":\"يا رب نج نفسي من الشفاه الظالمة ومن اللسان الغاش. ماذا تعطى وماذا تزاد من اللسان الغاش.\",\"r\":\"يصلي المرنم أن ينجيه الله من الشفاه الظالمة ومن اللسان الغاش، ويسأل ماذا ينتفع صاحبه منه. الصدق في القول يبدأ من طلب النجاة من غش الكلمة. قبل أن تعد بشيء اليوم، تأكد أنك ستفي، وإلا فقل بصراحة: لا.\",\"p\":\"يا رب، نجِّ نفسي من الشفاه الظالمة ومن اللسان الغاش. علّمني أن يكون كلامي نعم نعم ولا لا، وأن أفي بوعودي. آمين.\",\"x\":\"يطلب المرنم النجاة من اللسان الغاش، فالكلمة سلاح ذو حدين. تدريب: قل اليوم نعم حين تعني نعم، ولا حين تعني لا.\"},{\"t\":\"ليكن كلامكم نعم نعم\",\"ref\":\"متى ٥: ٣٧\",\"bk\":\"متى\",\"v\":\"بل ليكن كلامكم: نعم نعم، لا لا. وما زاد على ذلك فهو من الشرير.\",\"r\":\"«ليكن كلامكم نعم نعم لا لا، وما زاد على ذلك فهو من الشرير». يريد المسيح لسانًا موثوقًا: إذا قلت نعم فهي نعم، وإذا قلت لا فهي لا. فلا أحتاج إلى حلف أو إقناع. والمصداقية تُبنى بالأمانة اليومية في الصغائر.\",\"p\":\"يا رب، اجعل كلامي صادقًا موثوقًا. علّمني ألا أعد بما لا أقدر، وأن أحفظ كلمتي في الصغير والكبير، ولتكن نعم نعم ولا لا. آمين.\",\"x\":\"الحلف كان وسيلة لإثبات الصدق، لكنه يعني ضمنيًا أن غير الحلف قد لا يكون صادقًا. والمسيح يدعو إلى حياة شفافة. وهذا يتطلب تفكيرًا قبل الوعد: لا أقول نعم لأرضي، ولا أقول لا لأتهرب. وهذا يشمل الالتزامات الصغيرة: مواعيد ووعود. فمن يحفظ كلمته في الصغير يُؤتمن في الكبير. وكلامنا مرآة لقلبنا.\\nراجع وعدًا صغيرًا قلته مؤخرًا ولم تنفذه، وبادر بتنفيذه أو الاعتذار بصدق.\"},{\"t\":\"باب اللسان\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل أخ الأب بيمن عن خوفه ألا يفتح له الباب، فقال: نحن لا نعرف أن نغلق الباب الخشبي لكن باب اللسان. لا نتعب في حفظ أبواب البيت وننسى فمنا. ما الكلمة التي تحتاج أن تغلق بابها اليوم؟\",\"p\":\"يا رب، أغلق باب لساني عن كل كلمة لا تنفع. وأعطني حكمة أن أتكلم بالحق وفي وقته. آمين.\",\"x\":\"باب اللسان يحتاج إلى حارس، فمن يملكه يملك نفسه. تدريب: عدّ اليوم كم مرة تكلمت بلا فائدة.\",\"fq\":356}]},\"5-13\":{\"th\":\"لا تقلقوا\",\"m\":[{\"t\":\"يعطي فراخ الغربان طعامها\",\"ref\":\"المزمور ١٤٦ — النوم\",\"v\":\"الذي يجلل السماء بالغمام، الذي يهيئ للأرض المطر، الذي ينبت العشب على الجبال والخضرة لخدمة البشر، ويعطي البهائم طعامها، ولفراخ الغربان التي تدعوه.\",\"r\":\"يذكّرنا المرنم بإله يدبر المطر والعشب وطعام فراخ الغربان. من يعتني بكل هذا لا ينسى أبناءه. لهذا قال الرب: لا تقلقوا. اكتب اليوم ثلاثة أشياء تقلق منها وضعها أمام الله، ثم اعمل ما عليك واترك الباقي.\",\"p\":\"أيها الرب الذي يعطي البهائم طعامها ولفراخ الغربان التي تدعوه، اعتن بي. خذ قلقي وأعطني ثقة بتدبيرك. آمين.\",\"x\":\"الله يعطي فراخ الغربان طعامها، فكم بالأحرى يعتني بنا. تدريب: اترك اليوم هماً ماديًا لله، وقل: أنت تدبّر.\"},{\"t\":\"لا تهتموا للغد\",\"ref\":\"متى ٦: ٣٤\",\"bk\":\"متى\",\"v\":\"فلا تهتموا للغد، لأن الغد يهتم بما لنفسه. يكفي اليوم شره.\",\"r\":\"«فلا تهتموا للغد لأن الغد يهتم بما لنفسه. يكفي اليوم شره». لا أحمل غدًا بجانب اليوم، فهو حمل زائد. والله يعطيني نعمة لليوم، وسيعطيني نعمة للغد حين يأتي. وهذا يحررني من الاحتراق بالتفكير في ما لم يحدث.\",\"p\":\"يا رب، أعطني نعمة اليوم. حرّرني من حمل الغد قبل أوانه، وعلّمني أن أعيش لحظتي بأمانة، وأثق بك في كل ما هو آتٍ. آمين.\",\"x\":\"القلق من الغد يسرق فرح اليوم. وغالبًا ما تكون مخاوفنا بعيدة عن الواقع. والمسيح لا يقول إن اليوم بلا مشاكل: «يكفي اليوم شره». لكنه يقول إن لكل يوم نعمته. وهذا ما نطلبه في الصلاة الربانية: «خبزنا كفافنا أعطنا اليوم». نعيش بالاعتماد اليومي. وهذا يجعلنا أكثر قربًا من الله. والتخطيط ممكن، لكن بلا قلق.\\nعندما تأتيك فكرة مخيفة عن الغد، قل: «هذا للغد»، وارجع بهدوء إلى مهمة اليوم.\"},{\"t\":\"إذا قام الإنسان بواجباته\",\"ref\":\"\",\"v\":\"\",\"r\":\"عبارة الأب بيمن قصيرة وحاسمة: «إذا قام الإنسان بواجباته لا يضطرب». القلق كثيرًا ما يأتي من تأجيل ما علينا، والسلام يأتي مع الأمانة في الواجب. ما الواجب الذي تؤجله وهو سبب جزء من قلقك؟ ابدأ به اليوم.\",\"p\":\"يا رب، أعطني أن أقوم بواجباتي بأمانة فأرتاح من القلق. وليكن اهتمامي الأول ملكوتك وبرك. آمين.\",\"x\":\"إذا قام الإنسان بواجبه سلّم الباقي لله. تدريب: افعل ما عليك ثم اترك النتيجة.\",\"fq\":438}]},\"5-14\":{\"th\":\"لا تدينوا\",\"m\":[{\"t\":\"ليس رحمة في الدينونة\",\"ref\":\"قطعة الخدمة الثالثة (٢) — نصف الليل — الخدمة الثالثة\",\"v\":\"بما أن الديان حاضر، اهتمي يا نفسي وتيقظي وتفهمي تلك الساعة المخوفة. فإنه ليس رحمة في الدينونة لمن لم يستعمل الرحمة. فلهذا أشفق علي أيها المخلص.\",\"r\":\"تذكّرنا الكنيسة بالديان الحاضر وبقاعدة الرحمة: الدينونة بلا رحمة لمن لم يستعمل الرحمة. حين أدين غيري أحكم على نفسي بالمعيار نفسه. اترك اليوم حكمًا كنت ستصدره على أحد، واستبدله بطلب رحمة لك وله.\",\"p\":\"بما أن الديان حاضر، اهتمي يا نفسي وتيقظي. فلهذا أشفق عليّ أيها المخلص، فإنك محب البشر وحدك. آمين.\",\"x\":\"لا رحمة في الدينونة لمن لم يعمل رحمة، فالرحمة تُقابل بالرحمة. تدريب: لا تحكم على أحد اليوم، بل اسأل: لماذا يتصرف هكذا؟\"},{\"t\":\"لماذا تدين أخاك\",\"ref\":\"رومية ١٤: ١٠\",\"bk\":\"رومية\",\"v\":\"وأما أنت، فلماذا تدين أخاك؟ أو أنت أيضا، لماذا تزدري بأخيك؟ لأننا جميعا سوف نقف أمام كرسي المسيح،\",\"r\":\"«وأما أنت فلماذا تدين أخاك؟ أو أنت أيضًا لماذا تزدري بأخيك؟ لأننا جميعًا سوف نقف أمام كرسي المسيح». الحكم ليس لي، فسأقف أنا أيضًا أمام المسيح. وهذا يضعني في مكاني الصحيح: مخلوق يحتاج رحمة. وتحويل نظري من الآخر إلى نفسي هو بداية الحكمة.\",\"p\":\"يا رب، ذكّرني أني سأقف أمام كرسيك. احفظني من الدينونة والازدراء، وعلّمني أن أسعى لما يبني أخي ولا أضع له عثرة. آمين.\",\"x\":\"بولس ينبه أن الدينونة والازدراء يهدمان الجماعة. ويدعونا بعد ذلك: «فلا نحاكم أيضًا بعضنا بعضًا بل بالحري احكموا بهذا: أن لا يوضع للأخ مصدمة أو معثرة». أي أن نكون سببًا في البنيان لا العثرة. وعندما نتذكر أننا سنقف أمام الله نتواضع. وحسابنا يخص أنفسنا. وهذا يعطي حرية من أحكام الآخرين وأحكامنا عليهم.\\nفكّر في آخر مرة حكمت فيها على أحد، وقدّم هذا الحكم لله وقل: «أنت تعلم يا رب».\"},{\"t\":\"من أنا؟\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب يوسف الذي في بنفو أخًا يطلب الراحة: إذا أردت أن تجد راحة هنا وهناك، قل في كل شيء: «من أنا؟» ولا تدن أحدًا. هذا السؤال يوقف الدينونة. جرّبه اليوم قبل أن تحكم على أحد.\",\"p\":\"يا رب، علّمني أن أسأل نفسي: من أنا؟ وأن أتوقف عن الدينونة. ارحمني ولا تدنّي كما أدين غيري. آمين.\",\"x\":\"من أنا حتى أدين أخي، وأنا غارق في خطاياي؟ تدريب: أمسك لسانك عن النقد اليوم.\",\"fq\":182}]},\"5-15\":{\"th\":\"الباب الضيق\",\"m\":[{\"t\":\"ارفعوا أيها الرؤساء أبوابكم\",\"ref\":\"المزمور ٢٣ (٢٤) — الثالثة\",\"v\":\"ارفعوا أيها الرؤساء أبواكم، وارتفعي أيتها الأبواب الدهرية، فيدخل ملك المجد. من هو هذا ملك المجد؟\",\"r\":\"الأبواب الدهرية تُرفع ليدخل ملك المجد. الباب الضيق ليس ضيقًا على المسيح، بل على من يحمل أمتعة كثيرة. وهو الذي قال: أنا هو الباب. أين الأبواب المغلقة في قلبك؟ افتح اليوم بابًا واحدًا لمن يطرقه.\",\"p\":\"يا رب، ارفع أبواب قلبي الدهرية، فيدخل ملك المجد. اجعلني أدخل من بابك الضيق، وتحمل عني ما يعطلني. آمين.\",\"x\":\"ترفع الأبواب الدهرية ليدخل ملك المجد، والباب الضيق هو الذي يدخل منه. تدريب: اترك اليوم شيئًا ثقيلًا لا يمر من الباب الضيق، مثل كبرياء أو عادة.\"},{\"t\":\"أنا هو الباب\",\"ref\":\"يوحنا ١٠: ٩\",\"bk\":\"يوحنا\",\"v\":\"أنا هو الباب. إن دخل بي أحد فيخلص ويدخل ويخرج ويجد مرعى.\",\"r\":\"«أنا هو الباب. إن دخل بي أحد فيخلص ويدخل ويخرج ويجد مرعى». الباب الضيق هو المسيح نفسه. فلا أدخل بمجهودي بل به. وهو يعدني بالخلاص والحرية والغذاء. فالباب ليس سجنًا بل مدخل لحياة غنية: أدخل وأخرج وأجد مرعى.\",\"p\":\"يا رب يسوع، أنت الباب. أدخلني بك إلى الخلاص والحرية والمرعى، واحمني من كل ذئب، وأعطني حياة وفيرة في شركتك. آمين.\",\"x\":\"الباب في الحظيرة يحمي الخراف من الذئاب ويسمح لها بالدخول والخروج للرعي. وكذلك المسيح: يحمينا ويقودنا إلى مرعى. وهذه الحرية الآمنة مختلفة عن حرية مطلقة بلا حماية. وهو يقول بعدها: «أنا أتيت لتكون لهم حياة وليكون لهم أفضل». فهدفه حياة وفيرة. وفي هذا الباب كل من يأتي يجد قبولًا.\\nادخل اليوم «من الباب» بصلاة بسيطة: «يا يسوع أنت بابي»، ودع حياتك تمر تحت حمايته.\"},{\"t\":\"الطريق الضيقة\",\"ref\":\"\",\"v\":\"\",\"r\":\"سُئل القديس أمون عن الطريق الضيقة المحزنة فقال إنها أن يمسك الإنسان أفكاره ويقطع مشيئته حبًا بالله. الضيق في القرارات الصغيرة التي أتخلى فيها عن رغبتي. ما الرغبة التي تقطعها اليوم من أجل المسيح؟\",\"p\":\"يا رب، علّمني أن أمسك أفكاري وأقطع مشيئتي حبًا بك. أدخلني من الباب الضيق إلى حياتك. آمين.\",\"x\":\"الطريق الضيق يؤدي إلى الحياة، فلا نبحث عن الأسهل. تدريب: اختر الأصعب في أمر صغير اليوم لله.\",\"fq\":64}]},\"5-16\":{\"th\":\"الابتعاد عن محبة العالم\",\"m\":[{\"t\":\"ويل لي فإن غربتي طالت\",\"ref\":\"المزمور ١١٩ (١٢٠) — الغروب\",\"v\":\"ويل لي فإن غربتي قد طالت علي، وسكنت في مساكن قيدار. طويلا سكنت نفسي في الغربة: ومع مبغضي السلام كنت صاحب سلام، وحين كنت أكلمهم كانوا يقاتلونني باطلا هلليلويا.\",\"r\":\"يصف المرنم نفسه غريبًا يسكن مع من يكرهون السلام، وهو كلما كلمهم قاتلوه. من يحب الله يشعر في هذا العالم بالغربة بقدر ما يتعلق قلبه بالسماء. اسأل اليوم: هل أنا ضيف في هذا العالم أم ساكن؟\",\"p\":\"يا رب، غربتي قد طالت، فاجعل قلبي متعلقًا بوطنك. علّمني أن أكون صاحب سلام وسط من لا يحبون السلام. آمين.\",\"x\":\"يشعر المرنم بالغربة بين من يكرهون السلام. فالمؤمن غريب في العالم ومواطن في السماء. تدريب: اطلب اليوم السلام في مكان يسوده التوتر.\"},{\"t\":\"اهتمام الروح حياة وسلام\",\"ref\":\"رومية ٨: ٥–٦\",\"bk\":\"رومية\",\"v\":\"فإن الذين هم حسب الجسد فبما للجسد يهتمون، ولكن الذين حسب الروح فبما للروح. لأن اهتمام الجسد هو موت، ولكن اهتمام الروح هو حياة وسلام.\",\"r\":\"«لأن اهتمام الجسد هو موت ولكن اهتمام الروح هو حياة وسلام». الفكر الذي أغذّيه يقودني. إن غذّيت الفكر بما للجسد والعالم وجدت قلقًا وفراغًا. وإن غذّيته بما للروح وجدت سلامًا وحياة. فأنا أختار كل يوم بماذا أهتم.\",\"p\":\"يا رب، علّمني أن أهتم بما للروح. نقِّ فكري وغذّه بكلمتك وحضورك، وأعطني حياة وسلامًا من روحك الساكن فيّ. آمين.\",\"x\":\"الاهتمام هنا يعني التركيز والتوجه. وكل واحد يتجه بشيء. والاتجاه يصنع المسار. وبولس يربط هذا بحضور الروح: «وأما أنتم فلستم في الجسد بل في الروح إن كان روح الله ساكنًا فيكم». فالقدرة على الاهتمام بما للروح ليست مجهودنا وحدنا بل عطية. ولذلك نطلب الروح القدس باستمرار. ومن عادات الاهتمام بالروح: قراءة الكتاب والصلاة وصحبة الصالحين.\\nاستبدل اليوم عادة واحدة تغذّي الجسد فقط بعادة تغذّي الروح (مثل ترنيمة أو آية بدل تصفح طويل).\"},{\"t\":\"المال واللذة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس: «يستحيل عليك أن تعيش وفقًا لإرادة الله إذا كنت محبًا للمال واللذة». محبة العالم تزاحم محبة الله. ما الذي في العالم يشغل قلبك أكثر من اللازم؟ سمِّه، وخفّف تعلقك به اليوم.\",\"p\":\"يا رب، حرّر قلبي من محبة المال واللذة. اجعل محبتك تملأ كياني فلا يبقى مكان لغيرك. آمين.\",\"x\":\"الابتعاد عن محبة العالم يبدأ بنزع التعلق. تدريب: تخل عن شيء تحبه لأجل الله لساعات.\",\"fq\":199}]},\"5-17\":{\"th\":\"الصلاة معًا\",\"m\":[{\"t\":\"أنصت يا رب إلى صلاتي\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"أنصت يا رب إلي صلاتي. وأصغ إلى صوت تضرعي. في يوم شدتي إليك صرخت فأجبتني.\",\"r\":\"يطلب المرنم أن ينصت الرب لصلاته ويصغي لتضرعه، ويشهد أنه في يوم شدته صرخ فأجابه. الصلاة معًا تضاعف هذه الثقة، فنصلّي ونحن نعلم أن الجماعة تحمل ضعفنا. اطلب اليوم من أحد أن يصلي معك لأجل أمر واحد.\",\"p\":\"أنصت يا رب إلى صلاتنا، وأصغِ إلى صوت تضرعنا. في يوم شدتنا إليك نصرخ فتجيبنا. اجمعنا في الصلاة وكن في وسطنا. آمين.\",\"x\":\"يطلب المرنم الإنصات إلى صلاته، فالصلاة المشتركة ترفع القلوب. تدريب: صلّ مع شخص آخر اليوم ولو بعبارة قصيرة.\"},{\"t\":\"بقلب واحد\",\"ref\":\"أعمال الرسل ١: ١٤\",\"bk\":\"أعمال الرسل\",\"v\":\"هؤلاء كلهم كانوا يواظبون بنفس واحدة على الصلاة والطلبة، مع النساء، ومريم أم يسوع، ومع إخوته.\",\"r\":\"«هؤلاء كلهم كانوا يواظبون بنفس واحدة على الصلاة والطلبة مع النساء ومريم أم يسوع ومع إخوته». كانوا ينتظرون وعد الآب. ولم يملؤوا الانتظار بالقلق بل بالصلاة معًا. وجاء الروح القدس على جماعة متحدة. فالوحدة تهيّئ لاستقبال النعمة.\",\"p\":\"يا رب، علّمنا أن نواظب بنفس واحدة على الصلاة. حوّل أوقات انتظارنا إلى لقاء معك ومع بعضنا، واملأنا بروحك القدوس. آمين.\",\"x\":\"وجود العذراء مريم بين التلاميذ يعطي بُعدًا للأمومة الروحية. وكانوا من خلفيات مختلفة لكنهم اتحدوا. والمواظبة تعني الاستمرارية: لم يكن لقاء واحدًا. وبعد عشرة أيام جاء حلول الروح القدس. ونحن أيضًا ننتظر عمل الله في حياتنا بالصلاة والوحدة. وما أجمل أن تتحول فترات الانتظار إلى فترات صلاة مشتركة.\\nإن كنت تنتظر أمرًا مهمًا، فشارك الانتظار مع جماعة صغيرة أو أسرة بلقاء صلاة هذا الأسبوع.\"},{\"t\":\"كيف ينبغي أن نصلي؟\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلم الأب مكاريوس أننا لا نحتاج إلى كثرة الكلام، بل أن نمد أيدينا إلى العلاء ونقول: يا رب ارحمنا كما تريد وكما تعلم. هكذا نصلي معًا بكلمة بسيطة. رددوا هذه الجملة اليوم في البيت أو الكنيسة.\",\"p\":\"يا رب، ارحمنا كما تريد وكما تعلم. علّمنا أن نصلي معًا ببساطة، وأن تجمعنا صلاتنا في اسمك. آمين.\",\"x\":\"كيف نصلي معًا؟ بالتفاهم والانتباه والمحبة. تدريب: اطلب صلاة من شخص حاجة تحتاجها.\",\"fq\":239}]},\"5-18\":{\"th\":\"العبادة بالروح والحق\",\"m\":[{\"t\":\"أنا أستيقظ مبكرًا\",\"ref\":\"المزمور ٥٦ (٥٧) — السادسة\",\"v\":\"استيقظ يا مجدي، استيقظ أيها المزمار والقيثارة. أنا أستيقظ مبكرا.\",\"r\":\"يوقظ المرنم مجده: «استيقظ يا مجدي، استيقظ أيها المزمار والقيثارة. أنا أستيقظ مبكرًا». العبادة بالروح والحق تبدأ من اليقظة الداخلية قبل الصوت الخارجي. حاول اليوم أن تصلي بكلمات قليلة ولكن بانتباه كامل.\",\"p\":\"استيقظ يا مجدي، استيقظ أيها المزمار والقيثارة. يا رب، أنا أستيقظ لأعبدك بالروح والحق، وأسبحك من كل قلبي. آمين.\",\"x\":\"استيقظ يا مجدي، فالعبادة بالروح والحق صحوة قلب. تدريب: ابدأ يومك بتسبيحة صادقة تخرج من القلب.\"},{\"t\":\"امتلئوا بالروح\",\"ref\":\"أفسس ٥: ١٨–١٩\",\"bk\":\"أفسس\",\"v\":\"ولا تسكروا بالخمر الذي فيه الخلاعة، بل امتلئوا بالروح، مكلمين بعضكم بعضا بمزامير وتسابيح وأغاني روحية، مترنمين ومرتلين في قلوبكم للرب.\",\"r\":\"«ولا تسكروا بالخمر الذي فيه الخلاعة بل امتلئوا بالروح». كلنا نبحث عن ما يملأنا. فهناك امتلاء بالأشياء يؤدي إلى فراغ، وامتلاء بالروح يؤدي إلى فرح وترنيم. والامتلاء بالروح ليس حدثًا واحدًا بل حالة مستمرة تتغذى بالصلاة والكلمة.\",\"p\":\"يا روح الله، املأني بك. اجعلني أرتل وأسبح في قلبي كل حين، وأشكر الآب بكل شيء، وأخضع لإخوتي بمحبة المسيح. آمين.\",\"x\":\"النتيجة العملية للامتلاء بالروح: مزامير وتسابيح وأغانٍ روحية في القلب وفي الجماعة، ثم شكر في كل حين، ثم خضوع لبعضنا. أي أن الروح يثمر عبادة وشكرًا ومحبة. وفي الكنيسة نمارس هذا في الألحان والترانيم والتسبحة. وفي البيت يمكن أن ندخل الترنيم في أيامنا. وهو يغيّر أجواءنا الداخلية والخارجية.\\nرنّم أو اسمع تسبحة أو مزمورًا اليوم، وارفع قلبك مع الكلمات، وأضف شكرًا لله على نعمة محددة.\"},{\"t\":\"الصلاة في القلب دائمًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال القديس إبيفانيوس لرئيس دير أهمل صلوات النهار: الراهب الحقيقي ينبغي أن يحوي الصلاة في قلبه على الدوام. العبادة بالروح لا تتوقف عند ساعة الكنيسة. خذ اليوم جملة قصيرة من صلاة تحملها في قلبك طوال النهار.\",\"p\":\"يا رب، اجعل الصلاة في قلبي على الدوام. علّمني أن أعبدك بالروح والحق في كل ساعة وكل مكان. آمين.\",\"x\":\"الله يطلب عابدين بالروح والحق لا بالمظاهر. تدريب: صلِّ اليوم بلا نص مكتوب، بكلماتك أنت.\",\"fq\":99}]},\"5-19\":{\"th\":\"الروح والجسد\",\"m\":[{\"t\":\"ولتنطفئ حرارة الجسد\",\"ref\":\"تحليل الستار\",\"v\":\"أيها السيد الرب يسوع المسيح إلهنا اعطنا راحة في نومنا ونياحا في أجسادنا وطهارة في أنفسنا. واحفظنا من ظلمة الخطية المدلهمة. ولتسكن حركات الآلام ولتنطفئ حرارة الجسد.\",\"r\":\"تطلب الكنيسة راحة الجسد وطهارة النفس وسكون الآلام. الصراع بين الروح والجسد ليس عداوة مع الجسد نفسه، بل ترتيب: الروح تقود والجسد يتبع. قبل أن تنام الليلة، سلّم جسدك وأفكارك لله وقل: سكّن حركاتي.\",\"p\":\"أيها السيد الرب يسوع، أعطنا راحة في نومنا وطهارة في أنفسنا. احفظنا من ظلمة الخطية، واجعل الروح تقود حياتنا. آمين.\",\"x\":\"الكنيسة تطلب إخماد حرارة الجسد وسكون الآلام، فالصراع بين الجسد والروح يحتاج نعمة. تدريب: اطلب النعمة قبل أن تواجه أي تجربة.\"},{\"t\":\"إن أمتم أعمال الجسد\",\"ref\":\"رومية ٨: ١٣\",\"bk\":\"رومية\",\"v\":\"لأنه إن عشتم حسب الجسد فستموتون، ولكن إن كنتم بالروح تميتون أعمال الجسد فستحيون.\",\"r\":\"«لأنه إن عشتم حسب الجسد فستموتون ولكن إن كنتم بالروح تميتون أعمال الجسد فستحيون». الإماتة ليست كراهية للجسد بل رفضًا لأعمال تقتل الروح. وهي تتم بالروح لا بإرادتي وحدي. فأنا أتعاون مع نعمة تميت العادات السيئة.\",\"p\":\"يا رب، روح قيامتك ساكن فيّ. أمِت بروحك أعمال الجسد فيّ، وأعطني حياة وسلامًا، وقوِّ إرادتي لأقول لا لما يقتل روحي. آمين.\",\"x\":\"قبل هذه الآية: «وإن كان روح الذي أقام يسوع من الأموات ساكنًا فيكم فالذي أقام المسيح من الأموات سيحيي أجسادكم المائتة أيضًا بروحه الساكن فيكم». فنحن نملك قوة القيامة. وهذه القوة تعمل في إماتة العادات. والكنيسة تمارس ذلك بالصوم والسهر. فهي وسائل لتقوية الروح. ونتائجها حياة وسلام. وكل مرة نرفض شهوة نكتسب حرية أكبر.\\nاختر اليوم عادة واحدة تضعف روحك، وامتنع عنها لمدة اليوم كله باسم قيامة المسيح.\"},{\"t\":\"الصوم يسمو فوق اللذة\",\"ref\":\"\",\"v\":\"\",\"r\":\"تشجع الأم سينكليتيكي على ألا يغرينا تنعّم الأغنياء بلذتهم الجوفاء، فالصائم يسمو فوق طيّبات أطعمتهم. تدريب الجسد على الامتناع يحرر الروح. اختر اليوم امتناعًا صغيرًا عن شيء مباح، وقدّمه صلاة.\",\"p\":\"يا رب، علّمني أن أضبط جسدي ليخدم الروح. أعطني نعمة الامتناع بفرح، فأتحرر من عبودية اللذة. آمين.\",\"x\":\"الصوم يساعد الجسد على أن يسكن. تدريب: امتنع عن شيء محبب اليوم، وقدمه لله.\",\"fq\":533}]},\"5-20\":{\"th\":\"محبة الله والإخوة\",\"m\":[{\"t\":\"الرب يجمع المتفرقين\",\"ref\":\"المزمور ١٤٦ — النوم\",\"v\":\"الرب يبني أورشليم. الرب يجمع متفرقي إسرائيل.\",\"r\":\"يعلن المرنم أن الرب يبني أورشليم ويجمع متفرقي إسرائيل. محبة الله ليست شعورًا عابرًا بل عمل بناء وجمع. ومن أحب الله أحب أن يجمع هو أيضًا لا أن يفرّق. من هو الأخ الذي ابتعد عنك؟ ابدأ اليوم بخطوة جمع صغيرة نحوه.\",\"p\":\"الرب يبني أورشليم ويجمع متفرقي إسرائيل. يا رب، اجمعني بمحبتك إليك وإلى إخوتي، واجعلني أداة بنيان لا هدم. آمين.\",\"x\":\"الرب يبني ويجمع المتفرقين، ومحبة الله تُظهر في جمع الشمل. تدريب: اجمع بين اثنين متخاصمين بمصالحة، أو ادع لهما.\"},{\"t\":\"إن أحب بعضنا بعضًا\",\"ref\":\"يوحنا الأولى ٤: ١١–١٢\",\"bk\":\"يوحنا الأولى\",\"v\":\"أيها الأحباء، إن كان الله قد أحبنا هكذا، ينبغي لنا أيضا أن يحب بعضنا بعضا. الله لم ينظره أحد قط. إن أحب بعضنا بعضا، فالله يثبت فينا، ومحبته قد تكملت فينا.\",\"r\":\"«إن كان الله قد أحبنا هكذا ينبغي لنا أيضًا أن يحب بعضنا بعضًا. الله لم ينظره أحد قط. إن أحب بعضنا بعضًا فالله يثبت فينا ومحبته قد تكملت فينا». محبة الإخوة هي الطريقة التي يراه بها العالم. وهي تكمل محبته فيّ.\",\"p\":\"يا رب، أنت أحببتنا فعلّمنا أن نحب. اجعل محبتك تكمل فينا، واظهر من خلالنا للعالم الذي لا يراك، وثبّتنا في المحبة. آمين.\",\"x\":\"الله غير منظور، لكن محبته تُرى في حياة المحبين. وهذا يعطينا مسؤولية شهادة: أن نكون «وجه الله» لمن حولنا. والمحبة تكتمل فينا حين نمارسها. فهي ليست جاهزة بل تنمو بالتدريب. ثم يقول يوحنا: «نحن قد عرفنا وصدقنا المحبة التي لله فينا». فالمحبة اختبار ويقين. ومن ثبت فيها ثبت في الله.\\nكن اليوم «وجه الله» لشخص واحد: ابتسامة واهتمام وإصغاء حقيقي دون استعجال.\"},{\"t\":\"الحث على المحبة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: «كثيرون صاروا أقوياء، لكن القليلين يحثّون على المحبة». أي أن القوة سهلة والمحبة نادرة. لا تكتفِ اليوم بأن تحب، بل شجّع أخًا على محبة، بكلمة أو بمثال حي.\",\"p\":\"يا رب، علّمني أن أحث على المحبة بأعمالي. اجعلني بين القلة الذين يرفعون الآخرين ويشجعونهم على أن يحبوا. آمين.\",\"x\":\"الحث على المحبة هو عمل الراعي. تدريب: شجع شخصًا اليوم بكلمة محبة.\",\"fq\":410}]},\"5-21\":{\"th\":\"حكمة الله\",\"m\":[{\"t\":\"عظيم هو الرب\",\"ref\":\"المزمور ١٤٦ — النوم\",\"v\":\"المحصي كثرة الكواكب، ولكافتها يعطي أسماء. عظيم هو الرب وعظيمة هي قوته؛ ولا إحصاء لفهمه.\",\"r\":\"يتأمل المرنم أن الرب يحصي كثرة الكواكب ويدعو كل واحد باسمه، وأن فهمه لا إحصاء له. حكمة الله لا تُقاس بحجم معرفتنا. اسجد اليوم في صلاتك أمام لغز لا تفهمه، وقل: عظيم أنت يا رب، وأنا أثق بحكمتك.\",\"p\":\"عظيم أنت يا رب وعظيمة قوتك، ولا إحصاء لفهمك. أنت تحصي الكواكب وتعرف أسماءها، فاعرف قلبي وقده بحكمتك. آمين.\",\"x\":\"يحصي الله الكواكب ويدعو كلًا باسمه، فلا ننسى أمامه. تدريب: اذكر لنفسك أن الله يعرف اسمك الآن.\"},{\"t\":\"ما لم تر عين\",\"ref\":\"كورنثوس الأولى ٢: ٩\",\"bk\":\"كورنثوس الأولى\",\"v\":\"بل كما هو مكتوب: «ما لم تر عين، ولم تسمع أذن، ولم يخطر على بال إنسان: ما أعده الله للذين يحبونه».\",\"r\":\"«ما لم تر عين ولم تسمع أذن ولم يخطر على بال إنسان ما أعده الله للذين يحبونه». أفكاري صغيرة أمام عطايا الله. وهذا يعطيني رجاء لا حدود له. فلا أحكم على مستقبلي بما أتخيله، ولا أستسلم لتوقعات ضيقة.\",\"p\":\"يا رب، ما أعددته لمن يحبونك يفوق كل تصوري. افتح قلبي لروحك ليعلن لي ما لم تره عيني، وأعطني رجاءً لا حدود له. آمين.\",\"x\":\"بعد هذه الآية يقول بولس: «فأعلنه الله لنا نحن بروحه». أي أن الروح القدس يعرّفنا من هذه الأمور بقدر ما نحتمل. فنحن نعيش في رجاء ويقين. وهذه الآية تتردد في التأملات عن السماء. لكنها تنطبق أيضًا على الحياة الآن: ما يعده الله أعظم مما نظن. وأعظم شيء هو معرفة الله نفسه. فلنفتح قلوبنا للمفاجآت الصالحة.\\nاكتب حلمًا صغيرًا تخاف أن تطلبه من الله، وقدمه له بثقة في صلاتك اليوم.\"},{\"t\":\"حكماء كالحيات\",\"ref\":\"\",\"v\":\"\",\"r\":\"تفسر الأم سينكليتيكي قول الرب «كونوا حكماء كالحيّات ودعاء كالحمام» بأننا لا ينبغي أن تنطلي علينا ألاعيب الشيطان. الحكمة الإلهية تجمع الانتباه والوداعة. اطلب اليوم حكمة تميّز دون أن تتصلب.\",\"p\":\"يا رب، أعطني حكمة الحيات ووداعة الحمام. احفظني من خداع العدو، وقوِّ قلبي بحكمتك. آمين.\",\"x\":\"الحكمة كالحيات والبساطة كالحمام. تدريب: كن حكيمًا في تعاملك اليوم وبسيطًا في نيتك.\",\"fq\":544}]},\"5-22\":{\"th\":\"الشكر في كل شيء\",\"m\":[{\"t\":\"أنت إلهي فأشكرك\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"أنت هو إلهي فأشكرك، إلهي أنت فأرفعك. أعترف لك يا رب، لأنك استجبت لي وصرت لي مخلصا.\",\"r\":\"يسبح المرنم إلهه معترفًا: لأنك استجبت لي وصرت لي مخلصًا. الشكر هنا ليس مجاملة بل شهادة. أمسك ورقة وسجّل ثلاث استجابات حدثت لك هذا العام، وقدّمها لله اليوم شكرًا صريحًا.\",\"p\":\"أنت هو إلهي فأشكرك، إلهي أنت فأرفعك. أعترف لك يا رب لأنك استجبت لي وصرت لي مخلصًا. آمين.\",\"x\":\"لأنك استجبت لي وصرت لي مخلصًا، فالشكر على الخلاص أساس. تدريب: اشكر الله اليوم على ثلاثة أمور لم تطلبها.\"},{\"t\":\"أشكر إلهي\",\"ref\":\"فيلبي ١: ٣\",\"bk\":\"فيلبي\",\"v\":\"أشكر إلهي عند كل ذكري إياكم\",\"r\":\"«أشكر إلهي كلما ذكرتكم». بولس في السجن لكنه يشكر على أصدقائه. وهذا يدفعني أن أتذكر من أثروا في حياتي، وأشكر الله عليهم. فمن عرفتهم كانوا عطايا. وذكرهم بالشكر يغذي قلبي بمحبة.\",\"p\":\"يا رب، أشكرك على كل من وضعتهم في حياتي. بارك كل واحد منهم، وأكمل فيهم العمل الصالح الذي بدأته، واجعلني أصلي لأجلهم بفرح. آمين.\",\"x\":\"عندما نتذكر الناس بالشكر، نرى فيهم نعمة الله لنا. وهذا يغير علاقتنا بهم. وحتى من أساءوا إلينا قد علمونا دروسًا. وبولس يقول بعدها: «واثقًا بهذا عينه أن الذي ابتدأ فيكم عملًا صالحًا يكمل إلى يوم يسوع المسيح». فهو يشكر ويثق. والشكر لله على الناس يجعلنا نصلي لأجلهم بفرح. وهذا بداية شركة حقيقية.\\nاتصل اليوم أو اكتب لشخص تشكر الله عليه، وقل له بصراحة إنك تشكر الله على وجوده.\"},{\"t\":\"هنيئًا لمن يحتمل التعب بشكر\",\"ref\":\"\",\"v\":\"\",\"r\":\"عبارة الأب كوبريس في سطر: «هنيئًا لمن يحتمل التعب بشكر». أي أن الشكر لا ينتظر الراحة. إن كان تعب اليوم ثقيلًا، فاشكر فيه حتى قبل أن ينتهي، وانظر كيف يخف.\",\"p\":\"يا رب، علّمني أن أشكر في التعب. أعطني قلبًا يرى في كل جهد نعمة وفي كل تعب خيرًا. آمين.\",\"x\":\"هنيئًا لمن يحتمل بشكر. تدريب: اشكر في موقف مزعج واحد اليوم.\",\"fq\":222}]},\"5-23\":{\"th\":\"قوة الاسم\",\"m\":[{\"t\":\"ما أعجب اسمك\",\"ref\":\"المزمور الثامن — باكر\",\"v\":\"أيها الرب ربنا، ما أعجب اسمك في الأرض كلها! لأنه قد ارتفع عظم جلالك فوق السموات.\",\"r\":\"يفتتح المرنم صلاته بالتعجب من اسم الرب في الأرض كلها، وارتفاع جلاله فوق السماوات. الاسم ليس لفظًا بل حضور الله نفسه. حين تنطق «يا رب يسوع ارحمني» اليوم، تذكّر أنك تستدعي ملك الأرض.\",\"p\":\"أيها الرب ربنا، ما أعجب اسمك في الأرض كلها. ارتفع جلالك فوق السماوات، فاسمك قوتي وملجئي في كل ضيق. آمين.\",\"x\":\"ما أعجب اسمك في الأرض كلها، فاسم الرب يملأ الأرض. تدريب: انطق اسم يسوع اليوم بتمهل ثلاث مرات، واجعله صلاة.\"},{\"t\":\"مهما سألتم باسمي\",\"ref\":\"يوحنا ١٤: ١٣–١٤\",\"bk\":\"يوحنا\",\"v\":\"ومهما سألتم باسمي فذلك أفعله ليتمجد الآب بالابن. إن سألتم شيئا باسمي فإني أفعله.\",\"r\":\"«ومهما سألتم باسمي فذلك أفعله ليتمجد الآب بالابن». الصلاة باسم المسيح ليست إضافة عبارة بل مطابقة لقلبه ومشيئته. وغاية الاستجابة أن يتمجد الآب. وهذا يهذب طلباتي: هل ما أطلبه يمجد الله؟ ويعطيني ثقة بقبول الطلب.\",\"p\":\"يا رب يسوع، أطلب باسمك فاستجب لي بحسب مشيئتك ليتمجد الآب بك. هذّب طلباتي، وأعطني ثقة بمحبتك وحكمتك في كل استجابة. آمين.\",\"x\":\"طلب «باسمه» يعني بحسب شخصه وإرادته وسلطانه. فهو ليس سحرًا. ولذلك نصلي ونقول «لتكن مشيئتك». ومن هنا نتعلم أن نطلب أمورًا تتفق مع محبة الله. وتأتي الاستجابة بطرق متنوعة، قد لا تكون كما نتوقع. لكنها تصب في مجد الآب. وما أجمل وعد المسيح: «أنا أفعله»! فهو شريك في كل صلاة.\\nقبل طلبك اليوم اسأل: هل هذا يمجد الآب؟ ثم اطلب باسم يسوع بثقة.\"},{\"t\":\"اسم أكبر من العمل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يتحسر الأب سلوان على من كان اسمه أكبر من عمله. قوة الاسم المسيحي تكمن في أن يطابقه السلوك. حين يسمّيك الناس مسيحيًا، هل يجدون حياة تشهد لهذا الاسم؟ اجعل عملك اليوم يشرّف الاسم.\",\"p\":\"يا رب، لا تدعني أحمل اسمك باطلًا. اجعل أعمالي توافق اسم المسيحي الذي دعيت به. آمين.\",\"x\":\"اسم الله أكبر من أعمالنا، فلا نتكل على إنجازاتنا. تدريب: اترك إنجازًا ولا تذكره اليوم.\",\"fq\":514}]},\"5-24\":{\"th\":\"الكرازة\",\"m\":[{\"t\":\"بشروا بخلاصه\",\"ref\":\"المزمور ٩٧ (٩٨) — التاسعة\",\"v\":\"سبحوا الرب تسبيحا جديدا لأن الرب قد صنع أعمالا عجيبة. خلصت له يمينه وذراعه القدوس، أعلن الرب خلاصه وكشف قدام الأمم عدله.\",\"r\":\"تعلن الكرازة ما صنعه الله: أعمال عجيبة وخلاص يمين الله وعدله. ليس المبشر صاحب الرسالة بل ناقلها. في حديث اليوم مع من يهمّك أمره، اذكر شيئًا واحدًا صنعه الله معك، وقله بصدق دون ضغط.\",\"p\":\"سبحوا الرب تسبيحًا جديدًا لأنه صنع أعمالًا عجيبة. يا رب، أعطني فمًا يعلن خلاصك، وحياة تشهد لعدلك أمام الأمم. آمين.\",\"x\":\"بشروا بخلاصه: الكرازة إعلان ما صنع الله. تدريب: احكِ لأحد قصة صغيرة عن عمل الله معك.\"},{\"t\":\"اذهبوا إلى العالم\",\"ref\":\"مرقس ١٦: ١٥\",\"bk\":\"مرقس\",\"v\":\"وقال لهم: «اذهبوا إلى العالم أجمع واكرزوا بالإنجيل للخليقة كلها.\",\"r\":\"«اذهبوا إلى العالم أجمع واكرزوا بالإنجيل للخليقة كلها». الإنجيل ليس سرًا بل بشرى لكل أحد. وهذه ليست مهمة المتخصصين فقط، بل دعوة لكل مؤمن بحسب موقعه. والبشارة تبدأ بحياة تشهد وكلمة محبة في وقتها.\",\"p\":\"يا رب، أرسلني إلى من تريد لأحمل بشارتك. أعطني محبة وحكمة وجرأة، وافتح قلوب من حولي لسماع كلمتك. آمين.\",\"x\":\"«اذهبوا» تعني تحركوا خارج دائرة الراحة. و«العالم أجمع» يعني لا حدود جغرافية أو اجتماعية. و«الخليقة كلها» تعني أن الفداء يشمل الكل. وقد يكون «العالم» عندي هو زملائي وجيراني وأقاربي. والكرازة تبدأ بالمحبة والاحترام والصبر، وليس بالجدال. والله هو الذي يقنع القلوب. ونحن ننقل البشارة بوداعة. وبهذا نكمل مهمة التلاميذ الأولى.\\nاختر شخصًا واحدًا في دائرتك وقدم له اليوم عملًا صغيرًا من المحبة يعكس بشارة الإنجيل بدون وعظ.\"},{\"t\":\"الكلمة الطيبة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب مكاريوس: «الكلمة الشريرة تجعل الصالحين أشرارًا، أما الكلمة الطيبة فمن شأنها أن تجعل الأشرار صالحين». الكرازة الأولى كلمة طيبة. قل اليوم كلمة تشجيع صادقة لشخص لا يتوقعها.\",\"p\":\"يا رب، ضع في فمي كلمة طيبة تبني. اجعل كلامي مبشرًا بك، وتغيّر قلوب من يسمعه. آمين.\",\"x\":\"الكلمة الطيبة كرازة صغيرة. تدريب: قل ثلاث كلمات طيبة اليوم لأشخاص مختلفين.\",\"fq\":250}]},\"5-25\":{\"th\":\"الأمور الصغيرة\",\"m\":[{\"t\":\"من هو الإنسان حتى تذكره؟\",\"ref\":\"المزمور الثامن — باكر\",\"v\":\"من هو الإنسان حتى تذكره. أو ابن الإنسان حتى تفتقده؟!\",\"r\":\"يتعجب المرنم من أن الله يذكر الإنسان ويفتقده، رغم عظمة السماوات. الله لا يزدري الصغير. إن شعرت أن ما تفعله اليوم صغير لا قيمة له، فتذكّر أن من يحصي الكواكب يهتم بكأس ماء بارد.\",\"p\":\"من هو الإنسان حتى تذكره، وابن الإنسان حتى تفتقده؟ يا رب، أشكرك على اهتمامك بالصغير. بارك الأمور الصغيرة في يدي. آمين.\",\"x\":\"من هو الإنسان حتى تذكره؟ يتعجب المرنم من اهتمام الله بالصغير. تدريب: تأمل في اهتمام الله بتفاصيل حياتك.\"},{\"t\":\"كأس ماء بارد\",\"ref\":\"متى ١٠: ٤٢\",\"bk\":\"متى\",\"v\":\"ومن سقى أحد هؤلاء الصغار كأس ماء بارد فقط باسم تلميذ، فالحق أقول لكم إنه لا يضيع أجره».\",\"r\":\"«ومن سقى أحد هؤلاء الصغار كأس ماء بارد فقط باسم تلميذ فالحق أقول لكم إنه لا يضيع أجره». كأس ماء! لا مال ولا مجهود كبير، لكن المسيح يحسبه. فالمحبة الصغيرة عند الله عظيمة. وكل لفتة طيبة تحمل أجرًا.\",\"p\":\"يا رب، أشكرك لأنك تحسب أصغر عطية. علّمني أن أخدم بالصغائر بمحبة، وأن أرى فيها خدمتك، فلا يضيع أجر ما أقدمه باسمك. آمين.\",\"x\":\"المسيح يعبر عن اهتمامه بأدق التفاصيل. وهو يرى كأس الماء الذي نقدمه لمتعب أو غريب. وهذا يعطي معنى للخدمة اليومية: كوب شاي لزميل متعب، أو مساعدة لجار. ولا يعني هذا أن نتجاهل الأعمال الكبيرة بل أن نقدّر الصغيرة. والوعد «لا يضيع أجره» يجعلنا نخدم بلا انتظار تصفيق. فالأجر عند الذي يرى في الخفاء.\\nقدم اليوم «كأس ماء بارد» لشخص: خدمة صغيرة أو كلمة شكر أو مساعدة بسيطة، دون ضجيج.\"},{\"t\":\"ما تراه فافعله\",\"ref\":\"\",\"v\":\"\",\"r\":\"ألحّ أخ على الأب سيسوى أن يعطيه كلمة واحدة، فقال له: «لماذا ترغمني على الكلام؟ ما تراه إياه افعل». أي لا تنتظر العظائم، بل افعل الخير الذي تراه أمامك. ما الخير الصغير الذي تراه ولا تفعله؟ افعله الآن.\",\"p\":\"يا رب، علّمني أن أفعل الخير الذي أراه ولو كان صغيرًا. اجعلني أمينًا في القليل وأعمل بما ترشدني إليه. آمين.\",\"x\":\"الأمور الصغيرة تُرى في عين الله كبيرة. تدريب: أتقن عملًا صغيرًا اليوم باهتمام كبير.\",\"fq\":508}]},\"5-26\":{\"th\":\"البحث عن الضال\",\"m\":[{\"t\":\"ضللت مثل الخروف الضال\",\"ref\":\"المزمور ١١٨ — الجزء الثاني والعشرون («كُونوا مُستَعِدّينَ، لأنَّهُ في ساعَةٍ لا تَظُنّونَ يَأتي ابنُ الإنسان.») — الستار\",\"v\":\"وأحكامك تعينيني. ضللت مثل الخروف الضال، فاطلب عبدك، فإني لوصاياك لم أنس هلليلويا.\",\"r\":\"يعترف المرنم بأنه ضلّ مثل الخروف الضال ويطلب من الله أن يطلب عبده. المسيح هو الراعي الذي يخرج للبحث. من ضلّ لا يفقد قيمته، بل يُطلب. فكّر اليوم في إنسان ابتعد عن الكنيسة أو عنك، وصلّ من أجله بالاسم.\",\"p\":\"ضللت مثل الخروف الضال، فاطلب عبدك لأني لوصاياك لم أنس. يا راعي الخراف، ابحث عني وعن كل ضال، وردنا إلى حظيرتك. آمين.\",\"x\":\"ضللت مثل الخروف الضال فاطلب عبدك، فالراعي يبحث عن الضال. تدريب: اسأل أين ضللت، وارجع إلى الراعي اليوم.\"},{\"t\":\"لا أسر بموت الشرير\",\"ref\":\"حزقيال ١٨: ٢٣\",\"bk\":\"حزقيال\",\"v\":\"هل مسرة أسر بموت الشرير؟ يقول السيد الرب. ألا برجوعه عن طرقه فيحيا؟\",\"r\":\"«هل مسرة أسر بموت الشرير؟ يقول السيد الرب. ألا برجوعه عن طرقه فيحيا؟». الله لا يتلذذ بمعاقبة أحد. فهو يشتاق إلى عودتي. وهذا يغيّر نظرتي إليه: ليس قاضيًا متربصًا بل أبًا ينتظر. ويغير نظرتي للخاطئين: فهم أحباء ينتظرهم.\",\"p\":\"يا رب، أشكرك لأنك لا تسر بموت الخاطئ بل برجوعه. أرجع إليك اليوم، فاقبلني، وعلّمني أن أنظر إلى الخطاة بنظرة محبتك وانتظارك. آمين.\",\"x\":\"الرسالة النبوية هنا ضد من اتهم الله بالظلم. والله يجيب: بل هو يعطي كل واحد فرصة العودة. وإن رجع الشرير عن شره يُغفر له، وإن رجع البار عن بره يفقد. فالمهم هو الاتجاه الحالي. وهذا يحمي من الاتكال على ماضينا الجيد ومن اليأس بسبب ماضينا السيئ. ونحن نعيش في أيام الفرصة. وكل يوم فرصة للرجوع.\\nاسأل: هل أنا متجه نحو الله اليوم؟ وإن لا فاتخذ خطوة رجوع صغيرة: اعتراف، أو صلاة، أو تصالح.\"},{\"t\":\"خاطئ يتوب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سارمتا: «أفضل إنسانًا خاطئًا لكنه يعرف خطيته ويتوب عليها، على إنسان لا يخطئ بل يرى نفسه بارًا». الله يبحث عن التائب ويفرح به. لا تحكم على أحد ضال، بل تذكّر أنك كنت مطلوبًا أنت أيضًا.\",\"p\":\"يا رب، اجعلني أعرف خطيتي وأتوب عنها. ولا تدعني أرى نفسي بارًا فأبتعد عن رحمتك. آمين.\",\"x\":\"الخاطئ التائب مكرّم عند الله. تدريب: لا تستصغر خاطئًا اليوم، فقد يكون تائبًا.\",\"fq\":517}]},\"5-27\":{\"th\":\"الشفاعة\",\"m\":[{\"t\":\"أنت استجبت لهم\",\"ref\":\"المزمور ٩٨ (٩٩) — التاسعة\",\"v\":\"لأنهم حفظوا شهاداته. والأوامر التي أعطاهم. أيها الرب إلهنا، أنت استجبت لهم.\",\"r\":\"يمدح المرنم موسى وهرون وصموئيل لأنهم حفظوا شهادات الله وأوامره، وأن الله استجاب لهم. الشفاعة تقوى بالأمانة. من هو الشخص الذي تحمله في صلاتك؟ اذكره اليوم بالاسم، واطلب له خيرًا كما تطلب لنفسك.\",\"p\":\"أيها الرب إلهنا، أنت استجبت لهم لأنهم حفظوا شهاداتك. علّمني أن أشفع في الآخرين بإيمان، وأحمل أحبائي أمامك في صلاتي. آمين.\",\"x\":\"موسى وهرون وصموئيل استجاب لهم الله لأنهم حفظوا شهاداته، وللشفاعة قوة. تدريب: اكتب أسماء خمسة أشخاص وصلِّ لهم اليوم.\"},{\"t\":\"كنت أود أن أكون أنا محرومًا\",\"ref\":\"رومية ٩: ٣\",\"bk\":\"رومية\",\"v\":\"فإني كنت أود لو أكون أنا نفسي محروما من المسيح لأجل إخوتي أنسبائي حسب الجسد،\",\"r\":\"«فإني كنت أود لو أكون أنا نفسي محرومًا من المسيح لأجل إخوتي أنسبائي حسب الجسد». هذا كان قلب بولس: حزن مستمر لأجل الذين لم يؤمنوا. وهذا يعلمني ألا أكون بارد القلب نحو من لا يعرف المسيح. بل أحزن وأصلي.\",\"p\":\"يا رب، أعطني قلبًا يتألم لخلاص الآخرين. ازرع فيّ محبة تصلي وتعمل من أجل البعيدين، وأعد إليك أقاربي وأحبائي. آمين.\",\"x\":\"بولس لم يتخلَّ عن شعبه رغم أنهم اضطهدوه. وهذه المحبة تتجاوز العداوة. وهو يقسم بالمسيح ويعلن صدقه: «لا أكذب». فالأمر عميق. والمحبة الراعوية تحمل ألمًا لخلاص الآخرين. وهذا الألم يترجم إلى صلاة وعمل. ولكل منا أقارب أو أصدقاء بعيدون عن الإيمان. فهل نحملهم في قلوبنا؟ هذا اختبار حبنا.\\nاكتب اسمي شخصين بعيدين عن الإيمان وصلِّ لأجلهما يوميًا هذا الأسبوع بكلمة محبة.\"},{\"t\":\"صلّوا من أجل بعضكم\",\"ref\":\"\",\"v\":\"\",\"r\":\"عندما جاء أخ يشكو كاهنًا، قال له الأب مرقس: «الكل يطرحون الفساد خارجًا، أما أنت فقد أحضرته إلي»، وذكّره بقول الكتاب: لا تدينوا. الشفاعة بدل الشكوى. صلِّ اليوم لمن يضايقك بدل أن تشكوه.\",\"p\":\"يا رب، علّمني أن أشفع في من يضايقني بدل أن أتكلم عنه. اجعل صلاتي رحمة تغطي ولا تفضح. آمين.\",\"x\":\"صلوا من أجل بعضكم لتشفوا، وصية الكتاب. تدريب: اطلب من أحد أن يصلي لأجلك ثم صلِّ له.\",\"fq\":286}]},\"5-28\":{\"th\":\"الخميرة\",\"m\":[{\"t\":\"يرسل كلمته فيسرع قوله\",\"ref\":\"المزمور ١٤٧ — النوم\",\"v\":\"الذي يرسل كلمته إلى الأرض فيسرع قوله عاجلا جدا. المعطي الثلج كالصوف.\",\"r\":\"يقول المرنم إن الله يرسل كلمته إلى الأرض فيسرع قوله عاجلًا جدًا. الخميرة الصغيرة في العجين تعمل بصمت حتى يختمر الكل. كلمة صادقة تقولها أو عمل خير تفعله قد يحمل أثرًا لا تراه. اترك اليوم في مكانك خميرة خير.\",\"p\":\"الذي يرسل كلمته إلى الأرض فيسرع قوله عاجلًا جدًا، أرسل كلمتك إلى قلبي وإلى بيتي. واجعلني خميرة صالحة في كل مكان. آمين.\",\"x\":\"يرسل الله كلمته فيسرع قوله، فكلمة الله فعالة. تدريب: اقرأ آية وانتظر أثرها في يومك.\"},{\"t\":\"قليل من الخميرة\",\"ref\":\"كورنثوس الأولى ٥: ٦\",\"bk\":\"كورنثوس الأولى\",\"v\":\"ليس افتخاركم حسنا. ألستم تعلمون أن خميرة صغيرة تخمر العجين كله؟\",\"r\":\"«أما تعلمون أن خميرة صغيرة تخمّر العجين كله؟». خطية صغيرة مخفية قد تنتشر وتفسد الجماعة. وهذا يعلّمني الجدية في معالجة الأخطاء الصغيرة قبل انتشارها. وقد تكون الخميرة نميمة أو كبرياء أو حسدًا. وعلاجها التنقية بالتوبة.\",\"p\":\"يا رب، نقِّ قلبي من خميرة الشر والخبث. اجعلني عجينًا جديدًا لأن فصحنا المسيح قد ذبح لأجلنا، وساعدني أن أحفظ نقاء جماعتك. آمين.\",\"x\":\"بولس يذكر بعدها: «نقوا منكم الخميرة العتيقة لكي تكونوا عجينًا جديدًا كما أنتم فطير. لأن فصحنا أيضًا المسيح قد ذبح لأجلنا». فالمسيح هو الذي يمكننا من التنقية. والعيد الذي نحتفل به هو احتفال حياة جديدة. وليس المقصود احتقار أحد، بل رعاية نقاء الجماعة بمحبة. وعلينا أن نفحص أنفسنا قبل أن نحكم على الآخرين. والتنقية فرح لا ثقل.\\nحدد «خميرة صغيرة» في قلبك (مثل نميمة أو حسد) وقرر أن ترفضها اليوم بصلاة صريحة.\"},{\"t\":\"الماء يثقب الصخرة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب بيمن كلمة الله بالماء الناعم الذي ينزل على الصخرة قطرة قطرة فيثقبها. هكذا تعمل الكلمة تدريجيًا في قلب قاسٍ. لا تيأس من بطء التغيير، وواظب اليوم على قطرة: آية تقرؤها وتتأملها.\",\"p\":\"يا رب، ليتنقط في قلبي ماء كلمتك فيثقب قسوته. واظب بي على قراءتها حتى تتغير حياتي. آمين.\",\"x\":\"الماء الهادئ يثقب الصخرة بالمثابرة. تدريب: ثبّت اليوم على عمل صغير بلا ملل.\",\"fq\":451}]},\"5-29\":{\"th\":\"الحصاد\",\"m\":[{\"t\":\"الأرض أعطت ثمرتها\",\"ref\":\"المزمور السادس والستون — باكر\",\"v\":\"الأرض أعطت ثمرتها، فليباركنا الله إلهنا. ليباركنا الله.\",\"r\":\"يعلن المرنم أن الأرض أعطت ثمرتها، ثم يطلب: فليباركنا الله إلهنا. الحصاد عطية قبل أن يكون إنجازًا. لا تشكر على الحصاد وحده، بل على الزارعين الذين سبقوك. تذكّر اليوم من زرع في حياتك الروحية.\",\"p\":\"الأرض أعطت ثمرتها، فليباركنا الله إلهنا. أشكرك على كل من زرع فيّ الإيمان. اجعلني حصادًا نافعًا وأرسلني لأحصد ما زرعته أنت. آمين.\",\"x\":\"الأرض أعطت ثمرتها، فتفرح الكنيسة بالحصاد. تدريب: اجمع ثمرة تعب من أشهر وشكر الله عليها.\"},{\"t\":\"الحصاد كثير\",\"ref\":\"متى ٩: ٣٧–٣٨\",\"bk\":\"متى\",\"v\":\"حينئذ قال لتلاميذه: «الحصاد كثير ولكن الفعلة قليلون. فاطلبوا من رب الحصاد أن يرسل فعلة إلى حصاده».\",\"r\":\"«الحصاد كثير ولكن الفعلة قليلون. فاطلبوا من رب الحصاد أن يرسل فعلة إلى حصاده». بدأ المسيح بالنظر بحنان إلى الجموع، ثم دعا إلى الصلاة. وأول الخدمة هي الصلاة: أن نطلب فعلة. وربما أكون أنا أحد الفعلة الذين يرسلهم الله استجابة لصلاة.\",\"p\":\"يا رب الحصاد، أرسل فعلة إلى حصادك. اجعلني مستعدًا أن أكون واحدًا منهم، وأعطني حنانك على الجموع المتعبة وجرأة على الخدمة. آمين.\",\"x\":\"قبل هذه الآية قيل إن المسيح «تحنن» على الجموع. فالدافع هو الحنان لا الإحصاء. ثم يرسل التلاميذ الاثني عشر. أي أن الذين يصلون يُرسلون أحيانًا. وهذا يعلمنا ألا نصلي بلا استعداد للإجابة. والحقول كثيرة: بيوت وأحياء وقلوب. والكنيسة تحتاج إلى مواهب متنوعة. ولا يجب أن ننتظر مؤهلات كبيرة بل قلبًا مستعدًا. والمسيح هو الذي يدرب.\\nصلِّ اليوم لأجل خدام جدد في كنيستك، وأضف: «وإن أردت، أرسلني».\"},{\"t\":\"رجاء وعمل\",\"ref\":\"\",\"v\":\"\",\"r\":\"الكلمة التي ينقلها الأب كيرس عن الرجاء والعمل تذكّرنا أن الرجاء بلا عمل لا يثمر. الحصاد الكثير يحتاج فعلة قليلين. فاسأل: ما العمل الذي يتطلبه رجائي اليوم؟ ابدأه ولو بخطوة.\",\"p\":\"يا سيد الحصاد، لا تدعني متفرجًا على حقلك. اجعلني واحدًا من فعلتك بالرجاء والعمل. آمين.\",\"x\":\"رجاء وعمل معًا، فلا نكتفي بأحدهما. تدريب: اتبع رجاءك بخطوة عملية.\",\"fq\":224}]},\"5-30\":{\"th\":\"الأيدي المرفوعة\",\"m\":[{\"t\":\"لتستقم صلاتي كالبخور\",\"ref\":\"المزمور ١٤٠ (١٤١) — النوم\",\"v\":\"لتسقم صلاتي كالبخور قدامك. وليكن رفع يدي كذبيحة مسائية.\",\"r\":\"يشبّه المرنم صلاته بالبخور ورفع يديه بذبيحة مسائية. الأيدي المرفوعة صورة التوسل والاتكال على الله وحده، وهي تحمل المحتاجين. ارفع يديك الليلة في صلاتك، ولو في سرك، وضع بين يديك كل من تحمله في قلبك.\",\"p\":\"لتستقم صلاتي كالبخور قدامك، وليكن رفع يدي كذبيحة مسائية. تقبّل يا رب صلاتي وشفاعاتي كما تقبّلت بخور هارون. آمين.\",\"x\":\"لتستقم صلاتي كالبخور ورفع يدي كذبيحة مسائية. الأيدي المرفوعة صلاة بلا كلام. تدريب: ارفع يديك الليلة قليلًا في صلاة صامتة.\"},{\"t\":\"يدا موسى ثقيلتان\",\"ref\":\"الخروج ١٧: ١١–١٢\",\"bk\":\"الخروج\",\"v\":\"وكان إذا رفع موسى يده أن إسرائيل يغلب، وإذا خفض يده أن عماليق يغلب. فلما صارت يدا موسى ثقيلتين، أخذا حجرا ووضعاه تحته فجلس عليه. ودعم هارون وحور يديه، الواحد من هنا والآخر من هناك. فكانت يداه ثابتتين إلى غروب الشمس.\",\"r\":\"«وكان إذا رفع موسى يده أن إسرائيل يغلب وإذا خفض يده أن عماليق يغلب». الصلاة لها أثر حقيقي في المعركة. وعندما ثقلت يدا موسى سنده أخواه. وهذا يعلمني أنني أحتاج إلى من يسندني في الصلاة، وأن أكون أنا أيضًا سندًا لغيري.\",\"p\":\"يا رب، أشكرك على قوة الصلاة. أعطني من يسند يديّ عند التعب، وأعطني أن أسند الآخرين، وأن نغلب بصلواتنا المشتركة. آمين.\",\"x\":\"موسى كان القائد، لكنه تعب. وهذا طبيعي. فلا عيب في الحاجة إلى مساندة. وهارون وحور قدما الحجر وسندا اليدين. أي أنهما فعلا شيئًا عمليًا. وهكذا ينبغي أن يكون دعم الصلاة: مباشر وثابت. وفي الكنيسة نؤمن بالصلاة المتبادلة. وفي الأسرة والخدمة يجب أن نوزع الأحمال. وكل قائد يحتاج إلى سند حتى تغيب الشمس أي حتى نهاية المعركة.\\nاختر قائدًا أو خادمًا وأرسل له اليوم رسالة تقول: «أنا أرفع يديك بالصلاة»، وصلِّ له.\"},{\"t\":\"النار والماء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب بيمن الإنسان الذي يشعل نارًا بيسراه ويحمل وعاء ماء بيمناه ليخمدها. هكذا الصلاة: الأيدي ترتفع لتطفئ نار الأفكار. عند أول فكر ملتهب اليوم، ارفع يدك في سرك واطلب الإخماد.\",\"p\":\"يا رب، أطفئ بصلاتي نار الأفكار التي تشتعل في قلبي. وارفع يدي إليك لتحفظني من الاضطراب. آمين.\",\"x\":\"النار والمصباح يحتاجان زيتًا دائمًا. تدريب: جدّد اليوم نشاطك الروحي بشيء بسيط.\",\"fq\":421}]},\"5-31\":{\"th\":\"كل الأشياء للخير\",\"m\":[{\"t\":\"إن سلكت في وسط الشدة\",\"ref\":\"المزمور ١٣٧ — النوم\",\"v\":\"إن سلكت في وسط الشدة فإنك تحييني. على رجز الأعداء مددت يدك وخلصتني يمينك.\",\"r\":\"يشهد المرنم أنه إن سلك في وسط الشدة فالله يحييه، وأن يده امتدت على رجز الأعداء. يختم الشهر بحقيقة: كل الأشياء تعمل معًا للخير. قد لا ترى الخير الآن، لكن يد الله ممدودة. اذكر شدة مضت وصارت خيرًا.\",\"p\":\"إن سلكت في وسط الشدة فإنك تحييني، وعلى رجز الأعداء تمد يدك وتخلصني يمينك. أشكرك لأن كل الأشياء تعمل معًا للخير. آمين.\",\"x\":\"إن سلكت في وسط الشدة فالله يحييني، ويده تمتد لتخلصني. تدريب: في كل ضيق اليوم اذكر: يده ممتدة.\"},{\"t\":\"أنتم قصدتم لي شرًا\",\"ref\":\"التكوين ٥٠: ٢٠\",\"bk\":\"التكوين\",\"v\":\"أنتم قصدتم لي شرا، أما الله فقصد به خيرا، لكي يفعل كما اليوم، ليحيي شعبا كثيرا.\",\"r\":\"«أنتم قصدتم لي شرًا. أما الله فقصد به خيرًا لكي يفعل كما اليوم ليحيي شعبًا كثيرًا». بعد سنين من السجن والظلم، رأى يوسف يد الله. لم ينكر الشر الذي وقع عليه، لكنه رأى أن الله حوّله لخير. وهذا يحررني من المرارة.\",\"p\":\"يا رب، علّمني أن أرى يدك وراء كل أذى. حوّل قصدهم الشر خيرًا في حياتي، وأعطني قلبًا يغفر كيوسف ويطمئن من أساء إليّ. آمين.\",\"x\":\"يوسف لم يتحول إلى كارهٍ، بل غفر وطمأن إخوته: «لا تخافوا… أنا أعولكم وأولادكم». فالنظرة الإيمانية تؤدي إلى الغفران. ولا يعني أن الأذى لا بأس به، لكن الله أقوى منه. وكل ظلم نقع فيه يمكن أن يتحول عند الله إلى خدمة. وهذا ينير حياتنا ويعطي كل جرح معنى. ومن هنا يتعلم الغافر أن يتحدث بحنان لا بتشفٍّ.\\nإن كان هناك شخص أساء إليك، فاسأل الله أن يريك كيف يحوّل ذلك إلى خير، وصلِّ لأجله.\"},{\"t\":\"سلّمه إلى الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب سيسوى أن من حلّت به تجربة يقول: «إن هذا حدث من أجل خطيئتي» ويسلّم الأمر إلى الله. هكذا يتحول الحدث إلى مدرسة. اختم الشهر بتسليم تجربة ما بين يدي الله بثقة أنه يرتب خيرًا.\",\"p\":\"يا رب، أسلّم لك كل تجربة. حوّل ما أراه شرًا إلى خير، وعلّمني أن أرى يدك في كل حدث. آمين.\",\"x\":\"سلّم الأمر لله وارتح، فالتسليم قوة. تدريب: اختر أمرًا واحدًا وسلمه لله تسليمًا كاملًا.\",\"fq\":498}]},\"6-1\":{\"th\":\"حلول الروح القدس\",\"m\":[{\"t\":\"جدّده في أحشائنا\",\"ref\":\"قطعة الثالثة (٢)\",\"v\":\"أيها الرب الذي أرسلت روح قدسك على تلاميذك القديسين ورسلك المكرمين في الساعة الثالثة، لا تنزعه منا، بل نسألك أن تجدده في أحشائنا روحًا مستقيمًا ومحييًا، روح القداسة والعدالة والسلطة.\",\"r\":\"صلاة الساعة الثالثة تذكّرنا بيوم حلول الروح على التلاميذ، وتطلب ألا يُنزع منا. الروح القدس يسكن في قلب مفتوح له، ويجدد ما فينا من الداخل. افتح قلبك الآن دقيقة صمت، وقل له: تفضل وجدد.\",\"p\":\"أيها الروح القدس، لا تنزعك مني، وجدد فيّ روحًا مستقيمًا. اجعل صلاتي اليوم منك لا مني، وخلّص نفسي بنعمتك. آمين.\",\"x\":\"صلاة الساعة الثالثة تذكرنا بحلول الروح على التلاميذ، فنطلب أن يجدد الله فينا روحًا مستقيمًا. الروح ليس ذكرى بل عطية حاضرة. تدريب: في الساعة الثالثة اليوم قل: جدد في أحشائي روحًا مستقيمًا.\"},{\"t\":\"امتلأ الجميع من الروح\",\"ref\":\"أعمال الرسل ٢: ١–٤\",\"bk\":\"أعمال الرسل\",\"v\":\"ولما حضر يوم الخمسين كان الجميع معا بنفس واحدة، وصار بغتة من السماء صوت كما من هبوب ريح عاصفة وملأ كل البيت حيث كانوا جالسين، وظهرت لهم ألسنة منقسمة كأنها من نار واستقرت على كل واحد منهم. وامتلأ الجميع من الروح القدس، وابتدأوا يتكلمون بألسنة أخرى كما أعطاهم الروح أن ينطقوا.\",\"r\":\"«وكان الجميع معًا بنفس واحدة… وامتلأ الجميع من الروح القدس». لم يكونوا يعملون شيئًا استثنائيًا، كانوا مجتمعين ومنتظرين. والروح القدس نزل على الجماعة كلها لا على فرد واحد. وهذا يعلمني أن الامتلاء يأتي في الشركة والانتظار والطاعة.\",\"p\":\"تعالَ يا روح الله واملأني. أحرق فيّ كل ما يعيق محبتك، وأعطني دفئًا وشجاعة لأشهد لك، واجمعنا معًا في وحدة الكنيسة. آمين.\",\"x\":\"الريح والنار صورتان للروح القدس: ريح تحرك، ونار تنقي وتدفئ. والألسنة المنقسمة تعني أن الروح يعطي كل واحد كلمة تناسبه. وكان هذا بداية انتشار الكنيسة. وفي المعمودية والميرون نلنا هذا الروح. وكل قداس هو طلب لحلول الروح على الجماعة والقرابين. ونحتاج أن نفتح قلوبنا ليحرك فينا الدفء والشجاعة.\\nاطلب اليوم من الروح القدس بصلاة بسيطة: «تعالَ يا روح الله واملأني»، ثم انتبه لما يحركه في قلبك من محبة أو شجاعة.\"},{\"t\":\"العمل الداخلي\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصينا الأب أرسانيوس أن نجاهد ليكون عملنا الداخلي موافقًا لإرادة الله، فتنهزم الأهواء الخارجية. والروح القدس هو الذي يعمل في الداخل. اسأل نفسك اليوم: ما الذي يريده الله في قلبي أكثر مما في مظهري؟\",\"p\":\"يا رب، أرني ما في داخلي، واعمل أنت فيه بروحك القدوس. أعطني جهادًا هادئًا يوافق مشيئتك. آمين.\",\"x\":\"الروح يعمل في القلب الذي يتهيأ له، وتهيئته بالتوبة والصلاة. تدريب: خصص اليوم لحظة صمت تطلب فيها حلول الروح.\",\"fq\":29}]},\"6-2\":{\"th\":\"الاستنارة بالروح\",\"m\":[{\"t\":\"الرب نوري\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"الرب نوري وخلاصي ممن أخاف؟! الرب حصن حياتي ممن أجزع؟!\",\"r\":\"حين يكون الرب نورنا لا يبقى للخوف سلطان، فالنور يكشف الطريق قبل أن يطرد الظلمة. الاستنارة عطية تُطلب كل صباح. قبل أن تقرأ أو تقرر شيئًا اليوم، اطلب نورًا للخطوة التالية فقط.\",\"p\":\"يا رب، أنت نوري وخلاصي. أنر عقلي وقلبي في كل قرار، ولا تدع الخوف يحجب عني طريقك. آمين.\",\"x\":\"حين يكون الرب نورنا لا يبقى للخوف سلطان، فالنور يكشف الطريق. تدريب: ما الأمر الغامض في حياتك؟ اطلب نور الله عليه.\"},{\"t\":\"الروح القدس يعلمكم كل شيء\",\"ref\":\"يوحنا ١٤: ٢٦\",\"bk\":\"يوحنا\",\"v\":\"وأما المعزي، الروح القدس، الذي سيرسله الآب باسمي، فهو يعلمكم كل شيء، ويذكركم بكل ما قلته لكم.\",\"r\":\"«وأما المعزي الروح القدس الذي سيرسله الآب باسمي فهو يعلمكم كل شيء ويذكركم بكل ما قلته لكم». يعدني المسيح أن كلماته لن تضيع. فالروح القدس يذكّرني بها في الوقت المناسب. وكم مرة جاءتني آية في لحظة احتياج! هذا هو عمل الروح.\",\"p\":\"يا روح الله المعزي، علّمني كل شيء وذكّرني بكلمات المسيح. اجعل قلبي مخزنًا لكلمتك، وذكّرني بها في كل احتياج، وأرشدني بها. آمين.\",\"x\":\"التذكير عمل الروح. وهذا يشجعنا على أن نحفظ الكلمة في قلوبنا لتكون مادة لتذكير الروح. فإن لم يكن هناك شيء مخزون فماذا يذكّرني؟ ولذلك نحفظ المزامير والآيات. والروح لا يعلّم تعليمًا جديدًا مخالفًا بل يعمّق ما قاله المسيح. وهكذا تثبت الكنيسة في التقليد. ومن يحب الكلمة يجد الروح يعمل فيه. والتعليم هو علاقة مستمرة.\\nاحفظ اليوم آية قصيرة (مثل «الرب راعيّ فلا يعوزني شيء»)، وكررها حتى تثبت.\"},{\"t\":\"زيت السراج\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب أورسيسيوس القلب بسراج إن أهملنا الزيت انطفأ شيئًا فشيئًا وقويت عليه الظلمة. زيت النور هو الصلاة وحفظ القلب كل يوم. اكتب لنفسك اليوم عادة صغيرة تحفظ بها قلبك.\",\"p\":\"يا رب، املأ سراج قلبي بزيت نعمتك. علّمني أن أحفظ قلبي، فلا ينطفئ فيّ نورك. آمين.\",\"x\":\"الاستنارة تأتي بالصلاة والتواضع. تدريب: اطلب من الله أن يريك خطوة واحدة فقط، ولا تسأل عن الباقي.\",\"fq\":311}]},\"6-3\":{\"th\":\"الجسد المقدس\",\"m\":[{\"t\":\"من يسكن في مسكنك؟\",\"ref\":\"المزمور الرابع عشر — باكر\",\"v\":\"يا رب من يسكن في مسكنك. ومن يحل في جبل قدسك؟\",\"r\":\"يسأل المرنم من يستحق السكنى في بيت الله، فيجيب بالسلوك الذي لا عيب فيه والبر والحق في القلب. القداسة تشمل الجسد واللسان والقلب معًا. اختر اليوم عضوًا من جسدك تقدّسه لله، كعينك أو لسانك.\",\"p\":\"يا رب، قدّس جسدي وحواسي. اجعلني أسلك بلا عيب وأتكلم بالحق من قلبي، وأسكن في بيتك. آمين.\",\"x\":\"من يسكن في مسكنك؟ السالك بلا عيب والعامل بالحق. تدريب: اختر سلوكًا من الوصف وطبّقه اليوم.\"},{\"t\":\"هذه هي إرادة الله قداستكم\",\"ref\":\"تسالونيكي الأولى ٤: ٣–٤\",\"bk\":\"تسالونيكي الأولى\",\"v\":\"لأن هذه هي إرادة الله: قداستكم. أن تمتنعوا عن الزنا، أن يعرف كل واحد منكم أن يقتني إناءه بقداسة وكرامة،\",\"r\":\"«لأن هذه هي إرادة الله قداستكم: أن تمتنعوا عن الزنا. أن يعرف كل واحد منكم أن يقتني إناءه بقداسة وكرامة». القداسة ليست نظرية بل تشمل الجسد والعلاقات. والله يريد لي كرامة، لا يحرمني. فالقيم التي يطلبها تحفظني وتحفظ من أحب.\",\"p\":\"يا رب، قدّسني. احفظ جسدي وعيني وفكري في طهارة وكرامة، وأعطني أن أقتني إنائي بقداسة، لأعيش إرادتك في كل شيء. آمين.\",\"x\":\"الإناء قد يعني الجسد أو الزوجة، وفي الحالتين المقصود الكرامة والاحترام. والقداسة هنا ليست جفافًا بل حياة منسجمة مع الغاية التي خلقني الله لها. والعالم يروّج أن الحرية في تجاوز الحدود، لكن الكتاب يعلّم أن الحرية الحقيقية في القداسة. ومن اقتنى جسده بقداسة نال سلامًا. والله لم يدعنا للنجاسة بل للتقديس.\\nاحفظ اليوم عينيك وسمعك من محتوى يلوّث، وقدّم هذا الجهد لله كتقدمة قداسة.\"},{\"t\":\"ضمير نقي تجاه القريب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوسف إن من لا يقدر على كل الجهادات يكفيه أن يحفظ ضميره نقيًا تجاه قريبه. القداسة تظهر في تعاملنا مع الناس. راجع ضميرك اليوم تجاه شخص واحد، وصحح ما يحتاج تصحيحًا.\",\"p\":\"يا رب، طهّر ضميري من كل ما يؤذي أخًا لي. أعطني أن أرى قريبي بعينك، وأعامله بطهارة. آمين.\",\"x\":\"الجسد المقدس يتطلب قلبًا طاهرًا ومستعدًا. تدريب: استعد لقدوم القداس القادم بصلاة وتوبة.\",\"fq\":183}]},\"6-4\":{\"th\":\"زيارة المتألمين\",\"m\":[{\"t\":\"الرب سمع صوت بكائي\",\"ref\":\"المزمور السادس — باكر\",\"v\":\"لأن الرب قد سمع صوت بكائي. الرب سمع تضرعي، الرب لصلاتي قبل؛ فليخر وليضطرب جدا جميع أعدائي، وليرتدوا إلى ورائهم بالخزي سريعا جدا.\",\"r\":\"يعلن المرنم أن الرب سمع صوت بكائه وقبل صلاته. الله لا يهمل دمعة متألم، ونحن مدعوون أن نسمع معه. المتألمون حولنا يحتاجون من يجلس إلى جوارهم. اتصل اليوم بمريض أو حزين وأنصت إليه.\",\"p\":\"يا رب، اسمع صراخ كل متألم وعزّه. وأعطني قلبًا يرى المتألمين، ويدين تمتدان لراحتهم. آمين.\",\"x\":\"الرب سمع صوت بكائي، فالله لا يهمل دمعة. تدريب: زر اليوم مريضًا أو اتصل به، فقد يكون هو دمعة تنتظر.\"},{\"t\":\"كنت مريضًا فزرتموني\",\"ref\":\"متى ٢٥: ٣٦\",\"bk\":\"متى\",\"v\":\"عريانا فكسوتموني. مريضا فزرتموني. محبوسا فأتيتم إلي.\",\"r\":\"«كنت عريانًا فكسوتموني. مريضًا فزرتموني. محبوسًا فأتيتم إليّ». لم يقل المسيح «كنتم تعبدون في الهيكل» بل ركّز على الرحمة العملية. وعندما أزور مريضًا أو أخدم محتاجًا، أخدمه هو. وهذا يعطي قيمة لكل لفتة صغيرة.\",\"p\":\"يا رب، علّمني أن أراك في وجه كل مريض ومحتاج. افتح قلبي لزيارة المتألمين، وأعطني حنانًا وانتباهًا، لأخدمك فيهم بفرح. آمين.\",\"x\":\"لاحظ أن الذين خدموا لم يعرفوا أنهم يخدمون المسيح: «متى رأيناك مريضًا؟». فالخدمة الحقيقية عفوية ومنسية. والمسيح يتخفى في وجوه المحتاجين. وهذا يجعلنا ننتبه إلى كل شخص بعين مختلفة. وكلنا قادرون على زيارة أو مكالمة أو رسالة. والمهم ليس كثرة الكلام بل الحضور. فالمريض يحتاج أن يعلم أنه ليس وحيدًا.\\nاتصل اليوم بمريض أو متألم أو وحيد، واسأله عن أحواله بصدق، وأعرض عليه مساعدة محددة.\"},{\"t\":\"رأسه على ركبتي\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إنه إذا رأى أخًا ينعس أسند رأسه على ركبته ليريحه. هكذا تكون الخدمة: لمسة صغيرة تحمل راحة حقيقية. ابحث اليوم عن تعب قريب منك، وقدّم له راحة بسيطة.\",\"p\":\"يا رب، علّمني الرحمة العملية. أعطني أن أريح أخًا متعبًا، وأخدمك فيه. آمين.\",\"x\":\"زيارة المتألمين خدمة المسيح نفسه. تدريب: خصص وقتًا هذا الأسبوع لزيارة متألم.\",\"fq\":379}]},\"6-5\":{\"th\":\"المحبة الأولى\",\"m\":[{\"t\":\"واحدة سألت\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"واحدة سألت من الرب وإياها التمس. أن أسكن في بيت الرب كل أيام حياتي. لكي أنظر نعيم الرب، وأتفرس في هيكله المقدس.\",\"r\":\"أراد المرنم شيئًا واحدًا: أن يسكن في بيت الرب وينظر نعيمه. هذه هي المحبة الأولى، شوق يسبق كل طلب. عُد اليوم إلى لحظة أول فرح لك بالمسيح، وسله أن يجدد ذلك الاشتياق.\",\"p\":\"يا رب، أعد إليّ محبتي الأولى. اجعل أعظم شوق في قلبي أن أكون في بيتك وأنظر نعيمك. آمين.\",\"x\":\"أراد المرنم شيئًا واحدًا: أن يسكن في بيت الرب. فالأولوية الواحدة تبسط الحياة. تدريب: حدد أولويتك الأولى في هذا اليوم، وقدمها على الباقي.\"},{\"t\":\"غيرة خطوبتك\",\"ref\":\"إرميا ٢: ٢\",\"bk\":\"إرميا\",\"v\":\"«اذهب وناد في أذني أورشليم قائلا: هكذا قال الرب: قد ذكرت لك غيرة صباك، محبة خطبتك، ذهابك ورائي في البرية في أرض غير مزروعة.\",\"r\":\"«قد ذكرت لك غيرة صباك، محبة خطبتك، ذهابك ورائي في البرية». الله يتذكر بدايتي معه بحنين. كانت لي حرارة في البداية، فهل حافظت عليها؟ وهو لا يعاتب فقط بل يشتاق. وهذه دعوة للرجوع: أن أستعيد حب البدايات.\",\"p\":\"يا رب، أذكر محبتي الأولى لك. أعد إليّ حرارة البدايات وشوق الخطبة، ولا تدع محبتي تفتر. أنت تتذكر غيرة صباي فأرجع إليك. آمين.\",\"x\":\"البرية تعني الصعوبة وعدم الأمان، ومع ذلك كان الشعب يتبع. فالحب الأول يتبع بلا حساب. ثم فتر. والله يستعمل لغة الخطبة والزواج ليعبر عن اهتمامه. وقد تفتر محبتنا بالتعود. والعلاج ليس مجهودًا مضاعفًا بل رجوعًا بسيطًا: وقت هادئ مع الحبيب. وكل شيء يتجدد بالحب. وهو ينتظر برحمة.\\nاذكر لحظة في بداية علاقتك مع الله كانت فيها حرارة وفرح، واكتب ما كان يميزها، وحاول استعادة شيء منها اليوم.\"},{\"t\":\"محبة تخفف الجهاد\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينقل إفاغريوس عن أحد الآباء أن أشد أنواع الحياة هو الذي يقترن بالمحبة، فيصل صاحبه سريعًا إلى ميناء السلام. المحبة تجعل الجهاد خفيفًا. قدّم اليوم عملًا صغيرًا بدافع الحب لا الواجب.\",\"p\":\"يا رب، اجعل جهادي كله محبة. علّمني أن أعمل بدافع الحب لك وللناس. آمين.\",\"x\":\"المحبة الأولى لا تفتر إذا غذيناها بالصلاة. تدريب: ارجع إلى ما كنت تفعله في أيام حماسك الأولى مع الله.\",\"fq\":113}]},\"6-6\":{\"th\":\"كلمة تثمر\",\"m\":[{\"t\":\"في حفظها ثواب عظيم\",\"ref\":\"المزمور الثامن عشر — باكر\",\"v\":\"عبدك يحفظها. وفي حفظها ثواب عظيم.\",\"r\":\"كلمة الله لا تُحفظ في الذاكرة فقط، بل في الحياة. وعد الرب أنها لا ترجع فارغة بل تثمر. اقرأ اليوم آية واحدة وكرر قراءتها ثلاث مرات، ثم اسأل: ما الخطوة التي تطلبها مني؟\",\"p\":\"يا رب، ازرع كلمتك في قلبي فتثمر. أعطني أن أحفظها بالعمل، فأنال ثوابها الذي وعدت به. آمين.\",\"x\":\"في حفظ كلمة الله ثواب عظيم، لأن الحفظ يعني العمل. تدريب: اختر آية واحفظها اليوم وكررها في طريقك.\"},{\"t\":\"لا ترجع إليّ فارغة\",\"ref\":\"إشعياء ٥٥: ١٠–١١\",\"bk\":\"إشعياء\",\"v\":\"لأنه كما ينزل المطر والثلج من السماء ولا يرجعان إلى هناك، بل يرويان الأرض ويجعلانها تلد وتنبت وتعطي زرعا للزارع وخبزا للآكل، هكذا تكون كلمتي التي تخرج من فمي. لا ترجع إلي فارغة، بل تعمل ما سررت به وتنجح في ما أرسلتها له.\",\"r\":\"«هكذا تكون كلمتي التي تخرج من فمي: لا ترجع إليّ فارغة، بل تعمل ما سررت به وتنجح في ما أرسلتها له». ثقة جميلة: كلمة الله تعمل حتى لو لم أر. فأنا أزرع الكلمة في قلبي وفي قلوب غيري، وأثق أنها لا تضيع.\",\"p\":\"يا رب، أشكرك على كلمتك التي لا ترجع فارغة. ازرعها في قلبي وقلوب إخوتي، وأعطني صبرًا لانتظار ثمرها، وثقة بأنها تعمل ما سررت به. آمين.\",\"x\":\"المطر يختفي في الأرض، لكنه يعمل في الخفاء ثم يظهر النبات. وهكذا الكلمة. فقد أقرأ آية ولا أشعر بشيء، لكنها تعمل فيّ. وفي الخدمة قد أعلم ولا أرى نتيجة، لكن الكلمة تفعل. وهذا يعطي صبرًا وتواضعًا. فالمنتج ليس أنا بل الله. وعلينا أن نكون زارعين أمناء.\\nاقرأ اليوم آية وكررها دون أن تنتظر شعورًا، وثق أنها تعمل في الداخل كالمطر.\"},{\"t\":\"تأمل يثمر في الصلاة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب نيلوس إن كل ما تتأمل فيه صابرًا ستجني ثمره ساعة الصلاة. فالتأمل بذار، والصلاة موسم الحصاد. خصص اليوم عشر دقائق تتأمل فيها آية دون عجلة.\",\"p\":\"يا رب، علّمني الصبر في التأمل. اجعل كلمتك تتحول في قلبي صلاة ومحبة. آمين.\",\"x\":\"التأمل يحول الكلمة إلى حياة. تدريب: أعد قراءة آية بتمهل خمس مرات وسجل ما تفهمه.\",\"fq\":292}]},\"6-7\":{\"th\":\"معرفة الله\",\"m\":[{\"t\":\"عرّفتني سبل الحياة\",\"ref\":\"المزمور الخامس عشر — باكر\",\"v\":\"قد عرفتني سبل الحياة.\",\"r\":\"معرفة الله ليست معلومات بل طريق نسير فيه، وهو الذي يعرّفنا إياه. الاهتداء بنور وجهه يعطينا فرحًا لا تعطيه الأرض. اسأل الرب اليوم أن يكشف لك خطوة واحدة في سبيل الحياة.\",\"p\":\"يا رب، عرّفني سبل الحياة. اجعلني أعرفك أكثر كل يوم، وأسير معك بفرح. آمين.\",\"x\":\"عرفتني سبل الحياة: الله يُعرّف السبيل لمن يطلبه. تدريب: اطلب اليوم هداية في أمر محدد.\"},{\"t\":\"لنعرف لنتتبع لنعرف الرب\",\"ref\":\"هوشع ٦: ٣\",\"bk\":\"هوشع\",\"v\":\"لنعرف فلنتتبع لنعرف الرب. خروجه يقين كالفجر. يأتي إلينا كالمطر. كمطر متأخر يسقي الأرض.\",\"r\":\"«فلنعرف ولنتتبع لنعرف الرب. خروجه يقين كالفجر ويأتي إلينا كالمطر». معرفة الله ليست حدثًا بل مسيرة: نتتبع لنعرف. وهو يأتي كالفجر والمطر: بيقين ونعمة. وأنا أستطيع أن أعتمد على هذا اليقين، فهو آتٍ كل يوم كالفجر.\",\"p\":\"يا رب، دعني أعرف وأتتبع لأعرفك. خروجك يقين كالفجر، فأتّكل على مجيئك كالمطر. زد معرفتي بك كل يوم، وثبّتني في تتبعك. آمين.\",\"x\":\"التتبع يعني أن أستمر. فالمعرفة الحقيقية تتعمق بالمثابرة. وكل يوم أتتبع الله في الصلاة والقراءة والخدمة فأزداد معرفة. وهو يظهر بيقين، فأنا لا أبحث عن إله متقلب. والمطر المتأخر يسقي الأرض في آخر موسم النمو. وهكذا يأتي الله حتى في أواخر أوقاتنا. ولا يتأخر عنا. فلنتتبعه بشوق.\\nاستيقظ باكرًا غدًا قليلًا لتشهد الفجر وقل: «خروجك يقين كالفجر يا رب»، ثم صلِّ.\"},{\"t\":\"كلما اقتربنا رأينا ضعفنا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ماتوى إن الإنسان كلما دنا من الله رأى نفسه خاطئًا، وإشعياء لما رأى الله قال إنه دنس. المعرفة الحقيقية تقود إلى تواضع. قل لله اليوم بصدق: أنا أحتاجك.\",\"p\":\"يا رب، قرّبني إليك. وإذا رأيت ضعفي فاجعلني أرتمي في رحمتك لا في يأسي. آمين.\",\"x\":\"كن دون الجميع في عين نفسك. تدريب: اجلس في آخر الصف اليوم في موقف اجتماعي.\",\"fq\":269}]},\"6-8\":{\"th\":\"الأمان في الله\",\"m\":[{\"t\":\"الساكن في عون العلي\",\"ref\":\"المزمور ٩٠ (٩١) — السادسة\",\"v\":\"الساكن في عون العلي، يستريح في ظل إله السماء. يقول للرب أنت هو ناصري وملجأي، إلهي فأتكل عليه.\",\"r\":\"الأمان لا يقوم على قوتنا بل على من نسكن في ظله. يقول المرنم: أنت ناصري وملجأي. حين يشتد القلق اليوم، توقف وقل هذه العبارة بصوت منخفض ثلاث مرات.\",\"p\":\"يا رب، أنت ناصري وملجأي. أسكن في ظلك فلا أخاف، وأتكل عليك في كل أمر. آمين.\",\"x\":\"الساكن في عون العلي يبيت في ظل القدير، فالأمان في الإقامة مع الله. تدريب: اجعل بيتك اليوم مكان صلاة، ولو لدقائق.\"},{\"t\":\"أضطجع بسلام\",\"ref\":\"المزامير ٤: ٨\",\"bk\":\"المزامير\",\"v\":\"بسلامة أضطجع بل أيضا أنام، لأنك أنت يا رب منفردا في طمأنينة تسكنني.\",\"r\":\"«بسلام أضطجع وأيضًا أنام، لأنك أنت يا رب منفردًا في طمأنينة تسكنني». قالها داود ضمن مرحلة ضيق. لم تتغير الظروف، لكن تغير قلبه. فالنوم بسلام ثمرة الثقة. وأنا أحتاج أن أنهي يومي بتسليمه، فأنام بطمأنينة.\",\"p\":\"يا رب، بسلام أضطجع وأنام لأنك تسكنني في طمأنينة. أسلّم لك يومي بكل ما فيه، واحفظني في الليل، وأيقظني بنشاط وشكر. آمين.\",\"x\":\"المزمور ٤ هو مزمور مسائي. وفيه يطلب داود الاستجابة ويعلن فرحًا أكبر من فرح أصحاب الحصاد. وفي النهاية يقول عبارته الجميلة. والنوم نعمة. وقد نفقده بسبب القلق. فلنتدرب على صلاة مسائية بسيطة نسلم فيها يومنا. وفي الأجبية صلوات نوم تحفظنا. وهي تعلمنا أن نسلم أنفسنا بين يدي الله قبل النوم.\\nقبل أن تنام الليلة، سلّم لله ثلاث أمور من يومك، وقل: «بسلام أضطجع وأنام لأنك تسكنني بطمأنينة».\"},{\"t\":\"أنا والله فقط\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ألونيوس إن الإنسان إن لم يقل في قلبه: أنا والله فقط في العالم، لن يجد راحة. الراحة تبدأ حين أضع نفسي أمام الله وحده. خصص اليوم لحظة خلوة بلا مقارنات ولا انشغال بآراء الناس.\",\"p\":\"يا رب، أنت وحدك تكفيني. اجعلني أجد راحتي في حضورك، لا في رضا الناس. آمين.\",\"x\":\"الأمان يأتي من الثبات في الله. تدريب: اختر نقطة ارتكاز يومية مثل وقت ثابت للصلاة.\",\"fq\":72}]},\"6-9\":{\"th\":\"غنى المسيح\",\"m\":[{\"t\":\"يرفع المسكين\",\"ref\":\"المزمور ١١٢ (١١٣) — باكر\",\"v\":\"المقيم المسكين من التراب، الرافع البائس من المزبلة لكي يجلسه مع رؤساء شعبه.\",\"r\":\"غنى المسيح أنه افتقر لأجلنا، فلا نحتاج أن نكون أغنياء لنكون مقبولين عنده. هو يرفع البائس ويجلسه مع الرؤساء. اشكره اليوم على غنى لا يُشترى بمال، وفكّر فيما تملكه فعلًا.\",\"p\":\"يا رب، أشكرك لأنك رفعتني من التراب. علّمني أن أعيش غنى نعمتك وأشارك الآخرين. آمين.\",\"x\":\"المسيح افتقر لأجلنا لنغتني بفقره، فلا نقيس غنانا بما نملك. تدريب: اعطِ اليوم من حاجتك لا من فائضك، ولو قليلًا.\"},{\"t\":\"افتقر لأجلكم\",\"ref\":\"كورنثوس الثانية ٨: ٩\",\"bk\":\"كورنثوس الثانية\",\"v\":\"فإنكم تعرفون نعمة ربنا يسوع المسيح، أنه من أجلكم افتقر وهو غني، لكي تستغنوا أنتم بفقره.\",\"r\":\"«فإنكم تعرفون نعمة ربنا يسوع المسيح أنه من أجلكم افتقر وهو غني لكي تستغنوا أنتم بفقره». افتقر ليغنيني. هذه هي النعمة. وهي دافع لي أن أعطي بسخاء. فمن أخذ منه كل شيء يعطي بفرح.\",\"p\":\"يا رب يسوع، أنت افتقرت لأجلي لأستغني. أشكرك على نعمتك، واجعلني أعطي بسخاء وفرح، وأتشبه بك في بذل نفسي. آمين.\",\"x\":\"بولس يستخدم هذه الآية في حديثه عن جمع التبرعات للكنيسة الفقيرة. أي أن النعمة تُترجم إلى عطاء. والمسيح افتقر بالتجسد والصليب. وغنانا بالخلاص والبنوة والملكوت. فنحن «أغنياء» روحيًا. وهذا الغنى يصير سخاءً. وكل عطية نقدمها جزء من نعمته فينا. وهذا يحمينا من الشح.\\nاعط اليوم شيئًا بسخاء، ولو صغيرًا، وقل: «أنت افتقرت لأجلي فأعطي لأجلك».\"},{\"t\":\"ثمن البر الرخيص\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس إبيفانيوس إن الله يبيع البر رخيصًا لمن يبادرون إلى شرائه: بقطعة خبز، أو كأس ماء بارد، أو فلس واحد. الله يقبل القليل بقلب كبير. أعطِ اليوم شيئًا بسيطًا لمحتاج.\",\"p\":\"يا رب، علّمني أن أشتري البر بعطية صغيرة. اجعل قلبي سخيًا كما أنت سخي. آمين.\",\"x\":\"غنى المسيح الحقيقي يُرى في عطائه. تدريب: ابحث اليوم عن شخص يحتاج إلى ما عندك.\",\"fq\":102}]},\"6-10\":{\"th\":\"صورة الله في الإنسان\",\"m\":[{\"t\":\"بالمجد والكرامة توجته\",\"ref\":\"المزمور الثامن — باكر\",\"v\":\"أنقصته قليلا عن الملائكة. بالمجد والكرامة توجته، وعلى أعمال يديك أقمته.\",\"r\":\"خلق الله الإنسان على صورته وكلّله بالمجد والكرامة. قيمتك ليست فيما تملك بل فيمن خلقك. تعامل اليوم مع نفسك ومع كل إنسان تقابله كصورة لله.\",\"p\":\"يا رب، توّجتني بالمجد والكرامة بنعمتك. اجعلني أحترم نفسي وإخوتي، وأرى فيهم مجدك. آمين.\",\"x\":\"توجه الله بالمجد والكرامة، فقيمة الإنسان من صورة الله فيه. تدريب: عامل اليوم نفسك والآخرين بكرامة، فلا تحتقر أحدًا.\"},{\"t\":\"على صورة الله خلقه\",\"ref\":\"التكوين ١: ٢٧\",\"bk\":\"التكوين\",\"v\":\"فخلق الله الإنسان على صورته. على صورة الله خلقه. ذكرا وأنثى خلقهم.\",\"r\":\"«فخلق الله الإنسان على صورته، على صورة الله خلقه، ذكرًا وأنثى خلقهم». كل إنسان أقابله يحمل صورة الله. وهذا يغير نظرتي: لا أحتقر ولا أستخف بأحد. وأنا أيضًا حامل لهذه الصورة، وأحتاج أن أحفظها نقية.\",\"p\":\"يا خالقي، أشكرك لأنك خلقتني على صورتك. علّمني أن أحترم كل إنسان كحامل صورتك، وأحفظ صورتي نقية، وأتجدد بالمسيح الصورة الكاملة. آمين.\",\"x\":\"الصورة تعني قدرة على المحبة والتفكير والحرية والعلاقة. وقد شوّهتها الخطية، لكن المسيح، الصورة الكاملة، يرمّمها فينا. فكل إنسان له قيمة لا تُقاس. وهذا أساس كرامة الفقير والمريض والصغير والمسن. وعندما نحترم الآخرين نحترم صورة الله. وفي المعمودية استُعيدت صورتنا. ومن ثم نحيا كأبناء. فلنعامل كل شخص باحترام واضح.\\nعامل اليوم كل شخص تقابله بنظرة احترام، وكأنك ترى فيه صورة الله، حتى من يصعب عليك.\"},{\"t\":\"صورتان\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: نحن وإخوتنا صورتان، فإذا انتبه الإنسان لنفسه ولامها وجد أخاه مكرّمًا في عينيه. احترام صورة الله في الغير يبدأ بتواضعنا. اختر اليوم شخصًا صعبًا وابحث عن شيء مكرَّم فيه.\",\"p\":\"يا رب، أعطني عينًا تكرّم إخوتي. حرّرني من النظر إلى نفسي صالحًا وإلى غيري شريرًا. آمين.\",\"x\":\"صورة الله فينا تدعونا للاحترام. تدريب: انظر إلى وجه شخص اليوم وابحث عن صورة الله فيه.\",\"fq\":423}]},\"6-11\":{\"th\":\"الثمر المطلوب\",\"m\":[{\"t\":\"طوبى للرجل\",\"ref\":\"المزمور الأول — باكر\",\"v\":\"طوبى للرجل الذي لم يسلك في مشورة المنافقين. وفي طريق الخطاة لم يقف. وفي مجلس المستهزئين لم يجلس.\",\"r\":\"يبدأ المزمور برفض ثلاث خطوات: مشورة المنافقين وطريق الخطاة ومجلس المستهزئين. الثمر يبدأ من اختيار الصحبة والطريق. افحص اليوم من يؤثر في أفكارك، وتخلَّ عن مشورة واحدة لا تبني.\",\"p\":\"يا رب، احفظني من مشورة الأشرار وطريقهم. اجعل لذتي في ناموسك، فأثمر في أوانه. آمين.\",\"x\":\"يبدأ المزمور برفض ثلاث خطوات تنحدر بالإنسان: المشورة والطريق والمجلس. تدريب: ابتعد اليوم عن مجلس يضعفك روحيًا.\"},{\"t\":\"مثمرين في كل عمل صالح\",\"ref\":\"كولوسي ١: ١٠\",\"bk\":\"كولوسي\",\"v\":\"لتسلكوا كما يحق للرب، في كل رضى، مثمرين في كل عمل صالح، ونامين في معرفة الله،\",\"r\":\"«لتسلكوا كما يحق للرب، في كل رضى، مثمرين في كل عمل صالح، ونامين في معرفة الله». الثمر ليس مجهودًا لإثبات نفسي، بل نتيجة معرفة تنمو. كلما عرفت الله أكثر، صار عملي الصالح أصدق وأهدأ.\",\"p\":\"يا رب، علّمني أن أسلك كما يحق لك، وأثمر في كل عمل صالح، وأنمو في معرفتك كل يوم. آمين.\",\"x\":\"بولس يربط ثلاثة أمور: السلوك اللائق بالرب، والثمر في العمل الصالح، والنمو في المعرفة. فالمعرفة هنا ليست معلومات فقط، بل علاقة تُغيّر الحياة. والثمر يأتي في كل عمل، لا في العبادة وحدها، بل في البيت والعمل والكلمة. وكل رضى يعني أن نطلب ما يرضيه لا ما يعجب الناس. وهذا يحمينا من الاستعراض ومن الإحباط معًا.\\nاختر اليوم عملًا صغيرًا في بيتك أو عملك وقدّمه كما للرب، بإتقان وبدون انتظار مدح.\"},{\"t\":\"الشجرة والرياح\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم ثيوذورا إن الشجرة إذا لم تتعرض للرياح والعواصف لا تأتي بثمر، وكذلك نحن. الضيقات تعمق جذورنا. انظر اليوم إلى ضيق صغير كفرصة لإثمار صبر ومحبة.\",\"p\":\"يا رب، ثبّت جذوري فيك وسط الرياح. حوّل ضيقاتي إلى ثمر يمجدك. آمين.\",\"x\":\"الثمر المطلوب في وقته، فالصبر شرط. تدريب: ثق أن الله يرى زرعك وانتظر.\",\"fq\":148}]},\"6-12\":{\"th\":\"فرح الرب قوتنا\",\"m\":[{\"t\":\"ليفرح جميع المتكلين\",\"ref\":\"المزمور الخامس — باكر\",\"v\":\"وليفرح جميع المتكلين عليك، إلى الأبد يسرون وتحل فيهم. ويفتخر بك كل الذين يحبون اسمك.\",\"r\":\"الفرح الحقيقي وعد للمتكلين على الرب، لا يتوقف على الظروف. فرح الرب قوتنا لأنه لا يُسلب. سجّل اليوم ثلاثة أسباب للفرح ولو كانت صغيرة، وقدّمها شكرًا لله.\",\"p\":\"يا رب، املأ قلبي فرحًا بك. اجعلني أفتخر باسمك وأتكل عليك في كل حال. آمين.\",\"x\":\"ليفرح جميع المتكلين على الرب، فالفرح وعد لا يتوقف على الظروف. تدريب: اذكر وعدًا من وعود الله وافرح به اليوم.\"},{\"t\":\"لا تحزنوا\",\"ref\":\"نحميا ٨: ١٠\",\"bk\":\"نحميا\",\"v\":\"فقال لهم: «اذهبوا كلوا السمين، واشربوا الحلو، وابعثوا أنصبة لمن لم يعد له، لأن اليوم إنما هو مقدس لسيدنا. ولا تحزنوا، لأن فرح الرب هو قوتكم».\",\"r\":\"«لا تحزنوا، لأن فرح الرب هو قوتكم». بكى الشعب حين سمعوا الشريعة، لكن القادة ردّوهم إلى الفرح. فالتوبة الحقيقية لا تتركني في الحزن، بل تفتح لي باب فرح الرب فيصير قوتي.\",\"p\":\"يا رب، حوّل حزني على خطاياي إلى فرح بغفرانك، واجعل فرحك قوتي في كل عمل. آمين.\",\"x\":\"في أيام نحميا اجتمع الشعب وسمعوا الشريعة فبكوا لشعورهم بالتقصير. فقال لهم نحميا وعزرا والاويون أن اليوم مقدس، وأمروهم أن يأكلوا ويشربوا ويرسلوا أنصبة للمحتاجين. فالفرح هنا ليس عاطفة عابرة، بل قوة تحمل العمل والبناء. وقد أمرهم أن يشاركوا الفقير، فالفرح الحقيقي يتسع للآخرين. وقوتنا ليست في حزننا على خطايانا بل في رحمة الله التي تقبلنا.\\nشارك اليوم أحدًا في فرحك، بكلمة أو هدية أو زيارة صغيرة.\"},{\"t\":\"شكر بدل الكبرياء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بطرس إنه لا ينبغي أن نتكبر حين يجري الرب أمرًا على أيدينا، بل نشكره لأنه أهّلنا. الفرح بالخدمة يكتمل بالشكر. إن نجح لك أمر اليوم فقل: يا رب هذا منك.\",\"p\":\"يا رب، أنت صاحب كل عمل صالح. حفظني من الكبرياء، وأعطني أن أنسب الفضل لك. آمين.\",\"x\":\"فرح الرب قوتنا في الضيق. تدريب: ابتسم لشخص تعبان اليوم.\",\"fq\":472}]},\"6-13\":{\"th\":\"سلام لمحبي الشريعة\",\"m\":[{\"t\":\"الرب يبارك شعبه بالسلام\",\"ref\":\"المزمور ٢٨ (٢٩) — الثالثة\",\"v\":\"الرب يعطى شعبه قوة، الرب يبارك شعبه بالسلام.\",\"r\":\"السلام هبة يعطيها الرب لشعبه مع القوة. سلام بلا قوة هش، وقوة بلا سلام قاسية. اطلب اليوم من الرب سلامًا لموقف يضايقك، وأسلمه له.\",\"p\":\"يا رب، أعطني قوتك وسلامك. بارك بيتي وكنيستك بالسلام الذي لا يُنزع. آمين.\",\"x\":\"الرب يبارك شعبه بالسلام، والسلام مع القوة. تدريب: اطلب اليوم سلامًا وقوة معًا لما تواجهه.\"},{\"t\":\"سلامة جزيلة\",\"ref\":\"المزامير ١١٩: ١٦٥\",\"bk\":\"المزامير\",\"v\":\"سلامة جزيلة لمحبي شريعتك، وليس لهم معثرة.\",\"r\":\"«سلامة جزيلة لمحبي شريعتك، وليس لهم معثرة». عندما أحب الوصية، لا أعود أراها قيدًا. وتصير مثل سياج يحميني من السقوط ويمنحني راحة. فأطلب اليوم أن أزداد حبًا لكلمته وصبرًا على العمل بها.\",\"p\":\"يا رب، علّمني أن أحب وصاياك. امنحني سلامة جزيلة، واحفظني من كل معثرة في طريقي. آمين.\",\"x\":\"المزمور ١١٩ كله مديح لكلمة الله، وفي هذه الآية ربط بين المحبة والسلام وعدم التعثر. فمن يحب الوصية يسير في النور فلا يتعثر. والمعثرة قد تكون خطية أو أحداثًا تُضعف الإيمان. لكن من تأصّل في الكلمة يقف ثابتًا. والمحبة لا الخوف هي التي تحفظ الوصية. وهذه المحبة تنمو بالقراءة والتأمل والعمل.\\nاحفظ اليوم آية واحدة قصيرة، وكررها في فترات اليوم لتصير ملجأً لك.\"},{\"t\":\"هدوء الليل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بولس إن هدوء الليل يكفينا إذا كان ذهننا صاحيًا. فسلام الليل يحتاج ذهنًا هادئًا. قبل أن تنام الليلة، سلّم لله مخاوف يومك واحدة واحدة.\",\"p\":\"يا رب، اجعل ذهني صاحيًا وقلبي مطمئنًا. أعطني ليلة هادئة في حضورك. آمين.\",\"x\":\"السلام لمحبي الشريعة لا يعثرهم شيء. تدريب: اختر أن تحب وصية اليوم بدل أن تتحملها.\",\"fq\":476}]},\"6-14\":{\"th\":\"هدوء القلب\",\"m\":[{\"t\":\"اشخصوا وانظروا\",\"ref\":\"المزمور ٤٥ (٤٦) — الثالثة\",\"v\":\"هلم فانظروا أعمال الرب، التي جعلها ايات على الأرض. الذي ينزع الحروب من أقاصي الأرض.\",\"r\":\"يدعونا المرنم أن ننظر أعمال الرب: ينزع الحروب من أقاصي الأرض. الهدوء ليس غياب الأحداث بل الثقة بمن يضبطها. اجلس اليوم خمس دقائق صامتًا، وتذكر ما صنعه الله معك.\",\"p\":\"يا رب، انزع الاضطراب من قلبي كما تنزع الحروب. علّمني أن أسكن وأعرف أنك أنت الله. آمين.\",\"x\":\"اشخصوا وانظروا أعمال الرب: ينزع الحروب ويكسر القسي، فهدوء القلب ثمرة النظر إلى الله. تدريب: توقف عن الجري ثلاث دقائق وانظر إلى عمل الله حولك.\"},{\"t\":\"السكوت والانتظار\",\"ref\":\"مراثي إرميا ٣: ٢٦\",\"bk\":\"مراثي إرميا\",\"v\":\"جيد أن ينتظر الإنسان ويتوقع بسكوت خلاص الرب.\",\"r\":\"«جيد أن ينتظر الإنسان ويتوقع بسكوت خلاص الرب». لا أحتاج أن أشرح لله ألف مرة أو أضغط عليه بسرعة. بل أنتظر هادئًا لأنني أثق أن خلاصه آتٍ في وقته.\",\"p\":\"يا رب، علّمني أن أنتظرك بسكوت وثقة، وأن أرى خلاصك في وقتك. ثبّت قلبي في رجائك. آمين.\",\"x\":\"إرميا كتب هذه الكلمات وسط خراب أورشليم، ومع ذلك ذكر أن مراحم الرب لا تزول وأنها جديدة كل صباح. فالانتظار الهادئ هو ثمرة الثقة. والصمت هنا ليس سلبية بل صلاة بلا كلام. والآباء يمدحون السكوت أمام الله لأنه يهدئ العواصف الداخلية. وانتظار الخلاص يعني أن الله يعمل حتى حين لا أرى.\\nخصص اليوم خمس دقائق صمت أمام الله، بلا طلبات، وقل في نهايتها: «انتظرتك يا رب».\"},{\"t\":\"محبة الصمت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إنك إذا كنت محبًا للصمت تجد راحة أينما حللت. الصمت مكان لقاء، لا هروب. اجعل في يومك دقائق قليلة صمت كامل قبل النوم أو بعد الصلاة.\",\"p\":\"يا رب، علّمني أن أحب السكوت معك. أعطني قلبًا هادئًا في كل مكان. آمين.\",\"x\":\"محبة الله تهدئ القلب القلق. تدريب: ردد: أحبك يا رب، كلما اضطربت.\",\"fq\":374}]},\"6-15\":{\"th\":\"انتظار الرب\",\"m\":[{\"t\":\"وأنت يا رب فإلى متى؟\",\"ref\":\"المزمور السادس — باكر\",\"v\":\"وأنت يا رب فإلي متى؟ عد ونج نفسي. وأحيني من أجل رحمتك.\",\"r\":\"يتساءل المرنم عن طول الانتظار، لكنه يطلب النجاة والإحياء من أجل الرحمة. الانتظار بيت الإيمان حين لا نرى الحل. اكتب الأمر الذي تنتظر فيه الله اليوم، وسلّمه له.\",\"p\":\"يا رب، عد ونجّ نفسي. أحيني من أجل رحمتك، وأعطني صبرًا أنتظرك به. آمين.\",\"x\":\"وأنت يا رب فإلى متى؟ سؤال المنتظر الذي يتعب، لكنه يطلب الإحياء. تدريب: اكتب انتظارًا طويلًا وسلمه اليوم لله.\"},{\"t\":\"الذين ينتظرون\",\"ref\":\"المزامير ٣٧: ٩\",\"bk\":\"المزامير\",\"v\":\"لأن عاملي الشر يقطعون، والذين ينتظرون الرب هم يرثون الأرض.\",\"r\":\"«الذين ينتظرون الرب هم يرثون الأرض». قد أرى الشر يتقدم أحيانًا فأتعب. لكن الله يعدني أن من ينتظره يرث، فأثبت في الانتظار وأعمل الخير. فأهدأ وأترك الأمور في يد الله العادل وأثبت في الخير.\",\"p\":\"يا رب، أنتظرك بثقة. احفظني من الغيرة والقلق، وثبّتني في عمل الخير حتى ترثني ملكوتك. آمين.\",\"x\":\"المزمور ٣٧ يعالج مشكلة قديمة: لماذا ينجح الأشرار؟ فيجيب داود بأن نجاحهم قصير، وأن الله يعتني بمنتظريه. والانتظار هنا ليس خمولًا، بل ثقة تصاحبها طاعة، فهو يقول أيضًا: «افعل الخير». والوراثة وعد بالأرض في العهد القديم، وبالملكوت في العهد الجديد. والمسيح قال: «طوبى للودعاء لأنهم يرثون الأرض». فالثقة بالله تمنحني ألا أتعجل أو أغار.\\nاليوم، اترك قلقك من نجاح من لا يستحق، وبدلًا منه اعمل عملًا صالحًا مخفيًا.\"},{\"t\":\"اليوم فقط\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب بيمن من تأتيه التجربة ألا يسأل كم ستدوم، بل أن يقول: اليوم. الصبر يعيش يومًا بيوم. قل لنفسك الآن: اليوم فقط أحتمل بنعمة الله.\",\"p\":\"يا رب، علّمني أن أعيش يومي. أعطني نعمة أحتمل بها اليوم، وتُبقي الغد في يدك. آمين.\",\"x\":\"الصبر على الانتظار ثمرة الإيمان. تدريب: لا تقرر بتسرع اليوم.\",\"fq\":404}]},\"6-16\":{\"th\":\"فرح القلب المستقر\",\"m\":[{\"t\":\"أسبح الرب المحسن إلي\",\"ref\":\"المزمور ١٢ (١٣) — باكر\",\"v\":\"أسبح الرب المحسن إلي، وأرتل لاسم الرب العلي.\",\"r\":\"يختم المرنم ضيقته بالتسبيح لأنه تذكر إحسان الله. القلب المستقر يتغذى بتذكر النعم. اختر اليوم نعمة صنعها الله معك ورتّل لها ترنيمة أو مزمورًا.\",\"p\":\"يا رب، أسبحك لأنك محسن إليّ. اجعل قلبي مستقرًا في ذكر نعمك، وفمي ممتلئًا بتسبيحك. آمين.\",\"x\":\"يختم المرنم ضيقته بالتسبيح لأنه تذكر إحسان الله. تدريب: قبل أن تشتكي اليوم، اذكر إحسانًا واحدًا لله.\"},{\"t\":\"بظل جناحيك\",\"ref\":\"المزامير ٦٣: ٧\",\"bk\":\"المزامير\",\"v\":\"لأنك كنت عونا لي، وبظل جناحيك أبتهج.\",\"r\":\"«لأنك كنت عونًا لي، وبظل جناحيك أبتهج». حتى في البرية الجافة يجد داود فرحًا. وأنا أيضًا حين أقف في ظل الله أجد راحة لا تعطيها الظروف. فأعود إلى هذه الصورة كلما شعرت بالتعب أو الوحدة اليوم.\",\"p\":\"يا رب، كنت عونًا لي دائمًا. أحميني بظل جناحيك، وأعطني أن أبتهج بك في كل برية أمر بها. آمين.\",\"x\":\"كتب داود هذا المزمور وهو في برية يهوذا، عطشان إلى الله. ومع ذلك يقول إنه يبتهج. فالفرح لا يتوقف على المكان بل على الحضور. وصورة الجناحين تذكّرنا بقول الرب: «كم مرة أردت أن أجمع أولادك كما تجمع الدجاجة فراخها تحت جناحيها». فالله حنون وقوي معًا. وفي ظله نحتمي من الحر والخوف.\\nعندما تواجه اليوم موقفًا ثقيلًا، قل في داخلك: «في ظل جناحيك أحتمي»، وتابع عملك بهدوء.\"},{\"t\":\"ملك على أهوائه\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوسف إنه ملك اليوم لأنه ملك على أهوائه. الفرح الحقيقي في سلطان النفس على نفسها بنعمة الله. اجعل لك اليوم هدفًا صغيرًا: ضبط هوى واحد.\",\"p\":\"يا رب، أعطني أن أملك على أهوائي بنعمتك. فيمتلئ قلبي فرحًا في طاعتك. آمين.\",\"x\":\"القلب المستقر يشبع بالله. تدريب: اختر أن تكتفي بما عندك اليوم.\",\"fq\":186}]},\"6-17\":{\"th\":\"التسبيح وسط الخسارة\",\"m\":[{\"t\":\"عظم الرب الصنيع معنا\",\"ref\":\"المزمور ١٢٥ (١٢٦) — الغروب\",\"v\":\"إذا ما رد الرب سبي صهيون صرنا فرحين. حينئذ امتلأ فمنا فرحا ولساننا تهليلا. حينئذ يقال في الأمم إن الرب قد عظم الصنيع معهم. عظم الرب الصنيع معنا فصرنا فرحين.\",\"r\":\"يتذكر المرنم رد السبي فيمتلئ فمه فرحًا. التسبيح يبدأ بالذاكرة حين لا نجد في الحاضر ما نشكر عليه. حين يخسر الإنسان شيئًا يتذكر ما صنعه الله قبلاً. اكتب اليوم ثلاث مرات أنقذك فيها الله.\",\"p\":\"يا رب، عظّمت الصنيع معنا فصرنا فرحين. ذكّرني بإحساناتك السابقة وسط كل خسارة. آمين.\",\"x\":\"رد الله سبي صهيون فامتلأ الفم فرحًا، فالتسبيح بعد التحرر. تدريب: سبح الله اليوم على حرية نلتها.\"},{\"t\":\"مع ذلك أبتهج\",\"ref\":\"حبقوق ٣: ١٧\",\"bk\":\"حبقوق\",\"v\":\"فمع أنه لا يزهر التين، ولا يكون حمل في الكروم. يكذب عمل الزيتونة، والحقول لا تصنع طعاما. ينقطع الغنم من الحظيرة، ولا بقر في المذاود،\",\"r\":\"«فمع أنه لا يزهر التين، ولا يكون حمل في الكروم... فإني أبتهج بالرب». تخيّل أن تخسر كل مصدر رزق ثم تسبّح! هذا إيمان لا يتعلق بالعطايا بل بالمعطي نفسه.\",\"p\":\"يا رب، حتى لو نقصت كل الأشياء، أنت قوتي وخلاصي. علّمني أن أبتهج بك في كل حال. آمين.\",\"x\":\"الآية ١٧ سلسلة من الخسارات: التين والكروم والزيتون والحقول والغنم والبقر. وكان ذلك يعني مجاعة شاملة. وجاء بعدها: «فإني أبتهج بالرب وأفرح بإله خلاصي. الرب السيد قوتي ويجعل قدمي كالأيائل». فالله يمنح خفة وثباتًا في الجبال. والفرح هنا قرار إيمان لا شعور. وهذه الكلمات تعلّمنا أن نقول «مع ذلك» في وجه كل شكوى.\\nفي موقف خسارة أو نقص اليوم، قل بصوت هادئ: «مع ذلك أبتهج بالرب»، وكررها بإيمان.\"},{\"t\":\"لوم النفس يحمّل الشدائد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن الإنسان إذا لام نفسه صبر على الشدائد أينما كان. لوم النفس يخفف حدة الخسارة لأنه يرفع الاتهام عن الآخرين. بدلًا من لوم الظروف، قل: يا رب ماذا تريد أن أتعلم؟\",\"p\":\"يا رب، علّمني أن أقبل الشدة بروح التواضع. حوّل كل خسارة إلى درس يقربني إليك. آمين.\",\"x\":\"التسبيح وسط الخسارة قمة الإيمان. تدريب: قل شكرًا في موقف خسارة صغير.\",\"fq\":382}]},\"6-18\":{\"th\":\"خير الله وثباتنا\",\"m\":[{\"t\":\"ذوقوا وانظروا\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"ذوقوا وانظروا ما أطيب الرب! طوبى للإنسان المتكل عليه.\",\"r\":\"يدعونا المرنم إلى اختبار صلاح الله لا الاكتفاء بالسماع. وطوبى لمن يتكل عليه. اختبر صلاح الله اليوم: اطلب منه شيئًا وانتبه لكيفية استجابته.\",\"p\":\"يا رب، ما أطيبك! أعطني أن أتذوق صلاحك كل يوم، وأتكل عليك في كل أمر. آمين.\",\"x\":\"ذوقوا وانظروا ما أطيب الرب، فالمعرفة بالاختبار. تدريب: جرّب اليوم وصية جديدة وانظر ثمرها.\"},{\"t\":\"بضيقات كثيرة\",\"ref\":\"أعمال الرسل ١٤: ٢٢\",\"bk\":\"أعمال الرسل\",\"v\":\"يشددان أنفس التلاميذ ويعظانهم أن يثبتوا في الإيمان، وأنه بضيقات كثيرة ينبغي أن ندخل ملكوت الله.\",\"r\":\"«بضيقات كثيرة ينبغي أن ندخل ملكوت الله». الإنجيل لا يعدني بحياة بلا ألم، بل بحضور الله في الألم. والتشجيع الحقيقي هو أن أعرف الطريق وأثبت. فأقبل الضيق بصبر لأنه جزء من الطريق الذي مشاه المسيح قبلي.\",\"p\":\"يا رب، ثبّتني في الإيمان في كل ضيق، وشدد نفوس إخوتي. وأدخلنا بنعمتك إلى ملكوتك. آمين.\",\"x\":\"قال الرسولان هذا بعد أن رُجم بولس في لسترة وخرج حيًا، ومع ذلك عاد إلى المدن نفسها ليشدد الكنائس. فالضيقة لم توقف الخدمة بل ثبّتتها. وعبارة «ينبغي» تعني أنها جزء من الطريق لا استثناء. والآباء يرون في الألم تنقية للإيمان. والمسيح نفسه قال: «في العالم سيكون لكم ضيق، لكن ثقوا أنا قد غلبت العالم».\\nشجّع اليوم شخصًا يمر بضيق، برسالة قصيرة أو اتصال، وذكّره بأن الله معه.\"},{\"t\":\"علامة الراهب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن علامة الراهب تظهر في التجارب. وكلنا نُعرف في ساعة الضيق لا الرخاء. حين تأتيك مشكلة اليوم اجعلها فرصة لتظهر ثبات إيمانك.\",\"p\":\"يا رب، ثبتني في التجارب. اجعل ضيقاتي تظهر إيماني لا ضعفي. آمين.\",\"x\":\"الثبات في الخير يمتحن بالأيام. تدريب: كرر فضيلة صغيرة اليوم ولا تتوقف.\",\"fq\":317}]},\"6-19\":{\"th\":\"الثبات في الرب\",\"m\":[{\"t\":\"إلهنا ملجأنا وقوتنا\",\"ref\":\"المزمور ٤٥ (٤٦) — الثالثة\",\"v\":\"إلهنا ملجأنا وقوتنا، ومعيننا في شدائدنا التي أصابتنا جدا. لذلك لا نخشى إذا تزعزعت الأرض، وانقلبت الجبال إلى قلب البحار.\",\"r\":\"يقول المرنم لا نخشى حتى لو تزعزعت الأرض. الثبات ليس غياب الاهتزاز بل وجود الملجأ. حين تضطرب اليوم أمام خبر أو موقف، كرر: إلهنا ملجأنا وقوتنا.\",\"p\":\"يا رب، أنت ملجأي وقوتي. ثبتني حين تهتز الأرض، ولا تدعني أخاف. آمين.\",\"x\":\"إلهنا ملجأنا وقوتنا، فلا نخشى حتى لو تزعزعت الأرض. تدريب: عند أول اضطراب اليوم قل: إلهنا ملجأنا.\"},{\"t\":\"اسهروا واثبتوا\",\"ref\":\"كورنثوس الأولى ١٦: ١٣\",\"bk\":\"كورنثوس الأولى\",\"v\":\"اسهروا. اثبتوا في الإيمان. كونوا رجالا. تقووا.\",\"r\":\"«اسهروا. اثبتوا في الإيمان. كونوا رجالًا. تقووا». وصايا مختصرة كجنود على الحراسة. أحتاج أن أكون يقظًا في أفكاري، وثابتًا في إيماني، وشجاعًا في الشهادة. فأختار اليوم أن أكون واعيًا في كلماتي وقراراتي وصلواتي.\",\"p\":\"يا رب، علّمني أن أسهر وأثبت في الإيمان، وأكون شجاعًا وقويًا بنعمتك، وفي كل شيء بمحبة. آمين.\",\"x\":\"بولس يختم رسالته الأولى لكورنثوس، وبعد معالجة الانقسامات والأخطاء يعطي هذه الوصايا الأربع. فالسهر ضد الغفلة، والثبات ضد التذبذب، والرجولة بمعنى النضج والشجاعة، والتقوّي بالنعمة لا بالعضلات. ثم يضيف: «لتصر كل أموركم في محبة». فكل قوة بلا محبة تفسد. والكنيسة تقدم لنا الأصوام والسهرانيات والتسبحة لنتدرب على السهر والثبات.\\nاختر اليوم وصية واحدة من الأربع وعشها بوعي، وسجّل كيف ساعدتك.\"},{\"t\":\"الطوب المطبوخ\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب أورسيسيوس الإنسان غير المنصهر بمخافة الله بطوب غير مطبوخ يتداعى سريعًا، أما المطبوخ فيصمد كالحجر. الثبات ينمو بالمخافة والاختبار. اطلب اليوم أن يطبخ الله فيك فضيلة واحدة بنار الصبر.\",\"p\":\"يا رب، اجعلني ثابتًا كالحجر في مخافتك. لا تدع أول ريح تهدمني. آمين.\",\"x\":\"الثبات ليس غياب الاضطراب بل الاستقرار فيه. تدريب: حافظ على هدوئك في موقف يستفزك.\",\"fq\":310}]},\"6-20\":{\"th\":\"تسبيح الفرح\",\"m\":[{\"t\":\"سبحوا الرب\",\"ref\":\"المزمور ١١٢ (١١٣) — باكر\",\"v\":\"سبحوا الرب أيها الفتيان، سبحوا اسم الرب. ليكن اسم الرب مباركا من الآن وإلى الأبد. من مشارق الشمس إلى مغاربها باركوا اسم الرب.\",\"r\":\"تبدأ التسبحة بدعوة الفتيان أن يسبحوا اسم الرب من مشارق الشمس إلى مغاربها. فرح التسبيح لا يعرف عمرًا ولا ساعة. رتّل اليوم ترنيمة بفرح، ولو في مكان بعيد عن الناس.\",\"p\":\"يا رب، ليكن اسمك مباركًا من الآن وإلى الأبد. اجعل التسبيح فرح قلبي في كل حين. آمين.\",\"x\":\"تبدأ التسبحة بدعوة الفتيان أن يسبحوا اسم الرب من مشارق الشمس إلى مغاربها. تدريب: سبح الله اليوم بصوت مرتفع في سيارتك أو بيتك.\"},{\"t\":\"أفرح وأبتهج بك\",\"ref\":\"المزامير ٩: ٢\",\"bk\":\"المزامير\",\"v\":\"أفرح وأبتهج بك. أرنم لاسمك أيها العلي.\",\"r\":\"«أفرح وأبتهج بك. أرنم لاسمك أيها العلي». الفرح هنا موجّه إلى الله نفسه. وحين أركز على من هو، لا على ما عندي، تتسع نفسي وتنفتح للترنيم. فأشاركه الآن بكل قلبي، وأتذكر ما صنعه معي أمس.\",\"p\":\"يا رب، أحمدك بكل قلبي وأحدث بعجائبك. أفرح وأبتهج بك، وأرنم لاسمك العلي كل أيام حياتي. آمين.\",\"x\":\"قبل هذه الآية يقول داود: «أحمد الرب بكل قلبي، أحدث بجميع عجائبك». فالحمد يبدأ بكل القلب، والتحديث بالعجائب يعني أن أروي ما صنعه الله. ثم يتحول الحمد إلى فرح وابتهاج وترنم. وهذا تدرج روحي: الحمد، ثم التحدّث، ثم الفرح، ثم الترنيم. والتسبحة اليومية في الكنيسة تعلّمنا هذا الترتيب.\\nاذكر اليوم عجيبة واحدة صنعها الله معك لأحد أفراد أسرتك أو صديق، واروها بفرح.\"},{\"t\":\"ألا نفتر في التراتيل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ثيوذورس إننا إذا حوسبنا على كسلنا في الصلاة وفتورنا في التراتيل لا نخلص. الله يريد حرارة لا مجرد شكل. صلِّ اليوم صلاة قصيرة بكامل انتباهك.\",\"p\":\"يا رب، أبعد عني الفتور. أعطني حرارة الروح في صلاتي وتسبيحي. آمين.\",\"x\":\"فرح التسبيح يجدد الإنسان. تدريب: اختر ترنيمة وردّدها بفرح.\",\"fq\":141}]},\"6-21\":{\"th\":\"التواضع والنعمة\",\"m\":[{\"t\":\"الناظر إلى المتواضعين\",\"ref\":\"المزمور ١١٢ (١١٣) — باكر\",\"v\":\"الساكن في الأعالي، الناظر إلى المتواضعين في السماء وعلى الأرض.\",\"r\":\"الرب عالٍ ومع ذلك ينظر إلى المتواضعين. التواضع ليس إنكار المواهب بل معرفة أن كل شيء نعمة. اعمل اليوم خدمة صغيرة دون أن يراك أحد، ودع الله وحده ينظر إليك.\",\"p\":\"يا رب، انظر إلى اتضاعي وارفعني في وقتك. أعطني نعمة التواضع كل يوم. آمين.\",\"x\":\"الرب عال وينظر إلى المتواضعين، فالتواضع جاذب لنظرة الله. تدريب: اتضع اليوم أمام شخص بسيط واخدمه.\"},{\"t\":\"يعطي نعمة أعظم\",\"ref\":\"يعقوب ٤: ٦\",\"bk\":\"يعقوب\",\"v\":\"ولكنه يعطي نعمة أعظم. لذلك يقول: «يقاوم الله المستكبرين، وأما المتواضعون فيعطيهم نعمة».\",\"r\":\"«يقاوم الله المستكبرين، وأما المتواضعون فيعطيهم نعمة». أحيانًا أتعب لأنني أحاول أن أثبت نفسي، بينما النعمة تنتظر قلبًا فارغًا من الكبرياء. حين أنحني أمام الله أجد يده ممدودة لتسندني.\",\"p\":\"يا رب، انزع من قلبي كل كبرياء، وعلّمني أن أقف أمامك متواضعًا لأنال نعمتك التي تسند ضعفي وتقودني. آمين.\",\"x\":\"يعقوب يتحدث عن الصراعات والأهواء التي تفسد العلاقات، ثم يضع هذا المبدأ الحاسم: الله لا يقاوم الضعيف بل المستكبر. والمتواضع ليس من يحتقر نفسه، بل من يعرف مكانه أمام الله ويقبل أن يحتاج إلى غيره. والنعمة هنا عطية مجانية لا تُشترى بالاستحقاق. ولهذا كان الآباء يقولون إن التواضع أساس كل فضيلة، لأن النعمة لا تسكن في قلب ممتلئ بذاته.\\nاعترف اليوم بكلمة تواضع واحدة أمام شخص كنت تتجنب الاعتذار له.\"},{\"t\":\"التواضع الأصيل\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم ثيوذورا إنه لا النسك ولا السهر ولا أي وجع يخلّص الإنسان سوى التواضع الأصيل. التواضع هو الباب الذي تدخل منه النعمة. اطلب اليوم أن يعلّمك الله التواضع في موقف محدد.\",\"p\":\"يا رب، علّمني التواضع الأصيل. لا تدع جهادي يتحول إلى كبرياء. آمين.\",\"x\":\"النعمة تسكن القلب المتضع. تدريب: لا ترد على نقد بكبرياء.\",\"fq\":149}]},\"6-22\":{\"th\":\"رحمة الآب\",\"m\":[{\"t\":\"اذكر رأفاتك\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"اذكر يا رب رأفاتك ومراحمك. لأنها ثابتة منذ الأزل.\",\"r\":\"يطلب المرنم أن يذكر الله رأفاته ومراحمه الثابتة منذ الأزل. رحمة الله قديمة قدم الدهور ولا تتغير بتغيّر حالنا. ارفع اليوم صلاة طلب رحمة لنفسك ولمن أخطأوا إليك.\",\"p\":\"يا رب، اذكر رأفاتك ومراحمك. كن رحيمًا كما أنت رحيم، وعلّمني أن أرحم غيري. آمين.\",\"x\":\"اذكر رأفاتك ومراحمك التي منذ الأزل، فرحمة الله أقدم من خطايانا. تدريب: اقرأ المزمور وردد: اذكر رأفاتك، واثق في رحمة الله.\"},{\"t\":\"كونوا رحماء\",\"ref\":\"لوقا ٦: ٣٦\",\"bk\":\"لوقا\",\"v\":\"فكونوا رحماء كما أن أباكم أيضا رحيم.\",\"r\":\"«كونوا رحماء كما أن أباكم أيضًا رحيم». الرحمة ليست عاطفة عابرة بل تشبّه بالله. وكلما رأيت كم احتملني، صار الصفح عن غيري أسهل على قلبي. وهكذا أصير صورة صغيرة لأبي السماوي في بيتي وعملي.\",\"p\":\"يا أبانا الرحيم، اجعلني رحيمًا كما أنت رحيم. علّمني الإحسان بلا انتظار، ونقِّ قلبي من الانتقام. آمين.\",\"x\":\"قبل هذه الآية يطلب الرب أن نحب أعداءنا ونحسن ونقرض ونحن لا نرجو شيئًا، فيكون أجرنا عظيمًا ونكون بني العلي، لأنه منعم على غير الشاكرين والأشرار. فالرحمة تصل إلى من لا يستحق. وبعدها يقول الرب: لا تدينوا فلا تدانوا، اغفروا يُغفر لكم. فالرحمة تفتح باب الرحمة. وهذا لا يعني ألا نقول الحق، بل أن نقوله بقلب لا يشتهي الانتقام.\\nقدّم اليوم إحسانًا لشخص لا ينتظر منه جزاءً، وانظر كيف يتحرك قلبك.\"},{\"t\":\"الرحيم يسكب مخافته\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أورسيسيوس إن الله الرحيم يسكب مخافته في من يغلبه الكسل قليلًا، فيقوّيه ليصحو. الرحمة تقيمنا لا تتركنا. إن تعثرت اليوم فلا تيأس، بل قم بسرعة.\",\"p\":\"يا رب، أيقظني من كسلي برحمتك. قوّني لأسهر وأحفظ نفسي حتى مجيئك. آمين.\",\"x\":\"الرحمة تسبق الدينونة. تدريب: ارحم شخصًا اليوم بدل أن تحكم عليه.\",\"fq\":312}]},\"6-23\":{\"th\":\"محبة بلا رياء\",\"m\":[{\"t\":\"الشفاه الغاشة\",\"ref\":\"المزمور الحادي عشر — باكر\",\"v\":\"يستأصل الرب جميع الشفاه الغاشة، واللسان الناطق بالعظائم.\",\"r\":\"يعلن المرنم أن الرب يستأصل الشفاه الغاشة واللسان الناطق بالعظائم. المحبة بلا رياء كلام يطابق القلب. اختر اليوم أن تقول لشخص كلمة صادقة ومشجعة، لا مجاملة.\",\"p\":\"يا رب، احفظ لساني من الغش. اجعل كلامي صادقًا ومحبتي بلا رياء. آمين.\",\"x\":\"يستأصل الرب الشفاه الغاشة، فالصدق صفة إلهية. تدريب: امتنع عن مجاملة كاذبة اليوم.\"},{\"t\":\"وادين بالمحبة\",\"ref\":\"رومية ١٢: ١٠\",\"bk\":\"رومية\",\"v\":\"وادين بعضكم بعضا بالمحبة الأخوية، مقدمين بعضكم بعضا في الكرامة.\",\"r\":\"«وادّين بعضكم بعضًا بالمحبة الأخوية، مقدمين بعضكم بعضًا في الكرامة». التكريم يعني أن أعطي لأخي مكانًا قبل نفسي. وهذا يتطلب قلبًا هادئًا لا يخاف على صورته. فأتدرب اليوم على أن أسبق غيري بالتحية والتقدير.\",\"p\":\"يا رب، علّمني محبة بلا رياء، وأن أقدم إخوتي في الكرامة، وأجد فرحي في خدمتهم. آمين.\",\"x\":\"قبل الآية يقول بولس: «المحبة فلتكن بلا رياء. كونوا كارهين الشر، ملتصقين بالخير». فالمحبة الحقيقية ليست مجاملة بل صدق، وهي تكره الشر في الوقت نفسه الذي تحب فيه الإنسان. والمحبة الأخوية دفء في العلاقة، والتكريم احترام عملي. ونعمة الله تجعلنا نتسابق في خدمة بعضنا بدل أن نتسابق على المراكز. وهذا ما تُظهره الكنيسة في الخدمة الجماعية.\\nمدح اليوم شخصًا بكلمة صادقة أمام الآخرين، وامنحه فرصة ليظهر.\"},{\"t\":\"أعطي القريب ما يحتاجه\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إننا سنعطي القريب ما هو بحاجة إليه، حتى لو كان ذلك لإرضاء الناس. المحبة العملية تقدم الحاجة قبل الحسابات. اسأل اليوم أحد المقربين: ماذا تحتاج؟\",\"p\":\"يا رب، علّمني المحبة التي تعطي. حرّرني من الحسابات الصغيرة التي تعطل رحمتي. آمين.\",\"x\":\"أعطِ بلا رياء، فالرياء يفسد العطاء. تدريب: اعطِ اليوم في الخفاء.\",\"fq\":349}]},\"6-24\":{\"th\":\"الغفران\",\"m\":[{\"t\":\"غفرت ذنب شعبك\",\"ref\":\"المزمور ٨٤ (٨٥) — السادسة\",\"v\":\"حللت كل رجزك. رجعت عن سخط غضبك.\",\"r\":\"يتذكر المرنم أن الله أزال غضبه وسكن سخطه. الغفران الإلهي أساس غفراننا لبعضنا. فكر اليوم في شخص أخطأ إليك، وصلِّ من أجله بالاسم.\",\"p\":\"يا رب، كما غفرت لي أعطني أن أغفر. انزع المرارة من قلبي واملأه سلامك. آمين.\",\"x\":\"غفرت ذنب شعبك وسترت خطاياهم: الغفران الإلهي أساس الرجاء. تدريب: اطلب الغفران وامنحه لشخص واحد اليوم.\"},{\"t\":\"متسامحين كما سامحكم الله\",\"ref\":\"أفسس ٤: ٣٢\",\"bk\":\"أفسس\",\"v\":\"وكونوا لطفاء بعضكم نحو بعض، شفوقين متسامحين كما سامحكم الله أيضا في المسيح.\",\"r\":\"«كونوا لطفاء بعضكم نحو بعض، شفوقين، متسامحين كما سامحكم الله أيضًا في المسيح». عندما يصعب عليّ أن أسامح أتذكر كم سامحني الله. فمن غُفر له كثيرًا يقدر أن يغفر.\",\"p\":\"يا رب، سامحني كما أسامح، وانزع من قلبي كل مرارة، واجعلني لطيفًا شفوقًا متسامحًا كما سامحتني في المسيح. آمين.\",\"x\":\"الآية تنتهي بعبارة «في المسيح»، أي أن الغفران ليس مبادرة منا بل انعكاس لما فعله الله في الصليب. وقبلها يوصي بولس: لا تحزنوا روح الله القدوس، وانزعوا المرارة والسخط. فالمرارة تسكن القلب وتؤذي صاحبها أكثر من غيره. والتسامح ليس نسيانًا مفتعلًا، بل قرار بألا أحمل الجرح إلى الأبد. وهو يبدأ بالصلاة من أجل من أخطأ إليّ.\\nصلِّ اليوم بالاسم من أجل شخص أحزنك، واطلب له بركة حقيقية.\"},{\"t\":\"سبعين مرة سبع مرات\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إنه إذا كان الله قد طلب من الإنسان أن يغفر لأخيه، فهو بالأحرى يفعل ذلك. فغفراننا صدى لغفرانه. اكتب اليوم اسم من تريد أن تسامحه وصلِّ له.\",\"p\":\"يا رب، أعطني قلبًا غافرًا. علّمني أن أغفر مهما تكرر الإساءة. آمين.\",\"x\":\"سبعين مرة سبع مرات، الغفران بلا حد. تدريب: اغفر لشخص كرر إساءته.\",\"fq\":375}]},\"6-25\":{\"th\":\"الأمانة في القليل\",\"m\":[{\"t\":\"لا يتزعزع إلى الأبد\",\"ref\":\"المزمور الرابع عشر — باكر\",\"v\":\"الذي يحلف لقريبه ولا يغدر به. ولا يعطى فضته بالربا، ولا يقبل الرشوة على الأبرياء. الذي يصنع هذا لا يتزعزع إلى الأبد.\",\"r\":\"يصف المرنم الأمين: الذي يحلف لقريبه ولا يغدر، ولا يأخذ الرشوة. الأمانة في القليل تُظهر من نحن. حافظ اليوم على موعد أو وعد صغير مهما كلّفك.\",\"p\":\"يا رب، اجعلني أمينًا في الصغير. احفظ كلمتي ووعودي، ولا تدعني أتزعزع. آمين.\",\"x\":\"الأمين لا يتزعزع إلى الأبد، فالأمانة في الصغير ثبات في الكبير. تدريب: التزم اليوم بوعد صغير.\"},{\"t\":\"أمينًا في القليل\",\"ref\":\"لوقا ١٩: ١٧\",\"bk\":\"لوقا\",\"v\":\"فقال له: نعما أيها العبد الصالح! لأنك كنت أمينا في القليل، فليكن لك سلطان على عشر مدن.\",\"r\":\"«نعمًا أيها العبد الصالح! لأنك كنت أمينًا في القليل، فليكن لك سلطان على عشر مدن». الأمانة في الأمور الصغيرة هي التي تُعدّني لما هو أكبر. فلا أحتقر عملًا صغيرًا ما دام لله.\",\"p\":\"يا رب، اجعلني أمينًا في القليل حتى تستأمنني على الكثير. لا أطلب سلطانًا بل أن أخدمك بإخلاص. آمين.\",\"x\":\"قال الرب هذا المثل وهو قريب من أورشليم، حين ظنوا أن ملكوت الله يظهر حالًا. والرجل النبيل أعطى عبيده عشرة أمناء وقال: «تاجروا حتى أجيء». فأحدهم ربح عشرة والثاني خمسة. وما يلفت أن العبد الثاني ربح أقل لكنه نال مكافأة مناسبة. فالله لا يقارن بيننا بل يقيّم أمانة كل منا. وكل لحظة فيها فرصة للربح الروحي.\\nاستخدم اليوم عشر دقائق من وقتك لخدمة أو صلاة أو زيارة، ولا تؤجلها إلى فرصة أفضل.\"},{\"t\":\"ضعف الخير\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إنك إذا صنعت قليلًا من الخير مع أخيك الصالح، فاجعل ضعفه للآخر لأنه المريض. الأمانة تهتم بالأضعف. أحسن اليوم إلى من يصعب الإحسان إليه.\",\"p\":\"يا رب، علّمني الأمانة في المحبة. اجعلني أسبق لمن يحتاج. آمين.\",\"x\":\"الأمانة في القليل تكسب الكثير. تدريب: أعد شيئًا استعرته.\",\"fq\":366}]},\"6-26\":{\"th\":\"محبة تستر\",\"m\":[{\"t\":\"اغفر لي خطيتي\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"من أجل اسمك يا رب اغفر لي خطيتي لأنها كثيرة.\",\"r\":\"يصلي المرنم: من أجل اسمك اغفر لي خطيتي لأنها كثيرة. من يعرف مقدار ما غُفر له يستر على غيره. حين تسمع اليوم عن عثرة أخ، لا تنشرها بل صلِّ له.\",\"p\":\"يا رب، اغفر لي خطيتي واستر عليّ. علّمني أن أستر على إخوتي بمحبة. آمين.\",\"x\":\"يصلي المرنم من أجل اسم الله أن يغفر خطيته لأنها كثيرة. من يعرف خطيته يقترب. تدريب: اعترف لله بخطية متكررة بصدق.\"},{\"t\":\"طالب المحبة\",\"ref\":\"الأمثال ١٧: ٩\",\"bk\":\"الأمثال\",\"v\":\"من يستر معصية يطلب المحبة، ومن يكرر أمرا يفرق بين الأصدقاء.\",\"r\":\"«من يستر معصية يطلب المحبة، ومن يكرر أمرًا يفرق بين الأصدقاء». كل كلمة أعيدها عن عيب أحد قد تهدم علاقة. وبصمتي المحب أبني ما يهدمه الكلام. فأحفظ سر أخي وأطلب له الخير في صلاتي أمام الله.\",\"p\":\"يا رب، احفظ لساني من تكرار الأخطاء وتفريق الأصدقاء. علّمني أن أطلب المحبة وأستر بدل أن أنشر. آمين.\",\"x\":\"الآية تفرّق بين من يستر ومن يكرر. الستر لا يعني التستر على الشر الذي يؤذي الناس، بل عدم نشر الأخطاء الشخصية وتحويلها إلى حكاية. وهناك واجب أن نصحح بمحبة، كما في متى ١٨: «اذهب وعاتبه بينك وبينه وحدكما». فالكلام الأول يكون مع صاحب الشأن لا مع الآخرين. وهكذا تُحفظ الصداقة والكرامة معًا.\\nتجنب اليوم أي حديث يتناول عيب شخص غائب، وحوّل الحديث إلى موضوع بنّاء.\"},{\"t\":\"الله يكتم سقطاتنا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إننا في اللحظة التي نكتم فيها سقطة أخينا يكتم الله سقطاتنا. الستر استثمار في رحمة الله. قاوم اليوم رغبة الحديث عن خطأ آخر.\",\"p\":\"يا رب، استر علينا وعلى إخوتنا. احفظ لساني من كشف عيوب الآخرين. آمين.\",\"x\":\"الله يكتم خطايا من يتوب. تدريب: لا تفضح خطأ أخيك اليوم.\",\"fq\":361}]},\"6-27\":{\"th\":\"كلمة في وقتها\",\"m\":[{\"t\":\"فاض قلبي بكلام صالح\",\"ref\":\"المزمور ٤٤ (٤٥) — الثالثة\",\"v\":\"فاض قلبي بكلام صالح. إني أخبر الملك بأفعالي، لساني قلم كاتب ماهر.\",\"r\":\"من فيض القلب يتكلم اللسان، وهو قلم كاتب ماهر في يد الله. الكلمة المناسبة في وقتها ثمر الصلاة. قبل أن تتكلم اليوم في موقف حساس، اطلب من الله أن يعطيك الكلمة.\",\"p\":\"يا رب، املأ قلبي بكلام صالح. واجعل لساني قلم كاتب ماهر يشهد لك. آمين.\",\"x\":\"من فيض القلب يتكلم اللسان، فالكلمة الصالحة تحتاج قلبًا ممتلئًا بالخير. تدريب: املأ قلبك اليوم بآية قبل أن تتكلم.\"},{\"t\":\"فرح بجواب الفم\",\"ref\":\"الأمثال ١٥: ٢٣\",\"bk\":\"الأمثال\",\"v\":\"للإنسان فرح بجواب فمه، والكلمة في وقتها ما أحسنها!\",\"r\":\"«للإنسان فرح بجواب فمه، والكلمة في وقتها ما أحسنها!». ليست كل كلمة صحيحة تُقال في أي وقت. فحين أنتظر اللحظة المناسبة وأصلي قبل أن أتكلم، تصير كلماتي بلسمًا.\",\"p\":\"يا رب، ضع على فمي حارسًا، وعلّمني الكلمة في وقتها لأكون بركة لكل من يسمعني اليوم. آمين.\",\"x\":\"الحكمة هنا لا تتعلق بكثرة الكلام بل بتوقيته ونبرته. فقد يؤذي القول الحق إن جاء متعجلًا، وقد يشفي إذا قيل في وقته. والآباء ينصحون بأن نفكر قبل أن نتكلم، وأن نسأل: هل هذه الكلمة نافعة؟ هل هي محبة؟ هل هذا وقتها؟ والمسيح كان يتكلم مع كل شخص بما يناسب حاله: مع السامرية عن الماء، ومع نيقوديموس عن الولادة الجديدة.\\nقبل أي حوار صعب اليوم، توقف ثلاث ثوانٍ وصلِّ في قلبك: «يا رب أعطني الكلمة في وقتها».\"},{\"t\":\"الصمت والكلام\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن هناك من يتكلم من الصباح للمساء لكنه صامت لأنه لا يتكلم إلا بنفع، وهناك من يصمت وقلبه يدين كثيرين. الكلام المفيد صمت حقيقي. اختر اليوم أن تتكلم بكلمة نافعة واحدة.\",\"p\":\"يا رب، علّمني متى أتكلم ومتى أصمت. ولتكن كلماتي نافعة وقلبي نقيًا. آمين.\",\"x\":\"الكلمة في وقتها تبني. تدريب: قل كلمة تشجيع في وقت مناسب.\",\"fq\":327}]},\"6-28\":{\"th\":\"مرساة الرجاء\",\"m\":[{\"t\":\"رجاء حصين\",\"ref\":\"المزمور ٦٠ (٦١) — السادسة\",\"v\":\"وبرجا حصينا في وجه العدو. فأسكن في مسكنك إلى الدهر، وأستظل بستر جناحيك.\",\"r\":\"يرى المرنم في الله رجاءه وبرجه الحصين في وجه العدو، ويسكن في مسكنه ويستظل بجناحيه. الرجاء مرساة للنفس وسط العواصف. اكتب اليوم عبارة رجاء تحملها في قلبك.\",\"p\":\"يا رب، أنت رجائي وبرجي الحصين. ثبّتني تحت ستر جناحيك، ولا تدعني أيأس. آمين.\",\"x\":\"رجاء حصين وبرج قوة في وجه العدو، فالله يحمي من يلتجئ إليه. تدريب: اختر اليوم الله ملجأً في ما يخيفك.\"},{\"t\":\"إله الرجاء\",\"ref\":\"رومية ١٥: ١٣\",\"bk\":\"رومية\",\"v\":\"وليملأكم إله الرجاء كل سرور وسلام في الإيمان، لتزدادوا في الرجاء بقوة الروح القدس.\",\"r\":\"«وليملأكم إله الرجاء كل سرور وسلام في الإيمان، لتزدادوا في الرجاء بقوة الروح القدس». الرجاء ليس تفاؤلًا بل عطية. وحين أمتلئ من الروح القدس يصير الأمل في داخلي حيًا وإن ضاقت الظروف.\",\"p\":\"يا إله الرجاء، املأني سرورًا وسلامًا في الإيمان، وأفِض فيَّ الرجاء بقوة روحك القدوس كل يوم. آمين.\",\"x\":\"يختم بولس هذا الجزء من رسالة رومية بصلاة تجمع الرجاء والفرح والسلام والإيمان والروح القدس. فالله هو «إله الرجاء»، أي مصدره وصاحبه. والامتلاء يأتي «في الإيمان»، فلا ينفصل عن الثقة. والنتيجة أن يفيض الرجاء، أي أن نشارك الآخرين رجاءنا. احمل اليوم صلاة قصيرة لشخص يشعر باليأس، وقل له كلمة رجاء حقيقية. \\n\"},{\"t\":\"إن كان لك قلب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بمفو: إذا كان لك قلب يمكنك أن تخلص. القلب الحي هو أول الخلاص. اطلب اليوم قلبًا يحس ويصلي ويرجو.\",\"p\":\"يا رب، أعطني قلبًا حيًا. لا تدع اليأس يقسّيه، واجعل رجائي فيك ثابتًا. آمين.\",\"x\":\"إن كان لك صديق فاحفظه بالمحبة. تدريب: اتصل بصديق قديم.\",\"fq\":462}]},\"6-29\":{\"th\":\"تعزية الله\",\"m\":[{\"t\":\"يستجيب لك الرب\",\"ref\":\"المزمور ١٩ (٢٠) — الثالثة\",\"v\":\"يستجيب لك الرب في يوم شدتك. ينصرك اسم إله يعقوب. يرسل لك عونا من قدسه.\",\"r\":\"يعد المزمور بالاستجابة في يوم الضيق وبعون من القدس. التعزية ليست غياب الضيق بل حضور المعين. اذكر اليوم ضيقة تمر بها، وقل: يا رب أرسل لي عونًا.\",\"p\":\"يا رب، استجب لي في يوم شدتي. أرسل لي عونًا من قدسك وعزّني بروحك. آمين.\",\"x\":\"يستجيب لك الرب في يوم الضيق ويرسل عونًا من القدس. تدريب: ثق أن الله يسمع في وقت ضيقك.\"},{\"t\":\"تكثر تعزيتنا\",\"ref\":\"كورنثوس الثانية ١: ٥\",\"bk\":\"كورنثوس الثانية\",\"v\":\"لأنه كما تكثر آلام المسيح فينا، كذلك بالمسيح تكثر تعزيتنا أيضا.\",\"r\":\"«كما تكثر آلام المسيح فينا، كذلك بالمسيح تكثر تعزيتنا أيضًا». لا يعدني الله بغياب الألم، بل بتعزية تفوقه. وكلما اشتد الحمل، اشتد حضوره بجواري. فأقبل عزاءه اليوم وأشارك به من يحتاج إليه حولي.\",\"p\":\"يا إله كل تعزية، عزّني في ضيقي، واجعلني أعزي غيري بنفس التعزية التي تعزيت بها منك. آمين.\",\"x\":\"بولس يفتتح رسالته الثانية إلى كورنثوس بالتسبيح لإله كل تعزية، الذي يعزينا في كل ضيقتنا لكي نستطيع أن نعزي الذين هم في كل ضيقة. فالتعزية التي نأخذها ليست لنا وحدنا بل لننقلها. وآلام المسيح فينا تشير إلى الألم الذي نتحمله بسبب الإيمان أو في سبيل الخدمة. وهذا ألم له معنى. والعزاء ليس فكرة بل شخص: المسيح الذي يرافقنا.\\nاتصل اليوم بشخص مر بضيق مشابه لما مررت به، وكن له سندًا.\"},{\"t\":\"الصلاة دواء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب نيلوس إن الصلاة دواء للفتور والأحزان. حين يثقل الحزن لا نصمت بل نصلي. صلِّ اليوم صلاة قصيرة حين يغلبك الحزن.\",\"p\":\"يا رب، اجعل صلاتي دوائي في الحزن والفتور. أعطني تعزيتك في كل ضيق. آمين.\",\"x\":\"الصلاة تعزي المتألم. تدريب: اطلب أن تكون معزيًا لأحد اليوم.\",\"fq\":290}]},\"6-30\":{\"th\":\"الصبر من أجل الآخرين\",\"m\":[{\"t\":\"اللهم التفت إلى معونتي\",\"ref\":\"المزمور التاسع والستون — باكر\",\"v\":\"اللهم التفت إلى معونتي. يا رب أسرع وأعنى.\",\"r\":\"صلاة قصيرة تصلح للطريق كله: التفت إلى معونتي، أسرع وأعنّي. الصبر على الآخرين يحتاج معونة من فوق. حين يضايقك أحد اليوم، قل هذه الصلاة قبل أي رد فعل.\",\"p\":\"اللهم التفت إلى معونتي، يا رب أسرع وأعنّي. اجعلني صبورًا على إخوتي، رحيمًا في الرد. آمين.\",\"x\":\"التفت إلى معونتي، أسرع وأعني: صلاة قصيرة تصلح لكل الطريق. تدريب: ردد هذه الصلاة اليوم مرات.\"},{\"t\":\"مثال الأنبياء في الصبر\",\"ref\":\"يعقوب ٥: ١٠\",\"bk\":\"يعقوب\",\"v\":\"خذوا يا إخوتي مثالا لاحتمال المشقات والأناة: الأنبياء الذين تكلموا باسم الرب.\",\"r\":\"«خذوا يا إخوتي مثالًا لاحتمال المشقات والأناة الأنبياء الذين تكلموا باسم الرب». الصبر ليس ضعفًا بل طريق سار فيه الأنبياء قبلي. وإذا نظرت إلى عاقبة أيوب رأيت أن الرب رحيم ورؤوف، فأتشجع.\",\"p\":\"يا رب، اجعلني صابرًا كأيوب، واكشف لي عاقبتك الصالحة. فأنت رحيم ورؤوف في كل طرقك. آمين.\",\"x\":\"يعقوب يقدم الأنبياء مثالًا للصبر في احتمال المشقات، ثم في الآية التالية يقول: «ها نحن نطوّب الصابرين»، ويذكر أيوب الذي فقد كل شيء ولم يترك الله. وفي النهاية رأى الرب يرد له ضعف ما كان. لكن الأهم هو ما تعلمه عن الله: أنه كثير الرحمة ورؤوف. فالصبر ليس فضيلة صامتة بل شهادة لأمانة الله. وكل واحد منا يمر بامتحان صبر، ومن خلاله يعرف الله أكثر.\\nاكتب اليوم قصة أيوب في ثلاثة أسطر، وسل نفسك: ماذا أتعلم عن الله من صبره؟\"},{\"t\":\"ألا تحزن أخاك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: اترك فكرك يجري، ألا يكفي ألا تحزن أخاك؟ أقل الواجب ألا نجرح أحدًا. اختر اليوم أن تتجنب كلمة جارحة واحدة.\",\"p\":\"يا رب، أعطني حكمة الصبر. احفظني من إحزان أي أخ، وعلّمني المحبة الطويلة. آمين.\",\"x\":\"الصبر من أجل الآخرين محبة عملية. تدريب: احتمل ثقل أخ اليوم بلا شكوى.\",\"fq\":440}]},\"7-1\":{\"th\":\"نداء اتبعني\",\"m\":[{\"t\":\"سهّل طريقنا يا رب\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"يا رب سهل طريقنا. مبارك الآتي باسم الرب.\",\"r\":\"دعوة «اتبعني» تبدأ بخطوة صغيرة وتحتاج إلى طريق يسهّله الله. نتبع المسيح لأنه الآتي باسم الرب وهو الذي يسبقنا. اسأله اليوم أن يريك خطوة واحدة تتبعه فيها.\",\"p\":\"يا رب، سهّل طريقنا. أعطني أن أسمع ندائك وأتبعك بقلب مستعد، فأنت مبارك الآتي باسم الرب. آمين.\",\"x\":\"عبارة «مبارك الآتي باسم الرب» هتفت بها الجموع عند دخول المسيح أورشليم، وتصليها الكنيسة في كل قداس. من يتبع المسيح يتبع من سبقه إلى الطريق. تدريب: اسأل نفسك أين يسبقك المسيح اليوم، وتبعه في خطوة واحدة محددة.\"},{\"t\":\"اتبعني\",\"ref\":\"يوحنا ١: ٤٣\",\"bk\":\"يوحنا\",\"v\":\"في الغد أراد يسوع أن يخرج إلى الجليل، فوجد فيلبس فقال له: «اتبعني».\",\"r\":\"«وجد فيلبس فقال له: اتبعني». لاحظ أن المسيح هو الذي وجد، لا فيلبس. الله يبحث عني قبل أن أبحث عنه، وكلمته لي بسيطة وواضحة: اتبعني. وعلي أن أجيب بخطوة عملية اليوم لا بمجرد شعور.\",\"p\":\"يا رب يسوع، أشكرك لأنك وجدتني ودعوتني. أعطني قلبًا يسمع صوتك ويجيبك بخطوة طاعة صادقة اليوم. آمين.\",\"x\":\"في اليوم التالي لدعوة التلاميذ الأولين، قرر يسوع أن يمضي إلى الجليل، فوجد فيلبس. ولم يشرح له خطة طويلة، بل قال له كلمة واحدة. وفيلبس لم يحتفظ بالدعوة لنفسه، بل ذهب ووجد نثنائيل وقال له: تعال وانظر. فمن وجده المسيح يصير حاملًا للدعوة لغيره.  اسأل نفسك اليوم: ما هي الخطوة الصغيرة التي يطلبها مني المسيح الآن؟ ثم قم بها.\\n\"},{\"t\":\"المكان الذي يقيم فيه الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"طلب أحد الآباء أن يرى القديسين فلم يجد الأب أنطونيوس بينهم، فقيل له إنه في المكان الذي يقيم فيه الله. من يتبع المسيح يقيم حيث يقيم. اجعل اليوم قلبك مكانًا يقيم فيه الله بالصلاة.\",\"p\":\"يا رب، اجعلني أقيم حيث تقيم أنت. وأعطني أن أتبعك بصدق، وأمكث في حضورك. آمين.\",\"x\":\"رأى الأب أنطونيوس غائبًا عن جمع القديسين، لأنه كان في المكان الذي يقيم فيه الله. أي أن القداسة لا تُرى بل تُقاس بالقرب من الله. تدريب: ابحث اليوم عن مكانك الصغير الذي يقيم فيه الله، وكن فيه بكامل انتباهك.\",\"fq\":15}]},\"7-2\":{\"th\":\"الاتباع الأمين\",\"m\":[{\"t\":\"لا يمنع الخيرات\",\"ref\":\"المزمور ٨٣ (٨٤) — السادسة\",\"v\":\"الرب لا يمنع الخيرات عن السالكين بالدعة. يا رب إله القوات، طوبى للإنسان المتكل عليك.\",\"r\":\"الرب لا يمنع الخيرات عن السالكين بالدعة، وطوبى للمتكل عليه. الاتباع الأمين سير يومي دون التفات إلى الوراء. التزم اليوم بقرار واحد أجّلته، وتابع السير دون تردد.\",\"p\":\"يا رب إله القوات، طوبى للمتكل عليك. اجعلني أسلك بالدعة وأتبعك بأمانة، ولا ألتفت إلى الوراء. آمين.\",\"x\":\"الوعد أن الرب لا يمنع الخيرات عن السالكين بالدعة، أي الذين يمشون بكمال وبساطة بلا ازدواج. الخير هنا ليس رفاهية بل شركة مع الله. تدريب: انتبه اليوم لموضع ازدواج في سلوكك، وقدّمه لله ليوحّد قلبك.\"},{\"t\":\"لا ينظر إلى الوراء\",\"ref\":\"لوقا ٩: ٦٢\",\"bk\":\"لوقا\",\"v\":\"فقال له يسوع: «ليس أحد يضع يده على المحراث وينظر إلى الوراء يصلح لملكوت الله».\",\"r\":\"«ليس أحد يضع يده على المحراث وينظر إلى الوراء يصلح لملكوت الله». الحارث الذي يلتفت يعوّج خطّه. وأنا إذا ظللت أتأمل في أخطاء الماضي أو أمجاده، تعطلت خطواتي الجديدة مع الله.\",\"p\":\"يا رب، ثبّت عيني إلى الأمام نحوك. حررني من ثقل الماضي، وأعطني أن أتبعك بلا ارتداد ولا تأخير. آمين.\",\"x\":\"قيلت هذه العبارة لمن أراد أن يتبع المسيح لكنه طلب أولًا أن يودّع أهل بيته. والمسيح لا يمنع المحبة الأسرية، لكنه يكشف التردد والتأجيل. والمحراث صورة العمل الجاد الذي يحتاج تركيزًا. والنظر إلى الوراء قد يكون حنينًا إلى ما تركناه، أو ندمًا مرضيًا يشلنا. اليوم، اكتب أمرًا واحدًا من الماضي تحتاج أن تتركه، وأمرًا واحدًا جديدًا تبدأه. \\n\"},{\"t\":\"يكفيني أن أراك\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال أحد الآباء للأب أنطونيوس: يكفيني أن أراك يا أبت. الاتباع يبدأ بالوجود قرب من نحبه. اختر اليوم لحظة تجلس فيها في حضرة الله دون أن تطلب شيئًا.\",\"p\":\"يا رب، يكفيني أن أكون في حضرتك. علّمني أن أتبعك لأجل حبك لا لأجل عطاياك. آمين.\",\"x\":\"قال الزائر للأب أنطونيوس: يكفيني أن أراك. أحيانًا حضور شخص قدّيس يعلّم أكثر من كلامه. تدريب: اجلس اليوم مع شخص روحي بلا طلب، فقط لتتعلم من هدوئه، أو اجلس بصمت أمام الله.\",\"fq\":14}]},\"7-3\":{\"th\":\"حمل الصليب\",\"m\":[{\"t\":\"الرب قد ملك على خشبة\",\"ref\":\"المزمور ٩٥ (٩٦) — التاسعة\",\"v\":\"قولوا بين الأمم إن الرب قد ملك على خشبة؛ وأيضا ثبت المسكونة فلن تتزعزع.\",\"r\":\"تقول الكنيسة بين الأمم إن الرب ملك على خشبة، فالصليب عرشه. حمل الصليب يعني أن نقبل الألم بروح المسيح. اسأل نفسك اليوم: ما الصليب الصغير الذي أهرب منه؟ احمله بصلاة.\",\"p\":\"يا رب، يا من ملكت على خشبة، علّمني أن أحمل صليبي كل يوم بفرح، وأتبعك حتى النهاية. آمين.\",\"x\":\"عبارة «الرب قد ملك على خشبة» من ترجمة قديمة للمزمور ٩٥ تفسرها الكنيسة بالصليب، إذ صار الخشب عرشًا للمصلوب. فالألم الذي يحمله المسيح هو مجده. تدريب: انظر إلى صليب في بيتك أو على صدرك، وقل: ملكك على خشبة يا رب.\"},{\"t\":\"فلينكر نفسه\",\"ref\":\"مرقس ٨: ٣٤\",\"bk\":\"مرقس\",\"v\":\"ودعا الجمع مع تلاميذه وقال لهم: «من أراد أن يأتي ورائي فلينكر نفسه ويحمل صليبه ويتبعني.\",\"r\":\"«من أراد أن يأتي ورائي فلينكر نفسه ويحمل صليبه ويتبعني». الدعوة مفتوحة لمن يريد. ولا يجبرني أحد، لكن الطريق يمر بإنكار الأنا وبحمل صليب يومي أحبه لأنه يقودني إليه.\",\"p\":\"يا رب، علّمني أن أنكر ذاتي وأحمل صليبي كل يوم، وأتبعك بفرح الذي يعرف أن الصليب طريق القيامة. آمين.\",\"x\":\"قال الرب هذا بعد أن أعلن لتلاميذه عن آلامه وموته وقيامته، وبعد أن انتهره بطرس. فأوضح أن طريقه هو طريقهم. وإنكار النفس ليس كراهية للذات بل رفض لأنانيتها وتسلطها. والصليب هنا ليس ألمًا عشوائيًا، بل الطاعة والبذل من أجل الله والناس. وكل مؤمن له صليبه: صوم، مصالحة، صبر على مرض، خدمة في الخفاء. والرب نفسه يحمل معنا.\\nاختر اليوم صليبًا صغيرًا بإرادتك: امتناع عن شيء تحبه، أو خدمة لا ينتبه إليها أحد.\"},{\"t\":\"الخطيئة أمام العينين\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أنطونيوس إن قوة الإنسان الكبرى أن يضع خطيئته نصب عينيه أمام الله وينتظر التجربة حتى النسمة الأخيرة. حمل الصليب يبدأ بصدق مع النفس. اعترف اليوم بضعف واحد أمام الله.\",\"p\":\"يا رب، اكشف لي ضعفي بلطف، وقوّني أن أحمل صليبي بتواضع حتى آخر نسمة. آمين.\",\"x\":\"يرى الأب أنطونيوس القوة الكبرى في وضع الخطية أمام الله دائمًا وانتظار التجربة حتى النسمة الأخيرة. فالقوة لا تعني ألا نسقط بل ألا ننسى. تدريب: اذكر اليوم ضعفك الأكبر أمام الله بصدق، وقل: أعني.\",\"fq\":403}]},\"7-4\":{\"th\":\"الخدمة كمثال\",\"m\":[{\"t\":\"انظر إلي وارحمني\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"انظر إلي وارحمني. أعط عزة لعبدك. وخلص ابن أمتك.\",\"r\":\"يصلي المرنم: انظر إلي وارحمني، أعط عزة لعبدك. الخادم الحقيقي يطلب قوة من الله قبل أن يعطي غيره. قبل أن تخدم اليوم، قل له: أعطني ما أقدمه لهم.\",\"p\":\"يا رب، انظر إلي وارحمني. أعطني عزة لأخدم إخوتي، وعلّمني أن أكون خادمًا كما فعلت أنت. آمين.\",\"x\":\"يطلب المرنم أن ينظر الله إليه ويعطيه عزة، فالخادم يستمد قوته من نظرة الله لا من مهارته. تدريب: قبل أن تخدم أحدًا اليوم، ارفع عينيك لله وقل: أنظر إليّ وأعطني قوة.\"},{\"t\":\"أعطيتكم مثالًا\",\"ref\":\"يوحنا ١٣: ١٥\",\"bk\":\"يوحنا\",\"v\":\"لأني أعطيتكم مثالا، حتى كما صنعت أنا بكم تصنعون أنتم أيضا.\",\"r\":\"«أعطيتكم مثالًا، حتى كما صنعت أنا بكم تصنعون أنتم أيضًا». المسيح لا يكتفي بالتعليم، بل يفعل أمامنا. غسل أرجل تلاميذه، ومنهم من سينكره ومن سيسلمه. وأنا أُدعى أن أخدم بلا تمييز.\",\"p\":\"يا رب، علّمني أن أخدم كما خدمت أنت. اجعلني متواضعًا أنحني لإخوتي بلا تمييز ولا انتظار شكر. آمين.\",\"x\":\"في العشاء الأخير قام الرب عن العشاء وخلع ثيابه واتزر بمنشفة وغسل أرجل تلاميذه، عمل العبيد. ولم يستثنِ يهوذا. وعندما اعترض بطرس، أوضح أن هذا العمل رمز للتطهير وللمحبة. ثم أعطاهم المثال. فالخدمة التي لا تنحني لا تشبه المسيح. وفي الكنيسة نمارس هذا في خميس العهد بغسل الأرجل، تذكيرًا بأن المحبة الحقيقية تتجسد في عمل متواضع.\\nقم اليوم بعمل خدمة بسيطة لا يتوقعها أحد: ترتيب مكان، مساعدة، أو غسل أطباق لمن تعب.\"},{\"t\":\"الإحسان ولو لإرضاء الناس\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سارة إنه يحسن بالبشر أن يتصدقوا ولو كان السبب إرضاء الناس، لأن الإحسان يحقق إرضاء الله. الخدمة تعلّمنا حتى حين تكون النية ناقصة. قدّم اليوم عطاءً بسيطًا لمحتاج.\",\"p\":\"يا رب، طهّر نيّتي في العطاء والخدمة. وارحمني حين أعطي بغير محبة كاملة، وعلّمني أن أعطي لك. آمين.\",\"x\":\"تقول الأم سارة إنه يحسن بالناس أن يتصدقوا حتى لو كان الدافع إرضاء الناس، لأن الإحسان يرضي الله. نظرة واقعية: العطاء يطهّر الدافع مع الوقت. تدريب: اعطِ اليوم دون أن تنتظر أن تكون نيتك كاملة، وصلِّ أن يصفّيها الله.\",\"fq\":530}]},\"7-5\":{\"th\":\"مواهب الروح\",\"m\":[{\"t\":\"عظيمة هي أعمال الرب\",\"ref\":\"المزمور ١١٠ (١١١) — التاسعة\",\"v\":\"عظيمة هي أعمال الرب، ومشيئاته كلها مفحوصة: جلال وبهاء عمله؛ وعدله دائم إلى أبد الأبد. صنع ذكرا لجميع عجائبه.\",\"r\":\"يتأمل المرنم في أعمال الرب وعجائبه فيعترف بجلالها. المواهب التي فينا من أعماله هو، وهي لخدمة الجميع. اذكر اليوم موهبة وهبك الله إياها، واستخدمها في عمل صغير لإخوتك.\",\"p\":\"يا رب، عظيمة هي أعمالك. شكرًا على مواهبي، وعلّمني أن أستخدمها لمجدك ولخدمة إخوتي. آمين.\",\"x\":\"يصف المزمور أعمال الله بأنها جلال وبهاء، ويدعو إلى حفظ ذكرى عجائبه. أعظم المواهب أن نذكر. تدريب: اكتب ثلاث عجائب صنعها الله في حياتك، وعلقها حيث تراها.\"},{\"t\":\"ليتمجد الله في كل شيء\",\"ref\":\"بطرس الأولى ٤: ١١\",\"bk\":\"بطرس الأولى\",\"v\":\"إن كان يتكلم أحد فكأقوال الله. وإن كان يخدم أحد فكأنه من قوة يمنحها الله، لكي يتمجد الله في كل شيء بيسوع المسيح، الذي له المجد والسلطان إلى أبد الآبدين. آمين.\",\"r\":\"«إن كان يتكلم أحد فكأقوال الله. وإن كان يخدم أحد فكأنه من قوة يمنحها الله، لكي يتمجد الله في كل شيء». موهبتي ليست ملكي، بل أمانة. والقوة التي أخدم بها هي من الله، فلا أفتخر بل أشكر.\",\"p\":\"يا رب، اجعل كل كلمة وكل خدمة مني لمجد اسمك. أعطني قوتك، ولا تدعني أنسب شيئًا لنفسي. آمين.\",\"x\":\"بطرس يختم حديثه عن المواهب بهدف واضح: مجد الله. فلا أتكلم لأجذب الأنظار، ولا أخدم لأصنع اسمًا. ومن يتكلم يفعل ذلك كمن ينقل كلام الله، أي بأمانة لا بتحريف. ومن يخدم يتكل على قوة تعطى له، لا على طاقته. وهذا يحرر من الكبرياء ومن الإحباط معًا. فإذا نجحت أشكر، وإذا ضعفت أستند. والتمجيد يكون بيسوع المسيح، فهو الوسيط في كل عطية.\\nاليوم بعد أي عمل ناجح تقوم به، قل في قلبك: «المجد لك يا رب».\"},{\"t\":\"قليل من كل الفضائل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب بيمن الإنسان الذي يبني بيتًا بمن يجمع طاقات كثيرة، فنحن علينا أن نأخذ قليلًا من كل الفضائل. المواهب تنمو بالتكامل. اختر اليوم فضيلة لم تمارسها واعمل فيها خطوة صغيرة.\",\"p\":\"يا رب، ابنِ فيّ بنيانًا كاملًا. أعطني من كل فضيلة نصيبًا، وبارك مواهبي. آمين.\",\"x\":\"يشبّه الأب بيمن الإنسان الباني بيته بمن يجمع طاقات كثيرة، وكذلك نحن ننال قليلًا من كل الفضائل. فلا نكتفي بفضيلة واحدة. تدريب: اختر فضيلة لا تهتم بها عادة، وجرّب أن تعيشها اليوم ولو قليلًا.\",\"fq\":407}]},\"7-6\":{\"th\":\"الحصاد الكثير\",\"m\":[{\"t\":\"أرضنا تعطي ثمرها\",\"ref\":\"المزمور ٨٤ (٨٥) — السادسة\",\"v\":\"والبر من السماء تطلع. لأن الرب يعطى الخيرات، وأرضنا تعطى ثمرها.\",\"r\":\"الرب يعطي الخيرات والأرض تعطي ثمرها. الحصاد وعد من الله لا أمر نصنعه وحدنا. افحص اليوم ما زرعته من صلاة أو خدمة، وابتهج بالثمر الذي يعدك الله به.\",\"p\":\"يا رب، أنت تعطي الخيرات وأرضنا تعطي ثمرها. ابعث فعلة إلى حصادك وأعطني أن أكون واحدًا منهم. آمين.\",\"x\":\"يقول المزمور إن الرب يعطي الخيرات والأرض تعطي ثمرها، فالنمو شراكة بين عطية السماء وتعب الأرض. تدريب: اسأل: ما الذي زرعته من صلاة وخدمة ولم أر ثمره؟ واترك الحصاد لله.\"},{\"t\":\"تحنن عليهم\",\"ref\":\"متى ٩: ٣٦\",\"bk\":\"متى\",\"v\":\"ولما رأى الجموع تحنن عليهم، إذ كانوا منزعجين ومنطرحين كغنم لا راعي لها.\",\"r\":\"«ولما رأى الجموع تحنن عليهم». النظر ينتج الحنان، والحنان ينتج الخدمة. أحيانًا لا أخدم لأنني لا أنظر حقًا إلى من حولي. فأطلب من المسيح أن يعطيني عينيه وقلبه.\",\"p\":\"يا رب، افتح عيني لأرى كما ترى، وحرك قلبي بحنانك لأخدم المتعبين والمشتتين حولي بمحبة صادقة. آمين.\",\"x\":\"قبل هذه الآية قضى الرب أيامًا في المدن يعلم ويشفي. ثم نظر إلى الجموع بعيون راعٍ صالح. وصفهم بأنهم منزعجون ومنطرحون، أي متعبون ومشتتون وبلا قيادة. وكلمة «تحنن» في الأصل اليوناني تعني أن أحشاءه تحركت. فالله لا يخدمنا من بعيد، بل من قلب متألم. ثم دعا تلاميذه إلى المشاركة: «اطلبوا من رب الحصاد». فالصلاة والخدمة تبدآن من نظرة حقيقية للناس.\\nاليوم، اجلس في مكان عام لدقائق، وانظر إلى الناس بعين المسيح، وصلِّ من أجل ثلاثة منهم.\"},{\"t\":\"أي فضيلة ننشد؟\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أنطونيوس إن من يضرب الحديد يفكر أولًا ماذا يصنع منه، منجلًا أم فأسًا. الحصاد يحتاج هدفًا واضحًا. حدد اليوم فضيلة واحدة تجاهد فيها كي لا تتعب عبثًا.\",\"p\":\"يا رب، علّمني أن أعرف هدف جهادي. اجعل تعبي مثمرًا لا عبثًا. آمين.\",\"x\":\"يقول الأب أنطونيوس إن من يضرب الحديد يفكر أولًا ماذا يصنع منه، منجلًا أم فأسًا، كذلك علينا أن نحدد أية فضيلة ننشد لئلا نتعب عبثًا. تدريب: حدد هدفًا روحيًا واحدًا لهذا الأسبوع واكتبه.\",\"fq\":19}]},\"7-7\":{\"th\":\"الثبات والثمر\",\"m\":[{\"t\":\"كجبل صهيون\",\"ref\":\"المزمور ١٢٤ (١٢٥) — الغروب\",\"v\":\"المتوكلون على الرب مثل جبل صهيون لا يتزعزع إلى الأبد.\",\"r\":\"المتكلون على الرب مثل جبل صهيون لا يتزعزع إلى الأبد. من يثبت في الكرمة يثمر. اختر اليوم أن تثبت في الصلاة عشر دقائق قبل كل عمل.\",\"p\":\"يا رب، ثبّتني فيك كالكرمة. اجعلني متكلًا عليك فلا أتزعزع، وأثمر لك ثمرًا يدوم. آمين.\",\"x\":\"جبل صهيون ثابت في موضعه، وهكذا من يتكل على الرب لا يتزعزع مهما اشتدت الريح. الاتكال ليس شعورًا بل قرار يتكرر. تدريب: عند أول قلق اليوم، قل: أتكل عليك يا رب، وأعد القول بعد دقيقة.\"},{\"t\":\"إن ثبتم فيّ\",\"ref\":\"يوحنا ١٥: ٧\",\"bk\":\"يوحنا\",\"v\":\"إن ثبتم في وثبت كلامي فيكم تطلبون ما تريدون فيكون لكم.\",\"r\":\"«إن ثبتم فيّ وثبت كلامي فيكم، تطلبون ما تريدون فيكون لكم». الثبات يغيّر ما أريده. وكلما ثبتُّ فيه صارت رغباتي أقرب إلى رغباته، فتصير صلاتي مستجابة. فأقرأ كلمته اليوم لأنها غذاء ثباتي.\",\"p\":\"يا رب يسوع، ثبّتني فيك وثبّت كلمتك فيّ. اجعل رغباتي موافقة لرغباتك، واستجب صلاتي بحسب إرادتك. آمين.\",\"x\":\"قبل هذه الآية يحذّر الرب من أن الغصن المنفصل عن الكرمة يجف ويُطرح. فالانفصال موت. وفي هذه الآية يربط بين الثبات في المسيح وثبات الكلمة في القلب. أي أن علاقتي به تنبع من قراءة الكلمة وتأملها وحفظها. ومن ثم تأتي الصلاة المستجابة، لا لأن الله يطيع أهوائي، بل لأن قلبي صار في اتجاه قلبه. وهذا ما يصنعه الروح القدس فينا.\\nاحفظ آية واحدة اليوم، وردّدها عدة مرات، وقل: «يا رب ليثبت كلامك فيّ».\"},{\"t\":\"لم أترك فكرًا يغضب الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"سُئل الأب سلوان عن نسكه فأجاب أنه لم يترك في قلبه فكرًا يغضب الله. الثبات في المسيح يبدأ من الأفكار. راقب اليوم فكرًا واحدًا يتكرر عليك، وأسلمه لله.\",\"p\":\"يا رب، احفظ أفكاري. طهّر ذهني، واجعل قلبي مسكنًا لك. آمين.\",\"x\":\"لما سألوا الأب سلوان عن نسكه أجاب أنه لم يترك في قلبه فكرًا يغضب الله. فالنسك الأعمق يحدث في الأفكار لا في الأعمال الظاهرة. تدريب: انتبه اليوم لفكر يغضب الله ولا تتركه يبقى.\",\"fq\":512}]},\"7-8\":{\"th\":\"أرسلكم أنا\",\"m\":[{\"t\":\"الرب يحفظ دخولك وخروجك\",\"ref\":\"المزمور ١٢٠ (١٢١) — الغروب\",\"v\":\"الرب يحفظ نفسك. الرب يحفظ دخولك وخروجك.\",\"r\":\"الإرسال لا يعني أن نذهب وحدنا، فالرب يحفظ دخولنا وخروجنا. ثق بأنه معك حيث يرسلك. حين تخرج اليوم من بيتك قل: أنا مرسل منه.\",\"p\":\"يا رب، احفظ نفسي ودخولي وخروجي. أرسلني حيث تريد، وكن معي في كل خطوة. آمين.\",\"x\":\"«الرب يحفظ دخولك وخروجك» وعد يرافق المسافر والعامل والخادم، فالمرسَل لا يذهب وحده. تدريب: ضع يدك على باب بيتك وأنت تخرج، وصلِّ: احفظ دخولي وخروجي.\"},{\"t\":\"حكماء كالحيات\",\"ref\":\"متى ١٠: ١٦\",\"bk\":\"متى\",\"v\":\"«ها أنا أرسلكم كغنم في وسط ذئاب، فكونوا حكماء كالحيات وبسطاء كالحمام.\",\"r\":\"«ها أنا أرسلكم كغنم في وسط ذئاب، فكونوا حكماء كالحيات وبسطاء كالحمام». الحكمة بلا بساطة تصير مكرًا، والبساطة بلا حكمة تصير سذاجة. وأنا أحتاج الاثنين معًا في تعاملي.\",\"p\":\"يا رب، امنحني حكمة الفطنة وبساطة الحمام. احفظني من الخبث ومن السذاجة، وقدني بروحك في كل خطوة. آمين.\",\"x\":\"في خطاب الإرسال يعدّ الرب تلاميذه لمقاومة قادمة. فهو لا يعدهم بطريق سهل، لكنه يعطيهم مبدأين: الفطنة والنقاء. والحية تتجنب الخطر وتتصرف بحذر، والحمامة رمز البراءة والسلام. وفي الآيات التالية يقول إنهم سيسلَّمون إلى مجالس، لكن الروح القدس سيتكلم فيهم. فنحن لا نعتمد على ذكائنا وحده. والمؤمن يتعلم أن يتعامل مع الناس بحكمة دون أن يفقد براءته.\\nقبل أن تتخذ قرارًا اليوم، اسأل: هل هو حكيم؟ وهل هو نقي؟ ثم صلِّ.\"},{\"t\":\"أن تبقى\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول أحد الآباء: إذا ذهبت يقولون لك أنطونيوس، أما إذا بقيت فيقولون الأب أنطونيوس. الإرسال يحتاج إلى ثبات في المكان. التزم اليوم بما أوكل إليك دون أن تنتقل من عمل إلى آخر.\",\"p\":\"يا رب، علّمني أن أثبت في إرساليتي. أعطني صبرًا في مكاني حتى أثمر. آمين.\",\"x\":\"يلاحظ الأب أنطونيوس أن من يذهب يُسمّى باسمه، ومن يبقى يُسمّى أبًا. الثبات يعطي وقارًا. تدريب: لا تتنقل اليوم بين المشاغل بعجلة، وثبّت في مهمة واحدة حتى تنتهي.\",\"fq\":16}]},\"7-9\":{\"th\":\"شجاعة الشهادة\",\"m\":[{\"t\":\"لا تخشى من خوف الليل\",\"ref\":\"المزمور ٩٠ (٩١) — السادسة\",\"v\":\"فلا تخشى من خوف الليل، ولا من سهم يطير في النهار. ولا من أمر يسلك في الظلمة. ولا من سقطة وشيطان الظهيرة.\",\"r\":\"يعد المزمور بحفظ من خوف الليل وسهم النهار وسقطة الظهيرة. الشهادة تحتاج شجاعة من لا يخاف. اكتب اليوم الخوف الذي يمنعك من الشهادة، وسلّمه للرب.\",\"p\":\"يا رب، احفظني من كل خوف. أعطني جرأة أن أشهد لك بحياتي وبكلامي. آمين.\",\"x\":\"المزمور يعد بحفظ من الخوف في الليل ومن السهم في النهار ومن شيطان الظهيرة. الله يغطي الساعات كلها. تدريب: حدد ساعة من يومك تخاف فيها، وقدمها لله قبل أن تأتي.\"},{\"t\":\"عرفوهما أنهما كانا مع يسوع\",\"ref\":\"أعمال الرسل ٤: ١٣\",\"bk\":\"أعمال الرسل\",\"v\":\"فلما رأوا مجاهرة بطرس ويوحنا، ووجدوا أنهما إنسانان عديما العلم وعاميان، تعجبوا. فعرفوهما أنهما كانا مع يسوع.\",\"r\":\"«فعرفوهما أنهما كانا مع يسوع». أعظم شهادة ليست علمي أو فصاحتي، بل أن يرى الناس فيّ أثر لقائي بالمسيح. فأنا مدعو أن أقضي وقتًا معه ليظهر فيّ. ولهذا أطلب الجلوس معه كل يوم قبل أن أنطلق.\",\"p\":\"يا رب، اجعلني قريبًا منك حتى يعرف الناس أنني معك. املأني من روحك لأشهد بجرأة وتواضع. آمين.\",\"x\":\"قبض الرؤساء على بطرس ويوحنا بعد شفاء الأعرج عند باب الجميل، وسألوهما بأي قوة فعلتما هذا. فأجاب بطرس ممتلئًا من الروح القدس بجرأة. فتعجبوا لأنهما كانا من الصيادين. وعرفوا مصدر الجرأة: صحبة المسيح. وعندما رأوا الرجل الذي شُفي واقفًا معهما، لم يجدوا ما يقولونه. فالحياة المتغيرة هي أقوى دليل. والشهادة بالأفعال تسبق الكلام.\\nخصص اليوم عشر دقائق للجلوس مع المسيح في الصلاة والإنجيل، قبل أن تنشغل بأي شيء.\"},{\"t\":\"أنت مجنون\",\"ref\":\"\",\"v\":\"\",\"r\":\"يتنبأ القديس أنطونيوس أن الناس سيصيرون مجانين، وإن رأوا إنسانًا عاقلًا قالوا له أنت مجنون لأنه يختلف عنهم. الشهادة تعني أحيانًا أن نكون مختلفين. اثبت اليوم على قيمة مسيحية واحدة رغم ضغط الجماعة.\",\"p\":\"يا رب، ثبتني على الحق ولو خالفت الناس. اجعلني شاهدًا بهدوء ومحبة. آمين.\",\"x\":\"يتنبأ الأب أنطونيوس بأن الناس سيصيرون مجانين، ومن بقي عاقلًا قالوا له: أنت مجنون، لأنه يختلف عنهم. الشهادة قد تعني أن نبدو مختلفين. تدريب: اقبل أن تكون مختلفًا اليوم في موقف خلقي صغير، بهدوء.\",\"fq\":13}]},\"7-10\":{\"th\":\"انتظار القوة\",\"m\":[{\"t\":\"رتب مصاعد في قلبه\",\"ref\":\"المزمور ٨٣ (٨٤) — السادسة\",\"v\":\"طوبى للرجل الذي نصرته من عندك يا رب، رتب مصاعد في قلبه. في وادي البكاء، في المكان الذي قرره.\",\"r\":\"الإنسان الذي نصرته من عند الله يرتب مصاعد في قلبه حتى في وادي البكاء. انتظار القوة صعود خطوة خطوة. اطلب اليوم قوة لمهمة بعينها، ثم ابدأ بها واثقًا.\",\"p\":\"يا رب، رتّب في قلبي مصاعد نحوك. قوّني في وادي البكاء، وانتظرني حتى أنال قوتك. آمين.\",\"x\":\"«رتب مصاعد في قلبه» أي أن الله يرفع المؤمن درجة درجة حتى في وادي البكاء. حتى الألم له مصعد. تدريب: اسأل أين الدرجة التالية في وادي بكائك، وارفع خطوة صغيرة.\"},{\"t\":\"موعد الآب\",\"ref\":\"أعمال الرسل ١: ٤\",\"bk\":\"أعمال الرسل\",\"v\":\"وفيما هو مجتمع معهم أوصاهم أن لا يبرحوا من أورشليم، بل ينتظروا «موعد الآب الذي سمعتموه مني،\",\"r\":\"«أوصاهم أن لا يبرحوا من أورشليم، بل ينتظروا موعد الآب». الانتظار لا يعني الفراغ بل الاستعداد. والرب لا يريدني أن أعمل بقوتي، بل أن أنتظر قوته. فالله يعد ولا يخلف.\",\"p\":\"يا رب، علّمني أن أنتظرك بصبر، وأن أطلب قوة روحك القدوس قبل أن أنطلق في أي عمل. آمين.\",\"x\":\"في الأربعين يومًا بين القيامة والصعود علّم الرب التلاميذ عن الملكوت. ثم أمرهم أن ينتظروا. وكان هذا صعبًا لأنهم كانوا متحمسين. لكن الرسالة بدون الروح عديمة القوة. وفي العشرة أيام بين الصعود والعنصرة كانوا يواظبون على الصلاة بنفس واحدة. وهكذا تعلمنا الكنيسة أن الصوم والصلاة تهيئة لعمل الروح. فلا نتعجل الثمر، بل نستعد بالانتظار.\\nاخصص اليوم وقتًا للصمت والانتظار أمام الله، وقل: «تكلم يا رب فعبدك سامع».\"},{\"t\":\"أعطني القوة\",\"ref\":\"\",\"v\":\"\",\"r\":\"صلاة الأم سارة قصيرة جدًا: يا الله أعطني القوة. القوة تأتي حين نعترف بضعفنا. كرر هذه الصلاة اليوم كلما شعرت بالتعب.\",\"p\":\"يا الله، أعطني القوة. لا تتركني لضعفي، بل اسكب روحك عليّ. آمين.\",\"x\":\"صلاة الأم سارة كانت قصيرة جدًا: يا الله أعطني القوة. حاربها شيطان الزنى سنين، ولم تطلب أن تُرفع الحرب بل القوة. تدريب: اطلب من الله اليوم قوة ثابتة بدل أن تطلب زوال الصعوبة.\",\"fq\":525}]},\"7-11\":{\"th\":\"اعتراف الإيمان\",\"m\":[{\"t\":\"في مجلس المستقيمين\",\"ref\":\"المزمور ١١٠ (١١١) — التاسعة\",\"v\":\"في مجلس المستقيمين وفي مجمعهم.\",\"r\":\"الاعتراف بالإيمان يعلن بالفم ويصدّق بالقلب، في مجلس المستقيمين وفي مجمعهم. قل اليوم بصوت منخفض ما تؤمن به عن المسيح، وكن صادقًا في كل كلمة.\",\"p\":\"يا رب، أعترف لك من كل قلبي أنك ابن الله. ثبّت إيماني ولا تدعني أخجل باسمك. آمين.\",\"x\":\"الاعتراف بالإيمان في مجلس المستقيمين يعني أن الإيمان يُعاش داخل جماعة. لا يؤمن المرء وحده. تدريب: ردّد اليوم قانون الإيمان ببطء، وتوقف عند عبارة واحدة تتأمل فيها.\"},{\"t\":\"اعتراف الفم وإيمان القلب\",\"ref\":\"رومية ١٠: ٩\",\"bk\":\"رومية\",\"v\":\"لأنك إن اعترفت بفمك بالرب يسوع، وآمنت بقلبك أن الله أقامه من الأموات، خلصت.\",\"r\":\"«إن اعترفت بفمك بالرب يسوع، وآمنت بقلبك أن الله أقامه من الأموات، خلصت». الإيمان ليس شعورًا مخبأ في القلب فقط، ولا كلمات بلا قلب. أحتاج أن يتوافق ما في داخلي مع ما أقوله وأعيشه أمام الناس.\",\"p\":\"يا رب يسوع، أؤمن بقلبي أنك قمت من الأموات، وأعترف بفمي أنك ربي ومخلصي. اجعل حياتي كلها شهادة لهذا الإيمان. آمين.\",\"x\":\"بولس يقتبس من التثنية أن الكلمة قريبة منك، في فمك وفي قلبك. فالخلاص ليس بعيدًا ولا يحتاج إلى بطولات، بل إلى إيمان بقيامة المسيح واعتراف بربوبيته. وفي الآية التالية يوضح: القلب يؤمن للبر والفم يعترف للخلاص. والاعتراف في العهد الجديد كان مكلفًا لأنه يعني أن قيصر ليس الرب. ونحن نعترف في قانون الإيمان كل صلاة وكل قداس: بالحقيقة نؤمن بإله واحد. فهو إعلان حي للإيمان.\\nردد اليوم قانون الإيمان ببطء وانتباه، وتوقف عند عبارة واحدة تشعر أنها تلمس قلبك.\"},{\"t\":\"أمام الله الذي يفحص القلوب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أفرام: إذا كنا نستحي من الناس فكم بالحري ينبغي أن نخجل من الله الذي يفحص خفايا القلوب. الاعتراف الحقيقي أمام الله. راجع اليوم فكرًا تخجل أن يراه الناس، وقدمه لله بصدق.\",\"p\":\"يا رب، يا فاحص القلوب، طهّر ما في داخلي. أعطني مخافتك وصدق الاعتراف. آمين.\",\"x\":\"يقول القديس أفرام: إن كنا نستحي من الناس فكم بالحري نخجل من الله الذي يفحص القلوب. الحياء من الله بداية الطهارة. تدريب: قبل أن تفعل أمرًا خفيًا اليوم، اسأل: هل أفعله أمام الله بلا خجل؟\",\"fq\":103}]},\"7-12\":{\"th\":\"الرسولان بطرس وبولس\",\"m\":[{\"t\":\"رأس الزاوية\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"الحجر الذي رذله البناءون هذا صار رأسا للزاوية. من قبل الرب كان هذا وهو عجيب في أعيننا.\",\"r\":\"الحجر الذي رذله البناءون صار رأس الزاوية، وهذا عجيب في أعيننا. على هذا الأساس بُنيت الكنيسة بشهادة بطرس وبولس. فكر اليوم في ثبات إيمانك على المسيح الحجر الحي.\",\"p\":\"يا رب، أنت الحجر رأس الزاوية. ابنِ حياتي عليك كما بنيت كنيستك على إيمان رسلك. آمين.\",\"x\":\"الحجر الذي رذله البناءون صار رأس الزاوية، آية قالها المسيح عن نفسه، وتتم في الكنيسة التي أسسها على اعتراف بطرس وتعليم بولس. تدريب: اشكر الله على من رذله الناس وجعله الله أساسًا، وابحث عمن تقصيه وقدّره.\"},{\"t\":\"جاهدت الجهاد الحسن\",\"ref\":\"تيموثاوس الثانية ٤: ٧\",\"bk\":\"تيموثاوس الثانية\",\"v\":\"قد جاهدت الجهاد الحسن، أكملت السعي، حفظت الإيمان،\",\"r\":\"«قد جاهدت الجهاد الحسن، أكملت السعي، حفظت الإيمان». لم يقل بولس أنه انتصر بقوته، بل أنه جاهد وحفظ. وأنا أيضًا أُدعى للأمانة حتى النهاية، فالأمانة هي مقياس الجهاد الحسن.\",\"p\":\"يا رب، أعطني أن أجاهد الجهاد الحسن وأحفظ الإيمان، وأكمل السعي بنعمتك حتى أنال إكليل البر مع جميع محبي ظهورك. آمين.\",\"x\":\"كتب بولس هذه الكلمات من سجنه الأخير في روما، وهو يعلم أن وقت انحلاله قد حضر. وهو لا يتحدث عن نجاح بشري بل عن أمانة ثلاثية: جهاد وسعي وحفظ للإيمان. ثم ينظر إلى الأمام: إكليل البر. وهو لنفسه ولجميع الذين يحبون ظهور الرب، أي كل من يشتاق إلى لقائه. فالنهاية المجيدة ليست للرسل فقط. وفي ختام حياتنا نحتاج أن نقول بتواضع: بنعمتك أكملت ما أعطيتني.\\nاكتب لنفسك اليوم سطرين: ما هو الجهاد الذي يدعوك الله إليه في هذه المرحلة من حياتك؟\"},{\"t\":\"احصوا الأميال\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بنيامين: اسلكوا الطريق الملوكي واحصوا الأميال ولا تكونوا غير مبالين. أكمل بولس السعي وحفظ الإيمان بمثل هذا الانتباه. حدد اليوم ميلًا روحيًا تقطعه: صلاة أو قراءة أو خدمة.\",\"p\":\"يا رب، علّمني أن أسعى بانتباه. أعطني أن أكمل السعي وأحفظ الإيمان كرسلك. آمين.\",\"x\":\"يوصي الأب بنيامين: اسلكوا الطريق الملوكي واحصوا الأميال ولا تكونوا غير مبالين. فمن يعد خطواته يعرف أين وصل. تدريب: اكتب أين كنت قبل سنة روحيًا، وأين أنت الآن.\",\"fq\":85}]},\"7-13\":{\"th\":\"الكنيسة بيت روحي\",\"m\":[{\"t\":\"يوم في ديارك\",\"ref\":\"المزمور ٨٣ (٨٤) — السادسة\",\"v\":\"لأن يوما صالحا في ديارك خير من آلاف. اخترت لنفسي أن أطرح على باب بيت الله، أفضل من أن أسكن في مظال الخطاة.\",\"r\":\"يوم واحد في بيت الله خير من آلاف، والمرنم يفضل أن يطرح على بابه. الكنيسة بيت روحي نبنى فيه حجارة حية. اذهب اليوم إلى الكنيسة أو صلِّ فيها قليلًا إن استطعت.\",\"p\":\"يا رب، ما أحلى بيتك. اجعلني حجرًا حيًا في كنيستك، وأعطني حب الاجتماع فيها. آمين.\",\"x\":\"يوم واحد في ديار الرب خير من ألف، والمرنم يفضل أن يكون على العتبة بدل أن يسكن مع الخطاة. المهم أن نكون قرب بيته. تدريب: اجعل لك اليوم عشر دقائق في الكنيسة أو في ركن الصلاة، كأنك على عتبة بيته.\"},{\"t\":\"أساس الرسل\",\"ref\":\"أفسس ٢: ٢٠\",\"bk\":\"أفسس\",\"v\":\"مبنيين على أساس الرسل والأنبياء، ويسوع المسيح نفسه حجر الزاوية،\",\"r\":\"«مبنيين على أساس الرسل والأنبياء، ويسوع المسيح نفسه حجر الزاوية». لست وحدي في إيماني، بل أنا جزء من بناء بدأ منذ قرون. وكل حجر يستمد ثباته من حجر الزاوية الذي يحمل البناء كله.\",\"p\":\"يا رب، أشكرك على الكنيسة التي بنيتها على أساس الرسل. ثبّتني حجرًا حيًا فيها، وليكن المسيح حجر زاويتي. آمين.\",\"x\":\"بولس يخاطب أهل أفسس من الأمم ويقول إنهم لم يعودوا غرباء بل أهل بيت الله. والبناء يقوم على شهادة الرسل والأنبياء، أي الكتاب المقدس والتقليد الحي. وحجر الزاوية يحدد اتجاه البناء كله وزواياه. والمسيح هو الذي يوحّد اليهودي والأممي في جسد واحد. وفي كنيستنا نعتز بالتسلسل الرسولي وبالإيمان الذي تسلمناه، لأنه ليس اختراعًا حديثًا بل أمانة تسلمناها.\\nاقرأ اليوم قانون الإيمان وتأمل أنه نفس الإيمان الذي حفظه الرسل والآباء عبر الأجيال، واشكر الله على هذه السلسلة.\"},{\"t\":\"عمل الحياة المشتركة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن الحياة المشتركة تحتاج إلى عمل التواضع وعمل الطاعة وعمل الحياة المشتركة نفسه. الكنيسة جماعة تحتاج أعضاء متضعين. ساهم اليوم بعمل في كنيستك أو أسرتك دون أن تطلب شكرًا.\",\"p\":\"يا رب، علّمني التواضع والطاعة في الجماعة. اجعلني عضوًا نافعًا في جسدك. آمين.\",\"x\":\"يرى الأب بيمن أن الحياة المشتركة تحتاج إلى التواضع والطاعة والعمل المشترك. فهي مدرسة الفضائل. تدريب: شارك في عمل جماعي اليوم وتنازل فيه عن رأيك مرة واحدة.\",\"fq\":388}]},\"7-14\":{\"th\":\"كلمة الله\",\"m\":[{\"t\":\"أعطى طعامه لأتقيائه\",\"ref\":\"المزمور ١١٠ (١١١) — التاسعة\",\"v\":\"رحيم هو الرب ورؤوف. أعطى طعامه لأتقيائه: يذكر إلى الدهر ميثاقه.\",\"r\":\"الرب رحيم ورؤوف، وأعطى طعامه لأتقيائه ويذكر ميثاقه. كلمة الله طعام للنفس مثل الخبز للجسد. اقرأ اليوم فصلًا من الإنجيل قبل أي شيء آخر.\",\"p\":\"يا رب، أطعمني من كلمتك. أعطني أن أسمعها بإيمان، فتصير حياة في قلبي. آمين.\",\"x\":\"يعطي الله طعامه لأتقيائه ويذكر ميثاقه، وكلمة الله طعام يومي كالخبز. من لا يأكل يضعف. تدريب: اقرأ اليوم فصلًا ببطء، واختر منه عبارة تأكلها طوال يومك.\"},{\"t\":\"الإيمان بالخبر\",\"ref\":\"رومية ١٠: ١٧\",\"bk\":\"رومية\",\"v\":\"إذا الإيمان بالخبر، والخبر بكلمة الله.\",\"r\":\"«إذًا الإيمان بالخبر، والخبر بكلمة الله». كيف أنمو في إيماني؟ بأن أسمع كلمة الله وأقرأها وأتأملها باستمرار. فالإيمان يتغذى من الكلمة كما يتغذى الجسد من الطعام، ولا يعيش بالحماس العابر وحده.\",\"p\":\"يا رب، افتح أذني وقلبي لكلمتك، واجعل إيماني ينمو بسماعها ليصير حياة وثمرًا في كل أيامي. آمين.\",\"x\":\"بولس يتحدث عن الذين لم يؤمنوا بعد، فيسأل: كيف يؤمنون بمن لم يسمعوا به؟ وكيف يسمعون بلا كارز؟ فالكرازة والسمع والإيمان سلسلة متصلة. وفي حياتنا الشخصية نحتاج أن نعيد السمع باستمرار. ولهذا تضع الكنيسة قراءات الإنجيل والرسائل والمزامير في كل قداس. والخبر هنا هو بشارة الخلاص. فمن يسمعها بقلب مفتوح يبدأ الإيمان فيه، ومن يحفظها ينمو إيمانه.\\nاقرأ اليوم فصلًا من الإنجيل بصوت مسموع، وسجّل جملة منه تتأمل فيها طوال اليوم.\"},{\"t\":\"احفظ الإنجيل\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح الأب مكاريوس أخًا تحاربه الأفكار أن يحفظ الإنجيل والأسفار عن ظهر قلب، وأن يوجه أبصاره إلى العلاء. الكلمة المحفوظة سلاح وقت الضيق. احفظ اليوم آية واحدة تلجأ إليها.\",\"p\":\"يا رب، اكتب كلمتك على قلبي. أعطني أن أرددها في التجربة فتنتصر فيّ. آمين.\",\"x\":\"ينصح الأب مكاريوس أخًا تحاربه الأفكار أن يحفظ الإنجيل والأسفار، وإذا جاءه فكر شرير يرفع بصره إلى العلاء. الحفظ سلاح جاهز. تدريب: احفظ اليوم آية قصيرة، وردّدها عند أول فكر مشوش.\",\"fq\":234}]},\"7-15\":{\"th\":\"جماعة تصلي\",\"m\":[{\"t\":\"ادخلوا دياره\",\"ref\":\"المزمور ٩٥ (٩٦) — التاسعة\",\"v\":\"احملوا الذبائح وادخلوا دياره، اسجدوا للرب في دياره المقدسة.\",\"r\":\"يدعونا المرنم أن نحمل الذبائح وندخل دياره المقدسة ونسجد للرب. الجماعة التي تصلي معًا تجد قوة لا يجدها المنفرد. صلِّ اليوم مع أحد أفراد أسرتك ولو بصلاة قصيرة.\",\"p\":\"يا رب، اجمعنا في اسمك. علّمنا أن نصلي معًا بقلب واحد وروح واحدة. آمين.\",\"x\":\"يدعو المرنم أن نحمل الذبائح وندخل ديار الرب، فالعبادة الجماعية حركة جماعية. تدريب: ادخل اليوم أي كنيسة أو صلِّ مع شخص آخر، ولو بصلاة الأبانا.\"},{\"t\":\"مصلين بكل صلاة\",\"ref\":\"أفسس ٦: ١٨\",\"bk\":\"أفسس\",\"v\":\"مصلين بكل صلاة وطلبة كل وقت في الروح، وساهرين لهذا بعينه بكل مواظبة وطلبة، لأجل جميع القديسين،\",\"r\":\"«مصلين بكل صلاة وطلبة كل وقت في الروح، وساهرين لهذا بعينه بكل مواظبة وطلبة لأجل جميع القديسين». الصلاة ليست قسمًا من يومي بل هواء حياتي. وهي أيضًا مسؤولية تجاه الجميع.\",\"p\":\"يا رب، علّمني أن أصلي في كل وقت وبكل صلاة. وأعطني أن أشفع في إخوتي القديسين وخدام كنيستك. آمين.\",\"x\":\"سلاح الله من منطقة الحق إلى سيف الروح، ثم يأتي ختامه الصلاة. فكل سلاح بلا صلاة لا ينفع. وعبارة «كل صلاة» تعني أنواعها: تسبيح وشكر وطلبة وشفاعة وصمت. و«كل وقت» أي في الصباح والليل ووسط العمل. وطلب بولس أن يُعطى له كلام يدل على أنه يعتمد على صلواتنا. فنحن نصلي لأجل خدام الكنيسة ورعاتها. وفي الأجبية صلوات الساعات تعلمنا هذا الإيقاع المستمر.\\nاصنع اليوم ثلاث وقفات صلاة قصيرة موزعة على يومك، ورفع فيها اسم خادم أو كاهن.\"},{\"t\":\"كنا نرتفع إلى السماوات\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب مياثيوس إننا في البدء كنا نجتمع ونتباحث في أمور نافعة بانين بعضنا بعضًا فنرتفع إلى السماوات، أما الآن فنجتمع ليدين أحدنا أخاه. اجعل لقاءك اليوم بنيانًا لا إدانة.\",\"p\":\"يا رب، اجعل اجتماعاتنا بنيانًا. احفظ ألسنتنا من الإدانة وعلّمنا أن نصعد معًا إليك. آمين.\",\"x\":\"يقول الأب مياثيوس إننا كنا نجتمع ونبني بعضنا فنرتفع إلى السماوات، أما الآن فنجتمع ليدين أحدنا أخاه فنهبط. الاجتماع يرفع أو يهبط بحسب ما نقول. تدريب: في أول لقاء اليوم لا تتكلم عن غائب إلا بخير.\",\"fq\":283}]},\"7-16\":{\"th\":\"المحبة الكاملة\",\"m\":[{\"t\":\"الرب يحب الرحمة والحق\",\"ref\":\"المزمور ٨٣ (٨٤) — السادسة\",\"v\":\"لأن الرب الإله يحب الرحمة والحق، ويعطى مجدا ونعمة.\",\"r\":\"الرب الإله يحب الرحمة والحق ويعطي مجدًا ونعمة. المحبة الكاملة هي التي تجمع الرحمة والحق معًا. اختر اليوم موقفًا تجمع فيه الحق بالرحمة دون تجريح.\",\"p\":\"يا رب، علّمني أن أحب كما تحب. اجعل رحمتي وحقي معًا في كل تعامل. آمين.\",\"x\":\"الله يحب الرحمة والحق ويعطي مجدًا ونعمة، فهما صفتان يجب أن تلتقيا فينا. تدريب: حين تواجه خطأ اليوم، قل الحق وأضف رحمة، وراقب الفرق.\"},{\"t\":\"هو أحبنا أولًا\",\"ref\":\"يوحنا الأولى ٤: ١٩\",\"bk\":\"يوحنا الأولى\",\"v\":\"نحن نحبه لأنه هو أحبنا أولا.\",\"r\":\"«نحن نحبه لأنه هو أحبنا أولًا». لا أحتاج أن أتصنع محبة الله، بل أن أتأمل في محبته لي حتى تشتعل محبتي له. فمن عرف كم هو محبوب يصير قادرًا على أن يحب.\",\"p\":\"يا رب، أنت أحببتني أولًا. افتح قلبي لمحبتك، واملأني بها حتى أحب إخوتي كما أحببتني. آمين.\",\"x\":\"قبل هذه الآية قال يوحنا إن المحبة الكاملة تطرح الخوف إلى خارج. فمن يشعر بأنه محبوب لا يعيش في خوف من العقاب. والمحبة الإلهية سبقتنا بالخلق والفداء والدعوة. وبعد الآية يقول: «إن قال أحد إني أحب الله وأبغض أخاه فهو كاذب». فالاستجابة لمحبة الله تظهر في محبة القريب. والتأمل في الصليب هو أقصر طريق لإدراك محبته. فمن هناك تنبع قدرتنا على أن نحب.\\nقف اليوم أمام صورة المصلوب لدقائق، وقل له: «أنت أحببتني أولًا»، واترك محبته تغمرك.\"},{\"t\":\"محبة بلا دينونة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب كسنثيا إن الكلب أفضل منه لأن عنده محبة ولا يأتي إلى دينونة أحد. المحبة تخفض الأنا وتبعد الدينونة. أحب اليوم بلا حكم على أحد.\",\"p\":\"يا رب، هب لي محبة بسيطة لا تدين. وطهّر قلبي من كل كبرياء يمنعني أن أحب. آمين.\",\"x\":\"يقول الأب كسنثيا إن الكلب أفضل منه لأن عنده محبة ولا يدين أحدًا. هذه مبالغة متواضعة تعلّمنا أن الدينونة أبعد ما تكون عن المحبة. تدريب: اقضِ اليوم بلا أي حكم داخلي على أحد.\",\"fq\":308}]},\"7-17\":{\"th\":\"الوحدة\",\"m\":[{\"t\":\"سبحوه يا جميع الأمم\",\"ref\":\"المزمور ١١٦ (١١٧) — الغروب\",\"v\":\"سبحوا الرب يا جميع الأمم ولتباركه كافة الشعوب. لأن رحمته قد ثبتت علينا وحق الرب يدوم إلى الأبد هلليلويا.\",\"r\":\"يدعو المرنم كل الأمم والشعوب إلى تسبيح واحد لأن رحمة الرب ثبتت علينا. الوحدة تبدأ بتسبيح مشترك. صلِّ اليوم من أجل وحدة كنيستك وبيتك.\",\"p\":\"يا رب، اجمع شعبك في تسبيح واحد. ثبّت رحمتك علينا، واجعلنا واحدًا كما أنت والآب واحد. آمين.\",\"x\":\"يدعو المزمور كل الأمم إلى التسبيح، فرحمة الله ليست لشعب واحد. تدريب: صلِّ اليوم من أجل كنيسة أو شعب لا تعرفه، وسبح الله على رحمته للجميع.\"},{\"t\":\"ما أحسن وما أجمل\",\"ref\":\"المزامير ١٣٣: ١\",\"bk\":\"المزامير\",\"v\":\"هوذا ما أحسن وما أجمل أن يسكن الإخوة معا!\",\"r\":\"«هوذا ما أحسن وما أجمل أن يسكن الإخوة معًا!». الوحدة ليست فرضًا بل جمال وعطر وندى. وحيث يجتمع الإخوة بمحبة، يأمر الرب بالبركة، فتنمو الحياة وتنتعش الأرواح. وأنا أبدأ بنفسي: أن أكون سبب جمال لا سبب خصام.\",\"p\":\"يا رب، ما أحسن وما أجمل أن نسكن معًا بالمحبة! اجعل بيوتنا وكنائسنا مكانًا تأمر فيه بالبركة. آمين.\",\"x\":\"هذا من مزامير المصاعد التي كان الحجاج ينشدونها وهم صاعدون إلى أورشليم. والتشبيهان يصفان الوحدة بنعمة تنساب: الدهن المقدس الذي مسح هارون، والندى الذي ينعش الجبال في الصيف. فالوحدة ليست صراعًا بل راحة وانتعاش. وعبارة «هناك أمر الرب بالبركة» تعني أن البركة مرتبطة بالوحدة. ولا يعني هذا أن نتفق في كل شيء بل أن نحب ونتحمل ونتعاون في مسيرتنا نحو الله.\\nاليوم، اجتمع مع أسرتك أو أصدقائك على صلاة بسيطة أو شاي هادئ، وشكرا الله على وجودكم معًا.\"},{\"t\":\"أن تموت عن قريبك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب موسى الحبشي إن أن تموت عن قريبك يعني أن تحمل خطاياك ولا تسيء إلى أحد ولا تحتقر من أخطأ. الوحدة تحتاج هذا الموت عن الذات. تصالح اليوم مع شخص ما، أو صلِّ من أجله.\",\"p\":\"يا رب، أمتّ فيّ كل ما يفرّقني عن إخوتي. اجعلني صانع سلام ومصالحة. آمين.\",\"x\":\"يشرح الأب موسى الحبشي أن الموت عن القريب أن تحمل خطاياك ولا تسيء إلى أحد ولا تحتقر من أخطأ. أي أن الأنا تموت حتى يعيش الأخ. تدريب: اترك اليوم فكرة استعلاء على شخص أخطأ.\",\"fq\":266}]},\"7-18\":{\"th\":\"الحرية في المسيح\",\"m\":[{\"t\":\"نجت أنفسنا\",\"ref\":\"المزمور ١٢٣ (١٢٤) — الغروب\",\"v\":\"نجت أنفسنا مثل العصفور من فخ الصيادين، الفخ انكسر ونحن نجونا، عوننا باسم الرب الذي صنع السماء والأرض هلليلويا.\",\"r\":\"نجت أنفسنا مثل العصفور من فخ الصيادين، الفخ انكسر ونحن نجونا. الحرية في المسيح فك لكل فخ. اكتب اليوم عادة تقيدك، وقدمها للمسيح طالبًا الحرية.\",\"p\":\"يا رب، حررني من كل فخ. أنت كسرت قيودي فأعطني أن أسلك في حريتك. آمين.\",\"x\":\"العصفور نجا والفخ انكسر، والمعونة باسم الرب. النجاة عمل الله لا عمل العصفور. تدريب: اشكر الله على فخ نجوت منه ولم تنتبه، وقل: لك المجد على كل فخ انكسر.\"},{\"t\":\"أحرارًا بالحقيقة\",\"ref\":\"يوحنا ٨: ٣٦\",\"bk\":\"يوحنا\",\"v\":\"فإن حرركم الابن فبالحقيقة تكونون أحرارا.\",\"r\":\"«فإن حرركم الابن فبالحقيقة تكونون أحرارًا». أحيانًا أظن الحرية أن أفعل ما أشاء، لكن المسيح يعلمني أنها التحرر من عبودية لا أراها. هو وحده يفك القيود ويعطيني قدرة على عمل الخير.\",\"p\":\"يا رب يسوع، حرّرني من كل قيد داخلي وخطية متسلطة، وأعطني حرية أبناء الله في بيتك. آمين.\",\"x\":\"قال الرب هذا لليهود الذين افتخروا بأنهم أبناء إبراهيم ولم يستعبدوا لأحد. فأجابهم أن كل من يفعل الخطية هو عبد للخطية. فالعبودية الداخلية أخطر من الخارجية. والعبد لا يبقى في البيت، أما الابن فيبقى. والمسيح يحررنا بالحق، أي بمعرفته وبنعمته، لا بمجرد معرفة أفكار. وهذا يفتح الباب لنوع من الحرية يجعلنا نختار الخير بمحبة، كما تفعل الطفولة السليمة في بيت الأب.\\nاكتب اليوم عادة تشعر أنها تقيدك، وقدمها للمسيح في صلاة، واطلب أن يحررك منها.\"},{\"t\":\"احتقر الأموال\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس: إذا اشتهيت ملكوت السماوات فاحتقر الأموال واسع نحو المكافأة الإلهية. المال أول قيد للقلب. تخلَّ اليوم عن شراء شيء غير ضروري، وأعطِ ثمنه لمحتاج.\",\"p\":\"يا رب، فكّ قلبي من أسر الغنى. اجعل كنزي عندك في السماء. آمين.\",\"x\":\"يقول الأب إيسيذورس: إذا اشتهيت ملكوت السماوات فاحتقر الأموال. فالمال أول قيد ما لم نملكه نحن. تدريب: راجع شيئًا تتعلق به من المال أو الأشياء، وأعطِ منه لمحتاج اليوم.\",\"fq\":198}]},\"7-19\":{\"th\":\"السلوك في النور\",\"m\":[{\"t\":\"نور أشرق في الظلمة\",\"ref\":\"المزمور ١١١ (١١٢) — التاسعة\",\"v\":\"نور أشرق في الظلمة للمستقيمين.\",\"r\":\"النور أشرق في الظلمة للمستقيمين. السلوك في النور اختيار يومي للصدق والشفافية. حدد اليوم أمرًا تخفيه، وأخرجه إلى النور بالاعتراف أو التصحيح.\",\"p\":\"يا رب، أنر طريقي. أعطني أن أسلك في النور، فلا أخفي شيئًا منك ولا من الناس. آمين.\",\"x\":\"النور يشرق في الظلمة للمستقيمين، أي أن الاستقامة تجذب نور الله. من يخفي شيئًا يبقى في ظل. تدريب: اعترف لأب اعترافك أو اكتب لله أمرًا تخفيه حتى يدخل النور.\"},{\"t\":\"شركة ودم يطهر\",\"ref\":\"يوحنا الأولى ١: ٧\",\"bk\":\"يوحنا الأولى\",\"v\":\"ولكن إن سلكنا في النور كما هو في النور، فلنا شركة بعضنا مع بعض، ودم يسوع المسيح ابنه يطهرنا من كل خطية.\",\"r\":\"«إن سلكنا في النور كما هو في النور، فلنا شركة بعضنا مع بعض، ودم يسوع المسيح ابنه يطهرنا من كل خطية». السير في النور يعني الصدق مع الله ومع الناس، ولا أخفي شيئًا عن عينيه الرحيمتين.\",\"p\":\"يا رب، علّمني أن أسلك في نورك بلا خوف ولا أقنعة، وطهّرني بدمك الكريم من كل خطية. آمين.\",\"x\":\"يوحنا يربط بين النور والشركة والتطهير. والنور هنا هو الله نفسه: قداسته وحقه ومحبته. والسلوك فيه يعني أن نتصرف أمام الله بلا أقنعة. وعندئذ نتمتع بشركة حقيقية مع الإخوة، لأن الصدق يقرب القلوب. ويستمر دم المسيح في تطهيرنا من كل خطية. وهذا يعلمنا أن الاعتراف ليس خوفًا من الظلمة بل دخول إلى النور. والمستمر في السلوك يتطهر باستمرار.\\nاعترف اليوم بصدق لله بشيء تخفيه، وأقم من يومك شركة صادقة مع أحد إخوتك.\"},{\"t\":\"نقاوة الذهن\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح الأب سيسوى بأن نقتني نقاوة الذهن وعدم الهم والكلام. النور الداخلي يحتاج ذهنًا صافيًا. خصص اليوم عشر دقائق بلا هاتف، واجلس مع الله.\",\"p\":\"يا رب، نقِّ ذهني من كل همّ زائد. اجعل فكري صافيًا لتشرق فيه. آمين.\",\"x\":\"نصح الأب سيسوى أخًا اضطرب عند قراءة الكتب بأن يقتني نقاوة الذهن وعدم الهم والكلام. أي أن الفهم يأتي من القلب الهادئ. تدريب: اقرأ اليوم آية بذهن صاف دون أن تفتح هاتفك.\",\"fq\":492}]},\"7-20\":{\"th\":\"الصوت المنخفض الخفيف\",\"m\":[{\"t\":\"صالح ووديع\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"لأني إليك يا رب رفعت نفسي. لأنك أنت يا رب صالح ووديع. ورحمتك كثيرة لكافة المستغيثين بك.\",\"r\":\"يقول المرنم: أنت يا رب صالح ووديع، ورحمتك كثيرة لكافة المستغيثين بك. الله يتكلم بالصوت المنخفض، ونحتاج هدوءًا لنسمعه. اجلس اليوم دقائق في صمت، وقل: تكلم يا رب.\",\"p\":\"يا رب، أنت صالح ووديع. رفعت إليك نفسي، فتكلم إلى قلبي بصوتك الخفيف. آمين.\",\"x\":\"المرنم يشهد أن الرب صالح ووديع كثير الرحمة لكل المستغيثين. الله يتعامل معنا بلطف لا بصخب. تدريب: استقبل اليوم صوته المنخفض: دقيقة صمت بعد كل صلاة.\"},{\"t\":\"صوت منخفض خفيف\",\"ref\":\"الملوك الأول ١٩: ١٢\",\"bk\":\"الملوك الأول\",\"v\":\"وبعد الزلزلة نار، ولم يكن الرب في النار. وبعد النار صوت منخفض خفيف.\",\"r\":\"«وبعد النار صوت منخفض خفيف». كثيرًا ما أبحث عن الله في الأحداث الكبيرة والمشاعر القوية، لكنه يخاطبني في الهدوء. أحتاج إلى سكون أصغي فيه إلى صوته الرقيق داخل قلبي.\",\"p\":\"يا رب، أصغِ إلى صوتك المنخفض الخفيف. اهدئ ضجيج قلبي لأسمعك، وأرسلني بما تريد وأنا مطمئن. آمين.\",\"x\":\"مرّت أمام إيليا ريح عظيمة تشق الجبال وزلزلة ونار، لكن الله لم يكن فيها. ثم جاء صوت منخفض خفيف، فستر إيليا وجهه بردائه. فالله ليس غائبًا حين لا نرى الأحداث الكبيرة، بل يحضر في اللطف. وفي حياتنا أيضًا، صوت الله في الصلاة الهادئة والكلمة والضمير. وهذا الصوت يطمئن ولا يخيف. وبعده أعطى الله إيليا مهمة وأرسله ومعه تلميذ، فالهدوء يقود إلى رسالة.\\nاجلس اليوم عشر دقائق في هدوء كامل، وأغلق الهاتف، وقل: «تكلم يا رب فإن عبدك سامع».\"},{\"t\":\"صوت عصفور\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أرسانيوس إن الإنسان إذا أقام في السكينة وسمع صوت عصفور لا يكون في قلبه الهدوء نفسه. الهدوء الداخلي هش، يحتاج حراسة. أغلق اليوم أحد مصادر الضوضاء عمدًا.\",\"p\":\"يا رب، علّمني حراسة الهدوء. اجعلني أسمع صوتك في كل صمت. آمين.\",\"x\":\"قال الأب أرسانيوس إن من سكن السكينة يضطرب قلبه حتى من صوت عصفور، فكم بالأحرى من اهتزاز القصب. الهدوء يُكتسب بجهد. تدريب: ابعد مصدر ضجيج صغير عن يومك لساعة واحدة.\",\"fq\":38}]},\"7-21\":{\"th\":\"نعمة فوق نعمة\",\"m\":[{\"t\":\"ذكر رحمته\",\"ref\":\"المزمور ٩٧ (٩٨) — التاسعة\",\"v\":\"ذكر رحمته ليعقوب وحقه لبيت إسرائيل. نظرت أقاصي الأرض جميعا خلاص إلهنا.\",\"r\":\"ذكر الله رحمته ليعقوب وحقه لبيت إسرائيل، ونظرت أقاصي الأرض خلاص إلهنا. نعمة فوق نعمة تتدفق من غنى المسيح. اكتب اليوم نعمة تلقيتها هذا الأسبوع، واشكره عليها.\",\"p\":\"يا رب، ذكرت رحمتك لنا. أعطني أن أرى نعمك الكثيرة وأشكرك عليها. آمين.\",\"x\":\"يذكر الله رحمته وحقه، وأقاصي الأرض ترى خلاصه. خلاص الله ليس سرًا بل إعلان للجميع. تدريب: شارك أحدًا اليوم بآية عن الخلاص أو بخبرة عن رحمة الله.\"},{\"t\":\"من ملئه أخذنا\",\"ref\":\"يوحنا ١: ١٦\",\"bk\":\"يوحنا\",\"v\":\"ومن ملئه نحن جميعا أخذنا، ونعمة فوق نعمة.\",\"r\":\"«ومن ملئه نحن جميعًا أخذنا، ونعمة فوق نعمة». لا أحيا من رصيد قديم من النعمة، بل من تدفق جديد كل يوم. كل صباح تأتي نعمة فوق التي أخذتها أمس، فلا أخاف من نفاد أو من جفاف.\",\"p\":\"يا رب، من ملئك أخذت نعمة فوق نعمة. أشكرك على عطاياك المتجددة، واجعل قلبي مستعدًا دائمًا لقبولها. آمين.\",\"x\":\"في مقدمة إنجيل يوحنا يعلن أن الكلمة صار جسدًا وحل بيننا ممتلئًا نعمة وحقًا. وهذه الآية تقول إننا ننال من ذلك الملء. وعبارة «نعمة فوق نعمة» تعني نعمة تحل محل نعمة، أو نعمة تضاف إلى نعمة، مثل أمواج البحر التي تتتابع بلا انقطاع. فمن عرف أن المسيح ملؤه لا يفرغ، يتحرر من القلق على المستقبل. والكنيسة تعلّمنا أن الأسرار والصلوات والكلمة قنوات متجددة لهذه النعمة.\\nاقض اليوم لحظات تذكر فيها ثلاث نعم تلقيتها هذا الأسبوع، ثم قل: «شكرًا يا رب على نعمة فوق نعمة».\"},{\"t\":\"التواضع ومخافة الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوحنا الكولوفي إن التواضع ومخافة الله أسمى من كل الفضائل. من تواضع قبل النعمة ونمت فيه. تواضع اليوم في موقف واحد، واترك الدفاع عن نفسك.\",\"p\":\"يا رب، علّمني التواضع ومخافتك. املأني من نعمتك، وأنقذني من كبريائي. آمين.\",\"x\":\"يقول الأب يوحنا الكولوفي إن التواضع ومخافة الله أسمى من كل الفضائل. لأن بلا تواضع تنقلب الفضيلة تكبرًا. تدريب: عند أول نجاح اليوم قل: هذا ليس مني.\",\"fq\":159}]},\"7-22\":{\"th\":\"توبوا قد اقترب الملكوت\",\"m\":[{\"t\":\"لأني مسكين وبائس\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"أمل يا رب أذنك واستمعني، لأني مسكين وبائس أنا. احفظ نفسي لأني بار، يا إلهي خلص عبدك المتكل عليك. ارحمني يا رب، لأني إليك أصرخ اليوم كله.\",\"r\":\"يطلب المرنم أن يميل الرب أذنه لأنه مسكين وبائس، ويصرخ إليه اليوم كله. التوبة أن نأتي إلى الله فقراء. ملكوت السماوات يقترب من القلب المنكسر. قل لله اليوم: ارحمني.\",\"p\":\"يا رب، أنا مسكين وبائس، فاسمعني وارحمني. أعطني توبة صادقة وصراخًا إليك كل اليوم. آمين.\",\"x\":\"يعترف المرنم بأنه مسكين وبائس، وهذا أصدق مدخل للتوبة. الله يميل أذنه لمن يقف أمامه فقيرًا. تدريب: صلِّ الليلة هذه العبارة بصدق: أنا مسكين وبائس فأمل أذنك إليّ.\"},{\"t\":\"قد اقترب ملكوت السماوات\",\"ref\":\"متى ٤: ١٧\",\"bk\":\"متى\",\"v\":\"من ذلك الزمان ابتدأ يسوع يكرز ويقول: «توبوا لأنه قد اقترب ملكوت السماوات».\",\"r\":\"«توبوا لأنه قد اقترب ملكوت السماوات». السبب الأول للتوبة ليس الخوف من العقاب بل قرب الله. والملكوت ليس بعيدًا في السماء فقط، بل اقترب إليّ في المسيح. فأتحول إليه لأنه قريب.\",\"p\":\"يا رب، أتوب إليك لأنك قريب مني. اغفر لي، وأدخلني إلى ملكوتك بنعمتك واجعلني أسير في طريقك. آمين.\",\"x\":\"التوبة في الكتاب المقدس تعني تغيير الاتجاه والذهن، لا مجرد الحزن. وكان يوحنا المعمدان قد نادى بالدعوة نفسها، لكن المسيح يعطيها بعدًا جديدًا: الملكوت قد اقترب بشخصه. فمن يتوب لا يحاول الوصول إلى الله بجهده، بل يلتفت إلى الله الذي جاء إليه. وهذا يجعل التوبة مبهجة. والكنيسة تضع التوبة في بداية كل صلاة، لأنها مفتاح الدخول إلى حضرة الله.\\nاليوم خصص دقيقتين لفحص ضمير سريع، واستدر بالقلب نحو المسيح في خطية معينة تريد أن تتركها.\"},{\"t\":\"كلام العشار\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح الأب أمون أخًا أن يبقى في قلايته وأن يكون في قلبه كلام العشار، فيخلص. التوبة صلاة قصيرة يومية. كرر اليوم: ارحمني يا الله أنا الخاطئ.\",\"p\":\"يا رب، علّمني توبة العشار. ارحمني أنا الخاطئ، وأدخلني إلى ملكوتك. آمين.\",\"x\":\"يوصي الأب أمون من يميل إلى التجوال أن يبقى في قلايته ويأكل قليلًا ويضع في قلبه كلام العشار. الثبات في المكان مع الاعتراف يخلص. تدريب: قل اليوم: يا الله ارحمني أنا الخاطئ، مرات كثيرة.\",\"fq\":62}]},\"7-23\":{\"th\":\"أنتم نور العالم\",\"m\":[{\"t\":\"مثل العريس الخارج من خدره\",\"ref\":\"المزمور الثامن عشر — باكر\",\"v\":\"جعل في الشمس مظلته. وهي مثل العريس الخارج من خدره. تتهلل مثل الجبار الذي يسرع في طريقه.\",\"r\":\"جعل الله في الشمس مظلته وهي مثل العريس الخارج من خدره، تتهلل كالجبار. هكذا يُشرق المؤمن نورًا للعالم. اجعل اليوم عملًا واحدًا يُرى فيه نور المسيح فيك.\",\"p\":\"يا رب، اجعلني نورًا في العالم. أشرق فيّ بنورك، فيرى الناس أعمالي ويمجدون أباك. آمين.\",\"x\":\"الشمس في المزمور كالعريس الخارج من خدره، فرحة ونور. هكذا يشرق المؤمن في العالم. تدريب: ابدأ يومك بفرح ظاهر، وأعط تحية مشرقة لمن تقابله.\"},{\"t\":\"مدينة على جبل\",\"ref\":\"متى ٥: ١٤\",\"bk\":\"متى\",\"v\":\"أنتم نور العالم. لا يمكن أن تخفى مدينة موضوعة على جبل،\",\"r\":\"«أنتم نور العالم. لا يمكن أن تخفى مدينة موضوعة على جبل». المسيح لا يقول: اجتهدوا لتصيروا نورًا، بل يعلن أنكم نور. لأنه نور فيّ، وعلي أن أترك هذا النور يظهر دون خجل ودون استعراض.\",\"p\":\"يا رب، أنت نور العالم، وقد جعلتني نورًا بك. اجعل أعمالي تضيء أمام الناس فيمجدوا أبي الذي في السماوات. آمين.\",\"x\":\"في العظة على الجبل، بعد التطويبات، يعلن الرب هوية تلاميذه: ملح الأرض ونور العالم. والنور وظيفته أن يضيء، لا أن يفتخر بنفسه. فالهدف هو تمجيد الآب لا الذات. والمدينة على الجبل لا تحاول الظهور بل تظهر لأنها في موضعها. وهكذا الكنيسة والمؤمن. اليوم، افعل عملًا حسنًا في العلن بلا استعراض، لتمجد الآب فقط. \\n\"},{\"t\":\"قرية مزينة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أنطونيوس لقرية تبدو جميلة مزينة من الأمام لكن اللصوص يسلبونها من الخلف. النور الحقيقي ليس مظهرًا، بل حياة كاملة. اسأل نفسك اليوم: أي باب خلفي مفتوح في حياتي؟\",\"p\":\"يا رب، احرس كل أبواب قلبي، لا ظاهري فقط بل باطني. اجعلني نورًا حقيقيًا. آمين.\",\"x\":\"يقول الأب أنطونيوس لراهب لم يحتمل الإهانة بعد المديح: أنت تشبه قرية جميلة من الأمام يسلبها اللصوص من الخلف. المدح يكشف هشاشتنا عند أول إساءة. تدريب: اختبر نفسك اليوم: كيف أتصرف إن أُهنت؟\",\"fq\":10}]},\"7-24\":{\"th\":\"عظيم إيمانك\",\"m\":[{\"t\":\"وباسم الرب دعوت\",\"ref\":\"المزمور ١١٤ — التاسعة\",\"v\":\"ضيقا وحزنا وجدت، وباسم الرب دعوت: يا رب نج نفسي. الرب رحيم وصديق وإلهنا يرحم.\",\"r\":\"يجد المرنم ضيقًا وحزنًا فيدعو باسم الرب ويعلن أنه رحيم. الإيمان العظيم يلجأ إلى الله في الضيق ويتواضع. اطلب اليوم من الله شيئًا بإلحاح ولا تتراجع كالمرأة الكنعانية.\",\"p\":\"يا رب، أنا أؤمن فأعن عدم إيماني. علّمني أن أتواضع وأصرخ إليك حتى تستجيب. آمين.\",\"x\":\"يجد المرنم ضيقًا وحزنًا فيدعو باسم الرب. الإيمان العظيم أن ندعوه حين لا نرى مخرجًا. تدريب: عند أول ضيق اليوم، قل: يا رب نجِّ نفسي، قبل أن تحاول الحل.\"},{\"t\":\"عظيم إيمانك\",\"ref\":\"متى ١٥: ٢٨\",\"bk\":\"متى\",\"v\":\"حينئذ أجاب يسوع وقال لها: «يا امرأة، عظيم إيمانك! ليكن لك كما تريدين». فشفيت ابنتها من تلك الساعة.\",\"r\":\"«يا امرأة، عظيم إيمانك! ليكن لك كما تريدين». لم تغضب من الاختبار ولم تنسحب، بل قبلت المكان الأخير بتواضع، فنالت الأول. وهذا إيمان يجمع الثقة بمحبة المسيح مع الاعتراف بعدم الاستحقاق.\",\"p\":\"يا رب، لست مستحقًا لكن أثق في غنى رحمتك. اشفِ ضعفي وضعف أحبائي، وأعطني إيمانًا عظيمًا متواضعًا. آمين.\",\"x\":\"حين قال لها الرب إنه لم يُرسل إلا إلى خراف بيت إسرائيل الضالة، ثم قال إنه ليس حسنًا أن يؤخذ خبز البنين ويطرح للكلاب، أجابت بحكمة: «نعم يا سيد، والكلاب أيضًا تأكل من الفتات». فأقرت بالتواضع وأكدت الثقة بغنى المائدة. فتنازلت عن الكبرياء وطلبت الفتات. وهذا ما نردده في صلاة قبل التناول: «لست مستحقًا». والنتيجة أن المسيح مدحها بكلمة نادرة: «عظيم إيمانك».\\nاليوم، في موقف تشعر فيه بعدم الاستحقاق، قل بثقة: «ولو فتاتًا يا رب»، وانتظر بإيمان.\"},{\"t\":\"يا إله القوات\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب أمون النطروني من تأتيه التجربة أن يقول: يا إله القوات، بصلوات أبي أعتقني. الإيمان يلجأ إلى الله في ساعة التجربة. اختر اليوم صلاة قصيرة تقولها عند الضيق.\",\"p\":\"يا إله القوات، أعتقني من كل تجربة. ثبّت إيماني وعلّمني أن ألجأ إليك سريعًا. آمين.\",\"x\":\"ينصح الأب أمون النطروني من تأتيه التجربة أن يقول: يا إله القوات بصلوات أبي أعتقني. كلمة قصيرة مع شفاعة تكفي. تدريب: احفظ هذه الصلاة، وأعدّها عند أي تجربة اليوم.\",\"fq\":69}]},\"7-25\":{\"th\":\"ارحمنا\",\"m\":[{\"t\":\"ارحمنا يا رب ارحمنا\",\"ref\":\"المزمور ١٢٢ (١٢٣) — الغروب\",\"v\":\"ارحمنا يا رب ارحمنا، فإننا كثيرا ما امتلأنا هوانا، وكثيرا ما امتلأت نفوسنا العار اردده على المخصبين والهوان على المتعظمين هلليلويا.\",\"r\":\"تتكرر صرخة ارحمنا لأن النفس شبعت هوانًا. هذه هي صلاة الأعمى وصلاة الكنيسة كلها. صلِّ اليوم «يا رب ارحم» بلا انقطاع في ساعة واحدة.\",\"p\":\"يا رب، ارحمنا ارحمنا. اسمع صراخ ضعفنا، ولا تحجب وجهك عنا. آمين.\",\"x\":\"تتكرر كلمة «ارحمنا» لأن النفس شبعت هوانًا. هذه هي الصلاة التي نصليها في كل قداس: كيرياليسون. تدريب: صلِّ ببطء اليوم: يا رب ارحم، أربعين مرة، وتأمل في معناها.\"},{\"t\":\"يا ابن داود ارحمني\",\"ref\":\"مرقس ١٠: ٤٧\",\"bk\":\"مرقس\",\"v\":\"فلما سمع أنه يسوع الناصري، ابتدأ يصرخ ويقول: «يا يسوع ابن داود، ارحمني!»\",\"r\":\"«فانتهره كثيرون ليسكت، فصرخ أكثر كثيرًا: يا ابن داود، ارحمني!». أحيانًا تحاول الظروف أو الناس أو حتى أفكاري أن تسكتني عن الصلاة. لكن الحاجة الحقيقية تجعلني أصرخ أكثر.\",\"p\":\"يا ابن داود، ارحمني. لا تدعني أسكت عن الصلاة مهما انتهرني الناس، وافتح عيني لأبصر نورك. آمين.\",\"x\":\"كان برتيماوس جالسًا على الطريق يستعطي، وسمع أن يسوع الناصري مجتاز. فصرخ بعبارة صارت صلاة الكنيسة: ارحمني. وانتهره كثيرون لكنه لم يتوقف. فوقف يسوع وقال: ادعوه. وعندما دُعي ألقى رداءه وقفز وجاء. وسأله الرب: ماذا تريد أن أفعل لك؟ فقال: أن أبصر. فصلاة يسوع المعروفة «يا ربي يسوع المسيح ارحمني» هي صدى هذه الصرخة. وهي تحول القلب إلى مكان رحمة.\\nردد اليوم صلاة يسوع بهدوء عدة مرات: «يا رب يسوع المسيح ارحمني أنا الخاطئ».\"},{\"t\":\"ثلاثة أيام\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إنه إذا تاب الإنسان من كل قلبه وتوقف عن الخطيئة فإن الله يقبله حتى في ثلاثة أيام. الرحمة أقرب مما نظن. ابدأ اليوم بتوبة صغيرة صادقة.\",\"p\":\"يا رب، اقبل توبتي مهما تأخرت. ارحمني وأعدني إلى حضنك. آمين.\",\"x\":\"قال الأب بيمن لأخ أراد أن يتوب ثلاث سنين: إذا تاب الإنسان من كل قلبه وتوقف عن الخطية فإن الله يقبله حتى في ثلاثة أيام. فالتوبة تُقاس بصدقها لا بطولها. تدريب: لا تؤجل توبة اليوم بحجة تحتاج وقتًا.\",\"fq\":316}]},\"7-26\":{\"th\":\"ثقة الرجاء\",\"m\":[{\"t\":\"الاتكال على الرب خير\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"الاتكال على الرب خير من الاتكال على البشر، الرجاء بالرب خير من الرجاء بالرؤساء.\",\"r\":\"الاتكال على الرب خير من الاتكال على البشر، والرجاء به خير من الرجاء بالرؤساء. ثقة الرجاء ثابتة لأن الله أمين. ضع اليوم أمرًا يقلقك في يد الله، ولا تحمله وحدك.\",\"p\":\"يا رب، أنت رجائي وثقتي. علّمني أن أتكل عليك وحدك، فلا أخزى أبدًا. آمين.\",\"x\":\"الاتكال على الرب خير من الاتكال على البشر وعلى الرؤساء. لا يلغي هذا التعاون بل يرتب الأولويات. تدريب: اذكر من تتكل عليه أكثر من الله، وسلّم أمرًا واحدًا له وحده اليوم.\"},{\"t\":\"إن تمسكنا بثقة الرجاء\",\"ref\":\"العبرانيين ٣: ٦\",\"bk\":\"العبرانيين\",\"v\":\"وأما المسيح فكابن على بيته. وبيته نحن إن تمسكنا بثقة الرجاء وافتخاره ثابتة إلى النهاية.\",\"r\":\"«وبيته نحن إن تمسكنا بثقة الرجاء وافتخاره ثابتة إلى النهاية». أنا جزء من بيت الله. والتمسك بالرجاء ليس عنادًا بل ثقة في المسيح الذي لا يخذل. فأمسك به حين تتغير الظروف.\",\"p\":\"يا رب، ثبّتني في بيتك بثقة الرجاء. أعطني أن أتمسك بك إلى النهاية مهما تغيرت الأيام. آمين.\",\"x\":\"الرسالة إلى العبرانيين كتبت لمؤمنين من أصل يهودي واجهوا ضغوطًا وكانوا يميلون للتراجع. فيذكّرهم الكاتب أن المسيح أعظم من موسى، لأن موسى كان أمينًا كخادم في البيت، والمسيح كابن على بيته. ثم يدعوهم للثبات في الرجاء. والتمسك لا يعني الجهد المنفرد بل الالتصاق بالمسيح. ونرى هذا في حياة الشهداء والنساك الذين ثبتوا إلى النهاية. فالطريق طويل، لكن الرجاء يحمل المسافر.\\nحدد اليوم مجال ضعف في رجائك، وسلّمه للمسيح، وقل: «أتمسك بك إلى النهاية».\"},{\"t\":\"لا نيأس من خلاصنا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يؤكد الأب بولس البسيط صلاح الله لمن يهرعون إليه بصدق، فلا نيأس من خلاصنا لأن خطايانا تُطهَّر وتصير بيضاء كالثلج. الرجاء يبدأ حين نعود. عد اليوم إلى الله، مهما كان ماضيك.\",\"p\":\"يا رب، لا أيأس من خلاصي. طهّرني وبيّضني، وأهّلني لخيرات أورشليم السماوية. آمين.\",\"x\":\"يؤكد الأب بولس البسيط صلاح الله لمن يهرعون إليه بصدق، فلا نيأس من خلاصنا. وسرد قصة أخ تاب قبوله الله. تدريب: لا تقل اليوم: لا أمل لي، بل قل: يقبلني.\",\"fq\":479}]},\"7-27\":{\"th\":\"الحكمة من الرب\",\"m\":[{\"t\":\"جيل المستقيمين يبارك\",\"ref\":\"المزمور ١١١ (١١٢) — التاسعة\",\"v\":\"جيل المستقيمين يبارك. مجد وغنى في بيته؛ وبره يدوم إلى الأبد.\",\"r\":\"جيل المستقيمين يبارك، ومجد وغنى في بيته وبره يدوم. الحكمة ثمرة الاستقامة ومخافة الرب. اطلب اليوم حكمة لقرار ينتظرك، واسأل مشورة أمينة.\",\"p\":\"يا رب، اهدني بحكمتك. اجعلني مستقيمًا فيبارك الله نسلي، ويدوم برّك في بيتي. آمين.\",\"x\":\"جيل المستقيمين يبارك، فالبركة تنتقل بين الأجيال. ما نعيشه اليوم يصير إرثًا. تدريب: اترك لأولادك أو من حولك سلوكًا يتذكرونه بالخير.\"},{\"t\":\"الرب يعطي حكمة\",\"ref\":\"الأمثال ٢: ٦\",\"bk\":\"الأمثال\",\"v\":\"لأن الرب يعطي حكمة. من فمه المعرفة والفهم.\",\"r\":\"«لأن الرب يعطي حكمة. من فمه المعرفة والفهم». أحيانًا أحتار في قرار أو علاقة أو أولوية، وأظن أنني أحتاج ذكاءً أكبر. لكن الحكمة تأتي من فم الرب، وتُطلب بالسؤال والإصغاء.\",\"p\":\"يا رب، أنت تعطي حكمة. امنحني حكمة من فمك في قراراتي، وعلّمني أن أطلبها بتواضع وأسمعها بانتباه. آمين.\",\"x\":\"في الأصحاح الثاني من الأمثال يدعو الأب ابنه أن يقبل أقواله ويخبئ وصاياه، ويميل بأذنه إلى الحكمة، ويطلبها كالفضة، ويبحث عنها كالكنوز. فالحكمة تحتاج إلى بحث جاد. وعندئذ يعد بأنه سيفهم مخافة الرب. ثم تأتي هذه الآية لتؤكد أن مصدرها الله. وقد قال يعقوب: «إن كان أحدكم تعوزه حكمة فليطلب من الله الذي يعطي الجميع بسخاء». فالطلب والإصغاء هما الطريق.\\nاطلب اليوم من الله حكمة في أمر محدد، ثم اجلس هادئًا خمس دقائق دون أن تتكلم، لتسمع.\"},{\"t\":\"الفضائل الثلاث\",\"ref\":\"\",\"v\":\"\",\"r\":\"يتأسف الأب إيليا أن فضائل آبائنا كانت اللاقنية والإمساك والوداعة، أما الآن فيسود الطمع والشراهة والوقاحة. الحكمة أن نعود إلى البسيط. ابدأ اليوم بفضيلة منها: الوداعة.\",\"p\":\"يا رب، أعد إلينا بساطة الآباء. اغرس فينا الوداعة والاكتفاء. آمين.\",\"x\":\"يتأسف الأب إيليا لأن فضائل الآباء الثلاث، اللاقنية والإمساك والوداعة، تراجعت أمام الطمع والشراهة والوقاحة. تدريب: اختر فضيلة من الثلاث وعشها اليوم.\",\"fq\":130}]},\"7-28\":{\"th\":\"ملجأنا\",\"m\":[{\"t\":\"رب القوات معنا\",\"ref\":\"المزمور ٤٥ (٤٦) — الثالثة\",\"v\":\"الرب إله القوات معنا، ناصرنا هو إله يعقوب.\",\"r\":\"رب القوات معنا، إله يعقوب ناصر لنا. هو ملجأنا لأنه حاضر معنا. حين تخاف اليوم من أمر قل بصوت مسموع: رب القوات معنا.\",\"p\":\"يا رب القوات، كن معنا وملجأنا. احفظنا في ظلك، ولا تدع الخوف يغلبنا. آمين.\",\"x\":\"«الرب معنا» عبارة لا تتوقف عن البشارة، ومن تعني عمانوئيل. معه نواجه الخوف. تدريب: ردد عند أول قلق: رب القوات معنا.\"},{\"t\":\"ملجأ في أزمنة الضيق\",\"ref\":\"المزامير ٩: ٩\",\"bk\":\"المزامير\",\"v\":\"ويكون الرب ملجأ للمنسحق. ملجأ في أزمنة الضيق.\",\"r\":\"«ويكون الرب ملجأ للمنسحق. ملجأ في أزمنة الضيق». حين ينكسر قلبي أو تضيق بي الأمور، لا أبحث عن ملجأ بعيد، فالرب نفسه هو المأوى. وهو يستقبل المنسحقين ولا يرفض أحدًا.\",\"p\":\"يا رب، أنت ملجأي في أزمنة الضيق. احتضن قلبي المنسحق، وعلّمني أن آوي إليك في كل حين. آمين.\",\"x\":\"المزمور التاسع مزمور شكر لله على انتصاره للمظلومين. والمنسحق هو المسحوق بالضيق أو الظلم. والكلمة «ملجأ» تعني موضعًا مرتفعًا آمنًا. فالله ليس فقط ينقذ بل يحتضن. وفي الآية التالية يقول: «ويتكل عليك العارفون اسمك لأنك لم تترك طالبيك يا رب». فمعرفة اسم الله تولد الاتكال. وفي كل زمن ضيق نعود إلى هذا الوعد.\\nاذكر اليوم موقفًا شعرت فيه بالانسحاق ووجدت الله ملجأً، واشكره بصوت عالٍ.\"},{\"t\":\"ثلاث حروب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أنطونيوس إن من يقيم في السكينة يتحرر من حروب السمع والكلام والنظر. الملجأ الحقيقي هو الله والسكينة معه. أغلق اليوم عينيك لحظات عن شيء يشتتك.\",\"p\":\"يا رب، احفظ حواسي. اجعل سمعي ونظري ولساني لك وحدك. آمين.\",\"x\":\"يقول الأب أنطونيوس إن من يقيم في السكينة يتحرر من حروب السمع والكلام والنظر، وتبقى حرب واحدة. السكينة تقلل جبهات الحرب. تدريب: قلل اليوم مصدرًا من مصادر السمع أو النظر الذي يشتتك.\",\"fq\":8}]},\"7-29\":{\"th\":\"شبع النفس\",\"m\":[{\"t\":\"وتبصر خيرات أورشليم\",\"ref\":\"المزمور ١٢٧ (١٢٨) — الغروب\",\"v\":\"يباركك الرب من صهيون، وتبصر خيرات أورشليم جميع أيام حياتك: وترى بني بنيك، والسلام على إسرائيل.\",\"r\":\"يعد المزمور بالبركة والخير والسلام لمن يتقي الرب. النفس تشبع حين تعود إلى الله. قبل أن تشتهي شيئًا اليوم، اسأل: هل هذا ما تحتاجه روحي فعلًا؟\",\"p\":\"يا رب، أشبع نفسي من صلاحك. باركني وأعطني أن أبصر خيراتك وسلامك. آمين.\",\"x\":\"يعد المزمور من يتقي الرب بالبركة وخيرات أورشليم وبنين وسلام. الوعد يشمل البيت كله. تدريب: بارك بيتك اليوم بصلاة جماعية قصيرة أو بكلمة طيبة.\"},{\"t\":\"أشبع نفسًا مشتهية\",\"ref\":\"المزامير ١٠٧: ٩\",\"bk\":\"المزامير\",\"v\":\"لأنه أشبع نفسا مشتهية وملأ نفسا جائعة خبزا،\",\"r\":\"«لأنه أشبع نفسًا مشتهية، وملأ نفسًا جائعة خبزًا». في داخلي جوع أحاول إشباعه بأشياء كثيرة لا تكفي. والله وحده يملأ النفس المشتهية، فأقبل إليه بجوعي ولا أخجل. فهو الذي يعطي الشبع الحقيقي لنفسي الجائعة كل يوم.\",\"p\":\"يا رب، أشبعني من خيراتك ومن رحمتك. املأ جوع نفسي الحقيقي بك أنت، يا خبز الحياة. آمين.\",\"x\":\"المزمور ١٠٧ يروي أربع قصص: ضالين في البرية، وأسرى في الظلمة، ومرضى بسبب تمردهم، وبحارة في عاصفة. وكل مجموعة صرخت إلى الرب فخلصهم. ثم يردد المرنم: «فليحمدوا الرب على رحمته وعجائبه لبني آدم». وهذه الآية هي في القصة الأولى، حيث وجدوا مدينة سكن بعد التيه. فالله يعطي مأوى وطعامًا وخلاصًا. وعند الكنيسة نجد في الإفخارستيا الخبز الحقيقي الذي يشبع.\\nاقرأ المزمور ١٠٧ اليوم، واختر القصة الأقرب إلى حالك، واشكر الله على نجاته.\"},{\"t\":\"الشبع الممقوت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن الشبع الجسدي ممقوت أمام الرب. وشبع النفس يأتي من الله لا من الطعام. قلل اليوم من طعامك قليلًا، وارفع الفارق صلاة.\",\"p\":\"يا رب، أشبع روحي بك. ساعدني أن أضبط جسدي، فلا يعيق صلاتي. آمين.\",\"x\":\"يقول الأب بيمن إن الشبع الجسدي ممقوت أمام الرب، فالنفس لا تشبع بالطعام. تدريب: كل اليوم أقل قليلًا مما تشتهي، وقدم الفرق شكرًا لله.\",\"fq\":336}]},\"7-30\":{\"th\":\"الظل والنور\",\"m\":[{\"t\":\"من حيث يأتي عوني\",\"ref\":\"المزمور ١٢٠ (١٢١) — الغروب\",\"v\":\"رفعت عيني إلى الجبال، من حيث يأتي عوني. معونتي من عند الرب الذي صنع السماء والأرض.\",\"r\":\"أرفع عيني إلى الجبال من حيث يأتي عوني، ومعونتي من عند الرب الذي صنع السماء والأرض. ظل الله وراحتنا فيه نور لطريقنا. ارفع عينيك الآن إلى السماء لحظة، ثم عد إلى عملك.\",\"p\":\"يا رب، معونتي منك. استرني في ظل جناحيك، وأنر طريقي. آمين.\",\"x\":\"يرفع المرنم عينيه إلى الجبال، لكن معونته من خالق السماء والأرض لا من الجبال. فالنظر إلى العلاء يوجه إلى الله. تدريب: ارفع عينيك اليوم إلى السماء ثلاث مرات واذكر: معونتي من عند الرب.\"},{\"t\":\"مثل حدقة العين\",\"ref\":\"المزامير ١٧: ٨\",\"bk\":\"المزامير\",\"v\":\"احفظني مثل حدقة العين. بظل جناحيك استرني\",\"r\":\"«احفظني مثل حدقة العين. بظل جناحيك استرني». حدقة العين أرق ما في الجسد وأشد ما نحميه. هكذا يحفظني الله. فلا أخاف من أني صغير أو ضعيف، فأنا في حماية حنانه.\",\"p\":\"يا رب، احفظني مثل حدقة العين، واسترني بظل جناحيك من كل شر، فأنا في حضنك آمن. آمين.\",\"x\":\"المزمور ١٧ صلاة داود وهو مطارد من الأعداء. يطلب العدل من الله ويدعوه أن يفحص قلبه. ثم يطلب الحفظ. صورة حدقة العين مأخوذة من سفر التثنية، حيث يقول الله عن شعبه: «صانه مثل حدقة عينه». وصورة الجناحين تتكرر في الكتاب: الطائر الذي يظلل فراخه. فالله حنون وقوي معًا. قبل أن تنام الليلة، ضع نفسك بين يدي الله وقل: «احفظني مثل حدقة العين». \\n\"},{\"t\":\"اهرب واصمت واهدأ\",\"ref\":\"\",\"v\":\"\",\"r\":\"سمع الأب أرسانيوس صوتًا يقول له: اهرب واصمت واهدأ، لأن هذه جذور عدم الخطيئة. الظل الذي نحتمي به هو الهدوء مع الله. اهرب اليوم من ضجيج واحد، واصمت قليلًا.\",\"p\":\"يا رب، قدني إلى هدوء لا يزعجه شيء. علّمني أن أصمت لأسمعك. آمين.\",\"x\":\"سمع الأب أرسانيوس صوتًا يقول: اهرب واصمت واهدأ، لأن هذه جذور عدم الخطية. هذه ثلاث خطوات: ابتعاد وصمت وسكون. تدريب: خصص اليوم دقائق للصمت والسكون بعيدًا عن الناس.\",\"fq\":24}]},\"7-31\":{\"th\":\"شكر الغروب\",\"m\":[{\"t\":\"اقبل تمجيدنا\",\"ref\":\"تحليل الغروب\",\"v\":\"اللهم اقبل تمجيدنا هذا الذي صار الآن. هب لنا في هذه الليلة المقبلة سلامة بغير ألم ولا قلق ولا تعب.\",\"r\":\"نختم الشهر بتمجيد الغروب وشكر على يوم مضى. اجلس الليلة دقائق وراجع أسبوعك وقدم شكرك على كل ما أعطاك. ثم اطلب ليلة بسلام.\",\"p\":\"يا رب، اقبل شكري. هب لي ليلة هادئة بلا قلق، وأيقظني إلى يوم جديد في نعمتك. آمين.\",\"x\":\"في صلاة الغروب نطلب سلامة بلا ألم ولا قلق ولا تعب لليلة القادمة، فالنوم بركة. وتجمع تسبحة الغروب بين الشكر على ما مضى والطلب لما يأتي. تدريب: اختم يومك بقول: اللهم اقبل تمجيدنا، ثم سلّم الغد.\"},{\"t\":\"أشبعنا بالغداة\",\"ref\":\"المزامير ٩٠: ١٤\",\"bk\":\"المزامير\",\"v\":\"أشبعنا بالغداة من رحمتك، فنبتهج ونفرح كل أيامنا.\",\"r\":\"«أشبعنا بالغداة من رحمتك، فنبتهج ونفرح كل أيامنا». أبدأ الصباح بالقلق أو بالتفكير في المهام، لكن موسى يعلمني أن أبدأه بالشبع من رحمة الله. وعندئذ يخرج الفرح عفويًا لأيامي كلها.\",\"p\":\"يا رب، أشبعنا بالغداة من رحمتك فنبتهج ونفرح كل أيامنا. وثبّت عمل أيدينا لمجد اسمك. آمين.\",\"x\":\"المزمور ٩٠ هو صلاة موسى الوحيدة في المزامير. وفيه يقر بقصر الحياة وهشاشة الإنسان أمام أبدية الله: «علّمنا إحصاء أيامنا». ثم يطلب في الآية ١٤ أن يشبعنا بالغداة، أي في الصباح. فالتعامل مع قصر العمر لا يقود إلى اليأس بل إلى اختيار الرحمة أولًا. وهذه الآية تدعونا لأن نبدأ كل يوم بالصلاة قبل أن ننشغل. وتنتهي بطلب أن يثبّت الله عمل أيدينا.\\nغدًا صباحًا، قبل أن تفتح الهاتف، قل: «أشبعني يا رب من رحمتك»، وابتسم للنهار.\"},{\"t\":\"أشكرك ربي\",\"ref\":\"\",\"v\":\"\",\"r\":\"في مرض الأب أرسانيوس قال: أشكرك ربي لأنك أهلتني أن آخذ حسنة من أجل اسمك. هكذا يشكر القلب في الضعف. اشكر الله الليلة على ما لم تفهمه من يومك.\",\"p\":\"يا رب، أشكرك على كل ما كان. علّمني أن أشكر في الضعف كما في القوة. آمين.\",\"x\":\"قال الأب أرسانيوس وهو مريض: أشكرك ربي لأنك أهلتني أن آخذ حسنة من أجل اسمك. حتى في الضعف رأى حسنة. تدريب: اشكر اليوم على عطية صغيرة وصلت إليك في وقت ضعف.\",\"fq\":37}]},\"8-1\":{\"th\":\"هلم نرجع إلى الرب\",\"m\":[{\"t\":\"فلتدخل طلبتي إلى حضرتك\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء الثاني والعشرون · صلاة الستار\",\"v\":\"فلتدن وسيلتي قدامك يا رب، كقولك فهمني. فلتدخل طلبتي إلى حضرتك يا رب، ككلمتك أحيني.\",\"r\":\"يطلب المرنم أن تدنو وسيلته من الله وأن تدخل طلبته إلى حضرته. الرجوع إلى الرب يبدأ بطلب فهم وحياة منه. ابدأ اليوم بالجملة البسيطة: هلم نرجع إلى الرب، وحدد شيئًا واحدًا تعود عنه.\",\"p\":\"يا رب، لتدن وسيلتي قدامك ولتدخل طلبتي إلى حضرتك. أرجعني إليك وأحيني ككلمتك. آمين.\",\"x\":\"هذا الجزء من المزمور ١١٨ نصليه في صلاة الستار، وفيه طلب مزدوج: أن تقترب وسيلتنا من الله، وأن تدخل طلبتنا إلى حضرته. ونطلب في الحالتين الفهم والحياة. تدريب: قبل أن تنام قل: أفهمني يا رب وأحيني، ثم اذكر طلبة واحدة.\"},{\"t\":\"هو افترس فيشفينا\",\"ref\":\"هوشع ٦: ١\",\"bk\":\"هوشع\",\"v\":\"هلم نرجع إلى الرب لأنه هو افترس فيشفينا، ضرب فيجبرنا.\",\"r\":\"«هلم نرجع إلى الرب، لأنه هو افترس فيشفينا، ضرب فيجبرنا». حتى حين أتألم من نتائج خطاياي، لا أبتعد عن الله بل أرجع إليه، لأن الذي سمح بالجرح هو الذي يضمده. فالتأديب عنده بداية الشفاء لا نهاية الرجاء.\",\"p\":\"يا رب، هلم نرجع إليك لأنك أنت الذي تشفي وتجبر. اقبلني في توبتي، وضمد جراحي بحنانك الأبوي. آمين.\",\"x\":\"في سفر هوشع يظهر قلب الله الأب المجروح من خيانة شعبه، وفي الوقت نفسه المشتاق إلى عودتهم. ودعوة «هلم نرجع» دعوة جماعية، فالتوبة تبدأ من فرد لكنها تمتد إلى الجماعة. والفعلان «افترس» و«ضرب» يتبعهما «شفى» و«جبر»، فنهاية الطريق الإلهي هي الرحمة. وهذا ما نراه في ابن الضال الذي رجع فاستقبله أبوه. وتبدأ الكنيسة شهر أغسطس بالاستعداد لصوم العذراء، وهو فرصة للرجوع.\\nاليوم، اكتب جرحًا في حياتك الروحية وقل فيه: «يا رب أنت الذي تجبر، فأرجع إليك».\"},{\"t\":\"التوبة أمامك\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب لوط لأخ سقط: تشجع يا أخي فالتوبة أمامك، اجلس في الكهف وأنا أحتمل معك نصف الخطية. الرجوع إلى الله يحتاج رفيقًا يشجع. شجّع اليوم أخًا تعثر بدلًا من أن تحكم عليه.\",\"p\":\"يا رب، افتح أمامي باب التوبة. وأعطني أن أشجع من سقط حتى يقوم، كما شجعتني أنت. آمين.\",\"x\":\"قال الأب لوط لأخ سقط في زلة عظيمة: تشجع فالتوبة أمامك، وأنا أحتمل معك نصف الخطية. الأب لم يخفف الخطية بل حمل معه ثقلها. تدريب: ادعم اليوم من سقط بحضورك وصلاتك، لا بكلام الوعظ.\",\"fq\":229}]},\"8-2\":{\"th\":\"قلب جديد\",\"m\":[{\"t\":\"تحيا نفسي وتسبحك\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء الثاني والعشرون · صلاة الستار\",\"v\":\"اشتقت إلى خلاصك يا رب. وناموسك هو تلاوتي. تحيا نفسي وتسبحك.\",\"r\":\"يشتاق المرنم إلى خلاص الرب ويجعل ناموسه تلاوته، فتحيا نفسه وتسبح. القلب الجديد عطية يعطيها الله لمن يشتاق إليها. اقرأ اليوم آية واحدة بشوق وقل: أعطني قلبًا جديدًا.\",\"p\":\"يا رب، اشتقت إلى خلاصك. اخلق فيّ قلبًا جديدًا، واجعل ناموسك تلاوتي، فتحيا نفسي وتسبحك. آمين.\",\"x\":\"يجعل المرنم ناموس الله تلاوته، أي مادة حديثه اليومي، فتحيا نفسه وتسبح. الشوق إلى الخلاص يغذي بالكلمة. تدريب: اجعل لنفسك آية تتلوها اليوم عند كل انتقال من مكان إلى آخر.\"},{\"t\":\"قلبًا جديدًا\",\"ref\":\"حزقيال ٣٦: ٢٦\",\"bk\":\"حزقيال\",\"v\":\"وأعطيكم قلبا جديدا، وأجعل روحا جديدة في داخلكم، وأنزع قلب الحجر من لحمكم وأعطيكم قلب لحم.\",\"r\":\"«وأعطيكم قلبًا جديدًا، وأجعل روحًا جديدة في داخلكم، وأنزع قلب الحجر من لحمكم وأعطيكم قلب لحم». لا يطلب الله تجميل القلب بل استبداله. وأنا أحتاج أن أسمح له بأن ينزع قساوتي ويعطيني حساسية جديدة.\",\"p\":\"يا رب، أعطني قلبًا جديدًا وروحًا جديدة. انزع قساوة قلبي وأعطني قلبًا حيًا يستجيب لمحبتك وكلمتك. آمين.\",\"x\":\"قيل هذا الوعد لشعب سُبي بسبب خطاياه، وكانوا يشعرون باليأس. فجاء حزقيال برسالة نقية: الله يتدخل بنفسه ويغير الداخل. وقلب الحجر هو القلب القاسي الذي لا يتأثر بكلمة الله ولا بألم الآخرين. أما قلب اللحم فحي ومرن ومتجاوب. وبعد الآية يعد بأنه يجعل روحه في داخلنا فنسلك في فرائضه. فالتوبة ليست جهدًا بشريًا فقط بل هبة روح جديد. وهذا ما نناله في المعمودية والميرون.\\nصلِّ اليوم صلاة قصيرة: «يا رب انزع قسوتي وأعطني قلبًا يتأثر»، وانتبه إلى أول شخص يحتاج حنانك.\"},{\"t\":\"ينابيع مياه\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سينكليتيكي: مثّل العشار لئلا تدان مع الفريسي، وآثر وداعة موسى لتحول قلبك الصلد إلى ينابيع مياه. القلب القاسي يلين بالوداعة. اختر اليوم رد فعل لين في موقف يضايقك.\",\"p\":\"يا رب، حوّل قلبي الصلد إلى ينابيع مياه. امنحني وداعة موسى وتوبة العشار. آمين.\",\"x\":\"تنصح الأم سينكليتيكي أن نمثّل العشار لئلا ندان مع الفريسي، ونختار وداعة موسى ليتحول القلب الصلد إلى ينابيع. فالقلب القاسي يلين بالاتضاع. تدريب: لا تدافع عن نفسك اليوم في موقف بسيط.\",\"fq\":539}]},\"8-3\":{\"th\":\"ارجع إلى الرب\",\"m\":[{\"t\":\"انظر إلى مذلتي ونجني\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء العشرون · صلاة الستار\",\"v\":\"انظر إلى مذلتي وأنقذني، فإني لم أنس ناموسك. احكم لي في دعواي ونجني.\",\"r\":\"يطلب المرنم من الله أن ينظر إلى مذلته وينجيه، لأنه لم ينس ناموسه. الرجوع إلى الله يكون من مكان الضعف لا من مكان القوة. ارجع اليوم إلى الرب بصلاة صادقة واذكر له ما يوجع قلبك.\",\"p\":\"يا رب، انظر إلى مذلتي وأنقذني، واحكم لي في دعواي ونجني. أرجع إليك فاقبلني. آمين.\",\"x\":\"يطلب المرنم أن ينظر الله إلى مذلته وينقذه لأنه لم ينس ناموسه. الذي يحفظ الوصية في الضعف يجد عونًا. تدريب: اطلب النجاة اليوم من موضع ضعف محدد، وقل: لم أنس ناموسك.\"},{\"t\":\"قد تعثرت بإثمك\",\"ref\":\"هوشع ١٤: ١\",\"bk\":\"هوشع\",\"v\":\"ارجع يا إسرائيل إلى الرب إلهك، لأنك قد تعثرت بإثمك.\",\"r\":\"«ارجع يا إسرائيل إلى الرب إلهك، لأنك قد تعثرت بإثمك». كلمة «تعثرت» رقيقة، فهي لا تقول سقطت ولا هلكت. الله يرى ضعفي كعثرة تحتاج إلى قيام، ويقول لي: ارجع، فلا تيأس من نفسك.\",\"p\":\"يا رب، ها أنا أرجع إليك وقد تعثرت بإثمي. ارفع عني كل إثم، وأقمني بنعمتك لأسير في طريقك. آمين.\",\"x\":\"الأصحاح الأخير من سفر هوشع ينتهي بدعوة جميلة إلى التوبة وبوعد من الله: «أشفي ارتدادهم، أحبهم فضلًا». فالتوبة تتضمن كلامًا وصلاة واعترافًا. وهي في الأصل مبادرة إلهية. والتعثر لا يعني السقوط النهائي، بل لحظة يمكن القيام بعدها بيد الله. قل اليوم لله بكلماتك الخاصة: «ارفع كل إثم»، واذكر إثمًا محددًا أمامه. \\n\"},{\"t\":\"الطريق الذي سلّمه الآباء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن من أراد التحرر من خطاياه يتخلص منها بالبكاء، وهو الطريق الذي سلمه الكتاب المقدس والآباء. الدموع تغسل ما لا يغسله الكلام. اجلس اليوم دقائق وابك أمام الله على خطية واحدة.\",\"p\":\"يا رب، أعطني دموع التوبة. اغسلني بها، واقبلني ابنًا راجعًا إليك. آمين.\",\"x\":\"يقول الأب بيمن إن من أراد التحرر من خطاياه يتخلص منها بالبكاء، لأنه الطريق الذي سلمه الكتاب والآباء. البكاء ليس حزنًا بلا رجاء بل غسل. تدريب: خصص اليوم لحظة تبكي فيها على خطية بصدق بين يدي الله.\",\"fq\":397}]},\"8-4\":{\"th\":\"الصوم المقبول\",\"m\":[{\"t\":\"برحمتك أحيني\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء العشرون · صلاة الستار\",\"v\":\"انظر يا رب، فإني أحببت وصاياك. برحمتك يا رب أحيني.\",\"r\":\"يعلن المرنم محبته لوصايا الله ويطلب الحياة برحمته. الصوم الذي يريده الله يبدأ بالمحبة للوصية ثم يمتد إلى العطاء. قدّم اليوم صومًا صغيرًا وأعطِ ما وفرته لمحتاج.\",\"p\":\"انظر يا رب فإني أحببت وصاياك، وبرحمتك أحيني. اجعل صومي مقبولًا، وعلّمني أن أفتح يدي للفقراء. آمين.\",\"x\":\"يعلن المرنم محبته لوصايا الله ويطلب الحياة برحمته، فالوصية محبوبة لا مفروضة. هذا ينير معنى الصوم: وصية نحبها. تدريب: اختر وصية تثقل عليك وحاول أن تحبها اليوم، وقل: أحببت وصاياك.\"},{\"t\":\"أن تكسر للجائع خبزك\",\"ref\":\"إشعياء ٥٨: ٧\",\"bk\":\"إشعياء\",\"v\":\"أليس أن تكسر للجائع خبزك، وأن تدخل المساكين التائهين إلى بيتك؟ إذا رأيت عريانا أن تكسوه، وأن لا تتغاضى عن لحمك.\",\"r\":\"«أن تكسر للجائع خبزك، وأن تدخل المساكين التائهين إلى بيتك». الصوم الذي يرضي الله لا ينتهي بالامتناع عن الطعام بل يمتد إلى العطاء. وما أوفره بصيامي يجب أن يصل إلى يد محتاج.\",\"p\":\"يا رب، علّمني الصوم الذي ترضى به. اجعل صومي رحمة وعطاءً، وافتح قلبي وبيتي للمحتاجين. آمين.\",\"x\":\"الشعب في زمن إشعياء كان يصوم ويتساءل: لماذا لا ينظر الله إلينا؟ فجاءهم الجواب: في يوم صومكم تجدون سروركم وتسخرون كل عمالكم، وتصومون للخصومة والنزاع. وأعلن الله ما يريده: حل قيود الظلم، وإطلاق المسحوقين، ومشاركة الخبز والبيت والكساء. فالصوم ممارسة روحية تنتج رحمة. وفي كنيستنا يرتبط الصوم دائمًا بالصدقة والصلاة. وصوم العذراء القادم فرصة لأن يتحول الامتناع إلى عطاء.\\nحدد اليوم مبلغًا أو وجبة توفرها وتعطيها لمحتاج، كجزء من صومك.\"},{\"t\":\"ضبط الأفكار\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينقل الأب لوكيوس قول إشعياء إن إحناء العنق ليس هو الصوم المقبول، بل الأفضل ضبط الأفكار الشريرة. الصوم الحقيقي صراع مع الفكر قبل الجسد. اختر اليوم فكرًا شريرًا يتكرر عليك وقاومه بصلاة.\",\"p\":\"يا رب، علّمني صومًا يضبط أفكاري. نقِّ ذهني، واجعل صومي ثمرة محبة لا مظهرًا. آمين.\",\"x\":\"يشير الأب لوكيوس إلى قول إشعياء إن إحناء العنق ليس صومًا مقبولًا، بل الأفضل ضبط الأفكار الشريرة. فالصوم الحقيقي في الداخل. تدريب: صم اليوم عن فكر واحد يؤذيك، وقدم هذا صومك لله.\",\"fq\":231}]},\"8-5\":{\"th\":\"الصلاة في الخفاء\",\"m\":[{\"t\":\"اهدني إلى طريقك\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"وأمجد اسمك إلى الأبد.\",\"r\":\"يطلب المرنم الهداية ويعترف من كل قلبه ويمجد اسم الرب. الصلاة في الخفاء تبدأ بالاعتراف أمام من يرى في الخفاء. أغلق اليوم بابك ودقائق قليلة، واسكب قلبك أمام أبيك.\",\"p\":\"يا رب، اهدني إلى طريقك، وأعترف لك من كل قلبي. أمجد اسمك إلى الأبد وأنا في خلوتي معك. آمين.\",\"x\":\"يطلب المرنم أن يمجد اسم الله إلى الأبد، والمجد في الخفاء ثمرة صدق. الصلاة التي لا يراها أحد هي الأصدق. تدريب: صلِّ اليوم في مكان مغلق وحدك لمدة خمس دقائق، بلا ملابس صلاة ولا برنامج.\"},{\"t\":\"يعتزل ويصلي\",\"ref\":\"لوقا ٥: ١٦\",\"bk\":\"لوقا\",\"v\":\"وأما هو فكان يعتزل في البراري ويصلي.\",\"r\":\"«وأما هو فكان يعتزل في البراري ويصلي». المسيح كان مشغولًا بالجموع والمرضى، ومع ذلك كان يخلو بالآب. وإن كان هو يحتاج إلى هذه الخلوة فكم بالحري أنا. فلا أسمح للانشغال أن يسرق وقت صلاتي.\",\"p\":\"يا رب يسوع، علّمني أن أعتزل وأصلي كما فعلت. اجعل الخلوة معك أحب أوقات يومي. آمين.\",\"x\":\"الجملة تقع بعد شفاء الأبرص، وبعد أن ذاع خبره وازدحم الناس عليه ليسمعوا ويستشفوا. وكان رد فعل المسيح أن يعتزل ويصلي. الخلوة ليست هروبًا بل تجديدًا. وتشير الصيغة «كان يعتزل» إلى عادة متكررة. فلم تكن الصلاة حدثًا نادرًا بل نمط حياة. وكثيرًا ما كان يقضي الليل في الصلاة. وفي الكنيسة نتعلم من هذا قيمة الخلوة اليومية والرهبانية والأصوام.\\nخصص اليوم مكانًا هادئًا في بيتك، ولو ركنًا صغيرًا، لتجلس فيه عشر دقائق مع الله.\"},{\"t\":\"فلندخل إلى مخادعنا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: فلندخل إلى مخادعنا ونتذكر خطايانا، والرب يعيننا في كل شيء. الخلوة موضع الصدق مع النفس ومع الله. اجعل لك اليوم موعدًا ثابتًا مع الله لا تعطيه لأي أمر آخر.\",\"p\":\"يا رب، علّمني حب الخلوة معك. أعنّي في مخدعي، واكشف لي ما يحتاج إلى توبة. آمين.\",\"x\":\"يقول الأب بيمن: فلندخل إلى مخادعنا ونتذكر خطايانا والرب يعيننا في كل شيء. المخدع مكان الصدق. تدريب: ادخل غرفتك الليلة، وتذكر خطية واحدة وارفع صلاة التوبة.\",\"fq\":435}]},\"8-6\":{\"th\":\"العطاء المبارك\",\"m\":[{\"t\":\"أذبح لك طائعًا\",\"ref\":\"المزمور ٥٣ (٥٤) — السادسة\",\"v\":\"لأنك من جميع الشدائد نجيتني.\",\"r\":\"يقول المرنم: الله عوني، أذبح لك طائعًا وأعترف لاسمك. العطاء الحقيقي ذبيحة طوعية يقدمها القلب المحب. أعط اليوم من وقتك أو مالك شيئًا بفرح، دون أن يطلب منك أحد.\",\"p\":\"يا رب، أنت عوني. علّمني أن أعطي طائعًا فرحًا، وبارك ما أقدمه لك ولإخوتي. آمين.\",\"x\":\"يعدد المرنم نجاة الله له من الشدائد، فيرد بذبيحة طوعية. العطاء الحقيقي شكر. تدريب: اذكر شدة نجاك الله منها، وقدم عطاء مادي أو وقتيًا شكرًا.\"},{\"t\":\"الصالح العين يبارك\",\"ref\":\"الأمثال ٢٢: ٩\",\"bk\":\"الأمثال\",\"v\":\"الصالح العين هو يبارك، لأنه يعطي من خبزه للفقير.\",\"r\":\"«الصالح العين هو يبارك، لأنه يعطي من خبزه للفقير». العين الصالحة ترى حاجة الآخر ولا تحسدهم. وحين أعطي من خبزي لا من فائضي فقط، أتحول إلى بركة وأنال بركة.\",\"p\":\"يا رب، اجعل عيني صالحة ترى حاجة إخوتي، وقلبي سخيًا يعطي من خبزه بفرح وسلام دائم. آمين.\",\"x\":\"في اللغة الكتابية «العين الصالحة» تشير إلى الكرم والسخاء، و«العين الشريرة» إلى البخل والحسد. وقد استخدم الرب هذا التعبير في العظة على الجبل: «سراج الجسد هو العين، فإن كانت عينك بسيطة فجسدك كله يكون نيرًا». فالنظرة الطيبة تنتج عطاءً طيبًا. والعطاء من الخبز لا من الزائد يدل على محبة حقيقية. وتتضاعف البركة لأن الله هو الذي يرد.\\nاليوم، قاسم أحدًا طعامك أو وقتك، من أجل المحبة وليس الفائض.\"},{\"t\":\"العطاء أكثر من الأخذ\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب بفنوتيوس: أحبوا الضيق أكثر من الراحة، والاحتقار أكثر من المجد، والعطاء أكثر من الأخذ. العطاء يحرر القلب. اختر اليوم أن تعطي في موضع كنت تأخذ فيه.\",\"p\":\"يا رب، حرر قلبي من حب الأخذ. اجعلني أحب العطاء كما أنت المعطي الكريم. آمين.\",\"x\":\"يوصي الأب بفنوتيوس بحب الضيق أكثر من الراحة، والاحتقار أكثر من المجد، والعطاء أكثر من الأخذ. وصية ثلاثية عكس ما يريده العالم. تدريب: اختر اليوم أن تعطي أكثر مما تأخذ في موقف.\",\"fq\":275}]},\"8-7\":{\"th\":\"العذراء مريم: نظر إلى اتضاعها\",\"m\":[{\"t\":\"يا باب الحياة\",\"ref\":\"قطعة الخدمة الثالثة (٣) — نصف الليل — الخدمة الثالثة\",\"v\":\"يا باب الحياة العقلي، يا والدة الإله المكرمة، خلصي الذين التجأوا إليك بإيمان من الشدائد، لكي نمجد ميلادك الطاهر في كل شيء من أجل خلاص نفوسنا.\",\"r\":\"تدعو الكنيسة العذراء باب الحياة لأن من خلالها جاء الحياة إلينا. نظر الله إلى اتضاعها فصارت أم الرب. تعلّم منها اتضاعها في طلب شفاعتها، وأن تقول لله اليوم: لتكن مشيئتك.\",\"p\":\"يا رب، بشفاعة والدة الإله القديسة مريم خلص الملتجئين إليها بإيمان. علّمني اتضاعها وطاعتها. آمين.\",\"x\":\"تدعو الكنيسة العذراء في قطع الخدمة باب الحياة العقلي، لأن منها دخل الحياة إلى العالم. وفي صوم العذراء تكرمها. تدريب: ردد تحية الملاك لها: السلام لك يا مريم، وتأمل في عبارة واحدة.\"},{\"t\":\"نظر إلى اتضاع أمته\",\"ref\":\"لوقا ١: ٤٨\",\"bk\":\"لوقا\",\"v\":\"لأنه نظر إلى اتضاع أمته. فهوذا منذ الآن جميع الأجيال تطوبني،\",\"r\":\"«لأنه نظر إلى اتضاع أمته. فهوذا منذ الآن جميع الأجيال تطوبني». لم تفتخر مريم بنفسها بل بنظر الله إليها. والتطويب الذي تناله هو من الله وليس من جهدها. وهكذا نتعلم أن نطلب نظرة الله لا مديح الناس.\",\"p\":\"يا رب، كما نظرت إلى اتضاع أمتك مريم، انظر إلى اتضاعي. وبشفاعتها ساعدني أن أصوم وأصلي بقلب متواضع. آمين.\",\"x\":\"في زيارتها لأليصابات انطلقت مريم بتسبحة قوية تبدأ بـ«تعظم نفسي الرب». وفي هذه الآية تذكر سبب تطويبها: الله نظر إلى اتضاعها. فالله لا يختار الأقوياء بل المتواضعين. وتتحقق نبوتها في كنيستنا التي تطوبها في كل صلاة، لكنها تعطي المجد لله. ويبدأ اليوم صوم العذراء، وهو فرصة للاقتداء بتواضعها وطاعتها وصلاتها.\\nابدأ صوم العذراء اليوم بنية: أن تتعلم من مريم التواضع، وقل لها: «اطلبي عنا يا سيدتي».\"},{\"t\":\"اتضاع بلا كلام كثير\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب نيلوس: هنيئًا للراهب الذي يعتبر نفسه نفاية الكل. الاتضاع الحقيقي لا يطلب مديحًا. اختر اليوم عملًا صغيرًا تقوم به بلا ضجيج، كما فعلت العذراء مريم في صمت.\",\"p\":\"يا رب، علّمني اتضاع العذراء. اجعلني أعمل عملي في الخفاء، وأفرح بنظرتك. آمين.\",\"x\":\"يقول الأب نيلوس: هنيئًا للراهب الذي يعتبر نفسه نفاية الكل. العبارة قاسية لكنها تعني التحرر من المقارنة. تدريب: عش يومًا بلا أن تقارن نفسك بأحد، وقل: أنا في عيني الله فقط.\",\"fq\":295}]},\"8-8\":{\"th\":\"الرافع المتضعين\",\"m\":[{\"t\":\"من مثل الرب إلهنا؟\",\"ref\":\"المزمور ١١٢ (١١٣) — باكر\",\"v\":\"الرب عال على كل الأمم؛ فوق السموات مجده. من مثل الرب إلهنا؟!\",\"r\":\"الرب عال على كل الأمم، ومع ذلك ينظر إلى المتواضعين ويرفعهم. وعد مريم أن الله يرفع المتضعين ويشبع الجياع. اعترف اليوم بمكان ضعفك أمام الله وارفع إليه عينيك.\",\"p\":\"يا رب، من مثلك؟ ارفعني من تراب ضعفي، وعلّمني أن أتضع أمامك. آمين.\",\"x\":\"الرب عال على الأمم ومجده فوق السماوات، ومع ذلك ينظر إلى المتواضعين، كما قالت العذراء: أنزل الأعزاء عن الكراسي ورفع المتضعين. تدريب: اطلب اليوم الاتضاع بصدق وقل: من مثل إلهنا؟\"},{\"t\":\"أنزل الأعزاء\",\"ref\":\"لوقا ١: ٥٢\",\"bk\":\"لوقا\",\"v\":\"أنزل الأعزاء عن الكراسي ورفع المتضعين.\",\"r\":\"«أنزل الأعزاء عن الكراسي، ورفع المتضعين». ميزان الله يختلف عن ميزان العالم. فمن يتكبر ينزل، ومن يتضع يُرفع. وهذا يريحني من سباق المراكز، لأن رفعي في يد الله وحده.\",\"p\":\"يا رب، ارفع المتضعين وانزع الكبرياء من قلبي. وعلّمني أن أرفع من هم أصغر مني بمحبة. آمين.\",\"x\":\"التسبحة تقارن بين الأعزاء والمتضعين، وبين الجياع والأغنياء، وكأنها تعلن ثورة روحية. لكنها ثورة سلمية يقودها الله. فلا يقال إن المتضعين يرفعون أنفسهم، بل «رفع». والتاريخ الكنسي يشهد على رفع الله لرعاة بسطاء وقديسين مجهولين. وفي كل أسرة وجماعة هناك من يحتاج أن يُرفع بكلمة أو فرصة. ونحن يمكن أن نكون أدوات لرفع المتضعين.\\nاليوم، أعط فرصة أو مكانًا لشخص يُنسى عادة في جماعتك: اسمعه، أو امدحه، أو أشركه في عمل.\"},{\"t\":\"علو التواضع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس إن علو التواضع عظيم، وكذلك السقوط في الكبرياء. من اتضع ارتفع ومن تكبر سقط. إن مدحك أحد اليوم فاشكر الله ولا تتكبر.\",\"p\":\"يا رب، احفظني من كبرياء القلب. ارفعني بتواضعك ولا تدعني أسقط. آمين.\",\"x\":\"يقول الأب إيسيذورس إن علو التواضع عظيم، كذلك السقوط في الكبرياء. الارتفاع والانحدار متقابلان. تدريب: إن مدحك أحد اليوم فارفع المدح لله بكلمة قصيرة.\",\"fq\":174}]},\"8-9\":{\"th\":\"قلب مريم الحافظ\",\"m\":[{\"t\":\"حفظت وصاياك وشهاداتك\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء الحادي والعشرون · صلاة الستار\",\"v\":\"حفظت نفسي شهاداتك وأحببتها جدا. حفظت وصاياك وشهاداتك.\",\"r\":\"يحفظ المرنم شهادات الله ويحبها جدًا. هكذا حفظت العذراء كل الأمور متفكرة بها في قلبها. القلب الحافظ يتأمل بصمت. اكتب اليوم كلمة سمعتها في الكنيسة أو الكتاب وتأمل فيها.\",\"p\":\"يا رب، احفظ في قلبي كلمتك كما حفظتها العذراء. أعطني قلبًا يتأمل ويحفظ ويعمل بها. آمين.\",\"x\":\"يحفظ المرنم شهادات الله ويحبها جدًا، والحفظ هنا ليس ذاكرة بل حراسة. وهكذا كانت العذراء تحفظ كل الأمور متأملة في قلبها. تدريب: اختر حدثًا اليوم واحفظه في قلبك بصمت دون أن تعلق عليه.\"},{\"t\":\"خاضعًا لهما\",\"ref\":\"لوقا ٢: ٥١\",\"bk\":\"لوقا\",\"v\":\"ثم نزل معهما وجاء إلى الناصرة وكان خاضعا لهما. وكانت أمه تحفظ جميع هذه الأمور في قلبها.\",\"r\":\"«ثم نزل معهما وجاء إلى الناصرة وكان خاضعًا لهما». ابن الله الأزلي قبل أن يخضع لوالدين بشريين. فلا أستخف بقيمة الطاعة في بيتي، فهي تعليم المسيح العملي لنا. وهناك في الناصرة صنع حياة هادئة وعادية.\",\"p\":\"يا رب يسوع، يا من خضعت لوالديك في الناصرة، علّمني الطاعة والتواضع في بيتي وعملي. آمين.\",\"x\":\"بعد اثني عشر عامًا، ظل يسوع في الهيكل وقال: «ينبغي أن أكون فيما لأبي». لكنه بعدها نزل إلى الناصرة وخضع. فتوازن بين الدعوة السماوية والواجب الأرضي. وبقيت مريم تحفظ كل هذا في قلبها. ثماني عشرة سنة صامتة من حياة المسيح يعلموننا قيمة الحياة اليومية البسيطة. وهكذا فالقداسة لا تتطلب أحداثًا ضخمة بل أمانة في الصغائر والعلاقات الأسرية.\\nاليوم، قم بعمل طاعة صغير بفرح في بيتك أو عملك، دون تذمر، تعبيرًا عن محبتك.\"},{\"t\":\"ماذا فعلت مما يريده الله؟\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب نيسثروس إن على الراهب أن يحاسب نفسه كل مساء وصباح: ماذا فعلت مما يريده الله وماذا فعلت مما لا يريده؟ حفظ القلب يحتاج مراجعة. اجعل الليلة محاسبة من ثلاث دقائق.\",\"p\":\"يا رب، أرني ما يرضيك وما لا يرضيك. أعطني قلبًا يحفظ ويراجع ويتوب. آمين.\",\"x\":\"يقول الأب نيسثروس إن على الراهب أن يحاسب نفسه صباحًا ومساءً: ماذا فعلت مما يريده الله وما لا يريده؟ فالمحاسبة نمط حياة. تدريب: اسأل نفسك هذا السؤال الليلة وسجل جوابين.\",\"fq\":300}]},\"8-10\":{\"th\":\"أم ربي\",\"m\":[{\"t\":\"صهيون الأم\",\"ref\":\"المزمور ٨٦ (٨٧) — السادسة\",\"v\":\"صهيون الأم تقول إن إنسانا وإنسانا ولد فيها، وهو العلي الذي أسسها إلى الأبد.\",\"r\":\"تُقال عن صهيون إن إنسانًا وإنسانًا وُلد فيها، وهو العلي الذي أسسها. وتراها الكنيسة صورة للعذراء أم الرب. أكرم اليوم أمك الروحية والجسدية بكلمة شكر.\",\"p\":\"يا رب، أشكرك على العذراء مريم أم مخلصي. علّمني أن أكرم أمي وأمهات الكنيسة. آمين.\",\"x\":\"صهيون الأم تُنسب إليها الولادة لأنها شعب الله الذي يولد فيه العلي، وترى الكنيسة فيها صورة للعذراء. الأمومة هنا كرامة. تدريب: اشكر اليوم من كان أمًا روحية لك، واذكرها في صلاتك.\"},{\"t\":\"من أين لي هذا\",\"ref\":\"لوقا ١: ٤٣\",\"bk\":\"لوقا\",\"v\":\"فمن أين لي هذا أن تأتي أم ربي إلي؟\",\"r\":\"«فمن أين لي هذا أن تأتي أم ربي إليّ؟». أليصابات الأكبر سنًا والأعلى مكانة تظهر تواضعًا كبيرًا أمام العذراء. وتعلمني أن أحترم من اختاره الله وأن أقول: من أنا حتى يزورني الله وقديسوه؟\",\"p\":\"يا رب، أشكرك على أمك العذراء التي كرمتها. علّمني أن أحترم قديسيك وأطلب شفاعتهم بتواضع. آمين.\",\"x\":\"حين دخلت مريم بيت زكريا وسلمت على أليصابات ارتكض الجنين في بطنها وامتلأت من الروح القدس. فنطقت بعبارة «أم ربي»، وهي من أقدم الشهادات على أن مريم والدة الإله. والتسمية ليست عن الأصل الإلهي بل عن شخص المسيح الواحد الإله المتجسد. وقد دافع آباؤنا عن هذا اللقب في مجمع أفسس. وفي صوم العذراء نردد هذا التكريم ونطلب شفاعتها.\\nاقرأ اليوم أحد تماجيد العذراء أو تسبحة مريم، وتأمل في معنى لقب «أم ربي».\"},{\"t\":\"أن تمجد قريبك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوحنا رجل القلالي: إذا سمعت شيخًا يمتدح قريبه أكثر من نفسه، فاعلم أنه بلغ كمالًا رفيعًا. المكرِّم هو المحب. اذكر اليوم اسم شخص وأثنِ عليه أمام غيره.\",\"p\":\"يا رب، اجعلني أمجد إخوتي أكثر من نفسي. وانزع من قلبي حب المدح. آمين.\",\"x\":\"يعلّم الأب يوحنا رجل القلالي أن الكمال أن تمجد قريبك أكثر من نفسك، فمن سمع شيخًا يمتدح قريبه فقد رأى كمالًا. تدريب: امدح اليوم شخصًا بصدق أمام آخرين.\",\"fq\":273}]},\"8-11\":{\"th\":\"نبوات التجسد\",\"m\":[{\"t\":\"ما الإنسان حتى تذكره؟\",\"ref\":\"المزمور الثامن (من صلاة باكر) — الستار\",\"v\":\"إذا أرى سَمواتِكَ عَمَلَ أصابِعِكَ، القَمَرَ والنُّجومَ التي كَوَّنْتَها، فمَا الإنسانُ حتَّى تَذكُرَه؟ وابنُ آدَمَ حتَّى تَفتَقِدَه؟\",\"r\":\"يتعجب المرنم أن يذكر الله الإنسان ويعتني به. هذا الاهتمام مهد له بنبوات العهد القديم قبل أن يتجسد المسيح. اقرأ اليوم نبوة واحدة عن ميلاد المخلص، وافرح بتحقيقها.\",\"p\":\"يا رب، ما أعجب اسمك! ذكرتنا بنبواتك قبل أن تتجسد، فأعطني أن أراك في كل الكتب. آمين.\",\"x\":\"المزمور الثامن يتأمل في عظمة السماء وصغر الإنسان، ثم يذكر أن الله يذكره ويفتقده. وهو مفتاح فهم التجسد: الله افتقد الإنسان. تدريب: اقرأ المزمور الثامن بصوت منخفض، وتأمل في عبارة: وابن آدم حتى تفتقده.\"},{\"t\":\"نسل المرأة يسحق رأسك\",\"ref\":\"التكوين ٣: ١٥\",\"bk\":\"التكوين\",\"v\":\"وأضع عداوة بينك وبين المرأة، وبين نسلك ونسلها. هو يسحق رأسك، وأنت تسحقين عقبه».\",\"r\":\"«هو يسحق رأسك، وأنت تسحقين عقبه». بعد السقوط مباشرة لم يترك الله الإنسان بلا رجاء، بل وعد بمخلص يولد من امرأة. وهذا الوعد تحقق في المسيح، فلا أيأس من خطيتي لأن النصرة بدأت منذ البداية.\",\"p\":\"يا رب، أشكرك لأنك وعدت منذ البداية بنسل المرأة الذي يسحق رأس الحية. اسحق الشر في حياتي بنعمتك. آمين.\",\"x\":\"قيل هذا الوعد في جنة عدن بعد أن أغوت الحية حواء. ويسمى «الإنجيل الأول» لأنه أول بشارة بالخلاص. ويرى الآباء أن «نسل المرأة» هو المسيح الذي ولد من العذراء مريم دون زرع بشر، وهو الذي سحق رأس الشيطان بموته وقيامته. وتلقب الكنيسة العذراء بـ«حواء الجديدة» لأنها بطاعتها فتحت الباب الذي أغلقته حواء بعصيانها. وفي صوم العذراء نتأمل هذه العلاقة.\\nقل اليوم: «شكرًا يا رب أنك وعدت بالخلاص منذ البداية»، وتذكر أن كل ضعف لك يمكن أن يسحقه المسيح.\"},{\"t\":\"من القديم إلى الجديد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيسوى: إني أقرأ العهد القديم وأرجع إلى العهد الجديد. فالقديم يمهد والجديد يكمل. اقرأ اليوم نصًا من العهدين متقابلين، وراقب الصلة بينهما.\",\"p\":\"يا رب، افتح ذهني لأفهم الكتب. أرني المسيح في كل صفحة منها. آمين.\",\"x\":\"يقول الأب سيسوى: إني أقرأ العهد القديم وأرجع إلى العهد الجديد. القراءة تدور بين العهدين. تدريب: اقرأ اليوم نصًا من العهد القديم، ثم اقرأ ما يوازيه في الجديد.\",\"fq\":499}]},\"8-12\":{\"th\":\"العليقة المتقدة\",\"m\":[{\"t\":\"لا شيء يختفي من حرارتها\",\"ref\":\"المزمور الثامن عشر — باكر\",\"v\":\"من أقصى السماء خروجها، ومنتهاها إلى أقصى السماء ولا شئ يختفي من حرارتها.\",\"r\":\"يصف المرنم الشمس التي لا يختفي شيء من حرارتها. ظهر الله لموسى في عليقة تتقد ولا تحترق. نار الله تطهر ولا تفني. اطلب اليوم أن يشعل الله فيك نار محبته دون أن يحرق ضعفك.\",\"p\":\"يا رب، أنت النار التي لا تحرق. أشعل فيّ غيرة لك ولا تحرقني بغضبك. آمين.\",\"x\":\"يقول المزمور عن الشمس إن شيئًا لا يختفي من حرارتها، وهو رمز لعلم الله ونوره. في العليقة تجلى الله لموسى بنار لا تحرق. تدريب: ضع نفسك اليوم أمام نور الله لتنكشف لك مناطق خافية في قلبك.\"},{\"t\":\"العليقة لم تكن تحترق\",\"ref\":\"الخروج ٣: ٢\",\"bk\":\"الخروج\",\"v\":\"وظهر له ملاك الرب بلهيب نار من وسط عليقة. فنظر وإذا العليقة تتوقد بالنار، والعليقة لم تكن تحترق.\",\"r\":\"«فنظر وإذا العليقة تتوقد بالنار، والعليقة لم تكن تحترق». ما أعجب هذا المنظر! النار تشتعل والعليقة لا تفنى. هكذا حضور الله يملأ ولا يحرق. وهذا ما يعلّمنا الآباء عن مريم وعن كل قلب يسكنه الله.\",\"p\":\"يا رب، كما ظهرت لموسى في العليقة، أظهر في حياتي. اجعل قلبي موضعًا لحضورك لا يحترق بل يستنير. آمين.\",\"x\":\"كان موسى يرعى غنم حميه في برية سيناء حين رأى المنظر. والعليقة نبات شوكي لا قيمة له، ومع ذلك اختارها الله مكانًا لظهوره. وفي التقليد الكنسي تعتبر العليقة المتقدة رمزًا لحلول اللاهوت في بطن العذراء دون أن يؤذيها. ولهذا تسمى مريم في الثيئوطوكيات «العليقة التي رآها موسى». والرمز أيضًا يخبرنا عن نفوسنا: الله يتجلى في أماكن بسيطة. وصوم العذراء فرصة لنأخذ هذا الرمز إلى حياتنا.\\nقدّم اليوم قلبك لله كعليقة، وقل: «يا رب، احل فيّ بنارك ولا تدعني أحترق».\"},{\"t\":\"الخشب بين المواد المشتعلة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب مكاريوس إن الخشب الذي يتوسط المواد المشتعلة تلتهمه النار بسرعة، وكذلك الإنسان إذا نقّى ذهنه بمخافة الله تلتهم المخافة جسده. مخافة الله نار نقية. اطلب اليوم مخافة الله لا خوفًا من الناس.\",\"p\":\"يا رب، اسكب في قلبي مخافتك كنار مطهرة. أحرق ما فيّ من شر، وأبقني لك. آمين.\",\"x\":\"يقول الأب مكاريوس إن الخشب الذي يتوسط المواد المشتعلة تلتهمه النار بسرعة، وكذلك من نقّى ذهنه بمخافة الله تلتهم المخافة جسده. تدريب: قبل أن تفكر في أمر اليوم، ضع مخافة الله أولًا.\",\"fq\":237}]},\"8-13\":{\"th\":\"الباب المغلق\",\"m\":[{\"t\":\"افتحوا لي أبواب البر\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"افتحوا لي أبواب البر لكي أدخل فيها وأعترف للرب. هذا هو باب الرب والصديقون يدخلون فيه.\",\"r\":\"يدعو المرنم أن تُفتح له أبواب البر ليعترف للرب، فهذا باب الرب والصديقون يدخلون فيه. الباب المغلق في الكنيسة علامة سر العذراء. افتح قلبك اليوم لله، وأغلقه على كل ما يفسده.\",\"p\":\"يا رب، افتح لي أبواب البر. علّمني أن أغلق قلبي على الشر وأفتحه لك وحدك. آمين.\",\"x\":\"أبواب البر في المزمور ١١٧ تُفتح للصديقين الذين يعترفون للرب. وتقرأ الكنيسة هذه الآية عند دخول الكنيسة، فالدخول للعبادة اعتراف. تدريب: عندما تدخل مكانًا مقدسًا اليوم أو تصلي، ابدأ بكلمة اعتراف قصيرة.\"},{\"t\":\"الباب يكون مغلقًا\",\"ref\":\"حزقيال ٤٤: ١\",\"bk\":\"حزقيال\",\"v\":\"ثم أرجعني إلى طريق باب المقدس الخارجي المتجه للمشرق، وهو مغلق.\",\"r\":\"«ثم أرجعني إلى طريق باب المقدس الخارجي المتجه للمشرق، وهو مغلق». هذا الرمز يعلمني قيمة القداسة والتكريس. فبعض الأبواب تبقى لله وحده، وفي حياتي أيضًا أحتاج أن أجعل لله بابًا لا يدخله غيره.\",\"p\":\"يا رب، أجعل في حياتي بابًا مغلقًا لك وحدك. اقبل تكريسي، واحفظ قلبي مقدسًا لحضورك. آمين.\",\"x\":\"في رؤيا حزقيال للهيكل الجديد، رأى الباب الشرقي مغلقًا ويقول الرب أن أحدًا لا يدخل منه لأن الرب دخل منه. وفي التقليد الكنسي تفسر هذه الرؤيا بأنها رمز لدوام بتولية العذراء مريم قبل الولادة وفي الولادة وبعدها. وتسميها صلوات الكنيسة «الباب المغلق». وهو فكر لاهوتي عميق يؤكد قداسة الأم التي حملت الله. وإذ نصوم، نتأمل في معنى التكريس.\\nاختر اليوم «بابًا» في حياتك تكرسه لله وحده: وقتًا أو عادة أو علاقة، وقل: «هذا لك يا رب».\"},{\"t\":\"اللسان والبطن\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب تيثوى: كيف يمكننا أن نحفظ قلبنا عندما يكون لساننا وبطننا مفتوحين؟ حراسة القلب تبدأ بإغلاق الأبواب. أغلق اليوم بابًا واحدًا: كلمة زائدة أو أكلة زائدة.\",\"p\":\"يا رب، ضع حارسًا على فمي، واحفظ باب قلبي. آمين.\",\"x\":\"سأل أخ الأب تيثوى كيف يحفظ قلبه، فأجاب: كيف نحفظه ولساننا وبطننا مفتوحان؟ حراسة القلب تبدأ بحراسة الفم. تدريب: أغلق باب اللسان اليوم ثلاث مرات، حين تريد أن تتكلم بلا حاجة.\",\"fq\":546}]},\"8-14\":{\"th\":\"عصا هارون المزهرة\",\"m\":[{\"t\":\"الكاهن على طقس ملكيصادق\",\"ref\":\"المزمور ١٠٩ (١١٠) — التاسعة\",\"v\":\"أقسم الرب ولن يندم أنك أنت هو الكاهن على طقس ملكيصادق.\",\"r\":\"أقسم الرب ولن يندم أنك أنت الكاهن على طقس ملكيصادق. كهنوت المسيح أزهر كعصا هارون، حياة من يابس. اطلب اليوم من الله أن يعيد الحياة إلى شيء يابس في حياتك.\",\"p\":\"يا رب، أنت الكاهن الأبدي. أزهِر في حياتي ما يبس، وأعد إليّ نضارة الإيمان. آمين.\",\"x\":\"يقول المزمور ١٠٩ إن الرب أقسم أن المسيح كاهن إلى الأبد على طقس ملكيصادق. وفي الصوم نتذكر كهنوته الأعظم. تدريب: صلِّ اليوم من أجل كاهنك بالاسم، واشكر الله على الكهنوت.\"},{\"t\":\"الرجل الذي أختاره\",\"ref\":\"العدد ١٧: ٥\",\"bk\":\"العدد\",\"v\":\"فالرجل الذي أختاره تفرخ عصاه، فأسكن عني تذمرات بني إسرائيل التي يتذمرونها عليكما».\",\"r\":\"«فالرجل الذي أختاره تفرخ عصاه». اختيار الله يظهر بثمر لا بدعاية. وليست العصا اليابسة هي التي تثمر بل قوة الله. وأنا أتعلم ألا أخشى من يبسي، فإن اختارني الله أثمرت بنعمته.\",\"p\":\"يا رب، كما أفرخت عصا هارون اليابسة، أنبت الحياة في ما جف في حياتي، واجعلني أثمر لمجدك. آمين.\",\"x\":\"في سفر العدد تذمر الشعب على سلطان موسى وهارون، فأمر الله بأن يضع كل رئيس سبط عصا في خيمة الشهادة. وعند الصباح وجدوا عصا هارون وحدها قد أفرخت وأزهرت وأنضجت لوزًا. وصارت العصا تحفظ أمام التابوت. وتعتبر الكنيسة العصا رمزًا لمريم التي أثمرت المسيح دون أن يمسها بشر، فالله يعطي الحياة من اليابس. وصوم العذراء فرصة لنؤمن بالمعجزات الصغيرة في حياتنا.\\nاليوم، اذكر مجالًا من حياتك يابسًا، وقدمه لله قائلًا: «اختر يا رب أن تثمر فيّ».\"},{\"t\":\"الغصن الغض\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أشعيا: كما أن الغصن الغض ينحني بسهولة، هكذا يكون المبتدئون في الطاعة. الحياة تحتاج مرونة تستجيب للمشيئة. اختر اليوم أن تنحني أمام مشيئة الله في موقف تقاومه.\",\"p\":\"يا رب، اجعلني غصنًا غضًّا في يديك. علّمني الطاعة التي تثمر، ولا تدعني أيبس. آمين.\",\"x\":\"يقول الأب أشعيا: كما أن الغصن الغض ينحني بسهولة، هكذا يكون المبتدئون في الطاعة. المرونة ميزة لا ضعف. تدريب: تقبل اليوم توجيهًا بلا تيبس.\",\"fq\":121}]},\"8-15\":{\"th\":\"نشيد العروس\",\"m\":[{\"t\":\"أبتهج بكلامك\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء الحادي والعشرون · صلاة الستار\",\"v\":\"أبتهج أنا بكلامك كمن وجد غنائم كثيرة. أبغضت الظلم ورذلته؛ أما ناموسك فأحببته.\",\"r\":\"يبتهج المرنم بكلام الله كمن وجد غنائم كثيرة، ويبغض الظلم ويحب الناموس. هذا هو غزل المحبة بين العروس والعريس. اقرأ اليوم آية من الإنجيل كأنها رسالة حب شخصية إليك.\",\"p\":\"يا رب، أبتهج بكلامك كمن وجد غنائم كثيرة. اجعل محبتي لك أعمق من كل محبة، وأبغض ما يبعدني عنك. آمين.\",\"x\":\"يبتهج المرنم بكلام الله كمن وجد غنائم كثيرة، وهو تشبيه عجيب عن الفرح بالكتاب. الكلمة ليست ثقيلة بل كنز. تدريب: ابحث اليوم عن آية جديدة كأنك تبحث عن كنز، وسجلها.\"},{\"t\":\"قومي يا حبيبتي\",\"ref\":\"نشيد الأنشاد ٢: ١٠\",\"bk\":\"نشيد الأنشاد\",\"v\":\"أجاب حبيبي وقال لي: «قومي يا حبيبتي، يا جميلتي وتعالي.\",\"r\":\"«أجاب حبيبي وقال لي: قومي يا حبيبتي، يا جميلتي، وتعالي». المسيح يخاطبني بحنان وليس بتوبيخ. يدعوني لأن أقوم من تراخيّ وأتجه إليه، ويسميني «جميلتي»، ثقة منه بقدرتي على الاستجابة.\",\"p\":\"يا حبيبي يسوع، أسمع دعوتك: قومي وتعالي. أقوم من فتوري وأتجه إليك بكل قلبي، فاجذبني إليك. آمين.\",\"x\":\"نشيد الأنشاد في التقليد المسيحي يُقرأ على مستوى روحي: محبة المسيح للكنيسة أو للنفس المؤمنة. ودعوة «قومي وتعالي» تتبعها وصف الشتاء الذي مضى والزهور التي ظهرت. وهذا رمز لقيامة النفس بعد الشتاء الروحي. وتوظف الكنيسة النشيد في أعياد العذراء لأنه يصف جمال القداسة. والدعوة هنا لا تعتمد على استحقاقي بل على محبته. ويمكنني أن أقوم اليوم من فتوري.\\nقم الآن واستمع لمقطع صلاة قصيرة أو ترنيمة تجذب قلبك إلى المسيح، وقل: «ها أنا آتي».\"},{\"t\":\"المحبة أهم من الصوم\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب كسيانوس: الصوم معي دائمًا أما أنتم فلستم معي دائمًا. الصوم اختياري أما إتمام المحبة فتطلبه شريعة الله بالضرورة. قدّم اليوم خدمة محبة قبل أي نسك.\",\"p\":\"يا رب، علّمني أن أضع المحبة قبل كل نسك. اجعل جهادي كله محبة لك ولإخوتي. آمين.\",\"x\":\"يقول الأب كسيانوس نقلًا عن أحد الآباء: الصوم أمر نافع لكنه اختياري، أما إتمام المحبة فتطلبه شريعة الله بالضرورة. فالمحبة تتقدم على الصوم. تدريب: إن طلب منك أحد خدمة اليوم فلا ترفضها بحجة عبادتك.\",\"fq\":208}]},\"8-16\":{\"th\":\"جبل الرب\",\"m\":[{\"t\":\"الجبال حولها\",\"ref\":\"المزمور ١٢٤ (١٢٥) — الغروب\",\"v\":\"الساكن في أورشليم. الجبال حولها، والرب حول شعبه من الآن وإلى الأبد.\",\"r\":\"المتوكلون على الرب مثل جبل صهيون، والجبال حول أورشليم والرب حول شعبه. الكنيسة جبل الرب الذي يلجأ إليه كل متعب. صلِّ اليوم من أجل كنيستك ورعاتها.\",\"p\":\"يا رب، كن حول شعبك من الآن وإلى الأبد. ثبّت كنيستك كجبل صهيون لا يتزعزع. آمين.\",\"x\":\"الجبال حول أورشليم والرب حول شعبه، صورة لحماية محيطة من كل جانب. الكنيسة جبل نلجأ إليه. تدريب: عندما تشعر بالتهديد اليوم، تخيل نفسك محاطًا بحماية الله.\"},{\"t\":\"عظيم هو الرب\",\"ref\":\"المزامير ٤٨: ١\",\"bk\":\"المزامير\",\"v\":\"عظيم هو الرب وحميد جدا في مدينة إلهنا، جبل قدسه.\",\"r\":\"«عظيم هو الرب وحميد جدًا في مدينة إلهنا، جبل قدسه». حين أنظر إلى عظمة الله، تصغر مشاكلي وتتسع نفسي. وتسبيح الجماعة في بيت الله يذكرني بأنني جزء من شعب يعبد إلهًا عظيمًا.\",\"p\":\"يا رب، عظيم أنت وحميد جدًا. أقم في وسطنا، واجعلنا نحدث الأجيال القادمة بعظمتك وأمانتك. آمين.\",\"x\":\"المزمور ٤٨ من مزامير صهيون التي تحتفل بسكنى الله في وسط شعبه. وجبل القدس رمز للثبات والسلام الإلهي. والمرنم يدعو إلى التجول حول المدينة وعد أبراجها والتأمل في حصونها ليحدثوا الجيل القادم. فالتسبيح يتحول إلى شهادة للأجيال. وفي الكنيسة نقف في كل قداس أمام جبل قدس الله. وفي هذه الأيام نستعد لعيد التجلي الذي يقدّم لنا جبلًا آخر، جبل تابور، حيث ظهر مجد الله.\\nاحكُ لأحد أبنائك أو أصدقائك الصغار اليوم موقفًا أظهر فيه الله عظمته لك.\"},{\"t\":\"الطريق الملوكي الخفيف\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن الآباء وجدوا أن الأفضل أن يأكل الإنسان قليلًا كل يوم، وسلموا الطريق الملوكي الخفيف. طريق الله صعود معتدل لا قفز. اختر اليوم نظامًا خفيفًا تستمر عليه شهرًا.\",\"p\":\"يا رب، علّمني الاعتدال في كل شيء. قدني في الطريق الملوكي الذي تحبه. آمين.\",\"x\":\"يقول الأب بيمن إن الآباء وجدوا أن الأفضل أن يأكل الإنسان قليلًا كل يوم، وسلموا الطريق الملوكي الخفيف. الاعتدال أبقى من الشدة المتقطعة. تدريب: اتبع اليوم اعتدالًا في طعامك بدل قفزات.\",\"fq\":331}]},\"8-17\":{\"th\":\"تعالوا نسجد\",\"m\":[{\"t\":\"الرب القوي في الحروب\",\"ref\":\"المزمور ٢٣ (٢٤) — الثالثة\",\"v\":\"الرب العزيز القدير، الرب القوى في الحروب.\",\"r\":\"الرب العزيز القدير القوي في الحروب هو الذي ندعوه ليدخل قلوبنا. السجود للرب يبدأ بفتح الأبواب له. افتح باب قلبك اليوم لملك المجد، وانحنِ في صلاة صامتة.\",\"p\":\"يا رب القوات، يا ملك المجد، أنت القوي في الحروب. افتح لك أبواب نفسي وأسجد لك. آمين.\",\"x\":\"القوي في الحروب هو الذي تدعوه الأبواب الدهرية لتفتح له في المزمور ٢٣. دخوله إلى قلوبنا معركة ينتصر فيها هو، لا نحن. تدريب: افتح اليوم باب أمر محتفظ به لنفسك، وقل: ادخل يا ملك المجد.\"},{\"t\":\"اسجدوا في جبل قدسه\",\"ref\":\"المزامير ٩٩: ٩\",\"bk\":\"المزامير\",\"v\":\"علوا الرب إلهنا، واسجدوا في جبل قدسه، لأن الرب إلهنا قدوس.\",\"r\":\"«علوا الرب إلهنا، واسجدوا في جبل قدسه، لأن الرب إلهنا قدوس». السجود ليس حركة جسد بل اعتراف بالقداسة. وحين أسجد بقلبي، أضع نفسي في مكانها الصحيح أمام الله العظيم.\",\"p\":\"يا رب القدوس، أسجد لك في جبل قدسك. علّمني أن أعلّي اسمك وأخضع لك بقلب محب. آمين.\",\"x\":\"المزمور ٩٩ يكرر ثلاث مرات «قدوس هو» في ما يشبه الترتيلة الثلاثية. ويذكر موسى وهارون وصموئيل الذين دعوا الرب فأجابهم. فالقداسة ليست بعيدة بل تستجيب. والسجود تعبير عن خضوع المحب. وفي الكنيسة القبطية نسجد في الصلوات ونسجد للصليب والإنجيل. ويعلمنا السجود التواضع وتسليم الكبرياء. والتجلي سيظهر لنا قداسة المسيح بحيث سجد التلاميذ على وجوههم.\\nاسجد اليوم في صلاتك سجدة هادئة، حتى في غرفتك، وقل: «قدوس أنت يا رب».\"},{\"t\":\"لا تغادر قلايتك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيرابيون: يا ولدي إذا ابتغيت المنفعة فلا تغادر قلايتك، انتبه لنفسك وعمل يديك، فالخروج لا يجديك نفعًا كالبكاء. السجود الداخلي أعمق من الحركة الخارجية. اجلس اليوم في مكانك بصلاة أطول.\",\"p\":\"يا رب، علّمني السجود في حضرتك. اجعل قلبي قلاية تلتقي فيها بي. آمين.\",\"x\":\"يوصي الأب سيرابيون من أراد المنفعة ألا يغادر قلايته وأن ينتبه لنفسه وعمل يديه، فالخروج لا يجديه نفعًا كالبكاء. المنفعة الداخلية لا تأتي بالتجوال. تدريب: ابقَ اليوم في مكانك وعملك بلا تشتت.\",\"fq\":521}]},\"8-18\":{\"th\":\"السحابة والمجد\",\"m\":[{\"t\":\"لبس الجلال\",\"ref\":\"المزمور ٩٢ (٩٣) — السادسة\",\"v\":\"الرب قد ملك. ولبس الجلال.\",\"r\":\"الرب قد ملك ولبس الجلال، ويظهر مجده في السحابة. تحجب السحابة ما لا نحتمل ونرى منه ما يكفينا. تأمل اليوم في عظمة الله بصمت، دون أن تطلب شيئًا.\",\"p\":\"يا رب، لقد ملكت ولبست الجلال. أنا أسجد لك في سحابة مجدك، وأتهيب حضورك. آمين.\",\"x\":\"الرب ملك ولبس الجلال، والسحابة تحجب مجده عن عيون لا تحتمله. فنرى منه ما يكفي لنعبد. تدريب: قف دقيقة أمام عظمة الله بلا طلب، وقل: أنت عظيم وأنا لا شيء.\"},{\"t\":\"جلد وجهه صار يلمع\",\"ref\":\"الخروج ٣٤: ٢٩\",\"bk\":\"الخروج\",\"v\":\"وكان لما نزل موسى من جبل سيناء ولوحا الشهادة في يد موسى، عند نزوله من الجبل، أن موسى لم يعلم أن جلد وجهه صار يلمع في كلامه معه.\",\"r\":\"«موسى لم يعلم أن جلد وجهه صار يلمع في كلامه معه». لم يقصد أن يتلألأ، لكن الصلاة تركت أثرها. فالمصلي الحقيقي لا يعرف ما يحمله من نور، لكن الناس يرونه في هدوئه ولطفه وسلامه.\",\"p\":\"يا رب، غيرني بصلاتي معك حتى يلمع وجهي بنورك دون أن أدري. وأعطني أن أحمل سلامك إلى من حولي. آمين.\",\"x\":\"موسى قضى أربعين يومًا مع الله، وعاد ومعه لوحا الشهادة. ولم يدرك أن وجهه يلمع حتى خاف الناس. وفي العهد الجديد يقول بولس إن مجد وجه موسى كان زائلًا، أما مجد المسيح فباقٍ. وفي التجلي أضاء وجه المسيح كالشمس، مجده الأصلي. فنحن ننتظر أن نتغير إلى صورته من مجد إلى مجد. وهذا التغيير يحدث في الصلاة والأسرار، بصمت وبدون استعراض.\\nعد من الصلاة اليوم بقلب هادئ، وتأمل: هل يرى أحد أثر الصلاة في وجهي وسلوكي؟\"},{\"t\":\"من لا يمتدحه أحد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أور إن من يُحترم ويُمتدح أكثر مما هو عليه يهلك كثيرًا، أما من لا يمتدحه أحد فيتمجد من فوق. المجد الحقيقي يأتي من الله. افرح اليوم إن لم يلتفت إليك أحد.\",\"p\":\"يا رب، لا أطلب مجد الناس. أعطني أن أتمجد بك وحدك. آمين.\",\"x\":\"يقول الأب أور إن من يُمتدح أكثر مما هو عليه يهلك كثيرًا، أما الذي لا يمتدحه أحد فيتمجد من فوق. المديح الزائد يضر. تدريب: اطلب اليوم مجدًا خفيًا لا يعرفه أحد.\",\"fq\":561}]},\"8-19\":{\"th\":\"عيد التجلي\",\"m\":[{\"t\":\"لبس الرب القوة\",\"ref\":\"المزمور ٩٢ (٩٣) — السادسة\",\"v\":\"لبس الرب القوة. وتمنطق بها. لأنه ثبت المسكونة فلن تتزعزع.\",\"r\":\"لبس الرب القوة وتمنطق بها، وثبت المسكونة فلن تتزعزع. في التجلي ظهر مجده على الجبل لتلاميذه لتثبت قلوبهم. تأمل اليوم في مجد المسيح الذي أخفاه ليحتمل ضعفنا.\",\"p\":\"يا رب، يا من تجليت على الجبل، ثبتنا في مجدك وأنر عيوننا لنراك. آمين.\",\"x\":\"لبس الرب القوة وتمنطق بها، وفي التجلي أظهر مجده لثلاثة تلاميذ ليثبتهم قبل الصليب. نرى المجد لنحتمل الطريق. تدريب: تذكر لحظة رأيت فيها حضور الله بوضوح، وارجع إليها في وقت الصعوبة.\"},{\"t\":\"أضاء وجهه كالشمس\",\"ref\":\"متى ١٧: ٢\",\"bk\":\"متى\",\"v\":\"وتغيرت هيئته قدامهم، وأضاء وجهه كالشمس، وصارت ثيابه بيضاء كالنور.\",\"r\":\"«وتغيرت هيئته قدامهم، وأضاء وجهه كالشمس، وصارت ثيابه بيضاء كالنور». التلاميذ رأوا لمحة من مجد المسيح الحقيقي قبل أن يروا عاره في الصليب. وأنا أيضًا مدعو لأن أرى وراء الظروف نور المسيح.\",\"p\":\"يا رب يسوع، يا من تجليت على الجبل بمجدك، أضئ على قلبي بنورك. ثبّتني في رجاء المجد وقت الصليب. آمين.\",\"x\":\"في عيد التجلي المجيد نتذكر أن المسيح لم يتغير في ذاته بل كشف عن مجده الذي كان مخفيًا. وقد أخذ معه ثلاثة تلاميذ: بطرس ويعقوب ويوحنا، الذين سيشهدون جثسيماني أيضًا. فكما رأوا مجده رأوا ضعفه. والتجلي يعد التلاميذ لقبول الصليب بمعرفة أنه الطريق إلى المجد. وهو أيضًا وعد لنا بأن أجسادنا ستتغير على صورة جسد مجده. فالرجاء حاضر في الألم.\\nفي هذا العيد، خصص وقتًا لصلاة هادئة، وتأمل في وجه المسيح المضيء، واطلب أن يضيء وجهه على حياتك.\"},{\"t\":\"مجد الناس باطل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيسوى: إذا لم يمجدنا الله فمجد الناس باطل. التجلي يعلّمنا أن المجد الحقيقي ينتظرنا مع المسيح. أطلب اليوم رضا الله قبل رضا الناس في قرار واحد.\",\"p\":\"يا رب، أنت مجدي. اجعلني أطلب وجهك لا استحسان الناس. آمين.\",\"x\":\"يقول الأب سيسوى للأسقف: إذا لم يمجدنا الله فمجد الناس باطل. التجلي يعلمنا أن المجد يأتي من الله. تدريب: لا تطلب اليوم اعتراف الناس بعملك، وانتظر نظرة الله.\",\"fq\":491}]},\"8-20\":{\"th\":\"النزول من الجبل\",\"m\":[{\"t\":\"لا ينعس حافظك\",\"ref\":\"المزمور ١٢٠ (١٢١) — الغروب\",\"v\":\"لا يسلم رجلك للزلل؛ فما ينعس حافظك. هوذا لا ينعس ولا ينام حارس إسرائيل.\",\"r\":\"لا يسلم الرب رجلك للزلل لأن حارس إسرائيل لا ينعس ولا ينام. التلاميذ نزلوا من الجبل إلى الواقع بحفظه. اجعل رؤيتك الروحية اليوم تنزل إلى عملك العادي وتغيره.\",\"p\":\"يا رب، احفظ رجلي من الزلل. اجعل ما أراه من نورك يظهر في واقع حياتي. آمين.\",\"x\":\"حارس إسرائيل لا ينعس ولا ينام، وبعد نزول التلاميذ من الجبل صاروا بحاجة لهذا الحفظ. الصعود يعطي الرؤية والنزول يطلب الحفظ. تدريب: خذ من صلاتك اليوم كلمة واحدة واعمل بها في العمل.\"},{\"t\":\"لا تعلموا أحدًا\",\"ref\":\"متى ١٧: ٩\",\"bk\":\"متى\",\"v\":\"وفيما هم نازلون من الجبل أوصاهم يسوع قائلا: «لا تعلموا أحدا بما رأيتم حتى يقوم ابن الإنسان من الأموات».\",\"r\":\"«لا تعلموا أحدًا بما رأيتم حتى يقوم ابن الإنسان من الأموات». بعض الخبرات الروحية تحتاج إلى وقت لتنضج قبل أن تُحكى. وأحيانًا يكون الصمت أفضل شهادة حتى يتضح المعنى كاملًا.\",\"p\":\"يا رب، علّمني الحكمة في الصمت والكلام. احفظ في قلبي ما أعطيتني حتى يحين وقت الشهادة بنعمتك. آمين.\",\"x\":\"لم يكن التلاميذ يفهمون بعد معنى القيامة، حتى أنهم تساءلوا فيما بينهم ما هو القيام من الأموات. ولو أعلنوا التجلي قبل الصليب لفهمه الناس مجد أرضي. ولذا أوصاهم بالصمت. وهذا يعلمنا الحكمة في الحديث عن خبراتنا الروحية: لا نتباهى بها ولا نستعجل نشرها. ونترك الله يوضحها في وقتها. وبعد القيامة تحدثوا بجرأة. فالتوقيت جزء من الشهادة.\\nاحتفظ اليوم بنعمة أخذتها من الله في قلبك، وتأملها في صمت قبل أن تحكيها.\"},{\"t\":\"تحمل ما يأتيك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيرابيون: إذا أردت أن تكون متواضعًا فدرّب نفسك على تحمل ما يأتيك من الآخرين. النزول من الجبل يعني احتمال الناس. تحمل اليوم كلمة ثقيلة بصمت وصلِّ للمتكلم.\",\"p\":\"يا رب، علّمني أن أحتمل بتواضع. أعطني صبر النزول إلى الناس. آمين.\",\"x\":\"يقول الأب سيرابيون: درّب نفسك على تحمل ما يأتيك من الآخرين لتكون متواضعًا. قاله لأخ ادعى أنه خاطئ ثم تذمر عند أول ملاحظة. التواضع يظهر عند الاحتكاك. تدريب: تحمل اليوم ملاحظة بلا ردة فعل.\",\"fq\":522}]},\"8-21\":{\"th\":\"نفوس الصديقين بيد الله\",\"m\":[{\"t\":\"الرب ينقذ نفوس عبيده\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"الرب ينقذ نفوس عبيده؛ ولا يندم جميع المتكلين عليه.\",\"r\":\"الرب ينقذ نفوس عبيده، ولا يندم جميع المتكلين عليه. نفوس الصديقين بيد الله فلا يمسها عذاب. لا تخف من ساعة الرحيل، بل استعد لها بتوبة هادئة اليوم.\",\"p\":\"يا رب، نفسي بين يديك. أنقذني ساعة الرحيل، ولا تدعني أخزى أبدًا. آمين.\",\"x\":\"الرب ينقذ نفوس عبيده ولا يندم المتكلون عليه، وهذا وعد للأبرار في ساعة الرحيل. الموت ليس نهاية. تدريب: اكتب الليلة رسالة شكر أو غفران لمن تحب كأنها وصية صغيرة.\"},{\"t\":\"بيد الله\",\"ref\":\"الحكمة ٣: ١\",\"bk\":\"الحكمة\",\"v\":\"أما نفوس الصديقين فهي بيد الله فلا يمسها العذاب\",\"r\":\"«أما نفوس الصديقين فهي بيد الله، فلا يمسها العذاب». الموت يبدو للناس نهاية وشقاء، لكن الإيمان يراه انتقالًا إلى يد الله. وما يبدو خسارة هو في الحقيقة بداية سلام ثابت لا ينقطع.\",\"p\":\"يا رب، نفوس الصديقين بيدك. أشكرك على أحبائي الراحلين، واحفظهم في سلامك، وعزّ قلوبنا برجاء اللقاء. آمين.\",\"x\":\"سفر الحكمة يخاطب مؤمنين في الإسكندرية عاشوا في وسط ثقافة تسخر من الإيمان وتتحدث عن الموت كفناء. فيؤكد لهم أن الصديقين في سلام وأن رجاءهم مملوء خلودًا. وتقرأ الكنيسة هذه الآيات في جنازات القديسين وأعياد نياحتهم. فنياحة العذراء التي نحتفل بها بعد غد هي نموذج لهذه الحقيقة: انتقال إلى حضن الله. ولهذا نقول نياحة لا موتًا، أي راحة. وهذا يعطينا عزاء حين نفقد أحبائنا.\\nاذكر اليوم شخصًا راحلًا تحبه، وصلِّ لأجله، وسلّمه ليد الله.\"},{\"t\":\"تذكر الموت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب إفاغريوس: عندما تجلس في قلايتك اجمع فكرك وتذكر أيام الموت وافهم المصيبة، لتثبت في السكينة ولا تضعف. ذكر الموت يعلّمنا الأولويات. اسأل نفسك اليوم: ماذا يهم فعلًا لو كان هذا آخر يوم؟\",\"p\":\"يا رب، علّمني إحصاء أيامي. أعطني أن أحيا كل يوم كما لو كان الأخير. آمين.\",\"x\":\"يوصي الأب إفاغريوس بجمع الفكر في القلاية وتذكر أيام الموت، لنثبت في السكينة ولا نضعف. ذكر الموت يحرر من الأباطيل. تدريب: اسأل نفسك اليوم: ما الذي لا يهم عند ساعة الرحيل؟ واترك شيئًا منه.\",\"fq\":108}]},\"8-22\":{\"th\":\"نياحة السيدة العذراء\",\"m\":[{\"t\":\"أنهضي نفسي المريضة\",\"ref\":\"قطعة النوم (٣)\",\"v\":\"أيتها العذراء الطاهرة أسبلي ظلك السريع المعونة على عبدك، وأبعدي أمواج الأفكار الرديئة عني، وأنهضي نفسي المريضة للصلاة والسهر، لأنها استغرقت في سبات عميق.\",\"r\":\"نتذكر اليوم نياحة العذراء مريم الأم الطاهرة التي انتقلت إلى مجد ابنها. نطلب شفاعتها لتنهض نفوسنا من نوم الغفلة. صلِّ اليوم لأجل شخص بعيد، واطلب من العذراء أن تشفع.\",\"p\":\"يا رب، بصلوات والدة الإله القديسة مريم أنهض نفسي من الغفلة. أعطني رجاء اللقاء بك. آمين.\",\"x\":\"في نياحة العذراء نتذكر انتقالها إلى مجد ابنها، ونطلب في صلاة النوم أن تظلنا ببركتها وتبعد أمواج الأفكار الرديئة. العذراء شفيعة. تدريب: اطلب شفاعتها الليلة في أمر محدد، وقل: يا أم النور صلي لأجلي.\"},{\"t\":\"المشرفة مثل الصباح\",\"ref\":\"نشيد الأنشاد ٦: ١٠\",\"bk\":\"نشيد الأنشاد\",\"v\":\"من هي المشرفة مثل الصباح، جميلة كالقمر، طاهرة كالشمس، مرهبة كجيش بألوية؟\",\"r\":\"«من هي المشرفة مثل الصباح، جميلة كالقمر، طاهرة كالشمس؟». الكنيسة ترى في العذراء مثل الفجر الذي سبق شمس البر. ومن يحمل نور المسيح يصير هو نفسه مضيئًا لغيره، فأطلب أن أكون كذلك.\",\"p\":\"يا رب، يا شمس البر، اجعلني قمرًا يعكس نورك. وبصلوات العذراء أضئ في قلبي حتى أضيء لمن حولي. آمين.\",\"x\":\"في تسابيح العذراء يقال إنها «القمر» الذي يعكس نور الشمس، أي المسيح. فالقمر لا يضيء من ذاته بل يستمد النور. وكذلك القديسون: يعكسون نور المسيح. وعبارة «مرهبة كجيش بألوية» تعبر عن قوة الطهارة والاعتراف. فهي جميلة وقوية معًا. وفي اليوم الذي نتذكر نياحتها نرى كيف أن حياة واحدة متواضعة صارت مصدر نور لأجيال. ويمكن أن تكون حياتنا كذلك.\\nاعكس اليوم نور المسيح في موقف: ابتسامة، تشجيع، أو غفران لمن أساء إليك.\"},{\"t\":\"الدينونة الأبدية\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إفاغريوس: تذكر على الدوام ساعة خروجك ولا تنس الدينونة الأبدية، فلا توجد في نفسك خطيئة. الانتقال يذكّرنا بساعة اللقاء. اعمل اليوم عملًا واحدًا تريد أن يراه الله عند لقائه بك.\",\"p\":\"يا رب، اجعلني مستعدًا للقائك. نقِّ حياتي من كل خطيئة قبل ساعة الرحيل. آمين.\",\"x\":\"يقول الأب إفاغريوس: تذكر على الدوام ساعة خروجك ولا تنس الدينونة الأبدية فلا توجد في نفسك خطية. ذكر النهاية يحمي من البدايات الخاطئة. تدريب: اختم يومك بسؤال: لو انتهت حياتي الليلة هل أنا مستعد؟\",\"fq\":111}]},\"8-23\":{\"th\":\"بيت أبي منازل كثيرة\",\"m\":[{\"t\":\"فرحت بالقائلين\",\"ref\":\"المزمور ١٢١ (١٢٢) — الغروب\",\"v\":\"هناك نصبت كراسي للقضاء كراسي بيت داود.\",\"r\":\"فرح المرنم بالقائلين إلى بيت الرب نذهب. بيت الآب فيه منازل كثيرة أعدها المسيح لنا. تأمل اليوم في الفرح بالمنزل الذي أعده لك، واعمل اليوم بما يناسب ذلك الفرح.\",\"p\":\"يا رب، أشتاق إلى بيتك الذي أعددته لنا. اجعلني أسلك اليوم كمن ينتظرك بفرح. آمين.\",\"x\":\"في المزمور ١٢١ يقف المرنم فرحًا بالدعوة إلى بيت الرب، وهناك نصبت كراسي القضاء. المنزل الأبدي مكان فرح وعدل. تدريب: تأمل في وعد المسيح بمنازل كثيرة، وافرح بأنك مدعو.\"},{\"t\":\"منازل كثيرة\",\"ref\":\"يوحنا ١٤: ٢\",\"bk\":\"يوحنا\",\"v\":\"في بيت أبي منازل كثيرة، وإلا فإني كنت قد قلت لكم. أنا أمضي لأعد لكم مكانا،\",\"r\":\"«في بيت أبي منازل كثيرة... أنا أمضي لأعد لكم مكانًا». يتكلم الرب عن السماء كبيت، وليس كمتاهة. يوجد مكان مُعدّ لي بيد المسيح. وهذا يرفع قلبي من الخوف إلى الشوق.\",\"p\":\"يا رب يسوع، أشكرك لأنك أعددت لي مكانًا في بيت أبيك. شوّقني إلى ذلك البيت وقدني إليه بسلام. آمين.\",\"x\":\"في العشاء الأخير حين اضطرب قلب التلاميذ من حديثه عن رحيله، أعطاهم هذه الكلمات. فهو لا يتركهم بل يمضي ليعد المكان ثم يعود ليأخذهم. وكلمة «منازل» تدل على الإقامة والثبات. والهدف «حيث أكون أنا تكونون أنتم أيضًا». فالسماء هي الكينونة مع المسيح. وفي عيد نياحة العذراء نتأمل في هذا الوعد المحقق لها قبلنا. ونعيش الآن برجاء ذلك البيت.\\nاليوم، عند أي قلق أو فقد، كرر: «في بيت أبي منازل كثيرة»، ودع الرجاء يهدئ قلبك.\"},{\"t\":\"ساعة خروجك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب كرونيوس إن الإنسان يجمع ذاته ويسلم نفسه للتعب الجسدي متذكرًا من كل قلبه ساعة خروجه من العالم ودينونة الله. ذكر الرحيل يخفف تعلقنا بالزائل. اكتب اليوم ما يستحق أن تحتفظ به للأبدية.\",\"p\":\"يا رب، علّمني أن أعيش للأبدية. اجعل قلبي في بيتك قبل أن يسكنه جسدي. آمين.\",\"x\":\"يقول الأب كرونيوس لمن سأل كيف يبلغ الإنسان التواضع إنه يجمع ذاته ويتذكر ساعة خروجه من العالم ودينونة الله. التواضع ثمرة ذكر النهاية. تدريب: اجلس خمس دقائق وتذكر أنك ستقف أمام الله.\",\"fq\":219}]},\"8-24\":{\"th\":\"رجاء القيامة\",\"m\":[{\"t\":\"لو كان العمر ثابتًا\",\"ref\":\"قطعة النوم (٢)\",\"v\":\"لو كان العمر ثابتًا وهذا العالم مؤبدًا لكان لك يا نفسي حجة واضحة. لكن إذا انكشفت أفعالك أمام الديان العادل، فأي جواب تجيبين؟\",\"r\":\"صلاة النوم توقظ النفس لتتذكر أن الحياة قصيرة وأن القيامة حقيقة وراء الموت. الرجاء بالقيامة يحول الخوف من الموت إلى ترقب لقاء. قبل أن تنام الليلة قل: يا رب أنا أنتظر قيامتك.\",\"p\":\"يا رب، يا قيامتنا ورجاءنا، أيقظ نفسي من غفلتها. اجعلني مستعدًا للقائك ورجائي ثابت فيك. آمين.\",\"x\":\"في تحليل صلاة النوم نواجه سؤالًا صادقًا: لو كان العمر ثابتًا لكان لنا حجة، لكن الأعمال ستنكشف أمام الديان. هذه دعوة للتوبة لا للخوف. تدريب: الليلة اعترف بعمل واحد لا تريد أن ينكشف، وتب عنه.\"},{\"t\":\"ابتلع الموت إلى غلبة\",\"ref\":\"كورنثوس الأولى ١٥: ٥٤\",\"bk\":\"كورنثوس الأولى\",\"v\":\"ومتى لبس هذا الفاسد عدم فساد، ولبس هذا المائت عدم موت، فحينئذ تصير الكلمة المكتوبة: «ابتلع الموت إلى غلبة».\",\"r\":\"«ومتى لبس هذا الفاسد عدم فساد، ولبس هذا المائت عدم موت، فحينئذ تصير الكلمة المكتوبة: ابتلع الموت إلى غلبة». الموت الذي بدا قويًا ينتهي ببلع كامل. وأنا أنتظر هذا اليوم بيقين.\",\"p\":\"يا رب، أشكرك لأنك غلبت الموت. ألبسني عدم فساد، واجعل رجائي بالقيامة حيًا وقويًا كل أيام حياتي. آمين.\",\"x\":\"الأصحاح ١٥ من رسالة كورنثوس الأولى هو نشيد القيامة. وفيه يربط بولس بين قيامة المسيح وقيامتنا، ويقول إن الجسد الذي يزرع في هوان يقام في مجد. والتعبير «لبس» يعني أن الحياة الجديدة ستغلف الجسد القديم كثوب جديد. ثم يصرخ بولس: «أين شوكتك يا موت؟ أين غلبتك يا هاوية؟». فتتحول الجنازات إلى احتفالات. وهذا ما نعيشه في صلوات تجنيز القديسين، التي فيها تهليل وتسبيح.\\nاليوم، قل مرة بفرح: «أين شوكتك يا موت؟»، وتذكر أن المسيح غلب.\"},{\"t\":\"الذهن إلى الدينونة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب كرونيوس: إذا التفت الذهن وطلب الله ذاكرًا الدينونة الأخيرة، سقط الهوى للحال. رجاء القيامة يُنقي القلب. اختر اليوم هوى واحدًا، وقاومه بذكر اللقاء.\",\"p\":\"يا رب، ذكّرني بلقائك كلما غلبني هوى. قوّني بنعمة القيامة. آمين.\",\"x\":\"يقول الأب كرونيوس إن الذهن إذا التفت وطلب الله ذاكرًا الدينونة الأخيرة، سقط الهوى للحال. ذكر الدينونة يطرد الأهواء. تدريب: عند أول إغراء اليوم تذكر أنك أمام الله.\",\"fq\":218}]},\"8-25\":{\"th\":\"سحابة الشهود\",\"m\":[{\"t\":\"يعسكر ملاك الرب\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"يعسكر ملاك الرب حول كل خائفيه وينجيهم.\",\"r\":\"يعسكر ملاك الرب حول خائفيه وينجيهم، فنحن محاطون بسحابة من الشهود. القديسون لا يزالون يصلون معنا. اختر اليوم قديسًا وصلِّ إليه، واطلب أن تتعلم منه فضيلة.\",\"p\":\"يا رب، أحط بملائكتك وقديسيك كل من يخافك. أعطني أن أتشبه بهم في الجهاد والإيمان. آمين.\",\"x\":\"يعسكر ملاك الرب حول خائفيه وينجيهم، وهو تعبير عن حماية الملائكة. نحن لسنا وحدنا في ساحة الجهاد. تدريب: ادع اليوم باسم ملاك أو قديس واطلب شفاعته في أمر محدد.\"},{\"t\":\"جبل صهيون ومدينة الله الحي\",\"ref\":\"العبرانيين ١٢: ٢٢\",\"bk\":\"العبرانيين\",\"v\":\"بل قد أتيتم إلى جبل صهيون، وإلى مدينة الله الحي. أورشليم السماوية، وإلى ربوات هم محفل ملائكة،\",\"r\":\"«بل قد أتيتم إلى جبل صهيون، وإلى مدينة الله الحي، أورشليم السماوية». حين أصلي لا أقف وحدي، بل أدخل إلى مجمع عظيم من الملائكة والقديسين. وهذا يعطي صلاتي عمقًا ويطمئن قلبي.\",\"p\":\"يا رب، أشكرك لأنك أدخلتنا إلى مدينتك السماوية. اجعلني أصلي بإحساس الانتماء إلى كنيسة واحدة في الأرض والسماء. آمين.\",\"x\":\"في العهد القديم اقترب بنو إسرائيل من جبل سيناء بخوف ورعدة. أما في العهد الجديد فنأتي إلى جبل صهيون بثقة. ويصف الكاتب المجمع السماوي: ربوات من الملائكة، وكنيسة الأبكار، وأرواح الأبرار المكملين، ويسوع وسيط العهد الجديد. والكنيسة على الأرض متحدة بالكنيسة في السماء. ولهذا نصلي معًا في القداس، ونطلب شفاعة القديسين. وهذا يعمق الشعور بالانتماء.\\nاليوم، في صلاتك، تخيل أنك واقف في وسط جموع الملائكة والقديسين، وانضم إلى تسبيحهم.\"},{\"t\":\"اقتنوا الفضائل بأتعابهم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أرسانيوس عن المصريين: هؤلاء اقتنوا الفضائل بأتعابهم. القديسون لم يرثوا القداسة، بل جاهدوا لأجلها. التعب اليوم في محبتك للمسيح هو بذار القداسة.\",\"p\":\"يا رب، أعطني اشتياقًا إلى جهاد القديسين. لا تدعني أستسهل، بل أتعب لأجلك. آمين.\",\"x\":\"يقول الأب أرسانيوس إن المصريين الذين لا يملكون تربية العالم اقتنوا الفضائل بأتعابهم. القداسة ثمرة جهاد لا ميراث ثقافة. تدريب: اختر فضيلة وجاهد فيها اليوم بتعب حقيقي.\",\"fq\":26}]},\"8-26\":{\"th\":\"أمامك شبع سرور\",\"m\":[{\"t\":\"طلبت إلى الرب فاستجاب\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"طلبت إلى الرب فاستجاب لي. ومن جميع مخاوفي نجاني.\",\"r\":\"طلب المرنم إلى الرب فاستجاب له ونجاه من جميع مخاوفه. الشبع الحقيقي سرور في حضرته. اكتب اليوم ثلاث طلبات، وسلّمها له وانتظر.\",\"p\":\"يا رب، أشكرك لأنك تستجيب. نجّني من مخاوفي، وأشبع نفسي من سرور حضرتك. آمين.\",\"x\":\"يشهد المرنم أنه طلب إلى الرب فاستجاب ونجاه من جميع مخاوفه. الاستجابة تُرى بالرجوع إلى الوراء. تدريب: راجع ثلاث طلبات استجاب لها الله، واشكره عليها.\"},{\"t\":\"سبيل الحياة\",\"ref\":\"المزامير ١٦: ١١\",\"bk\":\"المزامير\",\"v\":\"تعرفني سبيل الحياة. أمامك شبع سرور. في يمينك نعم إلى الأبد.\",\"r\":\"«تعرفني سبيل الحياة. أمامك شبع سرور. في يمينك نعم إلى الأبد». الله لا يعطيني معلومات عن الطريق فقط، بل هو نفسه الطريق. وفي حضرته أشبع، فلا أطلب سرورًا خارجه.\",\"p\":\"يا رب، عرّفني سبيل الحياة. أمامك شبع سرور، فاملأني بحضورك حتى لا أطلب غيرك أبدًا. آمين.\",\"x\":\"المزمور ١٦ مزمور ثقة، قيل في سياق إلهام نبوي بقيامة المسيح، فاقتبسه بطرس في يوم الخمسين. والآية الأخيرة منه تجمع بين الحياة والسرور والأبدية. وكلمة «شبع» تذكرنا بالمزمور ١٧: «أشبع إذا استيقظت بشبهك». فالمؤمن يجد في الله اكتفاءً. وهذا يحمينا من الجري وراء ملذات لا تشبع. وفي القداس نأخذ سبيل الحياة في خبز الحياة.\\nاليوم، قاوم رغبة في استهلاك شيء بلا حاجة (شراء، تصفح، طعام زائد)، وبدلًا منها اجلس مع الله خمس دقائق.\"},{\"t\":\"سرور في النفس\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سينكليتيكي إن من يحتمل الجوع الطوعي يزرع في جسده حزنًا ويزرع في نفسه سرورًا وراحة. السرور الحقيقي ثمرة تضحية. ضحِّ اليوم بشيء صغير يرضيك، واشعر بسرور داخلي.\",\"p\":\"يا رب، علّمني أن أجد سروري فيك. اجعل تضحياتي ثمرة سلام في قلبي. آمين.\",\"x\":\"تقول الأم سينكليتيكي إن من يحتمل الجوع الطوعي يزرع في جسده حزنًا ويزرع في نفسه سرورًا وراحة، كالثياب التي تنغسل بالدلك. السرور يأتي من الجهاد. تدريب: احتمل اليوم تعبًا صغيرًا بفرح.\",\"fq\":534}]},\"8-27\":{\"th\":\"انتظار النفس\",\"m\":[{\"t\":\"خلاصه قريب\",\"ref\":\"المزمور ٨٤ (٨٥) — السادسة\",\"v\":\"لأن خلاصه قريب من جميع خائفيه؛ ليسكن المجد في أرضنا.\",\"r\":\"أسمع ما يتكلم به الرب، لأن خلاصه قريب من خائفيه وليسكن المجد في أرضنا. انتظار النفس صمت واستماع. اجلس اليوم عشر دقائق صامتًا وانتظر الله.\",\"p\":\"يا رب، أسمع ما تقول لأن خلاصك قريب. اجعل نفسي تنتظرك بصمت وسلام. آمين.\",\"x\":\"خلاص الله قريب من خائفيه ليسكن المجد في أرضنا. السكوت يسمح لنا أن نسمع هذا القرب. تدريب: اجلس عشر دقائق بصمت بلا طلب، وانتظر ما يقوله الرب.\"},{\"t\":\"لله انتظري يا نفسي\",\"ref\":\"المزامير ٦٢: ٥\",\"bk\":\"المزامير\",\"v\":\"إنما لله انتظري يا نفسي، لأن من قبله رجائي.\",\"r\":\"«إنما لله انتظري يا نفسي، لأن من قبله رجائي». أحيانًا تنتظر نفسي حلولًا من الناس أو الظروف، فأتعب. لكن داود يعلمني أن أخاطب نفسي وأوجهها: لله انتظري. فهو وحده يعطي رجاءً لا يخيب.\",\"p\":\"يا رب، لك وحدك أنتظر يا نفسي، فمنك رجائي. اسكب قلبي أمامك، واملأه ثقة بأنك صخرتي وخلاصي. آمين.\",\"x\":\"المزمور ٦٢ مزمور ثقة في الله وسط تهديدات، وفيه يكرر داود «إنما» (وحده) ثلاث مرات: «إنما له أنتظر. هو وحده صخرتي وخلاصي». والكلمة تعني الاستغناء عن غيره. وهو لا يستخف بالناس بل يعرف أنهم زائلون. وفي الآية ٨ يقول: «توكلوا عليه في كل حين يا قوم، اسكبوا قدامه قلوبكم». فالاتكال يصحبه سكب القلب. وبذلك نتعلم أن الصلاة تفريغ وتجديد.\\nاسكب اليوم قلبك أمام الله بكلمات حرة وصريحة، لدقيقة كاملة، ثم قل: «إنما لله انتظري يا نفسي».\"},{\"t\":\"الصمت مع التواضع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيسوى: ما تطلبه هو الصمت الكثير مع التواضع، وهنيئًا للذين يثبتون فيه. الانتظار الحقيقي سكوت داخلي. صُم اليوم عن حديث غير ضروري.\",\"p\":\"يا رب، أعطني صمتًا متواضعًا. ثبّتني في انتظارك حتى يأتي خلاصك. آمين.\",\"x\":\"يقول الأب سيسوى لأخ سأل ماذا يعمل: ما تطلبه هو الصمت الكثير مع التواضع، وهنيئًا للذين يثبتون فيه. الصمت مع التواضع طريق الخلاص. تدريب: خفف كلامك اليوم بنصف.\",\"fq\":505}]},\"8-28\":{\"th\":\"كفطيم نحو أمه\",\"m\":[{\"t\":\"مثل الفطيم على أمه\",\"ref\":\"المزمور ١٣٠ — النوم\",\"v\":\"فان كنت لم أتضع لكن رفعت صوتي مثل الفطيم من اللبن على أمه؛ كذلك المجازاة على نفسي. فليتكل إسرائيل على الرب من الآن وإلى الأبد هلليلويا.\",\"r\":\"يطلب المرنم الهدوء كالفطيم على أمه، فيتكل إسرائيل على الرب من الآن وإلى الأبد. الراحة في حضن الله لا في عظائم الأمور. اترك اليوم أمرًا أكبر منك، وارتح في يد الله.\",\"p\":\"يا رب، اجعل نفسي هادئة كالفطيم على أمه. أتكل عليك من الآن وإلى الأبد. آمين.\",\"x\":\"يشبه المرنم نفسه بفطيم على أمه، ساكنًا مطمئنًا بلا طلب عظائم. الفطيم لا يصرخ طلبًا للطعام بل يرتاح في حضنها. تدريب: اسكن اليوم في حضن الله بلا طلب، فقط وجودًا.\"},{\"t\":\"كفطيم\",\"ref\":\"المزامير ١٣١: ٢\",\"bk\":\"المزامير\",\"v\":\"بل هدأت وسكت نفسي كفطيم نحو أمه. نفسي نحوي كفطيم.\",\"r\":\"«بل هدأت وسكتت نفسي كفطيم نحو أمه». الفطيم ليس جائعًا يطلب اللبن، بل يستريح لأن أمه حاضرة. هكذا أريد أن تكون صلاتي أحيانًا: لا طلبات بل راحة في حضن الله.\",\"p\":\"يا رب، هدّئ نفسي كفطيم نحو أمه. أعطني أن أستريح في حضرتك بلا ضجيج ولا شكوى. آمين.\",\"x\":\"المزمور ١٣١ من أقصر المزامير، وهو مزمور تواضع. يبدأ داود بأنه لا يتعاطى أمورًا عظيمة، ثم يصف نفسه كطفل فُطم. والفطام يعني الانتقال من الاعتماد على اللبن إلى الاعتماد على حضور الأم. وهكذا ننتقل في حياتنا الروحية من طلب العطايا إلى طلب الله ذاته. ويختم بدعوة: «ليرجُ إسرائيل الرب من الآن وإلى الدهر». وفي عيد العذراء نتعلم من دفء الأمومة الإلهية.\\nاجلس اليوم عشر دقائق في الصلاة دون أي طلب، فقط في حضور الله، كطفل في حضن أمه.\"},{\"t\":\"طريق التواضع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب تيثوى: إن طريق التواضع هي ضبط النفس والصلاة وأن يكون المرء دون الخليقة كلها. الراحة في الله تأتي بالتواضع. مارس اليوم ضبط النفس في أمر صغير.\",\"p\":\"يا رب، علّمني طريق التواضع. أعطني ضبط النفس والصلاة. آمين.\",\"x\":\"يقول الأب تيثوى إن طريق التواضع هي ضبط النفس والصلاة وأن يكون المرء دون الخليقة كلها. وصفة من ثلاثة عناصر. تدريب: اختر عنصرًا منها وطبّقه اليوم.\",\"fq\":547}]},\"8-29\":{\"th\":\"صالح هو الرب\",\"m\":[{\"t\":\"جميع طرق الرب رحمة\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"جميع طرق الرب رحمة وحق لحافظي عهده وشهاداته.\",\"r\":\"جميع طرق الرب رحمة وحق لحافظي عهده وشهاداته. صلاح الله يظهر في كل طريق يقودنا فيه. اذكر اليوم موقفًا بدا صعبًا ثم ظهر فيه صلاح الله، واشكره.\",\"p\":\"يا رب، ما أصلحك! علّمني أن أرى رحمتك في كل طريق. آمين.\",\"x\":\"كل طرق الرب رحمة وحق لحافظي عهده، حتى الطرق الصعبة. نرى الرحمة غالبًا في الخلف. تدريب: اكتب ثلاث مواقف صعبة وتأمل كيف كانت فيها رحمة الله.\"},{\"t\":\"حصن في يوم الضيق\",\"ref\":\"ناحوم ١: ٧\",\"bk\":\"ناحوم\",\"v\":\"صالح هو الرب. حصن في يوم الضيق، وهو يعرف المتوكلين عليه.\",\"r\":\"«صالح هو الرب. حصن في يوم الضيق، وهو يعرف المتوكلين عليه». في يوم الضيق، يكون الله حصنًا. ومعنى أنه «يعرف» أنه يعتني بكل واحد باسمه وبتفاصيله. فأتكل بثقة لأن اتكالي مقدّر عنده.\",\"p\":\"يا رب، أنت صالح وحصن في يوم الضيق. أشكرك لأنك تعرفني باسمي، فأتكل عليك بكل ثقة. آمين.\",\"x\":\"سفر ناحوم يتنبأ بسقوط نينوى، العاصمة الظالمة. ومع ذلك، وسط هذه النبوة المرعبة، تأتي هذه الآية تعزية لشعب الله. فالله صالح مع المتوكلين وقاسٍ مع الظالمين. والفعل «يعرف» في العبرية يشير إلى علاقة حميمة. فهو لا يعرفنا معرفة معلومات بل معرفة رعاية. وعندما نتكل عليه نجد حصنًا. وهذا يتكرر في المزامير: «الرب حصني».\\nفي ضيق اليوم، قل: «الله حصني وهو يعرفني»، وانتبه كيف يهدأ قلبك.\"},{\"t\":\"إكليل التواضع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أور: التواضع هو إكليل الراهب. أعظم ما يزين الإنسان هو تواضعه. تعامل اليوم مع شخص أقل منك بلطف يشبه تواضع المسيح.\",\"p\":\"يا رب، توّجني بإكليل التواضع. لا تدع المجد الباطل يسلبني إكليلي. آمين.\",\"x\":\"يقول الأب أور إن التواضع هو إكليل الراهب، فهو يتوج الفضائل. بدونه تضيع. تدريب: اجعل تواضعك اليوم في موقف خدمة: اخدم بلا أن تُلاحظ.\",\"fq\":560}]},\"8-30\":{\"th\":\"في وقته\",\"m\":[{\"t\":\"إلى متى يرتفع عدوي؟\",\"ref\":\"المزمور ١٢ (١٣) — باكر\",\"v\":\"إلى متى يرتفع عدوى علي؟\",\"r\":\"يصرخ المرنم: إلى متى؟ لكن الله يأتي في وقته لا في وقتنا. الحكمة أن ننتظر دون أن نتوقف عن الصلاة. اكتب اليوم رسالة قصيرة لله عن أمر طال انتظاره.\",\"p\":\"يا رب، أنت تعرف الوقت. علّمني أن أنتظر حسب توقيتك لا توقيتي. آمين.\",\"x\":\"يصرخ المرنم: إلى متى يرتفع عدوي؟ فالله لا يتأخر لكنه يأتي في وقته. الصلاة تحمل السؤال دون يأس. تدريب: اكتب انتظارًا طويلًا وقل لله: في وقتك يا رب.\"},{\"t\":\"إن توانت فانتظرها\",\"ref\":\"حبقوق ٢: ٣\",\"bk\":\"حبقوق\",\"v\":\"لأن الرؤيا بعد إلى الميعاد، وفي النهاية تتكلم ولا تكذب. إن توانت فانتظرها لأنها ستأتي إتيانا ولا تتأخر.\",\"r\":\"«إن توانت فانتظرها، لأنها ستأتي إتيانًا ولا تتأخر». أحيانًا تبدو وعود الله متأخرة، لكن الكلمة الإلهية تقول إنها لا تتأخر. فالانتظار ثقة والبار بإيمانه يحيا. وهكذا أثبت في الانتظار، وأكتب وعوده لأتذكرها وأتحرك بها.\",\"p\":\"يا رب، أنتظر وعدك الذي لا يتأخر. البار بإيمانه يحيا، فثبّت إيماني في زمن الانتظار. آمين.\",\"x\":\"حبقوق يحتج على الله بسبب الظلم، فيجيبه الله برؤيا. وتشمل الإجابة: اكتب الرؤيا، ركّز عليها، فهي للميعاد. والبار بإيمانه يحيا، وهي الآية التي اقتبسها بولس في رومية وغلاطية. فالإيمان هو أسلوب الحياة في الانتظار. والكتابة تساعد على الثبات: أن نكتب الوعود والنعم لنتذكرها. ويقول الله: «انقشها على الألواح لكي يركض قارئها». فالكتابة مرتبطة بالحركة.\\nاكتب اليوم وعدًا من الله أو نعمة تنتظرها، وضعها في مكان تراه، وصلِّ بها كل يوم.\"},{\"t\":\"وقت الإهانة\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح البابا ثيوفيلوس الأم ثيوذورا: افتدي وقت الإهانة بالتواضع وطول الأناة، وافتدي وقت الهوان بالصبر فتربحي. وقت الله يعلمنا الصبر. إن أهانك أحد اليوم، فالتزم الهدوء ولا ترد.\",\"p\":\"يا رب، أعطني صبرًا في ساعة الإهانة. اجعل تواضعي أقوى من كبريائي. آمين.\",\"x\":\"ينصح البابا ثيوفيلوس الأم ثيوذورا بافتداء الوقت: وقت الإهانة بالتواضع وطول الأناة، ووقت الهوان بالصبر، فكل الأمور المضادة تصير ربحًا بإرادتنا. تدريب: حوّل اليوم موقف إهانة إلى فرصة صبر.\",\"fq\":147}]},\"8-31\":{\"th\":\"عهد سلام لا يتزعزع\",\"m\":[{\"t\":\"أنت ناصري\",\"ref\":\"المزمور الثالث — باكر\",\"v\":\"أنت يا رب أنت هو ناصري. مجدي ورافع رأسي.\",\"r\":\"أنت يا رب هو ناصري، مجدي ورافع رأسي. عهد سلام الله لا يتزعزع لأنه قائم على أمانته. اكتب اليوم عبارة أمان تكررها: الرب هو ناصري.\",\"p\":\"يا رب، أنت ناصري ورافع رأسي. ثبّت في قلبي عهد سلامك الذي لا يتزعزع. آمين.\",\"x\":\"الرب ناصري ومجدي ورافع رأسي، هكذا يهتف داود في المزمور الثالث وهو هارب من ابنه. الأمان لا يتوقف على الظروف. تدريب: ردد اليوم: أنت ناصري يا رب، في موقف ضعف.\"},{\"t\":\"إحساني لا يزول\",\"ref\":\"إشعياء ٥٤: ١٠\",\"bk\":\"إشعياء\",\"v\":\"فإن الجبال تزول، والآكام تتزعزع، أما إحساني فلا يزول عنك، وعهد سلامي لا يتزعزع، قال راحمك الرب.\",\"r\":\"«فإن الجبال تزول، والآكام تتزعزع، أما إحساني فلا يزول عنك، وعهد سلامي لا يتزعزع». قد تتغير الأحوال وتتهدم المشاريع وتبتعد وجوه، لكن إحسان الله ثابت. وهذا هو أساس سلامي.\",\"p\":\"يا رب، الجبال تزول وإحسانك لا يزول. أشكرك على عهد سلامك الثابت، واحفظني فيه في الشهر القادم وكل أيامي. آمين.\",\"x\":\"قيلت هذه الآية لأورشليم المهجورة التي فقدت كل شيء. فبدل الإدانة جاء وعد مواساة: «ها أنا أبني بالإثمد حجارتك». والتعبير «عهد سلامي» يربط بين الله وشعبه رباطًا لا ينفصل. والتشبيه بالجبال الراسخة يجعل ثبات الله أكبر من كل ثبات. ومن اختبر ثبات الله في الماضي يتشجع في الحاضر. وفي خاتمة شهر أغسطس نشكر الله على ثباته معنا في كل أيامه.\\nسجل اليوم ثلاث مرات أثبت فيها الله إحسانه في هذا الشهر، وحوّلها إلى صلاة شكر.\"},{\"t\":\"قلب عفيف تجاه كل واحد\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سارة: إن طلبت أن يكون الجميع مرتاحين مني، فسأكون عند باب كل واحد تائبة، لكني سأصلي ليكون قلبي عفيفًا تجاه كل واحد. السلام يبدأ بقلب نقي. صلِّ اليوم من أجل نقاء قلبك نحو شخص صعب.\",\"p\":\"يا رب، اجعل قلبي نقيًا نحو الجميع. أقِم فيّ سلامك الذي لا يتزعزع. آمين.\",\"x\":\"تقول الأم سارة إنها لن تطلب أن يرتاح الجميع منها، بل أن يكون قلبها عفيفًا تجاه كل واحد. السلام يأتي من نقاء القلب لا من رضا الجميع. تدريب: لا تحاول إرضاء الجميع اليوم، بل حافظ على قلب نقي.\",\"fq\":528}]},\"9-1\":{\"th\":\"شكر ختام السنة\",\"m\":[{\"t\":\"إلى الأبد أعترف لك\",\"ref\":\"المزمور ٢٩ (٣٠) — الثالثة\",\"v\":\"أيها الرب إلهي إلى الأبد أعترف لك.\",\"r\":\"نبدأ السنة القبطية الجديدة بالشكر قبل الطلب. يعترف المرنم للرب إلى الأبد لأن رحمته لا تنقطع. اكتب اليوم ثلاث نعم صنعها الله معك في السنة الماضية، وصلِّ بها شكرًا.\",\"p\":\"يا رب إلهي، إلى الأبد أعترف لك. أشكرك على سنة مضت بنعمتك، وبارك أيامي الجديدة. آمين.\",\"x\":\"نبدأ السنة القبطية الجديدة بالاعتراف لله إلى الأبد، فالشكر يسبق الطلب. من يشكر يرى أن عامه كله كان محمولًا برحمة. تدريب: اكتب ثلاث نعم من العام الماضي لم تشكر عليها بعد، وقل لله: شكرًا.\"},{\"t\":\"يكللك بالرحمة\",\"ref\":\"المزامير ١٠٣: ٤\",\"bk\":\"المزامير\",\"v\":\"الذي يفدي من الحفرة حياتك. الذي يكللك بالرحمة والرأفة.\",\"r\":\"«الذي يفدي من الحفرة حياتك. الذي يكللك بالرحمة والرأفة». الله لم ينقذني فقط من السقوط، بل وضع على رأسي إكليلًا من الرحمة. ومع اقتراب نهاية السنة القبطية أتذكر كم حملتني رحمته في كل شهر، وأشكره من قلبي.\",\"p\":\"يا رب، أشكرك لأنك فديت حياتي من الحفرة وكللتني بالرحمة والرأفة طوال هذه السنة. باركني بالمزيد من نعمتك. آمين.\",\"x\":\"المزمور ١٠٣ يبدأ بدعوة النفس أن تبارك الرب ولا تنسى كل حسناته. ثم يعدد: يغفر، ويشفي، ويفدي، ويكلل، ويشبع. والإكليل في الكتاب علامة كرامة، فالله يعاملنا كملوك صغار لا كعبيد. وتأتي هذه الآية قبل أن يقول: «يشبع بالخير عمرك فيتجدد مثل النسر شبابك». والسنة القبطية على وشك أن تنتهي، فهي فرصة للتذكر والشكر قبل بدء عام جديد.\\nاكتب اليوم ثلاث رحمات خاصة نلتها هذه السنة، وارفعها شكرًا قبل النوم.\"},{\"t\":\"الشكر على الصمت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بمفو: الشكر لله أنني منذ رفضت العالم لم أندم على كلمة تلفظت بها. من يختم عامه بقلب مطمئن على ما قاله وفعله فقد ربح كثيرًا. راجع اليوم كلماتك في العام الماضي، واطلب مسامحة من جرحتهم.\",\"p\":\"يا رب، أشكرك على حفظك لساني. اغفر لي كلماتي الجارحة، وضع حارسًا على فمي في العام الجديد. آمين.\",\"x\":\"يقول الأب بمفو: الشكر لله أنني منذ أن رفضت العالم لم أندم على كلمة تلفظت بها. من يحفظ لسانه يختم عامه مطمئنًا. تدريب: اختم يومك بمراجعة كلماتك، وإن ندمت على كلمة فاعتذر عنها.\",\"fq\":458}]},\"9-2\":{\"th\":\"أغني للرب في حياتي\",\"m\":[{\"t\":\"أسبح الرب في حياتي\",\"ref\":\"المزمور ١٤٥ — النوم\",\"v\":\"سبحي يا نفسي الرب، أسبح الرب في حياتي وأرتل لإلهي ما دمت موجودا.\",\"r\":\"يقرر المرنم أن يسبح الرب ما دام موجودًا، فالتسبيح عمل العمر كله لا لحظة عابرة. أغنية الحياة تبدأ بنية يومية. رتّل اليوم مزمورًا أو ترنيمة في وقت غير متوقع، في الطريق أو المطبخ.\",\"p\":\"يا رب، أسبحك في حياتي كلها وأرتل لك ما دمت موجودًا. اجعل أيامي ترنيمة شكر لك. آمين.\",\"x\":\"يتعهد المرنم أن يسبح الرب في حياته ما دام موجودًا، فالتسبيح عمل العمر لا مناسبة. تدريب: اجعل لك كلمة تسبيح قصيرة تقولها في كل مرة تبدأ فيها عملًا اليوم.\"},{\"t\":\"أرنم ما دمت موجودًا\",\"ref\":\"المزامير ١٠٤: ٣٣\",\"bk\":\"المزامير\",\"v\":\"أغني للرب في حياتي. أرنم لإلهي ما دمت موجودا.\",\"r\":\"«أغني للرب في حياتي. أرنم لإلهي ما دمت موجودًا». لم يقل داود: عندما أشعر أو عندما أكون بخير، بل ما دمت موجودًا. فالترنيم ليس مزاجًا بل قرار حياة. وأريد أن أقرر اليوم أن أجعل التسبيح عادتي.\",\"p\":\"يا رب، أغني لك في حياتي كلها وأرنم لإلهي ما دمت موجودًا. اجعل نشيدي لذيذًا لك، وفرّح قلبي بك. آمين.\",\"x\":\"المزمور ١٠٤ نشيد للخليقة، يمتدح الله الذي يكسو السماء ويسقي الجبال ويطعم الوحوش. وفي ختامه ينتقل إلى الإنسان الذي يرد على هذه العناية بالغناء. والعبارة «فيلذ له نشيدي» تعبّر عن رغبة المرنم أن يرضى الله عن ترنيمه. ثم يقول: «أنا أفرح بالرب». فالتسبيح يصنع فرحًا. وهذا ما تعلمه الكنيسة: أن التسبحة ليست واجبًا ثقيلًا بل ينبوع فرح.\\nاختر ترنيمة أو لحنًا تحبه، وغنِّه بصوت مرتفع اليوم، ولو في السيارة أو المطبخ.\"},{\"t\":\"أفواه طاهرة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بمفو عن الرهبان: هؤلاء يتكلمون مع الله على الدوام وأفواههم طاهرة. الفم الذي يسبح لا يليق به أن يدين. اجعل لك اليوم ساعة بلا نقد ولا شكوى، ولا يخرج منها إلا تسبيح.\",\"p\":\"يا رب، طهّر فمي لأتكلم معك على الدوام. اجعل كلماتي تسبيحًا وبركة لمن يسمعني. آمين.\",\"x\":\"رأى الأب بمفو أناسًا من أهل العالم جالسين فقال لمن معه: انهضوا وقبّلوا الرهبان لكي تتباركوا، فهؤلاء يتكلمون مع الله على الدوام وأفواههم طاهرة. الفم المسبّح مكرَّم. تدريب: صُن فمك اليوم من كل كلمة لا تليق بالتسبيح.\",\"fq\":460}]},\"9-3\":{\"th\":\"أبواب الحمد\",\"m\":[{\"t\":\"ابتدئوا للرب بالاعتراف\",\"ref\":\"المزمور ١٤٦ — النوم\",\"v\":\"ابتدئوا للرب بالاعتراف. رتلوا لإلهنا بالقيثارة.\",\"r\":\"يدعونا المرنم أن نبتدئ للرب بالاعتراف ونرتل له بالقيثارة. أبواب الحمد تُفتح بشكر صادق. ابدأ يومك اليوم بكلمة حمد واحدة قبل أي هاتف أو رسالة.\",\"p\":\"يا رب، افتح لي أبواب الحمد. أبتدئ يومي بالاعتراف بصلاحك، وأرتل لك بقلب شاكر. آمين.\",\"x\":\"يدعونا المرنم أن نبتدئ للرب بالاعتراف وأن نرتل له بالقيثارة، فالحمد يبدأ بالشكر. تدريب: قبل أن تطلب شيئًا اليوم، قل لله ثلاث جمل شكر.\"},{\"t\":\"إن إلى الأبد رحمته\",\"ref\":\"المزامير ١١٨: ١\",\"bk\":\"المزامير\",\"v\":\"احمدوا الرب لأنه صالح، لأن إلى الأبد رحمته.\",\"r\":\"«احمدوا الرب لأنه صالح، لأن إلى الأبد رحمته». هذه الدعوة تفتتح مزمورًا يغنيه شعب الله عند دخول بيت الرب. وأنا أدخل حياتي اليومية بنفس الروح، شاكرًا قبل أن أطلب.\",\"p\":\"يا رب، أحمدك لأنك صالح ورحمتك إلى الأبد. أدخل أبوابك بحمد، فاقبلني في حضرتك. آمين.  ثبّتنا في بيتك كل أيامنا يا رب.\",\"x\":\"المزمور ١١٨ من مزامير الهلل التي كانت تُرتل في الفصح اليهودي، وقد رنمها الرب وتلاميذه ليلة العشاء الأخير. ففيه يظهر المسيح حجر الزاوية الذي رفضه البناؤون. وتحمل الكنيسة هذا المزمور في أعياد القيامة. والدعوة للحمد في أوله تضعنا في جو الاحتفال. فالشكر هو مدخل إلى حضرة الله، كما يقول المزمور ١٠٠: «ادخلوا أبوابه بحمد».\\nابدأ صلاتك اليوم بدقيقة من الحمد فقط قبل أي طلب، وانظر كيف يتغير اتجاه قلبك.\"},{\"t\":\"لا كذب في الفم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أنوف: منذ أن حل عليّ اسم المسيح لم يخرج من فمي كذب. الحمد الصادق يحتاج لسانًا صادقًا. اختر اليوم ألا تقول أي مبالغة أو كذبة صغيرة، حتى المجاملة.\",\"p\":\"يا رب، اجعلني أحمل اسمك بصدق. احفظ فمي من الكذب، ليخرج منه حمد وحق. آمين.\",\"x\":\"يقول الأب أنوف: منذ أن حلّ عليّ اسم المسيح لم يخرج من فمي كذب. اسم المسيح على الإنسان يحرس لسانه. تدريب: قبل أن تتكلم اليوم اسأل: هل هذا صدق كامل؟\",\"fq\":70}]},\"9-4\":{\"th\":\"أرى جود الرب\",\"m\":[{\"t\":\"رحمتك تدركني\",\"ref\":\"المزمور ٢٢ (٢٣) — الثالثة\",\"v\":\"هيأت قدامى مائدة تجاه مضايقي. مسحت بالزيت رأسي. وكأسك روتني بقوة. ورحمتك تدركني جميع أيام حياتي، ومسكني في بيت الرب إلى مدى الأيام.\",\"r\":\"يصف المرنم مائدة أعدها الله ورأسًا مسحه بالزيت وكأسًا ريانة، ثم تدركه الرحمة كل أيام حياته. جود الرب يُرى في التفاصيل اليومية. انتبه اليوم إلى ثلاثة أشياء صغيرة تعطيها لك نعمته وسط الزحام.\",\"p\":\"يا رب، أنت راعيّ فلا يعوزني شيء. أشكرك على مائدتك ورحمتك التي تدركني، واجعلني أسكن في بيتك. آمين.\",\"x\":\"هيأ الله مائدة قدام المضايقين ومسح الرأس بالزيت وملأ الكأس، فجوده يظهر وسط الضيق. تدريب: ابحث اليوم عن مائدة أعدها الله لك في وسط موقف صعب، واشكره عليها.\"},{\"t\":\"آمنت بأن أرى جود الرب\",\"ref\":\"المزامير ٢٧: ١٣\",\"bk\":\"المزامير\",\"v\":\"لولا أنني آمنت بأن أرى جود الربفي أرض الأحياء.\",\"r\":\"«لولا أنني آمنت بأن أرى جود الرب في أرض الأحياء». نصف الجملة يتركه داود مفتوحًا: لولا الإيمان لكان الأمر أصعب. فالإيمان بأنني سأرى صلاح الله في هذه الحياة هو ما يمسكني في أصعب اللحظات.\",\"p\":\"يا رب، أؤمن بأنني سأرى جودك في أرض الأحياء. قوِّ إيماني في ساعات الانتظار، وافتح عيني لرؤية خيراتك. آمين.\",\"x\":\"المزمور ٢٧ يبدأ بالثقة: «الرب نوري وخلاصي ممن أخاف؟» وسط حرب وأعداء. وبعد طلب السكنى في بيت الرب، يعبّر عن الجملة الناقصة. وبعدها: «انتظر الرب. ليتشدد وليتشجع قلبك». فالإيمان بالجود المقبل يدعو إلى الصبر. ولا يقول «في السماء» فقط بل «أرض الأحياء» أي هنا والآن. فالله يظهر جوده في حياتنا قبل الأبدية.\\nاليوم، ابحث عن علامة صغيرة لجود الله في حياتك، ولو تفصيلة بسيطة، وسجلها.\"},{\"t\":\"آخذ وأعطي\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب زينون: إذا قدّم لي أحد شيئًا آخذه، وإذا جاء أحد يطلب شيئًا أعطيه إياه. بساطة العطاء والقبول ترى جود الله في عطايا الناس. اقبل اليوم عطية صغيرة بشكر، وأعطِ من يسألك دون تردد.\",\"p\":\"يا رب، علّمني أن أقبل بشكر وأعطي بفرح. اجعل بيتي مفتوحًا لعطاياك ولمحتاجيك. آمين.\",\"x\":\"قال الأب زينون عن نفسه: إذا قدّم لي أحد شيئًا آخذه، وإذا جاء أحد يطلب شيئًا أعطيه إياه. قالها لما رأى أن كل من يأتون إليه يعودون محزونين. بساطة القبول والعطاء تريح الناس. تدريب: اقبل اليوم عطية بامتنان، وأعطِ من يطلب بلا تردد.\",\"fq\":115}]},\"9-5\":{\"th\":\"طرقك علمني\",\"m\":[{\"t\":\"على الصخرة رفعتني وأرشدتني\",\"ref\":\"المزمور ٦٠ (٦١) — السادسة\",\"v\":\"استمع يا الله طلبتي، وأصغ إلى صلاتي. من أقاصي الأرض صرخت إليك، عندما ضجر قلبي. على الصخرة رفعتني وأرشدتني.\",\"r\":\"يصرخ المرنم من أقاصي الأرض عندما يضجر قلبه، فيرفعه الله على صخرة ويرشده. الله لا يسمع صلاة من يعلم الطريق فقط، بل من يطلب الإرشاد. اسأل الله اليوم: ما هي الخطوة التالية؟ وانتظر جوابه.\",\"p\":\"يا رب، استمع طلبتي وأصغ إلى صلاتي. ارفعني على الصخرة وأرشدني في طريقي. آمين.\",\"x\":\"صرخ المرنم من أقاصي الأرض عندما ضجر قلبه، فرفعه الله على صخرة وأرشده. الإرشاد يأتي لمن يصرخ. تدريب: قل لله اليوم بصراحة ما يضجر قلبك، واطلب أن يرشدك خطوة واحدة.\"},{\"t\":\"عرفني طرقك\",\"ref\":\"المزامير ٢٥: ٤\",\"bk\":\"المزامير\",\"v\":\"طرقك يا رب عرفني. سبلك علمني.\",\"r\":\"«طرقك يا رب عرفني. سبلك علمني». هذه صلاة تلميذ. لا يطلب داود أن يغير الله طريقه بل أن يعلمه طريق الله. وكل يوم أحتاج أن أبدأ بالسؤال: ما هي طرقك اليوم يا رب؟\",\"p\":\"يا رب، عرفني طرقك وعلمني سبلك. دربني في حقك فإنك أنت إله خلاصي، وإياك أنتظر اليوم كله. آمين.\",\"x\":\"المزمور ٢٥ مزمور تعليم وتوبة، مرتب أبجديًا. يبدأ برفع النفس إلى الله والاتكال عليه. ثم يطلب المعرفة والتدريب. والتدريب في الحق يعني ممارسة بالتدريج. ويقدم السبب: «أنت إله خلاصي، إياك انتظرت اليوم كله». فالصلاة مرتبطة بانتظار طويل. وتتعلم النفس من الله لا من أفكارها فقط. ولهذا نبدأ الصلاة بالإصغاء.\\nاسأل الله في صباحك: ما هي طريقك اليوم؟ واكتب أول فكرة سلام تأتي إليك.\"},{\"t\":\"إرادة الله حيثما ذهبت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إسحق كاهن القلالي: لن أهرب بعد الآن لأن هذه إرادة الله، فحيثما ذهبت أصل إلى ذلك بعينه. الإرشاد أن نثبت في ما وضعنا الله فيه. اقبل اليوم ظرفًا تحاول الهرب منه، واطلب فيه حضور الله.\",\"p\":\"يا رب، علّمني أن أقبل مشيئتك. أعطني ألا أهرب من ظروفي بل أجد فيها طريقك. آمين.\",\"x\":\"لما جاءوا ليشرطنوا الأب إسحق كاهنًا فرّ، ثم وجدوه فقال: لن أهرب بعد الآن لأن هذه إرادة الله، فحيثما ذهبت أصل إلى ذلك بعينه. إرادة الله تدركنا حيث نكون. تدريب: لا تهرب اليوم من مسؤولية جاءتك.\",\"fq\":176}]},\"9-6\":{\"th\":\"كلمتك في قلبي\",\"m\":[{\"t\":\"لساني ينطق بأقوالك\",\"ref\":\"المزمور ١١٨ — الجزء الثاني والعشرون («كُونوا مُستَعِدّينَ، لأنَّهُ في ساعَةٍ لا تَظُنّونَ يَأتي ابنُ الإنسان.») — الستار\",\"v\":\"تفيض شفتاي السبح إذا ما علمتني حقوقك. لساني ينطق بأقوالك لأن جميع وصاياك عادلة. لتكن يدك لخلاصي لأنني اشتهيت وصاياك.\",\"r\":\"يطلب المرنم أن تفيض شفتاه تسبيحًا إذا علمه الله حقوقه، وأن ينطق لسانه بأقواله. كلمة الله لا تبقى في الذاكرة بل تنتقل إلى القلب. اقرأ اليوم آية وحاول أن تحفظها بتكرارها صامتًا ثلاث مرات.\",\"p\":\"يا رب، علّمني حقوقك فتفيض شفتاي بالتسبيح. لتكن يدك لخلاصي، فقد اشتهيت وصاياك. آمين.\",\"x\":\"يطلب المرنم أن تفيض شفتاه تسبيحًا إذا علّمه الله حقوقه، ويقول إن لسانه ينطق بأقواله لأن وصاياه عادلة. التعلم يتحول إلى كلام. تدريب: احفظ آية قصيرة وقلها لشخص اليوم.\"},{\"t\":\"خبأت كلامك في قلبي\",\"ref\":\"المزامير ١١٩: ١١\",\"bk\":\"المزامير\",\"v\":\"خبأت كلامك في قلبي لكيلا أخطئ إليك.\",\"r\":\"«خبأت كلامك في قلبي لكيلا أخطئ إليك». الكلمة المحفوظة في القلب حاضرة لحظة التجربة، مثل سلاح مخبأ. فالقراءة السطحية لا تكفي، بل أحتاج أن أحفظ آيات وأتأمل فيها حتى تصير جزءًا مني.\",\"p\":\"يا رب، أخبئ كلامك في قلبي لكيلا أخطئ إليك. ثبّت كلمتك فيّ وذكّرني بها في ساعات التجربة. آمين.\",\"x\":\"في المزمور ١١٩، أطول المزامير، كل آيات القسم تبدأ بنفس الحرف العبري. وهذا القسم يسأل: كيف يزكي الشاب طريقه؟ بحفظه حسب كلامك. ويجيب بخطوات: طلب الله بكل القلب، وحفظ الكلام فيه، والمباركة، والتعليم، والتحدث بالأحكام. والمسيح نفسه قاوم التجربة في البرية بآيات حفظها. فالحفظ ليس ترفًا بل حماية.\\nاحفظ اليوم آية واحدة من اختيارك، وراجعها ثلاث مرات في اليوم.\"},{\"t\":\"ما في القلب ينطق به الفم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب بيمن: علّم فمك أن ينطق بمكنونات قلبك. حين يمتلئ القلب بكلمة الله ينطق الفم بها. اجعل اليوم كلمة الله حاضرة في محادثة واحدة، لا بوعظ بل بصدق.\",\"p\":\"يا رب، املأ قلبي بكلمتك ليتكلم فمي بها. احفظني من التناقض بين فمي وقلبي. آمين.\",\"x\":\"يوصي الأب بيمن: علّم فمك أن ينطق بمكنونات قلبك. أي أن يصير الكلام صدى للداخل. تدريب: راقب اليوم هل يوافق كلامك ما في قلبك، وإن اختلفا فصحّح الاثنين.\",\"fq\":360}]},\"9-7\":{\"th\":\"كلمة تثبت\",\"m\":[{\"t\":\"المخبر كلمته ليعقوب\",\"ref\":\"المزمور ١٤٧ — النوم\",\"v\":\"المخبر كلمته ليعقوب وفرائضه وأحكامه لإسرائيل.\",\"r\":\"الله يخبر بكلمته وفرائضه وأحكامه شعبه، والعشب يجف أما كلمته فتثبت. ما يثبت في الحياة هو ما بُني على كلمته. اختر اليوم قرارًا واحدًا تبنيه على وعد من وعود الله.\",\"p\":\"يا رب، كلمتك تثبت إلى الأبد. ثبّت قلبي على وعودك، ولا تدعني أبني على رمال الظنون. آمين.\",\"x\":\"الله يخبر بكلمته وفرائضه وأحكامه شعبه، وكلمته تثبت وإن جفّ العشب. ما نبنيه عليها يثبت. تدريب: اختر قرارًا اليوم وابنه على وصية محددة.\"},{\"t\":\"كلمة إلهنا تثبت\",\"ref\":\"إشعياء ٤٠: ٨\",\"bk\":\"إشعياء\",\"v\":\"يبس العشب، ذبل الزهر. وأما كلمة إلهنا فتثبت إلى الأبد».\",\"r\":\"«يبس العشب، ذبل الزهر. وأما كلمة إلهنا فتثبت إلى الأبد». كم من الأشياء التي كنت أظنها دائمة ذبلت. لكن كلمة الله لم تتغير. وعندما أبني حياتي عليها، أبني على ما لا يزول.\",\"p\":\"يا رب، كل جسد عشب وكلمتك تثبت إلى الأبد. اجعلني أبني حياتي على كلمتك التي لا تزول. آمين.\",\"x\":\"الأصحاح ٤٠ في إشعياء يبدأ بنبرة تعزية: «عزوا عزوا شعبي». وسط هذا الأصحاح يقارن بين هشاشة الإنسان وثبات كلمة الله. فالكل «عشب» أي زائل. وقد اقتبس بطرس هذه الآية في رسالته الأولى مضيفًا: «وهذه هي الكلمة التي بشرتم بها». فالإنجيل هو الكلمة الباقية. وهذا يعطينا ثقة في زمن الأخبار المتغيرة.\\nاليوم، عندما تقلقك تقلبات الأخبار أو الأسواق، اقرأ هذه الآية وقل: «كلمتك تثبت».\"},{\"t\":\"حفظ وصايا الآباء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب موسى: إذا حفظنا وصايا آبائنا أضمن لكم أن البرابرة لا يأتون إلى هنا، وإن لم نحفظها فإن المنطقة هذه ستقفر. الكلمة التي تثبت هي التي نحفظها ونسلمها. التزم اليوم بوصية واحدة تسلمتها من آبائك.\",\"p\":\"يا رب، علّمني أن أحفظ تعليم آبائي. ثبّت في قلبي كلمتك، وسلّمها لمن بعدي. آمين.\",\"x\":\"قال الأب موسى في الأسقيط: إذا حفظنا وصايا آبائنا فإني أضمن لكم أن البرابرة لا يأتون إلى هنا، وإن لم نحفظها فإن المنطقة هذه ستقفر. حفظ الوصية حماية للمكان. تدريب: التزم اليوم بوصية واحدة تهملها.\",\"fq\":257}]},\"9-8\":{\"th\":\"هلموا إلى المياه\",\"m\":[{\"t\":\"تهب ريحه فتسيل المياه\",\"ref\":\"المزمور ١٤٧ — النوم\",\"v\":\"يرسل كلمته فتذيبه، تهب ريحه فتسيل المياه.\",\"r\":\"يسبح المرنم الله الذي يرسل كلمته فتذيب الجليد وتهب ريحه فتسيل المياه. كل ما يُروى به الإنسان من عطشه من يديه. هلموا إلى المياه التي لا تُشترى. أصغ اليوم إلى عطش داخلك وسمّه، ثم قدمه لله.\",\"p\":\"يا رب، أنت ينبوع الماء الحي. أرو عطشي بكلمتك، ولا تدعني أشرب من آبار مشققة. آمين.\",\"x\":\"يرسل الله كلمته فتذيب الجليد وتهب ريحه فتسيل المياه، فالكلمة تحرك ما تجمد فينا. تدريب: حدد قلبًا متجمدًا في داخلك، واقرأ له آية دافئة.\"},{\"t\":\"أيها العطاش هلموا\",\"ref\":\"إشعياء ٥٥: ١\",\"bk\":\"إشعياء\",\"v\":\"«أيها العطاش جميعا هلموا إلى المياه، والذي ليس له فضة تعالوا اشتروا وكلوا. هلموا اشتروا بلا فضة وبلا ثمن خمرا ولبنا.\",\"r\":\"«أيها العطاش جميعًا هلموا إلى المياه». دعوة لا تشترط استحقاقًا ولا مالًا. يكفي أن أعطش. وفي كثير من الأحيان أحاول أن أدفع ثمن النعمة بأعمالي، لكن الله يقول: تعال بلا فضة.\",\"p\":\"يا رب، أنا عطشان إليك. هلم بي إلى ينبوعك المجاني، واروِ نفسي بروحك القدوس. آمين.  واسقني من ينبوعك كل يوم يا رب.\",\"x\":\"إشعياء ٥٥ يختم القسم الثاني من السفر بدعوة مفتوحة. والمياه والخمر واللبن رموز لنعم الروح. والمسيح قال في الهيكل: «إن عطش أحد فليقبل إلي ويشرب». والكنيسة ترى في هذه الآية دعوة إلى الأسرار الإلهية. وفي الآية ٢ يسأل: لماذا تزنون فضة لغير خبز؟ أي لماذا نصرف عمرنا في ما لا يشبع. والتوبة هي تغيير الاتجاه نحو ما يشبع حقًا.\\nاعترف اليوم بعطش حقيقي في قلبك، وقل للمسيح: «أنا عطشان، اسقني».\"},{\"t\":\"ينابيع الماء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن الرهبان عندما يقيمون في البرية يلتهبون بسم الشياطين، فيأتون إلى ينابيع الماء، أعني جسد المسيح ودمه، ليتطهروا من مرارة الشرير. الشركة المقدسة ينبوع لا ينضب. حاول اليوم أن تتناول من الأسرار باستعداد.\",\"p\":\"يا رب، أنت الينبوع الحي. اغسلني بجسدك ودمك، وأرو عطشي بحضورك. آمين.\",\"x\":\"يفسر الأب بيمن «كما تتوق الإيل إلى ينابيع المياه»: الرهبان في البرية يلتهبون بسم الشياطين فيطلبون السبت والأحد ليأتوا إلى ينابيع الماء، أعني جسد المسيح ودمه، ليتطهروا. التناول ينبوع. تدريب: اشتاق اليوم للتناول القادم واستعد له بتوبة.\",\"fq\":330}]},\"9-9\":{\"th\":\"روح الرب علي\",\"m\":[{\"t\":\"انسكبت النعمة على شفتيك\",\"ref\":\"المزمور ٤٤ (٤٥) — الثالثة\",\"v\":\"وقد انسكبت النعمة على شفتيك. فلذلك باركك الله إلى الدهر.\",\"r\":\"انسكبت النعمة على الشفتين، فباركه الله إلى الدهر. مسحة الروح تُعطى لخدمة الكلمة والرحمة. اطلب اليوم من الله أن يمسحك لخدمة واحدة تقدمها: كلمة تشجيع أو قراءة أو تعليم.\",\"p\":\"يا رب، روحك عليّ لأبشر المساكين وأعصب منكسري القلوب. انسكب نعمتك عليّ لأخدم باسمك. آمين.\",\"x\":\"انسكبت النعمة على الشفتين فباركه الله إلى الدهر. المسحة تُعطى للخدمة بالكلمة والرحمة. تدريب: اطلب اليوم من الله نعمة كلمة تعزي بها أحدًا، وقلها.\"},{\"t\":\"مسحني لأبشر\",\"ref\":\"إشعياء ٦١: ١\",\"bk\":\"إشعياء\",\"v\":\"روح السيد الرب علي، لأن الرب مسحني لأبشر المساكين، أرسلني لأعصب منكسري القلب، لأنادي للمسبيين بالعتق، وللمأسورين بالإطلاق.\",\"r\":\"«روح السيد الرب علي، لأن الرب مسحني لأبشر المساكين». هذه رسالة المسيح، وهي تصير رسالتي بقدر ما أحمل روحه. فالمسحة ليست امتيازًا بل خدمة للمنكسرين والمأسورين.  فاجعلني يا رب أحمل بشارتك للمنكسرين حولي.\",\"p\":\"يا رب، روحك عليّ فأبشر المساكين وأعصب المنكسرين. استخدمني لتحرير المأسورين وتعزية الحزانى. آمين.  املأني بروحك لأخدم المتألمين بفرح، يا رب.\",\"x\":\"قرأ يسوع هذا النص في مجمع الناصرة ثم قال: «اليوم قد تم هذا المكتوب في مسامعكم». فهو المسيح، أي الممسوح. وتشمل رسالته: تبشير المساكين، وتضميد المنكسرين، وإعلان الحرية للمأسورين، وسنة مقبولة للرب. والكنيسة ممسوحة بالميرون لتكمل هذه الرسالة. وكل مؤمن يحمل نصيبًا من هذه المسحة. فالخدمة لأصحاب الحاجة هي في صميم الإيمان.\\nاختر اليوم شخصًا مكسور القلب وتقدم إليه بكلمة تعزية أو زيارة، كخادم للمسيح.\"},{\"t\":\"موهبة تأخذ زمنًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب مكاريوس: لقد أمضيت اثنتي عشرة سنة في خدمة ربي كي يمنحني هذه الموهبة. المواهب الروحية تنمو بالصبر والخدمة الطويلة. لا تيأس من موهبتك البطيئة، واستمر اليوم في تنميتها.\",\"p\":\"يا رب، أعطني صبرًا في خدمتك. وعلّمني ألا أستعجل مواهب روحك، بل أطلبها بتواضع. آمين.\",\"x\":\"ردّ الأب مكاريوس على من لامه على بساطته مع الإخوة: لقد أمضيت اثنتي عشرة سنة في خدمة ربي كي يمنحني هذه الموهبة، وها أنتم تنصحونني بالتخلي عنها. المواهب تنمو بالصبر والخدمة. تدريب: نمّ موهبة لديك بخطوة صغيرة اليوم.\",\"fq\":236}]},\"9-10\":{\"th\":\"استعداد للعام الجديد\",\"m\":[{\"t\":\"انتظرت نفسي الرب\",\"ref\":\"المزمور ١٢٩ (١٣٠) — النوم\",\"v\":\"صبرت نفسي لناموسك. انتظرت نفسي الرب من محرس الصبح إلى الليل.\",\"r\":\"صبرت نفس المرنم لناموس الرب وانتظرته من محرس الصبح إلى الليل. بداية عام جديد فرصة لتجديد كل شيء. حدد اليوم مجالًا واحدًا تريد أن تتغير فيه في هذا العام، وسلّمه للرب.\",\"p\":\"يا رب، أنت تعطي حياة جديدة. صبرت نفسي لناموسك، فأعدّني لعام جديد ببركتك. آمين.\",\"x\":\"صبرت نفس المرنم لناموس الرب وانتظرته من محرس الصبح إلى الليل. بداية العام فرصة لانتظار الرب بلا استعجال. تدريب: اكتب أمرًا واحدًا تريد أن يجدده الله فيك هذا العام.\"},{\"t\":\"أعوض لكم عن السنين\",\"ref\":\"يوئيل ٢: ٢٥\",\"bk\":\"يوئيل\",\"v\":\"«وأعوض لكم عن السنين التي أكلها الجراد، الغوغاء والطيار والقمص، جيشي العظيم الذي أرسلته عليكم.\",\"r\":\"«وأعوض لكم عن السنين التي أكلها الجراد». كم من سنوات أظن أنها ضاعت بالخطية أو الإهمال أو المرض. والله يعد بالتعويض. فلا أدخل العام الجديد بحسرة على الماضي بل برجاء أن الله يستطيع أن يرد.\",\"p\":\"يا رب، اعوض لي عن السنين التي أكلها الجراد. أسلمك ماضيّ كله، فاصنع معي عجبًا واملأ فمي تسبيحًا. آمين.\",\"x\":\"سفر يوئيل يبدأ بوصف غزو الجراد الذي ترك الأرض خرابًا. ثم يدعو إلى التوبة بقلب ممزق لا ثياب. وبعد التوبة تأتي الوعود: المطر والخير والتعويض. والتعويض لا يتم بمعجزة سحرية بل بنعمة تُجدد الحياة. وفي الآية التالية: «فتأكلون أكلًا وتشبعون وتسبحون اسم الرب إلهكم الذي صنع معكم عجبًا». فالنتيجة تسبيح. وفي ختام السنة نسلم الماضي إلى الله.\\nاكتب اليوم «سنة» أو فترة ظنت أنها ضاعت، وصلِّ: «يا رب عوّض».\"},{\"t\":\"أن أهدم لأبني\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ألونيوس: إذا لم أهدم كل شيء لا أستطيع أن أبني نفسي. التجديد يبدأ بالتخلي عما لا يصلح. تخلَّ اليوم عن عادة أو فكرة قديمة تعطل نموّك.\",\"p\":\"يا رب، اهدم فيّ ما لا يرضيك وابنني من جديد. اجعل عامي الجديد بداية أخرى معك. آمين.\",\"x\":\"يقول الأب ألونيوس: إذا لم أهدم كل شيء لا أستطيع أن أبني نفسي. البناء الجديد يحتاج هدم القديم الفاسد. تدريب: اهدم اليوم عادة واحدة تعطل نموك.\",\"fq\":73}]},\"9-11\":{\"th\":\"النيروز: عيد الشهداء\",\"m\":[{\"t\":\"الصديقون صرخوا\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"الصديقون صرخوا والرب استجاب لهم، ومن جميع شدائدهم نجاهم.\",\"r\":\"الصديقون صرخوا والرب استجاب لهم ومن جميع شدائدهم نجاهم. في عيد النيروز نذكر شهداء الكنيسة الذين صرخوا إليه وسط الاضطهاد. صلِّ اليوم من أجل المضطهدين في العالم كله.\",\"p\":\"يا رب، استجب لصرخة شهدائك ومضطهدي كنيستك. أعطني شجاعة الأمانة حتى الموت. آمين.\",\"x\":\"صرخ الصديقون والرب استجاب ونجاهم من كل شدائدهم، وهذه شهادة الشهداء. في النيروز نذكر أنهم أحبوا المسيح أكثر من حياتهم. تدريب: اذكر شهيدًا بالاسم اليوم واطلب أن يعطيك شجاعة في موقف إيمان.\"},{\"t\":\"كن أمينًا إلى الموت\",\"ref\":\"رؤيا يوحنا ٢: ١٠\",\"bk\":\"رؤيا يوحنا\",\"v\":\"لا تخف البتة مما أنت عتيد أن تتألم به. هوذا إبليس مزمع أن يلقي بعضا منكم في السجن لكي تجربوا، ويكون لكم ضيق عشرة أيام. كن أمينا إلى الموت فسأعطيك إكليل الحياة.\",\"r\":\"«كن أمينًا إلى الموت فسأعطيك إكليل الحياة». في أول توت تبدأ الكنيسة سنتها القبطية المسماة تقويم الشهداء، فتذكّرنا أن بدايتنا مبنية على أمانة أولادها. وأنا لست مطالبًا اليوم بالموت، لكنني مطالب بأمانة صغيرة في كلمة صادقة وعمل نزيه.\",\"p\":\"يا رب، أشكرك على شهدائك الذين ثبتوا حتى الدم. امنحني أمانة في الصغير والكبير، ولا تدعني أخاف من الحق، واجعلني شاهدًا لك بحياتي. آمين.\",\"x\":\"رسالة الرب إلى ملاك كنيسة سميرنا تبدأ بكلمة «لا تخف». فالخوف هو أول ما يقيّد الشهادة، والرب يعالجه بوعد إكليل. ويرتبط النيروز في الكنيسة القبطية ببداية تقويم الشهداء الذي يؤرخ من عصر دقلديانوس، حين ثبت المؤمنون على إيمانهم رغم الاضطهاد. وقد صارت دماؤهم بذارًا للكنيسة كما يقول التقليد. والأمانة ليست حدثًا واحدًا بل طريق يومي نسلكه في التفاصيل.\\nاختر اليوم موقفًا واحدًا تقول فيه الحق بمحبة ولو كلفك ذلك شيئًا، واذكر شهداء كنيستك في صلاتك.\"},{\"t\":\"الذين معنا أكثر\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس عن الملائكة: هؤلاء هم الذين يرسلهم الله لمساعدة القديسين، أما الذين في الغرب فهم الذين يحاربونهم، والذين معنا هم أكثر عددًا. الشهداء ثبتوا لأنهم رأوا هذه القوة. ثق اليوم أن من معك أكثر.\",\"p\":\"يا رب، افتح عيني لأرى ملائكتك حولي. اجعلني ثابتًا مثل شهدائك لأن معي من هو أعظم. آمين.\",\"x\":\"أرى الأب إيسيذورس الأب موسى جموع الشياطين في الغرب وجموع الملائكة في الشرق وقال: هؤلاء هم الذين يرسلهم الله لمساعدة القديسين، أما الذين في الغرب فهم الذين يحاربونهم، والذين معنا أكثر عددًا. تدريب: إذا خفت اليوم فتذكر أن الذين معك أكثر.\",\"fq\":252}]},\"9-12\":{\"th\":\"الصبر في الضيق\",\"m\":[{\"t\":\"أبث لديه ضيقي\",\"ref\":\"المزمور ١٤١ (١٤٢) — النوم\",\"v\":\"بصوتي إلى الرب تضرعت. أسكب أمامه توسلي. أبث لديه ضيقي، عند فناء روحي مني وأنت علمت سبلي.\",\"r\":\"يسكب المرنم أمام الرب توسله ويبث لديه ضيقه وهو يعلم أن الله علم سبله. الصبر في الضيق يبدأ بالكلام مع الله. اكتب اليوم ما يضايقك في رسالة قصيرة إلى الله، ثم ضعها في مكان أمين.\",\"p\":\"يا رب، بصوتي إليك تضرعت. أسكب أمامك ضيقي، وأنت تعلم سبلي، فاحفظني بصبرك. آمين.\",\"x\":\"يسكب المرنم أمام الرب توسله ويبث لديه ضيقه، ويعلم أن الله علم سبله. الصبر يبدأ بالكلام مع الله. تدريب: اسكب أمام الله ضيقك الليلة بكلمات كاملة وأنت واقف.\"},{\"t\":\"الصابر إلى المنتهى\",\"ref\":\"متى ٢٤: ١٣\",\"bk\":\"متى\",\"v\":\"ولكن الذي يصبر إلى المنتهى فهذا يخلص.\",\"r\":\"«ولكن الذي يصبر إلى المنتهى فهذا يخلص». الرب لم يعدنا بطريق بلا ضيق، لكنه وعدنا بخلاص لمن يثبت. والصبر ليس سلبية، بل هو التصاقي بالرب حين يتأخر الفرج. وأنا اليوم أحتاج هذا الصبر في أمر واحد أنتظر فيه.\",\"p\":\"يا رب، امنحني نعمة الصبر حتى النهاية. لا تدعني أفتر ولا أتراجع، وقوّ إيماني حين يتأخر الجواب. آمين.\",\"x\":\"قال الرب هذا في حديثه عن علامات النهاية، حين ذكر أن المحبة ستبرد عند كثيرين. فالامتحان ليس فقط في الاضطهاد بل في فتور القلب مع الوقت. والكلمة اليونانية للصبر تحمل معنى الثبات تحت الحمل. ولذلك لا يكفي أن نبدأ بحماس، بل أن نكمل بأمانة حتى النهاية. وقد علّمنا الآباء أن الجهاد المستمر الهادئ أنفع من اندفاع قصير.\\nحدد اليوم أمرًا بدأته وتوقفت عنه، كالمطالعة أو الصلاة، وارجع إليه بخطوة صغيرة ثابتة.\"},{\"t\":\"يضبطون أنفسهم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيسوى: إن الإخوة يضبطون أنفسهم حتى الموت دون أن يتكلموا، فمجّد الله. الصبر في الضيق ضبط للنفس بلا شكوى. تحمل اليوم متاعب صغيرة دون أن تتذمر.\",\"p\":\"يا رب، أعطني قوة الاحتمال بلا تذمر. علّمني أن أضبط نفسي وأمجدك في كل ضيق. آمين.\",\"x\":\"بعد أن ضلّ مرشد الإخوة الطريق في الظلام وصمتوا جميعًا حتى الصباح قال الأب سيسوى: إن الإخوة يضبطون أنفسهم حتى الموت دون أن يتكلموا، فمجّد الله. ضبط الألسنة في الضيق فضيلة. تدريب: لا تشتكِ اليوم في موقف مزعج، وصمتك صلاة.\",\"fq\":497}]},\"9-13\":{\"th\":\"قوة الله في الضعف\",\"m\":[{\"t\":\"الآن أقوم يقول الرب\",\"ref\":\"المزمور الحادي عشر — باكر\",\"v\":\"من أجل شقاء المساكين وتنهد البائسين الآن أقوم؛ يقول الرب، أصنع الخلاص علانية.\",\"r\":\"يقول الرب إنه من أجل شقاء المساكين وتنهد البائسين الآن يقوم ويصنع الخلاص علانية. قوته تظهر حين يضعف الإنسان ولا يخفي ضعفه. اعترف اليوم بضعف تحاول إخفاءه، واطلب قوة الله فيه.\",\"p\":\"يا رب، قوتك في ضعفي تكمل. قم الآن لخلاصي، واصنع قوتك فيّ حيث أنا أضعف. آمين.\",\"x\":\"يقول الرب إنه من أجل شقاء المساكين وتنهد البائسين يقوم ويصنع الخلاص علانية. تنهدنا مسموع عنده. تدريب: تنهد اليوم أمامه، وقل: أنا مسكين وأنت المخلص.\"},{\"t\":\"أنا قوي حين أنا ضعيف\",\"ref\":\"كورنثوس الثانية ١٢: ١٠\",\"bk\":\"كورنثوس الثانية\",\"v\":\"لذلك أسر بالضعفات والشتائم والضرورات والاضطهادات والضيقات لأجل المسيح. لأني حينما أنا ضعيف فحينئذ أنا قوي.\",\"r\":\"«لأني حينما أنا ضعيف فحينئذ أنا قوي». هذه ليست عبارة متناقضة، بل سر. فحين أعترف بضعفي أفتح الباب لقوة المسيح. وكثيرًا ما أخفي ضعفي خوفًا، فأحرم نفسي من قوته. فلأقدم ضعفي له اليوم بصدق.\",\"p\":\"يا رب، أعترف لك بضعفي فاسكن فيه بقوتك. لا تدعني أتكل على ذراعي، وأعطني نعمتك التي تكفيني. آمين.\",\"x\":\"قالها بولس بعد أن طلب ثلاث مرات أن تُرفع عنه شوكة في الجسد، فأجابه الرب: «تكفيك نعمتي لأن قوتي في الضعف تكمل». فتحول الضعف من عيب إلى مكان لعمل الله. والتواضع هنا ليس إنكارًا للقدرات بل إدراكًا لمصدرها. وقد قال الآباء إن الإنسان الذي يعرف ضعفه يصلي بحرارة، والذي يظن نفسه قويًا ينام. فضعفنا يدفعنا إلى الصلاة.\\nاذكر اليوم ضعفًا واحدًا في حياتك وقدّمه لله في صلاة صادقة بدل أن تخفيه.\"},{\"t\":\"لا أملك شيئًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب سيسوى أن نصمت ونقول: لا أملك شيئًا، لا أملك شيئًا، وأينما كنا. هذه هي الغربة. من يعترف بفقره يملأه الله. كرر اليوم هذه العبارة عند أي زهو، واستعد غنى الله.\",\"p\":\"يا رب، أنا لا أملك شيئًا إلا أنت. املأ فقري بقوتك. آمين.\",\"x\":\"جوابًا لأخ سأل ما هي الغربة قال الأب سيسوى: أصمت وقل لا أملك شيئًا، لا أملك شيئًا. هذا ردّده حيثما ذهبت وأينما كنت، هذه هي الغربة. تدريب: ردد اليوم عند كل تعلق: ليس لي شيء، والكل لله.\",\"fq\":466}]},\"9-14\":{\"th\":\"الاتكال على الله\",\"m\":[{\"t\":\"طوبى لمن إله يعقوب معينه\",\"ref\":\"المزمور ١٤٥ — النوم\",\"v\":\"طوبى لمن إله يعقوب معينه. واتكاله على الرب إلهه. الذي صنع السماء والأرض والبحر وكل ما فيها. الحافظ العدل إلى الدهر، الصانع الحكم للمظلومين المعطي الطعام للجياع.\",\"r\":\"طوبى لمن إله يعقوب معينه واتكاله على الرب الذي صنع السماء والأرض وهو يعطي الطعام للجياع. الاتكال لا يلغي العمل لكنه يزيل القلق. سلّم اليوم همًّا ماليًّا أو أسريًّا لله بصلاة محددة.\",\"p\":\"يا رب، أنت معيني ومتكلي. أعطني طعام يومي، وعلّمني أن أترك همومي في يديك. آمين.\",\"x\":\"طوبى لمن إله يعقوب معينه واتكاله على الرب الصانع السماء والأرض الحافظ العدل. الاتكال لا يلغي العمل بل يريحه. تدريب: اعمل واجبك اليوم، ثم سلّم النتيجة لله.\"},{\"t\":\"توكل من كل قلبك\",\"ref\":\"الأمثال ٣: ٥\",\"bk\":\"الأمثال\",\"v\":\"توكل على الرب بكل قلبك، وعلى فهمك لا تعتمد.\",\"r\":\"«توكل على الرب بكل قلبك، وعلى فهمك لا تعتمد». أعتمد عادة على حساباتي ثم أطلب من الله أن يباركها. أما الوصية فتقلب الترتيب: أبدأ بالله ثم أستخدم عقلي في ضوء توكلي عليه. هذا هو الأمان الحقيقي.\",\"p\":\"يا رب، أتكل عليك بكل قلبي. لا تدعني أعتمد على فهمي وحده، وقوّم طرقي كلها بحكمتك. آمين.\",\"x\":\"هذه الآية من الأمثال تُقرأ مع الآية التالية: «في كل طرقك اعرفه وهو يقوّم سبلك». أي أن الاعتراف بالله في كل قرار، صغيرًا كان أو كبيرًا، يضمن الاستقامة. وهذا لا يلغي العقل، لكنه ينزع كبرياءه. فالعقل خادم جيد وسيد رديء. والكنيسة تعلّمنا ذلك في صلاة الساعات حيث نسلّم الوقت كله بيد الله، من باكر حتى النوم.\\nقبل قرارك التالي اليوم، توقف دقيقة وصلِّ: «يا رب، ماذا تريد؟»، ثم اتخذ القرار.\"},{\"t\":\"أتحزنون من أجل الخبز؟\",\"ref\":\"\",\"v\":\"\",\"r\":\"يسأل الأب أموي: أتحزنون من أجل الخبز؟ ثم يذكر أن بعضًا غادروا بيوتهم تاركين كل شيء مفتوحة الأبواب. الاتكال على الله حرية من الخوف على الحاجات. اترك اليوم قلقًا بسبب ما ينقصك.\",\"p\":\"يا رب، أنت تعولني. حرّرني من الخوف على الغد، وعلّمني ثقة الطيور والزهور. آمين.\",\"x\":\"لتلاميذه الذين حزنوا لرحيلهم قال الأب أموي: أتحزنون من أجل الخبز؟ إني رأيت البعض يغادرون بيوتهم تاركين كل شيء دون أن يغلقوا الأبواب. الاتكال قرار شجاع. تدريب: سلّم الله همّ احتياج مادي اليوم بصلاة.\",\"fq\":67}]},\"9-15\":{\"th\":\"السهر والثبات\",\"m\":[{\"t\":\"فليقم الله\",\"ref\":\"قوموا يا بني النور — نصف الليل — الخدمة الأولى\",\"v\":\"فليقم الله وليتبدد جميع أعدائه. وليهرب من قدام وجهه كل مبغضي اسمه القدوس. وأما شعبك فليكن بالبركة ألوف ألو ف وربوات ربوات، يصنعون إرادتك. يا رب افتح شفتي ولينطق فمي بتسبيحك. أمين. هلليلويا.\",\"r\":\"يصلي الليل بصلاة القيام: فليقم الله وليتبدد أعداؤه، وليكن شعبه بالبركة وهو يصنع إرادته. السهر والثبات يحتاجان انتباه القلب. خصص اليوم لحظة سهر قصيرة قبل النوم أو بعد الاستيقاظ.\",\"p\":\"يا رب، افتح شفتي ولينطق فمي بتسبيحك. علّمني السهر والثبات لأصنع إرادتك. آمين.\",\"x\":\"في صلاة القيام نقول: ليقم الله ويتبدد أعداؤه وليكن شعبه بالبركة. السهر يعني أن نقف مع الله في المعركة. تدريب: قم الليلة دقائق قليلة قبل النوم، وصلّ المزمور ٦٧ واقفًا.\"},{\"t\":\"اسهروا وتضرعوا\",\"ref\":\"لوقا ٢١: ٣٦\",\"bk\":\"لوقا\",\"v\":\"اسهروا إذا وتضرعوا في كل حين، لكي تحسبوا أهلا للنجاة من جميع هذا المزمع أن يكون، وتقفوا قدام ابن الإنسان».\",\"r\":\"«اسهروا إذًا وتضرعوا في كل حين». السهر هنا ليس أرقًا بل يقظة قلب. والتضرع ليس طلبات فقط بل دوام ارتباط بالله. وأنا أحتاج أن أجعل لروحي لحظات يقظة وسط انشغالات يومي.\",\"p\":\"يا رب، أيقظ قلبي وأبعد عنه ثقل الهموم. علمني أن أسهر وأصلي في كل حين لأقف أمامك بثقة. آمين.\",\"x\":\"جاءت هذه الوصية في ختام حديث الرب عن المجيء الثاني، بعد تحذير من ثقل القلب بالخمر والسكر وهموم الحياة. فالعدو هنا ليس خارجيًا فقط بل ثقل داخلي. والنجاة تأتي بالسهر مع الصلاة معًا. وفي تقليد الكنيسة تأتي صلاة نصف الليل والتسبحة لتدريب أولادها على السهر. ويوضح الآباء أن السهر الحقيقي هو انتباه الذهن إلى الله لا مجرد البقاء مستيقظًا.\\nخصص اليوم خمس دقائق في هدوء بلا هاتف لتصلي صلاة يسوع ببطء.\"},{\"t\":\"كله عين\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيساريوس: ينبغي أن يكون الراهب كالشاروبيم والسارافيم، كلّه عين. السهر الحقيقي انتباه كامل للروح. راقب اليوم عينيك وأذنيك، وانتبه لما تدخله إلى قلبك.\",\"p\":\"يا رب، اجعل كياني كله يقظًا لك. احرس عيني وأذني، وثبّتني في سهرك. آمين.\",\"x\":\"قال الأب بيساريوس وهو على فراش الموت: ينبغي أن يكون الراهب كالشاروبيم والسارافيم كلّه عين. السهر انتباه كامل. تدريب: انتبه اليوم لثلاث مرات تفقد فيها حضورك بين الناس، وعد إلى الحضور.\",\"fq\":83}]},\"9-16\":{\"th\":\"قلب واحد ونفس واحدة\",\"m\":[{\"t\":\"لولا أن الرب كان معنا\",\"ref\":\"المزمور ١٢٣ (١٢٤) — الغروب\",\"v\":\"لولا أن الرب كان معنا ليقل إسرائيل - لولا أن الرب كان معنا عندما قام الناس علينا، لابتلعونا ونحن أحياء، عند سخط غضبهم علينا. إذا لغرقنا في الماء وعبرت نفوسنا السيل؛ بل جازت نفوسنا الماء الذي لا نهاية له. مبارك الرب الذي لم يسلمنا فريسة لأسنانهم.\",\"r\":\"لولا أن الرب كان معنا لابتلعونا أحياء، فمبارك الرب الذي لم يسلمنا فريسة. الوحدة بين المؤمنين عطية من الله الذي يحفظنا معًا. اشكره اليوم على من جمعك بهم، وصلِّ لهم بالاسم.\",\"p\":\"يا رب، مبارك أنت لأنك معنا. اجعلنا قلبًا واحدًا ونفسًا واحدة في محبتك. آمين.\",\"x\":\"لولا أن الرب كان معنا لابتلعونا أحياء، فمبارك الرب الذي لم يسلمنا فريسة. الوحدة عطية الله الذي يحفظ شعبه. تدريب: اشكر الله على من يحفظ وحدتك في أسرتك أو كنيستك، واكتب اسمه.\"},{\"t\":\"قلب واحد\",\"ref\":\"أعمال الرسل ٤: ٣٢\",\"bk\":\"أعمال الرسل\",\"v\":\"وكان لجمهور الذين آمنوا قلب واحد ونفس واحدة، ولم يكن أحد يقول إن شيئا من أمواله له، بل كان عندهم كل شيء مشتركا.\",\"r\":\"«كان لجمهور الذين آمنوا قلب واحد ونفس واحدة». الوحدة هنا ثمرة الروح لا اتفاق آراء. وهي تظهر في عطاء مشترك لا يقول أحد فيه «هذا لي». وأنا أحتاج أن أفحص أين أتمسك بما لي وأنسى أنني جزء من جسد.\",\"p\":\"يا رب، اجعلنا قلبًا واحدًا ونفسًا واحدة. انزع الأنانية من بيننا، واملأنا بروحك لنشارك بفرح. آمين.\",\"x\":\"يأتي هذا الوصف بعد حلول الروح القدس وصلاة الكنيسة التي زلزلت المكان. فالشركة هي نتيجة امتلاء الروح. والمشاركة لم تكن إجبارية، لكنها تعبير عن محبة. وقد تأثر آباء الرهبنة بهذا الوصف في تأسيس الشركة الرهبانية عند الأنبا باخوميوس. ونحن في الكنيسة نعيش جزءًا منه في صلاة واحدة وتناول واحد ومحبة تتجاوز الفروق.\\nاعمل اليوم عملًا مشتركًا: شارك أحدًا في طعام أو وقت أو مال، دون أن ينتظر ردًا.\"},{\"t\":\"ألا يكون في قلب أحد عليّ شيء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إسحق كاهن القلالي: لم أدخل إلى قلايتي فكرًا ضد أخ أزعجني، وكان همي ألا أترك أحدًا وفي قلبه عليّ شيء. الوحدة تحتاج مصالحة. صالح اليوم أحدًا في قلبه عليك شيء.\",\"p\":\"يا رب، لا تدع في قلب أحد عليّ شيئًا. أعطني أن أبادر بالسلام والمصالحة. آمين.\",\"x\":\"يقول الأب إسحق كاهن القلالي: لم أدخل إلى قلايتي فكرًا ضد أخ أزعجني، وكان همي ألا أترك أحدًا وفي قلبه عليّ شيء. تدريب: صالح اليوم شخصًا بينك وبينه شيء قبل غروب الشمس.\",\"fq\":179}]},\"9-17\":{\"th\":\"غلبة المسيح\",\"m\":[{\"t\":\"يملك الرب إلى الدهر\",\"ref\":\"المزمور ١٤٥ — النوم\",\"v\":\"يملك الرب إلى الدهر، وإلهك يا صهيون من جيل إلى جيل هلليلويا.\",\"r\":\"يملك الرب إلى الدهر، وهو إله صهيون من جيل إلى جيل. الغلبة هبة المسيح لا إنجاز بشري. اذكر اليوم عدوًا داخليًّا تتعب منه، وقل: الغلبة للمسيح.\",\"p\":\"يا رب، أنت الملك إلى الدهر. ارحمني وأعطني غلبتك على ضعفي. آمين.\",\"x\":\"يملك الرب إلى الدهر ومن جيل إلى جيل، فالغلبة ملكه هو. ما نعجز عنه يملك عليه المسيح. تدريب: سلّم المسيح عدوًا داخليًا بالاسم، وقل: املك أنت عليه.\"},{\"t\":\"من يغلب\",\"ref\":\"رؤيا يوحنا ٣: ٢١\",\"bk\":\"رؤيا يوحنا\",\"v\":\"من يغلب فسأعطيه أن يجلس معي في عرشي، كما غلبت أنا أيضا وجلست مع أبي في عرشه.\",\"r\":\"«من يغلب فسأعطيه أن يجلس معي في عرشي، كما غلبت أنا أيضًا». أنا لا أغلب بمفردي بل بغلبة المسيح الذي سبقني. والمكافأة ليست جائزة صغيرة بل شركة في مجده. وهذا يعطيني دافعًا للثبات في الصراع.\",\"p\":\"يا رب، أنت غلبت العالم فأعطني أن أغلب فيك. أخرجني من الفتور، وأدخلني إلى شركة مجدك. آمين.\",\"x\":\"هذا آخر وعد من الرسائل السبع، موجه إلى كنيسة لاودكية الفاترة. وهو دعوة للقيام من الفتور بوعد عظيم. والرب يقول «كما غلبت أنا»، أي أنه عاش الصراع مثلنا وانتصر. وفي تجسده ذاق التجربة وغلب. ولذلك نغلب فيه لا بذواتنا. وهذا الوعد يعلن أن الغلبة ليست حكرًا على الشهداء، بل لكل من يثبت في التوبة.\\nحدد اليوم نقطة فتور واحدة في حياتك الروحية وابدأ بخطوة صغيرة لعلاجها.\"},{\"t\":\"سحقت الأسد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يفسر الأب بيمن قول داود: سحقت الأسد وخنقت الدب، أي استأصلت الغضب وضيقت على الزنى بالأتعاب. المسيح يعطينا قوة نسحق بها أسودنا الداخلية. اجعل اليوم هدفًا: ألا تغضب.\",\"p\":\"يا رب، اسحق في داخلي الغضب. أعطني غلبتك على كل عادة تقيدني. آمين.\",\"x\":\"لأخ يحارب بالزنى والغضب فسّر الأب بيمن قول داود «سحقت الأسد وخنقت الدب» أي استأصلت الغضب وضيّقت على الزنى بالأتعاب. الجهاد يضيّق على الشهوة. تدريب: ضيّق اليوم على شهوة واحدة بتعب جسدي صغير أو صوم عن شيء مباح.\",\"fq\":393}]},\"9-18\":{\"th\":\"الوداعة\",\"m\":[{\"t\":\"الرب يرفع الودعاء\",\"ref\":\"المزمور ١٤٦ — النوم\",\"v\":\"الرب يرفع الودعاء ويذل الخطاة إلى الأرض.\",\"r\":\"الرب يرفع الودعاء ويذل الخطاة إلى الأرض. الوداعة قوة هادئة تحمل ثقل الآخرين دون كلام. تصرف اليوم بلطف مع أول شخص يضايقك، ولاحظ كيف تنزع الوداعة الحدة.\",\"p\":\"يا رب، ارفع الودعاء وعلّمني وداعتك. اجعل قلبي لطيفًا في ردود فعلي. آمين.\",\"x\":\"يرفع الرب الودعاء ويذل الخطاة إلى الأرض. الوداعة لا تعني ضعفًا بل ثقة في أن الله يرفع. تدريب: تحمّل اليوم كلمة قاسية بوداعة وانتظر الرب.\"},{\"t\":\"البسوا الوداعة\",\"ref\":\"كولوسي ٣: ١٢\",\"bk\":\"كولوسي\",\"v\":\"فالبسوا كمختاري الله القديسين المحبوبين أحشاء رأفات، ولطفا، وتواضعا، ووداعة، وطول أناة،\",\"r\":\"«فالبسوا كمختاري الله أحشاء رأفات، ولطفًا، وتواضعًا، ووداعة، وطول أناة». التعبير «البسوا» يعني أن الوداعة اختيار أرتديه كل صباح. وكما أختار ثيابي أختار طبعي اليوم. فلأضع في قلبي طول الأناة عندما أتعامل مع من يزعجني.\",\"p\":\"يا رب، البسني رأفة ولطفًا ووداعة. علمني أن أطيل أناتي مع الجميع، وحوّل غضبي إلى هدوء. آمين.\",\"x\":\"هذا المقطع يأتي بعد دعوة إلى خلع الإنسان العتيق: الغضب والسخط والخبث. فالحياة الجديدة تُلبس كالثياب الجديدة. والصفات الخمس المذكورة هي ثمار المسيح فينا، وكلها تظهر في العلاقات اليومية. والوداعة ليست ضعفًا بل قوة مضبوطة، كما كان موسى أحلم من جميع الناس. وهي قاعدة في الحياة الرهبانية وفي كل خدمة. وتنتهي الآية بطول الأناة، وهي أصعب الفضائل وأحوجها.\\nاليوم عند أول انفعال، تنفس وقل لنفسك: «ألبس الوداعة»، ثم أجب بهدوء.\"},{\"t\":\"انظر إلى تعبي وتواضعي\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب موسى الحبشي إن الصلاة بقوله: «انظر إلى تعبي وتواضعي وامح كل سيئاتي» تجعل النفس وديعة متواضعة. الوداعة ثمرة الوعي بالتعب والضعف. كرر هذه الآية اليوم.\",\"p\":\"يا رب، انظر إلى تعبي وتواضعي وامح كل سيئاتي. اجعل نفسي وديعة متواضعة. آمين.\",\"x\":\"لأخ سأل عن نفع الأصوام والأسهار قال الأب موسى الحبشي إنها تجعل النفس وديعة متواضعة، لأنه مكتوب «انظر إلى تعبي وتواضعي وامح كل سيئاتي». التعب سبيل التواضع. تدريب: قل هذه الآية في نهاية يومك.\",\"fq\":265}]},\"9-19\":{\"th\":\"التأني والانتظار\",\"m\":[{\"t\":\"فلينتظر إسرائيل الرب\",\"ref\":\"المزمور ١٢٩ (١٣٠) — النوم\",\"v\":\"من محرس الصبح فلينتظر إسرائيل الرب. لأن الرحمة من عند الرب. عظيم هو خلاصه وهو يفتدي إسرائيل من كل آثامه هلليلويا.\",\"r\":\"من محرس الصبح فلينتظر إسرائيل الرب، فالرحمة من عنده وخلاصه عظيم. التأني ثقة بتوقيت الله لا بتوقيتنا. اترك اليوم أمرًا تنتظره دون أن تضغط على الأحداث.\",\"p\":\"يا رب، أنتظرك فالرحمة من عندك. علّمني التأني، وافتد نفسي من كل إثم. آمين.\",\"x\":\"من محرس الصبح فلينتظر إسرائيل الرب، فالرحمة من عنده والخلاص عظيم. الانتظار موقف ثقة. تدريب: اترك اليوم أمرًا متأخرًا في يد الله ولا تلحّ على حله بنفسك.\"},{\"t\":\"فتأنوا\",\"ref\":\"يعقوب ٥: ٨\",\"bk\":\"يعقوب\",\"v\":\"فتأنوا أنتم وثبتوا قلوبكم، لأن مجيء الرب قد اقترب.\",\"r\":\"«فتأنوا أنتم وثبتوا قلوبكم، لأن مجيء الرب قد اقترب». التأني ليس خمولًا بل ثبات. والرجاء في مجيء الرب يعطيني سببًا للصبر. وكثير من اضطرابي يأتي من استعجالي، فلأتعلم أن أنتظر الرب بقلب ثابت.\",\"p\":\"يا رب، ثبّت قلبي وعلمني التأني. اجعلني أنتظر مجيئك بفرح، ولا تدعني أستعجل ما لم تأذن به. آمين.\",\"x\":\"قبلها يضرب يعقوب مثال الفلاح الذي ينتظر الثمر الثمين ويتأنى عليه حتى ينال المطر المبكر والمتأخر. فالتأني جزء من طبيعة الحياة الروحية. وعبارة «ثبتوا قلوبكم» تدعو إلى تقوية الداخل لا انتظار ظروف أفضل. والكنيسة تعلمنا الانتظار في الأصوام وأسابيع الاستعداد، فنتشوق للعيد بتهيؤ. وهكذا نتدرب على انتظار المجيء الثاني.\\nاليوم، اختر أمرًا تنتظره ولا تستعجله، وقل: «أنتظرك يا رب بقلب ثابت».\"},{\"t\":\"الراحة قبل أوانها\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ثيوذورس: كثيرون قد اختاروا الراحة هذه الأيام قبل أن يعطيهم إياها الله. التأني أن ننتظر راحة الله لا أن نصنعها بأيدينا. اصبر اليوم على التعب دون أن تهرب إلى ما يريحك سريعًا.\",\"p\":\"يا رب، علّمني أن أنتظر راحتك. لا تدعني أستعجل ما ليس بعد من عندك. آمين.\",\"x\":\"يقول الأب ثيوذورس الفرمي: كثيرون قد اختاروا الراحة هذه الأيام قبل أن يعطيهم إياها الله. التأني أن ننتظر راحة الله. تدريب: لا تتعجل راحة اليوم، واقبل التعب في وقته.\",\"fq\":138}]},\"9-20\":{\"th\":\"ثمر الروح والمحبة\",\"m\":[{\"t\":\"جعل تخومك في سلام\",\"ref\":\"المزمور ١٤٧ — النوم\",\"v\":\"لأنه قد قوى مغاليق أبوابك وبارك بنيك فيك. الذي جعل تخومك في سلام: ويملأك من شحم الحنطة.\",\"r\":\"يبارك الرب بنيه ويجعل تخومهم في سلام ويملأهم من شحم الحنطة. ثمر الروح محبة وفرح وسلام، وأول علاماته أنه يجمع ولا يفرق. اجمع اليوم بين شخصين متخاصمين بكلمة طيبة أو صلاة.\",\"p\":\"يا رب، اجعل تخومي في سلام. أثمر في حياتي ثمر روحك: المحبة والسلام والوداعة. آمين.\",\"x\":\"يبارك الرب بنيه ويجعل تخومهم في سلام. السلام ثمر روح يجمع ولا يفرق. تدريب: اصنع سلامًا اليوم في حدود بيتك بكلمة لطيفة.\"},{\"t\":\"ضد هذه ليس ناموس\",\"ref\":\"غلاطية ٥: ٢٣\",\"bk\":\"غلاطية\",\"v\":\"وداعة تعفف. ضد أمثال هذه ليس ناموس.\",\"r\":\"«وداعة تعفف. ضد أمثال هذه ليس ناموس». الثمر لا يحتاج إلى أمر خارجي لأنه ينمو من الداخل. وإن عشت في الروح فسأفعل الصواب بدافع الحب لا بدافع الخوف. وهذا هو الفرق بين الواجب والحياة.\",\"p\":\"يا رب، أثمر فيّ ثمر روحك. امنحني وداعة وتعففًا، وعلمني أن أعيش بالمحبة لا بالخوف. آمين.\",\"x\":\"قائمة ثمر الروح في غلاطية ٥ تبدأ بالمحبة والفرح والسلام وتنتهي بالتعفف، أي ضبط النفس. وكلمة «ثمر» مفرد، تدل على وحدة الثمار كلها في الروح. وهي على النقيض من أعمال الجسد الظاهرة. والكنيسة تدعونا لنكون كالشجرة المغروسة عند مجاري المياه. ولا يمكن إنتاج الثمر بمجهود شخصي فقط، بل بالبقاء في الكرمة. فالصلاة والأسرار هي الوسائل لنموه.\\nتأمل اليوم في ثمرة واحدة تحتاج إلى نمو، واطلبها من الروح القدس في صلاة بسيطة.\"},{\"t\":\"إيماءة تؤذي\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أشعيا: عندما يريد الإنسان أن يقابل الشر بالشر يستطيع بإيماءة فقط أن يؤذي ضمير قريبه. ثمر الروح يحفظ حتى إشاراتنا. راقب اليوم نظراتك وحركاتك مع الآخرين.\",\"p\":\"يا رب، قدّس حتى إشاراتي. اجعل ثمر الروح ظاهرًا في لغة جسدي وكلامي. آمين.\",\"x\":\"يقول الأب أشعيا: عندما يريد الإنسان أن يقابل الشر بالشر يستطيع بإيماءة فقط أن يؤذي ضمير قريبه. الأذى قد يكون بنظرة. تدريب: راقب اليوم نظراتك وإيماءاتك واجعلها لطيفة.\",\"fq\":123}]},\"9-21\":{\"th\":\"محبة المصلوب\",\"m\":[{\"t\":\"سررت أن تصعد على الصليب\",\"ref\":\"قطعة السادسة (٥)\",\"v\":\"نسجد لشخصك غير الفاسد أيها الصالح، طالبين مغفرة خطايانا أيها المسيح إلهنا. لأن بمشيئتك سررت أن تصعد على الصليب لتنجي الذين خلقتهم من عبودية العدو. نصرخ إليك ونشكرك لأنك ملأت الكل فرحًا، أيها المخلص لما أتيت لتعين العالم، يا رب المجد لك.\",\"r\":\"صعد المسيح على الصليب بمشيئته ليحررنا من عبودية العدو، وهذه هي محبته للمصلوب. الصليب ليس حدثًا عابرًا بل إعلان حب. قف اليوم أمام الصليب دقيقة صمت وقل: أنت فعلت هذا لأجلي.\",\"p\":\"يا رب، لك المجد على صليبك. نسجد لك شاكرين على محبتك التي صعدت بها لأجلنا. آمين.\",\"x\":\"نسجد لشخصك غير الفاسد طالبين مغفرة خطايانا، لأنه سُرّ أن يصعد على الصليب لينجي الذين خلقهم. تدريب: قف أمام صليب وقل: أحببتني حتى الصليب، فبماذا أجيبك اليوم؟\"},{\"t\":\"أرسل ابنه الوحيد\",\"ref\":\"يوحنا الأولى ٤: ٩\",\"bk\":\"يوحنا الأولى\",\"v\":\"بهذا أظهرت محبة الله فينا: أن الله قد أرسل ابنه الوحيد إلى العالم لكي نحيا به.\",\"r\":\"«بهذا أظهرت محبة الله فينا: أن الله قد أرسل ابنه الوحيد إلى العالم لكي نحيا به». محبة الله ليست كلامًا بل عمل تجسد وبذل. وأنا أحيا اليوم لأنه أرسل ابنه. فهل أعيش هذه الحياة بشكر أم بعادة؟\",\"p\":\"يا أبانا السماوي، أشكرك لأنك أرسلت ابنك الوحيد لنحيا به. اجعل حياتي شكرًا دائمًا لمحبتك، وقوّني لأحب كما أحببتني. آمين.\",\"x\":\"يكتب يوحنا هذه الرسالة ليؤكد أن المحبة الحقيقية تظهر في الفعل. وكلمة «الوحيد» تذكّر بالتضحية العظمى: الآب أرسل ما هو أغلى عنده. وغاية الإرسال «لكي نحيا به»، فالحياة الأبدية مبدؤها المسيح. ونحن نستعد هذه الأيام لعيد الصليب، ونتأمل في أن الصليب هو أعلى إعلان للمحبة. وقد قال الآباء إن الله لم يكتف بأن يعلن حبه بالكلام بل دخل التاريخ بالجسد.\\nاليوم، قل «شكرًا يا أبي لأنك أرسلت ابنك» أمام صورة الصليب وانظر إليه دقيقة صامتة.\"},{\"t\":\"واقفة عند الصليب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: كان فكري عند مريم والدة الإله التي كانت واقفة عند الصليب تبكي، وكم أردت لو أبكي مثلها باستمرار. الحب يتأمل الصليب ويبكي. اقرأ اليوم مشهد الصلب بتمهل.\",\"p\":\"يا رب، أعطني أن أتأمل صليبك مع أمك. اجعل دموعي دموع محبة لا حزن بلا رجاء. آمين.\",\"x\":\"يقول الأب بيمن: كان فكري عند مريم والدة الإله التي كانت واقفة عند الصليب تبكي، وكم أردت لو أبكي مثلها باستمرار. الدموع هنا ثمرة نظر إلى المصلوب. تدريب: تأمل دقيقتين في وقفة العذراء عند الصليب.\",\"fq\":420}]},\"9-22\":{\"th\":\"الذبيحة والقربان\",\"m\":[{\"t\":\"ذبيحة التهليل\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"طفت وذبحت في مظلته ذبيحة التهليل، أسبح وأرتل للرب.\",\"r\":\"يطوف المرنم ويذبح في مظلة الرب ذبيحة التهليل. الذبيحة الحقيقية قلب يفرح بتقديم ذاته. لا تنتظر ظرفًا استثنائيًّا. قدّم اليوم عملًا يكلفك راحتك وأنت تسبح.\",\"p\":\"يا رب، أقدم لك ذبيحة التهليل. اقبل من يدي ما أستطيع، ودع محبتك تكمل ما ينقصني. آمين.\",\"x\":\"يطوف المرنم ويذبح في مظلة الرب ذبيحة التهليل، فالذبيحة هي الفرح بتقديم الذات. تدريب: قدّم اليوم عملًا صغيرًا لله بفرح، ولا تذكر الثمن.\"},{\"t\":\"وضع نفسه لأجلنا\",\"ref\":\"يوحنا الأولى ٣: ١٦\",\"bk\":\"يوحنا الأولى\",\"v\":\"بهذا قد عرفنا المحبة: أن ذاك وضع نفسه لأجلنا، فنحن ينبغي لنا أن نضع نفوسنا لأجل الإخوة.\",\"r\":\"«بهذا قد عرفنا المحبة: أن ذاك وضع نفسه لأجلنا، فنحن ينبغي لنا أن نضع نفوسنا لأجل الإخوة». كلمة «ينبغي» تعني أنها ليست خيارًا إضافيًا. فالمحبة التي لا تبذل لا تشبه محبة المسيح. وأنا أسأل نفسي: ما الذي أبذله اليوم؟\",\"p\":\"يا رب، علمني المحبة بالعمل والحق. افتح عيني على احتياج إخوتي، وأعطني قلبًا سخيًا يتبع بذلك مثالك على الصليب. آمين.\",\"x\":\"والآية التالية تعطي مثالًا عمليًا: من كان له معيشة العالم ورأى أخاه محتاجًا وأغلق أحشاءه عنه، فكيف تثبت محبة الله فيه؟ فالبذل يبدأ بالمال والوقت قبل الدم. وتعلمنا الكنيسة هذا في الصدقة والافتقاد. والصليب هو النموذج الأعلى لكل بذل. افتقد اليوم شخصًا محتاجًا بمكالمة أو بعطاء بسيط، ولا تنتظر شكرًا. \\n\"},{\"t\":\"غيرة تفوق الناس\",\"ref\":\"\",\"v\":\"\",\"r\":\"تأثر الأب بمفو لأمرين: ضياع امرأة، وأنه لا يملك الحماس والغيرة الكافية لإرضاء الله كما ترضي هذه المرأة الناس. الذبيحة غيرة من أجل الله. اسأل نفسك اليوم: ما الذي أبذله لأجل الناس، ولا أبذله لأجل الله؟\",\"p\":\"يا رب، أشعل فيّ غيرة تفوق غيرتي على إرضاء الناس. علّمني أن أقدم ذاتي ذبيحة حية. آمين.\",\"x\":\"بكى الأب بمفو لما رأى في الإسكندرية ممثلة، وقال إنه تأثر لأمرين: ضياع هذه المرأة، وأنه لا يملك الحماس والغيرة لإرضاء الله كما ترضي هي الناس. الغيرة تُحاسب نفسها قبل غيرها. تدريب: اسأل: هل أبذل لله مثلما أبذل للناس؟\",\"fq\":457}]},\"9-23\":{\"th\":\"حمل الله\",\"m\":[{\"t\":\"الحمل والراعي\",\"ref\":\"قطعة التاسعة (٦)\",\"v\":\"عندما نظرت الوالدة الحمل والراعي مخلص العالم على الصليب معلقا قالت وهي باكية: أما العالم فيفرح لقبوله الخلاص، وأما أحشائي فتلتهب عند نظري إلى صلبوتك الذي أنت صابر عليه من أجل الكل يا ابني والهي.\",\"r\":\"تنظر الوالدة الحمل والراعي معلقًا على الصليب، فتلتهب أحشاؤها بينما يفرح العالم بالخلاص. حمل الله يرفع خطية العالم بألم الذين يحبونه. تأمل اليوم في الثمن الذي دفعه المسيح لأجلك.\",\"p\":\"أيها الحمل الذي ذُبح لأجلنا، ارحمنا. أشكرك على صليبك وخلاصك. آمين.\",\"x\":\"نظرت الوالدة الحمل والراعي معلقًا على الصليب فقالت إن العالم يفرح بالخلاص وأحشاءها تلتهب. هنا يظهر ثمن الخلاص. تدريب: تأمل أن الحمل حمل خطيتك أنت، واشكره.\"},{\"t\":\"هوذا حمل الله\",\"ref\":\"يوحنا ١: ٢٩\",\"bk\":\"يوحنا\",\"v\":\"وفي الغد نظر يوحنا يسوع مقبلا إليه، فقال: «هوذا حمل الله الذي يرفع خطية العالم!\",\"r\":\"«هوذا حمل الله الذي يرفع خطية العالم». شهادة يوحنا تلخص رسالة المسيح. وهو لا يرفع خطاياي بالإهمال بل بحمل ثقلها. وعندما أنظر إليه أرى الحل لخطيتي. فلأنظر إليه اليوم أكثر مما أنظر إلى سقطاتي.\",\"p\":\"يا حمل الله الذي يرفع خطية العالم، ارحمني. احمل عني خطيتي، وطهّر قلبي بدمك، وأعطني أن أنظر إليك دائمًا. آمين.\",\"x\":\"قال يوحنا هذا حين رأى يسوع مقبلًا إليه. وكان اليهود يقدمون الحمل في الفصح تذكارًا للخروج. فأعلن يوحنا أن المسيح هو الفصح الحقيقي. وكلمة «يرفع» تحمل معنيين: يحمل ويرفع بعيدًا. أي أنه يتحمل الخطية ويزيلها. وفي القداس يُقال قبل التناول: «القدسات للقديسين»، ونتناول الحمل المذبوح الذي صار حيًا. ويعلمنا الآباء أن النظر إلى الحمل يشفي كما كانت النظرة إلى الحية النحاسية.\\nقبل صلاتك اليوم، قل ببطء: «يا حمل الله الذي يرفع خطية العالم ارحمني».\"},{\"t\":\"بلا عيب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن الأبرار دُعوا بلا عيب لأنهم هجروا الخطيئة فصاروا أبرارًا. حمل الله بلا عيب يدعونا إلى الابتعاد عن الخطيئة. اختر اليوم خطية تكرارية، وصمم على ألا تعود إليها.\",\"p\":\"يا رب، اجعلني بلا عيب بنعمتك. علّمني أن أهجر الخطيئة محبة فيك. آمين.\",\"x\":\"سُئل الأب بيمن ما التوبة عن الخطيئة فقال: أن لا نرتكبها فيما بعد، ولذلك دُعي الأبرار بلا عيب لأنهم هجروا الخطيئة. التوبة هجر لا اعتذار فقط. تدريب: اترك اليوم خطية واحدة تتكرر.\",\"fq\":398}]},\"9-24\":{\"th\":\"بجراحه شفينا\",\"m\":[{\"t\":\"صرخت إليك فشفيتني\",\"ref\":\"المزمور ٢٩ (٣٠) — الثالثة\",\"v\":\"أيها الرب إلهي، صرخت إليك فشفيتني. يا رب أصعدت من الجحيم نفسي. وخلصتني من الهابطين في الجب.\",\"r\":\"صرخ المرنم إلى الرب فشفاه وأصعد من الجحيم نفسه. جراح المسيح هي مصدر شفاء جراحنا. قدّم اليوم له جرحًا قديمًا لا يزال يؤلمك، واطلب شفاءه.\",\"p\":\"يا رب، بجراحك شفيتنا. صرخت إليك فاشف انكسار قلبي واجبر كسري بمحبتك. آمين.\",\"x\":\"صرخ المرنم فشفاه الرب وأصعد من الجحيم نفسه. جراح المسيح تشفي جراحنا. تدريب: قدّم لله جرحًا قديمًا وقل: اشفني بجراحك.\"},{\"t\":\"مجروح لأجل معاصينا\",\"ref\":\"إشعياء ٥٣: ٥\",\"bk\":\"إشعياء\",\"v\":\"وهو مجروح لأجل معاصينا، مسحوق لأجل آثامنا. تأديب سلامنا عليه، وبحبره شفينا.\",\"r\":\"«وهو مجروح لأجل معاصينا، مسحوق لأجل آثامنا. تأديب سلامنا عليه، وبحبره شفينا». كل جرح في المسيح يقابل جرحًا فيّ. وسلامي الحقيقي نتيجة ألمه. فلا أنسى أن راحتي اليوم ثمنها ألم لا أراه.\",\"p\":\"يا رب، بجراحك شفيتني. أشكرك على ألمك لأجلي، واشفِ جراحات نفسي، وامنحني سلامك الذي اشتريته بحبرك. آمين.\",\"x\":\"تتكرر في الآية كلمة «لأجل»، فالألم كان بديلًا. و«تأديب سلامنا عليه» يعني أن العقوبة التي كانت لنا وقعت عليه. و«بحبره شفينا» تشير إلى الشفاء الروحي والجسدي معًا. وقد رأى الآباء في جراحات المسيح مصدر الحياة، فمن جنبه خرج دم وماء. وتصلي الكنيسة في الجمعة العظيمة بخشوع عند هذه النبوات. وتدعونا إلى أن نقترب من الجراح بإيمان لا بفضول.\\nاقرأ اليوم إشعياء ٥٣ كله ببطء، وتوقف عند كلمة تلمس قلبك.\"},{\"t\":\"الناس مرضى\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أنطونيوس إن الله لا يترك الحروب تعمل في هذا الجيل كما كانت في الأجيال السالفة، لأنه يعرف أن الناس الآن مرضى ولا يحتملون. الله يرحم ضعفنا ويشفي. اشكره اليوم على أنه لا يحمّلك فوق طاقتك.\",\"p\":\"يا رب، أشكرك لأنك تعرف ضعفي. لا تحمّلني ما لا أطيق، واشفني برحمتك. آمين.\",\"x\":\"يقول القديس أنطونيوس إن الله لا يترك الحروب تعمل في هذا الجيل كما كانت في الأجيال السالفة لأنه يعرف أن الناس الآن مرضى ولا يحتملون. الله يراعي ضعفنا. تدريب: اشكره على حروب لم يسمح بها لأنك لا تحتملها.\",\"fq\":12}]},\"9-25\":{\"th\":\"النبوات عن الصليب\",\"m\":[{\"t\":\"بطل الموت\",\"ref\":\"قطعة السادسة (٦)\",\"v\":\"أنت هي الممتلئة نعمة يا والدة الإله العذراء. نعظمك لأن من قبل صليب ابنك انهبط الجحيم وبطل الموت. أمواتا كنا فنهضنا، واستحققنا الحياة الأبدية، ونلنا نعيم الفردوس الأول. من أجل هذا نمجد بشكر غير المائت المسيح إلهنا.\",\"r\":\"تعظم الكنيسة العذراء لأن من قبل صليب ابنها انهبط الجحيم وبطل الموت، وقد كنا أمواتًا فنهضنا. نبوات العهد القديم عن الصليب تحققت كلها. اقرأ اليوم نبوة عن الآلام وتأمل كيف أكملها المسيح.\",\"p\":\"يا رب، لك المجد لأنك أكملت النبوات بصليبك. أمواتًا كنا فنهضنا، فاجعلنا نحيا لك. آمين.\",\"x\":\"تعظم الكنيسة العذراء لأن من قبل صليب ابنها انهبط الجحيم وبطل الموت، وكنا أمواتًا فنهضنا. الصليب في النبوات كان يُنتظر. تدريب: اقرأ مزمور ٢١ وتأمل كيف سبق وصوّر الصليب.\"},{\"t\":\"ثقبوا يدي ورجلي\",\"ref\":\"المزامير ٢٢: ١٦\",\"bk\":\"المزامير\",\"v\":\"لأنه قد أحاطت بي كلاب. جماعة من الأشرار اكتنفتني. ثقبوا يدي ورجلي.\",\"r\":\"«ثقبوا يدي ورجلي». كتب داود هذه الكلمات قبل اختراع الصلب بقرون. والكنيسة ترى فيها صوت المسيح على الصليب. وهذا يؤكد لي أن الكتاب موحى به، وأن الله يعرف التاريخ من أوله إلى آخره.\",\"p\":\"يا رب، أشكرك لأن كلمتك صادقة ومتممة. علمني أن أقرأ المزامير بقلب مصلي، وأن أرى فيها صوتك وألمك لأجلي. آمين.\",\"x\":\"المزمور ٢٢ يبدأ بكلمات الرب على الصليب: «إلهي إلهي لماذا تركتني»، وينتهي بنصرة وتسبيح. وفي وصفه يذكر اقتسام الثياب والاكتناف بالأشرار والعطش. وكلها تحققت عند الصلب. والآباء يستعملون هذا المزمور لإثبات إلهام الكتاب وصدق المسيح. ونحن نقرأه في صلاة الساعة السادسة والتاسعة يوم الجمعة العظيمة. ويعلمنا أن كل ألم يتحول إلى مجد في النهاية.\\nاقرأ المزمور ٢٢ اليوم، وانتبه كيف ينتقل من الصراخ إلى التسبيح، وصلِّ بذلك الانتقال.\"},{\"t\":\"ليتم قول المسيح\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب موسى: إن لي سنين طوالًا وأنا أنتظر هذا اليوم لكي يتم قول المسيح: «من أخذ بالسيف بالسيف يؤخذ». من ينتظر تحقق كلام الله يقبل حتى مصيره. ثق اليوم أن كلام الله يتم.\",\"p\":\"يا رب، ثبّتني على كلمتك وإن تأخرت. أعطني أن أراها تتم في وقتها. آمين.\",\"x\":\"قال الأب موسى للإخوة لما أنذرهم بقدوم البربر: لي سنين طوالًا أنتظر هذا اليوم لكي يتم قول المسيح «من أخذ بالسيف بالسيف يؤخذ». من أعد نفسه للموت لا يهاب. تدريب: أعد نفسك اليوم لأي شيء يأتي بتسليم هادئ.\",\"fq\":258}]},\"9-26\":{\"th\":\"الحية النحاسية\",\"m\":[{\"t\":\"داسهم بقوة صليبه\",\"ref\":\"تحليل التاسعة\",\"v\":\"اللهم أبطل عنا كل قوة المعاند وجميع جنوده الرديئة، كما داسهم ابنك الوحيد بقوة صليبه المحيي. واقبلنا إليك يا سيدي يسوع المسيح كما قبلت اللص اليمين وأنت معلق على عود الصليب.\",\"r\":\"كما رفع موسى الحية النحاسية في البرية فنظر إليها الملدوغون وحيوا، ارتفع المسيح على الصليب. النظر إلى المصلوب شفاء. انظر اليوم إلى الصليب حين تقاومك الأفكار الشريرة، وقل: يا رب أقبلني كما قبلت اللص.\",\"p\":\"يا رب، أبطل قوة المعاند بصليبك المحيي. اقبلني كما قبلت اللص اليمين. آمين.\",\"x\":\"نطلب أن يبطل الله قوة المعاند كما داسه الابن بصليبه المحيي. كما نظر الملدوغون إلى الحية النحاسية فحيوا، ننظر إلى المصلوب. تدريب: عند أي لدغة فكر اليوم انظر بقلبك إلى الصليب.\"},{\"t\":\"نظر إلى حية النحاس يحيا\",\"ref\":\"العدد ٢١: ٩\",\"bk\":\"العدد\",\"v\":\"فصنع موسى حية من نحاس ووضعها على الراية، فكان متى لدغت حية إنسانا ونظر إلى حية النحاس يحيا.\",\"r\":\"«فكان متى لدغت حية إنسانًا ونظر إلى حية النحاس يحيا». النظر هو الشرط، والإيمان هو الباب. لم يطلب الله من الملدوغ عملًا بل نظرة. فالخلاص هبة تُقبل بالنظر إلى المرفوع.\",\"p\":\"يا رب، لدغتني الخطية فانظر إلي وأنا أنظر إليك مرفوعًا. اشفني بصليبك وأحيني بنظرة الإيمان. آمين.\",\"x\":\"حدثت هذه القصة في برية سيناء حين تذمر الشعب فأرسل الرب الحيات المحرقة. وبعد توبتهم أمر الله موسى بصنع الحية النحاسية. وقد فسر الرب يسوع هذا لنيقوديموس: «كما رفع موسى الحية في البرية هكذا ينبغي أن يرفع ابن الإنسان». فالحية النحاسية رمز بلا سم للصليب، والنظر رمز للإيمان. ويرى الآباء أن المسيح أخذ شبه الجسد دون خطية ليشفي لدغة الحية القديمة.\\nاليوم، عندما تلسعك فكرة خاطئة أو شهوة، انظر فورًا إلى الصليب بصلاة قصيرة.\"},{\"t\":\"مقيَّد لا ميت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إبراهيم: لم تقتله فالهوى ما زال حيًّا فيك، إنما قد قُيّد، فالأهواء ما تزال حية إلا أنها لُجمت عند القديسين. الصليب يقيد الهوى لا يلغي الجهاد. ابقَ يقظًا اليوم أمام هوى معروف.\",\"p\":\"يا رب، قيّد أهوائي بصليبك. علّمني الانتباه الدائم، ولا تدعني أنام على نصر قديم. آمين.\",\"x\":\"لشيخ قال إنه قتل الزنى وحب الفضة والمجد الفارغ قال الأب إبراهيم: لم تقتله، فالهوى ما زال حيًّا فيك، إنما قد قُيّد. الأهواء لُجمت عند القديسين لا ماتت. تدريب: لا تأمن نفسك اليوم ولا تعرّضها لما يوقظ هواك.\",\"fq\":71}]},\"9-27\":{\"th\":\"عيد الصليب\",\"m\":[{\"t\":\"مزق صك خطايانا\",\"ref\":\"قطعة السادسة (١)\",\"v\":\"يا من في اليوم السادس وفي الساعة السادسة سمرت على الصليب من أجل الخطية التي تجرأ عليها أبونا آدم في الفردوس، مزق صك خطايانا أيها المسيح إلهنا وخلصنا.\",\"r\":\"في عيد الصليب نذكر الصليب الذي مزق صك خطايانا ورفع الدين الذي علينا. نفتخر به لا بأنفسنا. ارسم علامة الصليب اليوم بانتباه كامل، وقلها بصلاة: أنا مصلوب مع المسيح.\",\"p\":\"يا رب، لك المجد يا من سمرت على الصليب لأجلي. مزق صك خطاياي وخلصني. آمين.\",\"x\":\"في عيد الصليب نحتفل بما مزّق صك خطايانا ورفع الدين. نفتخر به لا بأنفسنا. تدريب: ارسم علامة الصليب اليوم بانتباه ثلاث مرات.\"},{\"t\":\"مع المسيح صلبت\",\"ref\":\"غلاطية ٢: ٢٠\",\"bk\":\"غلاطية\",\"v\":\"مع المسيح صلبت، فأحيا لا أنا، بل المسيح يحيا في. فما أحياه الآن في الجسد، فإنما أحياه في الإيمان، إيمان ابن الله، الذي أحبني وأسلم نفسه لأجلي.\",\"r\":\"«مع المسيح صلبت، فأحيا لا أنا بل المسيح يحيا فيّ». في عيد الصليب أسأل: من يعيش حياتي؟ إن كانت الأنا هي التي تقود، فالصليب لم يعمل فيّ بعد. والمسيح يريد أن يحيا فيّ بمحبته وطاعته.\",\"p\":\"يا رب، في عيد صليبك أسلمك حياتي كلها. أمت أنانيتي وعش أنت فيّ، وأعطني أن أحيا بإيمان ابن الله الذي أحبني. آمين.\",\"x\":\"في ١٧ توت تحتفل الكنيسة بظهور الصليب المقدس. وقد قال بولس هذه الآية لأن الصليب لم يكن عنده حدثًا تاريخيًا فقط بل خبرة شخصية. «الذي أحبني وأسلم نفسه لأجلي»: لاحظ كلمة «أجلي». فالمحبة شخصية. والصليب يعني موت الأنا وحياة المسيح فيّ. وهذه هي حياة التلمذة. ويحتفل المؤمنون بالعيد بقداس وتمجيد، ويرفعون الصليب في موكب.\\nاليوم ارسم إشارة الصليب بتأمل، وقل: «أنا صلبت معك يا رب، فعش أنت فيّ».\"},{\"t\":\"ثلاثة أيام في القبر\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب موسى: إذا لم يضع الإنسان نفسه عقليًّا في القبر ثلاثة أيام لا يمكنه أن يبلغ إلى قامة هذا الكلام. من يشارك المسيح في صليبه يتعلم أن يموت عن ذاته. تذكر اليوم أنك مدفون مع المسيح بالمعمودية.\",\"p\":\"يا رب، أمتني عن ذاتي معك. علّمني حياة القيامة بعد موت الأنا. آمين.\",\"x\":\"لأخ سأل كيف يميت الإنسان نفسه عن قريبه قال الأب موسى: إذا لم يضع الإنسان نفسه عقليًّا في القبر ثلاثة أيام لا يمكنه أن يبلغ قامة هذا الكلام. الصليب يعلم الموت عن الأنا. تدريب: لا تدافع عن نفسك في موقف اليوم.\",\"fq\":259}]},\"9-28\":{\"th\":\"موت الإنسان العتيق\",\"m\":[{\"t\":\"قتلت الخطية بالخشبة\",\"ref\":\"قطعة السادسة (٢)\",\"v\":\"يا يسوع المسيح إلهنا الذي سمرت على الصليب في الساعة السادسة، وقتلت الخطية بالخشبة، وأحييت الميت بموتك. اقتل أوجاعنا بآلامك الشافية المحيية.\",\"r\":\"المسيح قتل الخطية بالخشبة وأحيا الميت بموته، وهذا هو أساس موت إنساننا العتيق. التحرر من العتيق ليس بقوتنا بل بآلامه. اطلب اليوم من المسيح أن يقتل فيك عادة قديمة.\",\"p\":\"يا رب، اقتل أوجاعي بآلامك الشافية. أمِت إنساني العتيق وأحيِ فيّ إنسانًا جديدًا. آمين.\",\"x\":\"قتل المسيح الخطية بالخشبة وأحيا الميت بموته، وهذا أساس موت إنساننا العتيق. تدريب: اختر عادة عتيقة وقل: مت مع المسيح عليها اليوم.\"},{\"t\":\"محا الصك الذي علينا\",\"ref\":\"كولوسي ٢: ١٤\",\"bk\":\"كولوسي\",\"v\":\"إذ محا الصك الذي علينا في الفرائض، الذي كان ضدا لنا، وقد رفعه من الوسط مسمرا إياه بالصليب،\",\"r\":\"«إذ محا الصك الذي علينا، وقد رفعه من الوسط مسمرًا إياه بالصليب». ديوني ممحوة بدم المسيح. والعدو يحاول أن يذكرني بصك قديم لكنه لم يعد له مفعول. أمام الاتهام أقول: ديني سدد على الصليب.\",\"p\":\"يا رب، محوت صك خطاياي بصليبك. أشكرك على النصر، ولا تدع العدو يتهمني، بل ثبتني في غفرانك. آمين.\",\"x\":\"الصك هنا وثيقة دين مكتوبة، كانت تسمر أحيانًا على باب الدائن. فصور بولس أن الله أخذ وثيقة اتهامنا وسمرها على صليب المسيح. وبعدها تأتي صورة النصر: جرد الرياسات والسلاطين وأشهرهم جهارًا ظافرًا بهم. أي أن الصليب هو موكب نصر. وتذكر الكنيسة ذلك في ألحان عيد الصليب. فالمسيح غلب الشيطان بالتواضع والبذل.\\nاكتب اليوم على ورقة خطية ندمت عنها واعترفت، ثم اكتب فوقها «مغفورة» وصلِّ شاكرًا.\"},{\"t\":\"الحقل والديدان\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن من يسلك مع إنسان بهوى من أهواء الإنسان القديم ويتمسك به يشبه صاحب حقل تلتهمه الديدان والحشرات. الهوى القديم يفسد الثمر. اقتلع اليوم هوى يلتهم علاقة أو عملًا.\",\"p\":\"يا رب، حرّر علاقاتي من أهوائي القديمة. اقتلع الديدان من حقل قلبي. آمين.\",\"x\":\"يقول الأب بيمن إن من يعاشر إنسانًا ويسلك نحوه بهوى من أهواء الإنسان القديم ويتمسك به يشبه صاحب حقل تلتهمه الديدان والحشرات. الهوى يأكل الحقل. تدريب: افحص علاقة تحمل هوى وصحّحها.\",\"fq\":445}]},\"9-29\":{\"th\":\"الحياة للذي مات لأجلنا\",\"m\":[{\"t\":\"اذكرنا يا رب\",\"ref\":\"قطعة التاسعة (٥)\",\"v\":\"يا من قبل إليه اعتراف اللص على الصليب، اقبلنا إليك أيها الصالح، نحن المستوجبين حكم الموت من أجل خطايانا. نقر بخطايانا معه معترفين بألوهيتك، ونصرخ معه جميعًا: اذكرنا يا رب متى جئت في ملكوتك.\",\"r\":\"اللص المصلوب عاش لحظة واحدة للحياة الجديدة، فقبله المسيح، وهكذا نحيا لمن مات لأجلنا. الحياة التي أُعطيناها ليست لنا. اطلب اليوم كلمة تقولها بصدق: اذكرني يا رب.\",\"p\":\"يا رب، تذكّرني حين تجيء في ملكوتك. اقبل اعترافي واجعلني أحيا لك الذي مات لأجلي. آمين.\",\"x\":\"اعترف اللص على الصليب فقبله المسيح، فنحيا نحن لمن مات لأجلنا. تدريب: قل بإخلاص اليوم: اذكرني يا رب، واعترف بخطيتك الواضحة.\"},{\"t\":\"لا لأنفسهم\",\"ref\":\"كورنثوس الثانية ٥: ١٥\",\"bk\":\"كورنثوس الثانية\",\"v\":\"وهو مات لأجل الجميع كي يعيش الأحياء فيما بعد لا لأنفسهم، بل للذي مات لأجلهم وقام.\",\"r\":\"«كي يعيش الأحياء فيما بعد لا لأنفسهم، بل للذي مات لأجلهم وقام». غاية الفداء أن أنتقل من الحياة لنفسي إلى الحياة له. وهذا يجعل لحياتي معنى. فلا أسأل «ماذا أريد؟» فقط، بل «ماذا يريد الذي مات لأجلي؟».\",\"p\":\"يا رب، مت لأجلي فاجعلني أحيا لك. خذ وقتي ومواهبي وقراراتي، واجعل محبتك تحصرني فأخدمك بفرح. آمين.\",\"x\":\"في هذه الآيات يشرح بولس سبب غيرته: «محبة المسيح تحصرنا». أي تضغط علينا وتدفعنا. فالمحبة قوة تحرك وليست شعورًا فقط. والحياة له تعني قراراتنا وأوقاتنا ومواهبنا. وتشرح الكنيسة هذا في طقس الرهبنة والخدمة. لكن كل مؤمن مدعو إلى هذه الحياة، في العمل والبيت والخدمة. فنحن في هذا العالم سفراء لا مقيمين.\\nاسأل نفسك اليوم: ما الذي أفعله هذا الأسبوع حقًا للمسيح؟ وحدد عملًا يعبر عن ذلك.\"},{\"t\":\"مات عن العالم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب كسيانوس: لقد مت عن العالم قبله، فالميت لا يرث الحي. من مات عن العالم لا يحكمه العالم. اترك اليوم مجالًا واحدًا لا تدافع فيه عن حقك.\",\"p\":\"يا رب، أمتني عن العالم وأحيني لك. حرّرني من شهوة الدفاع عن نفسي. آمين.\",\"x\":\"لأنسبائه الذين دعوه ليرث أباه قال راهب في كهف عند الأب كسيانوس: لقد مت عن العالم قبله، فالميت لا يرث الحي. من مات عن العالم لا يطمع. تدريب: تخلَّ اليوم عن مطمع صغير.\",\"fq\":216}]},\"9-30\":{\"th\":\"دم يسوع والكهنوت\",\"m\":[{\"t\":\"هيكلك كالسماء\",\"ref\":\"قطعة مشتركة — نصف الليل — الخدمة الثانية\",\"v\":\"إذا ما وقفنا في هيكلك المقدس نحسب كالقيام في السماء. يا والدة الإله. أنت هي باب السماء، افتحي لنا باب الرحمة.\",\"r\":\"إذا وقفنا في هيكل الله حسبنا كالقيام في السماء. هناك الدم الذي نتقدس به، والكهنوت الذي يقدمه. اذكر اليوم اسم كاهنك وصلِّ لأجله وتأمل في سر الدم المقدس.\",\"p\":\"يا رب، أشكرك على هيكلك وكهنوتك ودمك. افتح لنا باب الرحمة، وقدّس خدامك. آمين.\",\"x\":\"إذا وقفنا في هيكل الله حسبنا كالقيام في السماء، وهناك دم المسيح والكهنوت. تدريب: صلِّ اليوم لكاهن اعترافك باسمه.\"},{\"t\":\"ثقة بالدخول إلى الأقداس\",\"ref\":\"العبرانيين ١٠: ١٩\",\"bk\":\"العبرانيين\",\"v\":\"فإذ لنا أيها الإخوة ثقة بالدخول إلى «الأقداس» بدم يسوع،\",\"r\":\"«فإذ لنا أيها الإخوة ثقة بالدخول إلى الأقداس بدم يسوع». الستار انشق وصار لي وصول إلى الله. وأنا لا أقترب بسبب استحقاقي بل بدم المسيح. وهذا يعطيني جرأة الصلاة دون خوف أو تردد.\",\"p\":\"يا رب، فتحت لي بدمك باب الأقداس. أقترب إليك بثقة، فاقبلني وطهرني وأعطني حضورك. آمين. وثبتني في قربك كل أيام حياتي.\",\"x\":\"كان الدخول إلى قدس الأقداس مرة في السنة لكبير الكهنة فقط. أما الآن فالطريق مفتوح لكل مؤمن. ويصف الكاتب هذا الطريق بأنه «كرسه لنا حديثًا حيًّا» عبر الحجاب أي جسده. وتعبر الكنيسة عن ذلك في القداس عندما يُفتح الهيكل وتُرفع الصلوات. ثم يدعونا إلى الاقتراب بقلب صادق وإيمان كامل. فالثقة هنا ثقة في عمل المسيح لا في أنفسنا.\\nاقترب إلى الله اليوم في صلاة مفتوحة قصيرة، وتكلم معه كابن مع أب.\"},{\"t\":\"من إنسان إلى ملاك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس عن زخريا الصبي إنه لما تقدم الأحد الماضي لتناول الجسد والدم الطاهرين كان إنسانًا، أما الآن فقد أضحى ملاكًا. التناول يغير حياتنا. تقدم للتناول باستعداد أو صلِّ صلاة استعداد.\",\"p\":\"يا رب، حوّلني بجسدك ودمك. اجعلني كل يوم أقرب إلى حياة الملائكة. آمين.\",\"x\":\"يقول الأب إيسيذورس عن زخريا الصبي: لما تقدم الأحد الماضي لتناول الجسد والدم الطاهرين كان إنسانًا، أما الآن فقد أضحى ملاكًا. التناول يغيّر. تدريب: اشتق للتناول وتأمل ما يفعله فيك.\",\"fq\":221}]},\"10-1\":{\"th\":\"الكنيسة جسد المسيح\",\"m\":[{\"t\":\"الله في وسطها فلن تتزعزع\",\"ref\":\"المزمور ٤٥ (٤٦) — الثالثة\",\"v\":\"مجارى الأنهار تفرح مدينة الله. لقد قدس العلي مسكنه. والله في وسطها فلن تتزعزع.\",\"r\":\"مدينة الله تفرح بمجاري الأنهار لأن العلي قدس مسكنه وهو في وسطها. الكنيسة جسد المسيح، والله في وسط الجسد لا يتزعزع. اذكر اليوم ثلاثة أعضاء من كنيستك، وصلِّ لكل منهم بالاسم.\",\"p\":\"يا رب، أنت في وسط كنيستك فلا تتزعزع. اجعلني عضوًا حيًّا في جسدك، يفرح بالشركة معك ومع إخوته. آمين.\",\"x\":\"مجاري الأنهار تفرح مدينة الله، والله في وسطها فلن تتزعزع. الكنيسة جسد المسيح، فحضوره في وسطها أمان لكل عضو. تدريب: اشكر الله اليوم على كنيستك، وصلِّ لأحد أعضائها بالاسم.\"},{\"t\":\"رأس فوق كل شيء للكنيسة\",\"ref\":\"أفسس ١: ٢٢\",\"bk\":\"أفسس\",\"v\":\"وأخضع كل شيء تحت قدميه، وإياه جعل رأسا فوق كل شيء للكنيسة،\",\"r\":\"«وإياه جعل رأسًا فوق كل شيء للكنيسة التي هي جسده». المسيح ليس بعيدًا عن الكنيسة بل هو رأسها. وأنا عضو في هذا الجسد. فلا أخاف على الكنيسة لأن رأسها حي، ولا أتعالى فيها لأن الرأس غيري.\",\"p\":\"يا رب، أنت رأس الكنيسة وحياتها. احفظ جسدك من الانقسام، واجعلني عضوًا حيًا نافعًا ومطيعًا لرأسه. آمين.\",\"x\":\"بعد أن يذكر بولس قيامة المسيح وجلوسه عن يمين الآب، يعلن أنه رأس للكنيسة. والرأس هو مصدر الحياة والتدبير. أما الجسد فهو العضو المطيع المتحد. وعبارة «ملء الذي يملأ الكل» تعني أن الكنيسة هي مكان حضور المسيح في العالم. ولذلك نرى الكنيسة في تقليدنا ليست مبنى بل جماعة المؤمنين الحية. ومن هنا أهمية ارتباط كل عضو بالجسد في الصلاة والأسرار.\\nاليوم، صلِّ لأجل الكنيسة كلها: بطريركها وأساقفتها وكهنتها وشعبها، وسمِّ كنيستك بالاسم.\"},{\"t\":\"كسلوك الجميع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب موتيوس: حيث تقيم ليكن سلوكك كسلوك الجميع، فالتواضع أن تكون مساويًا للأتقياء الذين تثق بهم. العضو في الجسد لا يتميز بغرابة بل بأمانة. اخدم اليوم في مكانك بروح الجماعة دون أن تبحث عن الظهور.\",\"p\":\"يا رب، علّمني أن أكون جزءًا من الجسد لا فوقه. وأعطني تواضعًا يحب المساواة مع إخوتي. آمين.\",\"x\":\"يقول الأب موتيوس: حيث تقيم ليكن سلوكك كسلوك الجميع، ومهما يفعل الأتقياء الذين تثق بهم افعله أنت أيضًا فترتاح، لأن التواضع أن تكون مساويًا لهم. العضو الحي يتناغم مع الجسد. تدريب: اتبع اليوم ترتيب الجماعة بلا استثناء لنفسك.\",\"fq\":281}]},\"10-2\":{\"th\":\"أعضاء بعضنا لبعض\",\"m\":[{\"t\":\"أدخل بيتك\",\"ref\":\"المزمور الخامس — باكر\",\"v\":\"أما أنا فبكثرة رحمتك أدخل بيتك. وأسجد قدام هيكل قدسك بمخافتك. اهدني يا رب ببرك.\",\"r\":\"يدخل المرنم بيت الله بكثرة الرحمة لا باستحقاقه، ويسجد بمخافته ويطلب الهداية ببر الله. نحن أعضاء بعضنا لبعض نحتاج هذا التواضع معًا. قبل أن تدخل الكنيسة أو الاجتماع اليوم، اطلب غفران الله ومحبة إخوتك.\",\"p\":\"يا رب، بكثرة رحمتك أدخل بيتك وأسجد أمام قدسك. اهدني ببرك واجعلني عضوًا نافعًا لإخوتي. آمين.\",\"x\":\"يدخل المرنم بيت الله بكثرة رحمته لا باستحقاقه، ويطلب الهداية ببره. نحن أعضاء بعضنا لبعض نحتاج رحمة وهداية معًا. تدريب: اطلب الهداية اليوم لقرار يخص أسرتك أو كنيستك.\"},{\"t\":\"إن تألم عضو\",\"ref\":\"كورنثوس الأولى ١٢: ٢٦\",\"bk\":\"كورنثوس الأولى\",\"v\":\"فإن كان عضو واحد يتألم، فجميع الأعضاء تتألم معه. وإن كان عضو واحد يكرم، فجميع الأعضاء تفرح معه.\",\"r\":\"«إن كان عضو واحد يتألم فجميع الأعضاء تتألم معه، وإن كان عضو واحد يكرم فجميع الأعضاء تفرح معه». هل أشارك الكنيسة في ألمها وفرحها؟ كثيرًا ما أتألم لنفسي وأفرح بنفسي، أما الجسد فيعلمني مشاركة الآخر.\",\"p\":\"يا رب، علمني أن أبكي مع الباكين وأفرح مع الفرحين. انزع الحسد من قلبي، واجعلني أشعر بإخوتي كما بجسدي. آمين.\",\"x\":\"في أصحاح ١٢ من كورنثوس الأولى يتناول بولس الانقسامات في الكنيسة. فيشبه الكنيسة بجسد: لا تقدر العين أن تقول لليد لا حاجة لي بك. والأعضاء الأضعف ضرورية. والغاية ألا يكون انشقاق في الجسد. ومن هنا تأتي قيمة الصلاة من أجل المتألمين والفرح مع المكرَّمين. فالحسد ينافي الجسد الواحد. وأعمال الرحمة في الكنيسة، كالافتقاد، تعبّر عن هذا الأصل.\\nاليوم، افرح من قلبك لنجاح أحد، أو شاركه ألمه بالاتصال أو الصلاة.\"},{\"t\":\"الفضيلة مع الناس أولًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب لوكيوس لمن أراد أن يهرب من الناس: إذا لم تحقق الفضيلة مع الناس أولًا، لا تستطيع بمفردك وأنت في البرية أن تحققها. نحن أعضاء بعضنا لبعض، ونتدرب على المحبة بينهم. اختر اليوم موقفًا مع شخص تتعب منه، وتدرّب فيه على الصبر.\",\"p\":\"يا رب، علّمني الفضيلة بين الناس. اجعلني أحتمل أعضاء جسدك كما احتملتني أنت. آمين.\",\"x\":\"لمن أراد أن يهرب من الناس قال الأب لوكيوس: إذا لم تحقق الفضيلة مع الناس أولًا لا تستطيع بمفردك وأنت في البرية أن تحققها. الفضيلة تُمتحن بين الناس. تدريب: مارس اليوم فضيلة في موقف مع من تضايقك.\",\"fq\":232}]},\"10-3\":{\"th\":\"بيت الله\",\"m\":[{\"t\":\"لبيتك ينبغي التقديس\",\"ref\":\"المزمور ٩٢ (٩٣) — السادسة\",\"v\":\"شهاداته صادقة جدا، لبيتك ينبغي التقديس يا رب طول الأيام.\",\"r\":\"شهادات الرب صادقة جدًا، ولبيته ينبغي التقديس طول الأيام. الكنيسة بيت الله، ونحن أيضًا هيكل لله. اسكت اليوم دقيقة عند دخولك أي مكان صلاة، وتذكر أن قلبك أيضًا بيته.\",\"p\":\"يا رب، لبيتك ينبغي التقديس. قدّس كنيستك وقدّس قلبي ليكون بيتًا لك. آمين.\",\"x\":\"شهادات الرب صادقة وللبيت التقديس طول الأيام، والتقديس لا يقتصر على ساعة الصلاة. تدريب: خصص اليوم خمس دقائق صمت قبل الدخول في أي عمل.\"},{\"t\":\"أهل بيت الله\",\"ref\":\"أفسس ٢: ١٩\",\"bk\":\"أفسس\",\"v\":\"فلستم إذا بعد غرباء ونزلا، بل رعية مع القديسين وأهل بيت الله،\",\"r\":\"«فلستم إذًا بعد غرباء ونزلاء، بل رعية مع القديسين وأهل بيت الله». كنيستي ليست مكانًا أزوره بل بيتي. فيها أنتمي وأنال المحبة. ولي مكان على مائدة العائلة الكبيرة. وهذا يمنحني إحساسًا بالأمان.\",\"p\":\"يا رب، أشكرك لأنك جعلتني من أهل بيتك. افتح قلبي للغرباء، وأعطني أن أستقبل كل أحد بمحبة العائلة. آمين.\",\"x\":\"كان الأمم قبل المسيح غرباء عن رعوية إسرائيل وعهود الموعد. أما الآن فقد صار لهم حق المواطنة والبنوّة. وعبارة «أهل بيت الله» تعني أعضاء الأسرة. ومن هنا نفهم أن الكنيسة ليست مؤسسة بل عائلة. وفي القداس نصلي معًا «أبانا الذي في السماوات». وتدعونا هذه الحقيقة أن نستقبل الغرباء الجدد في كنيستنا بترحيب العائلة.\\nإن رأيت اليوم وجهًا جديدًا أو مترددًا في الكنيسة، رحب به وعرّفه على بقية الأسرة.\"},{\"t\":\"صُن نفسك في القلاية وخارجها\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب بيمن أخًا: صُن نفسك في القلاية وخارجها. القداسة لا تنحصر في موضع الصلاة، بل تحملها معك. اجعل اليوم تصرفك خارج الكنيسة مطابقًا لما تقوله داخلها.\",\"p\":\"يا رب، احفظني في بيتك وخارجه. اجعل حياتي كلها قدسًا لك. آمين.\",\"x\":\"لأخ قال إن خروجه من القلاية يشغله بما عند غيره، أجابه الأب بيمن: صُن نفسك في القلاية وخارجها. القداسة تُحمل. تدريب: كن في الشارع اليوم كما أنت في الصلاة.\",\"fq\":414}]},\"10-4\":{\"th\":\"شعب الله والرعاية\",\"m\":[{\"t\":\"ادخلوا أبوابه بالاعتراف\",\"ref\":\"المزمور ٩٩ (١٠٠) — التاسعة\",\"v\":\"ادخلوا أبوابه بالاعتراف، ودياره بالتسابيح.\",\"r\":\"يدعونا المرنم أن ندخل أبواب الرب بالاعتراف وديارَه بالتسابيح. شعب الله له رعاة يسهرون على نفوسه، ونحن غنم رعيته. صلِّ اليوم لأجل راعيك وأطع نصيحة رعايته بفرح.\",\"p\":\"يا رب، نحن شعبك وغنم رعيتك. احفظ رعاتنا وعلّمنا أن ندخل أبوابك بالاعتراف والتسبيح. آمين.\",\"x\":\"ندخل أبوابه بالاعتراف وديارَه بالتسابيح، ونحن غنم يرعاها الراعي بالرعاة. تدريب: اشكر اليوم راعي كنيستك وصلِّ لأجله.\"},{\"t\":\"جنس مختار وكهنوت ملوكي\",\"ref\":\"بطرس الأولى ٢: ٩\",\"bk\":\"بطرس الأولى\",\"v\":\"وأما أنتم فجنس مختار، وكهنوت ملوكي، أمة مقدسة، شعب اقتناء، لكي تخبروا بفضائل الذي دعاكم من الظلمة إلى نوره العجيب.\",\"r\":\"«أنتم جنس مختار وكهنوت ملوكي وأمة مقدسة وشعب اقتناء». هذه هويتي في المسيح. ومن عرف هويته لا يعيش بحسب نظرة الناس. والغاية: «لكي تخبروا بفضائل الذي دعاكم». دعوتي أن أحكي عن الله بحياتي.\",\"p\":\"يا رب، دعوتني من الظلمة إلى نورك. أعطني أن أحيا كشعب مقتنى لك، وأخبر بفضائلك بحياتي وكلامي. آمين.\",\"x\":\"كان هذا الكلام يقال لإسرائيل في العهد القديم، وبطرس يطبقه على الكنيسة. فالكنيسة هي إسرائيل الجديد. ومعنى «اقتناء» أننا ملك له خاص. و«كهنوت ملوكي» يشير إلى قرب كل مؤمن من الله بالمسيح. وفي الكنيسة القبطية نؤمن بالكهنوت الخدمي الذي للأساقفة والكهنة، لكن كل مؤمن أيضًا يقدم ذبائح روحية. والرسالة هي إعلان فضائل الله بالسيرة والكلمة.\\nاليوم، قل لشخص واحد كلمة بسيطة عن عمل الله معك، فهذا إخبار بفضائله.\"},{\"t\":\"الدجاجة والبيضة\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سينكليتيكي لمن يعيش في شركة ألا يغير مكانه، فكما تهمل الدجاجة البيضة إن غادرتها، هكذا يفتر الإنسان وتنطفئ جذوة الإيمان فيه إن تنقل. ثبات الراعي والرعية في موضعها بركة. التزم اليوم بثبات في مكان خدمتك.\",\"p\":\"يا رب، ثبّتني في موضعي ورعايتي. لا تدع جذوة الإيمان تنطفئ بتنقلي وتقلبي. آمين.\",\"x\":\"تقول الأم سينكليتيكي لمن يعيش في شركة ألا يغير مكانه فيتأذى، فكما تهمل الدجاجة البيضة إن غادرتها هكذا يفتر الراهب أو العذراء إذا تنقل من موضع إلى آخر. الثبات يحفظ الحرارة. تدريب: ثبّت نفسك اليوم في مكان خدمتك ولا تتذمر.\",\"fq\":535}]},\"10-5\":{\"th\":\"الاجتماع وقطيع واحد\",\"m\":[{\"t\":\"رتلوا للرب\",\"ref\":\"المزمور ٩٧ (٩٨) — التاسعة\",\"v\":\"هللوا للرب يا كل الأرض، سبحوا وهللوا ورتلوا. رتلوا للرب بالقيثارة، بالقيثارة وصوت المزمار.\",\"r\":\"يدعو المرنم كل الأرض أن تهلل وتسبح وترتل للرب بالقيثارة. الاجتماع ليس واجبًا بل فرح قطيع واحد حول راعٍ واحد. اجعل اليوم موعدك للكنيسة ثابتًا، وإن تعذر فصلِّ مع أحد من أهلك.\",\"p\":\"يا رب، اجعلنا قطيعًا واحدًا بتسبيح واحد. هلل أمامك مع كل من يحبك. آمين.\",\"x\":\"يدعو المرنم كل الأرض أن تهلل وترتل للرب. الاجتماع تسبحة قطيع واحد حول راعٍ واحد. تدريب: انضم اليوم لجماعة صلاة ولو بدقائق.\"},{\"t\":\"غير تاركين اجتماعنا\",\"ref\":\"العبرانيين ١٠: ٢٥\",\"bk\":\"العبرانيين\",\"v\":\"غير تاركين اجتماعنا كما لقوم عادة، بل واعظين بعضنا بعضا، وبالأكثر على قدر ما ترون اليوم يقرب،\",\"r\":\"«غير تاركين اجتماعنا كما لقوم عادة». ترك الاجتماع يبدأ بتأجيل بسيط ثم يصير عادة. والمؤمن وحده معرض للفتور. أما في الجماعة فنتشجع معًا. فلأواظب على القداس والاجتماعات ولو كنت متعبًا.\",\"p\":\"يا رب، ثبتني في اجتماعات كنيستك. لا تدعني أترك الشركة تهاونًا، وأعطني رغبة في بيتك وفرحًا بإخوتي. آمين.\",\"x\":\"في هذا الأصحاح يدعو الكاتب إلى التقدم بقلب صادق وإيمان كامل، وإلى التمسك بإقرار الرجاء، ثم ملاحظة بعضنا بعضًا للمحبة والأعمال الحسنة. فالاجتماع ليس واجبًا شكليًا بل وسيلة نمو وتشجيع. وكلمة «واعظين» أي مشجعين. وقد عاشت كنيستنا في أوقات اضطهاد وسرية لكنها لم تترك اجتماعها. ولهذا حفظ الشعب القبطي إيمانه. والقداس الأسبوعي هو غذاء الأسبوع.\\nاليوم، خطط لحضور قداس هذا الأسبوع، وادع معك أحدًا لم يحضر منذ مدة.\"},{\"t\":\"الطاعة قبل النسك\",\"ref\":\"\",\"v\":\"\",\"r\":\"تقول الأم سينكليتيكي: عندما نكون في دير ذي حياة مشتركة يجب أن نؤثر الطاعة على النسك، لأن النسك قد يعلّم التشامخ أما الطاعة فتعلّم التواضع. الاجتماع يحتاج طاعة تحفظ الوحدة. أطع اليوم قرار الجماعة في أمر لا يحتمل مخالفة.\",\"p\":\"يا رب، علّمني الطاعة التي تحفظ وحدة قطيعك. احفظني من كبرياء النسك. آمين.\",\"x\":\"تقول الأم سينكليتيكي: في دير ذي حياة مشتركة يجب أن نؤثر الطاعة على النسك، لأن النسك قد يعلّم التشامخ أما الطاعة فتعلّم التواضع. الاجتماع مدرسة طاعة. تدريب: أطع اليوم توجيهًا لا يعجبك بفرح.\",\"fq\":542}]},\"10-6\":{\"th\":\"وحدة الروح\",\"m\":[{\"t\":\"لتعترف لك الشعوب\",\"ref\":\"المزمور السادس والستون — باكر\",\"v\":\"فلتعترف لك الشعوب يا الله فلتعترف لك الشعوب كلها. لتفرح الأمم وتبتهج، لأنك تحكم في الشعوب بالاستقامة، وتهدى الأمم في الأرض. فلتعترف لك الشعوب يا الله فلتعترف لك الشعوب جميعا.\",\"r\":\"يطلب المرنم أن تعترف الشعوب لله وتفرح الأمم، لأنه يحكم بالاستقامة ويهدي الأرض. وحدة الروح هي أن نعترف معًا بالرب الواحد. صلِّ اليوم من أجل وحدة الكنيسة في العالم.\",\"p\":\"يا رب، لتعترف لك الشعوب كلها. ثبّت وحدة الروح فيما بيننا برباط السلام. آمين.\",\"x\":\"يطلب المرنم أن تعترف الشعوب كلها لله وتفرح الأمم. وحدة الروح هي أن نعترف معًا بالرب. تدريب: صلِّ اليوم من أجل وحدة الكنيسة في العالم.\"},{\"t\":\"المجد الذي يوحّدنا\",\"ref\":\"يوحنا ١٧: ٢٢\",\"bk\":\"يوحنا\",\"v\":\"وأنا قد أعطيتهم المجد الذي أعطيتني، ليكونوا واحدا كما أننا نحن واحد.\",\"r\":\"«وأنا قد أعطيتهم المجد الذي أعطيتني، ليكونوا واحدًا كما أننا نحن واحد». وحدتنا ليست تفاهمًا بشريًا بل مشاركة في حياة الثالوث. وأنا أحتاج أن أطلب هذه الوحدة بالصلاة، لا بالتفاوض فقط.\",\"p\":\"يا رب، أعطنا المجد الذي أعطيتنا لنكون واحدًا. انزع الانقسام من كنيستك، وقرّبنا بعضنا إلى بعض بروحك. آمين.\",\"x\":\"المجد الذي يتحدث عنه المسيح ليس مجدًا مظهريًا بل حضور الله فينا. والغاية: أن يؤمن العالم أن الآب أرسله. أي أن وحدة الكنيسة شهادة للعالم. وحين تنقسم الكنيسة تضعف الشهادة. ولذلك تحرص الكنيسة على أن يتم القداس بروح واحدة. والاعتراف بالإيمان الواحد في قانون الإيمان كل أحد دليل على هذا. وكل خلاف صغير يمكن أن يعطل الشهادة.\\nاليوم أنهِ خلافًا صغيرًا بكلمة اعتذار أو تنازل، لأجل وحدة الجسد.\"},{\"t\":\"عديم الهم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن لمن أراد دير شركة: إن لم تكن عديم الهم في كل لقاء وفي كل شيء يستحيل عليك أن تعمل فيه، لأنه ليس لك سلطان على دورق الماء. وحدة الروح تحتاج أن نترك التمسك بالحقوق. تنازل اليوم عن حق صغير بفرح.\",\"p\":\"يا رب، خلّصني من التمسك بما هو لي. علّمني أن أعيش في الجماعة بلا همّ لنفسي. آمين.\",\"x\":\"لمن أراد دخول دير شركة قال الأب بيمن: إن لم تكن عديم الهم في كل لقاء وفي كل شيء يستحيل عليك أن تعمل فيه، لأنه ليس لك سلطان على دورق الماء. الشركة تطلب التخلي عن الحقوق الصغيرة. تدريب: تنازل اليوم عن حق صغير.\",\"fq\":426}]},\"10-7\":{\"th\":\"قول واحد وخبز واحد\",\"m\":[{\"t\":\"قدام كل شعبه\",\"ref\":\"المزمور ١١٥ — التاسعة\",\"v\":\"أوفي للرب نذوري في ديار بيت الرب، قدام كل شعبه. في وسط أورشليم.\",\"r\":\"يوفي المرنم نذوره للرب في ديار بيته أمام كل شعبه في وسط أورشليم. فنحن قول واحد وخبز واحد، نقف معًا ونأخذ معًا. فكر اليوم في معنى أن تقف مع الجماعة وتشاركها المائدة.\",\"p\":\"يا رب، أوفي لك نذوري أمام كل شعبك. اجعلنا قولًا واحدًا وخبزًا واحدًا، واحفظنا في وحدة جسدك. آمين.\",\"x\":\"يوفي المرنم نذوره في ديار بيت الرب أمام كل شعبه. نحن قول واحد وخبز واحد، نقف معًا ونأخذ معًا. تدريب: أوفِ اليوم بوعد قطعته لله أو لشخص.\"},{\"t\":\"خبز واحد، جسد واحد\",\"ref\":\"كورنثوس الأولى ١٠: ١٧\",\"bk\":\"كورنثوس الأولى\",\"v\":\"فإننا نحن الكثيرين خبز واحد، جسد واحد، لأننا جميعنا نشترك في الخبز الواحد.\",\"r\":\"«فإننا نحن الكثيرين خبز واحد، جسد واحد، لأننا جميعنا نشترك في الخبز الواحد». التناول ليس لقاءً فرديًا فقط، بل هو بناء للجسد الواحد. فعندما أتناول أتحد بالمسيح، وأتحد بكل من يتناول معي.\",\"p\":\"يا رب، اجعلني أشترك في الخبز الواحد بقلب نقي. وحّدنا في جسدك، واغفر لنا ما بيننا، واجمعنا فيك. آمين.\",\"x\":\"هنا يربط بولس بين الإفخارستيا والكنيسة. فالقربانة الواحدة من حبوب كثيرة، والكأس من عنب كثير. وهكذا الكنيسة. ولذلك يتقدم المؤمنون للتناول بالتوبة والمصالحة، لأن الشركة مع المسيح تقتضي شركة مع الإخوة. وقد أكد الآباء أن الكنيسة تبنى بالقداس. وقبل التناول نصلي ونطلب الصلح لأن الهدية على المذبح تحتاج إلى صفاء.\\nقبل القداس القادم، صالح من بينك وبينه جفاء، أو صلِّ له بصدق.\"},{\"t\":\"الأكل مع الأخ\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ماتوى: إذا كنت لا تتضايق وتأكل مع الأخ حسنًا تفعل. المائدة المشتركة علامة وحدة تتقدم على ترتيبنا الخاص. شارك اليوم وجبة مع أحد من أسرتك أو كنيستك دون مشاغل.\",\"p\":\"يا رب، اجعل مائدتنا مكان محبة. علّمني أن أترك رغبتي الخاصة لأجل الشركة. آمين.\",\"x\":\"لأخ سأل ماذا يعمل إذا جاءه أخ وقت صوم قال الأب ماتوى: إذا كنت لا تتضايق وتأكل مع الأخ حسنًا تفعل، وإذا كنت ترجو أن تأكل دون أن تنتظر أحدًا فهذا مرهون بإرادتك. المحبة تسبق الترتيب. تدريب: قدم اليوم راحة أخ على راحتك.\",\"fq\":272}]},\"10-8\":{\"th\":\"خبز الحياة\",\"m\":[{\"t\":\"فتشبع نفسي\",\"ref\":\"المزمور ٦٣ — باكر\",\"v\":\"لذلك أباركك في حياتي؛ وباسمك أرفع يدي. فتشبع نفسي كما من شحم ودسم.\",\"r\":\"يبارك المرنم الرب في حياته ويرفع يديه باسمه، فتشبع نفسه كما من شحم ودسم. المسيح هو الخبز الذي يعطي الحياة، ونتقبله بالإيمان والتسبيح. اقرأ اليوم فصلًا من يوحنا ٦، وتأمل أن المسيح هو خبزك.\",\"p\":\"يا رب يسوع، أنت خبز الحياة. أشبع نفسي منك، وأقبل رفع يدي بالتسبيح. آمين.\",\"x\":\"يبارك المرنم الرب في حياته ويرفع يديه باسمه فتشبع نفسه كما من شحم ودسم. المسيح هو الخبز الذي يشبع. تدريب: قبل أن تأكل اليوم ارفع يديك بصلاة شكر.\"},{\"t\":\"أنا هو خبز الحياة\",\"ref\":\"يوحنا ٦: ٣٥\",\"bk\":\"يوحنا\",\"v\":\"فقال لهم يسوع: «أنا هو خبز الحياة. من يقبل إلي فلا يجوع، ومن يؤمن بي فلا يعطش أبدا.\",\"r\":\"«أنا هو خبز الحياة. من يقبل إلي فلا يجوع، ومن يؤمن بي فلا يعطش أبدًا». أبحث عن الشبع في أشياء كثيرة، لكن جوعي الأعمق لا يشبعه إلا المسيح. وعندما أقبل إليه أجد ما كنت أبحث عنه.\",\"p\":\"يا رب، أنت خبز الحياة، أشبع جوع نفسي بك. لا تدعني أبحث عن الشبع في غيرك، وأعطني أن أقبل إليك كل يوم. آمين.\",\"x\":\"قال الرب هذا بعد معجزة إشباع الخمسة الآلاف، حين طلب الناس خبزًا مادياً. فأرشدهم إلى الخبز الحقيقي. وكما أن المن أعطي لبني إسرائيل في البرية، المسيح هو الغذاء النازل من السماء. وتقدم الكنيسة هذه الحقيقة في الإفخارستيا. وعبارة «يقبل إلي» و«يؤمن بي» تعني أن الشبع يتم بالعلاقة. والصوم يعلمنا أن نجوع إلى الله.\\nاليوم، عندما تشعر بجوع أو ملل، صلِّ: «أنت خبز الحياة، أشبعني بك».\"},{\"t\":\"مريم تحتاج إلى مرثا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يجيب الأب سلوان أخًا قرأ طوال النهار ولم يأكل: لأنك إنسان روحي ولا تحتاج إلى هذا الطعام، أما نحن فبشر ونحتاج إليه لهذا نعمل. ثم يضيف أن مريم تحتاج إلى مرثا، لأن مريم تُمتدح بسبب مرثا. الخبز الروحي والجسدي يخدم أحدهما الآخر. اشكر اليوم من يخدمك خبزك اليومي.\",\"p\":\"يا رب، أطعمني من كلمتك وبارك خبزي اليومي. علّمني أن أقدّر من يخدمني فأتفرغ أنا لحضورك. آمين.\",\"x\":\"لأخ سأل لماذا لا يأكل وقد قرأ طوال النهار أجاب الأب سلوان: لأنك إنسان روحي ولا تحتاج إلى هذا الطعام، أما نحن فبشر ونحتاج إليه. الأب يداعبه ليعلمه ألا يتشامخ. تدريب: لا تحتقر ضعف جسدك، واعتنِ به.\",\"fq\":511}]},\"10-9\":{\"th\":\"المعمودية والولادة الجديدة\",\"m\":[{\"t\":\"الذي يحفظ الأطفال هو الرب\",\"ref\":\"المزمور ١١٤ — التاسعة\",\"v\":\"الذي يحفظ الأطفال هو الرب. اتضعت فخلصني.\",\"r\":\"الرب هو الذي يحفظ الأطفال، والمرنم يقول: اتضعت فخلصني. المعمودية ولادة جديدة من الماء والروح، ولا يدخل الملكوت إلا من صار كطفل. تذكر اليوم يوم معموديتك أو اسأل أهلك عن تاريخه.\",\"p\":\"يا رب، يا حافظ الأطفال، اتضعت فخلصتني. أشكرك على ميلادي الجديد بالمعمودية، وأعطني أن أحيا كابنك. آمين.\",\"x\":\"الرب يحفظ الأطفال، والمرنم يقول اتضعت فخلصني. المعمودية ولادة جديدة من الماء والروح للمتضعين. تدريب: اشكر الله على اسمك المسيحي وعلى يوم معموديتك.\"},{\"t\":\"يولد من الماء والروح\",\"ref\":\"يوحنا ٣: ٥\",\"bk\":\"يوحنا\",\"v\":\"أجاب يسوع: «الحق الحق أقول لك: إن كان أحد لا يولد من الماء والروح لا يقدر أن يدخل ملكوت الله.\",\"r\":\"«إن كان أحد لا يولد من الماء والروح لا يقدر أن يدخل ملكوت الله». المعمودية ولادة جديدة وليست طقسًا فقط. وأنا ولدت مرة من أبويّ ومرة من الله. وهذا يمنحني هوية جديدة كابن لله.\",\"p\":\"يا رب، أشكرك على ولادتي الثانية من الماء والروح. ثبتني في بنوتي لك، وأعطني أن أحيا كابن مولود من فوق. آمين.\",\"x\":\"سأل نيقوديموس: كيف يمكن للإنسان أن يولد وهو شيخ؟ فأجابه الرب عن الماء والروح. وفهمت الكنيسة منذ البدء هذا النص كإشارة إلى المعمودية. والماء يشير إلى الغسل والروح إلى التجديد. ولذلك نعمّد الأطفال والكبار. والمعمودية تتم مرة واحدة، لكن التوبة تجددها. وفي كنيستنا، تلبس المعمودية الطفل ثوبًا أبيض، وهو علامة الحياة الجديدة.\\nتذكر تاريخ معموديتك، واسأل أهلك إن لم تكن تعرفه، وقدم شكرًا لله في ذلك اليوم.\"},{\"t\":\"كل شيء يخضع له\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بولس وهو يمسك الأفاعي: الإنسان إذا اقتنى الطهارة فإن كل شيء يخضع له ويطيعه، كحال آدم في الفردوس قبل أن يعصى. المعمودية أعادت لنا ذلك الأصل. اسأل الله اليوم أن يعيد فيك براءة المعمودية.\",\"p\":\"يا رب، أعد إليّ نقاء ميلادي الجديد. طهّر قلبي ليخضع لك كل ما فيّ. آمين.\",\"x\":\"وهو يمسك الأفاعي قال الأب بولس للإخوة: الإنسان إذا ما اقتنى الطهارة فإن كل شيء يخضع له ويطيعه كحال آدم في الفردوس قبل أن يعصى. الطهارة تعيد ما فقده آدم. تدريب: احفظ نظرك اليوم من كل ما يلوث.\",\"fq\":475}]},\"10-10\":{\"th\":\"المسحة والروح القدس\",\"m\":[{\"t\":\"مسحك الله بزيت البهجة\",\"ref\":\"المزمور ٤٤ (٤٥) — الثالثة\",\"v\":\"لأنك أحببت البر وأبغضت الإثم. من أجل هذا مسحك الله إلهك بزيت البهجة أفضل من رفقائك.\",\"r\":\"أحب الملك البر وأبغض الإثم، فمسحه الله بزيت البهجة أفضل من رفقائه. المسحة تعلن أن الروح القدس يحل علينا ويقدسنا. اطلب اليوم من الله أن يمسح خدمتك وصلاتك بروحه.\",\"p\":\"يا رب، أحببت البر فامسحني بزيت البهجة. اسكب روحك القدوس عليّ لأصلي وأخدم كما يليق. آمين.\",\"x\":\"مسح الله الملك بزيت البهجة لأنه أحب البر وأبغض الإثم. مسحة الميرون تقدس كل مسيحي. تدريب: ارشم نفسك اليوم بعلامة الصليب وقل: أنا مسيح الرب.\"},{\"t\":\"الذي مسحنا هو الله\",\"ref\":\"كورنثوس الثانية ١: ٢١\",\"bk\":\"كورنثوس الثانية\",\"v\":\"ولكن الذي يثبتنا معكم في المسيح، وقد مسحنا، هو الله\",\"r\":\"«الذي يثبتنا معكم في المسيح، وقد مسحنا، هو الله». الله هو الذي يثبتني ويمسحني. فثباتي ليس مجهودي وحدي. وأنا أحتاج أن أعيش كمن عليه مسحة الله: بقداسة وطمأنينة وخدمة.\",\"p\":\"يا رب، أنت الذي ثبتني ومسحتني، فاحفظ ختمك عليّ. أعطني أن أحيا كمن عليه مسحتك، وأعمل أعمالك بقوة روحك. آمين.\",\"x\":\"المسحة في الكتاب تقدس الكهنة والملوك والأنبياء، وتدل على اختيار الله وتخصيصه. وفي المسيحية، يُمسح المؤمن بالميرون المقدس بعد المعمودية فيصير هيكلًا للروح. والآية التالية تقول إن الله ختمنا وأعطى عربون الروح في قلوبنا. أي أن الروح القدس ضمان لما سيأتي. وحياتنا في الكنيسة تقوم على هذه النعمة. فلا نعيش حياة عادية بل حياة مختومة.\\nاليوم، اشكر الله على ختم الروح القدس، وصلِّ طالبًا أن ترى مسحته في عملك.\"},{\"t\":\"نارًا ملتهبة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوسف للأب لوط: لا تستطيع أن تصير راهبًا إذا لم تصبح نارًا ملتهبة بالكلية. الروح القدس يعلّمنا أن نحترق بالمحبة لا بالحماس العابر. اطلب اليوم حرارة الروح لصلاة واحدة.\",\"p\":\"يا رب، أشعل فيّ نار روحك. اجعلني ملتهبًا بحبك بالكلية. آمين.\",\"x\":\"قال الأب يوسف للأب لوط: لا تستطيع أن تصير راهبًا إذا لم تصبح نارًا ملتهبة بالكلية. الروح القدس ناري. تدريب: اطلب اليوم غيرة ملتهبة لعمل واحد.\",\"fq\":184}]},\"10-11\":{\"th\":\"الاستعداد للتجربة\",\"m\":[{\"t\":\"بصوتي إلى الرب صرخت\",\"ref\":\"المزمور الثالث — باكر\",\"v\":\"بصوتي إلى الرب صرخت. فاستجاب لي من جبل قدسه.\",\"r\":\"يقول المرنم: بصوتي إلى الرب صرخت فاستجاب لي من جبل قدسه. من يستعد للتجربة يصرخ قبل أن تشتد. اكتب اليوم ما يخيفك من تجارب قادمة، وارفعها في صلاة قصيرة.\",\"p\":\"يا رب، بصوتي إليك صرخت فاستجب لي. استعدني لكل تجربة تأتي، وكن معي فيها. آمين.\",\"x\":\"صرخ المرنم بصوته إلى الرب فاستجاب من جبل قدسه. من يستعد للتجربة يصرخ قبل أن تشتد. تدريب: اكتب ما يخيفك وسلّمه لله قبل أن يحدث.\"},{\"t\":\"أعدد نفسك للتجربة\",\"ref\":\"يشوع بن سيراخ ٢: ١\",\"bk\":\"يشوع بن سيراخ\",\"v\":\"يا بني إن أقبلت لخدمة الرب الإله فاثبت على البر والتقوى وأعدد نفسك للتجربة\",\"r\":\"«يا بني، إن أقبلت لخدمة الرب الإله فاثبت على البر والتقوى وأعدد نفسك للتجربة». الحكيم لا يعد بطريق سهل، بل بإعداد للنفس. وأنا حين أبدأ خدمة أو توبة أتوقع المقاومة ولا أنزعج منها، فالتجربة جزء من الطريق.\",\"p\":\"يا رب، أنا أريد خدمتك فأعدّني للتجربة. ثبتني على البر والتقوى، ولا تدعني أتفاجأ بالضيق أو أتراجع عنه. آمين.\",\"x\":\"سفر يشوع بن سيراخ من أسفار الحكمة التي تقرأها الكنيسة القبطية وتستشهد بها. وفي مطلع الأصحاح الثاني يخاطب القارئ كابن، وينبهه إلى أن الخدمة تجلب امتحانات. والنصيحة هنا ثلاثية: الثبات، والبر والتقوى، والإعداد. وهذا يتفق مع قول الرب: «في العالم سيكون لكم ضيق». فالاستعداد ليس تشاؤمًا بل واقعية روحية. وقد علّم الآباء أن الراهب يبدأ جهاده بالاستعداد للحرب لا للراحة.\\nاكتب اليوم تجربة متوقعة في خدمتك أو دراستك أو بيتك، وخطط كيف تثبت فيها بصلاة وحكمة.\"},{\"t\":\"أبعد التجارب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إفاغريوس كلمة قصيرة: أبعِدْ التجارب فلا يخلص أحد. فالتجارب تفتحنا على حاجتنا إلى الله، فنتعلم الصلاة والصبر. قل لنفسك اليوم: التجربة طريق لا عائق.\",\"p\":\"يا رب، لا تدخلني في تجربة فوق طاقتي. علّمني أن أنتصر بها وأقترب منك أكثر. آمين.\",\"x\":\"يقول الأب إفاغريوس: أبعِدْ التجارب فلا يخلص أحد. التجربة تعلمنا حاجتنا إلى الله. تدريب: عند أول تجربة اليوم قل: يا رب ساعدني، ولا تتذمر منها.\",\"fq\":112}]},\"10-12\":{\"th\":\"مخافة الرب\",\"m\":[{\"t\":\"يسر الرب بخائفيه\",\"ref\":\"المزمور ١٤٦ — النوم\",\"v\":\"لا يؤثر قوة الفرس ولا يسر بساقي الرجل، بل يسر الرب بخائفيه وبالراجين رحمته هلليلويا.\",\"r\":\"لا يؤثر الرب قوة الفرس ولا ساقي الرجل، بل يسر بخائفيه والراجين رحمته. مخافة الرب بداية الحكمة وهي تواضع أمام قداسته. ابدأ اليوم بصلاة قصيرة تعبر فيها عن احترامك لله.\",\"p\":\"يا رب، يسرّك الخائفون والراجون رحمتك. ضع في قلبي مخافتك فلا أخاف شيئًا آخر. آمين.\",\"x\":\"لا يؤثر الرب قوة الفرس ولا ساقي الرجل بل يسر بخائفيه والراجين رحمته. المخافة تواضع أمام قداسته. تدريب: قل اليوم في صلاتك: أنا لا أستحق، لكني أرجو رحمتك.\"},{\"t\":\"مخافة الرب مجد\",\"ref\":\"يشوع بن سيراخ ١: ١١\",\"bk\":\"يشوع بن سيراخ\",\"v\":\"مخافة الرب مجد وفخر وسرور وإكليل ابتهاج\",\"r\":\"«مخافة الرب مجد وفخر وسرور وإكليل ابتهاج». لا تعني المخافة الارتعاب بل الإجلال المحب. إنها أن أخاف أن أجرح قلب أبي. وهي عندي مصدر فرح، لأن من يهاب الله لا يهاب أحدًا.\",\"p\":\"يا رب، علمني مخافتك المحبة. اجعلها فخرًا وسرورًا لي، وامنعني من كل ما يجرح قلبك. آمين.\",\"x\":\"الأصحاح الأول من سيراخ يتغنى بمخافة الرب بوصفها بداية الحكمة وكمالها. والعدد الذي يلينا يقول إن مخافة الرب تلذ القلب وتعطي السرور وطول الأيام. وهذه المخافة مرتبطة بالمحبة، فالمتقي هو المحب. ولذلك يقول الكتاب في موضع آخر: «بدء الحكمة مخافة الرب». وفي الصلاة نقف بخشوع وحب أمام الله، فنجمع بين الاثنين. وقد علّم الآباء أن المخافة البنوية هي أن يخشى الابن أن يخسر رضا أبيه.\\nاليوم، قبل اتخاذ قرار، اسأل نفسك: هل يفرح قلب الله بهذا؟ ثم اختر.\"},{\"t\":\"خوف الله والتواضع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب أفربيوس: فليلازمك خوف الله والتواضع والحرمان من الأطعمة وأيضًا النوح. المخافة صحبة دائمة لا زائر عابر. اختر اليوم عملًا صغيرًا تؤديه خوفًا من الله لا من الناس.\",\"p\":\"يا رب، لازم قلبي بمخافتك وتواضعك. علّمني أن أخافك محبة. آمين.\",\"x\":\"يوصي الأب أفربيوس: فليلازمك خوف الله والتواضع والحرمان من الأطعمة وأيضًا النوح. أربع رفقة دائمة. تدريب: اختر منها واحدة وخذها صحبة اليوم.\",\"fq\":106}]},\"10-13\":{\"th\":\"انتظار رحمته\",\"m\":[{\"t\":\"وإياك انتظرت النهار كله\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"لأنك أنت هو الله مخلصي. وإياك انتظرت النهار كله.\",\"r\":\"يقول المرنم: أنت هو الله مخلصي وإياك انتظرت النهار كله. انتظار رحمته لا يضيع، فهي أقرب مما نظن. اجلس اليوم دقائق وانتظر الله بلا طلبات، فقط لتتذكر أنه رحيم.\",\"p\":\"يا رب، أنت الله مخلصي، وإياك انتظرت النهار كله. لا تدعني أخزى، بل أنقذني برحمتك. آمين.\",\"x\":\"أنت الله مخلصي وإياك انتظرت النهار كله، فانتظار رحمته لا يضيع. تدريب: اجلس اليوم دقائق بلا طلب، ثم قل: ها أنا منتظر.\"},{\"t\":\"انتظروا رحمته\",\"ref\":\"يشوع بن سيراخ ٢: ٧\",\"bk\":\"يشوع بن سيراخ\",\"v\":\"أيها المتقون للرب انتظروا رحمته ولا تحيدوا لئلا تسقطوا\",\"r\":\"«أيها المتقون للرب، انتظروا رحمته ولا تحيدوا لئلا تسقطوا». الانتظار يحتاج ثباتًا في الطريق. وأكثر ما يسقطني هو الاستعجال والانحراف عن الطريق عندما يتأخر الفرج. فلأبقَ على الدرب حتى تأتي رحمته.\",\"p\":\"يا رب، علمني أن أنتظر رحمتك بصبر. احفظني من الحيدان عن طريقك، ولا تدعني أسقط في تأخر الجواب. آمين.\",\"x\":\"هذه الآية جزء من سلسلة نداءات متتالية في الأصحاح الثاني، كل منها يبدأ بـ«أيها المتقون للرب»: انتظروا رحمته، آمنوا به، أملوا الخيرات. وهذا التكرار يشبه إيقاع التسبحة. وتعلمنا أن الحياة الروحية انتظار نشط. وقد سمى الآباء الصبر «ملكة الفضائل». والتحيد يعني ترك الطريق المستقيم بحثًا عن حلول سريعة. وكثير من السقوط يبدأ من تعب الانتظار.\\nإذا كنت تنتظر أمرًا من الله، اكتب اسمه على ورقة وضعها في كتابك المقدس، وقل كل يوم: «أنتظر رحمتك».\"},{\"t\":\"ثلاثة أيام\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيسوى: أؤمن أن الإنسان إذا تاب من كل قلبه فإن الله يقبله في غضون ثلاثة أيام. الله لا يؤخر رحمته على التائب. إن كنت تؤجل توبة، فابدأ اليوم.\",\"p\":\"يا رب، أتوب إليك من كل قلبي. اقبلني سريعًا برحمتك، ولا تؤخر مغفرتك. آمين.\",\"x\":\"لمن سأل إذا سقط أخ ألا ينبغي أن يتوب سنة كاملة قال الأب سيسوى إن فترة وجيزة تكفيه، لأن الإنسان إذا تاب من كل قلبه يقبله الله في غضون ثلاثة أيام. الله لا يؤخر رحمته. تدريب: لا تؤجل توبتك، ابدأها اليوم.\",\"fq\":494}]},\"10-14\":{\"th\":\"الاتضاع والوداعة\",\"m\":[{\"t\":\"يعاين المتواضعات\",\"ref\":\"المزمور ١٣٧ — النوم\",\"v\":\"لأن مجد الرب عظيم لأن الرب عال ويعاين المتواضعات والكائنات يعرفها من بعد.\",\"r\":\"مجد الرب عظيم، وهو عالٍ ويعاين المتواضعات ويعرف الكائنات من بعد. الاتضاع والوداعة أقرب الطرق إلى قلب الله. افعل اليوم شيئًا صغيرًا دون أن يعرف أحد، واترك الله وحده يعاين.\",\"p\":\"يا رب العلي الذي يعاين المتواضعات، علّمني الاتضاع. اجعل قلبي وديعًا كقلبك. آمين.\",\"x\":\"مجد الرب عظيم وهو عالٍ ويعاين المتواضعات، ويعرف الكائنات من بعد. التواضع يقرب منه. تدريب: اختر اليوم الموضع الأخير في موقف عادي.\"},{\"t\":\"اقض أعمالك بالوداعة\",\"ref\":\"يشوع بن سيراخ ٣: ١٩\",\"bk\":\"يشوع بن سيراخ\",\"v\":\"يا بني اقض أعمالك بالوداعة فيحبك الإنسان الصالح\",\"r\":\"«يا بني، اقضِ أعمالك بالوداعة فيحبك الإنسان الصالح». أنجز عملي بسلام لا بصخب. فكثيرًا ما أخسر الحب لأنني أصر على أن أنجز كل شيء بسرعة وقوة. والوداعة لا تعطل العمل بل تجعله مقبولًا.\",\"p\":\"يا رب، علمني أن أنجز أعمالي بوداعة. انزع مني الصخب والقسوة، وامنحني روحًا هادئة تجذب الناس إليك. آمين.\",\"x\":\"في الأصحاح الثالث يتناول ابن سيراخ الاتضاع كفضيلة عملية. والوداعة تعبر عن سلام داخلي ينعكس في أسلوب العمل والتعامل. وهي من ثمار الروح القدس. والإنسان الصالح، أي من يعرف قيمة الفضيلة، يتجه إلى المتواضع. وهذا ما نراه في الكنيسة: الخادم الوديع يجذب القلوب أكثر من الصاخب. وقد كان الأنبا موسى الأسود نموذجًا لتحول القسوة إلى وداعة.\\nاليوم أنجز مهمة واحدة بهدوء وبشاشة، ولاحظ كيف يستقبلها الناس.\"},{\"t\":\"ولم أبلغ بعد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب كاريون عن ابنه زخريا: بذلت جهودًا كثيرة تفوق ما بذله، ولم أبلغ بعد إلى قامته في التواضع والصمت. الاتضاع أن نعرف فضل غيرنا. اعترف اليوم بفضيلة عند شخص تتعلم منه.\",\"p\":\"يا رب، علّمني أن أتعلم من الصغار. أعطني تواضعًا يعترف بفضل غيري. آمين.\",\"x\":\"يقول الأب كاريون عن ابنه زخريا: بذلت جهودًا كثيرة تفوق ما بذله ابني، ولم أبلغ بعد إلى قامته في التواضع والصمت. الأب يعترف بتقدم ابنه. تدريب: اعترف بفضل من هو أصغر منك.\",\"fq\":220}]},\"10-15\":{\"th\":\"الرحمة بالفقير\",\"m\":[{\"t\":\"هذا المسكين صرخ\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"هذا المسكين صرخ فاستمعه الرب. ومن جميع ضيقاته خلصه.\",\"r\":\"هذا المسكين صرخ فاستمعه الرب ومن جميع ضيقاته خلصه، وهكذا يريدنا أن نرحم الفقير. الرحمة بالفقير تقليد لحنان الله نفسه. أعط اليوم من مالك أو وقتك لمحتاج، واذكر أنه ينوب عن المسيح.\",\"p\":\"يا رب، يا من تسمع صراخ المسكين، أعطني قلبًا رحيمًا. علّمني أن أعطي بفرح وسخاء. آمين.\",\"x\":\"هذا المسكين صرخ فاستمعه الرب، وهكذا يريدنا أن نرحم الفقير. الرحمة تقليد لحنان الله. تدريب: أعطِ اليوم لفقير أو لمن يحتاج، حتى لو قليلًا.\"},{\"t\":\"لا تحرم المسكين\",\"ref\":\"يشوع بن سيراخ ٤: ١\",\"bk\":\"يشوع بن سيراخ\",\"v\":\"يا بني لا تحرم المسكين ما يعيش به ولا تماطل عيني المعوز\",\"r\":\"«يا بني، لا تحرم المسكين ما يعيش به، ولا تماطل عيني المعوز». التأجيل في العطاء قسوة خفية. فالمحتاج لا ينتظر. وأنا حين أؤجل صدقتي أطيل ألمه. فلأعطِ ما أستطيع الآن، ولو كان قليلًا.\",\"p\":\"يا رب، افتح يدي لعطاء سريع وقلبي لرحمة حقيقية. لا تدعني أماطل عيني المحتاج، واجعلني قناة لبركتك. آمين.\",\"x\":\"تحتل الصدقة مكانة كبرى في سفر سيراخ، الذي يقول في موضع آخر إن الصدقة تكفر الخطايا. وكلمة «لا تماطل عيني المعوز» تعني ألا نتركه ينتظر طويلًا. وفي ممارسة الكنيسة، الصدقة جزء من الصوم والصلاة. وتعلمنا أن نعطي بفرح وسرعة. وقد قال الآباء إن الخبز الذي تحتفظ به هو للجائع. وذلك لا يعني الإسراف بل حسن التدبير والرحمة.\\nاليوم، أعط شخصًا محتاجًا شيئًا فورًا، ولا تؤجل إلى وقت أنسب.\"},{\"t\":\"أتصدق بإثنتين\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب لوكيوس إنه يربح من عمله وصلاته ست عشرة قطعة، يتصدق بإثنتين منها ويعيش بالباقي، والذي يتصدق عليه يصلي من أجله. العطاء يربط الغني بالفقير في صلاة واحدة. خصص اليوم نسبة صغيرة من دخلك للعطاء.\",\"p\":\"يا رب، علّمني أن أجعل العطاء جزءًا ثابتًا من حياتي. وبارك من أعطيهم ليصلوا من أجلي. آمين.\",\"x\":\"يقول الأب لوكيوس إنه يربح من عمله وصلاته ست عشرة قطعة، يتصدق باثنتين منها ويعيش بالباقي، والذي يتصدق عليه يصلي من أجله. العطاء يشترك فيه المحتاج بصلاته. تدريب: خصص جزءًا ثابتًا من دخلك للعطاء.\",\"fq\":227}]},\"10-16\":{\"th\":\"الصديق الأمين\",\"m\":[{\"t\":\"أنت باركت الصديق\",\"ref\":\"المزمور الخامس — باكر\",\"v\":\"لأنك أنت باركت الصديق يا رب. كما بترس المسرة كللتنا.\",\"r\":\"يقول المرنم: أنت باركت الصديق يا رب، كما بترس المسرة كللتنا. الصديق الأمين عطية الله وستر وكنز. اكتب اليوم رسالة قصيرة لصديق أمين تشكره فيها.\",\"p\":\"يا رب، بارك أصدقائي الأمناء. اجعلني صديقًا أمينًا لغيري كما أنت لي. آمين.\",\"x\":\"أنت باركت الصديق يا رب، كما بترس المسرة كللتنا. الصديق الأمين عطية الله وستر. تدريب: اكتب رسالة شكر لصديق أمين واتصل به.\"},{\"t\":\"الصديق الأمين معقل حصين\",\"ref\":\"يشوع بن سيراخ ٦: ١٤\",\"bk\":\"يشوع بن سيراخ\",\"v\":\"الصديق الأمين معقل حصين ومن وجده فقد وجد كنزا\",\"r\":\"«الصديق الأمين معقل حصين، ومن وجده فقد وجد كنزًا». الصديق الأمين هبة من الله. فلأشكره على أصدقائي، ولأكون أنا أيضًا صديقًا أمينًا لغيري. فالأمانة أغلى من المصلحة. فلأشكر الله على أصدقائي اليوم.\",\"p\":\"يا رب، أشكرك على الأصدقاء الأمناء. باركهم واحفظهم، واجعلني صديقًا أمينًا يقود غيره إليك. آمين. وثبّت مودتنا بسلامك.\",\"x\":\"يضع ابن سيراخ الصداقة في مرتبة الكنوز، ويقول بعدها إنه لا شيء يعادل الصديق الأمين. وفي الإنجيل سمى الرب تلاميذه أحباء، وقال: «ليس لأحد حب أعظم من هذا». فالصداقة الحقيقية تشبه محبة المسيح. وقد عاش القديسان أنطونيوس ومقاريوس علاقات روحية عميقة. والصديق الأمين يذكرنا بالله ويشجعنا على التوبة. ونحتاج أن نختار من يبني نفوسنا.\\nأرسل اليوم رسالة شكر لصديق أمين، وأخبره كم هو ثمين.\"},{\"t\":\"صديق من يقسو على نفسه\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح الأب بيمن أخًا: كن صديقًا لمن يقسو على نفسه. الصديق الأمين يجالس من يجاهد ولا يخفف عنه جهاده. ابحث اليوم عن صديق روحي يشجعك على الجهاد.\",\"p\":\"يا رب، اجمعني بأصدقاء يقوّونني في جهادي. وكن أنت الصديق الأمين لنفسي. آمين.\",\"x\":\"لأخ ذاهب إلى السوق قال الأب بيمن: كن صديقًا لمن يقسو على نفسه، فتبيع سلالك بسهولة. الصديق الذي يجاهد يعين على الخير. تدريب: اختر صحبة من يجاهد.\",\"fq\":436}]},\"10-17\":{\"th\":\"الغفران والتوبة\",\"m\":[{\"t\":\"ارحمني اشف نفسي\",\"ref\":\"المزمور ٤٠ (٤١) — الثالثة\",\"v\":\"أنا قلت يا رب ارحمني، اشف نفسي لأني قد أخطأت إليك.\",\"r\":\"يقول المرنم: أنا قلت يا رب ارحمني، اشف نفسي لأني قد أخطأت إليك. الغفران يبدأ بالاعتراف الصريح بالخطأ. اعترف اليوم بخطأ لشخص وأنت تطلب المسامحة.\",\"p\":\"يا رب، ارحمني واشف نفسي لأني أخطأت إليك. أعطني قلبًا يغفر كما غفرت لي. آمين.\",\"x\":\"قال المرنم: ارحمني اشف نفسي لأني أخطأت إليك. الشفاء يبدأ بالاعتراف دون تبرير. تدريب: سمِّ خطيتك اليوم أمام الله بوضوح بلا عذر.\"},{\"t\":\"اغفر لقريبك\",\"ref\":\"يشوع بن سيراخ ٢٨: ٢\",\"bk\":\"يشوع بن سيراخ\",\"v\":\"اغفر لقريبك ظلمه لك فإذا تضرعت تمحى خطاياك\",\"r\":\"«اغفر لقريبك ظلمه لك، فإذا تضرعت تمحى خطاياك». هذا هو نفس مبدأ الصلاة الربانية: اغفر لنا كما نغفر. وإن تمسكت بمرارتي، أعطلت صلاتي. فالغفران ليس كرمًا مني بل شرط لنوال الرحمة.\",\"p\":\"يا رب، اغفر لي كما أغفر لقريبي. أعطني قلبًا يترك المرارة، ويصلي من أجل من أساء إليّ. آمين.\",\"x\":\"هذه الوصية قبل المسيح بقرنين، وهي تتفق مع تعليم الرب في متى ٦ وغيره. ولا يطلب الغفران نسيان الألم، بل ترك الحق في الانتقام لله. وهو عملية قد تأخذ وقتًا. وقد تعلم القديسون هذا من الصليب: «يا أبتاه اغفر لهم». وفي القداس نصلي «كما نغفر نحن أيضًا». وتنصحنا الكنيسة بالمصالحة قبل التناول. وهذا جزء من التهيؤ.\\nاكتب اسم شخص أساء إليك، وصلِّ له بالخير، وقل: «أغفر له كما تغفر لي».\"},{\"t\":\"يبكي هنا أو هناك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن عن الأب أرسانيوس: من لا يبكي نفسه هنا سيبكي هناك أبدًا، فالإنسان لا بد أن يبكي إما هنا طوعًا أو هناك من العذابات. التوبة دموع تقبل الغفران. ابك اليوم أمام الله على خطية واحدة بصدق.\",\"p\":\"يا رب، أعطني دموع التوبة هنا لئلا أبكي هناك. اغسل خطاياي بنعمتك. آمين.\",\"x\":\"لما رأى الأب بيمن الأب أرسانيوس يبكي نفسه قال أرسانيوس: من لا يبكي نفسه هنا سيبكي هناك أبدًا، فالإنسان لا بد أن يبكي إما هنا طوعًا أو هناك من العذابات. دموع التوبة رحمة. تدريب: ابكِ اليوم على خطية بصدق.\",\"fq\":44}]},\"10-18\":{\"th\":\"نفوس الصديقين بيد الله\",\"m\":[{\"t\":\"كريم أمام الرب موت قديسيه\",\"ref\":\"المزمور ١١٥ — التاسعة\",\"v\":\"كريم أمام الرب موت قديسيه.\",\"r\":\"كريم أمام الرب موت قديسيه، ونفوس الصديقين بيد الله فلا يمسها عذاب. ساعة الرحيل ليست ظلمة للأبرار بل لقاء. زر اليوم قبرًا أو اذكر قديسًا بصلاة، متأملًا في رجاء الرقاد.\",\"p\":\"يا رب، كريم أمامك موت قديسيك. اجعل نفسي بيدك، وأعطني رجاء الرقاد في الإيمان. آمين.\",\"x\":\"كريم أمام الرب موت قديسيه، ونفوس الصديقين بيده. الرحيل لقاء لا ظلمة. تدريب: زر اليوم أو اتصل بمريض أو مسن وصلِّ معه.\"},{\"t\":\"هم في السلام\",\"ref\":\"الحكمة ٣: ٣\",\"bk\":\"الحكمة\",\"v\":\"وذهابهم عنا عطبا أما هم ففي السلام\",\"r\":\"«وذهابهم عنا عطبًا، أما هم ففي السلام». الموت في عين الجهال نهاية، وفي عين الإيمان انتقال. ومن فقد حبيبًا يجد في هذه الكلمة عزاء حقيقيًا. أما أنا فأصلي لهم وأثق أنهم في يد الله.\",\"p\":\"يا رب، أنت إله الأحياء. أرح أنفس راقدينا في حضنك، وعزّ القلوب الحزينة، وثبت رجاءنا في القيامة. آمين.\",\"x\":\"يقرأ سفر الحكمة في الكنيسة القبطية في مناسبات الراحلين، ويتناول هذه الآيات. والسلام هنا ليس غياب الحياة بل حضور الله. وتؤمن الكنيسة بشركة القديسين، فالراقدون أحياء في المسيح ونحن نصلي لهم. وقد وضع الآباء التبخير والقداس للراقدين تعبيرًا عن هذه الوحدة. وفي التجنيز نطلب لهم الراحة. ولا نبكي كالذين لا رجاء لهم.\\nاذكر اليوم راقدًا عزيزًا في صلاة خاصة، واطلب له الراحة ولنفسك الرجاء.\"},{\"t\":\"تتذكر هذه الساعة\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال البابا ثيوفيلوس عند رحيله للأب أرسانيوس: هنيئًا لك لأنك كنت تتذكر هذه الساعة دائمًا. من يحيا متذكرًا ساعة الرحيل يستقبلها بسلام. اقرأ اليوم قطعة عن الأبدية قبل النوم.\",\"p\":\"يا رب، علّمني أن أتذكر ساعة الرحيل دائمًا. اجعلني مستعدًا لها بالتوبة والرجاء. آمين.\",\"x\":\"قال البابا ثيوفيلوس عند رحيله للأب أرسانيوس: هنيئًا لك يا أرسانيوس لأنك كنت تتذكر هذه الساعة دائمًا. تذكر الساعة يهيئ لها. تدريب: اسأل نفسك اليوم: ماذا أريد أن أكون قد فعلت لو كانت الليلة آخر ليلة؟\",\"fq\":146}]},\"10-19\":{\"th\":\"الله يرحم الجميع\",\"m\":[{\"t\":\"أعمال يديك\",\"ref\":\"المزمور ١٣٧ — النوم\",\"v\":\"أعمال يديك يا رب لا تتركها هلليلويا.\",\"r\":\"يصلي المرنم: أعمال يديك يا رب لا تتركها. الله يرحم الجميع لأنه خالق الجميع ولا يترك عمل يديه. ارحم اليوم من أساء إليك بالصلاة له، كمن هو عمل يدي الله.\",\"p\":\"يا رب، أعمال يديك لا تتركها. ارحم الجميع، وأعطني أن أرحم الجميع كما ترحمني. آمين.\",\"x\":\"أعمال يديك يا رب لا تتركها. الله خالق الجميع فلا يترك أحدًا بلا رحمة. تدريب: ارحم اليوم من أساء إليك وصلِّ من أجله.\"},{\"t\":\"ترحم الجميع\",\"ref\":\"الحكمة ١١: ٢٤\",\"bk\":\"الحكمة\",\"v\":\"لكنك ترحم الجميع لأنك قادر على كل شيء وتتغاضى عن خطايا الناس لكي يتوبوا\",\"r\":\"«لكنك ترحم الجميع لأنك قادر على كل شيء، وتتغاضى عن خطايا الناس لكي يتوبوا». رحمة الله ليست ضعفًا بل قوة. وهو يمهلني لأتوب لا لأتمادى. وكل يوم جديد هو فرصة رحمة.\",\"p\":\"يا رب، ترحم الجميع لأنك قادر. أشكرك على إمهالك لي، وأعطني أن أتوب سريعًا وأرحم غيري كما رحمتني. آمين.\",\"x\":\"في الأصحاحات ١١–١٢ يتأمل كاتب الحكمة في صبر الله على المصريين والكنعانيين، ويستنتج أن الله يرحم لأنه قادر. وهذه فكرة عميقة: القوة الحقيقية تظهر في ضبط النفس. وقد قال بطرس: «الرب لا يتباطأ بل هو متأن علينا». فالإمهال دعوة إلى التوبة. وفي كنيستنا نردد: «ارحمنا يا الله» لأننا نثق في رحمته. وتعلمنا هذه الآية ألا نحتقر خاطئًا، فالله يرحم الجميع.\\nاليوم، عندما تحكم على شخص، تذكر أن الله يمهله، وأعطِه فرصة بدل الإدانة.\"},{\"t\":\"يبقى على خليقته\",\"ref\":\"\",\"v\":\"\",\"r\":\"يسأل الأب ميوس جنديًا يسأل إن كان الله يقبل التوبة: إذا كنت أنت تبقى على ثوبك الممزق، ألا يبقى الله على خليقته؟ رحمة الله أوسع من حكمنا على الناس. تذكر اليوم أن أحدًا لا يُحرم من رحمته.\",\"p\":\"يا رب، أنت تبقى على خليقتك. أعطني ثقة في رحمتك للجميع، وللتائبين خاصة. آمين.\",\"x\":\"سأل جندي الأب ميوس هل يقبل الله التوبة، فسأله: إذا تمزق ثوبك هل ترميه؟ فقال لا، بل أصلحه، فقال الأب: إذا كنت أنت تبقى على ثوبك ألا يبقى الله على خليقته؟ تدريب: لا تحكم على نفسك أو غيرك بأنه لا أمل فيه.\",\"fq\":285}]},\"10-20\":{\"th\":\"طلب الحكمة\",\"m\":[{\"t\":\"أبارك الرب الذي أفهمني\",\"ref\":\"المزمور الخامس عشر — باكر\",\"v\":\"أبارك الرب الذي أفهمني. وأيضا إلى الليل تنذرني كليتاي.\",\"r\":\"يبارك المرنم الرب الذي أفهمه، وحتى في الليل تنذره كليتاه. الحكمة عطية تُطلب من الله الذي يفهمنا. اطلب اليوم حكمة لقرار صغير، وانتظر الجواب بهدوء.\",\"p\":\"يا رب، مباركٌ أنت الذي تفهمني. هبني حكمة من عندك أسلك بها اليوم. آمين.\",\"x\":\"يبارك المرنم الرب الذي أفهمه، وحتى الليل تنذره كليتاه. الحكمة تُطلب. تدريب: اطلب حكمة اليوم لقرار محدد، وانتظر الإرشاد.\"},{\"t\":\"تمنيت فأوتيت الفطنة\",\"ref\":\"الحكمة ٧: ٧\",\"bk\":\"الحكمة\",\"v\":\"حينئذ تمنيت فأوتيت الفطنة ودعوت فحل علي روح الحكمة\",\"r\":\"«تمنيت فأوتيت الفطنة، ودعوت فحل عليّ روح الحكمة». الحكمة تُنال بالصلاة قبل الدراسة. وأنا عندما أحتار في قرار أحتاج أن أدعو الله أولًا. وهو لا يرد طلب الحكمة، كما وعد يعقوب بذلك.\",\"p\":\"يا رب، أطلب فطنتك وروح حكمتك. أرشدني في قراراتي، وعلمني ما يرضيك، ولا تتركني لفهمي. آمين.\",\"x\":\"يتكلم هنا كاتب الحكمة بلسان سليمان الذي طلب فهمًا فنال ما لم يطلبه. وهو يقول إنه فضل الحكمة على الصوالجة والعروش. والحكمة هنا ليست مجرد معرفة بل اتحاد بالله وفهم لإرادته. وقد وعد الرب أن الروح يرشدنا إلى الحق.\\nقبل أي قرار مهم هذا الأسبوع، اقضِ خمس دقائق في الصلاة لطلب الحكمة، ثم قرر.\"},{\"t\":\"ذهن صاح ويقظ\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: لا نحتاج إلى أحد إلا إذا كان عنده ذهن صاحٍ ويقظ. الحكمة تتطلب مرشدًا يقظًا لا كثير الكلام. اختر لنفسك اليوم مرشدًا حكيمًا وأصغ إليه.\",\"p\":\"يا رب، ضع في طريقي من له ذهن صاح ويقظ. اجعلني أسمع منه باتضاع. آمين.\",\"x\":\"يقول الأب بيمن: لا نحتاج إلى أحد إلا إذا كان عنده ذهن صاحٍ ويقظ. ليس كل مشورة تنفع. تدريب: اختر مرشدًا يقظًا ولا تستشر من يجاملك فقط.\",\"fq\":412}]},\"10-21\":{\"th\":\"الأسرة في قصد الله\",\"m\":[{\"t\":\"أما الرب فقبلني\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"فإن أبي وأمي قد تركاني، وأما الرب فقبلني.\",\"r\":\"يقول المرنم إن أباه وأمه قد تركاه أما الرب فقبله. الله هو أصل الأسرة وهو الذي يضم من ليس له أسرة. اشكر الله اليوم على أسرتك وصلِّ لكل فرد فيها، وللذين يعيشون بلا أسرة.\",\"p\":\"يا رب، بارك أسرتي وأحفظها في محبتك. وكن أبًا لمن ليس له أب وأمًّا لمن ليس له أم. آمين.\",\"x\":\"أبواي تركاني أما الرب فقبلني. الله أصل الأسرة وهو يضم من ليس له أحد. تدريب: ادعُ إلى مائدتك اليوم أو ابحث عن وحيد.\"},{\"t\":\"ليس جيدًا أن يكون آدم وحده\",\"ref\":\"التكوين ٢: ١٨\",\"bk\":\"التكوين\",\"v\":\"وقال الرب الإله: «ليس جيدا أن يكون آدم وحده، فأصنع له معينا نظيره».\",\"r\":\"«ليس جيدًا أن يكون آدم وحده، فأصنع له معينًا نظيره». الله هو الذي رأى حاجة الإنسان إلى الشركة. فالوحدة ليست طبيعتنا، والأسرة هبة من الله لا مجرد عرف اجتماعي. وأنا أشكره اليوم على من أعطاني ليكونوا معي.\",\"p\":\"يا رب، أشكرك لأنك لم تتركني وحدي. بارك أسرتي وكنيستي، واجعلني معينًا لمن حولي كما أعنتني. آمين.\",\"x\":\"في الأصحاح الثاني من التكوين، بعد أن قال الله عن كل ما خلق إنه حسن، يقول للمرة الأولى «ليس جيدًا». فالنقص ليس في الخليقة بل في غياب الشريك. وكلمة «معينًا» تعني من يسند، وليست دونية، فالله نفسه يسمى «معين» في المزامير. و«نظيره» أي مقابله ومثيله. ومنذ البدء نرى أن الله خلق الإنسان على صورة شركة. والكنيسة تعتبر الأسرة كنيسة صغيرة تتعلم فيها المحبة.\\nاليوم، اشكر الله على فرد من أسرتك أو مجتمعك الكنسي، وقل له كلمة امتنان.\"},{\"t\":\"أرح أباك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أرسانيوس لتلميذه: أرح أباك حتى إنه عندما ينتقل إلى الرب يصلي من أجلك لكي يأتيك الخير. براءة الأسرة تظهر في راحة الآباء. أرح اليوم أبًا أو أمًّا بكلمة أو خدمة.\",\"p\":\"يا رب، علّمني أن أريح والديّ وأكرمهما. بارك صلواتهما من أجلي. آمين.\",\"x\":\"قال القديس أرسانيوس لتلميذه: أرح أباك حتى إنه عندما ينتقل إلى الرب يصلي من أجلك لكي يأتيك الخير. راحة الأب بركة. تدريب: أرح والدك اليوم بعمل أو كلمة.\",\"fq\":40}]},\"10-22\":{\"th\":\"اثنان خير من واحد\",\"m\":[{\"t\":\"سلام عظيم\",\"ref\":\"المزمور ١١٨ — الجزء الحادي والعشرون («كُونوا مُستَعِدّينَ، لأنَّهُ في ساعَةٍ لا تَظُنّونَ يَأتي ابنُ الإنسان.») — الستار\",\"v\":\"فليكن سلام عظيم للذين يحبون اسمك.\",\"r\":\"سلام عظيم للذين يحبون اسم الرب. اثنان خير من واحد حين يجمعهما سلام ومحبة. قدّم اليوم لشريك حياتك أو لأحد المقربين كلمة سلام وشكر.\",\"p\":\"يا رب، ليكن سلام عظيم بين الذين يحبون اسمك. بارك رباط المحبة بين المتحدين. آمين.\",\"x\":\"سلام عظيم للذين يحبون اسم الرب. اثنان خير من واحد إذا جمعهما السلام. تدريب: قدم لشريك حياتك أو لمن تقرب منه كلمة تقدير.\"},{\"t\":\"اثنان خير من واحد\",\"ref\":\"الجامعة ٤: ٩\",\"bk\":\"الجامعة\",\"v\":\"اثنان خير من واحد، لأن لهما أجرة لتعبهما صالحة.\",\"r\":\"«اثنان خير من واحد، لأن لهما أجرة لتعبهما صالحة». أحمل أثقالي وحدي كثيرًا، لكن الشركة تخفف الحمل. وهذه الحكمة تنطبق على الزواج والخدمة والصداقة. فلأسمح لأحد أن يشاركني تعبي.\",\"p\":\"يا رب، علمني ألا أحمل أثقالي وحدي. اجعل لي رفيقًا أمينًا في الجهاد، وبارك كل شركة تبني ملكوتك. آمين.\",\"x\":\"الحكيم في الجامعة رأى الإنسان الوحيد الذي يتعب بلا نهاية ولا يشبع من الغنى، فخلص إلى أن الشركة خير. وتعلمنا الكنيسة الاشتراك في العمل: الخدمة جماعية، والصلاة جماعية. وقد أرسل الرب تلاميذه اثنين اثنين. والشريك يسند ويصحح ويشجع. ولذلك ينصح الآباء بأن يكون للمؤمن أب روحي وأخ في الجهاد. ومن يتعب وحده يسقط سريعًا.\\nاطلب اليوم مساعدة في عمل يثقلك، ولا تفعله وحدك.\"},{\"t\":\"لا تثقل الحرب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي الأب بيمن: إذا رأيت مشاهد وسمعت أنباء مهما كانت لا تنقلها لقريبك لأن هذا من شأنه أن يثقل الحرب عليه. الاثنان معًا يحمل أحدهما حمل الآخر. احتفظ اليوم بخبر مزعج لا يفيد، ولا تنقله.\",\"p\":\"يا رب، علّمني أن أخفف عن أخي لا أثقل عليه. اجعل كلامي سلامًا. آمين.\",\"x\":\"يوصي الأب بيمن: إذا رأيت مشاهد وسمعت أنباء مهما كانت لا تنقلها لقريبك لأن هذا يثقل الحرب عليه. الاثنان يحتاجان إلى سلام. تدريب: لا تنقل اليوم خبرًا يزعج.\",\"fq\":415}]},\"10-23\":{\"th\":\"المحبة والاحترام\",\"m\":[{\"t\":\"بمجد وبهاء كلّلته\",\"ref\":\"المزمور الثامن (من صلاة باكر) — الستار\",\"v\":\"نَقَصْتَهُ قَليلًا عَنِ الملائكة، وبمَجدٍ وبَهاءٍ كَلَّلتَه. وأقَمتَهُ على أعمالِ يَدَيك، وأخضَعتَ كُلَّ شَيءٍ تحتَ قَدَمَيه.\",\"r\":\"الله كلّل الإنسان بالمجد والبهاء وأقامه على أعمال يديه. هذا المجد يستحق الاحترام، ويظهر في العلاقة بين الزوجين والأسرة. أظهر اليوم احترامك لشخص قريب منك بكلمة تقدير.\",\"p\":\"يا رب، أشكرك لأنك كلّلتنا بالمجد والكرامة. علّمني أن أكرم من تعطيني إياهم من أسرتي. آمين.\",\"x\":\"كلل الله الإنسان بالمجد والبهاء، وهذا المجد يستحق الاحترام. تدريب: عامل كل من تقابله اليوم كمن كلله الله بمجد.\"},{\"t\":\"ليحب كل واحد امرأته\",\"ref\":\"أفسس ٥: ٣٣\",\"bk\":\"أفسس\",\"v\":\"وأما أنتم الأفراد، فليحب كل واحد امرأته هكذا كنفسه، وأما المرأة فلتهب رجلها.\",\"r\":\"«ليحب كل واحد امرأته هكذا كنفسه، وأما المرأة فلتهب رجلها». المحبة والاحترام ركنان متكاملان. لا تعيش المحبة بلا احترام، ولا يستقيم الاحترام بلا محبة. وأنا أراجع كيف أعبر عن الاثنين في بيتي.\",\"p\":\"يا رب، علمنا المحبة التي بذلت نفسك لأجلها والاحترام الذي يتواضع. اجعل بيوتنا صورة لعلاقتك بكنيستك. آمين.\",\"x\":\"هذا في ختام مقطع أفسس ٥ الذي يقارن الزواج بعلاقة المسيح بالكنيسة. فالرجل يحب كما أحب المسيح وبذل نفسه، والمرأة تحترم كما تحترم الكنيسة المسيح. والخضوع المتبادل يسبق ذلك في الآية ٢١: «خاضعين بعضكم لبعض في خوف الله». أي أن الأساس هو الاتضاع المتبادل. وعظم الغاية: صورة المسيح والكنيسة. والمشكلات الأسرية كثيرًا ما تنبع من اختلال هذين الركنين.\\nاليوم عبّر عن محبتك أو احترامك لشريكك أو لأحد في أسرتك بكلمة صادقة وفعل بسيط.\"},{\"t\":\"كلمة عفوًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ثيوذورس: لقد فقد الرهبان أدبهم عندما تخلوا عن كلمة «عفوًا». الاحترام يبدأ بكلمات صغيرة مثل عفوًا وشكرًا. قل اليوم هاتين الكلمتين لأقرب الناس إليك.\",\"p\":\"يا رب، علّمني أدب المحبة. اجعل لساني مهذبًا مع أسرتي أكثر من الغرباء. آمين.\",\"x\":\"يقول الأب ثيوذورس: لقد فقد الرهبان أدبهم عندما تخلوا عن كلمة عفوًا. الأدب كلمات صغيرة. تدريب: استعمل اليوم عفوًا وشكرًا في كل موقف.\",\"fq\":133}]},\"10-24\":{\"th\":\"بيت مبني بالحكمة\",\"m\":[{\"t\":\"احفظني يا رب\",\"ref\":\"المزمور الخامس عشر — باكر\",\"v\":\"احفظني يا رب فإني عليك توكلت. قلت للرب: أنت ربي.\",\"r\":\"يقول المرنم: احفظني يا رب فإني عليك توكلت. قلت للرب أنت ربي. البيت يبنى بحكمة حين يكون الرب سيده. قرر اليوم أن تجعل الصلاة المشتركة جزءًا ثابتًا من يوم أسرتك.\",\"p\":\"يا رب، احفظ بيتي فإني عليك توكلت. أنت ربي، فابنِ بيتي بحكمتك. آمين.\",\"x\":\"احفظني يا رب فإني عليك توكلت، قلت للرب أنت ربي. البيت يبنى بحكمة حين يكون الرب سيده. تدريب: قل لله اليوم في بيتك: أنت ربي.\"},{\"t\":\"حكمة المرأة تبني بيتها\",\"ref\":\"الأمثال ١٤: ١\",\"bk\":\"الأمثال\",\"v\":\"حكمة المرأة تبني بيتها، والحماقة تهدمه بيدها.\",\"r\":\"«حكمة المرأة تبني بيتها، والحماقة تهدمه بيدها». بناء البيت أو هدمه يحدث بقرارات صغيرة يومية: كلمة، موقف، صبر. وأنا مسؤول عن أن أكون من البنائين لا الهادمين، مهما كان دوري في الأسرة.\",\"p\":\"يا رب، اجعلني بانيًا لبيتي بحكمتك. احفظني من الكلمات والتصرفات التي تهدم، وامنحني صبرًا وحكمة. آمين.\",\"x\":\"تصور الأمثال البيت كبناء يحتاج صاحب حكمة. والحكمة هنا عملية: ضبط اللسان، وحسن التدبير، والصبر على الاختلاف. والحماقة تهدم بالأيدي، أي بتصرفات واعية. وهذا ينطبق على كل أفراد البيت. وتتحدث الأمثال في آخرها عن المرأة الفاضلة، وهي مثال للحكمة العملية. ويمكن أن نقرأ هنا أن الكنيسة نفسها «بيت» تبنيه الحكمة والصلاة. وتبدأ الحكمة بمخافة الرب.\\nاختر اليوم تصرفًا واحدًا يبني بيتك، كأن تساعد في عمل أو تقدم كلمة تشجيع.\"},{\"t\":\"مكتفٍ في كل شيء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يصف الراوي الأب أغاثون بأنه حكيم في التفكير، عديم التعب في الجسد، مكتفٍ في كل شيء، في العمل والمأكل والملبس. بيت الحكمة بيت القناعة. اكتف اليوم بقرار شراء واحد أقل مما كنت تنوي.\",\"p\":\"يا رب، اجعل بيتي بيت قناعة وشكر. علّمني الاكتفاء الذي يبني. آمين.\",\"x\":\"وُصف الأب أغاثون بأنه حكيم في التفكير، عديم التعب في الجسد، مكتف في كل شيء في العمل والمأكل والملبس. بيت الحكمة يكتفي. تدريب: اكتفِ اليوم بما عندك.\",\"fq\":51}]},\"10-25\":{\"th\":\"البنون ميراث من الرب\",\"m\":[{\"t\":\"مغبوط الرجل\",\"ref\":\"المزمور ١٢٦ (١٢٧) — الغروب\",\"v\":\"مغبوط هو الرجل الذي يملا جعبته منهم. حينئذ لا يخزون إذا كلموا أعداءهم في الأبواب هلليلويا.\",\"r\":\"يشبّه المرنم البنين بالسهام، ومغبوط من يملأ جعبته منها، فلا يخزى حين يكلم أعداءه. البنون عطية من الرب ومسؤولية بيد الوالدين. اقض اليوم وقتًا مع طفل بلا هاتف.\",\"p\":\"يا رب، البنون ميراث منك. بارك أبنائي وعلّمني أن أربيهم لك. آمين.\",\"x\":\"البنون كالسهام في يد الجبار، ومغبوط من يملأ جعبته منها. هم عطية ومسؤولية. تدريب: صلِّ اليوم لأولادك بالاسم، وإن لم يكن لك أبناء فلمن ترعاهم روحيًا.\"},{\"t\":\"البنون ميراث\",\"ref\":\"المزامير ١٢٧: ٣\",\"bk\":\"المزامير\",\"v\":\"هوذا البنون ميراث من عند الرب، ثمرة البطن أجرة.\",\"r\":\"«هوذا البنون ميراث من عند الرب، ثمرة البطن أجرة». أولادي ليسوا ملكي، بل عطية أؤتمن عليها. وهذا يعطيني مسؤولية وتواضعًا معًا: أعتني بهم لله، وأصلي لهم، ولا أحمل عليهم تحقيق أحلامي.\",\"p\":\"يا رب، أشكرك على عطية الأولاد. احفظهم في إيمانك، وعلمني أن أرعاهم كأمانة منك لا كملك لي. آمين.\",\"x\":\"المزمور ١٢٧ يبدأ: «إن لم يبن الرب البيت فباطلًا يتعب البناؤون». وهو مزمور لسليمان يربط بين بناء البيت وعطية الأولاد. فالبناء الحقيقي بيد الله. والولد «ميراث»، أي ما يُسلَّم لنا من الله. وتعلمنا الكنيسة أن نقدم أولادنا للمعمودية في سن مبكرة، تعبيرًا عن أنهم لله. وفي الأحد، نأتي بهم إلى القداس ومدارس الأحد لتغرس فيهم الإيمان.\\nاليوم، صلِّ لأولادك أو لأي أطفال تخدمهم بالاسم، وسلمهم بين يدي الله.\"},{\"t\":\"ما لم أفعله أنا\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوحنا رئيس الدير في وداعه: لم أفعل مرة مشيئتي، كما أنني لم أعلّم أحدًا ما لم أفعله أنا أولًا. التربية بالقدوة قبل الكلام. اسأل نفسك اليوم: ما الذي أطلبه من أبنائي ولا أفعله أنا؟\",\"p\":\"يا رب، اجعل حياتي معلمة قبل كلامي. علّمني أن أفعل أولًا ما أعلّمه. آمين.\",\"x\":\"قال الأب يوحنا رئيس الدير عند رحيله: لم أفعل مرة مشيئتي كما أنني لم أعلّم أحدًا ما لم أفعله أنا أولًا. التربية بالقدوة. تدريب: لا تطلب اليوم من ابنك ما لا تفعله.\",\"fq\":213}]},\"10-26\":{\"th\":\"إكرام الوالدين\",\"m\":[{\"t\":\"كلامك حق\",\"ref\":\"المزمور ١١٨ — الجزء العشرون («كُونوا مُستَعِدّينَ، لأنَّهُ في ساعَةٍ لا تَظُنّونَ يَأتي ابنُ الإنسان.») — الستار\",\"v\":\"بد، كلامك حق، وإلى الأبد كل أحكام عدلك. هلليلويا.\",\"r\":\"كلامك حق وإلى الأبد كل أحكام عدلك. إكرام الوالدين وصية بوعد، وهو أول الوصايا الاجتماعية. اتصل اليوم بأبيك أو أمك، أو قدّم لهما خدمة.\",\"p\":\"يا رب، علّمني الإكرام لوالديّ كما أوصيتني. بارك أيامهما وأعطني أن أكون لهما سندًا. آمين.\",\"x\":\"كلامك حق وكل أحكام عدلك إلى الأبد. إكرام الوالدين وصية بوعد. تدريب: اتصل اليوم بأبيك أو أمك واشكرهما.\"},{\"t\":\"وصية بوعد\",\"ref\":\"الخروج ٢٠: ١٢\",\"bk\":\"الخروج\",\"v\":\"أكرم أباك وأمك لكي تطول أيامك على الأرض التي يعطيك الرب إلهك.\",\"r\":\"«أكرم أباك وأمك لكي تطول أيامك». الإكرام ليس مجرد طاعة طفل، بل احترام يستمر طوال العمر. ومهما كبرت أحتاج أن أكرمهما بالزيارة والصلاة والاهتمام. وهذه الوصية لها بركة وعد.\",\"p\":\"يا رب، علمني أن أكرم أبي وأمي بحق. احفظهما واعطهما صحة وسلامًا، وأعطني قلبًا شاكرًا لهما. آمين.\",\"x\":\"الوصية الخامسة هي همزة الوصل بين وصايا محبة الله ووصايا محبة الناس. فالأب والأم أول من يمثل سلطة الله للإنسان. ويربط بولس هذه الوصية بوعد: «لكي يكون لك خير وتكون طويل العمر». والإكرام يشمل الاستماع والعناية عند الشيخوخة. وهو مصدر بركة للأجيال. وقد قدّم لنا الرب مثالًا في تسليمه أمه ليوحنا على الصليب.\\nاتصل اليوم بوالدك أو والدتك، أو أحد كبار عائلتك، واسأل عن صحتهم وصلِّ لهم.\"},{\"t\":\"كآباء وكرؤساء\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس: يجب على التلاميذ أن يحبوا المعلمين الحقيقيين كآباء وأن يخافوهم كرؤساء، فلا يسقطون الخوف بداعي المحبة ولا يزيلون المحبة بداعي الخوف. الإكرام يجمع الحب والهيبة. أظهر اليوم احترامًا لمن له سلطة عليك.\",\"p\":\"يا رب، علّمني الحب والهيبة معًا. أعطني أن أكرم كل من وضعتهم في حياتي أبوة لي. آمين.\",\"x\":\"يقول الأب إيسيذورس: يجب على التلاميذ أن يحبوا المعلمين الحقيقيين كآباء وأن يخافوهم كرؤساء، فلا يسقطون الخوف بداعي المحبة ولا يزيلون المحبة بداعي الخوف. تدريب: وازن اليوم بين محبتك واحترامك.\",\"fq\":201}]},\"10-27\":{\"th\":\"تربية الأجيال\",\"m\":[{\"t\":\"من أفواه الأطفال\",\"ref\":\"المزمور الثامن (من صلاة باكر) — الستار\",\"v\":\"مِن أفواهِ الأطفالِ والرُّضَّعِ أسَّسْتَ حَمدًا، بِسَبَبِ أضدادِكَ، لِتُسَكِّتَ العَدُوَّ والمُنتَقِم.\",\"r\":\"من أفواه الأطفال والرضع أسس الرب حمدًا. تربية الأجيال تبدأ بأن يسمع الأطفال تسبيحنا ويقلدوه. رتّل اليوم مع طفل ترنيمة بسيطة، أو صلِّ معه صلاة قصيرة.\",\"p\":\"يا رب، من أفواه الأطفال أسست حمدًا. اجعل بيتي مدرسة تسبيح لأطفالي. آمين.\",\"x\":\"من أفواه الأطفال والرضع أسس الرب حمدًا. الأطفال يتعلمون التسبيح من سماعنا. تدريب: رتل اليوم مع طفل ترنيمة قصيرة.\"},{\"t\":\"لئلا يفشلوا\",\"ref\":\"كولوسي ٣: ٢١\",\"bk\":\"كولوسي\",\"v\":\"أيها الآباء، لا تغيظوا أولادكم لئلا يفشلوا.\",\"r\":\"«أيها الآباء، لا تغيظوا أولادكم لئلا يفشلوا». التربية بالقسوة تنتج إحباطًا. والأولاد يحتاجون إلى توجيه بحب وصبر. وأنا أسأل نفسي: هل أبني ثقة من أخدمهم أم أحطمها بكلماتي وتوقعاتي؟\",\"p\":\"يا رب، علمني أن أربي بالمحبة والصبر. احفظني من الغضب مع الصغار، واجعل كلمتي تبني فيهم الثقة والإيمان. آمين.\",\"x\":\"الكلمة اليونانية «يفشلوا» تعني يفقدوا الهمة والنشاط. فالتربية القاسية تطفئ حماس الصغير. ويستخدم بولس في أفسس تعبيرًا قريبًا: «ربوهم بتأديب الرب وإنذاره». أي أن التأديب بروح المسيح لا بروح الغضب. وهذه الوصية مهمة للمعلمين في مدارس الأحد أيضًا. فالطفل يتعلم من حضور المعلم وطريقته أكثر مما يتعلم من كلماته. والحنان أقوى مؤثر.\\nاليوم، شجع طفلًا أو شابًا على نجاح صغير، وقل له إنك فخور به.\"},{\"t\":\"أعمل عملي صامتًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"تعلم الأب إسحق من الأب كرونيو الصامت أن يسرع إلى الأعمال التي ينويها، وقال: هذا علمني أن أقوم بعملي صامتًا. الصمت العملي يربي أكثر من الخطب. اعمل اليوم أمام أطفالك الصلاح الذي تريدهم أن يتعلموه.\",\"p\":\"يا رب، علّمني أن أربي بالصمت العامل. اجعل أعمالي كلمة صالحة لأبنائي. آمين.\",\"x\":\"تعلم الأب إسحق من الأب كرونيو الصامت ألا يطلب منه خدمة فكان يسرع إلى الأعمال التي ينويها، وقال: هذا علمني أن أقوم بعملي صامتًا. التربية تعلم بالصمت. تدريب: قم اليوم بعمل في البيت قبل أن يُطلب منك.\",\"fq\":177}]},\"10-28\":{\"th\":\"دعوا الأولاد يأتون\",\"m\":[{\"t\":\"أم أولاد فرحة\",\"ref\":\"المزمور ١١٢ (١١٣) — باكر\",\"v\":\"الذي يجعل العاقر ساكنة في بيت، أم أولاد فرحة.\",\"r\":\"الله يجعل العاقر ساكنة في بيت أمًّا فرحة بأولادها. الطفل في عين الله عظيم، وهو الذي قال دعوا الأولاد يأتون إلي. أنصت اليوم لطفل بانتباه كامل، دون أن تقاطعه.\",\"p\":\"يا رب، أشكرك على الأطفال وعلى تواضعهم. اجعل بيوتنا فرحة بهم، وعلّمني أن أقبلهم كما قبلتهم. آمين.\",\"x\":\"الله يجعل العاقر ساكنة في بيت أمًّا فرحة. الطفل في عين الله عظيم. تدريب: صلِّ لعائلة تنتظر طفلًا.\"},{\"t\":\"دعوا الأولاد يأتون إلي\",\"ref\":\"مرقس ١٠: ١٤\",\"bk\":\"مرقس\",\"v\":\"فلما رأى يسوع ذلك اغتاظ وقال لهم: «دعوا الأولاد يأتون إلي ولا تمنعوهم، لأن لمثل هؤلاء ملكوت الله.\",\"r\":\"«دعوا الأولاد يأتون إليّ ولا تمنعوهم، لأن لمثل هؤلاء ملكوت الله». المسيح يغتاظ حين يُعاق الصغار عن القرب منه. فلا أضع عوائق أمامهم من تعقيد أو ملل أو قسوة. بل أسهّل لهم الطريق إليه.\",\"p\":\"يا رب يسوع، أنت تحب الصغار. ساعدني لا أكون عائقًا لهم، بل باب محبة يقودهم إليك بسهولة وفرح. آمين.\",\"x\":\"يذكر مرقس أن الرب «اغتاظ»، وهي من القليل من الكلمات التي تعبّر عن انفعاله. فهو يدافع عن الصغار الذين اعتبرهم التلاميذ مزعجين. وفي الكنيسة نرى الأطفال في مدارس الأحد والقداسات والتناول. ويؤكد الآباء أن للصغير موهبة الإيمان البسيط. والخدمة بينهم أمانة عظيمة. فالمسيح يحتضنهم ويباركهم، وهذا نموذج لكل خادم.\\nاليوم، رحب بطفل في كنيستك بالاسم، واجعل لقاءك به لطيفًا وفرحًا.\"},{\"t\":\"كن قدوة\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب بيمن لمن سأل عن الإخوة المقيمين معه: كن قدوة في كل شيء وليس مشرّعًا. الأطفال يتعلمون من سلوكنا لا من لوائحنا. اجعل اليوم تصرفك القدوة لا الأوامر.\",\"p\":\"يا رب، اجعلني قدوة صالحة لأولادي وللصغار. اكتب فيّ ما أريد أن يقرؤوه. آمين.\",\"x\":\"لأخ سأل عن الإخوة المقيمين معه قال الأب بيمن: كن قدوة في كل شيء وليس مشرّعًا. الصغار يتعلمون من السلوك. تدريب: كن قدوة اليوم بلا وعظ.\",\"fq\":443}]},\"10-29\":{\"th\":\"الوفاء والمسؤولية\",\"m\":[{\"t\":\"أوفي نذوري يومًا فيوم\",\"ref\":\"المزمور ٦٠ (٦١) — السادسة\",\"v\":\"هكذا أرتل لاسمك إلى دهر الدهور، لأفي نذوري يوما فيوما.\",\"r\":\"يرتل المرنم لاسم الرب إلى دهر الدهور ليفي نذوره يومًا فيوم. الوفاء الحقيقي بقاء الإنسان مع من التزم بهم كما فعلت راعوث. أوف اليوم بوعد صغير تأخرت فيه.\",\"p\":\"يا رب، أوفي لك نذوري. علّمني الوفاء في الصغير والكبير، وأعطني أن أبقى أمينًا لمن ارتبطت بهم. آمين.\",\"x\":\"أرتل لاسمك ليوفي نذوري يومًا فيومًا. الوفاء التزام يومي. تدريب: وفِّ اليوم بوعد صغير قطعته.\"},{\"t\":\"حيثما ذهبت أذهب\",\"ref\":\"راعوث ١: ١٦\",\"bk\":\"راعوث\",\"v\":\"فقالت راعوث: «لا تلحي علي أن أتركك وأرجع عنك، لأنه حيثما ذهبت أذهب وحيثما بت أبيت. شعبك شعبي وإلهك إلهي.\",\"r\":\"«لا تلحي عليّ أن أتركك وأرجع عنك، لأنه حيثما ذهبت أذهب… شعبك شعبي وإلهك إلهي». الوفاء ليس مشاعر بل قرار. وراعوث اختارت الله والرفقة في وقت المرارة. وأنا أتعلم الوفاء لأهلي وكنيستي حتى في زمن الصعوبة.\",\"p\":\"يا رب، علمني الوفاء كما فعلت راعوث. اجعلني أمينًا لأهلي وكنيستي وشعبك، وثبتني بجوار من يحتاجني في ضيقه. آمين.\",\"x\":\"راعوث الموآبية تركت أهلها وإلهها لتتبع نعمي في الغربة والفقر، ولأجل ذلك باركها الله فصارت جدة داود وفي نسب المسيح. وقولها إعلان إيمان: «إلهك إلهي». ففي الوفاء للإنسان إيمان بالله. وقد اعتبر الآباء راعوث رمزًا لدخول الأمم إلى الكنيسة. وهي أيضًا نموذج للمرأة الأمينة. والوفاء في العلاقات يشمل الحضور والمشاركة والصبر.\\nاليوم، قم بعمل وفاء لشخص يمر بصعوبة: زيارة أو مساعدة، ولا تنتظر مقابلًا.\"},{\"t\":\"ثمن واحد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يعلّم الأب بيستامون من ينزعج وهو يبيع عمل يديه: قل ثمن السلال مرة واحدة فقط، وإن رغبت في تخفيضه فهذا لك، وبهذا تجد راحة. الأمانة في المعاملة تريح القلب. كن اليوم صريحًا وصادقًا في كل تعامل مالي.\",\"p\":\"يا رب، علّمني الصدق في كل أخذ وعطاء. اجعل كلمتي واحدة وذمتي نقية. آمين.\",\"x\":\"لأخ ينزعج وهو يبيع عمل يديه قال الأب بيستامون: قل ثمن السلال مرة واحدة فقط، وإن رغبت في تخفيضه فهذا لك، وبهذا تجد راحة. الأمانة ببساطة. تدريب: قل ما عندك بصدق مرة واحدة ولا تساوم.\",\"fq\":470}]},\"10-30\":{\"th\":\"البيت المبارك\",\"m\":[{\"t\":\"بظل جناحيك أبتهج\",\"ref\":\"المزمور ٦٣ — باكر\",\"v\":\"كنت أذكرك على فراشي. وفي أوقات الأسحار كنت أرتل لك. لأنك صرت لي عونا، وبظل جناحيك أبتهج.\",\"r\":\"يذكر المرنم الله على فراشه ويرتل له في الأسحار، فصار الله عونًا وبظل جناحيه يبتهج. البيت المبارك بيت يذكر الله في الصباح والمساء. ابدأ اليوم صلاة قصيرة مع أسرتك قبل النوم.\",\"p\":\"يا رب، كن عوني وبظل جناحيك أبتهج. بارك بيتنا وعلّمنا أن نذكرك مساءً وصباحًا. آمين.\",\"x\":\"يذكر المرنم الله على فراشه ويرتل له في الأسحار فصار الله عونًا. البيت المبارك بيت يذكر الله. تدريب: أنهِ يوم أسرتك بصلاة قصيرة مشتركة.\"},{\"t\":\"رجل المرأة الصالحة مغبوط\",\"ref\":\"يشوع بن سيراخ ٢٦: ١\",\"bk\":\"يشوع بن سيراخ\",\"v\":\"رجل المرأة الصالحة مغبوط وعدد أيامه مضاعف\",\"r\":\"«رجل المرأة الصالحة مغبوط، وعدد أيامه مضاعف». حضور شريك صالح يضاعف الفرح والسلام. وأنا أشكر الله على من أعطاني، وأطلب أن أكون أنا أيضًا مصدر خير وسلام لمن يشاركني الحياة.\",\"p\":\"يا رب، أشكرك على نعمة الأسرة الصالحة. بارك كل بيت، واجعل أزواجنا وزوجاتنا مصدر بركة وسلام. آمين.\",\"x\":\"يخصص ابن سيراخ أصحاحًا للمرأة الصالحة والمرأة الشريرة، وهو يعبّر عن واقع زمانه بأسلوب الحكمة. وهنا يحتفي بالزوجة الصالحة. ويذكّر بأن الزوجين يشاركان بعضهما البركة. وتعلّم الكنيسة أن الزواج طريق قداسة لكلا الطرفين. وقد جاهد زوجان قديسان مثل القديس يواقيم والقديسة حنة، والدا العذراء، بحياة تقوى. فالبيت المبارك يتحول إلى كنيسة صغيرة.\\nاكتب اليوم رسالة تقدير قصيرة لشريك حياتك أو لأحد والديك أو أحد أفراد أسرتك.\"},{\"t\":\"كنا نعيش بسلام\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب رومانوس عند رحيله: لا أذكر أني طلبت من أحدكم شيئًا دون التفكير به قبل طلبه، وهكذا كنا نعيش بسلام كل زمان حياتنا. السلام في البيت ثمرة التفكير قبل الطلب. فكر اليوم قبل أن تطلب من أحد أفراد أسرتك طلبًا.\",\"p\":\"يا رب، اجعل بيتنا بيت سلام. علّمنا أن نفكر قبل أن نطلب ونتكلم. آمين.\",\"x\":\"قال الأب رومانوس عند رحيله: لا أذكر أني طلبت من أحدكم شيئًا دون التفكير به قبل طلبه، وهكذا كنا نعيش بسلام. السلام ثمرة التفكير قبل الطلب. تدريب: فكر قبل أن تطلب اليوم.\",\"fq\":483}]},\"10-31\":{\"th\":\"أمانة الأجيال\",\"m\":[{\"t\":\"أمر بعهده إلى الأبد\",\"ref\":\"المزمور ١١٠ (١١١) — التاسعة\",\"v\":\"كل وصاياه صادقة. ثابتة إلى دهر الدهور، مصنوعة بالحق والاستقامة. أرسل خلاصا لشعبه. أمر بعهده إلى الأبد.\",\"r\":\"كل وصايا الله صادقة وثابتة إلى دهر الدهور، وقد أمر بعهده إلى الأبد. أمانة الأجيال أن ننقل هذا العهد من جيل إلى جيل. اكتب اليوم اسم من علّمك الإيمان، واشكر الله عليه، وفكر فيمن تعلّمه أنت.\",\"p\":\"يا رب، وصاياك ثابتة وعهدك أبدي. اجعل أمانتنا تسلم الإيمان لمن بعدنا. آمين.\",\"x\":\"كل وصاياه صادقة ثابتة إلى دهر الدهور، وقد أمر بعهده إلى الأبد. أمانة الأجيال أن ننقل العهد. تدريب: انقل اليوم لابن أو صغير آية أو قصة عن إيمانك.\"},{\"t\":\"أخبروا بنيكم عنه\",\"ref\":\"يوئيل ١: ٣\",\"bk\":\"يوئيل\",\"v\":\"أخبروا بنيكم عنه، وبنوكم بنيهم، وبنوهم دورا آخر.\",\"r\":\"«أخبروا بنيكم عنه، وبنوكم بنيهم، وبنوهم دورًا آخر». لا أعيش إيماني لنفسي فقط. إنه أمانة أنقلها. وأتساءل: ماذا أخبر به أولادي وأحفادي عن الله؟ وهل يرون في حياتي ما يثبت كلامي؟\",\"p\":\"يا رب، اجعلني شاهدًا لك أمام أولادي وأحفادي. علمني أن أنقل لهم ما اختبرته من أمانتك، ليثبتوا فيك. آمين.\",\"x\":\"يقول يوئيل هذا بعد كارثة الجراد التي حلت بالأرض، فكأنه يقول إن الأحداث الصعبة تصير شهادات يجب أن تُنقل. وفي كنيستنا نحيي ذكرى آلام الاستشهاد والاضطهاد لنحكي لأولادنا كيف ثبت الآباء. وكذلك نحكي قصص معجزات الله معنا. وهذا النقل يبني هوية الأجيال. ويصبح الإيمان إرثًا حيًا. والجيل الذي لا يسمع الحكاية ينسى.\\nاحك اليوم لأحد الصغار قصة عن لحظة اختبرت فيها عمل الله في حياتك.\"},{\"t\":\"انظروا سلوكي\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب إسحق لآبائه عند رحيله: انظروا كيف كان سلوكي بينكم، فإذا أردتم أن تتبعوني احفظوا وصايا الله وهو يرسل نعمته. هذا ميراث الأجيال. اجعل سلوكك اليوم رسالة لمن يتبعك.\",\"p\":\"يا رب، اجعل حياتي رسالة أمانة. علّمني أن أحفظ وصاياك لتحفظ نعمتك من بعدي. آمين.\",\"x\":\"قال الأب إسحق لآبائه عند رحيله: انظروا كيف كان سلوكي بينكم، فإذا أردتم أن تتبعوني احفظوا وصايا الله وهو يرسل نعمته ويحفظ هذا المكان. تدريب: كن مثالًا يُحتذى به اليوم.\",\"fq\":181}]},\"11-1\":{\"th\":\"صرخة من الهاوية\",\"m\":[{\"t\":\"من الأعماق صرخت\",\"ref\":\"المزمور ١٢٩ (١٣٠) — النوم\",\"v\":\"من الأعماق صرخت إليك يا رب؛ يا رب استمع صوتي. لتكن أذناك مصغيتين إلى صوت تضرعي.\",\"r\":\"صرخ المرنم من الأعماق، وصرخ يونان من جوف الحوت، والله سمع في الحالتين. لا يوجد عمق يمنع الصوت من الوصول إليه. اصرخ اليوم إلى الرب من موضع الضيق الذي تعرفه، بكلمات قليلة وصادقة.\",\"p\":\"يا رب، من الأعماق صرخت إليك. لتكن أذناك مصغيتين إلى صوت تضرعي، وأخرجني من حيث أنا. آمين.\",\"x\":\"صرخ المرنم من الأعماق وصرخ يونان من جوف الحوت، والله سمع في الحالتين. لا عمق يمنع الصوت من الوصول. تدريب: قل لله من أعمق نقطة في ضعفك: استمع صوتي.\"},{\"t\":\"دعوت من ضيقي فاستجابني\",\"ref\":\"يونان ٢: ٢\",\"bk\":\"يونان\",\"v\":\"وقال: «دعوت من ضيقي الرب، فاستجابني. صرخت من جوف الهاوية، فسمعت صوتي.\",\"r\":\"«دعوت من ضيقي الرب فاستجابني. صرخت من جوف الهاوية فسمعت صوتي». لا يوجد مكان أسفل من أن يصل إليه صوتي. وحتى لو كانت ضيقتي بسبب عنادي كما كان مع يونان، فإن الرب يسمع صرخة العودة.\",\"p\":\"يا رب، أنت تسمع من الهاوية. اسمع صرختي في ضيقي، وارفعني بيدك كما رفعت يونان، وأعطني أن أشكرك قبل أن أرى الخلاص. آمين.\",\"x\":\"صلاة يونان في الأصحاح الثاني مزمور شكر ينشده وهو في الحوت، قبل أن يخرج منه. أي أنه يشكر قبل أن يرى الخلاص. وهذا هو الإيمان. وقد جعل الرب يسوع آية يونان علامة لموته ودفنه وقيامته في اليوم الثالث. فصرخة يونان من الهاوية تتحقق كاملة في المسيح الذي نزل إلى الجحيم وقام. ولذلك تقرأ الكنيسة صلاة يونان في ليلة سبت الفرح. وهي تعلمنا أن الله يسمع من العمق.\\nاذكر اليوم موقفًا ضاق عليك فيه الحال ثم جاء الفرج، وارفع شكرًا للرب عليه.\"},{\"t\":\"جدار مظلم\",\"ref\":\"\",\"v\":\"\",\"r\":\"زار أخ الأب أموي طالبًا كلمة، وبعد سبعة أيام من الصمت قال له: اذهب وانتبه لنفسك، أما أنا فخطاياي قد صارت جدارًا مظلمًا بيني وبين الله. من يرى جدار خطيته يصرخ إلى الله من الأعماق. سمّ اليوم الجدار الذي يفصلك، وارفعه إلى الله.\",\"p\":\"يا رب، اهدم الجدار الذي أقمته بخطاياي بيني وبينك. اسمع صراخي من الأعماق وقرّبني إليك. آمين.\",\"x\":\"زار أخ الأب أموي طالبًا كلمة، وبعد سبعة أيام من الصمت قال له: اذهب وانتبه لنفسك، أما أنا فخطاياي قد صارت جدارًا مظلمًا بيني وبين الله. من يرى خطيته لا ينشغل بغيره. تدريب: انتبه اليوم لنفسك ولا تعلّق على أحد.\",\"fq\":66}]},\"11-2\":{\"th\":\"ارجعوا إلى الرب\",\"m\":[{\"t\":\"رأفتك كثيرة جدًا يا رب\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء العشرون · صلاة الستار\",\"v\":\"رأفتك كثيرة جدا يا رب. حسب أحكامك أحيني.\",\"r\":\"يتكل المرنم على كثرة رأفة الله ويطلب الحياة حسب أحكامه. الرجوع إلى الرب ليس بقوتنا بل برأفته. ارجع اليوم إلى الرب بخطوة واحدة محددة: اعتراف أو مصالحة أو صلاة.\",\"p\":\"رأفتك كثيرة جدًا يا رب، حسب أحكامك أحيني. أرجعني إليك برحمتك، فأنت الذي ترد من يرجع. آمين.\",\"x\":\"رأفتك كثيرة يا رب، حسب أحكامك أحيني. الرجوع إلى الرب ليس بقوتنا بل برأفته. تدريب: ارجع اليوم لعادة صلاة تركتها، ولو خمس دقائق.\"},{\"t\":\"خذوا معكم كلامًا\",\"ref\":\"هوشع ١٤: ٢\",\"bk\":\"هوشع\",\"v\":\"خذوا معكم كلاما وارجعوا إلى الرب. قولوا له: «ارفع كل إثم واقبل حسنا، فنقدم عجول شفاهنا.\",\"r\":\"«خذوا معكم كلامًا وارجعوا إلى الرب. قولوا له: ارفع كل إثم». لا يطلب الله ذبائح كثيرة بل كلامًا صادقًا من قلب تائب. وأنا أحتاج أن أجهز اعترافي بكلمات واضحة، وأتجنب العموميات.\",\"p\":\"يا رب، علمني كلمات التوبة. ارفع كل إثم واقبل ما هو حسن، وأعطني شجاعة الاعتراف الكامل. آمين.\",\"x\":\"في ختام سفر هوشع، بعد توبيخات كثيرة، يدعو النبي إلى الرجوع ويضع على فم الشعب كلمات الصلاة. فالله لا يترك التائب حائرًا بل يعلمه كيف يصلي. ومن هنا جاء تعبير «عجول شفاهنا»، أي ذبائح التسبيح والاعتراف. وفي كنيستنا، تساعد صلوات التحليل وأجبية التوبة على إيجاد الكلمات. وسر الاعتراف مكان نقول فيه الكلام المسؤول. والمطلوب أن نقول: ارفع كل إثم، لا بعضه.\\nاكتب اليوم اعترافك في ورقة بسيطة مختصرة، واحتفظ بها لتقدمها لأب اعترافك.\"},{\"t\":\"لا يتقيد بوصية\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ثيوذورس الفرمي: إن من يقيم في التوبة لا يتقيد بوصية. التوبة المقيمة حالة قلب مفتوح يقبل كل مشيئة الله. اجعل التوبة اليوم موقفًا لا فعلًا واحدًا: قل لله عند كل خطأ صغير: غفرانك.\",\"p\":\"يا رب، أقمني في التوبة كل أيام حياتي. اجعل قلبي منفتحًا لكل وصاياك. آمين.\",\"x\":\"يقول الأب ثيوذورس الفرمي: إن من يقيم في التوبة لا يتقيد بوصية. أي أن القلب التائب يقبل ما يرسمه الله بلا تذمر. تدريب: اقبل اليوم ما يأتيك كأنه من يد الله.\",\"fq\":136}]},\"11-3\":{\"th\":\"زرع البر وحبل المحبة\",\"m\":[{\"t\":\"توقعت خلاصك\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء الحادي والعشرون · صلاة الستار\",\"v\":\"توقعت خلاصك يا رب ووصاياك أحببتها.\",\"r\":\"يتوقع المرنم خلاص الرب ويحب وصاياه. زرع البر يبدأ بحب الوصية ثم بالعمل بها يومًا بيوم. ازرع اليوم عملًا صغيرًا من البر دون أن تنتظر ثمرًا قريبًا.\",\"p\":\"يا رب، توقعت خلاصك وأحببت وصاياك. ازرع فيّ بذار البر، واربطني بحبال محبتك. آمين.\",\"x\":\"توقعت خلاصك يا رب ووصاياك أحببتها. زرع البر يبدأ بحب الوصية ثم العمل بها يومًا بيوم. تدريب: ازرع اليوم عملًا صغيرًا من وصية، ولا تنتظر ثمره الآن.\"},{\"t\":\"بحبال البشر، بربط المحبة\",\"ref\":\"هوشع ١١: ٤\",\"bk\":\"هوشع\",\"v\":\"كنت أجذبهم بحبال البشر، بربط المحبة، وكنت لهم كمن يرفع النير عن أعناقهم، ومددت إليه مطعما إياه.\",\"r\":\"«كنت أجذبهم بحبال البشر، بربط المحبة، وكنت لهم كمن يرفع النير عن أعناقهم». الله لا يقودني بالقسر بل بالحب. وهو يعلمني كما يعلم الأب طفلًا الخطوات الأولى. وحين أسقط، يحملني. فلا أخاف من الاقتراب إليه.\",\"p\":\"يا أبي الحنون، أمسكتني بذراعيك ولم أعرف. اجذبني بربط محبتك، وارفع عني كل نير ثقيل، واطعمني من يدك. آمين.\",\"x\":\"هوشع ١١ من أحن النصوص في العهد القديم: الله أب يدرج ابنه أفرايم، يمسكه بذراعيه، ويشفيه وهو لا يعرف. والصورة تتحول إلى فلاح يرفع النير عن الثور ويطعمه. وهذه الصور تكشف عن محبة تتحمل الجحود. وتجد صداها في رسالة المسيح الذي قال: «تعالوا إلي يا جميع المتعبين… احملوا نيري». فنيره هين ومحبته تربط. والرب لا يقيد بالقوة.\\nاليوم، ضع نفسك في حضن الله بصلاة قصيرة صامتة، واقبل محبته دون أن تطلب شيئًا.\"},{\"t\":\"ثمار الطاعة\",\"ref\":\"\",\"v\":\"\",\"r\":\"عاد الأب يوحنا الكولوفي بعد ثلاث سنين بثمر العصا اليابسة التي غرسها له أبوه الروحي وأمره أن يسقيها، وقال للإخوة: خذوا كلوا من ثمار الطاعة. الطاعة تثمر حيث لا يُنتظر ثمر. اسق اليوم أمرًا يبدو يابسًا في حياتك بصبر أمين.\",\"p\":\"يا رب، علّمني الطاعة التي تثمر. أعطني صبرًا أسقي به ما يبدو يابسًا حتى يزهر. آمين.\",\"x\":\"بعد ثلاث سنين جاء الأب يوحنا الكولوفي بثمر العصا اليابسة التي غرسها له أبوه الروحي وأمره أن يسقيها، وقال للإخوة: خذوا كلوا من ثمار الطاعة. الطاعة تثمر في اليابس. تدريب: أطع اليوم بلا فهم كامل.\",\"fq\":150}]},\"11-4\":{\"th\":\"تطرح في أعماق البحر\",\"m\":[{\"t\":\"إلى الأبد رحمته\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"ليقل بيت إسرائيل إنه صالح وإن إلى الأبد رحمته.\",\"r\":\"يدعو المرنم أن يقول بيت إسرائيل إن الرب صالح وإلى الأبد رحمته. الله يطرح خطايانا في أعماق البحر ولا يذكرها. اكتب اليوم خطية تاب عنها واعترفت بها، وقل: طرحها الله في العمق.\",\"p\":\"يا رب، أنت صالح وإلى الأبد رحمتك. اطرح خطاياي في أعماق البحر ولا تذكرها. آمين.\",\"x\":\"يطرح الله خطايانا في أعماق البحر ولا يذكرها، والرب صالح وإلى الأبد رحمته. تدريب: اطرح اليوم عليه خطية قديمة اعترفت بها ولا تعد تذكرها.\"},{\"t\":\"تطرح خطاياهم\",\"ref\":\"ميخا ٧: ١٩\",\"bk\":\"ميخا\",\"v\":\"يعود يرحمنا، يدوس آثامنا، وتطرح في أعماق البحر جميع خطاياهم.\",\"r\":\"«يعود يرحمنا، يدوس آثامنا، وتطرح في أعماق البحر جميع خطاياهم». ما غفره الله لا يعود يحاسبني عليه. وأنا أحيانًا أستخرج خطاياي القديمة من أعماق البحر لأوبخ نفسي. فلأتوقف وأثق في غفرانه.\",\"p\":\"يا رب، أشكرك لأنك تدوس آثامي وتطرح خطاياي في أعماق البحر. ثبّتني في غفرانك، ولا تدعني أعود إلى ما قد غفرته. آمين.\",\"x\":\"صورة الأعماق تعني أن الخطايا لا تُسترجع. وهذا يضيء على قول الله في إشعياء: «لا أذكر خطاياك». والغفران عند الله ليس مؤقتًا. وفي المعمودية والتوبة، يمحو الله الحساب. والشيطان يحاول أن يعيدنا إلى الماضي. أما المسيح فيعطينا حاضرًا جديدًا. وتعلمنا الكنيسة أن الندم مفيد لكنه لا يصير سجنًا. فالتوبة تفتح الباب للمستقبل.\\nاليوم، عندما تتذكر خطية مغفورة، قل: «طرحها الله في أعماق البحر»، ولا تعد إليها.\"},{\"t\":\"الكيس خلف الظهر\",\"ref\":\"\",\"v\":\"\",\"r\":\"حمل الأب بيور كيسًا مملوءًا رملًا وراء ظهره، وقال إنه خطاياه الكثيرة، تركها وراءه لئلا يتألم بها، أما خطية أخيه فهي أمامه ينشغل بها إذ يدينه، وهذا لا يليق. من طُرحت خطاياه لا ينظر إلى خطايا الآخرين. ضع اليوم خطاياك أمام عينيك لا خطايا غيرك.\",\"p\":\"يا رب، سامحني على خطاياي الكثيرة واطرحها في العمق. احفظ عيني من النظر إلى خطايا إخوتي. آمين.\",\"x\":\"حمل الأب بيور كيسًا مملوءًا رملًا وراء ظهره وقال إنه خطاياه الكثيرة، تركها وراءه لئلا يتألم بها، أما خطية أخي فهي أمامي أنشغل بها إذ أدينه، ولا يليق أن أفعل هذا. تدريب: لا تحلل أخطاء غيرك اليوم.\",\"fq\":468}]},\"11-5\":{\"th\":\"اذكر الرحمة في الغضب\",\"m\":[{\"t\":\"وحياة في رضاه\",\"ref\":\"المزمور ٢٩ (٣٠) — الثالثة\",\"v\":\"لأن سخطا في غضبه: وحياة في رضاه.\",\"r\":\"يقول المرنم: سخط في غضبه وحياة في رضاه. حين يغضب الله لا ينسى أن يرحم، وهكذا يريدنا أن نتذكر الرحمة حين نغضب. حين يثور فيك غضب اليوم، تنفس ببطء وقل: يا رب اذكر الرحمة.\",\"p\":\"يا رب، في الغضب اذكر الرحمة. اجعلني أتذكر رحمتك حين أغضب وأغيظ، فأحيا في رضاك. آمين.\",\"x\":\"سخط في غضبه وحياة في رضاه. حين يغضب الله لا ينسى أن يرحم، فلنتذكر الرحمة حين نغضب. تدريب: عند أول غضب اليوم عدّ للعشرة وقل: ارحم يا رب.\"},{\"t\":\"في الغضب اذكر الرحمة\",\"ref\":\"حبقوق ٣: ٢\",\"bk\":\"حبقوق\",\"v\":\"يا رب، قد سمعت خبرك فجزعت. يا رب، عملك في وسط السنين أحيه. في وسط السنين عرف. في الغضب اذكر الرحمة.\",\"r\":\"«يا رب، عملك في وسط السنين أحيه… في الغضب اذكر الرحمة». كثيرًا ما أرى الأزمات ولا أرى يد الله. فأطلب منه أن يحيي عمله ويظهره. وفي ضيقي أذكره بما أعرفه عنه: أنه رحيم.\",\"p\":\"يا رب، أحيِ عملك في وسط السنين. في الغضب اذكر الرحمة، وفي ضيقنا ثبت إيماننا ورجاءنا. آمين.\",\"x\":\"الأصحاح الثالث من حبقوق صلاة تسبيح وتضرع، وقد استخدمتها الكنيسة في صلوات الأسبوع. وهي تبدأ بمخافة: «سمعت خبرك فجزعت». ثم تطلب إحياء عمل الله وسط السنين، أي في وسط التاريخ وبين الأجيال. والطلب الأعمق: أن تظل الرحمة حاضرة حتى في الغضب. وهذا يعلمنا أن نصلي في الأزمات بنبرة ثقة. وينتهي النص بترنيمة الفرح بالرب رغم غياب الثمار.\\nاليوم، في موقف يضغطك، قل بالصلاة: «يا رب، اذكر رحمتك»، وانتظر بهدوء.\"},{\"t\":\"الغضوب لا يُقبل\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أغاثون: لو أقام الغضوب ميتًا لن يكون مقبولًا عند الله. الغضب يهدم حتى أعظم العطايا. اترك اليوم محاولة الانتصار في جدال صغير، وقدمها لله.\",\"p\":\"يا رب، اقتلع الغضب من قلبي. اجعل رحمتي أسبق من غضبي ووداعتي أقوى من اندفاعي. آمين.\",\"x\":\"يقول القديس أغاثون: لو أقام الغضوب ميتًا لن يكون مقبولًا عند الله. الغضب يهدم أعظم العطايا. تدريب: اترك اليوم محاججة تنتهي بغضب.\",\"fq\":54}]},\"11-6\":{\"th\":\"اجعلوا قلبكم على طرقكم\",\"m\":[{\"t\":\"وعن شهاداتك لم أجنح\",\"ref\":\"المزمور ١١٨ (١١٩) — الجزء العشرون · صلاة الستار\",\"v\":\"كثيرون هم الذين يضطهدونني ويحزنونني. وعن شهاداتك لم أجنح.\",\"r\":\"كثيرون يضطهدون المرنم ويحزنونه، لكنه لم يجنح عن شهادات الله. أن نجعل قلبنا على طرقنا يعني أن نراجع خطواتنا بصدق. اكتب اليوم ثلاث خطوات عشتها هذا الأسبوع، واسأل: أين كنت فيها قريبًا من الله؟\",\"p\":\"يا رب، لا أجنح عن شهاداتك مهما كثر المضايقون. علّمني أن أراجع طرقي وأعدلها. آمين.\",\"x\":\"كثيرون يضطهدونني وعن شهاداتك لم أجنح. أن نجعل قلبنا على طرقنا أن نراجع خطواتنا بصدق. تدريب: راجع الليلة ثلاث خطوات من يومك واسأل: هل هي في طريق الله؟\"},{\"t\":\"اطلبوا الرب واطلبوا التواضع\",\"ref\":\"صفنيا ٢: ٣\",\"bk\":\"صفنيا\",\"v\":\"اطلبوا الرب، يا جميع بائسي الأرض الذين فعلوا حكمه. اطلبوا البر. اطلبوا التواضع. لعلكم تسترون في يوم سخط الرب.\",\"r\":\"«اطلبوا الرب… اطلبوا البر. اطلبوا التواضع». ثلاث طلبات متتابعة. طلب الرب أولًا ثم البر والتواضع. ولا أنال الاستتار في يوم الضيق إلا بقرب الله. فلأبدأ اليوم بالطلب، وأعلم أن التواضع يُطلب كما يُطلب البر.\",\"p\":\"يا رب، علمني أن أطلبك وأطلب البر والتواضع. استرني في يوم الضيق بسترك، واجعلني متكلًا على رحمتك. آمين.\",\"x\":\"يخاطب النبي مجموعة قليلة تفعل حكم الله، ويحثها على الاستمرار. والفعل «اطلبوا» يتكرر ثلاث مرات، مما يدل على الجهد المستمر. والتواضع فضيلة تُطلب بالصلاة والممارسة. وقد قال الآباء إن التواضع هو الطريق الوحيد إلى الملكوت. وكلمة «لعلكم تستترون» تعبر عن رجاء لا يقين، تعبّر عن اعتماد على رحمة الله. ونصلي كل يوم: «استرنا بستر جناحيك».\\nاليوم، مارس عملًا صغيرًا من التواضع: خدمة غير ملحوظة أو اعتراف بخطأ.\"},{\"t\":\"كشف الخطوات\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح القديس أنطونيوس بأن يكشف الراهب للآباء كل خطواته وكل قطرات الماء التي يشربها في قلايته، ليتأكد أنه لا يخطئ. الشفافية مع مرشد أمين تحمي الطريق. اكشف اليوم أمرًا لأب اعترافك أو صديق روحي.\",\"p\":\"يا رب، علّمني الشفافية أمام مرشدي. احفظني من التكتم الذي يخفي سقوطي. آمين.\",\"x\":\"ينصح القديس أنطونيوس بأن يكشف الراهب للآباء كل خطواته وكل قطرات الماء التي يشربها في قلايته ليتأكد أنه لا يخطئ. الكشف يحفظ. تدريب: شارك أب اعترافك في أمر تخفيه.\",\"fq\":22}]},\"11-7\":{\"th\":\"مجد البيت الأخير\",\"m\":[{\"t\":\"أحببت جمال بيتك\",\"ref\":\"المزمور ٢٥ (٢٦) — الثالثة\",\"v\":\"أغسل يدي بالنقاوة. وأطوف بمذبحك يا رب. لأسمع صوت تسبيحك. وأنطق بجميع عجائبك. يا رب أحببت جمال بيتك وموضع مسكن مجدك.\",\"r\":\"أغسل يدي بالنقاوة وأطوف بمذبحك، لأسمع صوت تسبيحك، فقد أحببت جمال بيتك وموضع مسكن مجدك. مجد البيت الأخير أعظم من الأول لأنه يمتلئ حضورًا. اسهم اليوم في ترتيب بيت من بيوت الله، كنيستك أو بيتك.\",\"p\":\"يا رب، أحببت جمال بيتك. اغسل يدي بالنقاوة واجعلني أطوف بمذبحك وأنطق بعجائبك. آمين.\",\"x\":\"أغسل يدي بالنقاوة وأطوف بمذبحك لأني أحببت جمال بيتك. مجد البيت الأخير أعظم من الأول. تدريب: اذهب اليوم إلى الكنيسة ولو ربع ساعة قبل التزاماتك.\"},{\"t\":\"وفي هذا المكان أعطي السلام\",\"ref\":\"حجي ٢: ٩\",\"bk\":\"حجي\",\"v\":\"مجد هذا البيت الأخير يكون أعظم من مجد الأول، قال رب الجنود. وفي هذا المكان أعطي السلام، يقول رب الجنود».\",\"r\":\"«مجد هذا البيت الأخير يكون أعظم من مجد الأول… وفي هذا المكان أعطي السلام». وعد بمجد أعظم وسلام. والمسيح دخل الهيكل وأعطى السلام. وهو يعطيني اليوم سلامه في بيته، فلا أترك السلام حين أخرج من الكنيسة.\",\"p\":\"يا رب، أنت أعطيت السلام في بيتك. املأ كنيستك بمجدك، واجعلني أحمل سلامك إلى أسرتي وعملي. آمين.\",\"x\":\"رأى الآباء في هذه النبوة إشارة إلى مجيء المسيح إلى الهيكل، وإلى الكنيسة التي هي بيت الله الأعظم. فالسلام الذي وُعد في هذا المكان هو سلام الصليب والقيامة: «سلامي أعطيكم». وفي كل قداس يقول الكاهن: «السلام لجميعكم». والمجد الأخير هو المسيح حاضرًا في كنيسته. ومهما بدت أعمالنا صغيرة، فإن الله يمجدها.\\nعند دخولك الكنيسة هذا الأسبوع، توقف لحظة وقل: «أشكرك لأنك تعطي السلام في هذا المكان».\"},{\"t\":\"الشدة والسكينة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوحنا الكيليكس: لنتشبه بآبائنا، كم من الشدة والسكينة أقاموا هنا. أساس البيت الروحي أن نبنيه على تضحية من سبقونا. اشكر اليوم من أسسوا كنيستك، وصلِّ لهم.\",\"p\":\"يا رب، أشكرك على من بنوا كنيستك بتعبهم. أعطني أن أحفظ ما تركوه وأبني عليه بأمانة. آمين.\",\"x\":\"يقول الأب يوحنا الكيليكس: لنتشبه بآبائنا، كم من الشدة والسكينة أقاموا هنا. البناء يقوم على تضحيات من سبقوا. تدريب: اذكر اليوم قديسًا بنى إيمانك وقلد فضيلة منه.\",\"fq\":195}]},\"11-8\":{\"th\":\"الرسول والعشور والتذكرة\",\"m\":[{\"t\":\"يذكر جميع ذبائحك\",\"ref\":\"المزمور ١٩ (٢٠) — الثالثة\",\"v\":\"يذكر جميع ذبائحك؛ ويستسمن محرقاتك. يعطيك الرب حسب قلبك، ويتمم كل مشورتك.\",\"r\":\"يذكر الرب ذبائحنا ويعطينا حسب قلوبنا ويتمم كل مشورتنا. العشور والتقدمات اعتراف بأن كل ما لدينا من يده. أفرز اليوم جزءًا من دخلك للرب أو للفقراء، وقدمه بفرح.\",\"p\":\"يا رب، اذكر ذبائحي وأعطني حسب قلبي. علّمني أن أقدم لك أول ما أملك بشكر. آمين.\",\"x\":\"يذكر الرب جميع ذبائحك ويعطيك حسب قلبك. العشور اعتراف بأن كل شيء من يده. تدريب: أفرز اليوم جزءًا من دخلك لله قبل أي مصروف.\"},{\"t\":\"جربوني بهذا\",\"ref\":\"ملاخي ٣: ١٠\",\"bk\":\"ملاخي\",\"v\":\"هاتوا جميع العشور إلى الخزنة ليكون في بيتي طعام، وجربوني بهذا، قال رب الجنود، إن كنت لا أفتح لكم كوى السماوات، وأفيض عليكم بركة حتى لا توسع.\",\"r\":\"«هاتوا جميع العشور إلى الخزنة… وجربوني بهذا». الله يدعوني إلى أمانة في المال أرى فيها وفاءه. العشور ليست ثمنًا للبركة، بل تدريب على الثقة. وأنا أبدأ بالأمانة فيما أملك لأرى أمانة الله.\",\"p\":\"يا رب، كل ما لدي منك. علمني الأمانة في العطاء، وافتح لي ثقة لا تتزعزع في أنك مصدر كل بركة. آمين.\",\"x\":\"كان الشعب قد اختصر في عطاياه، فجاء الرب يعاتبهم بأنهم يسلبونه. والعشور تشير إلى أن كل شيء له. وقد رتّب الله بها طعامًا في بيته للاويين والغرباء والأيتام. فالعطاء له بعد اجتماعي. وفي الكنيسة القبطية نمارس العشور والباكورات والنذور كتعبير عن الشكر. والجملة «جربوني» تعني أن الله يتحدى أمانتنا بوعد بركته. لكنها ليست معادلة تجارية بل علاقة ثقة.\\nراجع التزامك بالعشور أو العطاء المنتظم، وإن لم يكن لك نظام فابدأ بنسبة صغيرة ثابتة.\"},{\"t\":\"حب المال المخيف\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس إن حب المال المخيف الذي لا يعرف الشبع يقود النفس المستعبدة له إلى أسوأ الشرور، فلنبتعد عنه من البدء لأنه إذا ساد صار سيدًا لا يقهر. التذكرة الأولى في العشور أن المال ليس سيدًا. أعطِ اليوم قبل أن تحسب.\",\"p\":\"يا رب، حرّرني من حب المال. اجعلني خادمًا لك لا لمالي. آمين.\",\"x\":\"يقول الأب إيسيذورس إن حب المال المخيف الذي لا يعرف الشبع يقود النفس المستعبدة له إلى أسوأ الشرور، فلنبتعد عنه من البدء لأنه إذا ساد يصبح سيدًا لا يقهر. تدريب: قاوم اليوم رغبة شراء غير لازمة.\",\"fq\":175}]},\"11-9\":{\"th\":\"شمس البر\",\"m\":[{\"t\":\"الله الرب أضاء علينا\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"الله الرب أضاء علينا.\",\"r\":\"الله الرب أضاء علينا، فهو شمس البر وفي أجنحتها الشفاء. كل صباح لنا فرصة لنقف في ضوئه. وقف اليوم دقيقة في الشمس أو عند النافذة، وصلِّ: أضئ علينا يا رب.\",\"p\":\"يا شمس البر، أضئ علينا. اطلع في قلبي بشفاء أجنحتك، واجعلني أنعكس نورك. آمين.\",\"x\":\"الله الرب أضاء علينا. هو شمس البر وفي أجنحتها الشفاء. تدريب: قف في الضوء دقيقة وقل: أضئ على قلبي يا شمس البر.\"},{\"t\":\"تشرق شمس البر\",\"ref\":\"ملاخي ٤: ٢\",\"bk\":\"ملاخي\",\"v\":\"«ولكم أيها المتقون اسمي تشرق شمس البر والشفاء في أجنحتها، فتخرجون وتنشأون كعجول الصيرة.\",\"r\":\"«ولكم أيها المتقون اسمي تشرق شمس البر والشفاء في أجنحتها». المسيح هو شمس البر. وحين يشرق في قلبي تهرب الظلمة. ومن يعيش في نوره ينمو ويفرح كعجل خارج من الحظيرة.\",\"p\":\"يا شمس البر، أشرق في قلبي. اشفني من ظلمة الخطية، وأخرجني إلى نورك كعجل يفرح بحريته. آمين.\",\"x\":\"تسمي الكنيسة المسيح «شمس البر» في تسابيحها ويقال عنه في ألحان الميلاد وعيد الغطاس. والجناحان يشيران إلى أشعة الشمس. وهو يحمل الشفاء. وصورة العجول الخارجة من الحظيرة هي صورة الفرح والحرية والنمو. وأولئك الذين يخافون اسمه ينالون هذا النور. وفي صلاة باكر نقول: «يا نور العالم». وشروق النور يتحقق في كل صباح بصلاتنا.\\nاليوم، في الصباح، قف أمام النافذة أو الشمس لحظة، واشكر المسيح أنه شمس البر الذي يشرق عليك.\"},{\"t\":\"عن رؤية الله\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ثيوناس: بسبب انشغال العقل الأعلى في غير رؤية الله نسقط أسرى الأهواء الجسدية. الشمس الحقيقية تحرر من الظلام. وجّه اليوم نظرك لحظة نحو الله كلما انشغل ذهنك بما لا يليق.\",\"p\":\"يا رب، اجعل ذهني متجهًا نحوك. حرّره من انشغالاته الباطلة. آمين.\",\"x\":\"يقول الأب ثيوناس: بسبب انشغال العقل الأعلى في غير رؤية الله نسقط أسرى الأهواء الجسدية. من يرى الله يتحرر. تدريب: أعد ذهنك إلى الله كلما انشغل بغيره.\",\"fq\":144}]},\"11-10\":{\"th\":\"العهد الجديد والشفاء\",\"m\":[{\"t\":\"ورتبت مضجعه في مرضه\",\"ref\":\"المزمور ٤٠ (٤١) — الثالثة\",\"v\":\"الرب يعينه على سرير وجعه. إنك رتبت مضجعه كله في مرضه.\",\"r\":\"الرب يعين المريض على سرير وجعه ويرتب مضجعه كله في مرضه. العهد الجديد وعد بشفاء من الداخل أولًا. صلِّ اليوم من أجل مريض، وقدم له كلمة أو خدمة.\",\"p\":\"يا رب، أعن كل مريض على سرير وجعه. اشفِ جراح قلوبنا بعهدك الجديد. آمين.\",\"x\":\"الرب يعين المريض على سرير وجعه ويرتب مضجعه كله في مرضه. العهد الجديد يشفي من الداخل. تدريب: صلِّ اليوم لمريض بالاسم وزره إن أمكن.\"},{\"t\":\"أكتب شريعتي على قلوبهم\",\"ref\":\"إرميا ٣١: ٣٣\",\"bk\":\"إرميا\",\"v\":\"بل هذا هو العهد الذي أقطعه مع بيت إسرائيل بعد تلك الأيام، يقول الرب: أجعل شريعتي في داخلهم وأكتبها على قلوبهم، وأكون لهم إلها وهم يكونون لي شعبا.\",\"r\":\"«أجعل شريعتي في داخلهم وأكتبها على قلوبهم». الوصية لن تبقى حجرًا على لوح بل تدخل قلبي. وهذا يتم بنعمة الروح القدس. فلأطلب كل صباح أن يكتب الله وصاياه في قلبي، لا على ورقة أنساها.\",\"p\":\"يا رب، اكتب شريعتك على قلبي بروحك القدوس. اجعلني أحب وصاياك وأعمل بها، وكن إلهي وأنا من شعبك. آمين.\",\"x\":\"هذه النبوة اقتبستها رسالة العبرانيين لتشرح العهد الجديد الذي أسسه المسيح بدمه. والفرق بين القديم والجديد أن الأول خارج الإنسان والثاني داخله. فالروح القدس يسكن في المؤمن ويعلمه. وفي سر المعمودية والميرون نتمتع بهذا العهد. ومحور العهد: «أكون لهم إلهًا وهم يكونون لي شعبًا». أي علاقة حب متبادلة. والكتابة على القلوب تحتاج استعدادًا وانفتاحًا من جانبنا.\\nاحفظ اليوم آية واحدة عن ظهر قلب، لتصبح مكتوبة في قلبك.\"},{\"t\":\"جسد وروح\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب دانيال: بمقدار ما ينتعش الجسد تضعف النفس، وبمقدار ما يضعف الجسد تنتعش النفس. المرض قد يصير مدرسة للروح. اشكر الله اليوم على ما علّمك إياه الألم.\",\"p\":\"يا رب، علّمني أن أحيا في الضعف نمو الروح. اشفِ جسدي إن شئت وقوّ نفسي بك. آمين.\",\"x\":\"يقول الأب دانيال: بمقدار ما ينتعش الجسد تضعف النفس، وبمقدار ما يضعف الجسد تنتعش النفس. المرض مدرسة. تدريب: اقبل ضعفك الجسدي اليوم صلاة.\",\"fq\":94}]},\"11-11\":{\"th\":\"إيمان أيوب\",\"m\":[{\"t\":\"عليك توكلت\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"انظر إلى أعدائي فإنهم قد كثروا وأبغضوني ظلما. احفظ نفسي ونجني، لا أخزى لأني عليك توكلت.\",\"r\":\"ينظر المرنم إلى كثرة مبغضيه، لكنه يطلب الحفظ لأنه عليك توكل. هذا إيمان أيوب: أعلم أن فادي حي، وفي الامتحان أخرج كالذهب. توكل اليوم في أمر واحد تخشاه، ولو قلتها صلاة قصيرة.\",\"p\":\"احفظ نفسي ونجني يا رب، لا أخزى لأني عليك توكلت. ثبّت إيماني كأيوب في الامتحان. آمين.\",\"x\":\"انظر إلى أعدائي فقد كثروا وأبغضوني ظلمًا، احفظ نفسي لأني عليك توكلت. هذا إيمان أيوب: أعلم أن فادي حي. تدريب: قل في ألم اليوم: أعلم أن فاديّ حي.\"},{\"t\":\"أما أنا فقد علمت أن وليي حي\",\"ref\":\"أيوب ١٩: ٢٥\",\"bk\":\"أيوب\",\"v\":\"أما أنا فقد علمت أن وليي حي، والآخر على الأرض يقوم،\",\"r\":\"«أما أنا فقد علمت أن وليي حي، والآخر على الأرض يقوم». في قمة الألم يصرخ أيوب بإيمان القيامة. وأنا أيضًا، وسط ضيقاتي، أتمسك بأن فاديّ حي، وأنني سأرى الله. وهذا الرجاء لا يسلبه مني أحد.\",\"p\":\"يا فادي، أنت وليي الحي. ثبّت إيماني بقيامتي وقيامة أحبائي، وأعطني رجاءً لا يتزعزع في أوقات الألم والليل. آمين.\",\"x\":\"الولي في الشريعة هو القريب الفادي الذي يدافع عن حق قريبه. وأيوب يرى أن الله نفسه هو وليه. وقد رأى الآباء في هذه الآية نبوة عن المسيح الفادي وعن القيامة العامة. ولذلك تتلى هذه الآيات في صلوات الراقدين. وقوة النص أنه قيل في وقت لم يكن فيه أيوب يرى أي بصيص: أصدقاؤه يتهمونه ومرضه يشتد. ومع ذلك يشهد بإيمانه. والإيمان الحقيقي يظهر في الظلام.\\nاليوم، في موضع ضعفك أعلن بصوتك: «وليي حي»، وردد هذه الشهادة.\"},{\"t\":\"نوح ودانيال وأيوب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: نوح صورة اللاقنية، وأيوب صورة الألم، ودانيال مثال التمييز، وإذا وجد الثلاثة معًا في إنسان فإن الله يقيم فيه. إيمان أيوب يحتاج هذه الثلاثة. اختر منها اليوم فضيلة واحدة تتدرب عليها.\",\"p\":\"يا رب، أعطني قناعة نوح وصبر أيوب وتمييز دانيال. وأقم فيّ بنعمتك. آمين.\",\"x\":\"يقول الأب بيمن: الفقر والشدة والضيق والصوم أدوات السيرة الرهبانية لأنه مكتوب «ولو كان فيها هؤلاء الثلاثة نوح ودانيال وأيوب»؛ نوح صورة اللاقنية وأيوب الألم ودانيال التمييز. تدريب: اطلب فضيلة واحدة من الثلاث.\",\"fq\":358}]},\"11-12\":{\"th\":\"الحكمة والتأديب\",\"m\":[{\"t\":\"ليؤدبني الصديق برحمة\",\"ref\":\"المزمور ١٤٠ (١٤١) — النوم\",\"v\":\"فليؤدبني الصديق برحمة ويوبخني.\",\"r\":\"يقول المرنم: فليؤدبني الصديق برحمة ويوبخني. التأديب علامة محبة، والحكمة تبدأ بقبوله. اطلب اليوم من صديق أمين ملاحظة صادقة على تصرف لك.\",\"p\":\"يا رب، أعطني قلبًا يقبل التأديب. ليؤدبني الصديق برحمة، فأتعلم ولا أعاند. آمين.\",\"x\":\"ليؤدبني الصديق برحمة ويوبخني. التأديب علامة محبة. تدريب: اطلب اليوم من صديق أمين ملاحظة واحدة عنك، واقبلها بلا دفاع.\"},{\"t\":\"طوبى لرجل يؤدبه الله\",\"ref\":\"أيوب ٥: ١٧\",\"bk\":\"أيوب\",\"v\":\"« هوذا طوبى لرجل يؤدبه الله. فلا ترفض تأديب القدير.\",\"r\":\"«طوبى لرجل يؤدبه الله، فلا ترفض تأديب القدير». التأديب ليس رفضًا بل محبة. وأنا حين أتعرض لتصحيح لا أفرح به لكني أقبله، لأنه يشبه تأديب الأب لابنه. فلأعامل التأديب بشكر.\",\"p\":\"يا رب، لا أرفض تأديبك لأنه محبة. علمني من كل تصحيح، وأعطني قلبًا ينفتح للتعلم بدل أن ينغلق في الدفاع. آمين.\",\"x\":\"ملاحظة مهمة: كلام أليفاز في سفر أيوب فيه حق وخطأ، فقد أخطأ في اتهام أيوب. لكن هذه العبارة نفسها اقتبسها كاتب العبرانيين: «يا ابني لا تحتقر تأديب الرب». فتأديب الله حق، ولكن ليس كل ألم تأديبًا عن خطية. ويمنحنا ذلك حكمة: لا نفسر آلام الآخرين بأنها عقاب. ولكن في آلامنا نسأل ما يريد الرب أن يعلمنا. والتأديب غايته الشفاء، كما يقول بعدها: «هو يجرح ويعصب».\\nاسأل نفسك اليوم: ما التصحيح الذي أتعلمه الآن؟ وقل: «علمني يا رب».\"},{\"t\":\"التعليم يشبه التوبيخ\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: إن تعليم القريب شبيه بتوبيخه. من يعلّم يتحمل مسؤولية المعلم، ومن يقبل التعليم يتحمل أن يُصحَّح. اقبل اليوم تصحيحًا بتواضع، ولا تدافع.\",\"p\":\"يا رب، علّمني قبول التصحيح. وإن علّمت أحدًا فاجعل كلامي رحمة. آمين.\",\"x\":\"يقول الأب بيمن: إن تعليم القريب شبيه بتوبيخه. من يعلّم يتحمل المسؤولية. تدريب: قبل أن تنصح اليوم اسأل: هل أنا أفعل ما أقول؟\",\"fq\":430}]},\"11-13\":{\"th\":\"لكل شيء زمان\",\"m\":[{\"t\":\"سبع مرات في النهار\",\"ref\":\"المزمور ١١٨ — الجزء الحادي والعشرون («كُونوا مُستَعِدّينَ، لأنَّهُ في ساعَةٍ لا تَظُنّونَ يَأتي ابنُ الإنسان.») — الستار\",\"v\":\"سبع مرات في النهار سبحتك على أحكام عدلك.\",\"r\":\"يسبح المرنم الله سبع مرات في النهار على أحكام عدله. لكل شيء زمان، وللتسبيح زمان في كل ساعة. اختر اليوم ثلاث ساعات تتوقف فيها دقيقة للتسبيح.\",\"p\":\"يا رب، سبع مرات في النهار أسبحك. علّمني أن أعرف أزمنتي وأقدسها بحمدك. آمين.\",\"x\":\"سبع مرات في النهار سبحتك على أحكام عدلك. لكل شيء زمان وللتسبيح زمان في كل ساعة. تدريب: اختر ثلاث ساعات اليوم للتسبيح ولو دقيقة.\"},{\"t\":\"لكل شيء زمان\",\"ref\":\"الجامعة ٣: ١\",\"bk\":\"الجامعة\",\"v\":\"لكل شيء زمان، ولكل أمر تحت السماوات وقت:\",\"r\":\"«لكل شيء زمان، ولكل أمر تحت السماوات وقت». هناك وقت للبكاء ووقت للضحك، وقت للحصاد ووقت للغرس. وأنا أتعلم ألا أستعجل ما لم يحن، ولا أؤجل ما حان. فلأطلب من الله أن يعرفني زمني.\",\"p\":\"يا رب، أنت سيد الأوقات. علمني أن أعيش كل زمن بحسب مشيئتك، وأن أشكرك في الفرح، وأثق بك في الحزن. آمين.\",\"x\":\"أصحاح ٣ من الجامعة يعدد أربعة عشر زوجًا من الأوقات المتقابلة. والحكيم يرى أن الله ضبط الأوقات. والمؤمن لا يتذمر على زمن الضيق ولا يتعلق بزمن الفرح، بل يعيش في حضور الله فيهما. وتتلاءم هذه الحكمة مع دورة السنة الكنسية: صوم وفطر، حزن وفرح. ففي صوم الميلاد نسير في زمن الاستعداد. وهكذا نتعلم الصبر على الأوقات.\\nاسأل نفسك اليوم: ما هو الزمن الذي أنا فيه الآن؟ وما الذي يطلبه الله مني فيه؟\"},{\"t\":\"الخطايا أو المسيح أو الناس\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيليا: يفكر الناس إما بالخطايا أو بالمسيح أو بالناس. أزمنة اليوم تمتلئ بإحدى هذه الثلاث. راقب اليوم أين يذهب فكرك أكثر، وأعده إلى المسيح.\",\"p\":\"يا رب، اجعل فكري فيك لا في خطاياي ولا في الناس. آمين.\",\"x\":\"يقول الأب إيليا: يفكر الناس إما بالخطايا أو بالمسيح أو بالناس. تدريب: راقب اليوم أفكارك ومن ثلاثتهم يشغلها أكثر.\",\"fq\":129}]},\"11-14\":{\"th\":\"ختام الأمر كله\",\"m\":[{\"t\":\"كل طرقي أمامك\",\"ref\":\"المزمور ١١٨ — الجزء الحادي والعشرون («كُونوا مُستَعِدّينَ، لأنَّهُ في ساعَةٍ لا تَظُنّونَ يَأتي ابنُ الإنسان.») — الستار\",\"v\":\"وكل طرقي أمامك يا راج. هلليلويا.\",\"r\":\"يقول المرنم: كل طرقي أمامك. ختام الأمر كله أن نتقي الله ونحفظ وصاياه. اختم اليوم بأن تضع أمام الله كل ما فعلته، وانتظر رحمته.\",\"p\":\"يا رب، كل طرقي أمامك. اجعل ختام أمري كله أن أخافك وأحفظ وصاياك. آمين.\",\"x\":\"وكل طرقي أمامك يا رب. ختام الأمر كله أن نتقي الله ونحفظ وصاياه. تدريب: ضع أمام الله ما فعلته اليوم قبل النوم.\"},{\"t\":\"هذا هو الإنسان كله\",\"ref\":\"الجامعة ١٢: ١٣\",\"bk\":\"الجامعة\",\"v\":\"فلنسمع ختام الأمر كله: اتق الله واحفظ وصاياه، لأن هذا هو الإنسان كله.\",\"r\":\"«ختام الأمر كله: اتق الله واحفظ وصاياه، لأن هذا هو الإنسان كله». بعد كل تجارب الحكيم، يرى أن الحياة تتلخص في أمرين: مخافة الله وحفظ وصاياه. وهذا كافٍ ليعطي حياتي معنى وتوجهًا.\",\"p\":\"يا رب، علمني أن أتقيك وأحفظ وصاياك لأن هذا هو الإنسان كله. اجمع قلبي المشتت عليك، وامنحني بساطة الحكمة الحقيقية. آمين.\",\"x\":\"سفر الجامعة يتتبع محاولات الإنسان لإيجاد معنى بالحكمة واللذة والعمل والغنى، ويصل إلى «باطل الأباطيل». وفي الختام يعلن الحل: التقوى والوصايا. وكلمة «الإنسان كله» تعني أن هذا هو واجب كل إنسان وكماله. وقد وافقه المسيح حين لخص الشريعة في محبة الله والقريب. وتساعدنا الكنيسة أن نعيش هذا بالصلاة والأسرار. وكلما تعقدت الحياة نحتاج إلى العودة لهذا الجوهر البسيط.\\nلخص يومك الليلة في سؤالين: هل اتقيت الله؟ هل حفظت وصاياه؟ وقدم النتيجة بتوبة وشكر.\"},{\"t\":\"لا تثق ببرك\",\"ref\":\"\",\"v\":\"\",\"r\":\"يوصي القديس أنطونيوس: لا تثق ببرك ولا تندم على أمر قد عبر، وأمسك بطنك ولسانك. الختام الصالح يكون بتواضع من لا يعتمد على نفسه. اترك اليوم الندم على ماضٍ مضى، وابدأ من جديد.\",\"p\":\"يا رب، لا أثق ببري بل برحمتك. اغفر ما مضى، وأمسك لساني وجسدي في طاعتك. آمين.\",\"x\":\"قال القديس أنطونيوس لبموا حين سأله ماذا أعمل: لا تثق ببرك ولا تندم على أمر قد عبر، وأمسك بطنك ولسانك. تدريب: لا تفتخر ولا تتحسر اليوم، وضبط لسانك.\",\"fq\":4}]},\"11-15\":{\"th\":\"الرب يقاتل عنكم\",\"m\":[{\"t\":\"الرب عضدني\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"أحاطوا بي احتياطا واكتنفوني، وباسم الرب قهرتهم. أحاطوا بي مثل النحل حول الشهد، والتهبوا كنار في شوك، وباسم الرب انتقمت منهم. دفعت لأسقط والرب عضدني.\",\"r\":\"يقول المرنم: أحاطوا بي مثل النحل حول الشهد، وباسم الرب قهرتهم؛ دفعت لأسقط والرب عضدني. الرب يقاتل عنا ونحن صامتون. سلّم اليوم صراعًا لا تستطيع حله بنفسك، وقل: يا رب قاتل عني.\",\"p\":\"يا رب، عضدني حين أدفع لأسقط. باسمك أقهر، وأنت تقاتل عني. آمين.\",\"x\":\"أحاطوا بي مثل النحل حول الشهد وباسم الرب قهرتهم، دفعت لأسقط والرب عضدني. الرب يقاتل ونحن صامتون. تدريب: في معركة اليوم قل: باسم الرب أقهرهم.\"},{\"t\":\"الرب يقاتل عنكم\",\"ref\":\"الخروج ١٤: ١٤\",\"bk\":\"الخروج\",\"v\":\"الرب يقاتل عنكم وأنتم تصمتون».\",\"r\":\"«الرب يقاتل عنكم وأنتم تصمتون». حين يضيق الأمر ولا أرى مخرجًا، أميل إلى الجدال والاضطراب. وأحيانًا يكون المطلوب أن أصمت وأثق. فالله يقاتل في المواقف التي لا أقدر عليها.\",\"p\":\"يا رب، أنت تقاتل عني. علمني أن أصمت بثقة، وأتحرك حين تأمرني، ولا أجادل في وقت الضيق. آمين.\",\"x\":\"كان الشعب محاصرًا بين البحر والجيش المصري، فصرخوا ولاموا موسى. فأجاب بكلمة الإيمان. والصمت هنا يعني الهدوء والتوقف عن التذمر. ثم أمره الله أن يتقدم، فانشق البحر. أي أن الإيمان يجمع بين الصمت أمام الله والحركة بأمره. وفي الكنيسة نقرأ هذه الآية في تسبحة موسى. وعبور البحر رمز للمعمودية. وكل معركة روحية لا ننتصر فيها بقوتنا.\\nأمام مشكلة اليوم، قل: «الرب يقاتل عني»، وخصص وقتًا للصمت والصلاة قبل أي رد.\"},{\"t\":\"الجبّ العميق\",\"ref\":\"\",\"v\":\"\",\"r\":\"يشبّه الأب بيمن الإنسان أمام حرب جسدية بمن يقف أمام جب عميق، وإذا ابتعد عن الجسديات صار بعيدًا عن الجب، وإن حاول العدو أن يجره أرسل الله له العون. الابتعاد عن مواضع السقوط نصف المعركة. ابتعد اليوم عن موضع تعثر فيه.\",\"p\":\"يا رب، أبعدني عن حافة الجب. أرسل لي عونك حين يحاول العدو أن يجرني. آمين.\",\"x\":\"يشبّه الأب بيمن الإنسان أمام حرب جسدية بمن يقف أمام جب عميق متى شاء العدو يرميه، فإذا ابتعد عن الجسديات صار بعيدًا عن الجب. الهروب حكمة. تدريب: ابتعد اليوم عما يثير معركتك.\",\"fq\":357}]},\"11-16\":{\"th\":\"اختر الحياة\",\"m\":[{\"t\":\"من يهوى الحياة؟\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"من هو الإنسان الذي يهوى الحياة، ويحب أن يرى أياما صالحة؟\",\"r\":\"من هو الإنسان الذي يهوى الحياة ويحب أن يرى أيامًا صالحة؟ جواب الله: اختر الحياة. اختيار الحياة قرارات صغيرة يومية. اختر اليوم بوعي ما يعطي حياة: كلمة طيبة أو قراءة أو راحة.\",\"p\":\"يا رب، أريد أن أحيا وأرى أيامًا صالحة. اهدني في اختيار الحياة، وابعدني عما يميت. آمين.\",\"x\":\"من هو الإنسان الذي يهوى الحياة ويحب أن يرى أيامًا صالحة؟ جواب الله: اختر الحياة. تدريب: اختر اليوم في ثلاثة مواقف الطريق الذي يحيي.\"},{\"t\":\"فاختر الحياة\",\"ref\":\"التثنية ٣٠: ١٩\",\"bk\":\"التثنية\",\"v\":\"أشهد عليكم اليوم السماء والأرض. قد جعلت قدامك الحياة والموت. البركة واللعنة. فاختر الحياة لكي تحيا أنت ونسلك،\",\"r\":\"«قد جعلت قدامك الحياة والموت، البركة واللعنة، فاختر الحياة لكي تحيا أنت ونسلك». الله يدعوني إلى الاختيار، ولا يفرض. وقراراتي اليوم لا تؤثر علي وحدي بل على من بعدي. فلأختار الحياة في الأمور الصغيرة.\",\"p\":\"يا رب، أنت الحياة. أعنّي أن أختار الحياة في قراراتي اليومية، واحفظ أولادي ونسلي في طريق البركة. آمين.\",\"x\":\"الاختيار يتكرر في الكتاب: يشوع يقول «اختاروا لأنفسكم اليوم»، والرب يقول: «الطريق الواسع والطريق الضيق». والاختيار يتضمن قرارات يومية صغيرة. وكلمة «نسلك» تشير إلى أثر الاختيار على الأجيال القادمة. وقد اختارت الكنيسة الحياة بالصوم والصلاة. وتعلّمنا بالمعمودية أن اختيارنا تم بنعمة. واختيار الحياة معناه اختيار المسيح الذي قال: «أنا هو الحياة».\\nاختر اليوم الحياة في قرار واحد صغير: امتنع عن شيء يضرك، أو افعل شيئًا يبني.\"},{\"t\":\"الخطية تميت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: إذا وصل الإنسان إلى الخطية مات، وإذا وصل إلى الصلاح حيا وعمل الصلاح. الاختيار بين طريقين يتكرر كل يوم. قل اليوم نعم لصلاح واحد ولا لخطية واحدة.\",\"p\":\"يا رب، قدني إلى الصلاح الذي يحيي. أبعد عني الخطية التي تميت. آمين.\",\"x\":\"سُئل الأب بيمن: هل يستطيع المرء أن يكون كالميت؟ فقال: إذا وصل إلى الخطيئة يموت، وإذا وصل إلى الصلاح فإنه يحيا ويعمل الصلاح. تدريب: ابتعد اليوم عن موضع تسقط فيه.\",\"fq\":402}]},\"11-17\":{\"th\":\"عيون الإيمان\",\"m\":[{\"t\":\"بعينيك تتأمل\",\"ref\":\"المزمور ٩٠ (٩١) — السادسة\",\"v\":\"وعن يمينك ربوات، وأما أنت فلا يقتربون إليك. بل بعينيك تتأمل، ومجازاة الخطاة تبصر.\",\"r\":\"يعد المزمور أنه تسقط عن يسارك ألوف وعن يمينك ربوات وأنت لا يقتربون إليك، بل بعينيك تتأمل. عيون الإيمان تبصر ما لا تراه عيون الجسد، كما رأى خادم أليشع جبلًا مملوءًا خيلًا. اطلب اليوم من الله أن يفتح عينيك على حضوره.\",\"p\":\"يا رب، افتح عيني لأرى حضورك وحمايتك. ثبّتني بعيون الإيمان، فلا أخاف مما أراه. آمين.\",\"x\":\"عن يمينك ربوات وأنت لا يقتربون إليك، بل بعينيك تتأمل. عيون الإيمان ترى الحماية. تدريب: انظر إلى مشكلتك اليوم بعين الإيمان وقل: الله حاضر هنا.\"},{\"t\":\"الذين معنا أكثر\",\"ref\":\"الملوك الثاني ٦: ١٦\",\"bk\":\"الملوك الثاني\",\"v\":\"فقال: «لا تخف، لأن الذين معنا أكثر من الذين معهم».\",\"r\":\"«لا تخف، لأن الذين معنا أكثر من الذين معهم». ما يخيفني أحيانًا هو ما أراه فقط. لكن هناك حقيقة روحية أكبر لا تراها العين. فلأصلِّ مع أليشع: «يا رب افتح عيني فأبصر».\",\"p\":\"يا رب، افتح عيني لأرى جيشك المحيط بي. شدد قلبي وقت الخوف، واحفظني بملائكتك الأطهار. آمين.\",\"x\":\"حاصر الجيش الآرامي مدينة دوثان ليقبض على أليشع. فارتعب غلامه. وأليشع لم يطلب جيشًا، بل صلى أن تنفتح العينان. وقد رأى الغلام جيش السماء. هذه الحادثة تعلمنا أن الله يحيط بأولاده بحراسة غير مرئية. وتؤكد الكنيسة هذا في إيمانها بحراسة الملائكة. وفي القداس نصلي مع الملائكة. وفي الفزع نحتاج إلى بصيرة الإيمان أكثر من حسابات العقل. \\n\"},{\"t\":\"ما في الداخل\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال أحد الشيوخ للأب يوحنا الكولوفي: إبريقك مملوء سمًّا، فأجابه: لقد قلت هذا لأنك رأيت ما في الخارج فقط، ماذا كنت ستقول لو رأيت ما في الداخل أيضًا؟ عيون الإيمان تعترف بحقيقة النفس. اعترف اليوم بأعماق ضعفك لله وحده.\",\"p\":\"يا رب، أنت ترى ما في الداخل. طهّرني من الداخل واغفر لي ما لا يراه أحد. آمين.\",\"x\":\"قال أحد الشيوخ للأب يوحنا الكولوفي: إبريقك مملوء سمًّا، فأجابه: لقد قلت هذا لأنك رأيت ما في الخارج فقط، ماذا كنت ستقول لو رأيت ما في الداخل أيضًا؟ تدريب: لا تحكم اليوم بالظاهر على أحد، ولا على نفسك.\",\"fq\":152}]},\"11-18\":{\"th\":\"أمانة في الوقت المناسب\",\"m\":[{\"t\":\"عيناي على أمناء الأرض\",\"ref\":\"المزمور ١٠٠ (١٠١) — التاسعة\",\"v\":\"عيناي على جميع أمناء الأرض لكي أجلسهم معي. السالك في الطريق بلا عيب هذا كان يخدمني.\",\"r\":\"يقول المرنم: عيناي على جميع أمناء الأرض لكي أجلسهم معي، والسالك في الطريق بلا عيب هذا كان يخدمني. الأمانة في الوقت المناسب تُعرف بالخدمة الأمينة حين يطلبها الله. اسأل نفسك اليوم: ما الأمر الذي أصبح وقته الآن؟ وافعله.\",\"p\":\"يا رب، اجعلني أمينًا في وقتي. أعطني أن أخدمك بلا عيب فتجلسني مع أمنائك. آمين.\",\"x\":\"عيناي على أمناء الأرض لأجلسهم معي، والسالك بلا عيب هذا يخدمني. الأمانة في القليل تفتح الكثير. تدريب: أتمم اليوم عملًا صغيرًا بأمانة كاملة.\"},{\"t\":\"لوقت مثل هذا\",\"ref\":\"أستير ٤: ١٤\",\"bk\":\"أستير\",\"v\":\"لأنك إن سكت سكوتا في هذا الوقت يكون الفرج والنجاة لليهود من مكان آخر، وأما أنت وبيت أبيك فتبيدون. ومن يعلم إن كنت لوقت مثل هذا وصلت إلى الملك؟».\",\"r\":\"«ومن يعلم إن كنت لوقت مثل هذا وصلت إلى الملك؟». ربما وضعني الله في موقعي الحالي لسبب. وقد لا أرى الغاية الآن، لكنني أسأل: ما الذي يريده مني هنا؟ والصمت أمام الحق قد يضيع فرصة أمانة.\",\"p\":\"يا رب، ضعني حيث تريد وامنحني شجاعة أمانة في الوقت المناسب. لا تدعني أصمت حين يجب أن أتكلم، واستخدمني لخير شعبك. آمين.\",\"x\":\"كانت أستير الملكة اليهودية الخفية في بلاط فارس، وعرفت أن هامان يخطط لإبادة شعبها. فخافت من الذهاب للملك. فجاء كلام مردخاي كتحدٍّ. فقررت أن تصوم وتتقدم قائلة: «إذا هلكت هلكت». وصامت ثلاثة أيام قبل أن تتقدم. وتعلمنا القصة أن الله يعمل بتدبير غير مرئي وأن أمانتنا في لحظتها تصنع الفرق.\\nفكر في موقع تعمل فيه: أين يمكنك أن تتكلم بحق أو تخدم، لأنك هناك «لوقت مثل هذا»؟\"},{\"t\":\"اتّضع في السلام\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيساريوس: عندما تكون في سلام وغير محارب، اتّضع أكثر، فربما بدخول فرح غريب نفتخر فنُسلَّم للمعارك. أمانة الوقت أن نحرس السلام أيضًا. تواضع اليوم في لحظة نجاح أو راحة.\",\"p\":\"يا رب، احفظني من الافتخار في السلام. علّمني أن أتضع في الراحة كما في الضيق. آمين.\",\"x\":\"يقول الأب بيساريوس: عندما تكون في سلام وغير محارب اتّضع أكثر، فربما بدخول فرح غريب نفتخر فنُسلَّم للمعارك، لأن الله لا يسمح كثيرًا بتسليمنا إليها بسبب ضعفنا. تدريب: اشكر الله اليوم على سلامك ولا تفتخر به.\",\"fq\":81}]},\"11-19\":{\"th\":\"تواضع وصلاة ورجوع\",\"m\":[{\"t\":\"وجهك يا رب ألتمس\",\"ref\":\"المزمور السادس والعشرون — باكر\",\"v\":\"استمع يا رب صوتي الذي به دعوتك. ارحمني واستجب لي فإنه لك قال قلبي: طلبت وجهك. ووجهك يا رب ألتمس.\",\"r\":\"يصرخ المرنم بصوته إلى الله ويطلب وجهه، قائلاً قلبي طلب وجهك. شرط الاستجابة تواضع وصلاة وطلب وجه ورجوع. اجلس اليوم دقائق تقول فيها: وجهك يا رب ألتمس.\",\"p\":\"استمع يا رب صوتي الذي به دعوتك. ارحمني واستجب لي، ووجهك يا رب ألتمس. آمين.\",\"x\":\"استمع يا رب صوتي، قال قلبي: طلبت وجهك، ووجهك يا رب ألتمس. الاستجابة تحتاج تواضعًا وصلاة وطلب وجه ورجوعًا. تدريب: اجلس دقائق أمام الله بلا قائمة طلبات.\"},{\"t\":\"إن تواضع شعبي وصلوا\",\"ref\":\"أخبار الأيام الثاني ٧: ١٤\",\"bk\":\"أخبار الأيام الثاني\",\"v\":\"فإذا تواضع شعبي الذين دعي اسمي عليهم وصلوا وطلبوا وجهي، ورجعوا عن طرقهم الردية فإنني أسمع من السماء وأغفر خطيتهم وأبرئ أرضهم.\",\"r\":\"«فإذا تواضع شعبي… وصلوا وطلبوا وجهي ورجعوا عن طرقهم الردية فإنني أسمع من السماء وأغفر». أربع خطوات: تواضع، صلاة، طلب وجه الله، ورجوع عن الشر. والنتيجة سماع وغفران وشفاء. وأنا أبدأ من نفسي.\",\"p\":\"يا رب، أتواضع أمامك وأصلي وأطلب وجهك. أرجع عن طرقي الردية، فاسمع من السماء واغفر وأبرئ أرضنا وكنيستنا. آمين.\",\"x\":\"هذا الوعد جاء بعد صلاة سليمان في تدشين الهيكل. والله يتجاوب مع الشعب بالوعد. والتواضع أول شرط، ثم الصلاة وطلب الوجه، وهو يعني الاشتياق إلى الحضور، ثم التغيير الفعلي بالرجوع. فلا تكفي الكلمات. وتتوافق هذه الخطوات مع مراحل التوبة في كنيستنا: اعتراف وندم وعزم وتغيير. و«أبرئ أرضهم» يشير إلى أن توبة الشعب تشفي المجتمع كله.\\nاختر اليوم خطوة تغيير ملموسة تتبع صلاتك، كمصالحة أو ترك عادة، واجعلها جزءًا من توبتك.\"},{\"t\":\"افحص ضميرك\",\"ref\":\"\",\"v\":\"\",\"r\":\"ينصح الأب أور: عندما يأتيك فكر التشامخ افحص ضميرك هل حفظت كل الوصايا وأحببت كل أعدائك، واعتبر نفسك عبدًا بطّالًا وخاطئًا أكثر من جميع الناس. الرجوع إلى الله يبدأ بكسر الكبرياء. افحص اليوم ضميرك ثلاث دقائق.\",\"p\":\"يا رب، اكسر كبريائي وأرجعني إليك. أعطني أن أرى نفسي عبدًا بطّالًا محتاجًا لرحمتك. آمين.\",\"x\":\"ينصح الأب أور: عندما يأتيك فكر التشامخ افحص ضميرك هل حفظت كل الوصايا وأحببت كل أعدائك، واعتبر نفسك عبدًا بطالًا وخاطئًا أكثر من الجميع. الفحص يكسر الكبرياء. تدريب: طبق هذا الفحص عند أول فكر كبرياء.\",\"fq\":562}]},\"11-20\":{\"th\":\"الذين ردوا كثيرين إلى البر\",\"m\":[{\"t\":\"أظهر عجائبه لقديسيه\",\"ref\":\"المزمور الخامس عشر — باكر\",\"v\":\"أظهر عجائبه لقديسيه الذين في أرضه؛ وصنع فيهم كل مشيئاته.\",\"r\":\"أظهر الرب عجائبه لقديسيه الذين في أرضه وصنع فيهم كل مشيئاته. الذين يردون كثيرين إلى البر يضيئون كالكواكب، وقد صنع الله فيهم مشيئته أولًا. ارجع اليوم إلى حياتك الخاصة قبل أن تنصح أحدًا.\",\"p\":\"يا رب، اصنع فيّ مشيئتك لأكون سببًا في رجوع كثيرين إليك. ولا تدع أحدًا يتعثر بسببي. آمين.\",\"x\":\"أظهر الرب عجائبه لقديسيه وصنع فيهم كل مشيئاته. الذين يردون كثيرين إلى البر يضيئون كالكواكب. تدريب: كلّم اليوم شخصًا بعيدًا بكلمة محبة.\"},{\"t\":\"الفاهمون يضيئون\",\"ref\":\"دانيال ١٢: ٣\",\"bk\":\"دانيال\",\"v\":\"والفاهمون يضيئون كضياء الجلد، والذين ردوا كثيرين إلى البر كالكواكب إلى أبد الدهور.\",\"r\":\"«والفاهمون يضيئون كضياء الجلد، والذين ردوا كثيرين إلى البر كالكواكب إلى أبد الدهور». رد النفوس إلى الله أعظم عمل. وكل خدمة مهما كانت صغيرة، إذا قادت أحدًا إلى المسيح، لها مجد أبدي.\",\"p\":\"يا رب، اجعلني أضيء بنورك وأرد كثيرين إلى البر. استخدمني في خدمة النفوس، واقبل تعبي القليل لمجد اسمك. آمين.\",\"x\":\"تأتي هذه الآية في ختام سفر دانيال بعد الحديث عن القيامة. والأبرار في القيامة يضيئون. و«الفاهمون» هم الحكماء الأتقياء. وتشير الآية إلى أن الخدمة الروحية لها ثمر أبدي. وهذه تعزية للخدام الذين يتعبون في مدارس الأحد والافتقاد. فقد لا يرون الثمر، لكنه محفوظ لهم. وقد تأثر آباء الرهبنة بهذه الآية في سعيهم لخلاص النفوس. وكل نفس ترجع هي مجد للسماء.\\nاليوم، قل كلمة واحدة تقود أحدًا نحو المسيح: دعوة لحضور قداس أو ترنيمة أو آية.\"},{\"t\":\"عبثًا يكون التعب\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب موسى الحبشي: إذا لم تتفق الصلاة مع السيرة عبثًا يكون التعب، فلا نعمل ما نصلّي من أجله. من يردّ كثيرين إلى البر تتفق صلاته مع سيرته. اجعل اليوم صلاتك وسلوكك في خط واحد.\",\"p\":\"يا رب، وحّد صلاتي وسيرتي. اجعل حياتي شاهدة لما أطلبه في صلاتي. آمين.\",\"x\":\"يقول الأب موسى الحبشي: إذا لم تتفق الصلاة مع السيرة عبثًا يكون التعب، فلا نعمل ما نصلي من أجله، لأن الإنسان إذا تخلى عن مشيئته يتصالح مع الله. تدريب: اعمل اليوم بما صليت لأجله.\",\"fq\":264}]},\"11-21\":{\"th\":\"عيد رئيس الملائكة ميخائيل\",\"m\":[{\"t\":\"يوصي ملائكته بك\",\"ref\":\"المزمور ٩٠ (٩١) — السادسة\",\"v\":\"لأنه يوصى ملائكته بك؛ ليحفظوك في سائر طرقك. وعلى أيديهم يحملونك، لئلا تعثر بحجر رجلك.\",\"r\":\"في عيد رئيس الملائكة ميخائيل نتذكر أن الله يوصي ملائكته بنا ليحفظونا في كل طرقنا. على أيديهم يحملوننا لئلا نعثر. ارفع اليوم صلاة قصيرة إلى الملاك الحارس وإلى القديس ميخائيل.\",\"p\":\"يا رب، أوصِ ملائكتك بي ليحفظوني في سائر طرقي. بشفاعة الملاك ميخائيل احرسني ولا تعثّرني. آمين.\",\"x\":\"يوصي الله ملائكته بك ليحفظوك في كل طرقك، وعلى أيديهم يحملونك. في عيد ميخائيل نتذكر الحماية. تدريب: قل اليوم صلاة قصيرة لميخائيل رئيس الملائكة، واشكره.\"},{\"t\":\"ميخائيل الرئيس العظيم\",\"ref\":\"دانيال ١٢: ١\",\"bk\":\"دانيال\",\"v\":\"«وفي ذلك الوقت يقوم ميخائيل الرئيس العظيم القائم لبني شعبك، ويكون زمان ضيق لم يكن منذ كانت أمة إلى ذلك الوقت. وفي ذلك الوقت ينجى شعبك، كل من يوجد مكتوبا في السفر.\",\"r\":\"«وفي ذلك الوقت يقوم ميخائيل الرئيس العظيم القائم لبني شعبك… ينجى شعبك، كل من يوجد مكتوبًا في السفر». في أيام الضيق لا يترك الله شعبه. وأنا أطلب شفاعة رئيس الملائكة، وأثق أن اسمي مكتوب في سفر الحياة.\",\"p\":\"يا رب، أشكرك على رئيس الملائكة ميخائيل وكل جنودك السماويين. احفظنا بشفاعتهم، واكتب أسماءنا في سفر الحياة. آمين.\",\"x\":\"تحتفل الكنيسة القبطية في الثاني عشر من هاتور بعيد رئيس الملائكة الجليل ميخائيل، شفيع الكنيسة وحامي المؤمنين في تقليدها. وتدل نبوة دانيال على مكانته: «الرئيس العظيم القائم لبني شعبك». ومعنى اسمه «من مثل الله»، وهو يذكّرنا بأن الله وحده الإله. ولا نعبد الملائكة بل نطلب شفاعتهم ونشكر الله على خدمتهم. والتعزية الكبرى في الآية: «كل من يوجد مكتوبًا في السفر ينجى».\\nاليوم، قدّم صلاة شكر لله على حراسة ملائكته، وردد طلبة: «يا ميخائيل رئيس الملائكة اشفع فينا».\"},{\"t\":\"أصوات الملائكة\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب بيمن للإخوة الذين أرادوا أن يرحلوا من مكان بسبب أديرته: وهل تغادرون المكان بسبب أصوات الملائكة؟ الملائكة حاضرون حيث نصلي. ابقَ اليوم في حضرتهم، واحتمل ضجيج الصلاة بفرح.\",\"p\":\"يا رب، افتح أذني لأسمع تسبيح ملائكتك. اجعلني أحب مكان الصلاة ولا أنفر منه. آمين.\",\"x\":\"قال الأب بيمن للإخوة الذين أرادوا الرحيل بسبب صخب أديرة جاورتهم: وهل تغادرون المكان بسبب أصوات الملائكة؟ الصوت المقدس لا يزعج. تدريب: لا تشتكِ اليوم من ضوضاء الكنيسة أو الخدمة.\",\"fq\":428}]},\"11-22\":{\"th\":\"ملاك الرب حال حول خائفيه\",\"m\":[{\"t\":\"اسجدوا لله يا جميع ملائكته\",\"ref\":\"المزمور ٩٦ (٩٧) — التاسعة\",\"v\":\"اسجدوا لله يا جميع ملائكته.\",\"r\":\"يدعو المزمور جميع ملائكة الله أن يسجدوا له. وملاك الرب يحل حول خائفيه وينجيهم. الملائكة خدام الله وأرواح مرسلة لخدمة العتيدين أن يرثوا الخلاص. اشكر الله اليوم على ملائكته، وصلِّ بتسبيحهم: قدوس قدوس قدوس.\",\"p\":\"يا رب، لتسجد لك ملائكتك، وأسجد أنا معهم. احفظني بملاكك الحارس، وأنجني من كل شر. آمين.\",\"x\":\"يدعو المزمور جميع ملائكة الله أن يسجدوا له، وملاك الرب يحل حول خائفيه وينجيهم. تدريب: ابدأ صلاتك اليوم بسجدة مع الملائكة.\"},{\"t\":\"ملاك الرب حال حول خائفيه\",\"ref\":\"المزامير ٣٤: ٧\",\"bk\":\"المزامير\",\"v\":\"ملاك الرب حال حول خائفيه، وينجيهم.\",\"r\":\"«ملاك الرب حال حول خائفيه وينجيهم». لا أرى هذا الملاك، لكن الكلمة تؤكد أنه محيط بي. والشرط هو مخافة الرب. وعندما أنام وأسير وأعمل، يحرسني ملاك، فلأشكر الله على ذلك.\",\"p\":\"يا رب، أشكرك على ملاك حراستي. احفظني وبيتي وأحبائي بحراسته، وأعطني مخافتك فلا أخاف شيئًا غيرك. آمين.\",\"x\":\"المزمور ٣٤ مزمور شكر لداود بعد أن نجا من أبيمالك. وكلمة «حال» تعني معسكر حولهم. والصورة جيش يحيط بخائفي الرب. وتقول الكنيسة في صلاة النوم والأجبية: «ملاك الرب يحل حول خائفيه». وقد علّم الآباء أن لكل مؤمن ملاكًا حارسًا. والشرط هو مخافة الرب وليس الخوف من الشر. فمن يخاف الله لا يخاف غيره. وفي آخر المزمور: «ذوقوا وانظروا ما أطيب الرب».\\nاليوم، قبل النوم، اشكر الله على ملاك حراستك، وقل: «ملاك الرب حال حولي».\"},{\"t\":\"إرادة واحدة\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب أرسانيوس: القوات السماوية وآلاف الطغمات العلوية عندها إرادة واحدة، أما البشر فبإراداتهم كثيرة. الملائكة ينفذون مشيئة الله بوحدة كاملة. اجعل اليوم إرادتك واحدة مع مشيئة الله في قرار تتردد فيه.\",\"p\":\"يا رب، وحّد إرادتي بإرادتك كما توحد الملائكة. علّمني أن أقول: لتكن مشيئتك. آمين.\",\"x\":\"قال الأب أرسانيوس: يعلم الله أني أحبكم إلا أني لا أقدر أن أكون مع الله ومع الناس، فالقوات السماوية عندها إرادة واحدة أما البشر فبإراداتهم كثيرة. الملائكة وحدة إرادة. تدريب: اجعل إرادتك اليوم واحدة مع إرادة الله.\",\"fq\":33}]},\"11-23\":{\"th\":\"فرح الملائكة بالتائب\",\"m\":[{\"t\":\"صرخت في حزني فاستجبت لي\",\"ref\":\"المزمور ١١٩ (١٢٠) — الغروب\",\"v\":\"إليك يا رب صرخت في حزني فاستجبت لي.\",\"r\":\"يشهد المرنم أنه صرخ في حزنه فاستجاب الرب. وحين يعود الخاطئ إلى الله يفرح الملائكة. توبتك تفرح السماء قبل أن تفرحك. ارجع اليوم إلى الله بصلاة قصيرة وتخيل فرح الملائكة بك.\",\"p\":\"يا رب، صرخت إليك في حزني فاستجبت لي. اقبل توبتي وافرح بعودتي، وليفرح ملائكتك بي. آمين.\",\"x\":\"صرخت إليك في حزني فاستجبت لي. وحين يعود الخاطئ تفرح الملائكة، فتوبتك فرح في السماء. تدريب: عد اليوم إلى الله من خطية متكررة، وافرح بفرح الملائكة.\"},{\"t\":\"فرح قدام ملائكة الله\",\"ref\":\"لوقا ١٥: ١٠\",\"bk\":\"لوقا\",\"v\":\"هكذا، أقول لكم: يكون فرح قدام ملائكة الله بخاطئ واحد يتوب.\",\"r\":\"«يكون فرح قدام ملائكة الله بخاطئ واحد يتوب». توبتي تُحدث فرحًا في السماء. ولا أحتاج أن أنتظر لأتب بعد أن أكمل. فكل خطوة رجوع تفرح الملائكة. وهذا يرفع عني الشعور بالخجل.\",\"p\":\"يا رب، أشكرك لأن السماء تفرح بتوبتي. خذ بيدي إلى الاعتراف الصادق، واجعلني سبب فرح لملائكتك بدل الحزن. آمين.\",\"x\":\"الآية خاتمة مثلي الخروف الضال والدرهم المفقود في لوقا ١٥. وبعدهما مثل الابن الضال. وفي المثلين الأولين الباحث يفرح ويدعو أصدقاءه. فالتوبة عيد. وتصور الآية الملائكة كمشاهدين متحمسين لعمل النعمة. وهذا يغير نظرتنا للاعتراف: ليس موقف عقاب بل مناسبة فرح. وقد كان القديسون يرون الملائكة في مجلس التوبة. والتائب لا يقف وحده.\\nإن كنت متأخرًا في التوبة، اتخذ اليوم قرارًا بالاعتراف الأسبوع المقبل وحدد موعدًا.\"},{\"t\":\"النوح الدائم\",\"ref\":\"\",\"v\":\"\",\"r\":\"رأى الأب بيمن امرأة تبكي بمرارة عند قبر، فقال: لو انسكبت كل مباهج هذه الدنيا لا تقدر أن ترفع النوح عن نفس هذه المسكينة، وهكذا الراهب يجب أن يقتني النوح في قلبه على الدوام. النوح الصادق على الخطية يفرح السماء. ابك اليوم بصدق على خطية واحدة، ثم ارفع شكرك.\",\"p\":\"يا رب، أعطني نوحًا صادقًا على خطاياي لا يغادر قلبي. وحوّل نوحي إلى فرح بغفرانك. آمين.\",\"x\":\"رأى الأب بيمن امرأة تبكي بمرارة عند قبر فقال: لو انسكبت كل مباهج هذه الدنيا لا تقدر أن ترفع النوح عن نفس هذه المسكينة، هكذا الراهب يجب أن يقتني النوح في قلبه على الدوام. تدريب: اطلب دموع توبة صادقة.\",\"fq\":326}]},\"11-24\":{\"th\":\"قدوس قدوس قدوس\",\"m\":[{\"t\":\"قدوس هو\",\"ref\":\"المزمور ٩٨ (٩٩) — التاسعة\",\"v\":\"ارفعوا الرب إلهنا واسجدوا لموطئ قدميه فإنه قدوس هو.\",\"r\":\"يدعونا المزمور أن نرفع الرب إلهنا ونسجد لموطئ قدميه لأنه قدوس. وفي السماء يقول الملائكة: قدوس قدوس قدوس. الاقتراب من القداسة يبدأ بخضوع القلب. قف اليوم دقيقة صامتًا وانحنِ في داخلك، وقل ثلاث مرات: قدوس قدوس قدوس.\",\"p\":\"يا رب القدوس، أرفعك وأسجد لك. اجعلني أقترب منك بخشوع، وقدّسني بقداستك. آمين.\",\"x\":\"ارفعوا الرب إلهنا واسجدوا لموطئ قدميه فإنه قدوس. وفي السماء ينشد الملائكة قدوس قدوس قدوس. تدريب: قل قدوس قدوس قدوس ببطء ثلاث مرات الآن.\"},{\"t\":\"السرافيم واقفون فوقه\",\"ref\":\"إشعياء ٦: ٢\",\"bk\":\"إشعياء\",\"v\":\"السرافيم واقفون فوقه، لكل واحد ستة أجنحة، باثنين يغطي وجهه، وباثنين يغطي رجليه، وباثنين يطير.\",\"r\":\"«باثنين يغطي وجهه، وباثنين يغطي رجليه، وباثنين يطير». حتى السرافيم تخشع أمام الله. وأنا أدخل الصلاة أحيانًا بلا خشوع. فأتعلم منهم أن أغطي وجهي بالتواضع وأطير بالطاعة. ومن يخشع يقترب أكثر.\",\"p\":\"يا قدوس يا قدوس يا قدوس، علمني الخشوع في حضرتك. طهّر شفتيّ وقلبي، واجعلني مستعدًا أن أقول: هأنذا أرسلني. آمين.\",\"x\":\"الصورة هنا جزء من رؤيا إشعياء في الهيكل، حين سمع السرافيم ينادون: «قدوس قدوس قدوس رب الجنود». فالتغطية بجناحين تعني الاحتشام أمام جلال الله، والطيران يعني الخدمة. وتحمل الكنيسة هذا النشيد في القداس. وبعد سماع التسبيح اعترف إشعياء بنجاسة شفتيه فطهّره السرافيم بجمرة. أي أن اللقاء بقدوسية الله يقود إلى التوبة. ومنها إلى الإرسال: «هأنذا أرسلني».\\nعند دخولك الصلاة اليوم، قف دقيقة صامتة بخشوع، ثم ابدأ.\"},{\"t\":\"دون الخليقة كلها\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل أخ الأب سيسوى: أرى أن ذكر الله يبقى في داخلي، فأجابه أن المهم حقًّا أن تعاين نفسك دون الخليقة كلها، لأن هذا يقود مع التعب الجسدي إلى سبيل التواضع. من يرى قداسة الله يرى صغر نفسه. قل اليوم: أنا لا شيء أمام قداستك.\",\"p\":\"يا رب القدوس، علّمني أن أراك عظيمًا وأرى نفسي صغيرًا. وقدّسني بتواضع حقيقي. آمين.\",\"x\":\"لأخ قال إن ذكر الله يبقى في داخله أجابه الأب سيسوى: ليس بالأمر الهام أن يكون فكرك مع الله، المهم حقًّا أن تعاين نفسك دون الخليقة كلها لأن هذا يقود مع التعب الجسدي إلى سبيل التواضع. تدريب: اعتبر نفسك اليوم أقل من كل أحد.\",\"fq\":490}]},\"11-25\":{\"th\":\"بدء صوم الميلاد\",\"m\":[{\"t\":\"فلتفرح السماوات\",\"ref\":\"المزمور ٩٥ (٩٦) — التاسعة\",\"v\":\"فلتفرح السموات ولتبتهج الأرض وليعج البحر وجميع ملئه.\",\"r\":\"تفرح السماوات وتبتهج الأرض لأن الرب آتٍ. نبدأ اليوم صوم الميلاد بفرح، فنحن نصوم لنستقبل مولودًا لا لنحزن. حدد اليوم نوع صومك لهذه الأربعين: طعام أو ترفيه أو كلام، وقدمه لله بفرح.\",\"p\":\"يا رب، لتفرح السماوات وتبتهج الأرض بمجيئك. بارك صومنا واجعله استعدادًا صادقًا لاستقبالك. آمين.\",\"x\":\"تفرح السماوات وتبتهج الأرض لأن الرب آتٍ. نصوم لنستقبل مولودًا لا لنحزن. تدريب: حدد اليوم ما ستصومه في الميلاد، وبشر به أحدًا.\"},{\"t\":\"هوذا إلهكم يأتي\",\"ref\":\"إشعياء ٣٥: ٤\",\"bk\":\"إشعياء\",\"v\":\"قولوا لخائفي القلوب: «تشددوا لا تخافوا. هوذا إلهكم. الانتقام يأتي. جزاء الله. هو يأتي ويخلصكم».\",\"r\":\"«قولوا لخائفي القلوب: تشددوا لا تخافوا. هوذا إلهكم… هو يأتي ويخلصكم». اليوم تبدأ الكنيسة صوم الميلاد، وصوتها: لا تخافوا، الرب آت. فأبدأ هذا الصوم بالرجاء لا بالثقل. وصيامي استقبال لا حرمان.\",\"p\":\"يا رب، أبدأ صوم ميلادك بالرجاء. شددني ولا تدعني أخاف، وهيئ قلبي مذودًا نقيًا لاستقبالك في الميلاد. آمين.\",\"x\":\"الأصحاح ٣٥ من إشعياء قصيدة فرح بمجيء الله، تحول فيها البرية إلى جنة. وفي صوم الميلاد نقرأ نبوات تحمل نفس الروح. والصوم هنا ليس تقشفًا بل تهيئة لاستقبال العريس. والكنيسة القبطية تصوم ٤٣ يومًا قبل عيد الميلاد، مع التسابيح والقراءات. والصوم يعلمنا ضبط النفس والتوبة والاشتياق. وقد قال الآباء إن الميلاد لا يُستقبل في قلب مزدحم، بل في قلب فارغ للرب.\\nحدد اليوم قاعدة صوم واضحة لهذه الأيام، بمشورة أب الاعتراف، وسجل نية صومك.\"},{\"t\":\"الصوم والمحبة\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب سلوان لتلميذه الذي أراد أن يشرب في الطريق بعد أن أكلا قليلًا في دير: ما أكلناه كان من المحبة، أما هنا فلنحتفظ بصيامنا يا ولدي. الصوم يحفظ ولا يتصلب أمام المحبة. اجعل صومك هذه الأيام ثمرة محبة لا قسوة.\",\"p\":\"يا رب، علّمني صومًا يجمع النسك بالمحبة. احفظ أصوامي ببساطة وتواضع. آمين.\",\"x\":\"بعد أن أكل الأب سلوان وتلميذه قليلًا في دير قال لتلميذه الذي أراد أن يشرب في الطريق: ما أكلناه كان من المحبة، أما هنا فلنحتفظ بصيامنا يا ولدي. الصوم يلتزم به خارجًا أيضًا. تدريب: التزم صيامك اليوم في كل مكان.\",\"fq\":509}]},\"11-26\":{\"th\":\"الموعد منذ القديم\",\"m\":[{\"t\":\"قال الرب لربي\",\"ref\":\"المزمور ١٠٩ (١١٠) — التاسعة\",\"v\":\"قال الرب لربي: اجلس عن يميني حتى أضع أعداءك تحت موطئ قدميك. عصا قوة يرسل لك الرب من صهيون وتسود في وسط أعدائك.\",\"r\":\"يعلن المزمور عن ملك يجلس عن يمين الرب ويسود في وسط أعدائه. هذا الوعد القديم صار حقيقة في المسيح. اقرأ اليوم نبوة من سفر التكوين أو العدد وتأمل كيف تحققت في الميلاد.\",\"p\":\"يا رب، أنت الملك الجالس عن يمين الآب. أشكرك لأنك أتممت وعودك القديمة في ابنك. آمين.\",\"x\":\"قال الرب لربي: اجلس عن يميني، عصا قوة يرسل لك الرب من صهيون. هذا الوعد القديم تحقق في المسيح. تدريب: اقرأ اليوم نبوة عن الميلاد، مثل إشعياء ٧: ١٤.\"},{\"t\":\"حتى يأتي شيلون\",\"ref\":\"التكوين ٤٩: ١٠\",\"bk\":\"التكوين\",\"v\":\"لا يزول قضيب من يهوذا ومشترع من بين رجليه حتى يأتي شيلون وله يكون خضوع شعوب.\",\"r\":\"«لا يزول قضيب من يهوذا… حتى يأتي شيلون وله يكون خضوع شعوب». قبل آلاف السنين وعد الله بمجيء المسيح. ووعد الله لا يتأخر ولا يسقط. وإن بدا الانتظار طويلًا، فالله يعرف الوقت المعين.\",\"p\":\"يا رب، وعدك صادق وإن طال الانتظار. ثبت إيماني بمجيئك، وأعطني صبرًا في انتظار وعودك لحياتي وكنيستك. آمين.\",\"x\":\"كلمة شيلون فُسرت بمعنى «الذي له» أو «صاحب الأمر»، ورأى الآباء فيها المسيح. وقد جاء المسيح من سبط يهوذا. وتشير النبوة إلى أن الملك سيدوم حتى يأتي، وبعدها تخضع له الشعوب. وهذا تحقق في الكنيسة التي ضمت أممًا كثيرة. وتعلمنا النبوة أن الله يمهد لخطته عبر الأجيال. وصوم الميلاد فرصة لتأمل هذا التمهيد الطويل.\\nاذكر اليوم وعدًا أنتظر تحققه من الله، وجدد ثقتك بأن الله لا يتأخر.\"},{\"t\":\"لم تكن عليه تهمة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن لأخ سأله كيف يسلك الإنسان: نرى دانيال أنه لم تكن عليه تهمة إلا في خدمة الرب إلهه. أمانة المنتظرين للوعد تُعرف بتمسكهم بخدمة الله حتى لو اتُّهموا. اثبت اليوم في خدمتك لله ولو لم يفهمك الناس.\",\"p\":\"يا رب، ثبّتني في خدمتك كدانيال. أعطني ألا يكون لي ذنب إلا في أمانتي لك. آمين.\",\"x\":\"لأخ سأل كيف يسلك الإنسان قال الأب بيمن: نرى دانيال أنه لم تكن عليه تهمة إلا في خدمة الرب إلهه. الأمانة الكاملة لا تُتهم إلا بإيمانها. تدريب: كن أمينًا اليوم حتى لو اتُّهمت بسببه.\",\"fq\":351}]},\"11-27\":{\"th\":\"الملك والابن\",\"m\":[{\"t\":\"أنت ابني\",\"ref\":\"المزمور الثاني — باكر\",\"v\":\"أنا أقمته ملكا على صهيون جبل قدسه. لأكرز بأمر الرب. الرب قال لي: أنت ابني، وأنا اليوم ولدتك.\",\"r\":\"يعلن الرب: أنا أقمته ملكًا على صهيون جبل قدسه، وأنت ابني وأنا اليوم ولدتك. هذا هو الملك الذي ننتظره في الميلاد، ملك تواضع ليخلصنا. تأمل اليوم في المسيح الملك والابن الذي دعاك أيضًا ابنًا.\",\"p\":\"يا رب، أنت الملك وابن الله. أشكرك لأنك جعلتني ابنًا لك بنعمتك. ليكن ملكك في قلبي. آمين.\",\"x\":\"أنا أقمته ملكًا على صهيون، أنت ابني وأنا اليوم ولدتك. هذا الملك المنتظر جاء في الميلاد. تدريب: قل للمسيح اليوم: أنت ملكي، وسلّم له مجالًا من حياتك.\"},{\"t\":\"أنت ابني أنا اليوم ولدتك\",\"ref\":\"المزامير ٢: ٧\",\"bk\":\"المزامير\",\"v\":\"إني أخبر من جهة قضاء الرب: قال لي: «أنت ابني، أنا اليوم ولدتك.\",\"r\":\"«قال لي: أنت ابني، أنا اليوم ولدتك». سر البنوة هو سر الميلاد. والابن الأزلي سيأتي في ملء الزمان. وبهذا السر صرت أنا أيضًا ابنًا بالتبني. فلأقترب من الآب بثقة الأبناء.\",\"p\":\"يا أبانا السماوي، أشكرك لأنك ولدتنا بابنك الوحيد وجعلتنا أبناء. ثبتنا في بنوتنا، وأعطنا روح الثقة والمحبة. آمين.\",\"x\":\"المزمور ٢ مزمور ملوكي مسياني. تقتبسه الرسالة إلى العبرانيين لتثبت أن المسيح أعظم من الملائكة. وقد قاله الآب عند معمودية الرب. وتتناول الكنيسة هذه الآية في أعياد الميلاد والظهور الإلهي، موضحة أن بنوة المسيح أزلية. وكلمة «اليوم» ترمز إلى الأبدية التي لا تقاس بالزمن. ونحن نتبنى بالمسيح ونصرخ «يا أبانا». وهذا هو سر عيد الميلاد: الابن جاء ليجعلنا أبناء.\\nافتتح صلاتك اليوم بقول: «أبانا الذي في السماوات»، وتأمل في كلمة «أبانا» وحدها.\"},{\"t\":\"غربة وفقر وصمت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب أندراوس: الراهب تناسبه هذه الثلاثة: غربة وفقر وصمت مع صبر. الملك الذي ننتظره جاء غريبًا وفقيرًا وصامتًا في المذود. اختر اليوم أن تعيش لحظة بساطة وصمت كملكك.\",\"p\":\"يا رب، أعطني أن أحب غربتك وفقرك وصمتك. ليكن لي فيك سلام الاكتفاء. آمين.\",\"x\":\"يقول الأب أندراوس: الراهب تناسبه هذه الثلاثة: غربة وفقر وصمت مع صبر. والملك الذي ننتظره جاء غريبًا وفقيرًا وصامتًا. تدريب: اختر اليوم واحدة من الثلاثة.\",\"fq\":78}]},\"11-28\":{\"th\":\"الرحمة والحق التقيا\",\"m\":[{\"t\":\"أرسل الله رحمته وحقه\",\"ref\":\"المزمور ٥٦ (٥٧) — السادسة\",\"v\":\"أرسل الله رحمته وحقه.\",\"r\":\"يعلن المرنم أن الله أرسل رحمته وحقه. في الميلاد التقت الرحمة والحق، والبر والسلام تلاقيا. أرسل اليوم رحمة إلى أحد: رسالة أو زيارة أو كلمة تسامح.\",\"p\":\"يا رب، أرسلت رحمتك وحقك إلينا. اجعل في قلبي رحمة تلتقي بالحق، وسلامًا يحمل البر. آمين.\",\"x\":\"أرسل الله رحمته وحقه، وفي الميلاد التقت الرحمة والحق وتلاقى البر والسلام. تدريب: أرسل اليوم رحمة إلى شخص بكلمة أو عطية.\"},{\"t\":\"الرحمة والحق التقيا\",\"ref\":\"المزامير ٨٥: ١٠\",\"bk\":\"المزامير\",\"v\":\"الرحمة والحق التقيا. البر والسلام تلاثما.\",\"r\":\"«الرحمة والحق التقيا. البر والسلام تلاثما». في المسيح التقت الرحمة بالحق، فلا الله يتجاهل الخطية ولا يهلك الخاطئ. وأنا أرى في الميلاد هذا اللقاء: محبة تنزل لتتحمل العدل.\",\"p\":\"يا رب، في تجسدك التقت الرحمة بالحق والبر بالسلام. علمني أن أحيا بهذا التوازن، وأن أنشر سلامك بحق ورحمة. آمين.\",\"x\":\"يفسر الآباء هذه الآية بأنها تتحقق في التجسد والفداء: العدل الإلهي يطلب العقاب، والرحمة تطلب النجاة، فالتقيا في صليب المسيح. وصور القبلات (تلاثما) تعبر عن مصالحة. وتحتفل الكنيسة بهذا في عيد البشارة والميلاد. وهذا يعلمنا كيف نحل الخلافات بيننا: بحق ورحمة معًا، فلا حق بلا رحمة ولا رحمة بلا حق. والسلام ثمرتهما.\\nاليوم، في خلاف أو موقف صعب، حاول أن تجمع بين قول الحق ورحمة الأسلوب.\"},{\"t\":\"بهدوء وسكينة\",\"ref\":\"\",\"v\":\"\",\"r\":\"سُئل الأب أمون: لماذا تصعد إلى مركب خاص وأنت تحيك الخوص؟ فقال: لكي لا أجاري أفكاري، وهذا كان مثلًا لنا لنسلك طريق الرب بهدوء وسكينة. السلام يبدأ بألا نجاري كل فكر. خذ اليوم لحظة هدوء قبل الرد على فكر يستفزك.\",\"p\":\"يا رب، علّمني أن أسلك بهدوء وسكينة. لا أجاري أفكاري بل أسلمها لسلامك. آمين.\",\"x\":\"سُئل الأب أمون لماذا يصعد إلى مركب خاص وهو يحيك الخوص، فقال: لكي لا أجاري أفكاري، وهذا كان مثلًا لنا لنسلك طريق الرب بهدوء وسكينة. تدريب: ابتعد اليوم عن مكان يجرّ أفكارك.\",\"fq\":63}]},\"11-29\":{\"th\":\"قومي استنيري\",\"m\":[{\"t\":\"لتشرق فينا الحواس المضيئة\",\"ref\":\"قطعة باكر (٢)\",\"v\":\"إذا ما دخل إلينا وقت الصباح أيها المسيح إلهنا النور الحقيقي، فلتشرق فينا الحواس المضيئة والأفكار النورانية، ولا تغطينا ظلمة الآلام، لكي نسبحك عقليًا مع داود قائلين: سبقت عيناي وقت السحر لأتلو في جميع أقوالك.\",\"r\":\"تصلي الكنيسة عند الصباح أن يشرق النور الحقيقي في حواسنا وأفكارنا فلا تغطينا ظلمة الآلام. قومي استنيري لأن نورك قد جاء. ابدأ اليوم بفتح نافذة وتنفس عميق وصلاة تدخل فيها نور الله إلى كل حواسك.\",\"p\":\"يا مسيح النور الحقيقي، أشرق في حواسي وأفكاري. ولا تدع ظلمة الألم تغطيني. آمين.\",\"x\":\"عند الصباح نطلب أن يشرق النور الحقيقي في حواسنا وأفكارنا فلا تغطينا ظلمة الآلام. قومي استنيري لأن نورك قد جاء. تدريب: افتتح يومك بقولك: يا نور العالم أشرق عليّ.\"},{\"t\":\"قومي استنيري\",\"ref\":\"إشعياء ٦٠: ١\",\"bk\":\"إشعياء\",\"v\":\"«قومي استنيري لأنه قد جاء نورك، ومجد الرب أشرق عليك.\",\"r\":\"«قومي استنيري لأنه قد جاء نورك، ومجد الرب أشرق عليك». النور جاء، وعلي أن أقوم من نومي الروحي. فالاستنارة ليست جهدًا مني بل قبول لنور وصل إلي. وهذا يدعوني إلى النهوض ومواجهة الفتور.\",\"p\":\"يا نور الكنيسة، أيقظني من نومي الروحي. أشرق علي وأنرني، واجعلني أعكس نورك لكل من حولي. آمين.\",\"x\":\"الأصحاح ٦٠ يصور مجد الكنيسة المشرقة بنور الله. وتقرأ الكنيسة هذا النص في عيد الميلاد والظهور الإلهي. والأمر «قومي» يفترض أنها كانت نائمة أو منحنية. وفعل «استنيري» يجمع الاستقبال والانعكاس. والسبب: «قد جاء نورك». فالنور سابق لجهدنا. وقد صار المسيح نور العالم، ويقول لنا: «أنتم نور العالم». أي أننا نعكس ما أخذناه.\\nاليوم، ابدأ بالنهوض من تأجيل روحي: صلِّ الأجبية أو اقرأ فصلًا كنت تؤجله.\"},{\"t\":\"كعشر شموع\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب لوط للأب يوسف إنه يقوم بصلاته وصومه ودرسه وتأمله فماذا بقي عليه؟ فبسط الأب يوسف يديه نحو السماء فصارت أصابعه كعشر شموع من نار، وقال: إذا كنت تريد فما عليك إلا أن تكون نارًا بالكلية. النور الكامل يطلب قلبًا كاملًا. أعطِ الله اليوم شيئًا أكثر مما تعودت.\",\"p\":\"يا رب، اجعلني نارًا بالكلية في محبتك. لا أكتفي بما فعلت، بل أطلب نورك الكامل. آمين.\",\"x\":\"قال الأب لوط للأب يوسف إنه يقوم بصلاته وصومه ودرسه فماذا بقي عليه؟ فبسط الأب يوسف يديه فصارت أصابعه كعشرة مصابيح نار وقال: إذا كنت تريد فما عليك إلا أن تكون نارًا بالكلية. تدريب: أضف اليوم حرارة لعمل روحي واحد.\",\"fq\":185}]},\"11-30\":{\"th\":\"ملء الزمان\",\"m\":[{\"t\":\"كل الخليقة تهللت بمجيئك\",\"ref\":\"قطعة باكر\",\"v\":\"أيها النور الحقيقي الذي يضيء لكل إنسان آت إلى العالم: أتيت إلى العالم بمحبتك للبشر، وكل الخليقة تهللت بمجيئك. خلصت أبانا آدم من الغواية، وأعتقت أمنا حواء من طلقات الموت، وأعطيتنا روح البنوة.\",\"r\":\"جاء المسيح في ملء الزمان ليخلص آدم وحواء ويعطينا روح البنوة. كل الخليقة تهللت بمجيئه. حيّ في هذا اليوم النهاية القادمة للصوم بفرح الترقب، وقل لنفسك: إنه آتٍ.\",\"p\":\"يا نور العالم، أنت آتٍ في ملء الزمان. أعطني روح البنوة، وأدخلني في تهليل الخليقة بك. آمين.\",\"x\":\"جاء المسيح في ملء الزمان ليخلص آدم وحواء ويعطي روح البنوة، وتهللت كل الخليقة بمجيئه. تدريب: اشكره على أنه جاء في وقته ولا يتأخر في وقتك.\"},{\"t\":\"لما جاء ملء الزمان\",\"ref\":\"غلاطية ٤: ٤\",\"bk\":\"غلاطية\",\"v\":\"ولكن لما جاء ملء الزمان، أرسل الله ابنه مولودا من امرأة، مولودا تحت الناموس،\",\"r\":\"«ولكن لما جاء ملء الزمان، أرسل الله ابنه مولودًا من امرأة». الله لا يتعجل ولا يتأخر. هناك وقت معين لكل عمل. وأنا أنتظر بصبر أن يأتي ملء الزمان لكل وعد في حياتي، وأثق أن توقيته أفضل.\",\"p\":\"يا رب، أنت أرسلت ابنك في ملء الزمان. علمني أن أنتظر توقيتك في حياتي، وأثق أن كل شيء يكمل في وقته الصالح. آمين.\",\"x\":\"عبارة «ملء الزمان» تشير إلى التوقيت الإلهي الكامل، حين كانت الظروف مهيأة: سلام روماني، ولغة يونانية مشتركة، وطرق مفتوحة، وشوق عالمي للخلاص. والمسيح «مولود من امرأة»، أي حقيقة بشرية كاملة، و«تحت الناموس»، أي خاضع له ليفتدينا. ولا يعني ذلك أنه أقل من الآب، بل أنه قبل التواضع. والله يعمل في التاريخ لا خارجه. وكنيستنا تحتفل بالتجسد كحقيقة تاريخية.\\nاستعد للميلاد بقراءة لوقا ٢ اليوم، وتأمل كيف اجتمعت الظروف في اللحظة الصحيحة.\"},{\"t\":\"الخبرة تمتحن\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: الخبرة جميلة لأنها تجعل الإنسان ممتحنًا أكثر. وملء الزمان جاء بعد أزمنة طويلة من الانتظار والخبرة. لا تستعجل اليوم، فالله يعمل في زمنه وزماننا يمتحن.\",\"p\":\"يا رب، علّمني الصبر في الانتظار. اجعل خبرات الأيام تقربني إليك. آمين.\",\"x\":\"يقول الأب بيمن: الخبرة جميلة لأنها تجعل الإنسان ممتحنًا أكثر. وملء الزمان جاء بعد أزمنة طويلة من الانتظار. تدريب: انتفع اليوم من تجربة قديمة قبل أن تقرر.\",\"fq\":325}]},\"12-1\":{\"th\":\"زكريا وأليصابات\",\"m\":[{\"t\":\"طوبى للخائف الرب\",\"ref\":\"المزمور ١١١ (١١٢) — التاسعة\",\"v\":\"طوبى للرجل الخائف الرب ويهوى وصاياه جدا. يقوى نسله على الأرض.\",\"r\":\"من يخاف الرب ويحب وصاياه يبارك الله نسله. هكذا كان زكريا وأليصابات، بارّين أمام الله، وانتظرا طويلًا دون أن يتركا الصلاة. اخترنا اليوم وصية واحدة نتمسك بها بفرح، ولو بدا الانتظار طويلًا.\",\"p\":\"يا رب، علّمني أن أحب وصاياك وأخافك بمحبة. بارك حياتي وبيتي كما باركت بيت زكريا وأليصابات. آمين.\",\"x\":\"طوبى للرجل الخائف الرب، ويقوى نسله. كان زكريا وأليصابات بارّين وانتظرا طويلًا دون أن يتذمرا. تدريب: صلِّ اليوم من أجل طلب تأخر، وقل: في وقتك يا رب.\"},{\"t\":\"بارين أمام الله\",\"ref\":\"لوقا ١: ٦\",\"bk\":\"لوقا\",\"v\":\"وكانا كلاهما بارين أمام الله، سالكين في جميع وصايا الرب وأحكامه بلا لوم.\",\"r\":\"«وكانا كلاهما بارين أمام الله، سالكين في جميع وصايا الرب وأحكامه بلا لوم». لم يكن الطريق سهلًا، ولم يكن لهما ولد، ومع ذلك استمرا في الأمانة. وأنا أتعلم أن البر لا يتوقف على تحقق رغباتي.\",\"p\":\"يا رب، علمني أن أسلك في وصاياك بلا لوم وأنا أنتظر. ثبتني في الأمانة حين تتأخر الاستجابة، وأعطني رجاءً كرجاء زكريا وأليصابات. آمين.\",\"x\":\"تبدأ إنجيل لوقا بقصة بيت كهنوتي متقدم في السن، لا ولد له، وهو في تلك الأيام يعتبر عارًا. ومع ذلك يشهد لهما الإنجيل بالبر. فالأمانة في الانتظار هي أصل الاستجابة. وفي كنيستنا نبدأ أيام صوم الميلاد بقراءات عن هذا البيت لأنه يهيئ الطريق لمجيء المسيح. وتعلمنا القصة أن الله يعمل في الخفاء والانتظار. وأن البر الحقيقي يتجسد في طاعة وصاياه كل يوم بلا ملل.\\nاليوم، اختر وصية في الإنجيل تحافظ عليها بدقة وأمانة، حتى لو لم يلاحظك أحد.\"},{\"t\":\"ضمير نقي تجاه القريب\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل كاهن من النطرون الأب بمفو: كيف يمكن للإخوة أن يسلكوا؟ فأجاب: بنسك كبير وهم يحفظون ضميرهم طاهرًا نقيًا تجاه القريب. فالبر الحقيقي يظهر أولًا في علاقتنا بالناس. اسأل نفسك اليوم: هل بيني وبين أحد ما يثقل ضميري؟ وبادر بالصلح.\",\"p\":\"يا رب، طهّر ضميري تجاه كل قريب. أعطني أن أسلك بلا لوم أمامك وأمام الناس. آمين.\",\"x\":\"سأل كاهن من النطرون الأب بمفو كيف يمكن للإخوة أن يسلكوا؟ فأجاب: بنسك كبير وهم يحفظون ضميرهم طاهرًا نقيًا تجاه القريب. تدريب: نقّ ضميرك اليوم تجاه أحد.\",\"fq\":463}]},\"12-2\":{\"th\":\"السابق للمسيح\",\"m\":[{\"t\":\"رحيم رؤوف وبار\",\"ref\":\"المزمور ١١١ (١١٢) — التاسعة\",\"v\":\"رحيم هو الرب الإله ورؤوف وبار.\",\"r\":\"الله الذي ننتظر ميلاده رحيم ورؤوف وبار. لذلك وُلد يوحنا اسمه «الله حنّان»، ليهيئ الطريق لمن جاء بنعمته. أول ما يهيئ القلب هو أن يعرف الله على حقيقته: رحيمًا. اقرأ اليوم عن رحمة الله، واحتمل بها ضعف من حولك.\",\"p\":\"يا رب الرحيم الرؤوف، هيّئ قلبي لمجيئك، وعلّمني أن أرحم كما رحمتني. آمين.\",\"x\":\"الرب رحيم ورؤوف وبار، ولذلك وُلد يوحنا واسمه «الله حنّان» ليهيئ الطريق. تدريب: هيئ اليوم طريقًا للمسيح بتوبة صغيرة.\"},{\"t\":\"يمتلئ من الروح القدس\",\"ref\":\"لوقا ١: ١٥\",\"bk\":\"لوقا\",\"v\":\"لأنه يكون عظيما أمام الرب، وخمرا ومسكرا لا يشرب، ومن بطن أمه يمتلئ من الروح القدس.\",\"r\":\"«لأنه يكون عظيمًا أمام الرب… ومن بطن أمه يمتلئ من الروح القدس». العظمة الحقيقية هي عظمة أمام الرب، لا أمام الناس. وامتلاء الروح القدس هو سر قوة يوحنا. وأنا أطلب هذا الامتلاء كل يوم.\",\"p\":\"أيها الروح القدس، املأني منذ هذا الصباح. اجعلني عظيمًا أمام الرب لا أمام الناس، وكرّس حياتي لك. آمين.\",\"x\":\"عظمة يوحنا ليست في مركز أو سلطة بل في تكريس كامل: لا خمر ولا مسكر، ما يشير إلى حياة النذير. وامتلاؤه بالروح القدس منذ الحياة الجنينية يرمز إلى عمل الله السابق للمعرفة. وسيشهد المسيح بعده أنه «لم يقم بين المولودين من النساء أعظم من يوحنا المعمدان». والكنيسة ترى فيه قدوة للتوبة والزهد. وفي صوم الميلاد نتتلمذ على قدوته في الاستعداد.\\nاليوم، قدم لله قرارًا بالتكريس في أمر صغير (وقت صلاة، أو امتناع عن عادة) واطلب امتلاءً من الروح.\"},{\"t\":\"لا أستحق ما يُقال\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يعقوب: عندما يُمتدح إنسان ينبغي أن يتأمل في خطاياه ويفكر في أنه لا يستحق ما يُقال فيه. هذه كانت روح السابق: ينبغي أن ذلك يزيد وأني أنا أنقص. عند أول مدح تسمعه اليوم، ارفعه بصمت إلى الله وقل: لك المجد.\",\"p\":\"يا رب، احفظني من الافتخار بمدح الناس. اجعلني أنقص ليزيد اسمك فيَّ. آمين.\",\"x\":\"يقول الأب يعقوب: عندما يُمتدح إنسان ينبغي أن يتأمل في خطاياه ويفكر أنه لا يستحق ما يُقال فيه. المديح لا يغر المتواضع. تدريب: اقبل المديح اليوم وانسبه لله.\",\"fq\":188}]},\"12-3\":{\"th\":\"الصمت والإيمان\",\"m\":[{\"t\":\"حافظًا لفمي\",\"ref\":\"المزمور ١٤٠ (١٤١) — النوم\",\"v\":\"ضع يا رب حافظا لفمي، وبابا حصينا لشفتي. ولا تمل قلبي إلى كلام الشر، فيتعلل بعلل في الخطايا مع أناس فاعلي الإثم، ولا أتفق مع مختاريهم.\",\"r\":\"طلب المرنم من الله أن يضع حافظًا لفمه وبابًا حصينًا لشفتيه. زكريا فقد نطقه بسبب عدم إيمانه، ثم عاد يتكلم بالتسبيح. اجعل لفمك اليوم حارسًا: قبل أن تتكلم، اسأل نفسك هل هذه الكلمة تبني أم تهدم؟\",\"p\":\"يا رب، ضع حافظًا لفمي، وأبعد قلبي عن كلام الشر. وليكن كلامي اليوم تسبيحًا لك. آمين.\",\"x\":\"ضع يا رب حافظًا لفمي وبابًا حصينًا لشفتي. فقد زكريا نطقه ثم عاد يتكلم بالتسبيح. تدريب: لا تتكلم اليوم إلا بما يمجد.\"},{\"t\":\"كيف أعلم هذا؟\",\"ref\":\"لوقا ١: ١٨\",\"bk\":\"لوقا\",\"v\":\"فقال زكريا للملاك: «كيف أعلم هذا، لأني أنا شيخ وامرأتي متقدمة في أيامها؟»\",\"r\":\"«كيف أعلم هذا، لأني أنا شيخ وامرأتي متقدمة في أيامها؟». الواقع يضغط على إيماني، فأقيس وعد الله بإمكاناتي. وأنا أحتاج أن أنظر إلى الوعد قبل الظروف، وأن أتذكر أن لا شيء غير ممكن لدى الله.\",\"p\":\"يا رب، أؤمن فأعن عدم إيماني. لا تدع الظروف تعمي عيني عن وعودك، وقوّ إيماني حين يضعف أمام الواقع. آمين.\",\"x\":\"زكريا كان بارًا، ومع ذلك شك. وهذا يعلمنا أن الشك يصيب الأتقياء أيضًا. والفرق بين شكه وسؤال مريم لاحقًا هو أنه طلب علامة، أما هي فسألت عن الكيفية. وكلاهما سؤال، لكن الروح مختلفة. والشك لا يلغي وعد الله، لكنه يعطله بالنسبة لنا. وقد قال الرب: «إن كنت تؤمن فكل شيء مستطاع للمؤمن». فالإيمان يحول المستحيل.\\nاكتب اليوم موقفًا تقيس فيه وعد الله بإمكانياتك البشرية، وصلِّ: «أؤمن يا رب فأعن عدم إيماني».\"},{\"t\":\"أن نؤثر الصمت\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: إذا تذكّر المرء القول المكتوب «بكلامك تتبرر وبكلامك تدان» فإنه سرعان ما يؤثر الصمت. الصمت ليس هروبًا بل استعدادًا للسماع. اقضِ اليوم عشر دقائق بلا كلام لتسمع صوت الله في الأمور الصغيرة.\",\"p\":\"يا رب، علّمني أن أؤثر الصمت حين لا يفيد الكلام. وافتح فمي لتسبيحك وحده. آمين.\",\"x\":\"يقول الأب بيمن: إذا تذكّر المرء القول المكتوب «بكلامك تتبرر وبكلامك تدان» فإنه سرعان ما يؤثر الصمت. تدريب: قبل كل كلمة اليوم اسأل: هل سأتبرر بها؟\",\"fq\":340}]},\"12-4\":{\"th\":\"البشارة بالتجسد\",\"m\":[{\"t\":\"كرسي ملكك\",\"ref\":\"المزمور ٤٤ (٤٥) — الثالثة\",\"v\":\"كرسيك يا الله إلى دهر الدهر، قضيب الاستقامة هو قضيب ملكك.\",\"r\":\"كرسي الله إلى دهر الدهر، وقضيب ملكه قضيب استقامة. هكذا أعلن الملاك لمريم: وسيملك على بيت يعقوب إلى الأبد. الملك الذي يأتي لا يملك بالقوة بل بالاستقامة والتواضع. افتح اليوم لهذا الملك مجالًا في قرار صغير من قراراتك.\",\"p\":\"يا رب، ليملك في قلبي قضيب استقامتك. وأعطني أن أستقبل مشيئتك كما استقبلتها العذراء. آمين.\",\"x\":\"كرسيك يا الله إلى دهر الدهر وقضيب ملكك قضيب استقامة. هكذا أعلن الملاك لمريم أنه سيملك إلى الأبد. تدريب: قل لله اليوم: لتكن مشيئتك، كما قالت العذراء.\"},{\"t\":\"إلى عذراء مخطوبة\",\"ref\":\"لوقا ١: ٢٧\",\"bk\":\"لوقا\",\"v\":\"إلى عذراء مخطوبة لرجل من بيت داود اسمه يوسف. واسم العذراء مريم.\",\"r\":\"«إلى عذراء مخطوبة لرجل من بيت داود اسمه يوسف. واسم العذراء مريم». الله اختار فتاة بسيطة من بلدة صغيرة. فلا أحتقر بساطة حياتي، فهي قد تكون مكان عمل الله. وأرحب بالتواضع كطريق للنعمة.\",\"p\":\"يا رب، أشكرك على تواضعك الذي اخترت به الصغار. اجعلني أرحب بنعمتك مهما كانت حياتي بسيطة، وبارك عذراءك الطاهرة. آمين.\",\"x\":\"الناصرة بلدة غير مشهورة، وقال نثنائيل عنها: «أمن الناصرة يمكن أن يكون شيء صالح؟». ومع ذلك فيها تتم أعظم بشارة في التاريخ. واختيار الله لا يعتمد على المكانة بل على الاتضاع والنقاء. والعذراء مريم تقف في موقع خاص كأم المسيح وقدوة الإيمان. وتذكر الكنيسة ذلك في أعيادها وتماجيدها. وتحتفل بالبشارة في ٢٩ برمهات، وسنحتفل اليوم بالتأمل فيها.\\nاليوم، اطلب من الله أن يستخدم بساطتك، ولا تؤجل خدمتك بحجة أنك صغير.\"},{\"t\":\"كالنفس الذي لا ينقطع\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: يحتاج الإنسان إلى التواضع ومخافة الله، تمامًا كالنفَس الذي يخرج من أنفه. العذراء مريم قالت «هوذا أنا أمة الرب» وهي في كامل الاتضاع. نفّس اليوم بتواضع: كلما شعرت بالكبرياء، تنفس وقل: أنا عبدك يا رب.\",\"p\":\"يا رب، اجعل التواضع ومخافتك لي كالنفس الذي لا ينقطع. آمين.\",\"x\":\"يقول الأب بيمن: يحتاج الإنسان إلى التواضع ومخافة الله تمامًا كالنفَس الذي يخرج من أنفه. العذراء قالت «هوذا أنا أمة الرب». تدريب: اجعل التواضع نفَسك اليوم.\",\"fq\":347}]},\"12-5\":{\"th\":\"ليس شيء غير ممكن\",\"m\":[{\"t\":\"يمين الرب صنعت قوة\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"يمين الرب صنعت قوة، يمين الرب رفعتني، يمين الرب صنعت قوة.\",\"r\":\"يمين الرب رفعتني، يمين الرب صنعت قوة. وقال الملاك لمريم: ليس شيء غير ممكن لدى الله. فما تظنه مستحيلًا في حياتك اليوم، اعرضه على من لا يعجزه شيء، وانتظر تدخله.\",\"p\":\"يا رب، يمينك صنعت قوة. أؤمن أنه لا يعجزك شيء، فاعمل في ما أعجز أنا عنه. آمين.\",\"x\":\"يمين الرب صنعت قوة، يمين الرب رفعتني. وقال الملاك لمريم: ليس شيء غير ممكن لدى الله. تدريب: سلم لله اليوم أمرًا تظنه مستحيلًا.\"},{\"t\":\"لا يكون لملكه نهاية\",\"ref\":\"لوقا ١: ٣٣\",\"bk\":\"لوقا\",\"v\":\"ويملك على بيت يعقوب إلى الأبد، ولا يكون لملكه نهاية».\",\"r\":\"«ويملك على بيت يعقوب إلى الأبد، ولا يكون لملكه نهاية». كل الممالك تزول، وملكه لا يزول. وأنا إذ أنتمي إلى ملكوته أتحرر من القلق على مصير هذا العالم، فالمستقبل بيد الملك الأبدي.\",\"p\":\"يا ملك الدهور، ملكك لا نهاية له. ثبتنا في ملكوتك، ولا تدع الأحداث المتغيرة تهز إيماننا، فأنت ملك السلام. آمين.\",\"x\":\"هذا القول يردده قانون الإيمان: «الذي ليس لملكه انقضاء». والملك هنا ملك روحي، وليس ملك سلطة بشرية. فالرب يسوع قال: «مملكتي ليست من هذا العالم». لكنها تخترق العالم كخميرة. وتتحقق في الكنيسة التي تضم كل الشعوب. ولهذا نرى استمرار الكنيسة رغم الاضطهادات: «أبواب الجحيم لن تقوى عليها». وفي الصعوبات نتذكر أن ملكوته لا ينتهي.\\nعند الاضطراب من الأحداث العامة اليوم، ردد: «ملكه لا نهاية له»، وسلم الأمر بين يدي الملك الأبدي.\"},{\"t\":\"الإيمان بأن الله يهتم\",\"ref\":\"\",\"v\":\"\",\"r\":\"سُئل الأب أشعيا: ما هي محبة الفضة؟ فقال إنها عدم الإيمان بأن الله يهتم بك، واليأس من وعوده، ومحبة الافتخار والعظمة. من يؤمن أن الله يهتم يستريح من الخوف على الغد. قدّم اليوم همًّا ماديًّا واحدًا لله وقل له: أنت تهتم.\",\"p\":\"يا رب، أؤمن أنك تهتم بي. اشفِ ضعف إيماني بوعودك، وحررني من محبة المال. آمين.\",\"x\":\"سُئل الأب أشعيا ما هي محبة الفضة فقال: عدم الإيمان بأن الله يهتم بك، واليأس من وعوده، ومحبة الافتخار والعظمة. تدريب: ثق اليوم بأن الله يهتم بك.\",\"fq\":124}]},\"12-6\":{\"th\":\"زيارة مريم لأليصابات\",\"m\":[{\"t\":\"فرحت صهيون\",\"ref\":\"المزمور ٩٦ (٩٧) — التاسعة\",\"v\":\"سمعت صهيون ففرحت. وتهللت بنات يهوذا، من أجل أحكامك يا رب.\",\"r\":\"سمعت صهيون ففرحت وتهللت بنات يهوذا. هكذا حين سمعت أليصابات سلام مريم تحرك الجنين بابتهاج. الفرح معدٍ حين نحمل المسيح. اذهب اليوم لتزور أحدًا وحيدًا أو مريضًا، وليكن حضورك بشارة صغيرة.\",\"p\":\"يا رب، املأ قلبي فرحًا بك لكي أحمل فرحك لمن أزورهم. آمين.\",\"x\":\"سمعت صهيون ففرحت وتهللت بنات يهوذا. حين سمعت أليصابات سلام مريم تحرك الجنين بابتهاج. تدريب: شارك اليوم فرحك بخبر طيب مع شخص.\"},{\"t\":\"أليصابات نسيبتك حبلى\",\"ref\":\"لوقا ١: ٣٦\",\"bk\":\"لوقا\",\"v\":\"وهوذا أليصابات نسيبتك هي أيضا حبلى بابن في شيخوختها، وهذا هو الشهر السادس لتلك المدعوة عاقرا،\",\"r\":\"«وهوذا أليصابات نسيبتك هي أيضًا حبلى بابن في شيخوختها». الله يشجع بعلامة قريبة. وحين أشعر بصعوبة، قد يعطيني الله علامة في حياة أحد أحبائي ليقوي إيماني. فأتعلم أن أفرح بعمل الله في غيري.\",\"p\":\"يا رب، أشكرك على علاماتك التي تشجعنا. علمني أن أفرح بعملك في غيري، وأن أنقل الفرح لمن حولي. آمين.\",\"x\":\"أعطى الملاك علامة لمريم دون أن تطلبها، لأن إيمانها لم يحتج إلى إثبات، لكن الله يشجع. وهذه العلامة تدعوها إلى لقاء أليصابات، فتكون الشركة بين الاثنتين مصدر قوة. وهذا يعلمنا أن الله يربط المؤمنين ببعضهم. وفي الكنيسة نسمع شهادات عن عمل الله فنتشجع. وتبرز الآية الحاجة إلى الفرح بعمل الله في الآخرين، لا الحسد.\\nاليوم شارك مع أحد خبرًا مفرحًا عن عمل الله في حياتك أو حياة شخص تعرفه.\"},{\"t\":\"تعال متى تشاء\",\"ref\":\"\",\"v\":\"\",\"r\":\"جاء أخ إلى الأب يوحنا الكولوفي وكان يخشى أن يزعجه. فأشعل الشيخ مصابيح كثيرة من مصباح واحد دون أن يتضرر، وقال له: يمكنك أن تأتي إليّ متى تشاء دون أن تتردد. المحبة لا تنقص بالعطاء. افتح بابك اليوم لمن يحتاج إليك دون ضجر.\",\"p\":\"يا رب، اجعلني كالمصباح الذي لا ينقص نوره بالعطاء. علّمني أن أستقبل الجميع بمحبة. آمين.\",\"x\":\"خشي أخ أن يزعج الأب يوحنا الكولوفي، فأشعل الشيخ مصابيح كثيرة من مصباح واحد دون أن يتضرر وقال: هكذا الحال مع يوحنا، فلو جاءني كل سكان الأسقيط لا يمكنهم أن يعيقوني عن نعمة المسيح. تدريب: افتح بابك اليوم لمن يحتاجك.\",\"fq\":156}]},\"12-7\":{\"th\":\"الفرح والرحمة والوعد\",\"m\":[{\"t\":\"الرب قد ملك\",\"ref\":\"المزمور ٩٦ (٩٧) — التاسعة\",\"v\":\"الرب قد ملك فلتتهلل الأرض، ولتفرح الجزائر الكثيرة.\",\"r\":\"الرب قد ملك فلتتهلل الأرض. ملكه ليس بالسيف بل بالرحمة، وفي هذا الأسبوع نستعد لاستقبال ملك متواضع. اجعل لهذا اليوم ملكًا واحدًا: أن يملك الله على قرار واحد صغير، وفرّح بذلك.\",\"p\":\"يا رب، أنت الملك. لتتهلل أرض قلبي بملكك، ولتملك على كل أفكاري. آمين.\",\"x\":\"الرب قد ملك فلتتهلل الأرض. ملكه بالرحمة، وفي هذا الأسبوع نستقبل ملكًا متواضعًا. تدريب: استقبله اليوم برحمة لأحد.\"},{\"t\":\"ليذكر رحمة\",\"ref\":\"لوقا ١: ٥٥\",\"bk\":\"لوقا\",\"v\":\"كما كلم آباءنا. لإبراهيم ونسله إلى الأبد».\",\"r\":\"«عضد إسرائيل فتاه ليذكر رحمة، كما كلم آباءنا. لإبراهيم ونسله إلى الأبد». مريم ترى الميلاد تحقيقًا لوعد قديم. وأنا أتعلم أن أنظر إلى حياتي في ضوء وعود الله. فهو لا ينسى ويذكر رحمته.\",\"p\":\"يا رب، أنت تذكر رحمتك وتفي بوعودك. أشكرك على أمانتك مع آبائنا ومعنا، وأعطني أن أثق بوعودك لمستقبلي. آمين.\",\"x\":\"تسبحة مريم هي ختام القصة الأولى في لوقا، وتنتهي بإبراهيم لأن الوعد بدأ معه. وهي ترتب الأحداث في التاريخ كله: الله ذكر رحمة بعد قرون. وتنشدها الكنيسة في صلاة الغروب. وتعلمنا أن نسبح الله على الماضي والحاضر والمستقبل. وعبارة «كما كلم آباءنا» تؤكد أمانته. فكل ما نختبره اليوم يستند إلى عهد.\\nاكتب اليوم ثلاثة وعود من الله تحققت في حياتك أو أسرتك، وقدم له تسبيحًا عليها.\"},{\"t\":\"الله رحيم بالشجعان\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال أخ للأب بيمن إنه حيثما حل يجد عونًا. فقال له الشيخ إن الذين يحملون السيوف في أيديهم يجدون الله رحيمًا في الوقت الحاضر، وإذا كنا شجعانًا فإنه يرحمنا أيضًا. الشجاعة الروحية أن نجاهد الخطية، لا أن نهرب منها. جاهد اليوم في أمر واحد.\",\"p\":\"يا رب، أعطني شجاعة الجهاد، ولا تتركني أستسلم. ارحمني كما ترحم المجاهدين. آمين.\",\"x\":\"قال أخ للأب بيمن إنه حيثما حل يجد عونًا فأجابه: إن الذين يحملون السيوف في أيديهم يجدون الله رحيمًا في الوقت الحاضر، فإذا كنا شجعانًا فإنه يرحمنا أيضًا. تدريب: كن شجاعًا في جهادك اليوم.\",\"fq\":381}]},\"12-8\":{\"th\":\"يوسف البار\",\"m\":[{\"t\":\"أحسن إلى المستقيمين\",\"ref\":\"المزمور ١٢٤ (١٢٥) — الغروب\",\"v\":\"أحسن يا رب إلى الصالحين وإلى المستقيمي القلوب.\",\"r\":\"يطلب المرنم: أحسن يا رب إلى الصالحين والمستقيمي القلوب. يوسف كان بارًا ومستقيم القلب، فلم يشهّر بمريم بل أراد تخليتها سرًّا. البر الحقيقي لا يسرع إلى الحكم. إن بلغك أمر عن أحد اليوم، أمسك لسانك وصلِّ من أجله.\",\"p\":\"يا رب، أحسن إلى المستقيمين. اجعل قلبي كقلب يوسف: بارًا رحيمًا لا يسرع إلى الحكم. آمين.\",\"x\":\"أحسن يا رب إلى الصالحين والمستقيمي القلوب. يوسف كان بارًا فلم يشهّر بمريم. تدريب: لا تشهّر اليوم بعيب أحد.\"},{\"t\":\"رجلها إذ كان بارًا\",\"ref\":\"متى ١: ١٩\",\"bk\":\"متى\",\"v\":\"فيوسف رجلها إذ كان بارا، ولم يشأ أن يشهرها، أراد تخليتها سرا.\",\"r\":\"«فيوسف رجلها إذ كان بارًا، ولم يشأ أن يشهرها، أراد تخليتها سرًا». البر ممزوج بالرحمة. فهو لا يتعجل الحكم ولا يفضح. وأنا أتعلم منه أن أحفظ كرامة الناس حتى عندما أظن أنهم أخطأوا.\",\"p\":\"يا رب، علمني من يوسف البار أن أمزج البر بالرحمة. احفظ لساني من فضح الآخرين، وأعطني لطفًا يستر ولا يعير. آمين.\",\"x\":\"البر عند يوسف لم يكن قسوة بل لطفًا. فبحسب الشريعة كان يمكنه أن يشهرها ويطلب عقابها. لكنه اختار الستر. وفي ذلك صورة ليسوع الذي سيقول للمرأة الزانية: «ولا أنا أدينك». وتكرم الكنيسة القديس يوسف النجار بوصفه «البار»، وتعيّد له في ٢ أبيب. ويعلمنا أن الاستقامة تحتاج حكمة ورحمة معًا. وكثيرًا ما يضيع الإنسان بين القسوة والتساهل.\\nاليوم، عندما تسمع خبرًا سيئًا عن أحد، لا تنشره، واحفظ كرامته بالصمت أو بالصلاة.\"},{\"t\":\"اسمك في سفر الأحياء\",\"ref\":\"\",\"v\":\"\",\"r\":\"وقف الأب بفنوتيوس يصلي من أجل خطاياه بينما كان بعض الناس يتحدثون، فظهر له ملاك يحمل سيفًا وقال إن الذين يدينون إخوتهم يهلكون بحد هذا السيف، أما هو فقد كتب اسمه في سفر الأحياء لأنه لا يدين أحدًا بل يتضع كأنه المخطئ. اتضع اليوم ولا تدن.\",\"p\":\"يا رب، احفظني من الدينونة. علّمني أن أقف أمامك كالمخطئ، فأجد اسمي مكتوبًا في سفر الحياة. آمين.\",\"x\":\"وقف الأب بفنوتيوس يصلي من أجل خطاياه بينما كان آخرون يتحدثون، فظهر له ملاك يحمل سيفًا وقال إن الذين يدينون إخوتهم يهلكون بحد هذا السيف، أما من يتضع كأنه المخطئ فاسمه في سفر الأحياء. تدريب: لا تدن اليوم.\",\"fq\":473}]},\"12-9\":{\"th\":\"عمانوئيل\",\"m\":[{\"t\":\"جعلت العلي ملجأك\",\"ref\":\"المزمور ٩٠ (٩١) — السادسة\",\"v\":\"لأنك أنت يا رب رجائي. جعلت العلي ملجأك.\",\"r\":\"لأنك أنت يا رب رجائي، جعلت العلي ملجأك. اسم عمانوئيل معناه الله معنا. ليس الله بعيدًا عنا بل ملجأ قريب في كل ضيق. عندما يضطرب قلبك اليوم، قل: الله معي، وارجع إليه كملجأ.\",\"p\":\"يا رب عمانوئيل، أنت معي. اجعل فيك ملجأي ورجائي في كل ضيق. آمين.\",\"x\":\"أنت يا رب رجائي، جعلت العلي ملجأك. عمانوئيل معناه الله معنا. تدريب: كرر اليوم: الله معنا، في كل موقف.\"},{\"t\":\"الله معنا\",\"ref\":\"متى ١: ٢٣\",\"bk\":\"متى\",\"v\":\"«هوذا العذراء تحبل وتلد ابنا، ويدعون اسمه عمانوئيل» الذي تفسيره: الله معنا.\",\"r\":\"«هوذا العذراء تحبل وتلد ابنًا، ويدعون اسمه عمانوئيل، الذي تفسيره: الله معنا». أعظم عزاء أن الله معنا في الفرح والضيق. وأنا أبدأ يومي بهذه الحقيقة: لست وحدي، لأنه معي.\",\"p\":\"يا عمانوئيل، أنت الله معنا. كن معي في كل لحظة، وأعطني وعيًا بحضورك في الفرح والضيق، فلا أخاف شيئًا. آمين.\",\"x\":\"اسم عمانوئيل يلخص الإنجيل: الله مع الإنسان. وهو يتحقق في ميلاد المسيح، ويستمر في وعده: «ها أنا معكم كل الأيام إلى انقضاء الدهر». وإنجيل متى يبدأ بـ«الله معنا» وينتهي بـ«أنا معكم»، كإطار للإنجيل كله. وتحمل الكنيسة هذا الاسم في صلواتها وألحانها. ونتأمل في كيف يرافقنا الله في ضيقاتنا. وتتحول الوحدة إلى شركة عندما نعرف أنه حاضر.\\nعند أي لحظة وحدة اليوم، قل ببطء: «عمانوئيل، الله معنا»، وتنفس بهدوء.\"},{\"t\":\"ذكر الله الدائم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب يوحنا الكولوفي: السجن هو أن تقيم في قلايتك وتذكر الله على الدوام، وهذا هو معنى الآية «كنت محبوسًا فأتيتم إليّ». الإقامة مع الله ليست سجنًا بل حرية. اختر اليوم ساعة تجلس فيها وتذكر الله بلا انشغال.\",\"p\":\"يا رب عمانوئيل، علّمني أن أذكرك على الدوام. اجعل قلبي قلاية تسكن فيها. آمين.\",\"x\":\"يقول الأب يوحنا الكولوفي: السجن هو أن تقيم في قلايتك وتذكر الله على الدوام، وهذا معنى «كنت محبوسًا فأتيتم إليّ». تدريب: ابقَ اليوم مع الله في مكانك.\",\"fq\":161}]},\"12-10\":{\"th\":\"النور الحقيقي\",\"m\":[{\"t\":\"أخبرت السموات بعدله\",\"ref\":\"المزمور ٩٦ (٩٧) — التاسعة\",\"v\":\"أخبرت السموات بعدله؛ وعاينت جميع الشعوب مجده.\",\"r\":\"أخبرت السموات بعدله وعاينت جميع الشعوب مجده. النور الحقيقي الذي يضيء لكل إنسان يتجلى في الميلاد لكل الشعوب. لا يخص أحدًا دون غيره. تأمل اليوم في أن المسيح جاء لك أنت، ولمن تبغضه أيضًا.\",\"p\":\"يا نور العالم، أضئ لكل إنسان، وأضئ لي أنا. وليعاين الجميع مجدك. آمين.\",\"x\":\"أخبرت السماوات بعدله وعاينت جميع الشعوب مجده. النور الحقيقي يتجلى للجميع. تدريب: أشعل اليوم شمعة وصلِّ لكل من في ظلمة.\"},{\"t\":\"كل شيء به كان\",\"ref\":\"يوحنا ١: ٣\",\"bk\":\"يوحنا\",\"v\":\"كل شيء به كان، وبغيره لم يكن شيء مما كان.\",\"r\":\"«كل شيء به كان، وبغيره لم يكن شيء مما كان». الخالق هو المخلص. وكل جمال في الكون يشهد له. وأنا أنظر اليوم إلى الخليقة بعين شكر، لأنني أرى فيها يد المسيح.\",\"p\":\"يا خالق الكون، كل شيء بك كان. أشكرك على جمال خليقتك، وعلمني أن أحفظها وأحمدك عليها، وأن أراك في كل ما صنعت. آمين.\",\"x\":\"تؤكد هذه الآية دور الابن في الخلق، وتتفق مع قول بولس: «فيه خلق الكل». ولا يوجد شيء خارج نطاق خلقه. والتجسد هو دخول الخالق إلى مخلوقاته. فلا غريب أن تعجب الطبيعة بميلاده: نجم، ورعاة، وحيوانات في المذود. وتعلمنا الآية احترام الخليقة لأنها من الله. وأيضًا ألا نستسلم لفكرة أن الكون مصادفة، فله خالق محب.\\nاخرج اليوم لحظة وانظر إلى السماء أو شجرة، وقل: «كل شيء به كان، شكرًا يا رب».\"},{\"t\":\"شمعة في الريح\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل الإخوة الأب إسحق: لماذا تهرب من الإخوة بعد الصلاة؟ فأجاب: لو أمسك أحد شمعة مضاءة وأطال وقوفه في الريح تنطفئ، وهكذا عقلنا يظلم إذا مشينا خارج قلالينا بعد أن استنرنا من التقدمة المقدسة. احفظ نور القدسات بعد القداس بصمت وهدوء.\",\"p\":\"يا رب، احفظ نور القدسات في قلبي، ولا تدع ريح العالم تطفئه. آمين.\",\"x\":\"سأل الإخوة الأب إسحق لماذا تهرب منهم بعد الصلاة؟ فأجاب: لو أمسك أحد شمعة مضاءة وأطال وقوفه في الريح تنطفئ، هكذا نستنير من التقدمة ولا بد من حراسة. تدريب: احفظ نور القداس بعد خروجك.\",\"fq\":207}]},\"12-11\":{\"th\":\"الطريق إلى بيت لحم\",\"m\":[{\"t\":\"لندخل إلى مساكنه\",\"ref\":\"المزمور ١٣١ — النوم\",\"v\":\"ها قد سمعنا به في أفراته ووجدناه في موضع الغابة. فلندخل إلى مساكنه ونسجد في الموضع الذي فيه استقرت قدماه.\",\"r\":\"سمعنا به في أفراته ووجدناه في موضع الغابة، فلندخل إلى مساكنه ونسجد. أفراتة هي بيت لحم، حيث وُلد الرب. ذهب يوسف ومريم إليها بطاعة وتعب. افتح لنفسك طريقًا إلى بيت لحم اليوم بقراءة صغيرة من إنجيل لوقا.\",\"p\":\"يا رب، اجعلني أدخل إلى مساكنك وأسجد حيث استقرت قدماك. آمين.\",\"x\":\"سمعنا به في أفراته فلندخل إلى مساكنه ونسجد حيث استقرت قدماه. بيت لحم مقصد الشوق. تدريب: اكتب كلمة شوق واحدة للمسيح وصلِّ بها.\"},{\"t\":\"قيصر يأمر والله يدبّر\",\"ref\":\"لوقا ٢: ١\",\"bk\":\"لوقا\",\"v\":\"وفي تلك الأيام صدر أمر من أوغسطس قيصر بأن يكتتب كل المسكونة.\",\"r\":\"«وفي تلك الأيام صدر أمر من أوغسطس قيصر بأن يكتتب كل المسكونة». ظن القيصر أنه يعدّ رعاياه، وكان الله يعدّ مكان ميلاد ابنه. وأنا أتضايق أحيانًا من ظروف خارجة عن إرادتي. اليوم أتعلم أن يد الله تعمل خلف الأحداث، وأن ما يزعجني قد يكون جزءًا من خطة أكبر.\",\"p\":\"يا رب، أنت ضابط الكل ومدبّر الأحداث. علمني أن أثق في تدبيرك حين تتغير خطتي، وأن أرى يدك خلف كل ظرف، وأن أسلّم لك يومي بقلب مطمئن. آمين.\",\"x\":\"كان القيصر يحكم أقوى إمبراطورية في عصره، ومع ذلك لم يدرك أن أمره الإداري سيسوق يوسف ومريم من الناصرة إلى بيت لحم، فتتم نبوة ميخا التي قيلت قبل قرون عن مكان الميلاد. هكذا يستخدم الله الحكام، ولا يلغي حرية أحد. ويقول الحكيم: «قلب الملك في يد الرب كجداول مياه، حيثما شاء يميله». وهذا يعطينا سلامًا، فلا شيء يحدث خارج علم الله. وفي أيام الصوم نتذكر أن الله ضابط الكل، يرتب التاريخ كله لأجل خلاصنا.\\nاليوم، فكّر في ظرف يضايقك، وقل بإيمان: «يا رب، أنت تدبّر، وأنا أثق».\"},{\"t\":\"لباس يلتقطه أحد\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بمفو: يجب أن يرتدي الراهب لباسًا بحيث إذا رُمي خارج القلاية ثلاثة أيام لا يلتقطه أحد. الميلاد جاء في بساطة وفقر، في مذود وقماط. تخلَّ اليوم عن شيء كمالي في حياتك أو أعطه لمن يحتاجه.\",\"p\":\"يا رب، علّمني أن أحب بساطتك. ولا يتعلق قلبي بما يزول. آمين.\",\"x\":\"يقول الأب بمفو: الراهب يجب أن يرتدي لباسًا بحيث إذا رُمي خارج القلاية ثلاثة أيام لا يلتقطه أحد. وُلد المسيح في بساطة. تدريب: اختر اليوم بساطة في ملبسك.\",\"fq\":459}]},\"12-12\":{\"th\":\"بشارة الرعاة\",\"m\":[{\"t\":\"هللوا لله\",\"ref\":\"المزمور ٤٦ (٤٧) — الثالثة\",\"v\":\"يا جميع الأمم صفقوا بأيديكم، هللوا لله بصوت الابتهاج.\",\"r\":\"يدعو المرنم كل الأمم أن يصفقوا ويهللوا بصوت الابتهاج. وكان أول من هلل الرعاة البسطاء، سمعوا الخبر في الحقل ففرحوا. الفرح الكامل لا يحتاج إلى مكانة. ابحث اليوم عن سبب بسيط للتهليل، وقل شكرًا لله.\",\"p\":\"يا رب، أهلل لك بصوت الابتهاج. ملأتني فرحًا كالرعاة البسطاء. آمين.\",\"x\":\"يا جميع الأمم صفقوا بأيديكم هللوا لله بصوت الابتهاج. أول من هلل الرعاة البسطاء. تدريب: هلل اليوم بقلب بسيط: المجد لله في الأعالي.\"},{\"t\":\"ظهور الملاك للرعاة\",\"ref\":\"لوقا ٢: ٨–٩\",\"bk\":\"لوقا\",\"v\":\"وكان في تلك الكورة رعاة متبدين يحرسون حراسات الليل على رعيتهم، وإذا ملاك الرب وقف بهم، ومجد الرب أضاء حولهم، فخافوا خوفا عظيما.\",\"r\":\"«وكان في تلك الكورة رعاة متبدين يحرسون حراسات الليل». أول من سمع بشارة الميلاد كانوا بسطاء يعملون بأمانة في الظلام. لا يتجاهل الله من يخدم بصمت. وربما يعلن لي حضوره وأنا في عملي العادي المتعب، فأحتاج أن أكون ساهرًا وأمينًا.\",\"p\":\"يا رب، أشكرك لأنك تعلن ذاتك للبسطاء الأمناء. اجعلني أمينًا في عملي كأنني أسهر على رعيتك، وأرني مجدك في أيامي العادية. آمين.\",\"x\":\"كان الرعاة في نظر المجتمع طبقة متواضعة، ولم تكن شهادتهم تُقبل في المحاكم، ومع ذلك اختارهم الله ليكونوا أول شهود الميلاد. وهذا يوافق ما يقوله بولس: «اختار الله جهال العالم ليخزي الحكماء». والرعاة كانوا يسهرون على رعيتهم، فكانت أمانتهم مدخلًا للإعلان. أما الخوف الذي أصابهم فهو رهبة من يرى المجد الإلهي، وسيزيله صوت الملاك بقوله: «لا تخافوا». ومن يكن أمينًا في القليل يرَ مجد الله في حياته اليومية.\\nاليوم، أتمم عملك العادي بأمانة كاملة وكأنه خدمة لله، فقد يعلن لك فيه حضوره.\"},{\"t\":\"الأسد غير المنظور\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن إن داود لما عارك الأسد أمسك به من رقبته وقتله في الحال. ونحن إذا أمسكنا بحلقنا وبطننا نغلب بالله الأسد غير المنظور. الراعي الأمين يحرس نفسه أولًا. ضبط الشهوة يبدأ بأمر صغير، فاختر اليوم أن تضبط أمرًا واحدًا.\",\"p\":\"يا رب، علّمني أن أحرس نفسي كالراعي الأمين. واجعل نعمتك تقويني. آمين.\",\"x\":\"يقول الأب بيمن: إن داود لما عارك الأسد أمسك به من رقبته وقتله في الحال، ونحن إذا أمسكنا بحلقنا وبطننا نغلب بالله الأسد غير المنظور. تدريب: اضبط شهية واحدة اليوم.\",\"fq\":447}]},\"12-13\":{\"th\":\"الفرح بالمولود\",\"m\":[{\"t\":\"هللوا أمام الرب الملك\",\"ref\":\"المزمور ٩٧ (٩٨) — التاسعة\",\"v\":\"هللوا أمام الرب الملك. فليعج البحر وكل ملئه: المسكونة وكل الساكنين فيها.\",\"r\":\"هللوا أمام الرب الملك، فليعج البحر وكل ما فيه. الخليقة كلها تفرح بالميلاد، فلا يليق أن يصمت الإنسان. عبّر اليوم لأحد عن فرحك بالرب بكلمة صادقة قصيرة.\",\"p\":\"يا رب، لتهلل خليقتك كلها أمامك. وليكن لساني أول المهللين. آمين.\",\"x\":\"هللوا أمام الرب الملك فليعج البحر وكل ملئه. الخليقة تفرح بالميلاد. تدريب: عبّر اليوم عن فرحك بالميلاد لمن حولك.\"},{\"t\":\"وجدوا الطفل مضجعًا\",\"ref\":\"لوقا ٢: ١٦–١٧\",\"bk\":\"لوقا\",\"v\":\"فجاءوا مسرعين، ووجدوا مريم ويوسف والطفل مضجعا في المذود. فلما رأوه أخبروا بالكلام الذي قيل لهم عن هذا الصبي.\",\"r\":\"«فجاءوا مسرعين، ووجدوا مريم ويوسف والطفل مضجعًا في المذود». حين يسعى الإنسان بإخلاص يجد المسيح. لقد وجدوا الأمر كما قيل لهم، فازداد إيمانهم وصاروا يشهدون. أريد أن أكون مثلهم: أجد المسيح في الصلاة والإنجيل ثم أخبر الآخرين بفرحي.\",\"p\":\"يا رب، أشكرك لأنك تُظهر نفسك لمن يطلبك. أعطني أن أجدك كل يوم وأن أتحدث عنك بفرح وبساطة لكل من حولي. آمين.\",\"x\":\"لم يكتف الرعاة بأن يروا الطفل، بل أخبروا بما سمعوه، فصاروا أول المبشرين. وهذا مبدأ مهم في الحياة الروحية: اللقاء الحقيقي بالمسيح يتحول إلى شهادة طبيعية. ولم يكونوا علماء ولا وعاظًا، بل رعاة بسطاء ينقلون ما رأوا. والكنيسة تدعونا إلى الشهادة بالحياة قبل الكلام، ثم بالكلمة حين تُتاح الفرصة. فمن وجد كنزًا لا يكتمه. ومريم ويوسف في المشهد أيضًا يمثلان الجماعة المقدسة التي تنتظر القادمين إلى المسيح.\\nاليوم، شارك شخصًا بخبرة صغيرة من عمل الله معك هذا الأسبوع.\"},{\"t\":\"الكلام عن الله والصمت لأجله\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل أخ الأب بيمن: ما الأفضل، الكلام أم الصمت؟ فقال: إن من يتحدث عن الله فحسنًا يفعل، ومن يصمت حبًّا بالله يماثله. المهم الدافع: أن يكون للمحبة. أخبر اليوم أحدًا عن الله، أو اصمت لأجله، وكن في الحالين لله.\",\"p\":\"يا رب، اجعل كلامي وصمتي لك. ولتكن المحبة دافعي. آمين.\",\"x\":\"سأل أخ الأب بيمن ما الأفضل، الكلام أم الصمت؟ فقال: من يتحدث عن الله فحسنًا يفعل، ومن يصمت حبًّا بالله يماثله. الاثنان بالمحبة. تدريب: تكلم عن الله أو اصمت لأجله اليوم.\",\"fq\":422}]},\"12-14\":{\"th\":\"المجوس يسجدون\",\"m\":[{\"t\":\"كل الأمم يسجدون\",\"ref\":\"المزمور ٨٥ (٨٦) — السادسة\",\"v\":\"كل الأمم الذين خلقتهم يأتون ويسجدون أمامك يا رب، ويمجدون اسمك. لأنك أنت عظيم وصانع العجائب، أنت وحدك الإله العظيم.\",\"r\":\"كل الأمم التي خلقتها يأتون ويسجدون أمامك ويمجدون اسمك، وأنت وحدك الإله العظيم. بدأ السجود يتحقق حين جاء المجوس من بلاد بعيدة بالهدايا. اسجد اليوم في قلبك، وقدم هدية: وقتًا مع الله.\",\"p\":\"يا رب، أنت وحدك الإله العظيم. أسجد لك وأقدم لك قلبي هدية. آمين.\",\"x\":\"كل الأمم التي خلقتها يأتون ويسجدون أمامك، وأنت وحدك الإله العظيم. بدأ هذا السجود مع المجوس. تدريب: قدم اليوم هدية صغيرة لله: وقت أو مال أو خدمة.\"},{\"t\":\"أين هو المولود؟\",\"ref\":\"متى ٢: ١–٢\",\"bk\":\"متى\",\"v\":\"ولما ولد يسوع في بيت لحم اليهودية، في أيام هيرودس الملك، إذا مجوس من المشرق قد جاءوا إلى أورشليم قائلين: «أين هو المولود ملك اليهود؟ فإننا رأينا نجمه في المشرق وأتينا لنسجد له».\",\"r\":\"«أين هو المولود ملك اليهود؟ فإننا رأينا نجمه في المشرق وأتينا لنسجد له». قطعوا مسافات طويلة بحثًا عن الحق. أما أنا فأحيانًا لا أتحرك خطوة لأقترب من الله. أطلب اليوم قلبًا يبحث عن المسيح بشوق حقيقي ولا يكتفي بما هو قريب وسهل.\",\"p\":\"يا رب، أعطني شوق المجوس لأطلبك بكل قلبي. اجتذبني إليك بكل وسيلة، واجعل رحلتي نحوك أولوية حياتي. آمين.\",\"x\":\"كان المجوس علماء فلك من الشرق، ولم يكونوا من شعب الله، لكن الله خاطبهم بلغة يفهمونها: نجم. وهذا يبيّن أن الله يجتذب الجميع إليه بطرق مختلفة. وقد سألوا بتواضع: «أين هو؟»، وهدفهم واضح: «لنسجد له». لم يكن غرضهم الفضول ولا المنفعة. ويرى الآباء في رحلتهم صورة لدعوة الأمم إلى الإيمان. والسعي الصادق يكافأ دائمًا باللقاء، كما قال الرب: «اطلبوا تجدوا».\\nاليوم، خصص وقتًا إضافيًا للبحث عن الله: اقرأ فصلًا من الإنجيل بتمهل وبشوق.\"},{\"t\":\"اهرب من الناس\",\"ref\":\"\",\"v\":\"\",\"r\":\"كان الأب أرسانيوس في البلاط الملكي يصلي: يا رب عرّفني كيف أخلص. فجاءه صوت: اهرب من الناس تخلص. ترك قصر الملك وسلك طريقًا لم يتوقعه أحد. كذلك رجع المجوس في طريق أخرى. اترك اليوم لحظة ضوضاء لتخلو بالله.\",\"p\":\"يا رب، عرّفني كيف أخلص. وأعطني شجاعة الاعتزال حين تدعوني. آمين.\",\"x\":\"كان الأب أرسانيوس في البلاط الملكي يصلي: يا رب عرّفني كيف أخلص، فجاءه صوت: اهرب من الناس تخلص. ترك قصر الملك وتبع الصوت. تدريب: اترك اليوم ما يعيقك عن السجود.\",\"fq\":23}]},\"12-15\":{\"th\":\"حفظ الله وطاعة الابن\",\"m\":[{\"t\":\"تحت جناحيه تعتصم\",\"ref\":\"المزمور ٩٠ (٩١) — السادسة\",\"v\":\"لأنه ينجيك من فخ الصياد. ومن كلمة مقلقة. في وسط منكبيه يظللك، وتحت جناحيه تعتصم، عدله يحيط بك كالسلاح.\",\"r\":\"ينجيك الله من فخ الصياد ومن كلمة مقلقة، وتحت جناحيه تعتصم. هكذا حفظ الله الطفل يسوع في الهروب إلى مصر. نحن لا نعرف الطريق دائمًا، لكن الله يعرف. سلّم اليوم موضع قلق واحد لجناحيه.\",\"p\":\"يا رب، احفظني تحت جناحيك. وإذا اضطررت للهروب فكن أنت طريقي. آمين.\",\"x\":\"ينجيك الله من فخ الصياد ومن كلمة مقلقة، وتحت جناحيه تعتصم. هكذا حفظ الطفل في مصر. تدريب: سلّم الله قلقك من رسالة أو كلمة.\"},{\"t\":\"قم وخذ الصبي وأمه\",\"ref\":\"متى ٢: ١٣\",\"bk\":\"متى\",\"v\":\"وبعدما انصرفوا، إذا ملاك الرب قد ظهر ليوسف في حلم قائلا: «قم وخذ الصبي وأمه واهرب إلى مصر، وكن هناك حتى أقول لك. لأن هيرودس مزمع أن يطلب الصبي ليهلكه».\",\"r\":\"«قم وخذ الصبي وأمه واهرب إلى مصر». لم يناقش يوسف الأمر ولم يؤجل. هو يحمي الابن وأمه بطاعة صامتة. أنظر اليوم إلى حياتي: هل أطيع وصايا الله حتى لو لم أفهم كل التفاصيل؟ طاعة يوسف جعلته أداة لحفظ الله لابنه.\",\"p\":\"يا رب، احفظني كما حفظت عائلتك المقدسة في مصر. امنحني طاعة يوسف وإيمانه، وبارك أرضنا وشعبنا بنعمة حضورك. آمين.\",\"x\":\"في الأمر الإلهي تحول الخطر إلى طريق نحو مصر، فصارت أرضنا أرض مباركة بحضور العائلة المقدسة. وتحتفل كنيستنا بدخول العائلة المقدسة إلى مصر في الرابع والعشرين من بشنس، وهو الأول من يونيو. ويعلمنا الحدث أن الله لا يعد بحياة بلا ضيق، بل بحفظ في وسط الضيق. فقد حفظ الصبي في المنفى. ويتعلم يوسف أن الإيمان يتحرك بسرعة، فقام في الليل وهرب. وطاعة يوسف نموذج لمن يعمل ما يطلبه الله بلا تأخير.\\nاليوم، تذكر موقفًا تردد فيه قلبك أمام وصية، وقرر أن تطيع بلا جدال.\"},{\"t\":\"خير لي أن أهرب\",\"ref\":\"\",\"v\":\"\",\"r\":\"لما هرب الأب نيسثروس من تنين رآه في البرية، قال له أخ: وأنت أيضًا تخاف يا أبت؟ فقال: لا أخاف، لكن خير لي أن أهرب، وإلا فلن يمكنني أن أهرب من روح المجد الفارغ. أحيانًا الحكمة في الابتعاد. ابتعد اليوم عن موقف يجرحك.\",\"p\":\"يا رب، علّمني متى أهرب ومتى أثبت. واحفظني من المجد الفارغ. آمين.\",\"x\":\"لما هرب الأب نيسثروس من تنين قال له أخ: وأنت أيضًا تخاف؟ فأجاب: لا أخاف لكن خير لي أن أهرب وإلا فلن أهرب من روح المجد الفارغ. الهروب من المجد الباطل. تدريب: اهرب اليوم من فرصة تفاخر.\",\"fq\":297}]},\"12-16\":{\"th\":\"الاسم والانتظار\",\"m\":[{\"t\":\"وأريه خلاصي\",\"ref\":\"المزمور ٩٠ (٩١) — السادسة\",\"v\":\"ومن طول الأيام أشبعه. وأريه خلاصي.\",\"r\":\"ومن طول الأيام أشبعه وأريه خلاصي. انتظر سمعان الشيخ سنين طويلة، فرأى الخلاص بعينيه. الانتظار لله ليس ضياعًا للوقت. ماذا تنتظر من الله اليوم؟ قل له: أنا منتظر، وأريد أن أرى خلاصك.\",\"p\":\"يا رب، علّمني الصبر في الانتظار. أرني خلاصك كما أريته لسمعان. آمين.\",\"x\":\"ومن طول الأيام أشبعه وأريه خلاصي. انتظر سمعان الشيخ سنين فرأى الخلاص. تدريب: اصبر اليوم على أمر طال انتظاره.\"},{\"t\":\"سُمي يسوع\",\"ref\":\"لوقا ٢: ٢١\",\"bk\":\"لوقا\",\"v\":\"ولما تمت ثمانية أيام ليختنوا الصبي سمي يسوع، كما تسمى من الملاك قبل أن حبل به في البطن.\",\"r\":\"«ولما تمت ثمانية أيام ليختنوا الصبي سمي يسوع». اسمه يعني «يهوه يخلص». لهذا الاسم قوة وعزاء. حين أخاف أو أتعب أستطيع أن أنطق به، فهو يذكّرني بأن لي مخلصًا قريبًا. أريد أن يكون اسم يسوع على شفتي وفي قلبي اليوم.\",\"p\":\"يا يسوع، يا اسمًا حلوًا يعزي القلوب. ليكن اسمك على شفتي وفي قلبي، وخلصني من خطاياي ومخاوفي. لك المجد إلى الأبد. آمين.\",\"x\":\"أخضع المسيح نفسه للناموس بالختان، وهو واضع الناموس، تواضعًا ومشاركة لنا. والاسم الذي أُعطي له من السماء قبل الحبل به يكشف رسالته: «يخلص شعبه من خطاياهم». وتعلمنا الكنيسة الصلاة باسمه، ففي صلاة يسوع نكرر «يا ربي يسوع المسيح ارحمني». ويقول بولس: «لتجثو باسم يسوع كل ركبة». وفي الاسم حضور وسلطان وحنان. فاسمه ليس مجرد لقب بل هو دعوة إلى الثقة والتوبة.\\nاليوم، كرر في هدوء «يا ربي يسوع المسيح ارحمني» كلما شعرت بقلق، سبع مرات على الأقل.\"},{\"t\":\"أربع عشرة سنة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول القديس أمون: أمضيت أربع عشرة سنة في الإسقيط متضرعًا إلى الله ليل نهار أن يمنحني القوة لأتغلب على الغضب. لم يمل ولم يكل. الثبات في الطلبة يثمر. اختر اليوم عادة واحدة تتعب منها، وصلِّ من أجلها بإصرار.\",\"p\":\"يا رب، أعطني صبرًا في الصلاة. ولا أمل حتى أرى عمل نعمتك فيَّ. آمين.\",\"x\":\"يقول القديس أمون: أمضيت أربع عشرة سنة في الأسقيط متضرعًا إلى الله ليل نهار أن يمنحني القوة لأتغلب على الغضب. الجهاد في الغضب طويل. تدريب: ثابر في الصلاة على ضعف واحد.\",\"fq\":61}]},\"12-17\":{\"th\":\"لماذا تجسد؟\",\"m\":[{\"t\":\"قطعت قيودي\",\"ref\":\"المزمور ١١٥ — التاسعة\",\"v\":\"يا رب أنا عبدك. أنا عبدك وابن أمتك. قطعت قيودي.\",\"r\":\"يا رب أنا عبدك وابن أمتك، قطعت قيودي. جاء المسيح ليحرر من الخوف من الموت الذين كانوا طوال الحياة تحت العبودية. قد ربطتك عادة أو خوف؟ قل له اليوم باسمه: اقطع قيدي.\",\"p\":\"يا رب، أنا عبدك. اقطع قيودي، وحررني من كل عبودية. آمين.\",\"x\":\"يا رب أنا عبدك وابن أمتك قطعت قيودي. جاء المسيح ليحرر من خوف الموت. تدريب: سمِّ قيدًا يربطك وسلمه للمسيح.\"},{\"t\":\"ليبيد الموت\",\"ref\":\"العبرانيين ٢: ١٤–١٥\",\"bk\":\"العبرانيين\",\"v\":\"فإذ قد تشارك الأولاد في اللحم والدم اشترك هو أيضا كذلك فيهما، لكي يبيد بالموت ذاك الذي له سلطان الموت، أي إبليس، ويعتق أولئك الذين- خوفا من الموت- كانوا جميعا كل حياتهم تحت العبودية.\",\"r\":\"«فإذ قد تشارك الأولاد في اللحم والدم اشترك هو أيضًا كذلك فيهما، لكي يبيد بالموت ذاك الذي له سلطان الموت». أخاف أحيانًا من المرض والفقد والنهاية. لكن المسيح دخل الموت وكسر شوكته. فلست عبدًا للخوف، لأن لي مخلصًا غلب الموت وفتح لي باب الحياة.\",\"p\":\"يا رب، أنت الذي غلبت الموت بموتك. حرّرني من كل خوف يستعبدني، وثبّت رجائي في القيامة والحياة الأبدية معك. آمين.\",\"x\":\"يوضح الكاتب أن سبب التجسد هو الاشتراك الكامل في إنسانيتنا حتى الموت، لأن اللاهوت لا يموت، فاحتاج أن يأخذ جسدًا قابلًا للموت ليغلب به الموت من الداخل. وهذه فكرة أساسية عند آباء الكنيسة، وخاصة القديس أثناسيوس في كتاب «تجسد الكلمة». والخوف من الموت قيد يستعبد الناس لعيشة الأنانية، أما المسيح فيحررنا منه بالقيامة. ولذلك يعيش المؤمن بلا رعب، متطلعًا إلى الحياة الأبدية.\\nاليوم، سلّم المسيح خوفًا يقيّدك (مرض، فقد، مستقبل)، وقل له: «أنت غلبت الموت، فأنا لا أخاف».\"},{\"t\":\"ما قوة الخطية\",\"ref\":\"\",\"v\":\"\",\"r\":\"يسأل الأب إيليا: ما قوة الخطيئة عندما توجد التوبة؟ كذلك ما نفع المحبة عندما يظهر الكبرياء؟ التوبة أقوى من السقوط، والكبرياء يفسد الفضيلة. لا تيأس اليوم من سقطة، وابدأ بتوبة صغيرة، ولا تتكبر بفضيلة.\",\"p\":\"يا رب، أعطني توبة تغلب خطيتي، وتواضعًا يحفظ فضائلي. آمين.\",\"x\":\"يسأل الأب إيليا: ما قوة الخطيئة عندما توجد التوبة؟ كذلك ما نفع المحبة عندما يظهر الكبرياء؟ التوبة أقوى من السقوط. تدريب: تب اليوم بدل أن تيأس من سقطتك.\",\"fq\":128}]},\"12-18\":{\"th\":\"ظهور النعمة\",\"m\":[{\"t\":\"اعترفوا للرب\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"اعترفوا للرب لأنه صالح وأن إلى الأبد رحمته.\",\"r\":\"اعترفوا للرب لأنه صالح وأن إلى الأبد رحمته. النعمة المخلصة ظهرت للجميع، وهي عطية لا نستحقها، والجواب عليها هو الشكر. اكتب اليوم ثلاث نعم تتعامل معها كأنها حق لك، واشكر عليها.\",\"p\":\"يا رب، أعترف لك لأنك صالح. أشكرك على نعمتك التي ظهرت لنا. آمين.\",\"x\":\"اعترفوا للرب لأنه صالح وإلى الأبد رحمته. النعمة المخلصة ظهرت للجميع عطيةً لا نستحقها. تدريب: اشكره اليوم على نعمة لم تستحقها.\"},{\"t\":\"نعمة الله المخلصة\",\"ref\":\"تيطس ٢: ١١–١٢\",\"bk\":\"تيطس\",\"v\":\"لأنه قد ظهرت نعمة الله المخلصة، لجميع الناس، معلمة إيانا أن ننكر الفجور والشهوات العالمية، ونعيش بالتعقل والبر والتقوى في العالم الحاضر،\",\"r\":\"«لأنه قد ظهرت نعمة الله المخلصة لجميع الناس». النعمة ظهرت في شخص المسيح. وهي لا تتركني كما أنا، بل تعلمني أن أنكر الشر وأعيش بتعقل وبر وتقوى. أشكر الله على نعمته، وأطلب أن تقودني لحياة جديدة هذا اليوم.\",\"p\":\"أشكرك يا رب على نعمتك المخلصة. علمني أن أنكر كل شر، وأن أعيش بتعقل وبر وتقوى في هذا العالم، منتظرًا مجيئك المبارك. آمين.\",\"x\":\"يرى بولس في التجسد ظهور النعمة، وهي هبة مجانية للجميع. لكنها ليست رخصة للتهاون، بل مدرسة تعلّم: تُنكِر الفجور، وتُهذّب الشهوات، وتُدرّب على ثلاثة: التعقل في علاقتنا بأنفسنا، والبر مع الناس، والتقوى مع الله. فالنعمة تخلص وتغير. ومن يقبل نعمة الميلاد يتغير سلوكه. وفي تدبير الكنيسة، الأصوام والصلوات وسائل نتعاون بها مع النعمة، لا بديل عنها.\\nاليوم، طبّق واحدة من الثلاث: تعقل في كلامك، أو بر مع شخص، أو تقوى في صلاة مركزة.\"},{\"t\":\"الفضيلة المفقودة\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب بتنهد: كل الفضائل دخلت إلى هذا البيت ما عدا واحدة، بدونها بالجهد يصمد الإنسان. وسألوه: وما هي؟ فأجاب: أن يلوم الإنسان نفسه. من يلوم نفسه يقبل النعمة. اليوم، قبل أن تلوم أحدًا، تأمل ما نصيبك أنت من الخطأ.\",\"p\":\"يا رب، علّمني أن ألوم نفسي لا غيري. واملأ قلبي بنعمتك. آمين.\",\"x\":\"قال الأب بتنهد: كل الفضائل دخلت إلى هذا البيت ما عدا واحدة، بدونها بالجهد يصمد الإنسان، وهي أن يلوم الإنسان نفسه. لوم النفس يحفظ البقية. تدريب: لُم نفسك اليوم لا غيرك.\",\"fq\":411}]},\"12-19\":{\"th\":\"الطفل الذي ينمو\",\"m\":[{\"t\":\"مذابحك يا رب\",\"ref\":\"المزمور ٨٣ (٨٤) — السادسة\",\"v\":\"لأن العصفور وجد له بيتا، واليمامة عشا لتضع فيه أفراخها. مذابحك يا رب إله القوات، ملكي وإلهي.\",\"r\":\"العصفور وجد بيتًا، واليمامة عشًّا، ومذابحك يا رب ملكي وإلهي. وجد الطفل يسوع بيته في هيكل أبيه، وقال: ينبغي أن أكون فيما لأبي. هل لك مكان مع الله تشعر فيه بالبيت؟ اجعل لك اليوم لحظة في الكنيسة أو في ركن صلاة.\",\"p\":\"يا رب، مذبحك بيتي وراحتي. اجعلني أعشق بيتك وأسكن فيه كل أيام حياتي. آمين.\",\"x\":\"العصفور وجد بيتًا ومذابحك يا رب ملكي وإلهي. وجد الطفل يسوع بيته في هيكل أبيه وقال: ينبغي أن أكون فيما لأبي. تدريب: اجعل بيت الله بيتك اليوم ولو لساعة.\"},{\"t\":\"ينمو ويتقوى بالروح\",\"ref\":\"لوقا ٢: ٤٠\",\"bk\":\"لوقا\",\"v\":\"وكان الصبي ينمو ويتقوى بالروح، ممتلئا حكمة، وكانت نعمة الله عليه.\",\"r\":\"«وكان الصبي ينمو ويتقوى بالروح، ممتلئًا حكمة، وكانت نعمة الله عليه». حتى المسيح في ناسوته مرّ بمراحل النمو. فلا أتعجل ثمرة روحية سريعة ولا أيأس من بطء تقدمي. المهم أن أنمو يومًا بعد يوم في الصلاة والحكمة والنعمة.\",\"p\":\"يا رب، كما نما الصبي يسوع في الحكمة والنعمة، نمِّني أنا أيضًا. علمني الصبر في النمو، وبارك أسرتي لتكون بيتًا تسكنه نعمتك. آمين.\",\"x\":\"تبين الآية واقعية التجسد، فالمسيح عاش طفولة حقيقية وكبر مثلنا، وكانت حكمته تظهر تدريجيًا في ناسوته. وتتحدث الآية عن النمو في ثلاثة: القوة، والحكمة، والنعمة. وهذا يدعونا إلى الاهتمام بالنمو المتوازن، ولا نكتفي بالمعرفة وحدها. وبيت الناصرة كان مدرسة للتربية الروحية بين يوسف ومريم. والأسرة المسيحية مدعوة لتكون مثل بيت الناصرة، يتربى فيه الأولاد على حب الله.\\nاليوم، اختر عادة روحية صغيرة تنمّيها هذا الأسبوع، كقراءة آية يوميًا، والتزم بها.\"},{\"t\":\"لا تسبق أحدًا بالكلام\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل الأب أفربيوس في بداية حياته ناسكًا: قل لي كلمة، كيف أخلص؟ فأجابه: إذا أردت أن تخلص لازم عدم الكلام، ولا تسبق أحدًا إليه، ولا تتكلم قبل أن يسألوك. وهكذا كان يسوع بين المعلمين: يسمع ويسأل. اسمع اليوم أكثر مما تتكلم.\",\"p\":\"يا رب، علّمني أن أسمع قبل أن أتكلم. ولتكن كلماتي قليلة ونافعة. آمين.\",\"x\":\"سأل الأب أفربيوس في بداية حياته ناسكًا: قل لي كلمة كيف أخلص؟ فأجابه: إذا أردت أن تخلص فلا بد من عدم الكلام، ولا تسبق أحدًا إليه، ولا تتكلم قبل أن يسألوك. تدريب: لا تبدأ الحديث اليوم في اجتماع.\",\"fq\":107}]},\"12-20\":{\"th\":\"السهر في كيهك\",\"m\":[{\"t\":\"يا رب إليك صرخت\",\"ref\":\"المزمور ١٤٠ (١٤١) — النوم\",\"v\":\"يا رب إليك صرخت فاستمع لي. أنصت إلى صوت تضرعي. إذا ما صرخت إليك.\",\"r\":\"يا رب إليك صرخت فاستمع لي، أنصت إلى صوت تضرعي إذا صرخت إليك. شهر كيهك شهر السهر والتسبيح، ننتظر فيه مجيء الرب. جرّب اليوم أن تصلي صلاة قصيرة في وقت لم تعتد الصلاة فيه.\",\"p\":\"يا رب، إليك صرخت فاستمع لي. اجعل سهري صلاة، وصلاتي سهرًا. آمين.\",\"x\":\"يا رب إليك صرخت فاستمع لي. كيهك شهر السهر والتسبيح ننتظر فيه مجيء الرب. تدريب: صلِّ اليوم تسبحة كيهك أو مزمورًا قبل النوم.\"},{\"t\":\"الواقفون بالليل\",\"ref\":\"المزامير ١٣٤: ١–٢\",\"bk\":\"المزامير\",\"v\":\"هوذا باركوا الرب يا جميع عبيد الرب، الواقفين في بيت الرب بالليالي. ارفعوا أيديكم نحو القدس، وباركوا الرب.\",\"r\":\"«هوذا باركوا الرب يا جميع عبيد الرب، الواقفين في بيت الرب بالليالي». تقف الكنيسة في شهر كيهك لتسبّح في الليل قبل الفجر. حتى لو لم أستطع الذهاب، أخصص دقائق في الليل للتسبيح، فأرفع يدي وقلبي وأبارك الرب.\",\"p\":\"يا رب، أبارِكك في ليالي حياتي كلها. علمني أن أسهر معك، وارفع يدي وقلبي نحوك، واقبل تسبيحي مع الكنيسة المصلية في كل مكان. آمين.\",\"x\":\"كان اللاويون يخدمون في الهيكل ليلًا، وجاء هذا المزمور تحية لهم. وتحافظ الكنيسة القبطية على تقليد التسبيح الليلي، وخاصة في شهر كيهك الذي يُعرف بتسبحته الخاصة قبل عيد الميلاد، وتمجد فيها السيدة العذراء والتجسد. ويدعونا المزمور إلى رفع الأيدي، وهو علامة الصلاة والتسليم. وفي صلاة الليل نختبر هدوءًا خاصًا يساعد على الاتحاد بالله بعيدًا عن ضجيج النهار.\\nاليوم، قبل النوم رتل مزمور 134 بصوت خافت، وارفع يديك لحظة وبارك الرب.\"},{\"t\":\"أتعب الفضائل\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل الإخوة القديس أغاثون: ما هي الفضيلة التي تتطلب تعبًا أكثر من سواها؟ فقال: لا يوجد تعب كتعب الصلاة إلى الله، لأن الأعداء يسعون لإيقافه، ولأن الصلاة تحتاج إلى جهاد يدوم حتى النسمة الأخيرة. لا تتوقف اليوم عن صلاتك حين تتعب.\",\"p\":\"يا رب، قوّني في جهاد الصلاة. ولا تدعني أتوقف حتى النسمة الأخيرة. آمين.\",\"x\":\"سأل الإخوة القديس أغاثون أي فضيلة تتطلب تعبًا أكثر؟ فقال: لا يوجد تعب كتعب الصلاة إلى الله، لأن الأعداء يسعون لإيقافها لأنهم يعرفون أن لا شيء يعيقهم كالصلاة. تدريب: ثابر في صلاتك اليوم رغم الصعوبة.\",\"fq\":50}]},\"12-21\":{\"th\":\"السهر والصلاة\",\"m\":[{\"t\":\"أمال أذنه إلي\",\"ref\":\"المزمور ١١٤ — التاسعة\",\"v\":\"أحببت أن يسمع الرب صوت تضرعي. لأنه أمال أذنه إلي فأدعوه كل أيامي.\",\"r\":\"أحببت أن يسمع الرب صوت تضرعي، لأنه أمال أذنه إلي فأدعوه كل أيامي. الله ينحني ليسمعنا. هل ننحني نحن لنسمعه؟ اقضِ اليوم خمس دقائق تتكلم فيها مع الله بكلماتك أنت، ثم اصمت لتسمع.\",\"p\":\"يا رب، لقد أملت أذنك إليّ. أدعوك كل أيامي، فلا تغب عني. آمين.\",\"x\":\"أحببت أن يسمع الرب صوت تضرعي لأنه أمال أذنه إلي. الله ينحني ليسمعنا، فهل ننحني لنسمعه؟ تدريب: اقض اليوم دقائق صمت تسمع فيها.\"},{\"t\":\"أقوم في منتصف الليل\",\"ref\":\"المزامير ١١٩: ٦٢\",\"bk\":\"المزامير\",\"v\":\"في منتصف الليل أقوم لأحمدك على أحكام برك.\",\"r\":\"«في منتصف الليل أقوم لأحمدك على أحكام برك». حين يصمت العالم يصير القلب أقدر على الإصغاء. لا أنتظر أن أمتلك وقتًا طويلًا للصلاة، بل أقتطع لحظات من الليل أو الفجر أقول فيها لله شكرًا وحمدًا. أطلب اليوم قلبًا يسبقه الشوق إلى لقاء الله.\",\"p\":\"يا رب، أحمدك على أحكام برك. أيقظ قلبي لتسبيحك في هدوء الليل، وامنحني شوقًا حقيقيًا للقائك قبل كل شيء آخر. آمين.\",\"x\":\"يعبر المرنم عن حب يتجاوز الواجب، فهو يقوم من نومه لأن قلبه مشتاق، لا لأن أحدًا يحاسبه. وفي تقليد الكنيسة تُقام صلاة نصف الليل ضمن صلوات الأجبية، وهي تذكير بمجيء العريس. وعندما نصلي في ساعة الهدوء نكتشف عمق علاقتنا بالله بعيدًا عن الانشغال. ولا يطلب الله منا بطولات، بل أمانة صغيرة تتكرر. ومن يعتاد هذا اللقاء الليلي يجد فيه سلامًا يمتد إلى نهاره.\\nاليوم، قبل النوم أو عند الاستيقاظ، صلِّ مزمور 119 آية 62 ثلاث مرات ثم اشكر الله بكلماتك.\"},{\"t\":\"السهر يذيب الجسد\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب ثيوذوتس: إن حاجة الخبز تذيب جسد الراهب. وقال أب آخر: لكن السهر يذيب الجسد أكثر. السهر الروحي يهز الجسد والنفس معًا. في كيهك، اسهر قليلًا في الصلاة هذه الليلة، ولو بتسبحة واحدة.\",\"p\":\"يا رب، أعطني قوة السهر لأصلي. واجعل سهري ثمرًا بعد التعب. آمين.\",\"x\":\"قال الأب ثيوذوتس: إن حاجة الخبز تذيب جسد الراهب، وقال أب آخر: لكن السهر يذيب الجسد أكثر. السهر جهاد. تدريب: اسهر اليوم ربع ساعة للصلاة.\",\"fq\":143}]},\"12-22\":{\"th\":\"استيقظ أيها النائم\",\"m\":[{\"t\":\"ليبتهج بك الملتمسون\",\"ref\":\"المزمور التاسع والستون — باكر\",\"v\":\"وليبتهج ويفرح بك جميع الذين يلتمسونك. وليقل في كل حين محبو خلاصك: فليتعظم الرب.\",\"r\":\"ليبتهج ويفرح بك جميع الذين يلتمسونك، وليقل في كل حين محبو خلاصك: فليتعظم الرب. التمس الرب اليوم لا في أحداث كبيرة بل في تفاصيل بسيطة. وقل في كل حين: فليتعظم الرب.\",\"p\":\"يا رب، لتفرح بك نفسي وأنا أطلبك. فليتعظم اسمك في كل حين. آمين.\",\"x\":\"ليبتهج ويفرح بك جميع الذين يلتمسونك. التمس الرب اليوم في الصغائر. تدريب: ابحث اليوم عن أثر لله في ثلاثة مواقف.\"},{\"t\":\"فيضيء لك المسيح\",\"ref\":\"أفسس ٥: ١٤\",\"bk\":\"أفسس\",\"v\":\"لذلك يقول: «استيقظ أيها النائم وقم من الأموات فيضيء لك المسيح».\",\"r\":\"«استيقظ أيها النائم وقم من الأموات فيضيء لك المسيح». أحيانًا أنام روحيًا وأنا أتحرك، فأعيش بلا انتباه لمحبة الله. هذه الآية تدعوني إلى استيقاظ حقيقي: أن أقوم من عادات الموت، فيضيء لي المسيح طريقي. اليوم أطلب نعمة اليقظة.\",\"p\":\"يا نور العالم، أيقظني من كل غفلة ونوم روحي. أضئ لي طريقي، وأقمني من الموت إلى الحياة، لأعيش اليوم في نورك. آمين.\",\"x\":\"يرى بعض الدارسين أن هذه الكلمات جزء من ترنيمة كانت تُنشد في المعمودية في الكنيسة الأولى، فالمعمودية قيامة من موت الخطية إلى نور المسيح. وهي دعوة مستمرة لكل مؤمن، فنحن نحتاج أن نستيقظ كل يوم بالتوبة. وليس النوم هنا راحة الجسد بل غفلة الروح. والمسيح لا يقتصر على إيقاظنا، بل يضيء لنا، أي يعطينا نورًا لنرى الطريق. ولا نستيقظ بجهدنا وحده، بل بنعمته التي تناديني.\\nاليوم، عند استيقاظك صباحًا، قل: «استيقظ يا قلبي، فيضيء لي المسيح»، وابدأ يومك بصلاة قصيرة.\"},{\"t\":\"الصاحي ينهض للصلاة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب ثيوذورس: يأتي الفكر فيزعجني ويشغلني ويعيقني عن الفضيلة. أما الرجل الصاحي فينهض للصلاة عندما يهاجمه الفكر. استيقظ من الغفلة الروحية وقم عند أول فكر مزعج وصلِّ.\",\"p\":\"يا رب، أيقظني من غفلتي. وعند كل فكر مزعج اجعلني أنهض للصلاة. آمين.\",\"x\":\"يقول الأب ثيوذورس: يأتي الفكر فيزعجني ويشغلني ويعيقني عن الفضيلة، أما الرجل الصاحي فينهض للصلاة عندما يهاجمه الفكر. اليقظة بالصلاة. تدريب: حوّل أول فكر مزعج اليوم إلى صلاة.\",\"fq\":142}]},\"12-23\":{\"th\":\"المشرق من العلاء\",\"m\":[{\"t\":\"أضاءت بروقه\",\"ref\":\"المزمور ٩٦ (٩٧) — التاسعة\",\"v\":\"أضاءت بروقه المسكونة.\",\"r\":\"أضاءت بروقه المسكونة. جاء الإله المتجسد كنور في الظلمة، فأضاء لجالسين في ظلال الموت. في هذه الأيام الأخيرة قبل العيد، أضئ ركنًا مظلمًا في بيتك أو قلبك بعمل محبة.\",\"p\":\"يا مشرق من العلاء، أضئ حياتي. وليضئ نورك من خلالي لمن حولي. آمين.\",\"x\":\"أضاءت بروقه المسكونة. جاء الإله المتجسد نورًا في الظلمة. تدريب: أضئ اليوم في بيتك مكانًا مظلمًا بعمل صغير من الدفء.\"},{\"t\":\"افتقدنا المشرق\",\"ref\":\"لوقا ١: ٧٨–٧٩\",\"bk\":\"لوقا\",\"v\":\"بأحشاء رحمة إلهنا التي بها افتقدنا المشرق من العلاء. ليضيء على الجالسين في الظلمة وظلال الموت، لكي يهدي أقدامنا في طريق السلام».\",\"r\":\"«بأحشاء رحمة إلهنا التي بها افتقدنا المشرق من العلاء». لم أذهب أنا إلى النور، بل جاء النور إليّ. الله افتقدني برحمته وأنا في ظلمتي. أشكره اليوم على هذه الزيارة الإلهية، وأطلب أن يهدي خطواتي إلى طريق السلام في بيتي وعملي.\",\"p\":\"يا مشرق من العلاء، أشكرك لأنك افتقدتني برحمتك. أضئ ظلمات قلبي، واهدِ أقدامي في طريق السلام، واحفظ بيتي في نورك. آمين.\",\"x\":\"هذه الكلمات من تسبحة زكريا التي نطق بها بعد ولادة يوحنا، وهي تنبئ بمجيء المسيح «المشرق». فالمسيح هو الشمس التي تشرق على الجالسين في الظلمة. وتعبير «أحشاء رحمة» يصور حنان الله الأبوي. وأما الهدف فهو أن يهدي أقدامنا في طريق السلام، أي أنه لا يكتفي بإضاءة المكان بل يرشدنا في المسير. وبهذا ننظر إلى كل صباح جديد على أنه افتقاد من المشرق.\\nاليوم، عند خروجك من البيت ارفع قلبك قائلًا: «اهدِ خطواتي يا رب في طريق السلام».\"},{\"t\":\"من يسهر لا يكترث\",\"ref\":\"\",\"v\":\"\",\"r\":\"سمع الأب إسحق صوت طائر، فسأل الأب بيمن: هل يوجد مثل هذه الأصوات هنا؟ فأجابه: أمثالك يصغون إلى هذه الأصوات، لكن من يسهر لا يكترث لها. من ينشغل بالله لا تشغله الأصوات. في هذه الليالي، سلّم قلبك للصمت والترقب.\",\"p\":\"يا رب، اجعل قلبي ساهرًا فلا تشغله الأصوات. وانتظرك بقلب مستعد. آمين.\",\"x\":\"سمع الأب إسحق صوت طائر وسأل الأب بيمن هل توجد مثل هذه الأصوات هنا؟ فأجابه: أمثالك يصغون إلى هذه الأصوات، لكن من يسهر لا يكترث لها. تدريب: لا تدع شيئًا يشتت سهرك الليلة.\",\"fq\":390}]},\"12-24\":{\"th\":\"الرجاء المبارك\",\"m\":[{\"t\":\"لا تبطئ\",\"ref\":\"المزمور التاسع والستون — باكر\",\"v\":\"وأما أنا فمسكين وفقير اللهم أعنى. أنت معيني ومخلصي يا رب فلا تبطئ.\",\"r\":\"أنا مسكين وفقير، اللهم أعني. أنت معيني ومخلصي يا رب فلا تبطئ. هو صراخ منتظر ينتظر مجيء المسيح. الليلة تنتظر الكنيسة الميلاد. قل اليوم من قلبك: تعال يا رب يسوع.\",\"p\":\"يا رب يسوع، أنا مسكين وفقير. تعال وأعنّي ولا تبطئ. آمين.\",\"x\":\"أنا مسكين وفقير اللهم أعني، أنت معيني ومخلصي فلا تبطئ. هو صراخ منتظر مجيء المسيح. تدريب: الليلة قل: تعال أيها الرب يسوع.\"},{\"t\":\"منتظرين الرجاء المبارك\",\"ref\":\"تيطس ٢: ١٣\",\"bk\":\"تيطس\",\"v\":\"منتظرين الرجاء المبارك وظهور مجد الله العظيم ومخلصنا يسوع المسيح،\",\"r\":\"«منتظرين الرجاء المبارك وظهور مجد الله العظيم ومخلصنا يسوع المسيح». أعيش بين ميلاد مضى ومجيء قادم. الأول يعطيني اطمئنانًا لأن الله اقترب، والثاني يعطيني رجاءً لأن العدل قادم. أنتظر اليوم برجاء هادئ وأعمل بأمانة.\",\"p\":\"يا ربي يسوع، يا رجائي المبارك، أنتظر ظهور مجدك. ثبّتني في الإيمان والعمل الصالح، وأعطني فرحًا ورجاء في كل أيامي. آمين.\",\"x\":\"يصف بولس المسيح هنا بأنه «الله العظيم ومخلصنا»، وهي شهادة واضحة للاهوته. والانتظار المسيحي ليس سلبيًا، فهو يتضمن عملاً صالحًا ونقاوة، كما تقول الآيات السابقة. وفي كل قداس نعلن: «نبشر بموتك ونعترف بقيامتك المقدسة وصعودك إلى السماء، وبمجيئك الثاني». فالنظر إلى الأمام يعطي معنى للحاضر. ولا يكون الرجاء حقيقيًا إلا إذا بنينا حياتنا عليه.\\nاليوم، اكتب جملة رجاء عن المستقبل، وقل لله: «أنت رجائي المبارك».\"},{\"t\":\"أخاف ثلاثة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيليا: أخاف ثلاثة: عندما توشك نفسي أن تفارق جسدي، وعندما انتصب أمام الله، وعندما يصدر الحكم بحقي. الذي يخاف من مجيء الديان يستعد لمجيء المخلص. وفي الليلة الأخيرة قبل العيد، اعترف بخطيتك واستقبل الطفل.\",\"p\":\"يا رب، علّمني مخافتك ورجائي فيك. واجعلني مستعدًا للقائك. آمين.\",\"x\":\"يقول الأب إيليا: أخاف ثلاثة: عندما توشك نفسي أن تفارق جسدي، وعندما أنتصب أمام الله، وعندما يصدر الحكم بحقي. الانتظار الحقيقي يقظ. تدريب: اختم الليلة بفحص ضمير.\",\"fq\":127}]},\"12-25\":{\"th\":\"إلى هنا أعاننا الرب\",\"m\":[{\"t\":\"لأنك احتضنتني\",\"ref\":\"المزمور ٢٩ (٣٠) — الثالثة\",\"v\":\"أعظمك يا رب لأنك احتضنتني، ولم تشمت بي أعدائي.\",\"r\":\"أعظمك يا رب لأنك احتضنتني ولم تشمت بي أعدائي. اليوم احتضن الله البشرية في طفل. لم يبق بينه وبيننا بعد. كل عام وأنت بخير، وهذا هو العيد الحقيقي: أن تحتضنك يد الله. احتضن اليوم من أهملته.\",\"p\":\"يا رب، أعظمك لأنك احتضنتني بتجسدك. وأعطني أن أحتضن غيري بمحبتك. آمين.\",\"x\":\"أعظمك يا رب لأنك احتضنتني. اليوم احتضن الله البشرية في طفل. تدريب: احتضن اليوم أحدًا برفق ككلمة طيبة.\"},{\"t\":\"حجر المعونة\",\"ref\":\"صموئيل الأول ٧: ١٢\",\"bk\":\"صموئيل الأول\",\"v\":\"فأخذ صموئيل حجرا ونصبه بين المصفاة والسن، ودعا اسمه «حجر المعونة» وقال: «إلى هنا أعاننا الرب».\",\"r\":\"«فأخذ صموئيل حجرًا ونصبه... ودعا اسمه حجر المعونة وقال: إلى هنا أعاننا الرب». في أواخر السنة أقيم في قلبي حجر معونة. أتذكر المرات التي حملني فيها الله، ولو لم أنتبه إليها وقتها. من يتذكر المعونة السابقة يثق في المعونة القادمة.\",\"p\":\"يا رب، إلى هنا أعنتني. أشكرك على كل معونة عرفتها وكل معونة لم أنتبه لها. ثبّت إيماني بك للأيام القادمة، واحفظني من الجحود. آمين.\",\"x\":\"جاءت هذه الآية بعد انتصار على الأعداء لم يكن بقوة الشعب، بل بتدخل الله. فنصب صموئيل حجرًا ليكون تذكارًا. وعادة التذكار مهمة في الكتاب المقدس، لأن النسيان يقود إلى الجحود. وعبارة «إلى هنا» تحمل شكرًا عما مضى وتفتح بابًا لما سيأتي. وتعلمنا الكنيسة أن نختم الصلوات بشكر، ففي صلاة الشكر أول كل أجبية نقول: «فلنشكر صانع الخيرات». فالشكر يؤسس رجاء متجددًا.\\nاليوم، اكتب خمس مرات أعانك فيها الله هذا العام، واجعلها قائمة شكر.\"},{\"t\":\"لما كنت في الإسقيط\",\"ref\":\"\",\"v\":\"\",\"r\":\"قال الأب يوحنا الخصي للأب ثيوذورس الفرمي لما زاره: لما كنت في الإسقيط كانت أمور النفس شغلنا الأول وعمل اليد ثانيًا، أما الآن فقد صارت أمور النفس ثانوية وعمل اليد هو الأساس. في العيد، لا تجعل مشاغل العيد تسبق أمور نفسك. رتب اليوم ما هو أول.\",\"p\":\"يا رب، رتّب أولوياتي. واجعل شؤون نفسي أولًا ولو في زحمة العيد. آمين.\",\"x\":\"قال الأب يوحنا الخصي للأب ثيوذورس الفرمي: لما كنت في الأسقيط كانت أمور النفس شغلنا الأول وعمل اليد ثانيًا، أما الآن فقد صارت أمور النفس ثانوية. حذار أن يتغير ترتيب الأولويات. تدريب: راجع أولوياتك اليوم.\",\"fq\":135}]},\"12-26\":{\"th\":\"العطية التي لا يعبر عنها\",\"m\":[{\"t\":\"للرب الخلاص\",\"ref\":\"المزمور الثالث — باكر\",\"v\":\"للرب الخلاص وعلى شعبه بركته.\",\"r\":\"للرب الخلاص وعلى شعبه بركته. الخلاص عطية لا ثمن لها: هو الله نفسه بيننا. لا نقتنيه بجهدنا. تلقَّ اليوم هذه العطية بفم مفتوح، وقل شكرًا لمن لا يطلب مقابلًا.\",\"p\":\"يا رب، لك الخلاص وعلى شعبك بركتك. أشكرك على عطيتك التي لا يعبر عنها. آمين.\",\"x\":\"للرب الخلاص وعلى شعبه بركته. الخلاص عطية لا ثمن لها، هو الله نفسه بيننا. تدريب: تلقَّ العطية اليوم بصمت وشكر.\"},{\"t\":\"عطية لا يعبر عنها\",\"ref\":\"كورنثوس الثانية ٩: ١٥\",\"bk\":\"كورنثوس الثانية\",\"v\":\"فشكرا لله على عطيته التي لا يعبر عنها.\",\"r\":\"«فشكرًا لله على عطيته التي لا يعبر عنها». ليس بوسعي أن أصف قيمة هذه العطية، لكني أقدر أن أشكر. الله أعطاني نفسه في ابنه. وفي ذكرى الميلاد أتعلم أن أفتح يدي لأتقبل بامتنان، ثم أعطي بدوري بسخاء.\",\"p\":\"أشكرك يا أبانا السماوي على عطيتك التي لا يعبر عنها. ابنك الوحيد صار لي مخلصًا ومعينًا. اجعلني معطيًا بسخاء كما أعطيتني. آمين.\",\"x\":\"جاءت هذه الآية في ختام كلام بولس عن العطاء والجمع للكنائس الفقيرة، فربط بين عطاء الناس وعطية الله الأعظم. ويرى الآباء أن العطية هي المسيح نفسه، فهو هبة الآب للبشرية. والكلمة «لا يعبر عنها» تعني أنها فوق قدرة اللغة. وهكذا يتحول الشكر إلى تسبيح. ومن عرف حجم العطية الإلهية سهل عليه العطاء للآخرين، لأنه لا يعطي من ماله فقط، بل من نعمة نالها.\\nاليوم، قدّم عطية لشخص محتاج، وقل في قلبك: «هذه من عطية الله».\"},{\"t\":\"كن عديم الهم\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب سيسوى: ازدر بنفسك واجعل مشيئتك وراءك وكن عديم الهمّ، فتجد راحة. الراحة التي يعطيها الله تأتي حين نتخلى عن مشيئتنا. سلّم اليوم همًّا واحدًا ولا تأخذه معك.\",\"p\":\"يا رب، علّمني أن أضع مشيئتي وراءي. وارفع عني الهموم لتعطيني راحتك. آمين.\",\"x\":\"يقول الأب سيسوى: ازدر بنفسك واجعل مشيئتك وراءك وكن عديم الهمّ فتجد راحة. الراحة تأتي بالتخلي. تدريب: اترك اليوم رغبة عنادك.\",\"fq\":506}]},\"12-27\":{\"th\":\"عمق الغنى الإلهي\",\"m\":[{\"t\":\"عظمت رحمتك\",\"ref\":\"المزمور ٥٦ (٥٧) — السادسة\",\"v\":\"لأن رحمتك قد عظمت إلى السموات. وإلى السحاب عدلك.\",\"r\":\"عظمت رحمتك إلى السموات، وعدلك إلى السحاب. من يقيس غنى حكمة الله؟ إن كنا نحيا في ضيق، فرحمته لا تقاس. أحصِ اليوم ثلاث رحمات صغيرة في يومك، وقل: لك المجد.\",\"p\":\"يا رب، عظمت رحمتك إلى السموات. أشكرك على غنى نعمتك. آمين.\",\"x\":\"عظمت رحمتك إلى السماوات وعدلك إلى السحاب. غنى الله لا يُقاس. تدريب: أحصِ اليوم عشر نعم، وارفع لله بكل واحدة شكرًا.\"},{\"t\":\"يا لعمق غنى الله\",\"ref\":\"رومية ١١: ٣٣\",\"bk\":\"رومية\",\"v\":\"يا لعمق غنى الله وحكمته وعلمه! ما أبعد أحكامه عن الفحص وطرقه عن الاستقصاء!\",\"r\":\"«يا لعمق غنى الله وحكمته وعلمه! ما أبعد أحكامه عن الفحص وطرقه عن الاستقصاء!». كثيرًا ما أحاول فهم كل شيء، والله أكبر من إدراكي. في هذا الاعتراف راحة: لا أحتاج أن أفهم كل التدبير لأثق في الله، فيكفيني أن أسجد وأسبح.\",\"p\":\"يا لعمق غناك وحكمتك وعلمك يا رب. أسجد لك أمام ما لا أفهمه، وأثق في تدبيرك الصالح. علّمني التسبيح عند حدود عقلي. آمين.\",\"x\":\"يختم بولس بهذه التسبحة الفصول التسعة إلى الحادي عشر من رسالة رومية، بعد أن شرح تدبير الله مع اليهود والأمم. فعندما بلغ حد العقل وقف مبهورًا بالتسبيح. وهذه علامة اللاهوت الأرثوذكسي: العقل يخدم الإيمان ولا يحكم عليه. فتأمل سر التجسد يقودنا إلى الصمت والعبادة، كما يقول الآباء. وسر الله الذي لا يُحاط به لا يعني أنه بعيد، بل أنه أعظم من أن نحصره. وهو مع ذلك قريب بمحبته.\\nاليوم، اترك سؤالًا محيرًا في يد الله، وقل: «يا لعمق غنى الله»، ثم سبحه.\"},{\"t\":\"كالغنى والفقر\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب مكاريوس المصري: لن تموت إذا صار عندك الهزء كالمديح والفقر كالغنى والحرمان كالقنية. من يؤمن جيدًا ويسلك بتقوى لا يسقط في خديعة الشياطين. اطلب اليوم سلامًا لا يتغير مع ما عندك أو ما ينقصك.\",\"p\":\"يا رب، أعطني قلبًا متحررًا من الغنى والفقر. وليكن كنزي فيك. آمين.\",\"x\":\"يقول الأب مكاريوس المصري: لن تموت إذا صار عندك الهزء كالمديح والفقر كالغنى والحرمان كالقنية، لأنه يستحيل على من يؤمن جيدًا ويسلك بتقوى أن يسقط في نتانة الأهواء وخديعة الشياطين. تدريب: تعامل اليوم مع المديح والإهانة بالمثل.\",\"fq\":240}]},\"12-28\":{\"th\":\"الإله الأزلي\",\"m\":[{\"t\":\"كرسيك ثابت منذ الأزل\",\"ref\":\"المزمور ٩٢ (٩٣) — السادسة\",\"v\":\"كرسيك ثابت منذ البدء، وأنت هو منذ الأزل.\",\"r\":\"كرسيك ثابت منذ البدء، وأنت هو منذ الأزل. في عالم متغير يمنحنا الله ثباتًا. كل ما نتعلق به يزول، وهو وحده يبقى. ضع قرارك اليوم على ما يثبت: وصية أو عادة صلاة.\",\"p\":\"يا رب، أنت هو منذ الأزل. ثبّتني على كرسيك ولا أتزعزع. آمين.\",\"x\":\"كرسيك ثابت منذ البدء وأنت هو منذ الأزل. في عالم متغير يمنحنا الله ثباتًا. تدريب: عند أول قلق اليوم ردد: أنت ثابت.\"},{\"t\":\"ملجأ في دور فدور\",\"ref\":\"المزامير ٩٠: ١–٢\",\"bk\":\"المزامير\",\"v\":\"يا رب، ملجأ كنت لنا في دور فدور. من قبل أن تولد الجبال، أو أبدأت الأرض والمسكونة، منذ الأزل إلى الأبد أنت الله.\",\"r\":\"«يا رب، ملجأ كنت لنا في دور فدور». الأجيال تمضي والله ثابت. حين أشعر بعدم الاستقرار أتذكر أن بيتي الحقيقي ليس مكانًا بل شخصًا. أنهي السنة في ملجأ لا يتغير، وأسلم له ما مضى وما سيأتي.\",\"p\":\"يا رب، أنت ملجأ لنا في دور فدور. من قبل الجبال أنت الله. ثبتني في ملجأك الأمين، واحفظ أيامي في يدك. آمين.\",\"x\":\"هذا المزمور من صلوات موسى، وهو يقابل بين قصر حياة الإنسان وأبدية الله. وفي مواجهة تقلب الزمن، يجد الإنسان ملجأ في الله الذي لا يتغير. والأزلية صفة إلهية تميزه عن كل المخلوقات. وفي نهاية السنة تذكرنا الكنيسة بأن الزمن ملك لله. وهذا يعطي معنى للأيام التي نقضيها، فهي ليست مجرد دورة تقويم بل فرصة للتوبة والنمو. ومن أسس حياته على الأزلي لا تهزه تغيرات الأيام.\\nاليوم، خصص دقائق للهدوء، وقل: «أنت ملجأي يا رب»، وسلم له همًّا يخص العام القادم.\"},{\"t\":\"الفضائل خالدة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب إيسيذورس: أكرم الفضائل ولا تهتم باللذات، لأن الفضائل خالدة، أما الملذات فتزول بسهولة. ما نعمله لله يبقى، وما نركض خلفه من متع يذهب. اختر اليوم فضيلة تبقى وتخلد معك.\",\"p\":\"يا رب، أعطني أن أكرم الفضائل. واجعلني أستثمر في ما يبقى للأبد. آمين.\",\"x\":\"يقول الأب إيسيذورس: أكرم الفضائل ولا تهتم باللذات، لأن الفضائل خالدة أما الملذات فتزول بسهولة. تدريب: اختر فضيلة تدوم بدل لذة تزول.\",\"fq\":173}]},\"12-29\":{\"th\":\"الحفظ والشهادة\",\"m\":[{\"t\":\"عيناه على الصديقين\",\"ref\":\"المزمور ٣٣ (٣٤) — الثالثة\",\"v\":\"فإن عيني الرب على الصديقين، وأذنيه مصغيتان إلى طلبتهم.\",\"r\":\"عيني الرب على الصديقين وأذناه مصغيتان إلى طلبتهم. الله الذي يرى لا يغفل عنا. ننهي العام تحت نظره الأبوي وحفظه. تذكر اليوم موقفًا ظننت فيه أنك وحدك، وشاهد الله حاضرًا فيه.\",\"p\":\"يا رب، عيناك عليّ وأذناك مصغيتان إليّ. احفظني اليوم وفي كل أيام عمري. آمين.\",\"x\":\"عينا الرب على الصديقين وأذناه مصغيتان إلى طلبتهم. ننهي العام تحت نظره الأبوي. تدريب: أخبره الليلة بطلبة واحدة للعام الجديد.\"},{\"t\":\"يحفظ خروجك ودخولك\",\"ref\":\"المزامير ١٢١: ٧–٨\",\"bk\":\"المزامير\",\"v\":\"الرب يحفظك من كل شر. يحفظ نفسك. الرب يحفظ خروجك ودخولك من الآن وإلى الدهر.\",\"r\":\"«الرب يحفظ خروجك ودخولك من الآن وإلى الدهر». أخرج إلى عملي وأعود وأنا في حفظه، وأدخل السنة الجديدة وأخرج منها وهو معي. لا أعرف ما ينتظرني، لكني أعرف من يحفظني. هذا يكفي ليهدأ قلبي.\",\"p\":\"يا رب، أنت حارسي لا تنعس ولا تنام. احفظ خروجي ودخولي، وأسرتي وأحبائي، واحفظنا من كل شر في العام القادم. آمين.\",\"x\":\"المزمور 121 من مزامير المصاعد التي كان الحجاج يرتلونها وهم يصعدون إلى أورشليم. وهي تتحدث عن حفظ الله الدائم الذي لا ينعس ولا ينام. والخروج والدخول تعبير عن كل تحركات الإنسان اليومية. وتكرار كلمة «يحفظ» ثلاث مرات يؤكد الاهتمام الإلهي. وبهذا يصير المؤمن واثقًا في طريقه. وتستخدم الكنيسة مثل هذه الآيات في صلواتها، وتطلب حفظ الله لشعبها في كل مكان.\\nاليوم، قبل أن تغادر بيتك قل: «الرب يحفظ خروجي ودخولي»، وارسم علامة الصليب على نفسك.\"},{\"t\":\"عمل الله أولًا\",\"ref\":\"\",\"v\":\"\",\"r\":\"سألوا الأب يوحنا الخصي: كيف استطعتم أن تعملوا إرادة الله براحة، بينما نحن بالجهد نفعل ذلك؟ فأجاب: اهتمامنا الأساسي هو عمل الله، وللحاجة الجسدية نعير انتباهًا قليلًا، أما أنتم فتعطون الحاجة الجسدية الاهتمام الأول فتتعبون. قدّم الله اليوم في قائمة أولوياتك.\",\"p\":\"يا رب، اجعل عملك أول اهتمامي. وأرحني من تعب الأولويات الخاطئة. آمين.\",\"x\":\"سألوا الأب يوحنا الخصي كيف استطعتم أن تعملوا إرادة الله براحة بينما نحن بالجهد؟ فأجاب: اهتمامنا الأساسي هو عمل الله، وللحاجة الجسدية نعير انتباهًا قليلًا، أما أنتم فتعطون الجسد الاهتمام الأول. تدريب: اجعل عمل الله أولًا اليوم.\",\"fq\":192}]},\"12-30\":{\"th\":\"كل شيء جديدًا\",\"m\":[{\"t\":\"رفعت نفسي إليك\",\"ref\":\"المزمور ٢٤ (٢٥) — باكر\",\"v\":\"إليك يا رب رفعت نفسي.\",\"r\":\"إليك يا رب رفعت نفسي. والرب يقول: هأنذا أصنع كل شيء جديدًا. ننظر إلى العام القادم بقلب مرفوع إلى الله. ما الذي تريد أن يجدده الله فيك؟ ارفعه إليه اليوم بصلاة صريحة.\",\"p\":\"يا رب، إليك أرفع نفسي. اصنع في حياتي كل شيء جديدًا. آمين.\",\"x\":\"إليك يا رب رفعت نفسي، والرب يقول: هأنذا أصنع كل شيء جديدًا. ننظر إلى العام القادم بقلب مرفوع. تدريب: اكتب أمرًا واحدًا تطلب أن يجدده الله فيك.\"},{\"t\":\"بخار يظهر قليلًا\",\"ref\":\"يعقوب ٤: ١٤–١٥\",\"bk\":\"يعقوب\",\"v\":\"أنتم الذين لا تعرفون أمر الغد! لأنه ما هي حياتكم؟ إنها بخار، يظهر قليلا ثم يضمحل. عوض أن تقولوا: «إن شاء الرب وعشنا نفعل هذا أو ذاك».\",\"r\":\"«ما هي حياتكم؟ إنها بخار يظهر قليلًا ثم يضمحل». في آخر العام أشعر بسرعة مرور الأيام. لا أقول هذا لأخاف، بل لأستيقظ. أضع خططي لسنة جديدة بتواضع، وأقول من القلب: «إن شاء الرب وعشنا»، فكل ما عندي هبة منه.\",\"p\":\"يا رب، علمني أن أحسب أيامي بحكمة. أسلم لك خططي للعام القادم، وليكن ما تشاء. اجعل عمري كله لمجدك. آمين.\",\"x\":\"يخاطب يعقوب من يخططون للتجارة والربح كأنهم يملكون الغد. فيذكرهم بقصر الحياة، لا ليحبطهم بل ليعلمهم الاتكال على الله. والجملة «إن شاء الرب» ليست عبارة تقليدية بل هي موقف قلب يسلم الخطط لله. ولا يمنع هذا التخطيط الجاد، فنحن نعمل ونخطط ونصلي. وتعلّمنا الكنيسة أن نعد أيامنا كما قال المرنم لنؤتى قلب حكمة. ومن يقدر قيمة الوقت يستثمره في ما هو أبدي.\\nاليوم، اكتب هدفين روحيين للعام الجديد، وضع إلى جانبهما «إن شاء الرب»، وسلمهما له في صلاة.\"},{\"t\":\"السماء الجديدة\",\"ref\":\"\",\"v\":\"\",\"r\":\"يقول الأب بيمن: إذا استطاع الإنسان أن يبني سماء جديدة وأرضًا جديدة، لا يمكنه أن يكون بدون همّ. حتى أعظم الإنجازات لا تعطي راحة كاملة، فالراحة الحقيقية في الله. كلما انشغلت بالتخطيط للعام الجديد، سلّم همّه لمن يصنع كل شيء جديدًا.\",\"p\":\"يا رب، علّمني أن أطلب راحتي فيك. واصنع فيّ سماءً جديدة وأرضًا جديدة. آمين.\",\"x\":\"يقول الأب بيمن: إذا استطاع الإنسان أن يبني سماء جديدة وأرضًا جديدة لا يمكنه أن يكون بدون همّ. حتى أعظم الإنجازات لا تعفينا من الجهاد. تدريب: لا تتكل على إنجاز العام، وابدأ الجديد بتواضع.\",\"fq\":346}]},\"12-31\":{\"th\":\"ختام السنة وشكر\",\"m\":[{\"t\":\"اشكروا الرب\",\"ref\":\"المزمور ١١٧ (١١٨) — الغروب\",\"v\":\"اشكروا الرب فإنه صالح وأن إلى الأبد رحمته هلليلويا\",\"r\":\"اشكروا الرب فإنه صالح وأن إلى الأبد رحمته. في آخر يوم من السنة نتوقف لنشكر. تذكر هذا العام: صعوباته وأفراحه. كتب الله في كل منها اسمه. اقض اليوم دقائق في الشكر على ما مضى بلا مقارنة ولا ندم.\",\"p\":\"يا رب، أشكرك على كل يوم من هذا العام. فإنك صالح وإلى الأبد رحمتك. آمين.\",\"x\":\"اشكروا الرب فإنه صالح وإلى الأبد رحمته. في آخر يوم من السنة نتوقف لنشكر. تدريب: تذكر صعوبات هذا العام وأفراحه واشكر على الاثنين.\"},{\"t\":\"القادر أن يحفظكم\",\"ref\":\"يهوذا ١: ٢٤–٢٥\",\"bk\":\"يهوذا\",\"v\":\"والقادر أن يحفظكم غير عاثرين، ويوقفكم أمام مجده بلا عيب في الابتهاج، الإله الحكيم الوحيد مخلصنا، له المجد والعظمة والقدرة والسلطان، الآن وإلى كل الدهور. آمين.\",\"r\":\"«والقادر أن يحفظكم غير عاثرين، ويوقفكم أمام مجده بلا عيب في الابتهاج». أختم السنة بتسبحة الثقة هذه. لست قادرًا على حفظ نفسي، لكن القادر يحفظني. أسلم له الأيام القادمة، وأعبده بقلب شاكر، وأضع المجد كله له الآن وإلى كل الدهور.\",\"p\":\"للقادر أن يحفظنا غير عاثرين، الإله الحكيم الوحيد مخلصنا، له المجد والعظمة والقدرة والسلطان، الآن وإلى كل الدهور. احفظنا في السنة الجديدة بنعمتك. آمين.\",\"x\":\"تنتهي رسالة يهوذا، بعد تحذيرات شديدة من الانحراف، بتسبحة رجاء. فالله لا يترك أولاده بل يحفظهم من العثرة ويقدمهم أمام مجده في فرح. وتصور الآية النهاية السعيدة: الوقوف أمام المجد بلا عيب لا بسبب كمالنا بل بسبب غفرانه. ويُنسب المجد والعظمة والقدرة والسلطان إلى الله، فهو وحده مخلصنا. وتستخدم الكنيسة هذه الخاتمة في العبادة لتنهي الصلوات بشكر وتمجيد.\\nاليوم، في ختام السنة صلِّ الآية 24 و25 بصوت عال، وسلم السنة الجديدة للقادر أن يحفظك.\"},{\"t\":\"الرب معهم\",\"ref\":\"\",\"v\":\"\",\"r\":\"سأل الأب نيسثروس الأب أنطونيوس: ما هو العمل الصالح حتى أعمله؟ فأجاب: أليست كل الأعمال متساوية؟ إبراهيم كان مضيفًا والرب معه، وإيليا أحب السكينة والرب معه، وداود كان متواضعًا والرب معه. ما تريده نفسك وفقًا لمشيئة الله اعمله. في العام الجديد، اختر ما يرضي الله واثبت فيه.\",\"p\":\"يا رب، كن معي في كل عمل. وأعطني أن أنهي هذا العام وأبدأ العام الجديد بمشيئتك. آمين.\",\"x\":\"سأل الأب نيسثروس الأب أنطونيوس ما هو العمل الصالح؟ فأجاب: أليست كل الأعمال متساوية؟ إبراهيم كان مضيفًا والرب معه، وإيليا أحب السكينة والرب معه، وداود كان متواضعًا والرب معه. اعمل ما تجد نفسك مدعوًا إليه واحفظ قلبك. تدريب: اعمل ما يضعه الله أمامك بقلب مع الله.\",\"fq\":298}]}}}";
